// Hyperrealist Potting-Bench Corner in Overcast English Light
// Rendered with p5.js v2 + p5.brush in WEBGL

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom dry-brush for gritty terracotta, rust, and velvety moss
  brush.add("dryclay", {
    type: "default",
    weight: 3.5,
    scatter: 1.35,
    sharpness: 0.25,
    grain: 22,
    opacity: 65,
    spacing: 0.35,
    pressure: [0.4, 1.2, 0.3],
    rotate: "natural",
    noise: 0.9
  });

  // Fine botanical bristle for moss shoots and fine scratches
  brush.add("bristle", {
    type: "default",
    weight: 1.2,
    scatter: 0.4,
    sharpness: 0.75,
    grain: 14,
    opacity: 130,
    spacing: 0.2,
    pressure: [0.8, 1.0, 0.1],
    rotate: "natural",
    noise: 0.5
  });

  // Crisp highlight tip for slick snail mucus and wet specular glints
  brush.add("wetglint", {
    type: "custom",
    weight: 1.6,
    scatter: 0.05,
    opacity: 190,
    spacing: 0.18,
    pressure: [0.2, 1.3, 0.2],
    tip: (_m) => {
      _m.rotate(30);
      _m.ellipse(0, 0, 2.2, 0.9);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.2
  });

  // Custom gentle vector field for wood grain and organic curves
  brush.addField("woodgrain", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let n = noise(col * 0.08, row * 0.15);
        field[col][row] = -3 + (n - 0.5) * 10;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm damp watercolor paper ground
  background("#f2ede2");

  // 1. Out-of-focus Watercolor Garden Background (Foxgloves, Lupins, Hollyhocks)
  drawHumidGardenBackground();

  // 2. Weathered Wooden Potting Bench & Background Props
  drawPottingBench();
  drawBackgroundTwineAndLabels();

  // 3. Tipped-over Small Seedling Pot on Left Bench
  drawTippedSeedlingPot(235, 930);

  // 4. Hero Leaning Stack of Damp Terracotta Pots with Moss
  drawLeaningPotStack();

  // 5. Rusted Garden Trowel on the Right Bench
  drawRustedTrowel();

  // 6. Fallen Foxglove Blossom & Foreground Soil Crumb Details
  drawFallenFoxgloveAndDebris();

  // 7. Slick Snail Trail & Hero Snail Mid-Crawl on the Upper Rim
  drawSnailTrailAndSnail();

  // 8. Final Atmospheric Dappled Light & Fine Grain Cohesion
  drawDappledLightOverlay();

  noLoop();
}

// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function wetBlob(cx, cy, rx, ry, rotDeg, ptsCount, wobble, curvature = 0.6) {
  brush.beginShape(curvature);
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  for (let i = 0; i < ptsCount; i++) {
    let a = (i / ptsCount) * 360;
    let n = noise(cx * 0.01 + cos(a) * 1.2, cy * 0.01 + sin(a) * 1.2);
    let rMod = 1 + (n - 0.5) * wobble;
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    let gx = cx + lx * cr - ly * sr;
    let gy = cy + lx * sr + ly * cr;
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

function polyShape(pts, curvature = 0.35, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function getTiltedEllipsePt(cx, cy, rx, ry, tiltDeg, aDeg) {
  let lx = cos(aDeg) * rx;
  let ly = sin(aDeg) * ry;
  let ct = cos(tiltDeg);
  let st = sin(tiltDeg);
  return [cx + lx * ct - ly * st, cy + lx * st + ly * ct];
}

// ============================================================================
// 1. OUT-OF-FOCUS WATERCOLOR GARDEN BACKGROUND
// ============================================================================

function drawHumidGardenBackground() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // --- Pass A: Broad atmospheric overcast sky & foliage washes (Color Batched) ---
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.55, 0.18);

  // Misty overcast sky & dappled pale celadon light at top
  let skyPatches = [
    [180, 90, 220, 130, -8],
    [520, 70, 260, 120, 5],
    [920, 85, 250, 140, -6],
    [350, 180, 180, 110, 12],
    [760, 160, 190, 120, -10]
  ];
  brush.fill("#e4ece6", 75);
  for (let p of skyPatches) wetBlob(p[0], p[1], p[2], p[3], p[4], 12, 0.35);

  // Soft pastel sage & misty eucalyptus background foliage
  let sagePatches = [
    [120, 320, 180, 240, 10],
    [290, 480, 210, 260, -12],
    [640, 460, 230, 250, 8],
    [980, 420, 220, 280, -6],
    [1100, 620, 180, 200, 15],
    [80, 640, 170, 190, -10],
    [460, 220, 190, 170, 4]
  ];
  brush.fill("#b8cbb9", 80);
  for (let p of sagePatches) wetBlob(p[0], p[1], p[2], p[3], p[4], 12, 0.4);

  // Deeper humid olive-sage & slate-green foliage shadows
  let deepFoliage = [
    [60, 480, 140, 210, 5],
    [340, 630, 190, 160, -8],
    [740, 600, 210, 180, 12],
    [1060, 520, 160, 220, -14],
    [840, 290, 150, 190, 6],
    [220, 250, 130, 170, -5]
  ];
  brush.fill("#7f9984", 75);
  for (let p of deepFoliage) wetBlob(p[0], p[1], p[2], p[3], p[4], 12, 0.42);

  let darkFoliage = [
    [150, 680, 150, 120, 0],
    [390, 700, 160, 110, -5],
    [780, 690, 180, 120, 6],
    [1040, 700, 160, 110, -4],
    [620, 560, 130, 140, 10]
  ];
  brush.fill("#566e5d", 70);
  for (let p of darkFoliage) wetBlob(p[0], p[1], p[2], p[3], p[4], 11, 0.38);

  // --- Pass B: Lupin Spires (Left & Center-Left, x: 70..410) ---
  // Tall tapering columns of soft lilac, wisteria, and pastel lavender-rose
  let lupinSpires = [
    { x: 115, yTop: 110, yBot: 490, w: 52, tilt: 4, tone: "lilac" },
    { x: 195, yTop: 65, yBot: 460, w: 62, tilt: -3, tone: "lavender" },
    { x: 275, yTop: 145, yBot: 520, w: 55, tilt: 5, tone: "roseLilac" },
    { x: 355, yTop: 95, yBot: 430, w: 48, tilt: -2, tone: "lilac" }
  ];

  // Batch 1: Soft outer lilac halo on all lupins
  brush.fillBleed(0.42, "out");
  brush.fill("#d8c6e4", 82);
  for (let sp of lupinSpires) {
    let steps = 9;
    for (let i = 0; i < steps; i++) {
      let t = i / (steps - 1);
      let y = lerp(sp.yTop, sp.yBot, t);
      let x = sp.x + (t - 0.5) * sp.tilt * 8 + sin(t * 180) * 4;
      let rx = lerp(16, sp.w, pow(t, 0.75));
      let ry = lerp(14, 28, t);
      wetBlob(x, y, rx, ry, random(-12, 12), 10, 0.3);
    }
  }

  // Batch 2: Richer wisteria / amethyst-violet lower bells on lupins
  brush.fillBleed(0.32, "out");
  brush.fill("#a88cc4", 78);
  for (let sp of lupinSpires) {
    for (let i = 2; i < 9; i++) {
      let t = i / 8;
      let y = lerp(sp.yTop, sp.yBot, t);
      let x = sp.x + (t - 0.5) * sp.tilt * 8;
      let rx = lerp(12, sp.w * 0.78, t);
      wetBlob(x - rx * 0.25, y + 4, rx * 0.65, 16, -15, 9, 0.28);
      wetBlob(x + rx * 0.28, y + 6, rx * 0.6, 15, 15, 9, 0.28);
    }
  }

  // Batch 3: Creamy pastel-pink upper standards (pea-flower tops) on lupins
  brush.fillBleed(0.25, "out");
  brush.fill("#f0dce6", 90);
  for (let sp of lupinSpires) {
    for (let i = 0; i < 6; i++) {
      let t = i / 7;
      let y = lerp(sp.yTop, sp.yBot, t);
      let x = sp.x + (t - 0.5) * sp.tilt * 8;
      let rx = lerp(11, sp.w * 0.55, t);
      wetBlob(x, y - 4, rx, 12, 0, 8, 0.25);
    }
  }

  // --- Pass C: Foxglove Spires (Center & Upper-Right, x: 430..830) ---
  // Arching stems with pendulous tubular bells in rose madder, dusty magenta, and spotted throats
  let foxgloveStems = [
    { xBase: 460, yBase: 520, xTip: 435, yTip: 55, curve: -25, scale: 1.05 },
    { xBase: 615, yBase: 560, xTip: 575, yTip: 35, curve: -32, scale: 1.15 },
    { xBase: 735, yBase: 590, xTip: 710, yTip: 85, curve: -20, scale: 0.95 },
    { xBase: 835, yBase: 620, xTip: 855, yTip: 140, curve: 18, scale: 0.9 }
  ];

  // Collect bell positions for color batching
  let fgBells = [];
  for (let st of foxgloveStems) {
    let count = 11;
    for (let i = 0; i < count; i++) {
      let t = i / (count - 1); // 0 = top buds, 1 = lowest open bells
      let bx = lerp(st.xTip, st.xBase, t) + sin(t * 180) * st.curve;
      let by = lerp(st.yTip, st.yBase, t);
      let side = (i % 2 === 0 ? -1 : 1) * (0.6 + 0.4 * random());
      if (t > 0.25) {
        fgBells.push({
          x: bx + side * 26 * st.scale * (0.4 + 0.6 * t),
          y: by + 10,
          w: lerp(14, 36, t) * st.scale,
          h: lerp(18, 46, t) * st.scale,
          ang: side * 28 + random(-8, 8),
          isBud: false
        });
        // Secondary overlapping bell
        if (t > 0.45 && i % 2 === 0) {
          fgBells.push({
            x: bx - side * 18 * st.scale,
            y: by + 22,
            w: lerp(14, 32, t) * st.scale,
            h: lerp(18, 42, t) * st.scale,
            ang: -side * 22 + random(-6, 6),
            isBud: false
          });
        }
      } else {
        fgBells.push({
          x: bx + side * 10,
          y: by,
          w: 12 * st.scale,
          h: 16 * st.scale,
          ang: side * 15,
          isBud: true
        });
      }
    }
  }

  // Outer soft rose-madder bloom of foxgloves
  brush.fillBleed(0.38, "out");
  brush.fill("#df9eae", 85);
  for (let b of fgBells) {
    wetBlob(b.x, b.y, b.w * 0.72, b.h * 0.78, b.ang, 10, 0.28);
  }

  // Deeper rose-madder & crimson-pink upper hood of each bell
  brush.fillBleed(0.28, "out");
  brush.fill("#bc5c75", 82);
  for (let b of fgBells) {
    if (!b.isBud) {
      wetBlob(b.x, b.y - b.h * 0.15, b.w * 0.55, b.h * 0.55, b.ang, 9, 0.25);
    }
  }

  // Pale creamy-blush open lower lip / throat of foxglove bells
  brush.fillBleed(0.2, "out");
  brush.fill("#f5e2e4", 95);
  for (let b of fgBells) {
    if (!b.isBud) {
      let rad = b.ang + 90;
      let mx = b.x + cos(rad) * b.h * 0.32;
      let my = b.y + sin(rad) * b.h * 0.32;
      wetBlob(mx, my, b.w * 0.48, b.h * 0.26, b.ang, 8, 0.2);
    }
  }

  // --- Pass D: Hollyhocks (Right side & Mid-Right, x: 860..1150) ---
  // Large saucer-shaped ruffled blossoms in pastel blush, peach-rose, and deep madder wine throats
  let hollyhocks = [
    { x: 935, y: 155, r: 54 },
    { x: 1020, y: 235, r: 66 },
    { x: 910, y: 315, r: 72 },
    { x: 1045, y: 390, r: 76 },
    { x: 930, y: 485, r: 80 },
    { x: 1070, y: 555, r: 74 },
    { x: 865, y: 615, r: 68 }
  ];

  // Outer ruffled petals in soft pastel blush-rose and warm apricot-pink
  brush.fillBleed(0.4, "out");
  brush.fill("#edc4cc", 88);
  for (let h of hollyhocks) {
    wetBlob(h.x, h.y, h.r, h.r * 0.92, random(0, 180), 14, 0.35);
  }

  brush.fillBleed(0.32, "out");
  brush.fill("#dfa1b0", 78);
  for (let h of hollyhocks) {
    wetBlob(h.x - 6, h.y + 5, h.r * 0.76, h.r * 0.72, random(0, 180), 12, 0.3);
  }

  // Deep madder-wine center throats of the hollyhocks
  brush.fillBleed(0.25, "out");
  brush.fill("#9c3d58", 85);
  for (let h of hollyhocks) {
    wetBlob(h.x + 2, h.y + 2, h.r * 0.34, h.r * 0.32, 0, 10, 0.25);
  }

  // --- Pass E: Soft out-of-focus stems, foxglove throat speckles & bokeh details ---
  // Soft watery stems connecting the blooms
  brush.noFill();
  brush.set("marker", "#6e8772", 3.2);
  for (let st of foxgloveStems) {
    brush.spline([
      [st.xBase, st.yBase, 1.2],
      [lerp(st.xBase, st.xTip, 0.5) + st.curve, lerp(st.yBase, st.yTip, 0.5), 0.9],
      [st.xTip, st.yTip, 0.4]
    ], 0.5);
  }
  brush.set("marker", "#7a917c", 2.6);
  for (let sp of lupinSpires) {
    brush.line(sp.x, sp.yBot, sp.x - sp.tilt * 6, 750);
  }
  brush.line(980, 140, 965, 760);

  // Cream stamen central boss in each hollyhock
  brush.set("marker", "#f5e6c8", 3.0);
  for (let h of hollyhocks) {
    brush.circle(h.x + 2, h.y + 2, h.r * 0.1, 0.3);
  }

  // Signature Foxglove speckled throats (blurred maroon spots inside open bell mouths)
  brush.set("marker", "#7d2943", 1.1);
  for (let b of fgBells) {
    if (!b.isBud && b.w > 24) {
      let rad = b.ang + 90;
      let mx = b.x + cos(rad) * b.h * 0.28;
      let my = b.y + sin(rad) * b.h * 0.28;
      for (let s = 0; s < 5; s++) {
        let sx = mx + random(-b.w * 0.25, b.w * 0.25);
        let sy = my + random(-b.h * 0.1, b.h * 0.12);
        brush.line(sx, sy, sx + 1.5, sy + 1.5);
      }
    }
  }

  // Soft spray diffusion to melt the background into a humid pastel dream
  brush.set("spray", "#f0e4e8", 8);
  for (let i = 0; i < 28; i++) {
    let x = random(60, 1140);
    let y = random(60, 680);
    brush.line(x, y, x + random(-60, 60), y + random(-40, 40));
  }
  brush.set("spray", "#c8d6c6", 7);
  for (let i = 0; i < 22; i++) {
    let x = random(60, 1140);
    let y = random(350, 740);
    brush.line(x, y, x + random(-70, 70), y + random(-30, 30));
  }
}

// ============================================================================
// 2. WEATHERED POTTING BENCH & BACKGROUND PROPS
// ============================================================================

function drawPottingBench() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base watercolor washes for weathered grey-taupe cedar planks
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.65, 0.3);

  // Rear plank (y: 745 to 885)
  brush.fill("#c4bbb0", 165);
  polyShape([[0, 745], [1200, 770], [1200, 895], [0, 870]], 0.05);

  // Middle plank (y: 870 to 1045)
  brush.fill("#b5aba0", 175);
  polyShape([[0, 872], [1200, 897], [1200, 1055], [0, 1030]], 0.05);

  // Front plank (y: 1030 to 1200)
  brush.fill("#a3988c", 185);
  polyShape([[0, 1032], [1200, 1057], [1200, 1200], [0, 1200]], 0.05);

  // Damp water-stain & humic shadow washes under the pots and trowel
  brush.fillBleed(0.4, "out");
  brush.fill("#73685c", 120);
  wetBlob(460, 955, 290, 75, 2, 14, 0.35);
  wetBlob(235, 945, 140, 50, -4, 12, 0.35);
  wetBlob(820, 955, 240, 65, -8, 14, 0.35);

  // Deeper damp soil shadow right beneath Pot 1 and Trowel blade
  brush.fill("#4d4339", 145);
  wetBlob(475, 960, 185, 46, 1, 12, 0.25);
  wetBlob(715, 975, 130, 36, -12, 12, 0.3);

  // Greenish algae / damp moss stain on the back edge of the bench
  brush.fill("#7b8c6e", 95);
  wetBlob(160, 795, 150, 38, 2, 11, 0.4);
  wetBlob(680, 805, 170, 42, 1, 11, 0.4);
  wetBlob(1060, 820, 140, 40, 2, 11, 0.4);

  brush.noFill();

  // Wood grain texture using custom vector field + colored pencil & drybrush
  brush.field("woodgrain");
  let grainColors = ["#8c8175", "#6e6459", "#d6cec2", "#595046", "#9e9386"];
  for (let cIdx = 0; cIdx < grainColors.length; cIdx++) {
    brush.set("cpencil", grainColors[cIdx], 0.9);
    for (let i = 0; i < 65; i++) {
      let gx = random(0, 1150);
      let gy = random(755, 1190);
      brush.flowLine(gx, gy, random(60, 180), 1);
    }
  }
  brush.noField();

  // Plank gaps (dark damp crevices with tiny moss tufts)
  let seams = [
    [[0, 745], [600, 758], [1200, 770]],
    [[0, 871], [600, 884], [1200, 896]],
    [[0, 1031], [600, 1044], [1200, 1056]]
  ];
  for (let s of seams) {
    brush.set("charcoal", "#383028", 1.8);
    brush.spline(s, 0.2);
    brush.set("2B", "#1f1a15", 1.1);
    brush.spline(s, 0.2);
    // Light upper lip of lower plank catching overcast sky
    brush.set("cpencil", "#dfd8cc", 1.0);
    brush.line(s[0][0], s[0][1] + 3, s[2][0], s[2][1] + 3);
  }

  // Wood knots on the planks
  let knots = [[145, 955, 28, 10], [890, 985, 34, 12], [540, 1115, 38, 13]];
  for (let k of knots) {
    brush.set("2B", "#4f453b", 1.0);
    for (let r = 0.3; r <= 1.0; r += 0.25) {
      brush.BeginShape;
      let pts = [];
      for (let a = 0; a < 360; a += 30) {
        pts.push([k[0] + cos(a) * k[2] * r, k[1] + sin(a) * k[3] * r]);
      }
      polyShape(pts, 0.5, true);
    }
  }
}

function drawBackgroundTwineAndLabels() {
  // Right-rear corner prop: a moss-dusted spool of jute garden twine & wooden plant labels
  // Sitting softly on the back of the bench at (980, 795)
  let tx = 985, ty = 785;

  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.3);

  // Jute twine spool cylinder
  brush.fill("#b89f82", 190);
  polyShape([
    [tx - 48, ty - 42], [tx + 48, ty - 42],
    [tx + 52, ty + 38], [tx - 52, ty + 38]
  ], 0.3);

  brush.fill("#8f785d", 170);
  polyShape([
    [tx + 5, ty - 42], [tx + 48, ty - 42],
    [tx + 52, ty + 38], [tx + 5, ty + 38]
  ], 0.25);

  // Wooden plant labels sticking up behind/beside the twine
  brush.fill("#dfd3c0", 210);
  polyShape([[tx - 28, ty - 38], [tx - 42, ty - 135], [tx - 26, ty - 148], [tx - 12, ty - 132], [tx - 2, ty - 38]], 0.15);
  brush.fill("#cfc0aa", 205);
  polyShape([[tx + 10, ty - 40], [tx + 28, ty - 125], [tx + 44, ty - 132], [tx + 50, ty - 115], [tx + 32, ty - 38]], 0.15);

  brush.noFill();

  // Wrapped jute cord ridges on the spool
  for (let y = ty - 36; y <= ty + 34; y += 5.5) {
    let col = y % 11 < 5.5 ? "#786248" : "#cbb69b";
    brush.set("cpencil", col, 1.1);
    brush.arc(tx, y - 8, 50, 15, 165);
  }
  // Top hole of twine spool
  brush.set("2B", "#4a3c2c", 1.4);
  brush.circle(tx, ty - 40, 16, 0.2);

  // Faint graphite handwriting on the wooden plant label ("Digitalis 'Sutton's Apricot'")
  brush.set("2H", "#635c54", 0.7);
  for (let i = 0; i < 6; i++) {
    let ly = ty - 120 + i * 11;
    let lx = tx - 30 + i * 1.8;
    brush.wiggle(2);
    brush.line(lx, ly, lx + 14, ly + 2);
    brush.noField();
  }

  // Trailing loose twine string curling across the bench
  brush.set("cpencil", "#9e8669", 1.3);
  brush.spline([
    [tx - 45, ty + 32, 1.0],
    [tx - 95, ty + 55, 0.9],
    [tx - 135, ty + 48, 0.8],
    [tx - 165, ty + 68, 0.7]
  ], 0.6);
}

// ============================================================================
// 3. TIPPED-OVER SMALL SEEDLING POT (Bottom Left)
// ============================================================================

function drawTippedSeedlingPot(cx, cy) {
  // Small terracotta thumb-pot lying on its side, showing its circular base and drainage hole
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.65, 0.35);

  // Body cone tapering to the left
  brush.fill("#bd684b", 220);
  polyShape([
    [cx - 58, cy - 46],
    [cx + 55, cy - 68],
    [cx + 68, cy + 48],
    [cx - 48, cy + 52]
  ], 0.2);

  // Darker damp underside of the tipped pot
  brush.fill("#7d3b26", 190);
  polyShape([
    [cx - 52, cy + 5],
    [cx + 62, cy - 2],
    [cx + 68, cy + 48],
    [cx - 48, cy + 52]
  ], 0.2);

  // Thick rolled rim on the right side
  brush.fill("#cf7c5f", 225);
  polyShape([
    [cx + 46, cy - 74],
    [cx + 72, cy - 76],
    [cx + 85, cy + 54],
    [cx + 58, cy + 55]
  ], 0.25);

  // Circular flat base on the left facing the viewer at an angle
  let bx = cx - 53, by = cy + 3;
  brush.fill("#9c4f37", 230);
  wetBlob(bx, by, 26, 48, -8, 14, 0.12);

  // Dark drainage hole in center of base
  brush.fill("#2b1810", 245);
  wetBlob(bx, by + 2, 9, 17, -8, 10, 0.1);

  brush.noFill();

  // Dry-brush chalky mineral deposit & clay ridges
  brush.set("dryclay", "#e3cbb8", 0.9);
  brush.line(cx - 45, cy - 32, cx + 52, cy - 52);
  brush.line(cx - 38, cy - 18, cx + 56, cy - 34);

  brush.set("cpencil", "#5e2818", 1.1);
  // Rim contour lines
  brush.spline([
    [cx + 46, cy - 74, 0.8],
    [cx + 64, cy - 10, 1.1],
    [cx + 58, cy + 55, 0.8]
  ], 0.4);
  brush.spline([
    [cx + 72, cy - 76, 0.8],
    [cx + 88, cy - 10, 1.1],
    [cx + 85, cy + 54, 0.8]
  ], 0.4);

  // Drainage hole inner rim thickness (pale fired clay edge)
  brush.set("cpencil", "#d99b80", 1.3);
  brush.arc(bx + 2, by + 2, 12, -70, 110);

  // Cushion moss patch growing on the damp lower flank of the tipped pot
  drawMossPatch(cx + 10, cy + 32, 38, 18, 4);
}

