function drawSingleTerracottaPot(cfg) {
  let {
    xBot, yBot, rxBot, ryBot,
    xColBot, yColBot, rxColBot, ryColBot,
    xRim, yRim, rxRim, ryRim,
    tilt, showInterior
  } = cfg;

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // --- 1. Build Lower Body Polygon (Front visible half of truncated cone) ---
  let bodyPts = [];
  // Top edge (along collar bottom from left 180 deg to right 0 deg via front 90 deg)
  for (let a = 180; a >= 0; a -= 15) {
    bodyPts.push(getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.95, ryColBot * 0.95, tilt, a));
  }
  // Bottom edge (from right 0 deg to left 180 deg via front 90 deg)
  for (let a = 0; a <= 180; a += 15) {
    bodyPts.push(getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a));
  }

  // Base terracotta watercolor fill
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.7, 0.35);
  brush.fill("#c87253", 230);
  polyShape(bodyPts, 0.15, true);

  // Right-side cylindrical form shadow & damp lower moisture gradient
  let bodyShadowPts = [];
  for (let a = 105; a >= 0; a -= 15) {
    bodyShadowPts.push(getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.95, ryColBot * 0.95, tilt, a));
  }
  for (let a = 0; a <= 135; a += 15) {
    bodyShadowPts.push(getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a));
  }
  brush.fillBleed(0.32, "in");
  brush.fill("#8f432b", 175);
  polyShape(bodyShadowPts, 0.2, true);

  // Deep damp wicking zone near the bottom of the pot
  let dampPts = [];
  for (let a = 170; a >= 10; a -= 20) {
    let pTop = getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.95, ryColBot * 0.95, tilt, a);
    let pBot = getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a);
    dampPts.push([lerp(pBot[0], pTop[0], 0.38), lerp(pBot[1], pTop[1], 0.38)]);
  }
  for (let a = 10; a <= 170; a += 20) {
    dampPts.push(getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a));
  }
  brush.fill("#662b19", 165);
  polyShape(dampPts, 0.25, true);

  // Left-center soft overcast highlight plane on body
  let hiPts = [];
  for (let a = 155; a >= 105; a -= 15) {
    hiPts.push(getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.92, ryColBot * 0.92, tilt, a));
  }
  for (let a = 105; a <= 155; a += 15) {
    let pTop = getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.92, ryColBot * 0.92, tilt, a);
    let pBot = getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a);
    hiPts.push([lerp(pBot[0], pTop[0], 0.25), lerp(pBot[1], pTop[1], 0.25)]);
  }
  brush.fill("#df987c", 140);
  polyShape(hiPts, 0.25, true);

  // --- 2. Build Thick Rolled Collar / Rim Band ---
  let collarPts = [];
  for (let a = 180; a >= 0; a -= 12) {
    collarPts.push(getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, a));
  }
  for (let a = 0; a <= 180; a += 12) {
    collarPts.push(getTiltedEllipsePt(xColBot, yColBot, rxColBot, ryColBot, tilt, a));
  }

  brush.fillBleed(0.16, "in");
  brush.fill("#d47e5e", 235);
  polyShape(collarPts, 0.15, true);

  // Right-side shading on collar
  let colShadPts = [];
  for (let a = 95; a >= 0; a -= 15) {
    colShadPts.push(getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, a));
  }
  for (let a = 0; a <= 115; a += 15) {
    colShadPts.push(getTiltedEllipsePt(xColBot, yColBot, rxColBot, ryColBot, tilt, a));
  }
  brush.fillBleed(0.28, "in");
  brush.fill("#94462e", 175);
  polyShape(colShadPts, 0.2, true);

  // --- 3. If Top Pot, Draw Hollow Elliptical Interior & Rim Lip Thickness ---
  if (showInterior) {
    // Outer top lip surface
    let outerLip = [];
    for (let a = 0; a < 360; a += 15) {
      outerLip.push(getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, a));
    }
    brush.fillBleed(0.12, "in");
    brush.fill("#e39d80", 235);
    polyShape(outerLip, 0.35, true);

    // Inner hollow cavity
    let innerLip = [];
    let rxIn = rxRim * 0.84;
    let ryIn = ryRim * 0.78;
    for (let a = 0; a < 360; a += 15) {
      innerLip.push(getTiltedEllipsePt(xRim, yRim + 3, rxIn, ryIn, tilt, a));
    }
    brush.fillBleed(0.2, "in");
    brush.fill("#6e3320", 240);
    polyShape(innerLip, 0.35, true);

    // Deep shadow on left-inner wall, warmer reflected clay on right-inner wall
    let deepInner = [];
    for (let a = 90; a <= 290; a += 20) {
      deepInner.push(getTiltedEllipsePt(xRim, yRim + 3, rxIn, ryIn, tilt, a));
    }
    for (let a = 290; a >= 90; a -= 20) {
      deepInner.push(getTiltedEllipsePt(xRim + 15, yRim + 22, rxIn * 0.65, ryIn * 0.55, tilt, a));
    }
    brush.fill("#3d1a0f", 210);
    polyShape(deepInner, 0.3, true);
  }

  brush.noFill();

  // --- 4. Dry-Brush Chalky Salt Efflorescence & Gritty Clay Texture ---
  // White/cream mineral blooms characteristic of aged damp terracotta
  for (let i = 0; i < 26; i++) {
    let a = random(20, 165);
    let t = random(0.08, 0.92);
    let pTop = getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.95, ryColBot * 0.95, tilt, a);
    let pBot = getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a);
    let px = lerp(pTop[0], pBot[0], t);
    let py = lerp(pTop[1], pBot[1], t);

    let col = a > 95 ? "#ebd9c8" : "#cfa892";
    brush.set("dryclay", col, random(0.6, 1.3));
    let span = random(18, 48);
    brush.line(px - span * 0.5, py - 3, px + span * 0.5, py + 4);
  }

  // Chalky efflorescence on the thick collar
  for (let i = 0; i < 18; i++) {
    let a = random(25, 165);
    let t = random(0.15, 0.85);
    let pTop = getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, a);
    let pBot = getTiltedEllipsePt(xColBot, yColBot, rxColBot, ryColBot, tilt, a);
    let px = lerp(pTop[0], pBot[0], t);
    let py = lerp(pTop[1], pBot[1], t);
    brush.set("dryclay", a > 90 ? "#f2e3d5" : "#d49c82", random(0.7, 1.2));
    brush.line(px - 16, py - 2, px + 16, py + 3);
  }

  // --- 5. Colored Pencil & Graphite Cross-Contour Potter's Wheel Ridges ---
  // Elliptical wheel-thrown striations wrapping around the cylinder
  let ridgeLevels = [0.12, 0.24, 0.38, 0.52, 0.68, 0.82, 0.93];
  for (let lv of ridgeLevels) {
    let cx = lerp(xColBot, xBot, lv);
    let cy = lerp(yColBot, yBot, lv);
    let rx = lerp(rxColBot * 0.95, rxBot, lv);
    let ry = lerp(ryColBot * 0.95, ryBot, lv);

    // Draw broken elliptical arcs in dark terracotta and pale chalky pencil
    for (let seg = 0; seg < 5; seg++) {
      let aStart = random(12, 145);
      let aEnd = aStart + random(18, 35);
      let arcPts = [];
      for (let a = aStart; a <= aEnd; a += 6) {
        arcPts.push(getTiltedEllipsePt(cx, cy, rx, ry, tilt, a));
      }
      let strokeCol = aStart > 95 ? "#a6543a" : "#5e2716";
      brush.set("cpencil", strokeCol, random(0.7, 1.15));
      brush.spline(arcPts, 0.4);
    }
  }

  // Longitudinal shading strokes along the cylinder wall
  for (let a = 10; a <= 170; a += 4.5) {
    let pTop = getTiltedEllipsePt(xColBot, yColBot, rxColBot * 0.94, ryColBot * 0.94, tilt, a);
    let pBot = getTiltedEllipsePt(xBot, yBot, rxBot, ryBot, tilt, a);
    let col = a < 75 ? "#4f2012" : (a < 115 ? "#9c4c33" : "#e6b89c");
    if (random() < 0.75) {
      let t1 = random(0.0, 0.5);
      let t2 = random(t1 + 0.2, 1.0);
      brush.set("cpencil", col, random(0.65, 1.05));
      brush.line(
        lerp(pTop[0], pBot[0], t1), lerp(pTop[1], pBot[1], t1),
        lerp(pTop[0], pBot[0], t2), lerp(pTop[1], pBot[1], t2)
      );
    }
  }

  // --- 6. Crisp Shadow Under the Overhanging Collar Lip ---
  let underCollarPts = [];
  for (let a = 175; a >= 5; a -= 10) {
    underCollarPts.push(getTiltedEllipsePt(xColBot, yColBot + 3, rxColBot * 0.97, ryColBot * 0.97, tilt, a));
  }
  brush.set("charcoal", "#3d180d", 1.7);
  brush.spline(underCollarPts, 0.4);
  brush.set("2B", "#260e07", 1.0);
  brush.spline(underCollarPts, 0.4);

  // Highlight along the upper front rim of the collar
  let rimHiPts = [];
  for (let a = 165; a >= 65; a -= 10) {
    rimHiPts.push(getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, a));
  }
  brush.set("cpencil", "#f5dfd0", 1.25);
  brush.spline(rimHiPts, 0.4);

  // If top pot, draw inner rim edge and weathered chip on the lip
  if (showInterior) {
    let innerEdgePts = [];
    for (let a = 0; a <= 360; a += 15) {
      innerEdgePts.push(getTiltedEllipsePt(xRim, yRim + 3, rxRim * 0.84, ryRim * 0.78, tilt, a));
    }
    brush.set("cpencil", "#4a1f12", 1.1);
    brush.spline(innerEdgePts, 0.4);

    // A hyperrealist weathered V-chip on the front-left rim of the top pot
    let chipPt = getTiltedEllipsePt(xRim, yRim, rxRim, ryRim, tilt, 122);
    brush.noStroke();
    brush.fillBleed(0.05, "in");
    brush.fill("#632919", 230);
    polyShape([
      [chipPt[0] - 14, chipPt[1] - 4],
      [chipPt[0] + 12, chipPt[1] - 2],
      [chipPt[0] + 3, chipPt[1] + 16],
      [chipPt[0] - 8, chipPt[1] + 12]
    ], 0.15);
    brush.noFill();
    brush.set("cpencil", "#f0c9b2", 1.0);
    brush.line(chipPt[0] - 14, chipPt[1] - 4, chipPt[0] - 8, chipPt[1] + 12);

    // Hairline age crack descending from the chip
    brush.set("2H", "#38150b", 0.85);
    brush.spline([
      [chipPt[0] - 2, chipPt[1] + 15, 1.0],
      [chipPt[0] - 6, chipPt[1] + 42, 0.8],
      [chipPt[0] - 1, chipPt[1] + 68, 0.4]
    ], 0.3);
    brush.set("cpencil", "#e8bfa8", 0.65);
    brush.line(chipPt[0] - 1, chipPt[1] + 16, chipPt[0] - 5, chipPt[1] + 42);
  }

  // Fine mineral grit speckles across the clay
  brush.set("spray", "#4f2113", 3.5);
  for (let i = 0; i < 8; i++) {
    let p = getTiltedEllipsePt(
      lerp(xColBot, xBot, 0.5),
      lerp(yColBot, yBot, 0.5),
      rxBot * 0.7, ryBot * 0.7, tilt, random(20, 160)
    );
    brush.line(p[0], p[1], p[0] + 25, p[1] + 8);
  }
}

// ============================================================================
// HYPERREALIST VELVETY MOSS CUSHIONS & SPOROPHYTES
// ============================================================================

function drawMossPatch(cx, cy, rx, ry, puffCount, withSporophytes = false) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Dark humic damp ring where moss clings to the porous clay
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.4);
  brush.fill("#2b3620", 195);
  wetBlob(cx, cy + 4, rx * 1.08, ry * 0.95, random(-8, 8), 12, 0.35);

  // 2. Deep olive-forest cushion base
  brush.fillBleed(0.22, "out");
  brush.fill("#465e32", 215);
  for (let i = 0; i < puffCount; i++) {
    let ox = cx + map(i, 0, puffCount - 1, -rx * 0.72, rx * 0.72) + random(-6, 6);
    let oy = cy + sin(i * 55) * ry * 0.28 + random(-4, 4);
    let pr = ry * random(0.65, 1.05);
    wetBlob(ox, oy, pr * 1.2, pr * 0.9, random(-15, 15), 10, 0.3);
  }

  // 3. Mid-tone velvety sage & moss-green mounds
  brush.fillBleed(0.18, "out");
  brush.fill("#6d8c49", 210);
  for (let i = 0; i < puffCount; i++) {
    let ox = cx + map(i, 0, puffCount - 1, -rx * 0.65, rx * 0.65) + random(-5, 5);
    let oy = cy - ry * 0.15 + random(-4, 4);
    let pr = ry * random(0.5, 0.85);
    wetBlob(ox, oy, pr * 1.1, pr * 0.8, random(-10, 10), 9, 0.3);
  }

  brush.noFill();

  // 4. Dry-brush & colored pencil velvety gametophyte tufts (chartreuse, celadon, golden-moss)
  let mossTones = ["#28361c", "#4b6632", "#75964b", "#9cb865", "#bfd483", "#dce8a7"];
  for (let tIdx = 0; tIdx < mossTones.length; tIdx++) {
    let col = mossTones[tIdx];
    let count = tIdx < 4 ? 26 : 16;
    for (let i = 0; i < count; i++) {
      let a = random(0, 360);
      let d = sqrt(random()) * 0.95;
      let mx = cx + cos(a) * rx * d;
      // Bias brighter highlights toward the upper half of each moss pillow
      let my = cy + sin(a) * ry * d - (tIdx >= 4 ? ry * 0.22 : 0);

      brush.set(tIdx % 2 === 0 ? "bristle" : "cpencil", col, random(0.7, 1.25));
      let shootLen = random(5, 11);
      let shootAng = random(-125, -55);
      brush.line(
        mx, my,
        mx + cos(shootAng) * shootLen,
        my + sin(shootAng) * shootLen
      );
    }
  }

  // 5. Delicate hair-thin sporophyte stalks with nodding amber spore capsules
  if (withSporophytes) {
    let sporeCount = floor(random(4, 8));
    for (let s = 0; s < sporeCount; s++) {
      let sx = cx + random(-rx * 0.65, rx * 0.65);
      let sy = cy - random(ry * 0.2, ry * 0.7);
      let h = random(18, 34);
      let bend = random(-10, 12);
      let tx = sx + bend;
      let ty = sy - h;

      // Hair-thin reddish-amber seta (stalk)
      brush.set("2H", "#8c5332", 0.75);
      brush.spline([
        [sx, sy, 0.9],
        [sx + bend * 0.4, sy - h * 0.55, 0.7],
        [tx, ty, 0.5]
      ], 0.4);

      // Tiny nodding amber/lime capsule at tip
      brush.set("cpencil", "#d9a65b", 1.35);
      brush.line(tx, ty, tx + (bend >= 0 ? 4 : -4), ty + 3.5);
      brush.set("wetglint", "#f5eccd", 0.7);
      brush.line(tx, ty, tx + 1.5, ty + 1);
    }
  }
}

