function drawRustedTrowel() {
  // Trowel geometry:
  // Scooped blade tip at (615, 995), blade top shoulder at (778, 888), blade bottom shoulder at (805, 968)
  // Cranked tang neck from (792, 926) to ferrule at (865, 875)
  // Turned ash wood handle from (865, 875) to butt end at (1075, 810)

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // --- 1. Cast Shadow on the Bench Under Blade & Handle ---
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.5, 0.2);
  brush.fill("#3d342b", 165);
  polyShape([
    [612, 1005], [790, 945], [875, 905], [1075, 845],
    [1082, 868], [860, 935], [795, 988], [625, 1018]
  ], 0.35);

  // --- 2. Trowel Blade Base Washes (Steel + Oxidized Rust) ---
  let bladeOutline = [
    [612, 992],   // Pointed digging tip
    [682, 918],   // Upper left curve
    [775, 888],   // Upper shoulder
    [796, 925],   // Neck junction
    [806, 966],   // Lower shoulder
    [712, 1002]   // Lower curve back to tip
  ];

  // Worn pewter/steel base
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.7, 0.4);
  brush.fill("#969ea3", 230);
  polyShape(bladeOutline, 0.3, true);

  // Concave interior shadow in the upper half of the scoop
  brush.fillBleed(0.22, "in");
  brush.fill("#5e6469", 180);
  polyShape([
    [625, 986], [688, 924], [774, 894], [792, 926], [705, 962]
  ], 0.3, true);

  // Heavy corroded rust patches (burnt orange, venetian red, raw sienna)
  brush.fillBleed(0.28, "in");
  brush.fill("#ad4c24", 195);
  wetBlob(735, 925, 52, 24, -18, 12, 0.4);
  wetBlob(745, 965, 48, 22, -15, 12, 0.4);
  wetBlob(675, 955, 36, 18, -22, 10, 0.4);

  brush.fill("#732c14", 185);
  wetBlob(762, 932, 38, 20, -15, 10, 0.35);
  wetBlob(715, 972, 32, 15, -18, 10, 0.35);

  // --- 3. Turned Ash-Wood Handle Base Washes ---
  let handleOutline = [
    [864, 862],   // Ferrule top
    [935, 832],   // Swell top
    [1058, 792],  // Dome top
    [1082, 812],  // Butt end tip
    [1068, 838],  // Dome bottom
    [948, 872],   // Swell bottom
    [872, 888]    // Ferrule bottom
  ];

  brush.fillBleed(0.15, "in");
  brush.fill("#cbb89e", 235);
  polyShape(handleOutline, 0.3, true);

  // Lower cylindrical shadow on the wooden handle
  brush.fillBleed(0.22, "in");
  brush.fill("#87735a", 185);
  polyShape([
    [868, 875], [970, 842], [1078, 812],
    [1068, 838], [948, 872], [872, 888]
  ], 0.25, true);

  // Tarnished brass ferrule ring
  brush.fillBleed(0.1, "in");
  brush.fill("#9c8b6e", 235);
  polyShape([
    [844, 870], [866, 861], [874, 888], [852, 896]
  ], 0.15, true);

  brush.noFill();

  // --- 4. Hyperrealist Rust Pitting, Scratched Steel & Cranked Neck ---
