  brush.spline([[490, 268, 1.1], [476, 274, 0.9], [468, 280, 0.7]], 0.4);
  brush.set("wetglint", "#f2eee6", 0.55);
  brush.line(463, 270, 465, 270);
  brush.line(468, 279, 470, 279);

  // --- C. The Helicoid Spiral Shell (Center at x: 560, y: 218, radius ~ 48) ---
  let sx = 560, sy = 216, sr = 47;

  brush.noStroke();
  // 1. Base watercolor dome of the shell (warm amber-ochre & chestnut)
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.6, 0.35);
  brush.fill("#c49668", 238);
  wetBlob(sx, sy, sr * 1.06, sr * 0.96, -12, 16, 0.12);

  // Lower-right rounded whorl shadow
  brush.fillBleed(0.22, "in");
  brush.fill("#6e472b", 195);
  wetBlob(sx + 10, sy + 12, sr * 0.85, sr * 0.75, -10, 14, 0.15);

  // Soft pastel lilac-sky reflection on the glossy upper dome of the shell
  brush.fillBleed(0.25, "in");
  brush.fill("#dfd8e8", 150);
  wetBlob(sx - 10, sy - 16, sr * 0.62, sr * 0.42, -18, 12, 0.15);

  brush.noFill();

  // 2. Logarithmic Spiral Whorls, Chestnut Bands & Transverse Growth Striae
  // Apex of the spiral is shifted slightly right-down at (sx + 14, sy + 6)
  let ax = sx + 14, ay = sy + 6;
  let maxTurns = 3.25; // 3.25 full turns = 1170 degrees

  // Draw spiral dark chestnut & cream bands along the whorls
  for (let deg = 0; deg < maxTurns * 360; deg += 4) {
    let frac = deg / (maxTurns * 360); // 0 at apex, 1 at outer body whorl
    let r = pow(frac, 1.35) * sr;
    let rInner = pow(max(0, frac - 0.26), 1.35) * sr;
    let ang = -deg + 145;

    let xOut = ax + cos(ang) * r * 1.06;
    let yOut = ay + sin(ang) * r * 0.94;
    let xIn = ax + cos(ang) * rInner * 1.06;
    let yIn = ay + sin(ang) * rInner * 0.94;

    // Transverse curved growth rib across the whorl
    let mx = lerp(xIn, xOut, 0.5) + cos(ang + 90) * (r - rInner) * 0.22;
    let my = lerp(yIn, yOut, 0.5) + sin(ang + 90) * (r - rInner) * 0.22;

    // Alternate chestnut, golden ochre, and cream mottling (Cornu aspersum pattern)
    let mottle = sin(deg * 2.2) + cos(deg * 0.7);
    let col = mottle > 0.4 ? "#4a2c18" : (mottle > -0.3 ? "#9e6d42" : "#ebd5b8");
    // Top-left quadrant gets cool overcast sky reflection
    if (sin(ang) < -0.25 && frac > 0.45 && mottle <= 0.4) {
      col = "#e8e2ee";
    }

    brush.set("cpencil", col, map(frac, 0, 1, 0.5, 1.15));
    brush.spline([[xIn, yIn, 0.7], [mx, my, 1.1], [xOut, yOut, 0.7]], 0.4);

    // Spiral dark banding along the middle of the whorl
    if (frac > 0.22) {
      let b1x = lerp(xIn, xOut, 0.38);
      let b1y = lerp(yIn, yOut, 0.38);
      let b2x = lerp(xIn, xOut, 0.72);
      let b2y = lerp(yIn, yOut, 0.72);
      brush.set("cpencil", "#3d2210", 0.95);
      brush.line(b1x, b1y, b1x + cos(ang - 90) * 3.5, b1y + sin(ang - 90) * 3.5);
      brush.set("cpencil", "#57331b", 0.85);
      brush.line(b2x, b2y, b2x + cos(ang - 90) * 3.5, b2y + sin(ang - 90) * 3.5);
    }
  }

  // 3. Deep Suture Line (the indented groove of the spiral)
  let suturePts = [];
  for (let deg = 0; deg <= maxTurns * 360; deg += 12) {
    let frac = deg / (maxTurns * 360);
    let r = pow(frac, 1.35) * sr;
    let ang = -deg + 145;
    suturePts.push([ax + cos(ang) * r * 1.06, ay + sin(ang) * r * 0.94, map(frac, 0, 1, 0.5, 1.2)]);
  }
  brush.set("2B", "#2b160a", 1.15);
  brush.spline(suturePts, 0.45);

  // Pale calcified highlight ridge just outside the suture groove
  let sutureHiPts = suturePts.map(p => [p[0] - 1.5, p[1] - 1.8, p[2] * 0.8]);
  brush.set("cpencil", "#f5e8d6", 0.85);
  brush.spline(sutureHiPts, 0.45);

  // 4. Shell Aperture Lip (thickened pale peristome collar where body emerges at left)
  brush.set("cpencil", "#f2e2ce", 1.6);
  brush.spline([
    [516, 245, 1.0],
    [510, 222, 1.3],
    [520, 196, 1.1],
    [538, 182, 0.7]
  ], 0.45);
  brush.set("2B", "#331c0e", 1.2);
  brush.spline([
    [519, 246, 1.1],
    [514, 224, 1.2],
    [524, 200, 0.9]
  ], 0.45);

  // 5. Glossy Wet Specular Highlights on the Rounded Shell Whorls
  brush.set("wetglint", "#ffffff", 1.35);
  brush.spline([
    [532, 192, 0.7],
    [552, 184, 1.3],
    [574, 188, 0.8]
  ], 0.5);
  brush.set("wetglint", "#f7f4fa", 1.1);
  brush.spline([
    [568, 200, 0.6],
    [580, 198, 1.1],
    [590, 204, 0.6]
  ], 0.5);
}

