    noise: 0.18
  });

  brush.add("glow_edge", {
    type: "default",
    weight: 0.8,
    scatter: 0.16,
    sharpness: 0.42,
    grain: 11,
    opacity: 85,
    spacing: 0.18,
    pressure: [0.4, 1.25, 0.4],
    noise: 0.35
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.voidBlack);

  // Build botanical topology
  buildVeinIslands();
  buildShellRibbons();

  // 1. Deep space void & base nebula washes
  drawCosmicUnderpainting();

  // 2. Deep interior cavities, magenta dust lanes & receding sub-surface folds
  drawCavitiesAndSubsurface();

  // 3. The central conical core (stem pith, cambium & petiole nodes)
  drawStemCore();

  // 4. All concentric crinkled leaf ribbons (mesophyll, cellular cross-walls & cut epidermis)
  drawAllLeafRibbons();

  // 5. Cut midrib vein islands (space-telescope teal parenchyma & vascular bundles)
  drawAllVeinIslands();

  // 6. Inner meristem heart (tightly convoluted baby leaf whorls above core apex)
  drawMeristemHeart();

  // 7. Gaseous nebula highlights & dense stippled starfield dissolving into the black void
  drawGaseousHighlightsAndStarfield();

  noLoop();
}

// =============================================================================
// COORDINATE TRANSFORMS & ANATOMICAL FIELD FUNCTIONS
// =============================================================================

// Convert local cabbage coords (lx, ly) to canvas coords (x, y)
// Note: ly < 0 is top crown, ly > 0 is bottom stem stalk
function toWorld(lx, ly) {
  let c = cos(TILT);
  let s = sin(TILT);
  let rx = lx * c - ly * s;
  let ry = lx * s + ly * c;
  // Subtle organic global warp
  let wx = (noise(rx * 0.0025 + 10, ry * 0.0025 + 10) - 0.5) * 18;
  let wy = (noise(rx * 0.0025 + 30, ry * 0.0025 + 30) - 0.5) * 18;
  return [CX + rx + wx, CY + ry + wy];
}

// Polar to local Cartesian where phi = 0 is TOP crown, +90 is RIGHT, -90 is LEFT, +-180 is BOTTOM core
function polarToLocal(r, phi) {
  let lx = r * sin(phi);
  let ly = -r * cos(phi);
  return [lx, ly];
}

function polarToWorld(r, phi) {
  let [lx, ly] = polarToLocal(r, phi);
  return toWorld(lx, ly);
}

// Half-width of the conical stem core at radial distance r along the bottom axis (phi near +-180)
function getCoreHalfWidth(yLocal) {
  if (yLocal < 22) return 0;
  if (yLocal > 488) return 68;
  let t = constrain((yLocal - 22) / (488 - 22), 0, 1);
  // Conical taper with subtle anatomical node swellings where petioles attach
  let baseW = 24 + 72 * pow(t, 0.65) - 18 * pow(t, 2.4);
  let nodes = 4.5 * sin(t * 180 * 4.5);
  return baseW + nodes;
}

// Angle limit phiMax(r) where a shell of radius r meets the right/left flank of the stem core
function getCoreAngleLimit(r) {
  if (r < 55) return 165;
  let w = getCoreHalfWidth(r * 0.96);
  let ratio = constrain((w + 6) / r, 0.08, 0.82);
  return 180 - asin(ratio);
}

// Overall head silhouette modulation
function getHeadEnvelope(phi) {
  // Slightly oblate head, gently indented near bottom stalk
  let oblate = 1.0 + 0.045 * sin(phi) * sin(phi) - 0.025 * cos(phi);
  let stalkIndent = phi > 140 || phi < -140 ? -0.04 * pow((abs(phi) - 140) / 40, 1.5) : 0;
  let rad = phi * (PI / 180);
  let organicLobe = (noise(cos(rad) * 1.4 + 5, sin(rad) * 1.4 + 5) - 0.5) * 0.09;
  return oblate + stalkIndent + organicLobe;
}

// Build 24 anatomically placed midrib cross-sections (vein islands)
function buildVeinIslands() {
  veinIslands = [];
  // Curated rings of vein islands (r, phi, spanPhi, thickR, skew)
  const specs = [
    // Inner ring (r: 135..205)
    { r: 142, phi: -68, span: 15, thick: 11.5, skew: -0.15 },
    { r: 156, phi: 58, span: 16, thick: 12.0, skew: 0.12 },
    { r: 175, phi: -128, span: 17, thick: 13.5, skew: -0.2 },
    { r: 184, phi: 122, span: 17, thick: 14.0, skew: 0.2 },
    { r: 192, phi: -8, span: 15, thick: 11.5, skew: 0.05 },

    // Mid-inner ring (r: 220..295)
    { r: 228, phi: -98, span: 19, thick: 15.5, skew: -0.15 },
    { r: 236, phi: 88, span: 19, thick: 16.0, skew: 0.18 },
    { r: 252, phi: -42, span: 17, thick: 14.5, skew: -0.1 },
    { r: 264, phi: 36, span: 18, thick: 15.0, skew: 0.1 },
    { r: 278, phi: -144, span: 20, thick: 17.5, skew: -0.25 },
    { r: 285, phi: 140, span: 20, thick: 18.0, skew: 0.25 },

    // Mid-outer ring (r: 315..385)
    { r: 318, phi: -72, span: 21, thick: 18.0, skew: -0.12 },
    { r: 328, phi: 70, span: 21, thick: 18.5, skew: 0.14 },
    { r: 342, phi: -12, span: 19, thick: 16.0, skew: -0.05 },
    { r: 356, phi: -118, span: 22, thick: 20.0, skew: -0.22 },
    { r: 365, phi: 114, span: 22, thick: 20.5, skew: 0.2 },
    { r: 378, phi: 26, span: 18, thick: 16.5, skew: 0.08 },

    // Outer ring (r: 400..458)
    { r: 405, phi: -48, span: 21, thick: 18.5, skew: -0.1 },
    { r: 412, phi: 52, span: 21, thick: 19.0, skew: 0.12 },
    { r: 424, phi: -92, span: 23, thick: 21.5, skew: -0.18 },
    { r: 432, phi: 92, span: 24, thick: 22.0, skew: 0.18 },
    { r: 442, phi: -148, span: 22, thick: 23.0, skew: -0.28 },
    { r: 446, phi: 146, span: 22, thick: 23.0, skew: 0.28 },
    { r: 448, phi: -4, span: 20, thick: 17.0, skew: 0.0 }
  ];

  for (let i = 0; i < specs.length; i++) {
    let s = specs[i];
    veinIslands.push({
      id: i,
      r: s.r + random(-4, 4),
      phi: s.phi + random(-2.5, 2.5),
      span: s.span,
      thick: s.thick,
      skew: s.skew
    });
  }
}

// Compute vein island wrapping displacement & local tautness for a foliation shell
function evalVeinField(rNom, phi) {
  let disp = 0;
  let tautness = 0;
  for (let i = 0; i < veinIslands.length; i++) {
    let v = veinIslands[i];
    let dPhi = phi - v.phi;
    let u = dPhi / v.span;
    if (abs(u) < 1.55) {
      // Skewed crescent profile
      let uSkew = u - v.skew * (1 - u * u * 0.4);
      let prof = pow(max(0, 1 - pow(uSkew / 1.22, 2)), 1.65);
      let dr = rNom - v.r;
      let dir = dr >= 0 ? 1 : -1;
      let radialScale = v.thick * 2.5 + 24;
      let decay = exp(-abs(dr) / radialScale);
      disp += dir * (v.thick * 1.18 + 3.5) * prof * decay;
      tautness += prof * exp(-abs(dr) / (v.thick * 1.8 + 14));
    }
  }
  return { disp, tautness: constrain(tautness, 0, 1) };
}

// Evaluate deformed radius and tangential shift for shell `sIdx` at nominal radius `rNom` and angle `phi`
function evalShellPoint(rNom, phi, sIdx) {
  let env = getHeadEnvelope(phi);
  let rBase = rNom * env;

  let vf = evalVeinField(rNom, phi);
  let rWrapped = rBase + vf.disp;

  // Coherent medium-scale wave shared across nearby shells
  let rad = phi * (PI / 180);
  let sharedWave =
    14 *
    (rNom / R_HEAD) *
    (noise(cos(rad) * 2.1 + 20, sin(rad) * 2.1 + 20, rNom * 0.006) - 0.5) *
    2.0;

  // Cavity-forming buckle between shells (stronger in slack valleys between veins)
  let slack = 1.0 - 0.72 * vf.tautness;
  let buckleFreq = 6 + floor(rNom / 70) * 2;
  let bucklePhase = sIdx * 127 + 45 * noise(phi * 0.025 + 10, sIdx * 0.15);
  let cavityBuckle = (3.5 + 5.5 * slack) * sin(phi * buckleFreq + bucklePhase);

  // High-frequency Savoy crinkles (serpentine omega-folds in slack regions)
  let crinkleFreq = 22 + floor(rNom / 32) * 3;
  let crinkleMod = pow( max(0, noise(phi * 0.04 + sIdx * 0.3, rNom * 0.015) - 0.18) / 0.82, 0.85 );
  let crinkleAmp = (2.2 + 6.8 * slack * crinkleMod) * constrain(rNom / 160, 0.45, 1.15);
  let crinklePhase = phi * crinkleFreq + sIdx * 83 + 30 * sin(phi * 3 + sIdx * 19);

  let dR_crinkle = crinkleAmp * sin(crinklePhase);
  // Tangential oscillation creates rounded bulbous crinkles instead of pointy zigzags
  let dPhi_crinkle = (crinkleAmp / max(90, rNom)) * 42 * cos(crinklePhase) * slack;

  let finalR = max(28, rWrapped + sharedWave + cavityBuckle + dR_crinkle);
  let finalPhi = phi + dPhi_crinkle;

  return {
    r: finalR,
    phi: finalPhi,
    tautness: vf.tautness,
    crinkle: sin(crinklePhase) * slack * crinkleMod,
    cavityVal: sin(phi * buckleFreq + bucklePhase)
  };
}

// Build all 30 concentric foliation shells as finite-thickness leaf ribbons
function buildShellRibbons() {
  shellRibbons = [];
  const numShells = 30;

  for (let s = 0; s < numShells; s++) {
    let tShell = s / (numShells - 1);
    // Non-linear radial spacing: tighter near heart, broader in mid/outer zones
    let rNom = 78 + (R_HEAD - 78) * pow(tShell, 0.92);
    let phiLimit = getCoreAngleLimit(rNom);

    // Divide each shell into 2 or 3 overlapping imbricated leaf arcs
    let arcs = [];
    if (s % 3 === 0) {
      // Left-origin sweeping leaf + Right-origin sweeping leaf overlapping across crown
      arcs.push({ start: -phiLimit, end: 28 + (s % 4) * 8, originSide: -1 });
      arcs.push({ start: -18 - (s % 5) * 6, end: phiLimit, originSide: 1 });
    } else if (s % 3 === 1) {
      // Right-dominant leaf wrapping way past top + Left flank leaf
      arcs.push({ start: -phiLimit, end: -32, originSide: -1 });
      arcs.push({ start: -48, end: phiLimit, originSide: 1 });
    } else {
      // Three imbricated leaves: left petiole, crown arch, right petiole
      arcs.push({ start: -phiLimit, end: -42, originSide: -1 });
      arcs.push({ start: -62, end: 64, originSide: 0 });
      arcs.push({ start: 44, end: phiLimit, originSide: 1 });
    }

    for (let a = 0; a < arcs.length; a++) {
      let arc = arcs[a];
      let stepDeg = rNom < 180 ? 1.1 : rNom < 320 ? 0.85 : 0.68;
      let ptsIn = [];
      let ptsOut = [];
      let ptsMid = [];
      let meta = [];

      let span = arc.end - arc.start;
      let steps = max(12, floor(span / stepDeg));

      for (let i = 0; i <= steps; i++) {
        let u = i / steps; // 0 to 1 along leaf arc
        let phi = arc.start + u * span;

        // Slight radial shingle spiral so overlapping leaves tuck naturally
        let shingleOffset =
          arc.originSide === -1
            ? (u - 0.5) * 5.5
            : arc.originSide === 1
            ? (0.5 - u) * 5.5
            : sin(u * 180) * 3.5;

        let ev = evalShellPoint(rNom + shingleOffset, phi, s * 3 + a);

        // Compute biological ribbon thickness along the leaf
        // Thickest near core petiole origin and at periodic secondary vein nodes
        let tipTaper = 1.0;
        if (arc.originSide === -1) {
          tipTaper = pow(constrain(u / 0.08, 0.25, 1), 0.5) * pow(constrain((1 - u) / 0.18, 0.15, 1), 0.7);
        } else if (arc.originSide === 1) {
          tipTaper = pow(constrain((1 - u) / 0.08, 0.25, 1), 0.5) * pow(constrain(u / 0.18, 0.15, 1), 0.7);
        } else {
          tipTaper = sin(u * 180) * 0.75 + 0.25;
        }

        // Petiole base thickening near core attachment
        let coreProximity = pow(constrain((abs(phi) - 115) / 55, 0, 1), 1.6);
        // Periodic minor vein swellings along lamina
        let minorVeinWave = pow(max(0, sin(phi * 11 + s * 47)), 6);
        let baseThick = (4.2 + 3.6 * tShell + 7.5 * coreProximity + 4.2 * minorVeinWave) * tipTaper;

        // Vascular teal factor: high near core attachment and at minor vein nodes
        let tealFactor = constrain(coreProximity * 1.15 + minorVeinWave * 0.75 + (rNom < 125 ? 0.3 : 0), 0, 1);

        let rIn = ev.r - baseThick * 0.5;
        let rOut = ev.r + baseThick * 0.5;

        let pIn = polarToWorld(rIn, ev.phi);
        let pOut = polarToWorld(rOut, ev.phi);
        let pMid = polarToWorld(ev.r, ev.phi);

        ptsIn.push(pIn);
        ptsOut.push(pOut);
        ptsMid.push(pMid);
        meta.push({
          u,
          phi: ev.phi,
          r: ev.r,
          thick: baseThick,
          tealFactor,
          crinkle: ev.crinkle,
          cavityVal: ev.cavityVal
        });
      }

      shellRibbons.push({
        shellIdx: s,
        tShell,
        rNom,
        ptsIn,
        ptsOut,
        ptsMid,
        meta
      });
    }
  }
}

// =============================================================================
// DRAWING STAGE 1: COSMIC UNDERPAINTING & DEEP SPACE VOID
// =============================================================================

function drawCosmicUnderpainting() {
  brush.noStroke();

  // Outer nebula halo clouds in the dark void around the cabbage
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.25);

  const haloClouds = [
    { col: PAL.cavityIndigo, op: 95, n: 10, rMin: 380, rMax: 545, size: 190 },
    { col: PAL.magDark, op: 85, n: 12, rMin: 260, rMax: 515, size: 165 },
    { col: PAL.tealShadow, op: 75, n: 8, rMin: 160, rMax: 470, size: 145 }
  ];

  for (let hc of haloClouds) {
    brush.fill(hc.col, hc.op);
    for (let i = 0; i < hc.n; i++) {
      let ang = i * (360 / hc.n) + random(-14, 14);
      let rad = random(hc.rMin, hc.rMax);
      let [wx, wy] = polarToWorld(rad, ang);
      drawIrregularBlob(wx, wy, hc.size * random(0.75, 1.25), 10);
    }
  }
  brush.noFill();

  // Solid fast wash for the interior dark cavity bed of the cabbage
  brush.wash(PAL.cavityDeep, 235);
  brush.beginShape(0.3);
  for (let deg = -180; deg < 180; deg += 6) {
    let r = (R_HEAD + 10) * getHeadEnvelope(deg);
    let [wx, wy] = polarToWorld(r, deg);
    brush.vertex(wx, wy);
  }
  brush.endShape(true);
  brush.noWash();

  // Gaseous spray clouds across the interior domains
  // Magenta cavity basins
  brush.set("nebula_gas", PAL.magMid, 2.2);
  for (let i = 0; i < 65; i++) {
    let phi = random(-165, 165);
    let r = random(85, R_HEAD - 15) * getHeadEnvelope(phi);
    let [x1, y1] = polarToWorld(r, phi);
    let [x2, y2] = polarToWorld(r + random(-25, 25), phi + random(-14, 14));
    safeLine(x1, y1, x2, y2);
  }

  // Warm amber glow in leaf zones
  brush.set("nebula_gas", PAL.ambDeep, 1.9);
  for (let i = 0; i < 55; i++) {
    let phi = random(-155, 155);
    let r = random(95, R_HEAD - 25) * getHeadEnvelope(phi);
    let [x1, y1] = polarToWorld(r, phi);
    let [x2, y2] = polarToWorld(r + random(-15, 15), phi + random(-18, 18));
    safeLine(x1, y1, x2, y2);
  }

  // Deep teal glow under major vein islands & core
  brush.set("nebula_gas", PAL.tealDeep, 2.1);
  for (let v of veinIslands) {
    let [x1, y1] = polarToWorld(v.r, v.phi - v.span * 0.6);
    let [x2, y2] = polarToWorld(v.r, v.phi + v.span * 0.6);
    safeLine(x1, y1, x2, y2);
  }
}

function drawIrregularBlob(cx, cy, rad, nPts) {
  brush.beginShape(0.45);
  for (let i = 0; i < nPts; i++) {
    let a = (i * 360) / nPts;
    let r = rad * (0.72 + 0.45 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a)));
    brush.vertex(cx + r * cos(a), cy + r * sin(a));
  }
  brush.endShape(true);
}

// =============================================================================
// DRAWING STAGE 2: DEEP CAVITIES, MAGENTA NEBULA RIMS & SUB-SURFACE FOLDS
// =============================================================================

function drawCavitiesAndSubsurface() {
  // Along each ribbon, wherever cavityVal indicates a wide pocket behind/under the leaf,
  // render a receding sub-surface fold and magenta ionization rim
  for (let idx = 0; idx < shellRibbons.length; idx++) {
    let rib = shellRibbons[idx];
    let n = rib.ptsIn.length;

    // 1. Magenta gaseous rim along the inner (concave/cavity) wall of the ribbon
    for (let i = 0; i < n - 6; i += 6) {
      let m = rib.meta[i];
      if (m.cavityVal > 0.1) {
        let p1 = rib.ptsIn[i];
        let p2 = rib.ptsIn[min(n - 1, i + 6)];
        // Shift slightly inward into the cavity
        let [c1x, c1y] = polarToWorld(m.r - m.thick * 0.9 - 5, m.phi);
        let m2 = rib.meta[min(n - 1, i + 6)];
        let [c2x, c2y] = polarToWorld(m2.r - m2.thick * 0.9 - 5, m2.phi);

        brush.set("fine_mist", m.cavityVal > 0.55 ? PAL.magBright : PAL.magMid, 1.15);
        safeLine(c1x, c1y, c2x, c2y);

        // Deep cavity dark shadow line right under the epidermis
        brush.set("2H", PAL.magDark, 0.75);
        safeLine(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // 2. Dimly lit sub-surface receding folds inside the dark cavities (gives 3D depth!)
    for (let i = 2; i < n - 8; i += 9) {
      let m = rib.meta[i];
      if (m.cavityVal > 0.25) {
        let subPts = [];
        for (let k = 0; k <= 6; k++) {
          let mk = rib.meta[min(n - 1, i + k)];
          let depthOffset = 4.5 + 4.0 * sin(k * 30);
          let [sx, sy] = polarToWorld(mk.r - mk.thick * 0.55 - depthOffset, mk.phi);
          subPts.push([sx, sy, 0.4 + 0.5 * sin(k * 30)]);
        }
        brush.set("rotring", idx % 2 === 0 ? PAL.magBright : PAL.ambShadow, 0.42);
        safeSpline(subPts, 0.45);

        // Subtle cross-hatch shading sinking into the cavity
        if (i % 18 === 2) {
          let pA = subPts[2];
          let pB = rib.ptsIn[min(n - 1, i + 2)];
          brush.set("2H", PAL.magMid, 0.35);
          safeLine(pA[0], pA[1], pB[0], pB[1]);
        }
      }
    }
  }
}

// =============================================================================
// DRAWING STAGE 3: THE CONICAL STEM CORE (PITH, CAMBIUM & PETIOLE NODES)
// =============================================================================

function drawStemCore() {
  // Collect left and right boundary points of the core from yLocal = 485 up to apex yLocal = 24
  let leftPts = [];
  let rightPts = [];
  let innerLeft = [];
  let innerRight = [];

  for (let y = 485; y >= 24; y -= 10) {
    let w = getCoreHalfWidth(y);
    leftPts.push(toWorld(-w, y));
    rightPts.push(toWorld(w, y));
    innerLeft.push(toWorld(-w * 0.68, y + 6));
    innerRight.push(toWorld(w * 0.68, y + 6));
  }

  // 1. Dark magenta-black shadow moat outside the core flanks
  brush.set("nebula_gas", PAL.magDark, 1.8);
  safeSpline(leftPts, 0.35);
  safeSpline(rightPts, 0.35);

  // 2. Outer vascular cortex fill (rich space-telescope teal)
  brush.noStroke();
  brush.wash(PAL.tealDeep, 210);
  brush.beginShape(0.25);
  for (let p of leftPts) brush.vertex(p[0], p[1]);
  // Rounded apex dome
  let apex = toWorld(0, 16);
  brush.vertex(apex[0], apex[1]);
  for (let i = rightPts.length - 1; i >= 0; i--) {
    brush.vertex(rightPts[i][0], rightPts[i][1]);
  }
  brush.endShape(true);

  // 3. Inner pith medulla wash (warm amber-gold grading to radiant cyan-cream heart)
  brush.wash(PAL.ambWarm, 155);
  brush.beginShape(0.3);
  for (let p of innerLeft) brush.vertex(p[0], p[1]);
  let innerApex = toWorld(0, 26);
  brush.vertex(innerApex[0], innerApex[1]);
  for (let i = innerRight.length - 1; i >= 0; i--) {
    brush.vertex(innerRight[i][0], innerRight[i][1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Watercolor glow at the upper meristem heart of the core
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.55, 0.25);
  brush.fill(PAL.tealBright, 120);
  let [hx, hy] = toWorld(0, 115);
  drawIrregularBlob(hx, hy, 52, 9);

  brush.fill(PAL.goldBright, 130);
  let [gx, gy] = toWorld(0, 72);
  drawIrregularBlob(gx, gy, 36, 8);
  brush.noFill();

  // 4. Fine gaseous mist inside the core pith
  brush.set("fine_mist", PAL.goldMid, 1.3);
  for (let y = 450; y >= 50; y -= 22) {
    let w = getCoreHalfWidth(y) * 0.5;
    let [x1, y1] = toWorld(-w, y);
    let [x2, y2] = toWorld(w, y);
    safeLine(x1, y1, x2, y2);
  }

  brush.set("fine_mist", PAL.tealGlow, 1.1);
  for (let y = 460; y >= 35; y -= 18) {
    let w = getCoreHalfWidth(y) * 0.82;
    let [lx1, ly1] = toWorld(-w, y);
    let [lx2, ly2] = toWorld(-w * 0.65, y - 14);
    safeLine(lx1, ly1, lx2, ly2);
    let [rx1, ry1] = toWorld(w, y);
    let [rx2, ry2] = toWorld(w * 0.65, y - 14);
    safeLine(rx1, ry1, rx2, ry2);
  }

  // 5. Microscopic transverse pith growth menisci (curved horizontal cellular strata)
  for (let y = 475; y >= 30; y -= 6.5) {
    let w = getCoreHalfWidth(y) * 0.78;
    let archPts = [];
    for (let k = -4; k <= 4; k++) {
      let u = k / 4;
      let px = u * w;
      let py = y - 14 * (1 - u * u) + random(-0.8, 0.8);
      archPts.push([...toWorld(px, py), 0.5 + 0.4 * (1 - abs(u))]);
    }
    let col = y < 140 ? PAL.goldBright : y % 13 < 6.5 ? PAL.tealBright : PAL.ambWarm;
    brush.set("botanical_needle", col, 0.28);
    safeSpline(archPts, 0.4);
  }

  // 6. Longitudinal vascular cambium bundles & branching leaf-trace nodes
  for (let side of [-1, 1]) {
    for (let strand = 0; strand < 7; strand++) {
      let frac = 0.62 + strand * 0.065;
      let vPts = [];
      for (let y = 482; y >= 26; y -= 14) {
        let w = getCoreHalfWidth(y) * frac;
        let jitter = (noise(y * 0.05, strand * 2 + side) - 0.5) * 4.5;
        let [wx, wy] = toWorld(side * w + jitter, y);
        vPts.push([wx, wy, 0.5 + 0.5 * sin((y / 480) * 180)]);
      }
      let isOuter = strand >= 4;
      brush.set(
        isOuter ? "rotring" : "botanical_needle",
        strand === 5 ? PAL.tealWhite : isOuter ? PAL.tealGlow : PAL.tealMid,
        isOuter ? 0.5 : 0.32
      );
      safeSpline(vPts, 0.35);
    }

    // Branching vascular traces into the petiole bases along the core flanks
    for (let yNode = 445; yNode >= 75; yNode -= 32) {
      let w = getCoreHalfWidth(yNode);
      let [nx0, ny0] = toWorld(side * w * 0.65, yNode + 12);
      let [nx1, ny1] = toWorld(side * w * 1.02, yNode - 4);
      let [nx2, ny2] = toWorld(side * (w + 26), yNode - 18);
      brush.set("glow_edge", PAL.tealBright, 0.65);
      safeSpline([[nx0, ny0, 0.5], [nx1, ny1, 1.0], [nx2, ny2, 0.4]], 0.4);
      brush.set("botanical_needle", PAL.tealWhite, 0.38);
      safeSpline([[nx0, ny0, 0.5], [nx1, ny1, 1.0], [nx2, ny2, 0.4]], 0.4);
    }
  }

  // 7. Dense cellular stippling inside the core apex and cambium
  for (let i = 0; i < 320; i++) {
    let y = random(24, 480);
    let w = getCoreHalfWidth(y);
    let u = random(-1, 1);
    let [sx, sy] = toWorld(u * w * 0.92, y);
    let isCambium = abs(u) > 0.62;
    let col = isCambium ? PAL.tealGlow : y < 120 ? PAL.goldIncand : PAL.goldMid;
    brush.set("botanical_needle", col, random(0.28, 0.52));
    safeLine(sx, sy, sx + random(-1.2, 1.2), sy + random(-1.2, 1.2));
  }
}

// =============================================================================
// DRAWING STAGE 4: CONCENTRIC CRINKLED LEAF RIBBONS
// =============================================================================

function drawAllLeafRibbons() {
  const chunkLen = 14;

  // Pass 4A: Ribbon mesophyll body washes (gives every cut leaf slice solid anatomical thickness)
  brush.noStroke();
  for (let idx = 0; idx < shellRibbons.length; idx++) {
    let rib = shellRibbons[idx];
    let n = rib.ptsIn.length;

    for (let i = 0; i < n - 1; i += chunkLen) {
      let end = min(n - 1, i + chunkLen);
      if (end - i < 2) continue;

      let mMid = rib.meta[floor((i + end) * 0.5)];
      let col = pickMesophyllColor(mMid.tealFactor, mMid.crinkle, rib.tShell);
      let op = mMid.tealFactor > 0.45 ? 185 : 165;

      brush.wash(col, op);
      brush.beginShape(0.2);
      for (let k = i; k <= end; k++) {
        brush.vertex(rib.ptsIn[k][0], rib.ptsIn[k][1]);
      }
      for (let k = end; k >= i; k--) {
        brush.vertex(rib.ptsOut[k][0], rib.ptsOut[k][1]);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();

  // Pass 4B: Microscopic cellular cross-walls, central vascular thread & double epidermal cut edges
  for (let idx = 0; idx < shellRibbons.length; idx++) {
    let rib = shellRibbons[idx];
    let n = rib.ptsIn.length;

    // 1. Transverse cellular cross-striations bridging inner and outer epidermis
    let crossStep = rib.rNom < 200 ? 3 : 2;
    for (let i = 1; i < n - 1; i += crossStep) {
      let m = rib.meta[i];
      let pIn = rib.ptsIn[i];
      let pOut = rib.ptsOut[i];
      let cCol =
        m.tealFactor > 0.45
          ? PAL.tealBright
          : m.crinkle > 0.25
          ? PAL.goldBright
          : PAL.ambWarm;
      brush.set("botanical_needle", cCol, 0.24);
      safeLine(pIn[0], pIn[1], pOut[0], pOut[1]);
    }

    // 2. Chunked epidermal edges & central vascular trace along the ribbon
    for (let i = 0; i < n - 1; i += chunkLen - 1) {
      let end = min(n - 1, i + chunkLen);
      if (end - i < 2) continue;

      let mMid = rib.meta[floor((i + end) * 0.5)];
      let inChunk = [];
      let outChunk = [];
      let midChunk = [];

      for (let k = i; k <= end; k++) {
        let mk = rib.meta[k];
        let pPress = 0.55 + 0.45 * constrain(mk.thick / 8.0, 0.4, 1.3);
        inChunk.push([rib.ptsIn[k][0], rib.ptsIn[k][1], pPress]);
        outChunk.push([rib.ptsOut[k][0], rib.ptsOut[k][1], pPress]);
        midChunk.push([rib.ptsMid[k][0], rib.ptsMid[k][1], pPress * 0.7]);
      }

      // Soft luminous glow along the ribbon center/edges
      let glowCol =
        mMid.tealFactor > 0.42
          ? PAL.tealBright
          : mMid.crinkle > 0.15
          ? PAL.goldMid
          : PAL.ambWarm;
      brush.set("glow_edge", glowCol, 0.58);
      safeSpline(outChunk, 0.38);

      // Central vascular bundle thread inside the mesophyll
      if (mMid.thick > 4.2) {
        let vCol = mMid.tealFactor > 0.28 ? PAL.tealGlow : PAL.goldBright;
        brush.set("botanical_needle", vCol, 0.26);
        safeSpline(midChunk, 0.35);
      }

      // Inner epidermis cut edge (faces inward toward core/cavity)
      let inCol =
        mMid.tealFactor > 0.5
          ? PAL.tealGlow
          : mMid.cavityVal > 0.35
          ? PAL.magRose
          : PAL.goldMid;
      brush.set("botanical_needle", inCol, 0.36);
      safeSpline(inChunk, 0.4);

      // Outer epidermis cut edge (brightest top-lit botanical rim)
      let outCol =
        mMid.tealFactor > 0.5
          ? PAL.tealWhite
          : mMid.crinkle > 0.22
          ? PAL.goldIncand
          : PAL.goldBright;
      brush.set("botanical_needle", outCol, 0.42);
      safeSpline(outChunk, 0.4);

      // Incandescent specular edge glint on sharp crinkle crests
      if (mMid.crinkle > 0.38 || mMid.tealFactor > 0.68) {
        let subStart = max(0, floor(outChunk.length * 0.2));
        let subEnd = min(outChunk.length, ceil(outChunk.length * 0.8));
        let glintPts = outChunk.slice(subStart, subEnd);
        if (glintPts.length >= 3) {
          brush.set(
            "botanical_needle",
            mMid.tealFactor > 0.68 ? PAL.tealWhite : PAL.starWhite,
            0.3
          );
          safeSpline(glintPts, 0.42);
        }
      }
    }
  }
}

function pickMesophyllColor(tealFactor, crinkle, tShell) {
  if (tealFactor > 0.58) return PAL.tealMid;
  if (tealFactor > 0.34) return PAL.tealDeep;
  if (crinkle > 0.32) return PAL.goldMid;
  if (crinkle < -0.25) return PAL.ambDeep;
  return tShell < 0.28 ? PAL.ambWarm : PAL.ambMid;
}

// =============================================================================
// DRAWING STAGE 5: MAJOR CUT VEIN ISLANDS (MIDRIB CROSS-SECTIONS)
// =============================================================================

function drawAllVeinIslands() {
  // First batch watercolor fills for vein islands by color for high performance
  let islandGeoms = [];

  for (let v of veinIslands) {
    let env = getHeadEnvelope(v.phi);
    let rCenter = v.r * env;
    let upperPts = [];
    let lowerPts = [];
    let midArc = [];

    const nSteps = 20;
    for (let i = 0; i <= nSteps; i++) {
      let u = (i / nSteps) * 2 - 1; // -1 to +1 across the crescent
      let phi = v.phi + u * v.span * 1.15;
      let uSkew = u - v.skew * (1 - u * u * 0.4);
      let lens = pow(max(0, 1 - uSkew * uSkew), 1.35);

      // Crescent curvature follows the local shell geometry
      let rLocal = v.r * getHeadEnvelope(phi);
      let halfT = v.thick * lens + 1.6 * (1 - abs(u) * 0.5);

      // Slight kidney indentation on the inner (concave) face of the midrib
      let kidneyIndent = v.thick * 0.22 * pow(max(0, 1 - u * u * 1.8), 2);

      let rOut = rLocal + halfT * 1.05;
      let rIn = rLocal - halfT * 0.92 + kidneyIndent;
      let rMid = (rOut + rIn) * 0.5;

      upperPts.push(polarToWorld(rOut, phi));
      lowerPts.push(polarToWorld(rIn, phi));
      midArc.push({ pt: polarToWorld(rMid, phi), rMid, phi, halfT, u });
    }

    islandGeoms.push({ v, upperPts, lowerPts, midArc, rCenter });
  }

  // 1. Dark cavity shadow pockets around each vein island (especially at the pointed crescent tips)
  for (let g of islandGeoms) {
    let tipL = g.midArc[0];
    let tipR = g.midArc[g.midArc.length - 1];
    brush.set("fine_mist", PAL.cavityDeep, 1.7);
    safeLine(tipL.pt[0] - 8, tipL.pt[1] - 8, tipL.pt[0] + 8, tipL.pt[1] + 8);
    safeLine(tipR.pt[0] - 8, tipR.pt[1] - 8, tipR.pt[0] + 8, tipR.pt[1] + 8);

    brush.set("fine_mist", PAL.magBright, 1.25);
    let mL = g.midArc[2];
    let mR = g.midArc[g.midArc.length - 3];
    safeLine(tipL.pt[0], tipL.pt[1], mL.pt[0], mL.pt[1]);
    safeLine(tipR.pt[0], tipR.pt[1], mR.pt[0], mR.pt[1]);
  }

  // 2. Solid deep-teal base wash for all vein islands
  brush.noStroke();
  brush.wash(PAL.tealDeep, 230);
  for (let g of islandGeoms) {
    brush.beginShape(0.25);
    for (let p of g.upperPts) brush.vertex(p[0], p[1]);
    for (let i = g.lowerPts.length - 1; i >= 0; i--) {
      brush.vertex(g.lowerPts[i][0], g.lowerPts[i][1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 3. Batched luminous watercolor fill in space-telescope cyan-teal inside the vein parenchyma
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.35);
  brush.fill(PAL.tealMid, 175);
  for (let g of islandGeoms) {
    brush.beginShape(0.3);
    for (let i = 2; i < g.upperPts.length - 2; i++) {
      let pU = g.upperPts[i];
      let pM = g.midArc[i].pt;
      brush.vertex(lerp(pU[0], pM[0], 0.22), lerp(pU[1], pM[1], 0.22));
    }
    for (let i = g.lowerPts.length - 3; i >= 2; i--) {
      let pL = g.lowerPts[i];
      let pM = g.midArc[i].pt;
      brush.vertex(lerp(pL[0], pM[0], 0.22), lerp(pL[1], pM[1], 0.22));
    }
    brush.endShape(true);
  }
  brush.noFill();

  // 4. Microscopic parenchyma cellular striations, vascular bundle arcs & crisp collenchyma rims
  for (let g of islandGeoms) {
    let n = g.upperPts.length;

    // Gaseous cyan-white core mist along median arc
    let mistPts = g.midArc.slice(3, n - 3).map((m) => m.pt);
    brush.set("fine_mist", PAL.tealGlow, 1.15);
    safeSpline(mistPts, 0.4);

    // Radial cellular parenchyma lines bridging upper and lower epidermis of the midrib
    for (let i = 2; i < n - 2; i++) {
      let pU = g.upperPts[i];
      let pL = g.lowerPts[i];
      let pM = g.midArc[i].pt;
      brush.set("botanical_needle", i % 2 === 0 ? PAL.tealBright : PAL.tealShadow, 0.25);
      safeLine(pL[0], pL[1], pM[0], pM[1]);
      safeLine(pM[0], pM[1], pU[0], pU[1]);
    }

    // Internal row of Vascular Bundles (Xylem/Phloem rosettes characteristic of Brassica petioles)
    let numBundles = floor(map(g.v.thick, 11, 24, 5, 10));
    for (let b = 1; b <= numBundles; b++) {
      let frac = b / (numBundles + 1);
      let idx = constrain(round(frac * (n - 1)), 2, n - 3);
      let m = g.midArc[idx];
      let [bx, by] = m.pt;

      // Dark sclerenchyma bundle sheath
      brush.set("rotring", PAL.tealShadow, 0.65);
      brush.circle(bx, by, 2.6, 0.2);

      // Warm gold phloem cap (outer side of bundle)
      let [px, py] = polarToWorld(m.rMid + 1.6, m.phi);
      brush.set("botanical_needle", PAL.goldBright, 0.55);
      safeLine(px - 0.8, py - 0.8, px + 0.8, py + 0.8);

      // Incandescent cyan-white xylem vessels (inner side of bundle)
      let [xx, xy] = polarToWorld(m.rMid - 1.2, m.phi);
      brush.set("botanical_needle", PAL.tealWhite, 0.6);
      safeLine(xx - 0.7, xy - 0.7, xx + 0.7, xy + 0.7);
    }

    // Outer collenchyma glow & crisp double-walled cut boundary
    let uSpline = g.upperPts.map((p, idx) => [
      p[0],
      p[1],
      0.5 + 0.6 * sin((idx / (n - 1)) * 180)
    ]);
    let lSpline = g.lowerPts.map((p, idx) => [
      p[0],
      p[1],
      0.5 + 0.6 * sin((idx / (n - 1)) * 180)
    ]);

    brush.set("glow_edge", PAL.tealBright, 0.75);
    safeSpline(uSpline, 0.4);
    safeSpline(lSpline, 0.4);

    // Amber-gold sub-epidermal transition line where vein meets surrounding leaf blades
    brush.set("botanical_needle", PAL.goldMid, 0.36);
    safeSpline(lSpline, 0.4);

    // Razor-sharp cyan-white & gold-white cut rim
    brush.set("botanical_needle", PAL.tealGlow, 0.46);
    safeSpline(uSpline, 0.4);

    let crownSlice = uSpline.slice(floor(n * 0.22), ceil(n * 0.78));
    brush.set("botanical_needle", PAL.tealWhite, 0.35);
    safeSpline(crownSlice, 0.42);
  }
}

// =============================================================================
// DRAWING STAGE 6: INNER MERISTEM HEART (CONVOLUTED BABY LEAF WHORLS)
// =============================================================================

function drawMeristemHeart() {
  // Three nested meristematic rosette centers right above the stem core apex
  const whorls = [
    { lx: 0, ly: -34, rx: 46, ry: 38, rings: 6, rot: 8 },
    { lx: -46, ly: -18, rx: 32, ry: 28, rings: 5, rot: -22 },
    { lx: 46, ly: -20, rx: 32, ry: 28, rings: 5, rot: 25 }
  ];

  // Deep magenta-black cavern shadow behind the baby whorls
  for (let w of whorls) {
    let [wx, wy] = toWorld(w.lx, w.ly);
    brush.set("nebula_gas", PAL.cavityDeep, 1.5);
    safeLine(wx - 15, wy, wx + 15, wy);
    brush.set("fine_mist", PAL.magBright, 1.25);
    safeLine(wx - 12, wy - 8, wx + 12, wy + 8);
  }

  for (let wIdx = 0; wIdx < whorls.length; wIdx++) {
    let w = whorls[wIdx];
    for (let rIdx = 0; rIdx < w.rings; rIdx++) {
      let t = (rIdx + 1) / w.rings;
      // Split each whorl ring into 2 tightly folded C/S-shaped baby leaves
      for (let half = 0; half < 2; half++) {
        let aStart = half * 180 - 15 + rIdx * 23 + w.rot;
        let aEnd = aStart + 162;

        let inPts = [];
        let outPts = [];
        let steps = 28;

        for (let i = 0; i <= steps; i++) {
          let u = i / steps;
          let ang = aStart + u * (aEnd - aStart);

          // Intense serpentine brain-like folding
          let foldFreq = 7 + rIdx * 2;
          let foldWave =
            (2.4 + 4.2 * t) * sin(ang * foldFreq + rIdx * 55 + wIdx * 90);
          let tangShift = 6.5 * cos(ang * foldFreq + rIdx * 55);

          let aMod = ang + tangShift;
          let radX = w.rx * t + foldWave;
          let radY = w.ry * t + foldWave;

          let thick = (2.4 + 2.2 * t) * sin(u * 180);

          let lxIn = w.lx + (radX - thick * 0.5) * cos(aMod);
          let lyIn = w.ly + (radY - thick * 0.5) * sin(aMod);
          let lxOut = w.lx + (radX + thick * 0.5) * cos(aMod);
          let lyOut = w.ly + (radY + thick * 0.5) * sin(aMod);

          let pIn = toWorld(lxIn, lyIn);
          let pOut = toWorld(lxOut, lyOut);

          inPts.push([pIn[0], pIn[1], 0.5 + 0.5 * sin(u * 180)]);
          outPts.push([pOut[0], pOut[1], 0.5 + 0.5 * sin(u * 180)]);
        }

        // Baby leaf wash
        let isTealHeart = rIdx < 2 || (rIdx === 2 && half === 0);
        brush.noStroke();
        brush.wash(isTealHeart ? PAL.tealMid : PAL.ambWarm, 185);
        brush.beginShape(0.25);
        for (let p of inPts) brush.vertex(p[0], p[1]);
        for (let i = outPts.length - 1; i >= 0; i--) {
          brush.vertex(outPts[i][0], outPts[i][1]);
        }
        brush.endShape(true);
        brush.noWash();

        // Crisp glowing edges of baby meristem leaves
        brush.set("glow_edge", isTealHeart ? PAL.tealGlow : PAL.goldBright, 0.5);
        safeSpline(outPts, 0.42);

        brush.set("botanical_needle", isTealHeart ? PAL.tealBright : PAL.magRose, 0.32);
        safeSpline(inPts, 0.42);

        brush.set("botanical_needle", isTealHeart ? PAL.tealWhite : PAL.starWhite, 0.36);
        safeSpline(outPts, 0.42);
      }
    }
  }
}

// =============================================================================
// DRAWING STAGE 7: GASEOUS NEBULA HIGHLIGHTS & OUTER STIPPLED STARFIELD
// =============================================================================

function drawGaseousHighlightsAndStarfield() {
  // 1. Loosening outer wrapper leaf tendrils & billowing nebula plumes around the rim
  for (let i = 0; i < 18; i++) {
    let phiStart = -162 + i * 19 + random(-4, 4);
    let span = random(16, 30);
    let rBase = R_HEAD + random(6, 26);

    let tendrilIn = [];
    let tendrilOut = [];
    let steps = 18;

    for (let k = 0; k <= steps; k++) {
      let u = k / steps;
      let phi = phiStart + u * span;
      let env = getHeadEnvelope(phi);
      // Tendril lifts outward into the void at its distal tip
      let lift = 18 * pow(u, 1.8) + 5.5 * sin(u * 360 * 2.5 + i * 40);
      let r = rBase * env + lift;
      let thick = 5.5 * (1 - u * 0.85) * pow(constrain(u / 0.12, 0.2, 1), 0.5);

      let pIn = polarToWorld(r - thick * 0.5, phi);
      let pOut = polarToWorld(r + thick * 0.5, phi);
      tendrilIn.push([pIn[0], pIn[1], 1 - u * 0.6]);
      tendrilOut.push([pOut[0], pOut[1], 1 - u * 0.6]);
    }

    // Nebula gas plume trailing off the wrapper leaf
    let midP = tendrilOut[floor(steps * 0.5)];
    let tipP = tendrilOut[steps];
    brush.set("nebula_gas", i % 3 === 0 ? PAL.tealDeep : PAL.magMid, 1.6);
    safeLine(midP[0], midP[1], tipP[0], tipP[1]);

    brush.set("fine_mist", i % 3 === 0 ? PAL.tealBright : PAL.ambWarm, 1.15);
    safeLine(midP[0], midP[1], tipP[0], tipP[1]);

    // Wrapper leaf strokes
    brush.set("glow_edge", i % 3 === 0 ? PAL.tealBright : PAL.goldMid, 0.6);
    safeSpline(tendrilOut, 0.4);

    brush.set("botanical_needle", PAL.magRose, 0.32);
    safeSpline(tendrilIn, 0.4);

    brush.set("botanical_needle", i % 3 === 0 ? PAL.tealGlow : PAL.goldIncand, 0.38);
    safeSpline(tendrilOut, 0.4);
  }

  // 2. Dense stippled points scattering like stars along the outer edge into the black void
  // Inner rim stellar granulation (r: 445..515, ~2400 stipples)
  const rimColors = [
    PAL.goldIncand,
    PAL.goldBright,
    PAL.goldMid,
    PAL.ambWarm,
    PAL.tealGlow,
    PAL.tealBright,
    PAL.magRose,
    PAL.starWhite
  ];

  for (let cIdx = 0; cIdx < rimColors.length; cIdx++) {
    let col = rimColors[cIdx];
    let count = cIdx < 3 ? 420 : 280;
    brush.set("botanical_needle", col, 0.38);

    for (let i = 0; i < count; i++) {
      let phi = random(-180, 180);
      let env = getHeadEnvelope(phi);
      // Tangential spiral dust streams
      let streamMod = sin(phi * 9 + cIdx * 35) * 14;
      let r = (R_HEAD - 18 + pow(random(), 1.6) * 88) * env + streamMod;
      let [sx, sy] = polarToWorld(r, phi);
      let len = random(0.6, 1.6);
      let ang = phi + 90 + random(-25, 25);
      brush.line(sx, sy, sx + len * cos(ang), sy + len * sin(ang));
    }
  }

  // Mid-halo & deep-field cosmic stars scattering out to the canvas borders (~1400 stars)
  for (let cIdx = 0; cIdx < rimColors.length; cIdx++) {
    let col = rimColors[cIdx];
    brush.set("botanical_needle", col, 0.32);
    for (let i = 0; i < 175; i++) {
      let phi = random(-180, 180);
      let env = getHeadEnvelope(phi);
      let r = (R_HEAD + 42) * env + pow(random(), 2.1) * 280;
      let [sx, sy] = polarToWorld(r, phi);
      if (sx > 12 && sx < width - 12 && sy > 12 && sy < height - 12) {
        brush.line(sx, sy, sx + random(0.5, 1.3), sy + random(-0.8, 0.8));
      }
    }
  }

  // 3. Interior microscopic cellular & nebular stipple highlights across the cabbage face
  for (let i = 0; i < 650; i++) {
    let phi = random(-170, 170);
    let r = random(45, R_HEAD - 15) * getHeadEnvelope(phi);
    let [sx, sy] = polarToWorld(r, phi);
    let isTeal = i % 4 === 0;
    let col = isTeal ? PAL.tealWhite : i % 3 === 0 ? PAL.starWhite : PAL.goldBright;
    brush.set("botanical_needle", col, random(0.25, 0.45));
    brush.line(sx, sy, sx + random(0.6, 1.4), sy + random(-0.8, 0.8));
  }

  // 4. Space-Telescope Diffraction-Spiked Stars in the surrounding black void
  // (Authentic 6-point JWST symmetry subtly reinforcing the deep-field telescope aesthetic)
  for (let i = 0; i < 28; i++) {
    let phi = i * (360 / 28) + random(-6, 6);
    let env = getHeadEnvelope(phi);
    let r = (R_HEAD + random(24, 155)) * env;
    let [sx, sy] = polarToWorld(r, phi);

    if (sx > 28 && sx < width - 28 && sy > 28 && sy < height - 28) {
      let starSize = random(4.5, 13.5);
      let isTealStar = i % 3 === 0;
      drawTelescopeStar(
        sx,
        sy,
        starSize,
        isTealStar ? PAL.tealGlow : PAL.goldBright,
        isTealStar ? PAL.tealWhite : PAL.starWhite
      );
    }
  }
}

function drawTelescopeStar(x, y, rad, glowCol, coreCol) {
  // Soft nebula halo around star
  brush.set("fine_mist", glowCol, 0.85);
  safeLine(x - 1.5, y, x + 1.5, y);

  // 6-point JWST diffraction spikes (30, 90, 150 degrees)
  brush.set("botanical_needle", glowCol, 0.26);
  const angles = [30, 90, 150];
  for (let a of angles) {
    let r = a === 90 ? rad * 1.25 : rad;
    safeLine(x - r * cos(a), y - r * sin(a), x + r * cos(a), y + r * sin(a));
  }

  // Pinpoint incandescent stellar core
  brush.set("botanical_needle", coreCol, 0.55);
  safeLine(x - 1.2, y, x + 1.2, y);
  safeLine(x, y - 1.2, x, y + 1.2);
}

// =============================================================================
// SAFE GEOMETRY PRIMITIVE HELPERS
// =============================================================================

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) > 0.4) {
    brush.line(x1, y1, x2, y2);
  }
}

function safeSpline(pts, curvature = 0.4) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let curr = pts[i];
    if (dist(prev[0], prev[1], curr[0], curr[1]) > 1.2) {
      clean.push(curr);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

