// ============================================================================
// MATHEMATICAL MODEL OF THE HEIRLOOM AUBERGINE & 3D SURFACE NORMALS
// ============================================================================

// Tray transform parameters
const TRAY = {
  cx: 605,
  cy: 615,
  rx: 535,
  ry: 390,
  innerRx: 492,
  innerRy: 354,
  angle: -11
};

function trayPoint(aDeg, radScaleX = 1, radScaleY = 1, rx = TRAY.rx, ry = TRAY.ry) {
  let ca = cos(aDeg);
  let sa = sin(aDeg);
  let lx = ca * rx * radScaleX;
  let ly = sa * ry * radScaleY;
  let rotC = cos(TRAY.angle);
  let rotS = sin(TRAY.angle);
  return {
    x: TRAY.cx + lx * rotC - ly * rotS,
    y: TRAY.cy + lx * rotS + ly * rotC
  };
}

// Aubergine spine & cross-section parameterization
// u in [0, 1]: 0 = neck/calyx attachment, 1 = blossom apex
// theta in [-90, 90] degrees: -90 = top silhouette, 0 = front center, +90 = bottom belly
function aubergineSpine(u) {
  let x = 372 + 492 * u - 14 * sin(u * 180);
  let y = 478 + 132 * u + 56 * sin(pow(u, 0.88) * 180);
  return { x, y };
}

function aubergineRadius(u, thetaDeg = 0) {
  let baseR;
  if (u <= 0.67) {
    let t = u / 0.67;
    // Concave neck transition swelling into voluptuous belly
    baseR = 43 + 123 * (0.18 * t + 0.82 * pow(t, 1.85)) - 7 * sin(t * 180);
  } else {
    let t = (u - 0.67) / 0.33;
    let dome = sqrt(max(0, 1 - t * t));
    baseR = 166 * dome * (1 - 0.06 * t * t);
  }

  // Subtle organic heirloom longitudinal ribs/lobes + heavy belly asymmetry
  let s = sin(thetaDeg);
  let c = cos(thetaDeg);
  let bellyWeight = s > 0 ? 1 + 0.065 * s * sin(u * 180) : 1 - 0.025 * (-s) * sin(u * 180);
  let lobeEnv = pow(sin(u * 180), 1.15) * c;
  let lobes = 1 + lobeEnv * (0.028 * cos(thetaDeg * 4.2 + 18) + 0.014 * sin(thetaDeg * 2.5 - u * 90));

  // Slight puckering grooves right under the calyx fingers (u < 0.22)
  let calyxPucker = 1;
  if (u < 0.24) {
    let pk = pow(1 - u / 0.24, 2);
    calyxPucker -= 0.035 * pk * cos(thetaDeg * 5.5) * c;
  }

  return baseR * bellyWeight * lobes * calyxPucker;
}

function aubergineSurface(u, thetaDeg) {
  let eps = 0.004;
  let u0 = constrain(u - eps, 0, 1);
  let u1 = constrain(u + eps, 0, 1);
  let p0 = aubergineSpine(u0);
  let p1 = aubergineSpine(u1);
  let p = aubergineSpine(u);

  let dx = p1.x - p0.x;
  let dy = p1.y - p0.y;
  let len = sqrt(dx * dx + dy * dy) || 1;
  // Spine tangent T and perpendicular N2D (pointing downward toward belly)
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;

  let r = aubergineRadius(u, thetaDeg);
  let s = sin(thetaDeg);
  let c = cos(thetaDeg);

  // Screen position
  // As u approaches 1, dome closes smoothly
  let x = p.x + nx * r * s;
  let y = p.y + ny * r * s;
  let z = r * c;

  // Compute 3D surface normal via finite differences in (u, theta)
  let r_u1 = aubergineRadius(u1, thetaDeg);
  let r_u0 = aubergineRadius(u0, thetaDeg);
  let dr_du = (r_u1 - r_u0) / ((u1 - u0) * 510);

  let dTheta = 2.0;
  let r_t1 = aubergineRadius(u, constrain(thetaDeg + dTheta, -90, 90));
  let r_t0 = aubergineRadius(u, constrain(thetaDeg - dTheta, -90, 90));
  let dr_dth = (r_t1 - r_t0) / (radians(2 * dTheta) * max(8, r));

  // Local frame normal components: (along T, along N2D, along +Z)
  let nT = -dr_du * c;
  if (u > 0.67) {
    let domeT = (u - 0.67) / 0.33;
    nT = lerp(nT, pow(domeT, 1.35), pow(domeT, 0.8));
  }
  let nN = s - dr_dth * c;
  let nZ = c + dr_dth * s;

  // Convert to world 3D normal (Nx, Ny, Nz)
  let Wx = nT * tx + nN * nx;
  let Wy = nT * ty + nN * ny;
  let Wz = max(0.02, nZ * (1 - 0.35 * max(0, nT)));
  let nLen = sqrt(Wx * Wx + Wy * Wy + Wz * Wz) || 1;

  return {
    x,
    y,
    z,
    r,
    tx,
    ty,
    nx,
    ny,
    Nx: Wx / nLen,
    Ny: Wy / nLen,
    Nz: Wz / nLen
  };
}

// Compute reflection & studio window map for liquid reflections
function evaluateSkinOptics(u, thetaDeg) {
  let surf = aubergineSurface(u, thetaDeg);
  let Nx = surf.Nx;
  let Ny = surf.Ny;
  let Nz = surf.Nz;

  // Reflection of view vector V = (0, 0, 1) across N: R = (2*Nz*Nx, 2*Nz*Ny, 2*Nz^2 - 1)
  // Effective spherical coordinates of the reflected ray:
  let rx = Nx + 0.12 * sin(u * 220 + thetaDeg * 2);
  let ry = Ny - 0.06 * cos(u * 180 - thetaDeg * 3);

  // Fresnel factor (stronger reflection near grazing angles, softer at front center)
  let fresnel = pow(1 - constrain(Nz, 0, 1), 1.65);

  // ------------------------------------------------------------------
  // 1. PRIMARY LIQUID STUDIO WINDOW REFLECTION
  // ------------------------------------------------------------------
  // Window is positioned in upper-left reflection space:
  // Because the neck is concave and the belly is convex with lobes,
  // (wx, wy) warps organically like liquid across the aubergine skin.
  let wx = (rx + 0.14 - 0.16 * (u - 0.45)) / 0.42;
  let wy = (ry + 0.48 + 0.08 * sin(u * 260)) / 0.31;

  // Liquid shear / ripple along the curved form
  wx += 0.14 * wy * (u - 0.35) + 0.05 * sin(u * 360 + thetaDeg * 3);
  wy += 0.09 * wx * wx - 0.04 * cos(u * 300);

  let windowPane = 0;
  let windowHalo = 0;
  if (u > 0.08 && u < 0.93 && thetaDeg > -78 && thetaDeg < 18) {
    // Rounded arch window boundary
    let archY = wy + 0.12 * wx * wx;
    let distBox = max(abs(wx) - 0.92, abs(archY) - 0.82);

    if (distBox < 0.38) {
      windowHalo = constrain(1 - (distBox + 0.15) / 0.52, 0, 1);
      windowHalo = pow(windowHalo, 1.6);
    }

    if (distBox < 0.0) {
      // Soft window boundary falloff
      let edgeSoft = constrain(-distBox / 0.11, 0, 1);
      // Curved window mullions (3 columns x 2 rows of panes)
      let mullionX1 = abs(wx + 0.31);
      let mullionX2 = abs(wx - 0.31);
      let mullionY = abs(archY + 0.04);

      let barX = min(
        constrain((mullionX1 - 0.032) / 0.035, 0, 1),
        constrain((mullionX2 - 0.032) / 0.035, 0, 1)
      );
      let barY = constrain((mullionY - 0.038) / 0.04, 0, 1);

      // Intensity gradient across window panes (brighter in upper-left panes, warm persimmon toward edges)
      let paneGrad = 0.72 + 0.28 * (1 - (wx + 1) * 0.35) * (1 - (wy + 1) * 0.25);
      windowPane = edgeSoft * barX * barY * paneGrad;
    }
  }

  // ------------------------------------------------------------------
  // 2. SECONDARY BLOSSOM-END & NECK LIQUID STREAMERS
  // ------------------------------------------------------------------
  // Sleek liquid streamer running up the narrow neck toward the calyx
  let neckStream = 0;
  if (u > 0.04 && u < 0.42) {
    let targetTh = -34 + 8 * sin(u * 400);
    let dTh = abs(thetaDeg - targetTh);
    if (dTh < 14) {
      neckStream = pow(1 - dTh / 14, 2.2) * sin(((u - 0.04) / 0.38) * 180) * 0.75;
    }
  }

  // Curved secondary reflection near the bulbous blossom dome (u in 0.72..0.95)
  let domeRefl = 0;
  if (u > 0.68 && u < 0.96) {
    let targetTh = -18 + 28 * ((u - 0.68) / 0.28);
    let dTh = abs(thetaDeg - targetTh);
    if (dTh < 22) {
      let uEnv = sin(((u - 0.68) / 0.28) * 180);
      // Split by a single curved mullion
      let split = abs(u - 0.83) < 0.012 ? 0.15 : 1.0;
      domeRefl = pow(1 - dTh / 22, 2.0) * uEnv * split * 0.68;
    }
  }

  // ------------------------------------------------------------------
  // 3. WARM PERSIMMON BOUNCE & RIM GLOW
  // ------------------------------------------------------------------
  // Lower-right and belly grazing persimmon glow from warm studio bounce
  let persimmonRim = 0;
  if (thetaDeg > 15 && thetaDeg < 82) {
    let thEnv = sin(((thetaDeg - 15) / 67) * 180);
    let uEnv = pow(sin(constrain((u - 0.12) / 0.85, 0, 1) * 180), 0.9);
    persimmonRim = pow(thEnv, 1.5) * uEnv * (0.45 + 0.55 * fresnel);
  }
  // Upper-back grazing persimmon/plum edge light
  let topRim = 0;
  if (thetaDeg < -55 && thetaDeg > -87) {
    let thEnv = sin(((thetaDeg + 87) / 32) * 180);
    topRim = pow(thEnv, 1.4) * sin(u * 180) * 0.65;
  }

  // Diffuse purple-black volume light
  let diffuse = constrain(-0.25 * Nx - 0.55 * Ny + 0.65 * Nz, 0, 1);

  return {
    surf,
    fresnel,
    diffuse,
    windowPane,
    windowHalo,
    neckStream,
    domeRefl,
    persimmonRim,
    topRim
  };
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background("#060508");

  // 1. Deep layered lamp-black ground & charcoal masses
  drawLayeredBlackGround();

  // 2. Ceremonial black lacquer tray (recessed well, bevel, rim)
  drawLacquerTrayBase();

  // 3. Drifting clouds of fine maki-e gold dust across the lacquer tray
  drawDriftingGoldDust();

  // 4. Hairline burnished gold pen tendrils along the tray's rim
  drawGoldRimTendrils();

  // 5. Mirror reflection & abyssal contact shadow of the aubergine in the black lacquer
  drawAubergineLacquerReflection();

  // 6. The Aubergine: base washes, deep purple-black glazes, cross-contour & longitudinal skin
  drawAubergineBody();

  // 7. The Liquid Window Reflections & Persimmon Speculars
  drawLiquidWindowReflections();

  // 8. The Fuzzy, Exact Green Calyx & Woody Curved Stem
  drawFuzzyGreenCalyx();

  noLoop();
}

// ============================================================================
// 1. DEEP LAYERED BLACK GROUND
// ============================================================================
function drawLayeredBlackGround() {
  brush.noStroke();

  // Deep glazes around the outer corners and background
  brush.wash("#050407", 230);
  brush.rect(0, 0, 1200, 1200);

  // Subtle charcoal mass passes to give the dark ground physical, velvety tooth
  let groundZones = [
    { x: 60, y: 60, w: 1080, h: 320, col: "#09080c", ang: -12 },
    { x: 60, y: 820, w: 1080, h: 320, col: "#07060a", ang: -10 },
    { x: 80, y: 300, w: 1040, h: 600, col: "#0b0910", ang: -11 }
  ];

  for (let z of groundZones) {
    brush.mass("charcoal", z.col, {
      precision: 0.82,
      strength: 0.45,
      gradient: 0.35,
      outline: false
    });
    brush.rect(z.x, z.y, z.w, z.h);
    brush.noMass();
  }

  // Diagonal charcoal atmospheric grain across the background
  brush.hatchStyle("charcoal", "#0d0b12", 1.1);
  brush.hatch(18, -11, { rand: 0.12, gradient: 0.3 });
  brush.rect(20, 20, 1160, 1160);
  brush.noHatch();
}

// ============================================================================
// 2. CEREMONIAL BLACK LACQUER TRAY
// ============================================================================
function drawLacquerTrayBase() {
  brush.noStroke();

  // Outer drop shadow of the tray on the dark ground
  brush.wash("#020104", 210);
  drawTrayEllipseShape(TRAY.rx + 18, TRAY.ry + 22, 8, 16);

  // Tray raised outer rim base in warm urushi black
  brush.wash("#120d10", 245);
  drawTrayEllipseShape(TRAY.rx, TRAY.ry, 0, 0);

  // Rim bevel highlight (subtle warm lacquer bronze-persimmon sheen along the raised lip)
  brush.set("glaze", "#291814", 1.1);
  drawTrayArc(-165, -15, TRAY.rx - 8, TRAY.ry - 6, 48);
  brush.set("glaze", "#211510", 1.0);
  drawTrayArc(15, 165, TRAY.rx - 6, TRAY.ry - 5, 48);

  // Inner recessed well of the lacquer tray — deepest mirror lamp-black
  brush.noStroke();
  brush.wash("#060508", 250);
  drawTrayEllipseShape(TRAY.innerRx, TRAY.innerRy, 0, 0);

  // Layered dark watercolor glazes inside the tray well for deep urushi depth
  brush.fill("#09060d", 110);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.35, 0.2);
  drawTrayEllipseShape(TRAY.innerRx - 10, TRAY.innerRy - 8, 0, 0);
  brush.noFill();

  // Inner step shadow where the raised rim drops into the tray floor (top-left inner wall)
  brush.set("charcoal", "#020103", 1.8);
  drawTrayArc(-175, 25, TRAY.innerRx + 2, TRAY.innerRy + 2, 60);

  // Opposite inner rim wall catching a faint warm persimmon-gold reflection (bottom-right)
  brush.set("cpencil", "#381c14", 0.9);
  drawTrayArc(18, 155, TRAY.innerRx + 3, TRAY.innerRy + 3, 55);
  brush.set("2H", "#66371e", 0.55);
  drawTrayArc(32, 135, TRAY.innerRx + 1, TRAY.innerRy + 1, 45);

  // Ultra-fine diagonal lacquer polish lines across the tray floor
  for (let i = -14; i <= 14; i++) {
    let t = i / 14;
    let yOff = t * (TRAY.innerRy * 0.85);
    let halfChord = sqrt(max(0, 1 - t * t)) * (TRAY.innerRx * 0.92);
    let rotC = cos(TRAY.angle);
    let rotS = sin(TRAY.angle);
    let x1 = TRAY.cx + (-halfChord) * rotC - yOff * rotS;
    let y1 = TRAY.cy + (-halfChord) * rotS + yOff * rotC;
    let x2 = TRAY.cx + halfChord * rotC - yOff * rotS;
    let y2 = TRAY.cy + halfChord * rotS + yOff * rotC;

    // Subtle sheen band across the upper-middle lacquer floor
    let sheen = exp(-pow((t + 0.18) / 0.35, 2));
    let col = sheen > 0.45 ? "#141018" : "#0b090f";
    brush.set("glaze", col, 0.8 + sheen * 0.7);
    brush.line(x1, y1, x2, y2);
  }
}

function drawTrayEllipseShape(rx, ry, offX = 0, offY = 0) {
  brush.beginShape(0.3);
  let steps = 40;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let p = trayPoint(a, 1, 1, rx, ry);
    brush.vertex(p.x + offX, p.y + offY);
  }
  brush.endShape(true);
}

function drawTrayArc(aStart, aEnd, rx, ry, steps = 40) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    let p = trayPoint(a, 1, 1, rx, ry);
    let pr = sin((i / steps) * 180);
    pts.push([p.x, p.y, 0.25 + 0.75 * pr]);
  }
  brush.spline(pts, 0.4);
}

// ============================================================================
// 3. DRIFTING CLOUDS OF FINE GOLD DUST (MAKI-E / NASHIJI)
// ============================================================================
function drawDriftingGoldDust() {
  // Define 3 graceful drifting cloud currents across the lacquer tray
  // Cloud 1: Sweeps from lower-left inner rim across the left & upper-left field
  // Cloud 2: Drifts beneath the aubergine's right side toward the upper-right tray well
  // Cloud 3: A soft whisper pooling in the lower-central tray floor

  // Warm subsurface nashiji amber-bronze glow under the densest gold dust clouds
  brush.noStroke();
  let glowClouds = [
    { a: 155, rScale: 0.65, radX: 150, radY: 75, col: "#1e1407", op: 55 },
    { a: -145, rScale: 0.58, radX: 170, radY: 85, col: "#241808", op: 65 },
    { a: -25, rScale: 0.62, radX: 185, radY: 90, col: "#211608", op: 60 },
    { a: 45, rScale: 0.68, radX: 145, radY: 70, col: "#1a1106", op: 50 },
    { a: 105, rScale: 0.52, radX: 130, radY: 60, col: "#1c1307", op: 45 }
  ];

  for (let gc of glowClouds) {
    let c = trayPoint(gc.a, gc.rScale, gc.rScale, TRAY.innerRx, TRAY.innerRy);
    brush.wash(gc.col, gc.op);
    brush. beginShape(0.4);
    for (let k = 0; k < 16; k++) {
      let ang = (k / 16) * 360;
      let n = 0.8 + 0.35 * noise(c.x * 0.01 + cos(ang), c.y * 0.01 + sin(ang));
      let vx = c.x + cos(ang + TRAY.angle) * gc.radX * n;
      let vy = c.y + sin(ang + TRAY.angle) * gc.radY * n;
      brush.vertex(vx, vy);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // Sweeping spray passes along drifting S-curves inside the tray
  let driftCurrents = [
    // Upper-left to center-left drift
    {
      pts: [
        [-0.84, 0.25],
        [-0.68, -0.05],
        [-0.45, -0.32],
        [-0.15, -0.48],
        [0.18, -0.52]
      ],
      spread: 58,
      density: 1.0
    },
    // Lower-left to center drift
    {
      pts: [
        [-0.72, 0.48],
        [-0.42, 0.52],
        [-0.08, 0.44],
        [0.25, 0.35]
      ],
      spread: 52,
      density: 0.85
    },
    // Center-right to upper-right drift
    {
      pts: [
        [0.18, 0.42],
        [0.45, 0.28],
        [0.68, 0.02],
        [0.82, -0.28],
        [0.65, -0.55]
      ],
      spread: 64,
      density: 1.05
    }
  ];

  let goldTones = ["#5e4314", "#8a6523", "#b88b38", "#d9b155", "#f2d37e"];

  for (let dc of driftCurrents) {
    // Convert normalized tray coords to screen spline
    let screenPts = dc.pts.map((pt) => {
      let rotC = cos(TRAY.angle);
      let rotS = sin(TRAY.angle);
      let lx = pt[0] * TRAY.innerRx;
      let ly = pt[1] * TRAY.innerRy;
      return [TRAY.cx + lx * rotC - ly * rotS, TRAY.cy + lx * rotS + ly * rotC];
    });

    // Multi-layered gold_dust and spray passes
    for (let pass = 0; pass < 7; pass++) {
      let col = goldTones[pass % goldTones.length];
      let w = map(pass, 0, 6, 1.4, 0.55) * dc.density;
      brush.set(pass % 2 === 0 ? "gold_dust" : "spray", col, w);

      let offsetPts = screenPts.map((p, idx) => {
        let ang = pass * 55 + idx * 70;
        let d = (pass - 3) * (dc.spread * 0.22);
        return [
          p[0] + cos(ang) * d + random(-14, 14),
          p[1] + sin(ang) * d * 0.7 + random(-14, 14),
          0.35 + 0.6 * sin(((idx + 0.5) / screenPts.length) * 180)
        ];
      });
      brush.spline(offsetPts, 0.5);
    }

    // Fine individual maki-e gold dust particles & flakes along the current
    let numSpecks = floor(420 * dc.density);
    for (let i = 0; i < numSpecks; i++) {
      let t = random(1);
      // Interpolate along piecewise segments
      let segF = t * (screenPts.length - 1);
      let idx = constrain(floor(segF), 0, screenPts.length - 2);
      let frac = segF - idx;
      let bx = lerp(screenPts[idx][0], screenPts[idx + 1][0], frac);
      let by = lerp(screenPts[idx][1], screenPts[idx + 1][1], frac);

      // Gaussian-like scatter modulated by Perlin noise for nebular clustering
      let rGauss = (random() + random() + random() - 1.5) * dc.spread * 1.45;
      let ang = random(360);
      let px = bx + cos(ang) * rGauss * 1.25;
      let py = by + sin(ang) * rGauss * 0.85;

      // Ensure particle stays inside inner tray ellipse
      let dx = px - TRAY.cx;
      let dy = py - TRAY.cy;
      let rotC = cos(-TRAY.angle);
      let rotS = sin(-TRAY.angle);
      let lx = (dx * rotC - dy * rotS) / (TRAY.innerRx - 8);
      let ly = (dx * rotS + dy * rotC) / (TRAY.innerRy - 8);
      if (lx * lx + ly * ly > 0.98) continue;

      let nVal = noise(px * 0.012, py * 0.012);
      if (nVal < 0.34) continue;

      // Choose gold tone based on core density
      let distRatio = abs(rGauss) / (dc.spread * 0.75);
      let toneIdx = constrain(floor(map(nVal - distRatio * 0.35, 0.2, 0.75, 0, 4.99)), 0, 4);
      let col = goldTones[toneIdx];

      let speckLen = random(0.6, 2.2) * (toneIdx >= 3 ? 1.15 : 0.85);
      let speckAng = TRAY.angle + random(-35, 35);
      brush.set(toneIdx >= 3 ? "rotring" : "2H", col, random(0.32, 0.75));
      brush.line(
        px,
        py,
        px + cos(speckAng) * speckLen,
        py + sin(speckAng) * speckLen
      );
    }
  }
}

// ============================================================================
// 4. HAIRLINE GOLD PEN TENDRILS FOLLOWING THE TRAY'S RIM
// ============================================================================
function drawGoldRimTendrils() {
  let rimMidRx = (TRAY.rx + TRAY.innerRx) * 0.5;
  let rimMidRy = (TRAY.ry + TRAY.innerRy) * 0.5;
  let rimHalfW = (TRAY.rx - TRAY.innerRx) * 0.5;

  // Helper to draw a flowing botanical gold tendril along an angular span of the rim
  function drawTendrilSpan(aStart, aEnd, freq, ampScale, goldCol, hiCol, weightBase) {
    let steps = 55;
    let mainPts = [];
    let echoPts = [];

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = lerp(aStart, aEnd, t);
      let env = sin(t * 180);
      let wave = sin(t * 360 * freq) * rimHalfW * 0.42 * ampScale * env;
      let wave2 = cos(t * 360 * freq - 45) * rimHalfW * 0.26 * ampScale * env;

      let p1 = trayPoint(a, 1, 1, rimMidRx + wave, rimMidRy + wave * 0.75);
      let p2 = trayPoint(a, 1, 1, rimMidRx + wave2, rimMidRy + wave2 * 0.75);

      let pr = 0.2 + 0.85 * pow(env, 0.7);
      mainPts.push([p1.x, p1.y, pr]);
      echoPts.push([p2.x, p2.y, pr * 0.7]);
    }

    // Shadow/burnished base under-stroke
    brush.set("pen", "#593e12", weightBase * 1.25);
    brush.spline(mainPts, 0.45);

    // Primary hairline gold pen tendril
    brush.set("rotring", goldCol, weightBase);
    brush.spline(mainPts, 0.45);

    // Intertwining secondary hairline tendril
    brush.set("rotring", "#9c752b", weightBase * 0.72);
    brush.spline(echoPts, 0.45);

    // Bright burnished gold specular glint along the middle of the tendril
    let midSlice = mainPts.slice(floor(steps * 0.22), floor(steps * 0.78));
    if (midSlice.length > 3) {
      brush.set("rotring", hiCol, weightBase * 0.65);
      brush.spline(midSlice, 0.45);
    }

    // Delicate curling lateral offshoots (vine curls & gold buds)
    let branchCount = 5;
    for (let b = 1; b < branchCount; b++) {
      let bt = b / branchCount + random(-0.04, 0.04);
      let ba = lerp(aStart, aEnd, bt);
      let dir = b % 2 === 0 ? 1 : -1;
      let curlPts = [];
      for (let k = 0; k <= 10; k++) {
        let kt = k / 10;
        let ca = ba + kt * 7.5 * (aEnd > aStart ? 1 : -1);
        let cOff =
          sin(bt * 360 * freq) * rimHalfW * 0.42 * ampScale * sin(bt * 180) +
          dir * pow(kt, 1.3) * rimHalfW * 0.52 +
          sin(kt * 240) * 3.5 * dir;
        let cp = trayPoint(ca, 1, 1, rimMidRx + cOff, rimMidRy + cOff * 0.75);
        curlPts.push([cp.x, cp.y, (1 - kt * 0.85) * 0.75]);
      }
      brush.set("rotring", goldCol, weightBase * 0.7);
      brush.spline(curlPts, 0.5);

      // Tiny burnished gold terminal bud at end of offshoot
      let tip = curlPts[curlPts.length - 1];
      brush.set("rotring", hiCol, weightBase * 0.9);
      brush.circle(tip[0], tip[1], 1.6, 0.15);
    }
  }

  // Upper-left to top-right ceremonial rim tendril
  drawTendrilSpan(-162, -28, 2.5, 0.95, "#c99e44", "#f5d782", 0.52);
  // Subtle continuation along upper-right rim
  drawTendrilSpan(-22, 32, 1.5, 0.75, "#9e782c", "#d9b155", 0.42);
  // Lower-right to bottom-left ceremonial rim tendril
  drawTendrilSpan(24, 152, 2.5, 0.95, "#c4983f", "#f2d279", 0.5);
  // Fine outer rim double-hairline accent in antique gold
  brush.set("rotring", "#7a5b20", 0.34);
  drawTrayArc(-155, -35, TRAY.rx - 4, TRAY.ry - 3, 50);
  drawTrayArc(30, 145, TRAY.rx - 4, TRAY.ry - 3, 50);
}

// ============================================================================
// 5. MIRROR REFLECTION & CONTACT SHADOW IN THE BLACK LACQUER TRAY
// ============================================================================
function drawAubergineLacquerReflection() {
  // Contact line is along the bottom contour of the aubergine (theta = +90)
  // In the polished black lacquer tray directly below (y > bottom contour),
  // we see a dark, sleek reflection of the aubergine's belly, its persimmon rim glow,
  // and a ghost of the window highlight, topped by a razor-sharp contact shadow.

  brush.noStroke();

  // Soft dark reflection silhouette on the lacquer floor
  let reflPts = [];
  for (let i = 0; i <= 32; i++) {
    let u = i / 32;
    let bot = aubergineSurface(u, 88);
    reflPts.push([bot.x, bot.y - 2]);
  }
  for (let i = 32; i >= 0; i--) {
    let u = i / 32;
    let bot = aubergineSurface(u, 88);
    let top = aubergineSurface(u, 10);
    let depth = (bot.y - top.y) * 0.58 * sin(u * 180);
    reflPts.push([bot.x - 10 * sin(u * 180), bot.y + depth]);
  }

  // Dark purple-black lacquer mirror wash
  brush.wash("#050208", 215);
  brush.beginShape(0.3);
  for (let p of reflPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Reflected warm persimmon belly glow & deep plum sheen in the lacquer
  for (let row = 0; row < 26; row++) {
    let rt = row / 25;
    let thetaRefl = lerp(85, 18, rt);
    let pts = [];
    for (let j = 0; j <= 34; j++) {
      let u = 0.08 + (j / 34) * 0.88;
      let bot = aubergineSurface(u, 88);
      let s = aubergineSurface(u, thetaRefl);
      let dy = bot.y - s.y;
      let rx = s.x - dy * 0.12;
      let ry = bot.y + dy * 0.56;
      pts.push([rx, ry, sin((j / 34) * 180) * (1 - rt * 0.65)]);
    }

    let col;
    if (rt < 0.22) {
      col = "#040106";
    } else if (rt < 0.52) {
      col = lerpColor(color("#24091e"), color("#541918"), (rt - 0.22) / 0.3);
    } else if (rt < 0.78) {
      col = lerpColor(color("#541918"), color("#2b0b29"), (rt - 0.52) / 0.26);
    } else {
      col = "#0c0512";
    }
    brush.set("glaze", col, 1.15 * (1 - rt * 0.4));
    brush.spline(pts, 0.4);
  }

  // Faint ghost of the liquid window reflection mirrored in the black lacquer below
  for (let k = 0; k < 7; k++) {
    let kt = k / 6;
    let uStart = 0.26 + kt * 0.04;
    let uEnd = 0.68 - kt * 0.03;
    let pts = [];
    for (let j = 0; j <= 20; j++) {
      let u = lerp(uStart, uEnd, j / 20);
      let bot = aubergineSurface(u, 88);
      let depth = (28 + kt * 22) * sin(u * 180);
      pts.push([bot.x - 6, bot.y + depth, sin((j / 20) * 180) * 0.65]);
    }
    let ghostCol = lerpColor(color("#4a1c17"), color("#7a3320"), 1 - abs(kt - 0.5) * 2);
    brush.set("glaze", ghostCol, 0.75);
    brush.spline(pts, 0.45);
  }

  // Abyssal occlusion contact shadow right beneath the aubergine belly
  for (let pass = 0; pass < 8; pass++) {
    let offY = pass * 2.4;
    let spreadU = 0.02 * pass;
    let pts = [];
    for (let j = 0; j <= 36; j++) {
      let u = constrain(0.06 - spreadU + (j / 36) * (0.9 + spreadU), 0.02, 0.98);
      let bot = aubergineSurface(u, 89);
      let env = sin(((u - 0.02) / 0.96) * 180);
      pts.push([bot.x - pass * 0.8, bot.y + offY * env, 0.3 + 0.7 * env]);
    }
    brush.set(pass < 4 ? "charcoal" : "2B", "#020103", 1.8 - pass * 0.16);
    brush.spline(pts, 0.4);
  }

  // Stem & calyx cast shadow on the lacquer tray to the lower-left
  brush.noStroke();
  brush.wash("#030205", 175);
  brush.beginShape(0.4);
  brush.vertex(235, 430);
  brush.vertex(350, 485);
  brush.vertex(395, 555);
  brush.vertex(310, 575);
  brush.vertex(225, 495);
  brush.endShape(true);
  brush.noWash();
}

// ============================================================================
// 6. THE AUBERGINE BODY — LAYERED GLAZES & 3D CONTOUR SKIN RENDERING
// ============================================================================
function drawAubergineBody() {
  brush.noStroke();

  // 6A. Solid opaque foundation silhouette in deepest lamp-black / aubergine-black
  let silPts = [];
  let steps = 50;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let p = aubergineSurface(u, -90);
    silPts.push([p.x, p.y]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = i / steps;
    let p = aubergineSurface(u, 90);
    silPts.push([p.x, p.y]);
  }

  brush.wash("#07020a", 255);
  brush.beginShape(0.25);
  for (let p of silPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // 6B. Deep watercolor & glaze tonal zones inside the aubergine
  // Upper-mid royal aubergine purple-black zone
  brush.fill("#280833", 135);
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.25, 0.15);
  drawAuberginePatch(0.06, 0.94, -75, 25);

  // Luminous plum-magenta transition under the window reflection
  brush.fill("#4a0f4d", 115);
  brush.fillBleed(0.12, "in");
  drawAuberginePatch(0.14, 0.86, -55, 8);

  // Warm crimson-persimmon subsurface belly bounce zone
  brush.fill("#631824", 110);
  brush.fillBleed(0.15, "in");
  drawAuberginePatch(0.18, 0.92, 18, 78);

  // Deepest lamp-black core shadow band running through the equator
  brush.fill("#060109", 160);
  brush.fillBleed(0.15, "in");
  drawAuberginePatch(0.05, 0.92, -8, 42);
  brush.noFill();

  // 6C. Dense Longitudinal 3D Skin Glazes & Micro-Splines
  // Follow the exact 3D flow from neck (u=0) to blossom tip (u=1) across 95 latitude bands
  let latBands = 95;
  for (let b = 0; b <= latBands; b++) {
    let theta = map(b, 0, latBands, -89, 89);

    // Subdivide each longitudinal ribbon into overlapping segments so color adapts continuously
    let numSegs = 7;
    for (let s = 0; s < numSegs; s++) {
      let u0 = constrain((s - 0.15) / numSegs, 0.01, 0.995);
      let u1 = constrain((s + 1.15) / numSegs, 0.01, 0.995);
      let uMid = (u0 + u1) * 0.5;

      let opt = evaluateSkinOptics(uMid, theta);
      let col = computeBaseSkinColor(opt, uMid, theta);

      let pts = [];
      let segSteps = 8;
      for (let k = 0; k <= segSteps; k++) {
        let u = lerp(u0, u1, k / segSteps);
        let surf = aubergineSurface(u, theta);
        let pr = sin((k / segSteps) * 180);
        pts.push([surf.x, surf.y, 0.25 + 0.75 * pr]);
      }

      // Alternate between soft glaze brush and fine colored pencil for taut, hyperreal skin
      if (b % 2 === 0) {
        brush.set("glaze", col, 0.95);
        brush.spline(pts, 0.45);
      }
      brush.set("cpencil", col, 0.65);
      brush.spline(pts, 0.45);
    }
  }

  // 6D. Cross-Contour Curvature Splines (wrapping around theta from -88 to +88)
  // Gives the skin unmistakable 3D cylindrical/ellipsoidal volume and liquid tension
  let crossRings = 56;
  for (let r = 1; r < crossRings; r++) {
    let u = map(r, 0, crossRings, 0.03, 0.97);
    let numArcs = 5;
    for (let a = 0; a < numArcs; a++) {
      let th0 = map(a - 0.15, 0, numArcs, -86, 86);
      let th1 = map(a + 1.15, 0, numArcs, -86, 86);
      let thMid = (th0 + th1) * 0.5;

      let opt = evaluateSkinOptics(u, thMid);
      let col = computeBaseSkinColor(opt, u, thMid);

      let pts = [];
      for (let k = 0; k <= 7; k++) {
        let th = lerp(th0, th1, k / 7);
        let surf = aubergineSurface(u, th);
        let pr = sin((k / 7) * 180);
        pts.push([surf.x, surf.y, 0.2 + 0.65 * pr]);
      }
      brush.set("2B", col, 0.48);
      brush.spline(pts, 0.45);
    }
  }

  // 6E. Subtle blossom-end scar (pistil point) at u = 0.995
  let apex = aubergineSurface(0.992, 5);
  brush.set("charcoal", "#120714", 0.9);
  brush.circle(apex.x - 3, apex.y + 1, 6, 0.3);
  brush.set("rotring", "#6e4e32", 0.45);
  brush.circle(apex.x - 3, apex.y + 1, 3.5, 0.35);
  brush.set("cpencil", "#b87348", 0.4);
  brush.arc(apex.x - 3, apex.y + 1, 4.5, -60, 110);
}

function drawAuberginePatch(uMin, uMax, thMin, thMax) {
  brush.beginShape(0.35);
  let steps = 18;
  for (let i = 0; i <= steps; i++) {
    let u = lerp(uMin, uMax, i / steps);
    let p = aubergineSurface(u, thMin);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(uMin, uMax, i / steps);
    let p = aubergineSurface(u, thMax);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

function computeBaseSkinColor(opt, u, theta) {
  // Base palette anchors
  let cAbyss = color("#060209");
  let cDeepPurple = color("#190521");
  let cRoyalPlum = color("#380b47");
  let cBrightPlum = color("#5e166e");
  let cCrimsonPlum = color("#6e1834");
  let cPersimmon = color("#d64b24");
  let cWarmGold = color("#f08543");

  // Start with core shadow to diffuse royal aubergine transition
  let d = opt.diffuse;
  let col;
  if (d < 0.35) {
    col = lerpColor(cAbyss, cDeepPurple, d / 0.35);
  } else if (d < 0.68) {
    col = lerpColor(cDeepPurple, cRoyalPlum, (d - 0.35) / 0.33);
  } else {
    col = lerpColor(cRoyalPlum, cBrightPlum, (d - 0.68) / 0.32);
  }

  // Deepen core shadow band (theta around 0..32) for high-contrast heirloom drama
  if (theta > -12 && theta < 36) {
    let core = sin(((theta + 12) / 48) * 180);
    col = lerpColor(col, cAbyss, core * 0.65);
  }

  // Add warm persimmon halo around the liquid window reflection
  if (opt.windowHalo > 0.01) {
    let haloCol = lerpColor(cCrimsonPlum, cPersimmon, pow(opt.windowHalo, 0.85));
    col = lerpColor(col, haloCol, opt.windowHalo * 0.78);
  }

  // Add lower-right & belly persimmon bounce highlight
  if (opt.persimmonRim > 0.01) {
    let rimCol = lerpColor(cCrimsonPlum, cPersimmon, opt.persimmonRim);
    if (opt.persimmonRim > 0.55) {
      rimCol = lerpColor(cPersimmon, cWarmGold, (opt.persimmonRim - 0.55) / 0.45);
    }
    col = lerpColor(col, rimCol, constrain(opt.persimmonRim * 1.15, 0, 0.92));
  }

  // Add upper grazing plum/persimmon rim light
  if (opt.topRim > 0.01) {
    let topCol = lerpColor(cBrightPlum, cPersimmon, opt.topRim * 0.7);
    col = lerpColor(col, topCol, opt.topRim * 0.75);
  }

  // Darken extreme silhouette edge (theta > 82 or theta < -84) for crisp integration
  let edgeDist = min(90 - abs(theta), 10) / 10;
  if (edgeDist < 0.6) {
    col = lerpColor(cAbyss, col, edgeDist / 0.6);
  }

  return col;
}

// ============================================================================
// 7. LIQUID WINDOW REFLECTIONS & PERSIMMON SPECULARS
// ============================================================================
function drawLiquidWindowReflections() {
  // We sample the aubergine surface on a fine grid in (u, theta) and trace continuous
  // liquid contour splines through the warped studio window panes, neck streamer,
  // dome reflection, and razor-sharp persimmon rim highlights.

  // 7A. Soft glowing persimmon & plum under-glaze beneath the window panes
  for (let b = 0; b <= 52; b++) {
    let theta = map(b, 0, 52, -74, 14);
    let currentRun = [];

    for (let i = 0; i <= 90; i++) {
      let u = map(i, 0, 90, 0.08, 0.92);
      let opt = evaluateSkinOptics(u, theta);
      let intensity = max(opt.windowPane, opt.windowHalo * 0.55, opt.neckStream, opt.domeRefl);

      if (intensity > 0.14) {
        currentRun.push({
          x: opt.surf.x,
          y: opt.surf.y,
          val: intensity,
          pane: opt.windowPane,
          u: u,
          theta: theta
        });
      } else {
        if (currentRun.length >= 3) {
          renderReflectionRibbon(currentRun);
        }
        currentRun = [];
      }
    }
    if (currentRun.length >= 3) {
      renderReflectionRibbon(currentRun);
    }
  }

  // 7B. Cross-contour liquid reflection strokes (warping vertically across the window panes)
  for (let k = 0; k <= 64; k++) {
    let u = map(k, 0, 64, 0.1, 0.9);
    let currentRun = [];

    for (let j = 0; j <= 55; j++) {
      let theta = map(j, 0, 55, -72, 12);
      let opt = evaluateSkinOptics(u, theta);
      let intensity = max(opt.windowPane, opt.neckStream * 0.9, opt.domeRefl * 0.9);

      if (intensity > 0.22) {
        currentRun.push({
          x: opt.surf.x,
          y: opt.surf.y,
          val: intensity,
          pane: opt.windowPane,
          u: u,
          theta: theta
        });
      } else {
        if (currentRun.length >= 3) {
          renderCrossReflectionRibbon(currentRun);
        }
        currentRun = [];
      }
    }
    if (currentRun.length >= 3) {
      renderCrossReflectionRibbon(currentRun);
    }
  }

  // 7C. Incandescent Persimmon-Ivory Specular Core & Liquid Edge Ripples
  // Trace high-precision pen & colored-pencil highlights inside the brightest panes
  for (let b = 0; b <= 70; b++) {
    let theta = map(b, 0, 70, -66, 4);
    let coreRun = [];

    for (let i = 0; i <= 110; i++) {
      let u = map(i, 0, 110, 0.12, 0.88);
      let opt = evaluateSkinOptics(u, theta);
      let spec = max(opt.windowPane, opt.neckStream * 1.05, opt.domeRefl * 0.95);

      if (spec > 0.52) {
        coreRun.push({
          x: opt.surf.x,
          y: opt.surf.y,
          spec: spec,
          u: u,
          theta: theta
        });
      } else {
        if (coreRun.length >= 3) {
          drawCrispSpecularCore(coreRun);
        }
        coreRun = [];
      }
    }
    if (coreRun.length >= 3) {
      drawCrispSpecularCore(coreRun);
    }
  }

  // 7D. Glowing Persimmon Rim Highlight along the lower-right belly & blossom curve
  for (let r = 0; r < 14; r++) {
    let theta = map(r, 0, 13, 38, 74);
    let pts = [];
    for (let i = 0; i <= 45; i++) {
      let u = map(i, 0, 45, 0.22, 0.94);
      let opt = evaluateSkinOptics(u, theta);
      if (opt.persimmonRim > 0.25) {
        pts.push([opt.surf.x, opt.surf.y, opt.persimmonRim]);
      }
    }
    if (pts.length > 4) {
      let tMid = 1 - abs(r - 6.5) / 7;
      let col = lerpColor(color("#9e2916"), color("#f78c48"), pow(tMid, 1.3));
      brush.set("cpencil", col, 0.55 + 0.35 * tMid);
      brush.spline(pts, 0.45);
      if (tMid > 0.72) {
        brush.set("rotring", "#ffba82", 0.38);
        brush.spline(pts.slice(8, pts.length - 6), 0.45);
      }
    }
  }

  // 7E. Crisp dark purple-black mullion shadow accents cutting across the liquid window
  // Reinforces the razor-sharp glass reflection quality
  for (let b = 0; b <= 36; b++) {
    let theta = map(b, 0, 36, -64, 2);
    for (let i = 1; i < 85; i++) {
      let u = map(i, 0, 85, 0.16, 0.84);
      let opt = evaluateSkinOptics(u, theta);
      if (opt.windowHalo > 0.45 && opt.windowPane < 0.12) {
        let pNext = aubergineSurface(u + 0.008, theta);
        brush.set("rotring", "#210626", 0.45);
        brush.line(opt.surf.x, opt.surf.y, pNext.x, pNext.y);
      }
    }
  }
}

function renderReflectionRibbon(run) {
  let avgVal = 0;
  let avgTheta = 0;
  for (let p of run) {
    avgVal += p.val;
    avgTheta += p.theta;
  }
  avgVal /= run.length;
  avgTheta /= run.length;

  // Color grades from deep persimmon-plum at halo to fiery persimmon to creamy peach-ivory
  let cPlumPersimmon = color("#801e29");
  let cFieryPersimmon = color("#de5326");
  let cLuminousPeach = color("#f79b5c");
  let cCreamIvory = color("#ffe8cf");

  let col;
  if (avgVal < 0.38) {
    col = lerpColor(cPlumPersimmon, cFieryPersimmon, (avgVal - 0.14) / 0.24);
  } else if (avgVal < 0.68) {
    col = lerpColor(cFieryPersimmon, cLuminousPeach, (avgVal - 0.38) / 0.3);
  } else {
    col = lerpColor(cLuminousPeach, cCreamIvory, constrain((avgVal - 0.68) / 0.3, 0, 1));
  }

  let pts = run.map((p, idx) => {
    let env = sin(((idx + 0.5) / run.length) * 180);
    return [p.x, p.y, 0.25 + 0.75 * env * p.val];
  });

  brush.set("glaze", col, 0.68);
  brush.spline(pts, 0.45);
  brush.set("cpencil", col, 0.58);
  brush.spline(pts, 0.45);
}

function renderCrossReflectionRibbon(run) {
  let avgVal = 0;
  for (let p of run) avgVal += p.val;
  avgVal /= run.length;

  let col = lerpColor(color("#c94320"), color("#ffdfc2"), constrain((avgVal - 0.22) / 0.7, 0, 1));
  let pts = run.map((p, idx) => {
    let env = sin(((idx + 0.5) / run.length) * 180);
    return [p.x, p.y, 0.2 + 0.65 * env];
  });

  brush.set("cpencil", col, 0.45);
  brush.spline(pts, 0.45);
}

function drawCrispSpecularCore(run) {
  let maxSpec = 0;
  for (let p of run) maxSpec = max(maxSpec, p.spec);

  let col = lerpColor(color("#ffa666"), color("#fff6eb"), constrain((maxSpec - 0.52) / 0.42, 0, 1));
  let pts = run.map((p, idx) => {
    let env = sin(((idx + 0.5) / run.length) * 180);
    return [p.x, p.y, 0.3 + 0.7 * env];
  });

  brush.set("rotring", col, 0.52);
  brush.spline(pts, 0.45);
}

// ============================================================================
// 8. THE FUZZY, EXACT GREEN CALYX & CURVED WOODY STEM
// ============================================================================
function drawFuzzyGreenCalyx() {
  // The calyx clasps the neck around u = 0 (372, 478) with 5 distinct pointed sepals
  // reaching onto the glossy purple neck up to u ~ 0.17, and a curved woody stem
  // extending from (362, 475) up-left to the cut peduncle face at (238, 382).

  // Define the 5 exact botanical sepals (in back-to-front draw order)
  let sepals = [
    // 1. Dorsal (top-edge) sepal wrapping over the upper neck contour
    {
      baseTh: -76,
      tipU: 0.135,
      tipTh: -80,
      widthTh: 26,
      lightBias: 0.85,
      curlX: -4,
      curlY: -7
    },
    // 2. Ventral (bottom-edge) sepal cupping the underside of the neck
    {
      baseTh: 72,
      tipU: 0.125,
      tipTh: 76,
      widthTh: 28,
      lightBias: 0.22,
      curlX: -5,
      curlY: 6
    },
    // 3. Lower-front sepal curving across the lower neck
    {
      baseTh: 34,
      tipU: 0.165,
      tipTh: 38,
      widthTh: 32,
      lightBias: 0.42,
      curlX: 6,
      curlY: 5
    },
    // 4. Upper-front sepal reaching across the liquid neck highlight
    {
      baseTh: -38,
      tipU: 0.175,
      tipTh: -32,
      widthTh: 34,
      lightBias: 0.92,
      curlX: 8,
      curlY: -4
    },
    // 5. Central prominent sepal with strong raised midrib
    {
      baseTh: -4,
      tipU: 0.195,
      tipTh: 2,
      widthTh: 36,
      lightBias: 0.68,
      curlX: 10,
      curlY: 2
    }
  ];

  // 8A. Crisp dark cast shadows of the sepals onto the glossy aubergine neck
  for (let sep of sepals) {
    drawSepalShadow(sep);
  }

  // 8B. Render the curved woody stem (peduncle) first so the calyx crown clasps over it
  drawCurvedStem();

  // 8C. Render the central calyx cup/crown where sepals fuse
  drawCalyxCrown();

  // 8D. Render each of the 5 sculptural sepals with exact venation, russet edges, and velvety fuzz
  for (let sep of sepals) {
    drawExactSepal(sep);
  }

  // 8E. Render the cut elliptical stem face at (238, 382)
  drawStemCutFace();
}

function getSepalGeometry(sep, s, t) {
  // s in [0, 1] from calyx base (u ~ -0.01) to pointed sepal tip (u = sep.tipU)
  // t in [-1, 1] across sepal width (-1 = upper margin, 0 = midrib, +1 = lower margin)
  let u = lerp(-0.015, sep.tipU, s);
  let widthProfile = sin(pow(s, 0.65) * 180) * (1 - 0.25 * s * s);
  if (s < 0.25) widthProfile = lerp(0.72, widthProfile, s / 0.25);

  let thCenter = lerp(sep.baseTh, sep.tipTh, s);
  let th = thCenter + t * sep.widthTh * widthProfile;

  let surf = aubergineSurface(max(0, u), constrain(th, -90, 90));
  // Sepal thickness lifts slightly off the aubergine skin, especially at midrib and curled tip
  let midRibLift = (1 - abs(t)) * 3.5 * sin(s * 180);
  let tipCurlX = pow(s, 2.6) * sep.curlX;
  let tipCurlY = pow(s, 2.6) * sep.curlY;

  let backwardShift = u < 0 ? u * 480 : 0;

  return {
    x: surf.x + backwardShift * surf.tx + surf.Nx * midRibLift + tipCurlX,
    y: surf.y + backwardShift * surf.ty + surf.Ny * midRibLift + tipCurlY
  };
}

function drawSepalShadow(sep) {
  brush.noStroke();
  brush.wash("#030105", 195);
  brush.beginShape(0.35);
  let steps = 14;
  for (let i = 0; i <= steps; i++) {
    let s = i / steps;
    let p = getSepalGeometry(sep, s, -1.05);
    brush.vertex(p.x + 5 * s, p.y + 7 * s);
  }
  for (let i = steps; i >= 0; i--) {
    let s = i / steps;
    let p = getSepalGeometry(sep, s, 1.05);
    brush.vertex(p.x + 6 * s, p.y + 9 * s);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawCurvedStem() {
  // Stem spine from s=0 (cut end at 238, 382) to s=1 (calyx crown at 364, 476)
  function stemPoint(s, rNorm) {
    // Centerline curves gracefully
    let cx = lerp(238, 364, s) + 12 * sin(s * 180);
    let cy = lerp(382, 476, s) + 18 * sin(s * 180);

    // Stem radius flares out as it enters the calyx crown
    let rad = lerp(19, 34, pow(s, 1.4));
    // Perpendicular vector to stem spine
    let ang = atan2(476 - 382 + 18 * PI * cos(s * 180) * (PI / 180), 364 - 238);
    let nx = -sin(ang);
    let ny = cos(ang);

    return {
      x: cx + nx * rad * rNorm,
      y: cy + ny * rad * rNorm,
      nx,
      ny
    };
  }

  // Opaque dark olive-charcoal stem base
  brush.noStroke();
  brush.wash("#121a0d", 250);
  brush.beginShape(0.3);
  for (let i = 0; i <= 20; i++) {
    let p = stemPoint(i / 20, -1);
    brush.vertex(p.x, p.y);
  }
  for (let i = 20; i >= 0; i--) {
    let p = stemPoint(i / 20, 1);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Longitudinal woody ridges & 3D cylindrical shading along the stem
  let ridges = 34;
  for (let r = 0; r <= ridges; r++) {
    let rNorm = map(r, 0, ridges, -0.98, 0.98);
    let pts = [];
    for (let i = 0; i <= 18; i++) {
      let s = i / 18;
      let ribWave = 0.04 * sin(r * 45 + s * 120);
      let p = stemPoint(s, rNorm + ribWave);
      pts.push([p.x, p.y, 0.35 + 0.65 * sin(s * 180)]);
    }

    // Lighting across stem cylinder (-1 is lit upper-right ridge, +1 is dark underside)
    let light = constrain(1 - (rNorm + 0.45) * 0.85, 0, 1);
    let ribMod = 0.12 * cos(r * 55);
    let lVal = constrain(light + ribMod, 0, 1);

    let cShadow = color("#131c0e");
    let cDeepGreen = color("#283b1e");
    let cSageGreen = color("#4d693a");
    let cCeladon = color("#8ca86f");
    let cFrost = color("#c5d9a9");

    let col;
    if (lVal < 0.3) col = lerpColor(cShadow, cDeepGreen, lVal / 0.3);
    else if (lVal < 0.65) col = lerpColor(cDeepGreen, cSageGreen, (lVal - 0.3) / 0.35);
    else if (lVal < 0.88) col = lerpColor(cSageGreen, cCeladon, (lVal - 0.65) / 0.23);
    else col = lerpColor(cCeladon, cFrost, (lVal - 0.88) / 0.12);

    brush.set(r % 2 === 0 ? "cpencil" : "2B", col, 0.68);
    brush.spline(pts, 0.45);
  }

  // Velvety trichome fuzz along the stem surface and especially along its silhouette edges
  for (let i = 0; i < 240; i++) {
    let s = random(0.04, 0.96);
    // Bias toward the edges (-1 and +1) so the silhouette is visibly fuzzy
    let edgeBias = random() < 0.55 ? (random() < 0.65 ? random(-1.04, -0.72) : random(0.72, 1.04)) : random(-0.85, 0.85);
    let p = stemPoint(s, edgeBias);

    let hairLen = random(4.5, 10.5);
    let outDir = edgeBias < 0 ? -1 : 1;
    let hx = p.x + p.nx * outDir * hairLen * random(0.6, 1.1) + random(-3, 3);
    let hy = p.y + p.ny * outDir * hairLen * random(0.6, 1.1) + random(-3, 3);

    let isLit = edgeBias < 0.2;
    let hCol = isLit
      ? random(["#9ab57c", "#bdd4a1", "#dcebd0", "#76915b"])
      : random(["#2d3d22", "#475e37", "#6b5331"]);

    brush.set("fuzz", hCol, random(0.42, 0.85));
    brush.line(p.x, p.y, hx, hy);
  }
}

function drawCalyxCrown() {
  // Swollen base where the 5 sepals fuse around u = 0
  for (let pass = 0; pass < 28; pass++) {
    let t = pass / 27;
    let u = lerp(-0.025, 0.045, t);
    let pts = [];
    for (let k = 0; k <= 20; k++) {
      let th = map(k, 0, 20, -86, 86);
      let s = aubergineSurface(max(0, u), th);
      let back = u < 0 ? u * 450 : 0;
      let swell = 5 * sin(t * 180);
      pts.push([
        s.x + back * s.tx + s.Nx * swell,
        s.y + back * s.ty + s.Ny * swell,
        0.3 + 0.7 * sin((k / 20) * 180)
      ]);
    }
    let col = lerpColor(color("#1d2b15"), color("#4b6638"), sin(t * 180));
    brush.set("cpencil", col, 0.75);
    brush.spline(pts, 0.45);
  }
}

function drawExactSepal(sep) {
  // 1. Solid opaque sepal base
  brush.noStroke();
  brush.wash("#182412", 250);
  brush.beginShape(0.35);
  let steps = 16;
  for (let i = 0; i <= steps; i++) {
    let p = getSepalGeometry(sep, i / steps, -1);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    let p = getSepalGeometry(sep, i / steps, 1);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Longitudinal botanical shading ribs from base to pointed tip
  let ribs = 22;
  for (let r = 0; r <= ribs; r++) {
    let t = map(r, 0, ribs, -0.96, 0.96);
    let pts = [];
    for (let i = 0; i <= 14; i++) {
      let s = i / 14;
      let p = getSepalGeometry(sep, s, t);
      pts.push([p.x, p.y, 0.25 + 0.75 * sin(s * 180)]);
    }

    // Compute exact 3D botanical coloration across the sepal:
    // - Raised central midrib (|t| < 0.18) catches bright celadon light
    // - Upper half (t < 0) is better lit than lower half (t > 0)
    // - Outer margins (|t| > 0.82) and tip have warm russet/gold dried heirloom edges
    let midRib = exp(-pow(t / 0.2, 2));
    let sideLight = constrain(sep.lightBias * (0.65 - 0.35 * t) + 0.35 * midRib, 0, 1);

    let cDarkOlive = color("#162110");
    let cForest = color("#2d4222");
    let cSage = color("#526e3e");
    let cCeladon = color("#8aa66c");
    let cPaleSage = color("#c2d9a7");
    let cRussetEdge = color("#7d5a2d");

    let col;
    if (sideLight < 0.35) col = lerpColor(cDarkOlive, cForest, sideLight / 0.35);
    else if (sideLight < 0.68) col = lerpColor(cForest, cSage, (sideLight - 0.35) / 0.33);
    else if (sideLight < 0.88) col = lerpColor(cSage, cCeladon, (sideLight - 0.68) / 0.2);
    else col = lerpColor(cCeladon, cPaleSage, (sideLight - 0.88) / 0.12);

    if (abs(t) > 0.82) {
      col = lerpColor(col, cRussetEdge, (abs(t) - 0.82) / 0.18);
    }

    brush.set(abs(t) < 0.15 ? "rotring" : "cpencil", col, abs(t) < 0.15 ? 0.58 : 0.65);
    brush.spline(pts, 0.42);
  }

  // 3. Exact lateral veins branching off the central midrib (herringbone venation)
  for (let v = 1; v <= 6; v++) {
    let sStart = v * 0.13;
    let sEnd = min(0.96, sStart + 0.18);
    for (let dir of [-1, 1]) {
      let vPts = [];
      for (let k = 0; k <= 6; k++) {
        let kt = k / 6;
        let p = getSepalGeometry(sep, lerp(sStart, sEnd, kt), dir * pow(kt, 0.85) * 0.92);
        vPts.push([p.x, p.y, (1 - kt * 0.6) * 0.7]);
      }
      let veinCol = dir < 0 ? "#9bb57e" : "#25361c";
      brush.set("rotring", veinCol, 0.38);
      brush.spline(vPts, 0.35);
    }
  }

  // 4. Warm russet-gold dried margin & sharp sepal tip detail
  for (let side of [-0.98, 0.98]) {
    let edgePts = [];
    for (let i = 3; i <= 14; i++) {
      let s = i / 14;
      let p = getSepalGeometry(sep, s, side);
      edgePts.push([p.x, p.y, sin(s * 180) * 0.8]);
    }
    brush.set("rotring", side < 0 ? "#9e773e" : "#593e1c", 0.42);
    brush.spline(edgePts, 0.4);
  }

  // 5. Dense, exact velvety micro-fuzz (stellate trichomes) across the sepal and along its rim
  let numHairs = 135;
  for (let h = 0; h < numHairs; h++) {
    let s = random(0.02, 0.96);
    // Concentrate hairs along the outer margins and midrib so the fuzziness reads with hyperreal clarity
    let t = random() < 0.52 ? (random() < 0.55 ? random(-1.02, -0.75) : random(0.75, 1.02)) : random(-0.85, 0.85);
    let p0 = getSepalGeometry(sep, s, t);
    let p1 = getSepalGeometry(sep, min(1, s + 0.045), t + (t < 0 ? -0.18 : 0.18));

    let dx = p1.x - p0.x;
    let dy = p1.y - p0.y;
    let dLen = sqrt(dx * dx + dy * dy) || 1;
    let hLen = random(3.8, 8.5) * (1 - 0.35 * s);

    let hx = p0.x + (dx / dLen) * hLen + random(-1.8, 1.8);
    let hy = p0.y + (dy / dLen) * hLen + random(-1.8, 1.8);

    let isBright = t < 0.15 && sep.lightBias > 0.4;
    let hCol = isBright
      ? random(["#a7c288", "#cbe0b1", "#e4f2d5", "#86a168"])
      : random(["#3b522c", "#597344", "#7a9460", "#8c6d3e"]);

    brush.set("fuzz", hCol, random(0.38, 0.78));
    brush.line(p0.x, p0.y, hx, hy);
  }
}

function drawStemCutFace() {
  // Cut elliptical stem end at (238, 382), tilted perpendicular to the stem
  let cx = 238;
  let cy = 382;
  let rx = 10.5;
  let ry = 19.5;
  let tilt = 34;

  function cutPt(aDeg, rScale) {
    let lx = cos(aDeg) * rx * rScale;
    let ly = sin(aDeg) * ry * rScale;
    let c = cos(tilt);
    let s = sin(tilt);
    return {
      x: cx + lx * c - ly * s,
      y: cy + lx * s + ly * c
    };
  }

  // Outer green rind ring
  brush.noStroke();
  brush.wash("#3e542c", 250);
  brush.beginShape(0.3);
  for (let i = 0; i < 20; i++) {
    let p = cutPt((i / 20) * 360, 1.05);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);

  // Inner woody pith / cortex in warm parchment-olive
  brush.wash("#9e9665", 245);
  brush.beginShape(0.3);
  for (let i = 0; i < 20; i++) {
    let p = cutPt((i / 20) * 360, 0.84);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Concentric vascular rings and radial pith rays
  for (let r = 0.2; r <= 0.95; r += 0.18) {
    let pts = [];
    for (let i = 0; i <= 20; i++) {
      let p = cutPt((i / 20) * 360, r);
      pts.push([p.x, p.y, 0.6]);
    }
    let col = r > 0.8 ? "#2b3d1d" : r > 0.5 ? "#7a7044" : "#c7bf8f";
    brush.set("rotring", col, 0.45);
    brush.spline(pts, 0.4);
  }

  // Radial shrinkage cracks / vascular rays from center of cut stem
  for (let i = 0; i < 18; i++) {
    let a = (i / 18) * 360 + random(-8, 8);
    let p0 = cutPt(a, 0.12);
    let p1 = cutPt(a, random(0.75, 0.92));
    brush.set("rotring", i % 2 === 0 ? "#574e2d" : "#d9d2a7", 0.36);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Fuzzy trichome halo around the cut stem rim
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * 360;
    let p0 = cutPt(a, 0.98);
    let p1 = cutPt(a, 1.28 + random(0.15));
    brush.set("fuzz", a > 160 && a < 340 ? "#c8deb0" : "#5e7548", 0.5);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
}

// Palette: Wet-Plate Collodion Tintype (Chocolate Black, Pewter, Creamy Silver + Subtle Oil/Collodion Accent)
const C_IRON         = "#0a0706"; // Bare blackened ferrotype iron plate
const C_CHOC_DEEP    = "#140e0c"; // Deepest chocolate-black shadow
const C_CHOC_DARK    = "#221814"; // Dark chocolate charcoal
const C_CHOC_MID     = "#33251f"; // Rich chocolate umber
const C_CHOC_WARM    = "#45332b"; // Warm dark bronze-chocolate
const C_PEWTER_DARK  = "#4f4843"; // Dark tarnished pewter
const C_PEWTER_MID   = "#6e665f"; // Mid metallic pewter
const C_PEWTER_LIGHT = "#8f877e"; // Polished pewter
const C_SILVER_DIM   = "#b0a79c"; // Muted collodion silver
const C_SILVER_CREAM = "#d2cabd"; // Warm creamy silver
const C_SILVER_BRIGHT= "#eae3d5"; // Bright silver-cream highlight
const C_SILVER_SPEC  = "#fbf8f1"; // Pure specular wet-plate silver gleam
const C_ACCENT_OIL   = "#6e4628"; // Single subtle warm oil / collodion chemical stain accent
const C_ACCENT_BRASS = "#966840"; // Subtle tarnished brass/amber glint

// Focal sweet spot center for the Petzval lens effect
const FOCAL_X = 575;
const FOCAL_Y = 555;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1937);
  noiseSeed(1937);

  // Custom vector field emulating a vintage Petzval brass lens swirling bokeh
  brush.addField("petzval", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    let cx = cols * (FOCAL_X / 1200);
    let cy = rows * (FOCAL_Y / 1200);
    for (let col = 0; col < cols; col++) {
      for (let row = 0; row < rows; row++) {
        let dx = col - cx;
        let dy = row - cy;
        let radAngle = Math.atan2(dy, dx) * (180 / Math.PI);
        let distNorm = Math.sqrt(dx * dx + dy * dy) / (cols * 0.5);
        let wobble = (noise(col * 0.1, row * 0.1) - 0.5) * 22;
        // Tangential swirl with slight inward vortex pull
        field[col][row] = radAngle + 94 - distNorm * 8 + wobble;
      }
    }
    return field;
  });

  // Custom vector field for collodion chemical pour & drain streaks (toward bottom-left drain corner)
  brush.addField("collodion_pour", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let col = 0; col < cols; col++) {
      for (let row = 0; row < rows; row++) {
        let n = noise(col * 0.06, row * 0.06);
        field[col][row] = 118 + (n - 0.5) * 28;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(C_CHOC_DEEP);

  // 1. Base Collodion Plate Ground & Atmospheric Washes (batched by color for performance)
  drawCollodionGround();

  // 2. Out-of-Focus Background Chassis & Petzval Swirling Bokeh Underlayer
  drawSwirlingBackground();

  // 3. Core Engine Shadow Masses (Dense Charcoal Massing)
  drawEngineShadowMasses();

  // 4. Cracked Vintage Leather Solo Seat & Coiled Springs (Top Left)
  drawCrackedLeatherSeat();

  // 5. Rear & Front V-Twin Cylinder Barrels (Hyperreal Stacked Cooling Fins)
  // Rear cylinder: tilted back (-21 deg), from crankcase (505, 745) up to head (370, 345)
  drawCylinderBarrel(505, 745, 370, 345, 14, 108, 128, -21, false);
  // Front cylinder: tilted forward (+24 deg), from crankcase (645, 735) up to head (805, 355)
  drawCylinderBarrel(645, 735, 805, 355, 14, 112, 134, 24, true);

  // 6. Cylinder Heads & Rocker Boxes (Knuckle/Pan Vintage Overhead Valve Assemblies)
  drawRockerBox(365, 320, -21, 1.0, false);
  drawRockerBox(812, 330, 24, 1.04, true);

  // 7. Crankcase, Timing Chest, Primary Cover & Oily Perimeter Hex Bolts
  drawCrankcaseAndTimingChest();

  // 8. Pushrod Tubes & Tappet Blocks (Gleaming Metallic Cylinders in the V)
  drawPushrodAssemblies();

  // 9. Central Induction: Cast Y-Manifold & Linkert-Style Brass/Pewter Carburetor
  drawCarburetorAndManifold();

  // 10. Sweeping Exhaust Header Pipes & Finned Port Clamps
  drawExhaustPipes();

  // 11. Spark Plugs, Braided Cloth Ignition Leads, Throttle & Oil Lines
  drawSparkPlugsAndBraidedCables();

  // 12. Sharp Peripheral Focus Falloff (Petzval Swirl Overlays)
  drawPeripheralFocusFalloff();

  // 13. Wet-Plate Tintype Border, Uneven Collodion Pour Marks, Comet Streaks & Emulsion Vignette
  drawWetPlateBorderAndArtifacts();

  noLoop();
}

// =============================================================================
// 1. BASE COLLODION PLATE GROUND
// =============================================================================
function drawCollodionGround() {
  brush.noStroke();

  // Mid-pewter central illumination on the wet plate
  brush.fill(C_PEWTER_MID, 95);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.35);
  brush.circle(FOCAL_X, FOCAL_Y - 20, 470, 0.25);

  // Lighter silver-pewter halo behind the V-twin center and upper cylinders
  brush.fill(C_SILVER_DIM, 80);
  brush.fillBleed(0.5, "out");
  brush.circle(570, 460, 320, 0.3);
  brush.circle(490, 380, 240, 0.3);
  brush.circle(690, 420, 230, 0.3);

  // Warm chemical stain undertones in the plate emulsion
  brush.fill(C_ACCENT_OIL, 38);
  brush.fillBleed(0.55, "out");
  brush.circle(620, 620, 360, 0.35);
  brush.circle(310, 260, 220, 0.4);

  // Deep chocolate-black outer darkening around the plate perimeter
  brush.fill(C_CHOC_DEEP, 170);
  brush.fillBleed(0.4, "in");
  brush.rect(0, 0, 1200, 140, "corner");
  brush.rect(0, 1060, 1200, 140, "corner");
  brush.rect(0, 0, 130, 1200, "corner");
  brush.rect(1070, 0, 130, 1200, "corner");

  brush.noFill();
}

// =============================================================================
// 2. SWIRLING PETZVAL BACKGROUND & OUT-OF-FOCUS CHASSIS
// =============================================================================
function drawSwirlingBackground() {
  brush.field("petzval");

  // Out-of-focus background motorcycle frame tubes (backbone, downtube, rearstays)
  // Drawn with soft charcoal & spray following the Petzval swirl field
  let bgStrokes = [
    { x: 450, y: 170, len: 380, dir: 15, c: C_CHOC_DARK, w: 3.2 },
    { x: 750, y: 190, len: 420, dir: 55, c: C_CHOC_DARK, w: 3.5 },
    { x: 920, y: 310, len: 480, dir: 82, c: C_CHOC_DEEP, w: 4.0 },
    { x: 960, y: 340, len: 450, dir: 85, c: C_PEWTER_DARK, w: 1.8 },
    { x: 180, y: 420, len: 440, dir: 250, c: C_CHOC_DEEP, w: 3.8 },
    { x: 210, y: 450, len: 400, dir: 245, c: C_PEWTER_DARK, w: 1.6 }
  ];
  for (let s of bgStrokes) {
    brush.set("charcoal", s.c, s.w);
    brush.flowLine(s.x, s.y, s.len, s.dir);
  }

  // Swirling cat's-eye Petzval bokeh rings in the mid-distance
  for (let i = 0; i < 180; i++) {
    let angle = random(360);
    let rad = random(320, 560);
    let px = FOCAL_X + cos(angle) * rad;
    let py = FOCAL_Y + sin(angle) * rad;

    let col = C_PEWTER_DARK;
    let rVal = random();
    if (rVal > 0.82) col = C_SILVER_CREAM;
    else if (rVal > 0.55) col = C_SILVER_DIM;
    else if (rVal > 0.3) col = C_PEWTER_MID;
    else col = C_CHOC_DARK;

    let weight = map(rad, 320, 560, 0.7, 2.4) * random(0.6, 1.3);
    let len = map(rad, 320, 560, 35, 130) * random(0.7, 1.3);

    brush.set("charcoal", col, weight);
    brush.flowLine(px, py, len, angle + 90);
  }

  // Specular cat's-eye bokeh highlights (characteristic of fast brass lenses)
  for (let i = 0; i < 55; i++) {
    let angle = random(360);
    let rad = random(340, 510);
    let px = FOCAL_X + cos(angle) * rad;
    let py = FOCAL_Y + sin(angle) * rad;
    // Avoid dark bottom corners
    if (py < 960 && px > 120 && px < 1080) {
      let tangent = angle + 90;
      brush.set("2B", C_SILVER_BRIGHT, random(0.8, 1.8));
      brush.arc(px, py, random(14, 34), tangent - 40, tangent + 40);
      brush.set("HB", C_PEWTER_LIGHT, random(0.5, 1.2));
      brush.arc(px, py, random(12, 30), tangent + 140, tangent + 220);
    }
  }

  brush.noField();
}

// =============================================================================
// 3. DENSE CHARCOAL SHADOW MASSES OF THE ENGINE
// =============================================================================
function drawEngineShadowMasses() {
  brush.noStroke();

  // Deep charcoal massing for the engine core shadows
  brush.mass("charcoal", C_CHOC_DEEP, {
    precision: 0.65,
    strength: 0.9,
    gradient: 0.25,
    outline: false
  });

  // Rear cylinder core mass
  drawQuadShape([
    [300, 340], [455, 290],
    [575, 725], [415, 770]
  ]);

  // Front cylinder core mass
  drawQuadShape([
    [720, 295], [885, 370],
    [715, 770], [565, 710]
  ]);

  // Crankcase & primary shadow mass
  drawQuadShape([
    [260, 740], [790, 710],
    [820, 1040], [230, 1050]
  ]);

  // Deep recess in the V between cylinders (behind carburetor & pushrods)
  brush.mass("charcoal", C_IRON, {
    precision: 0.8,
    strength: 0.95,
    gradient: 0.1,
    outline: false
  });
  drawQuadShape([
    [435, 355], [735, 365],
    [630, 735], [510, 735]
  ]);

  brush.noMass();
}

// =============================================================================
// 4. CRACKED LEATHER SEAT EDGE & COILED SPRINGS (TOP LEFT)
// =============================================================================
function drawCrackedLeatherSeat() {
  // Coiled saddle springs underneath the leather seat (receding into left blur)
  drawSeatSpring(235, 215, 265, 345, 26, 7);
  drawSeatSpring(305, 210, 330, 325, 22, 6);

  // Heavy forged steel seat post bracket under the nose of the saddle
  brush.set("charcoal", C_CHOC_DEEP, 2.2);
  brush.line(340, 210, 445, 275);
  brush.set("2B", C_PEWTER_MID, 1.2);
  brush.line(342, 206, 445, 270);
  drawOilyBolt(395, 240, 11, true, 18);

  // Main leather saddle body (curving from top-left down toward the center-left)
  let topCurve = [
    [70, 95], [165, 105], [275, 125], [385, 152], [475, 184], [515, 206]
  ];
  let midRidge = [
    [75, 138], [170, 148], [280, 166], [385, 188], [470, 212], [512, 224]
  ];
  let botSkirt = [
    [80, 215], [175, 218], [282, 222], [382, 230], [462, 236], [512, 224]
  ];

  // Solid base wash for leather saddle
  brush.noStroke();
  brush.wash(C_CHOC_DEEP, 245);
  brush.beginShape(0.2);
  for (let p of topCurve) brush.vertex(p[0], p[1]);
  for (let i = botSkirt.length - 1; i >= 0; i--) brush.vertex(botSkirt[i][0], botSkirt[i][1]);
  brush.endShape(true);
  brush.noWash();

  // Dense charcoal mass on the lower leather skirt
  brush.noStroke();
  brush.mass("charcoal", C_CHOC_DARK, { precision: 0.75, strength: 0.8, gradient: 0.4, outline: false });
  brush.beginShape(0.2);
  for (let p of midRidge) brush.vertex(p[0], p[1]);
  for (let i = botSkirt.length - 1; i >= 0; i--) brush.vertex(botSkirt[i][0], botSkirt[i][1]);
  brush.endShape(true);
  brush.noMass();

  // Buffed pewter and creamy-silver worn highlights along the leather crown & rolled edge
  for (let i = 0; i < 48; i++) {
    let t = i / 47;
    let x1 = bezierPoint(110, 220, 350, 505, t);
    let y1 = bezierPoint(128, 146, 175, 214, t);
    let x2 = x1 + random(-12, 12);
    let y2 = y1 + random(18, 48);

    // Focus falloff toward far left edge
    let distFocus = dist(x1, y1, FOCAL_X, FOCAL_Y);
    let col = (i % 3 === 0) ? C_SILVER_DIM : C_PEWTER_MID;
    if (distFocus > 430) col = C_PEWTER_DARK;

    brush.set("2H", col, random(0.4, 0.9));
    brush.line(x1, y1, x2, y2);
  }

  // Highlight along the rolled crown ridge
  brush.set("HB", C_PEWTER_LIGHT, 1.4);
  brush.spline(midRidge, 0.4);
  brush.set("2H", C_SILVER_CREAM, 0.8);
  brush.spline(midRidge.slice(1), 0.4);
  brush.set("rotring", C_SILVER_BRIGHT, 0.45);
  brush.spline(midRidge.slice(2), 0.4);

  // Bottom rolled edge of the leather skirt
  brush.set("charcoal", C_IRON, 1.8);
  brush.spline(botSkirt, 0.4);
  brush.set("HB", C_PEWTER_MID, 0.9);
  let botHighlight = botSkirt.map(p => [p[0], p[1] - 4]);
  brush.spline(botHighlight, 0.4);

  // Embossed border groove & hyperreal individual saddle stitches
  let stitchLine = botSkirt.map((p, idx) => [p[0], p[1] - 14 + idx * 1.2]);
  brush.set("rotring", C_IRON, 0.8);
  brush.spline(stitchLine, 0.4);

  for (let i = 3; i < 36; i++) {
    let t = i / 37;
    let sx = lerp(115, 498, t);
    let sy = lerp(200, 217, t) + sin(t * 180) * 3;
    // Awl hole shadow
    brush.set("rotring", C_IRON, 0.9);
    brush.line(sx - 4, sy - 1, sx + 4, sy + 2);
    // Cream linen thread stitch catching the light
    brush.set("rotring", C_SILVER_CREAM, 0.65);
    brush.line(sx - 3, sy - 2, sx + 3, sy + 1);
  }

  // Hyperreal network of deep age cracks in the leather surface
  let crackSeeds = [
    { x: 245, y: 156, len: 46, ang: 78 },
    { x: 268, y: 160, len: 52, ang: 102 },
    { x: 295, y: 165, len: 48, ang: 85 },
    { x: 322, y: 170, len: 55, ang: 72 },
    { x: 348, y: 176, len: 50, ang: 95 },
    { x: 372, y: 182, len: 46, ang: 80 },
    { x: 398, y: 188, len: 44, ang: 68 },
    { x: 422, y: 194, len: 40, ang: 88 },
    { x: 448, y: 200, len: 34, ang: 76 },
    { x: 472, y: 207, len: 26, ang: 82 }
  ];

  for (let c of crackSeeds) {
    let pts = [[c.x, c.y]];
    let lightPts = [[c.x + 1.5, c.y + 0.5]];
    let cx = c.x;
    let cy = c.y;
    let steps = 5;
    for (let s = 0; s < steps; s++) {
      let a = c.ang + random(-22, 22);
      let stepLen = (c.len / steps) * random(0.7, 1.3);
      cx += cos(a) * stepLen;
      cy += sin(a) * stepLen;
      pts.push([cx, cy]);
      lightPts.push([cx + 1.5, cy + 0.8]);

      // Secondary branching micro-cracks
      if (s === 2 || s === 3) {
        let bx = cx + cos(a + 38) * 14;
        let by = cy + sin(a + 38) * 14;
        brush.set("rotring", C_IRON, 0.45);
        brush.line(cx, cy, bx, by);
        brush.set("2H", C_SILVER_DIM, 0.35);
        brush.line(cx + 1, cy + 1, bx + 1, by + 1);
      }
    }
    // Deep fissure shadow
    brush.set("rotring", C_IRON, 0.75);
    brush.spline(pts, 0.3);
    // Raised curled leather lip catching creamy silver highlight
    brush.set("rotring", C_SILVER_CREAM, 0.45);
    brush.spline(lightPts, 0.3);
  }

  // Fine stippled leather pore grain
  brush.set("spray", C_CHOC_DEEP, 0.6);
  brush.line(230, 165, 480, 210);
  brush.set("spray", C_SILVER_DIM, 0.4);
  brush.line(260, 160, 470, 202);
}

function drawSeatSpring(x1, y1, x2, y2, radius, coils) {
  for (let i = 0; i < coils; i++) {
    let t1 = i / coils;
    let t2 = (i + 0.5) / coils;
    let cx = lerp(x1, x2, t1);
    let cy = lerp(y1, y2, t1);
    let nx = lerp(x1, x2, t2);
    let ny = lerp(y1, y2, t2);

    // Back of coil
    brush.set("charcoal", C_CHOC_DEEP, 2.2);
    brush.line(cx - radius, cy, nx + radius, ny);
    // Front coil bar shadow
    brush.set("charcoal", C_CHOC_DARK, 2.6);
    brush.line(cx - radius, cy + 4, cx + radius, cy - 3);
    // Pewter & silver coil highlight
    brush.set("HB", C_PEWTER_LIGHT, 1.3);
    brush.line(cx - radius + 2, cy + 2, cx + radius - 2, cy - 5);
    brush.set("2H", C_SILVER_CREAM, 0.6);
    brush.line(cx - radius + 5, cy + 1, cx + 4, cy - 3);
  }
}

// =============================================================================
// 5. V-TWIN CYLINDER BARRELS (STACKED CAST-IRON COOLING FINS)
// =============================================================================
function drawCylinderBarrel(bx, by, tx, ty, numFins, rBase, rTop, tiltDeg, isFront) {
  // Unit vectors along cylinder axis (u) and perpendicular fin plane (v)
  let dx = tx - bx;
  let dy = ty - by;
  let len = Math.sqrt(dx * dx + dy * dy);
  let ux = dx / len;
  let uy = dy / len;
  // Perpendicular vector pointing toward right-down/up along the fin width
  let vx = -uy;
  let vy = ux;
  if (vx < 0) {
    vx = -vx;
    vy = -vy;
  }

  // Base mounting flange at the crankcase mouth
  drawFinPlate(bx, by, rBase * 0.92, 26, vx, vy, ux, uy, false, isFront, 0);
  // Base hold-down nuts
  if (isFront) {
    drawOilyBolt(bx - vx * 68, by - vy * 68 - 4, 11, true, 16);
    drawOilyBolt(bx + vx * 72, by + vy * 72 - 2, 11, true, 22);
  } else {
    drawOilyBolt(bx - vx * 64, by - vy * 64 - 4, 10, true, 15);
    drawOilyBolt(bx + vx * 64, by + vy * 64 - 2, 11, true, 18);
  }

  // Iterate from bottom fin to top fin
  for (let i = 0; i < numFins; i++) {
    let t = (i + 0.8) / numFins;
    let cx = lerp(bx, tx, t);
    let cy = lerp(by, ty, t);

    // Fin radius tapers outward from base to top head
    let finProfile = lerp(rBase, rTop, Math.pow(t, 0.75));
    // Slight step-in on alternate fins or upper barrel contour
    if (i === 0 || i === 1) finProfile *= 0.9;
    if (i > 10) finProfile *= 1.06;

    // Perspective foreshortening of each elliptical fin plate
    // Lower fins are seen slightly more edge-on; upper fins show slightly more underside/topside
    let minorRadius = lerp(24, 17, t);

    // 1. Deep shadow slot between this fin and the one below it
    let slotCx = cx - ux * (len / numFins) * 0.52;
    let slotCy = cy - uy * (len / numFins) * 0.52;
    drawFinSlotShadow(slotCx, slotCy, finProfile * 0.94, minorRadius, vx, vy, ux, uy, isFront);

    // 2. Render the individual cast-iron cooling fin plate in hyperreal detail
    drawFinPlate(cx, cy, finProfile, minorRadius, vx, vy, ux, uy, true, isFront, i / numFins);
  }
}

function drawFinSlotShadow(cx, cy, majorR, minorR, vx, vy, ux, uy, isFront) {
  let pts = [];
  let steps = 24;
  for (let s = 0; s <= steps; s++) {
    let ang = map(s, 0, steps, -175, 5);
    let px = cx + vx * cos(ang) * majorR * 0.86 - ux * sin(ang) * minorR * 0.85;
    let py = cy + vy * cos(ang) * majorR * 0.86 - uy * sin(ang) * minorR * 0.85;
    pts.push([px, py]);
  }
  // Deep chocolate-black recess between cooling fins
  brush.set("charcoal", C_IRON, 2.2);
  brush.spline(pts, 0.35);
  brush.set("2B", C_CHOC_DEEP, 1.6);
  let pts2 = pts.map(p => [p[0] + ux * 4, p[1] + uy * 4]);
  brush.spline(pts2, 0.35);

  // Subtle vertical cylinder barrel wall glimpse inside the slot
  let wallShift = isFront ? -0.15 : 0.15;
  let wx = cx + vx * majorR * wallShift;
  let wy = cy + vy * majorR * wallShift;
  brush.set("HB", C_PEWTER_DARK, 0.9);
  brush.line(wx - ux * 6, wy - uy * 6, wx + ux * 6, wy + uy * 6);

  // Vertical cast-iron tie-rod / fin support bosses between fins
  for (let side of [-0.52, 0.05, 0.55]) {
    let rx = cx + vx * majorR * side - ux * minorR * 0.65;
    let ry = cy + vy * majorR * side - uy * minorR * 0.65;
    brush.set("rotring", C_PEWTER_MID, 0.75);
    brush.line(rx - ux * 7, ry - uy * 7, rx + ux * 6, ry + uy * 6);
    brush.set("rotring", C_SILVER_CREAM, 0.45);
    brush.line(rx - ux * 5 + vx * 1.5, ry - uy * 5 + vy * 1.5, rx + ux * 5 + vx * 1.5, ry + uy * 5 + vy * 1.5);
  }
}

function drawFinPlate(cx, cy, majorR, minorR, vx, vy, ux, uy, hasNotches, isFront, heightNorm) {
  // Sample points around the front-facing arc of the cooling fin (-185 deg to +12 deg)
  let totalSteps = 44;
  let arcPts = [];

  for (let s = 0; s <= totalSteps; s++) {
    let ang = map(s, 0, totalSteps, -185, 12);
    let rMod = 1.0;

    // Authentic mechanical fin notches (pushrod tube relief on the inner V side, squared outer corners)
    if (hasNotches) {
      // Squared cast-iron corner swells at -145 and -35 degrees
      let cornerSw = Math.pow(sin(ang * 2), 2) * 0.08;
      rMod += cornerSw;

      // Inner V cutout for pushrod tube clearance
      if (isFront && ang < -125 && ang > -172) {
        rMod -= 0.14 * sin(map(ang, -172, -125, 0, 180));
      }
      if (!isFront && ang > -58 && ang < -10) {
        rMod -= 0.14 * sin(map(ang, -58, -10, 0, 180));
      }
    }

    let px = cx + vx * cos(ang) * majorR * rMod - ux * sin(ang) * minorR;
    let py = cy + vy * cos(ang) * majorR * rMod - uy * sin(ang) * minorR;
    arcPts.push({ x: px, y: py, ang: ang });
  }

  // 1. Fin surface ledge (graphite cross-hatching across the visible top/bottom bevel of the fin)
  for (let s = 3; s < totalSteps - 3; s += 2) {
    let p = arcPts[s];
    let inwardX = p.x + ux * 8 - vx * cos(p.ang) * 9;
    let inwardY = p.y + uy * 8 - vy * cos(p.ang) * 9;

    // Light comes from upper-left/front: stronger illumination on angles between -150 and -45
    let lightFactor = cos(p.ang + 105);
    let ledgeCol = C_CHOC_MID;
    if (lightFactor > 0.65) ledgeCol = C_PEWTER_LIGHT;
    else if (lightFactor > 0.25) ledgeCol = C_PEWTER_MID;
    else if (lightFactor > -0.15) ledgeCol = C_PEWTER_DARK;

    brush.set("2H", ledgeCol, 0.55);
    brush.line(p.x, p.y, inwardX, inwardY);
  }

  // 2. Underside shadow lip of the fin
  let underPts = arcPts.map(p => [p.x - ux * 3.5, p.y - uy * 3.5]);
  brush.set("2B", C_CHOC_DEEP, 1.3);
  brush.spline(underPts, 0.3);

  // 3. Machined/cast outer rim of the fin segmented by lighting zone
  // Divide the front arc into 6 tonal segments for smooth metallic wrap-around
  let segSize = Math.floor(totalSteps / 6);
  for (let seg = 0; seg < 6; seg++) {
    let startIdx = seg * segSize;
    let endIdx = (seg === 5) ? totalSteps : (seg + 1) * segSize;
    let segPts = [];
    for (let k = startIdx; k <= endIdx; k++) {
      segPts.push([arcPts[k].x, arcPts[k].y]);
    }

    let midAng = arcPts[Math.floor((startIdx + endIdx) / 2)].ang;
    // Key light angle peaks around -105 deg (front-left) and secondary rim at -50 deg
    let lum = cos(midAng + 102);
    if (isFront) lum = cos(midAng + 95);

    // Check distance from focal center for sharp vs soft graphite rendering
    let midPt = segPts[Math.floor(segPts.length / 2)];
    let distFromFocus = dist(midPt[0], midPt[1], FOCAL_X, FOCAL_Y);

    if (lum > 0.65) {
      // Bright creamy-silver specular fin edge
      brush.set("HB", C_PEWTER_LIGHT, 1.6);
      brush.spline(segPts, 0.3);
      brush.set("2H", C_SILVER_CREAM, 1.1);
      brush.spline(segPts.map(p => [p[0] + ux * 0.8, p[1] + uy * 0.8]), 0.3);
      if (distFromFocus < 370) {
        brush.set("rotring", C_SILVER_SPEC, 0.65);
        brush.spline(segPts.map(p => [p[0] + ux * 1.2, p[1] + uy * 1.2]), 0.3);
      }
    } else if (lum > 0.2) {
      // Mid-bright pewter fin edge
      brush.set("HB", C_PEWTER_MID, 1.5);
      brush.spline(segPts, 0.3);
      brush.set("2H", C_SILVER_DIM, 0.85);
      brush.spline(segPts.map(p => [p[0] + ux * 0.8, p[1] + uy * 0.8]), 0.3);
    } else if (lum > -0.25) {
      // Dark pewter transition
      brush.set("2B", C_PEWTER_DARK, 1.4);
      brush.spline(segPts, 0.3);
      brush.set("HB", C_PEWTER_MID, 0.65);
      brush.spline(segPts, 0.3);
    } else {
      // Deep shadow turn of the fin
      brush.set("charcoal", C_CHOC_DARK, 1.5);
      brush.spline(segPts, 0.3);
    }
  }

  // 4. Micro sand-cast iron texture & oil flecks on the brightest fin edges
  if (heightNorm > 0.2 && heightNorm < 0.9) {
    for (let n = 0; n < 4; n++) {
      let idx = Math.floor(random(10, 32));
      let p = arcPts[idx];
      // Tiny casting nick shadow + adjacent silver burr
      brush.set("rotring", C_CHOC_DEEP, 0.55);
      brush.line(p.x - 1.5, p.y, p.x + 1.5, p.y);
      brush.set("rotring", C_SILVER_SPEC, 0.45);
      brush.line(p.x + 1.5, p.y - 0.5, p.x + 3.5, p.y - 0.5);
    }
  }
}

// =============================================================================
// 6. CYLINDER HEADS & ROCKER BOXES (OVERHEAD VALVE KNUCKLE/PAN STYLE)
// =============================================================================
function drawRockerBox(cx, cy, tiltDeg, sc, isFront) {
  push();
  translate(cx, cy);
  rotate(tiltDeg);
  scale(sc);

  // Dark gasket seam & oily seepage below the rocker cover
  brush.set("charcoal", C_IRON, 2.8);
  brush.line(-118, 28, 118, 28);
  brush.set("2B", C_ACCENT_OIL, 1.6);
  brush.line(-95, 31, 85, 31);

  // Left and Right Rocker Domes ("Knuckles" / Valve Covers)
  let domes = [
    { x: -56, y: -12, w: 96, h: 64 },
    { x: 54,  y: -10, w: 94, h: 62 }
  ];

  for (let d of domes) {
    // Base cast aluminum shadow wash
    brush.noStroke();
    brush.wash(C_CHOC_DARK, 235);
    brush.rect(d.x, d.y, d.w, d.h, "center");
    brush.noWash();

    // Sculpted dome contours in soft graphite
    for (let r = 0; r < 12; r++) {
      let t = r / 11;
      let yy = lerp(d.y - d.h * 0.45, d.y + d.h * 0.42, t);
      let halfW = (d.w * 0.48) * Math.sqrt(1 - Math.pow((t - 0.55) * 1.4, 2) * 0.7);
      let col = C_PEWTER_DARK;
      if (t < 0.28) col = C_SILVER_CREAM;
      else if (t < 0.48) col = C_PEWTER_LIGHT;
      else if (t < 0.72) col = C_PEWTER_MID;
      else col = C_CHOC_MID;

      brush.set("HB", col, 1.3);
      brush.line(d.x - halfW, yy, d.x + halfW, yy);
    }

    // Bright specular crown across the upper curve of the aluminum rocker cover
    brush.set("2H", C_SILVER_BRIGHT, 1.2);
    brush.line(d.x - d.w * 0.36, d.y - d.h * 0.28, d.x + d.w * 0.25, d.y - d.h * 0.28);
    brush.set("rotring", C_SILVER_SPEC, 0.65);
    brush.line(d.x - d.w * 0.3, d.y - d.h * 0.31, d.x + d.w * 0.15, d.y - d.h * 0.31);

    // Raised vertical cast ribs on the rocker cover
    for (let ribX of [-24, 0, 24]) {
      let rx = d.x + ribX;
      brush.set("2B", C_CHOC_DEEP, 0.9);
      brush.line(rx - 3, d.y - d.h * 0.42, rx - 3, d.y + d.h * 0.38);
      brush.set("rotring", C_SILVER_CREAM, 0.7);
      brush.line(rx, d.y - d.h * 0.42, rx, d.y + d.h * 0.35);
      brush.set("HB", C_PEWTER_MID, 0.6);
      brush.line(rx + 2, d.y - d.h * 0.42, rx + 2, d.y + d.h * 0.38);
    }

    // Large scalloped hex rocker-shaft nut on the face of each knuckle
    drawHexNutFace(d.x, d.y + 4, 22);
  }

  // Central bridge casting between the two valve domes
  brush.set("charcoal", C_CHOC_DEEP, 2.0);
  brush.line(-12, -32, 12, -32);
  brush.set("HB", C_PEWTER_LIGHT, 1.2);
  brush.line(-15, -15, 15, -15);

  // Rocker cover perimeter hold-down bolts with oily stains
  let boltOffsets = [-98, -56, -12, 14, 56, 96];
  for (let bx of boltOffsets) {
    drawOilyBolt(bx, 22, 8.5, true, 14);
    drawOilyBolt(bx * 0.88, -42, 7.5, true, 6);
  }

  pop();
}

function drawHexNutFace(x, y, radius) {
  // Recessed shadow collar
  brush.noStroke();
  brush.wash(C_CHOC_DEEP, 230);
  brush.circle(x, y, radius * 1.18, 0.1);
  brush.noWash();

  brush.set("rotring", C_SILVER_DIM, 0.7);
  brush.circle(x, y, radius * 1.15, 0.08);

  // 6-sided hex perimeter
  let hexPts = [];
  for (let i = 0; i <= 6; i++) {
    let a = i * 60 - 30;
    hexPts.push([x + cos(a) * radius, y + sin(a) * radius]);
  }
  for (let i = 0; i < 6; i++) {
    let col = (i === 3 || i === 4) ? C_SILVER_SPEC : (i === 2 || i === 5) ? C_PEWTER_LIGHT : C_CHOC_DEEP;
    let w = (i === 3 || i === 4) ? 0.9 : 1.1;
    brush.set("rotring", col, w);
    brush.line(hexPts[i][0], hexPts[i][1], hexPts[i + 1][0], hexPts[i + 1][1]);
  }

  // Machined inner chamfer ring & central shaft end
  brush.set("2H", C_PEWTER_MID, 0.8);
  brush.circle(x, y, radius * 0.68, 0.05);
  brush.set("rotring", C_SILVER_BRIGHT, 0.55);
  brush.arc(x, y, radius * 0.68, 195, 330);
  brush.set("rotring", C_CHOC_DEEP, 0.7);
  brush.circle(x, y, radius * 0.28, 0.05);
}

