// HYPERREAL OILY HEX BOLT HELPER
// =============================================================================
function drawOilyBolt(x, y, r, hasWasher, oilDripLen) {
  // 1. Dark oil stain & downward gravity drip
  if (oilDripLen > 0) {
    brush.set("2B", C_CHOC_DEEP, r * 0.22);
    brush.line(x, y + r * 0.5, x + random(-2, 2), y + r + oilDripLen);
    brush.set("HB", C_ACCENT_OIL, r * 0.16);
    brush.line(x - 1, y + r * 0.4, x - 1, y + r + oilDripLen * 0.75);
    // Tiny wet specular bead on the oil trail
    brush.set("rotring", C_SILVER_BRIGHT, 0.38);
    brush.line(x + 1, y + r * 0.8, x + 1, y + r + oilDripLen * 0.45);
  }

  // 2. Cast shadow under bolt head
  brush.noStroke();
  brush.wash(C_IRON, 235);
  brush.circle(x + 2, y + 2.5, r * 1.25, 0.08);
  brush.noWash();

  // 3. Beveled steel washer
  if (hasWasher) {
    brush.set("rotring", C_PEWTER_MID, 0.65);
    brush.circle(x, y, r * 1.28, 0.06);
    brush.set("rotring", C_SILVER_SPEC, 0.55);
    brush.arc(x, y, r * 1.28, 190, 325);
  }

  // 4. 3D Hexagonal head facets
  // Top-left & top facets catch bright creamy silver; bottom-right facets in chocolate shadow
  brush.noStroke();
  brush.wash(C_CHOC_DARK, 240);
  brush.circle(x, y, r, 0.1);
  brush.noWash();

  // Bright top-left facet plane
  brush.set("HB", C_SILVER_CREAM, r * 0.18);
  brush.line(x - r * 0.75, y - r * 0.25, x - r * 0.1, y - r * 0.82);
  brush.set("rotring", C_SILVER_SPEC, 0.65);
  brush.line(x - r * 0.8, y - r * 0.2, x, y - r * 0.9);

  // Top-right facet plane
  brush.set("HB", C_PEWTER_LIGHT, r * 0.16);
  brush.line(x, y - r * 0.82, x + r * 0.75, y - r * 0.25);

  // Front circular chamfer of the bolt crown
  brush.set("2H", C_PEWTER_MID, 0.75);
  brush.circle(x, y, r * 0.68, 0.05);
  brush.set("rotring", C_SILVER_SPEC, 0.55);
  brush.arc(x, y, r * 0.66, 200, 315);

  // Dark bottom facet edge
  brush.set("rotring", C_IRON, 0.8);
  brush.arc(x, y, r * 0.92, 15, 165);
}

