// 8. PUSHROD TUBES & SPRING COLLARS (CHROME CYLINDERS IN THE V)
// =============================================================================
function drawPushrodAssemblies() {
  let pushrods = [
    // Rear Cylinder Exhaust & Intake Pushrod Tubes
    { x1: 526, y1: 702, x2: 392, y2: 356, r: 11.5 },
    { x1: 554, y1: 704, x2: 432, y2: 362, r: 11.5 },
    // Front Cylinder Intake & Exhaust Pushrod Tubes
    { x1: 598, y1: 704, x2: 734, y2: 368, r: 12.0 },
    { x1: 628, y1: 702, x2: 778, y2: 374, r: 12.0 }
  ];

  for (let pr of pushrods) {
    // Draw main chrome pushrod tube with longitudinal specular reflection bands
    drawStraightChromeCylinder(pr.x1, pr.y1, pr.x2, pr.y2, pr.r);

    // Lower tappet cover sleeve (wider stepped cylinder on bottom 35% of pushrod)
    let mx1 = lerp(pr.x1, pr.x2, 0.04);
    let my1 = lerp(pr.y1, pr.y2, 0.04);
    let mx2 = lerp(pr.x1, pr.x2, 0.36);
    let my2 = lerp(pr.y1, pr.y2, 0.36);
    drawStraightChromeCylinder(mx1, my1, mx2, my2, pr.r * 1.26);

    // Ribbed spring-retainer collars & cork-seal shadow rings along each tube
    let collarPositions = [0.04, 0.36, 0.42, 0.68, 0.95];
    let dx = pr.x2 - pr.x1;
    let dy = pr.y2 - pr.y1;
    let len = Math.sqrt(dx * dx + dy * dy);
    let nx = -dy / len;
    let ny = dx / len;

    for (let cp of collarPositions) {
      let cx = lerp(pr.x1, pr.x2, cp);
      let cy = lerp(pr.y1, pr.y2, cp);
      let cr = pr.r * 1.42;

      // Dark cork washer / oily groove
      brush.set("rotring", C_IRON, 1.3);
      brush.line(cx - nx * cr, cy - ny * cr, cx + nx * cr, cy + ny * cr);

      // Stepped chrome collar ring
      brush.set("HB", C_PEWTER_LIGHT, 1.4);
      brush.line(cx - nx * cr + dx / len * 3, cy - ny * cr + dy / len * 3, cx + nx * cr + dx / len * 3, cy + ny * cr + dy / len * 3);
      brush.set("rotring", C_SILVER_SPEC, 0.85);
      brush.line(cx - nx * cr * 0.85 + dx / len * 3.5, cy - ny * cr * 0.85 + dy / len * 3.5, cx + nx * cr * 0.2 + dx / len * 3.5, cy + ny * cr * 0.2 + dy / len * 3.5);
    }
  }
}

function drawStraightChromeCylinder(x1, y1, x2, y2, radius) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.sqrt(dx * dx + dy * dy);
  let nx = -dy / len;
  let ny = dx / len;
  // Ensure normal points toward upper-left light source
  if (nx > 0) {
    nx = -nx;
    ny = -ny;
  }

  // Cross-sectional reflection bands for high-contrast chrome cylinder:
  // [-1.0: dark edge, -0.7: reflected pewter, -0.45: bright specular, -0.15: creamy silver,
  //  +0.25: dark core reflection, +0.65: secondary pewter, +0.95: dark shadow edge]
  let bands = [
    { offset: -0.95, col: C_CHOC_DEEP,    w: 0.9,  b: "rotring" },
    { offset: -0.75, col: C_PEWTER_MID,   w: 1.1,  b: "HB" },
    { offset: -0.52, col: C_SILVER_CREAM, w: 1.3,  b: "2H" },
    { offset: -0.38, col: C_SILVER_SPEC,  w: 0.95, b: "rotring" },
    { offset: -0.18, col: C_SILVER_DIM,   w: 1.2,  b: "HB" },
    { offset:  0.12, col: C_CHOC_DEEP,    w: 1.6,  b: "charcoal" },
    { offset:  0.38, col: C_CHOC_DARK,    w: 1.4,  b: "2B" },
    { offset:  0.68, col: C_PEWTER_LIGHT, w: 1.1,  b: "HB" },
    { offset:  0.95, col: C_IRON,         w: 1.0,  b: "rotring" }
  ];

  for (let b of bands) {
    let ox = nx * radius * b.offset;
    let oy = ny * radius * b.offset;
    brush.set(b.b, b.col, b.w);
    brush.line(x1 + ox, y1 + oy, x2 + ox, y2 + oy);
  }
}

