function drawCurvedMetallicPipe(pts, radius, hasHeatPatina) {
  // Generate dense interpolated centerline points and normals
  let densePts = [];
  let steps = 36;
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[Math.max(0, i - 1)];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[Math.min(pts.length - 1, i + 2)];
    let subSteps = Math.ceil(steps / (pts.length - 1));
    for (let s = 0; s < subSteps; s++) {
      let t = s / subSteps;
      let x = curvePoint(p0[0], p1[0], p2[0], p3[0], t);
      let y = curvePoint(p0[1], p1[1], p2[1], p3[1], t);
      densePts.push({ x, y });
    }
  }
  densePts.push({ x: pts[pts.length - 1][0], y: pts[pts.length - 1][1] });

  // Compute unit normals along the pipe curve
  for (let i = 0; i < densePts.length; i++) {
    let prev = densePts[Math.max(0, i - 1)];
    let next = densePts[Math.min(densePts.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let l = Math.sqrt(dx * dx + dy * dy) || 1;
    densePts[i].nx = -dy / l;
    densePts[i].ny = dx / l;
  }

  // Draw parallel offset ribbons across the pipe cross-section (-1 to +1)
  let ribbons = [
    { off: -0.96, col: C_IRON,         w: 1.5, b: "charcoal" },
    { off: -0.78, col: C_CHOC_DARK,    w: 1.6, b: "2B" },
    { off: -0.58, col: C_PEWTER_DARK,  w: 1.5, b: "HB" },
    { off: -0.36, col: C_PEWTER_LIGHT, w: 1.5, b: "HB" },
    { off: -0.18, col: C_SILVER_CREAM, w: 1.4, b: "2H" },
    { off: -0.06, col: C_SILVER_SPEC,  w: 0.9, b: "rotring" },
    { off:  0.12, col: C_SILVER_DIM,   w: 1.3, b: "HB" },
    { off:  0.35, col: C_CHOC_DEEP,    w: 1.9, b: "charcoal" },
    { off:  0.58, col: C_CHOC_MID,     w: 1.6, b: "2B" },
    { off:  0.78, col: C_PEWTER_MID,   w: 1.3, b: "HB" },
    { off:  0.96, col: C_CHOC_DEEP,    w: 1.4, b: "charcoal" }
  ];

  for (let r of ribbons) {
    let linePts = densePts.map(p => [
      p.x + p.nx * radius * r.off,
      p.y + p.ny * radius * r.off
    ]);
    brush.set(r.b, r.col, r.w);
    brush.spline(linePts, 0.35);
  }

  // Heat-blued/amber patina & circumferential contour rings near the exhaust header bend
  if (hasHeatPatina) {
    let bendSlice = densePts.slice(2, Math.min(18, densePts.length));
    let patinaPts = bendSlice.map(p => [p.x + p.nx * radius * 0.05, p.y + p.ny * radius * 0.05]);
    brush.set("HB", C_ACCENT_OIL, 1.3);
    brush.spline(patinaPts, 0.35);

    for (let i = 2; i < densePts.length - 2; i += 3) {
      let p = densePts[i];
      brush.set("2H", C_PEWTER_LIGHT, 0.45);
      brush.line(
        p.x - p.nx * radius * 0.7, p.y - p.ny * radius * 0.7,
        p.x + p.nx * radius * 0.7, p.y + p.ny * radius * 0.7
      );
    }
  }
}

