function drawBraidedCable(pts, halfWidth, isMetallic) {
  // Interpolate smooth curve points
  let dense = [];
  let totalSteps = 68;
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[Math.max(0, i - 1)];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[Math.min(pts.length - 1, i + 2)];
    let sub = Math.ceil(totalSteps / (pts.length - 1));
    for (let s = 0; s < sub; s++) {
      let t = s / sub;
      let x = curvePoint(p0[0], p1[0], p2[0], p3[0], t);
      let y = curvePoint(p0[1], p1[1], p2[1], p3[1], t);
      dense.push({ x, y });
    }
  }

  // Cast shadow just behind cable
  let shadowPts = dense.map(p => [p.x + 4, p.y + 5]);
  brush.set("charcoal", C_IRON, 1.6);
  brush.spline(shadowPts, 0.35);

  // Core dark body of the cable
  let corePts = dense.map(p => [p.x, p.y]);
  brush.set("2B", C_CHOC_DEEP, 1.8);
  brush.spline(corePts, 0.35);

  // Crisscross diamond weave texture along the entire length of the cable
  for (let i = 1; i < dense.length - 1; i++) {
    let p = dense[i];
    let next = dense[i + 1];
    let dx = next.x - p.x;
    let dy = next.y - p.y;
    let l = Math.sqrt(dx * dx + dy * dy) || 1;
    let ux = dx / l;
    let uy = dy / l;
    let nx = -uy;
    let ny = ux;

    // Alternating diagonal weave strands
    let dir = (i % 2 === 0) ? 1 : -1;
    let x1 = p.x - nx * halfWidth * dir - ux * 2.5;
    let y1 = p.y - ny * halfWidth * dir - uy * 2.5;
    let x2 = p.x + nx * halfWidth * dir + ux * 2.5;
    let y2 = p.y + ny * halfWidth * dir + uy * 2.5;

    // Shadow crevice between braids
    brush.set("rotring", C_IRON, 0.65);
    brush.line(x1 - ux * 1.5, y1 - uy * 1.5, x2 - ux * 1.5, y2 - uy * 1.5);

    // Illuminated braid strand
    let strandCol = isMetallic ? C_SILVER_CREAM : ((i % 3 === 0) ? C_ACCENT_BRASS : C_PEWTER_LIGHT);
    brush.set("rotring", strandCol, 0.6);
    brush.line(x1, y1, x2, y2);

    // Specular crown dot on the center-left ridge of each weave knot
    let hx = p.x - nx * halfWidth * 0.35;
    let hy = p.y - ny * halfWidth * 0.35;
    brush.set("rotring", C_SILVER_SPEC, 0.55);
    brush.line(hx, hy, hx + ux * 2, hy + uy * 2);
  }
}

