// 12. SHARP PERIPHERAL FOCUS FALLOFF (PETZVAL SWIRL OVERLAYS)
// =============================================================================
function drawPeripheralFocusFalloff() {
  brush.field("petzval");

  // Swirl-blur the outer edges of the engine & periphery (radius > 375 from focal center)
  for (let i = 0; i < 240; i++) {
    let ang = random(360);
    let rad = random(375, 590);
    let px = FOCAL_X + cos(ang) * rad;
    let py = FOCAL_Y + sin(ang) * rad;

    let distNorm = constrain(map(rad, 375, 590, 0, 1), 0, 1);
    let len = lerp(28, 135, distNorm) * random(0.75, 1.25);
    let w = lerp(0.5, 2.2, distNorm);

    // Sample appropriate regional tone so the blur pulls pigment from the underlying parts
    let col = C_CHOC_DARK;
    if (rad < 470 && random() > 0.55) {
      col = (random() > 0.45) ? C_PEWTER_MID : C_SILVER_DIM;
    } else if (random() > 0.78) {
      col = C_PEWTER_DARK;
    } else if (rad > 510) {
      col = C_CHOC_DEEP;
    }

    let bName = (distNorm > 0.45) ? "charcoal" : "2B";
    brush.set(bName, col, w);
    brush.flowLine(px, py, len, ang + 90);
  }

  brush.noField();
}

