  brush.rect(0, 0, 42, 1200, "corner");
  brush.rect(1158, 0, 42, 1200, "corner");
  brush.noWash();

  // 2. Uneven Collodion Pour Meniscus Waves & Chemical Tide Marks around all edges
  let pourWaves = [
    // Top-right thumb pour wave
    [[790, 42], [885, 68], [975, 115], [1058, 178], [1120, 275], [1156, 395]],
    [[750, 48], [860, 82], [955, 132], [1038, 198], [1105, 295], [1148, 425]],
    // Bottom-left drain corner wave (concentric collodion ripples)
    [[42, 785], [75, 895], [128, 995], [198, 1068], [295, 1125], [415, 1156]],
    [[52, 740], [92, 865], [148, 968], [222, 1045], [322, 1105], [450, 1146]],
    [[64, 695], [110, 835], [172, 942], [248, 1020], [352, 1085], [485, 1132]],
    // Top-left wave
    [[42, 355], [78, 240], [132, 145], [215, 78], [335, 44]],
    [[55, 385], [95, 262], [152, 165], [238, 95], [365, 54]],
    // Bottom-right wave
    [[810, 1155], [935, 1118], [1038, 1052], [1112, 955], [1155, 810]],
    [[780, 1142], [912, 1102], [1018, 1032], [1095, 932], [1142, 785]]
  ];

  for (let idx = 0; idx < pourWaves.length; idx++) {
    let wPts = pourWaves[idx];
    // Dark thickened collodion ridge
    brush.set("charcoal", C_IRON, 2.2);
    brush.spline(wPts, 0.45);
    // Warm amber/oil chemical developer stain along the meniscus
    brush.set("2B", C_ACCENT_OIL, 1.3);
    let stainPts = wPts.map(p => [p[0] + random(-4, 4), p[1] + random(-4, 4)]);
    brush.spline(stainPts, 0.45);
    // Creamy-silver metallic "oyster" halo where silver nitrate pooled at the emulsion edge
    brush.set("HB", (idx % 2 === 0) ? C_SILVER_CREAM : C_PEWTER_LIGHT, 0.95);
    let haloPts = wPts.map(p => [
      lerp(p[0], 600, 0.012),
      lerp(p[1], 600, 0.012)
    ]);
    brush.spline(haloPts, 0.45);
  }

  // Irregular emulsion peeling and rough charcoal border texture along the 4 edges
  for (let i = 0; i < 90; i++) {
    let side = i % 4;
    let x1, y1, x2, y2;
    if (side === 0) {
      x1 = random(60, 1140); y1 = random(35, 75);
      x2 = x1 + random(-60, 60); y2 = y1 + random(-15, 25);
    } else if (side === 1) {
      x1 = random(60, 1140); y1 = random(1125, 1165);
      x2 = x1 + random(-60, 60); y2 = y1 + random(-25, 15);
    } else if (side === 2) {
      x1 = random(35, 75); y1 = random(60, 1140);
      x2 = x1 + random(-15, 25); y2 = y1 + random(-60, 60);
    } else {
      x1 = random(1125, 1165); y1 = random(60, 1140);
      x2 = x1 + random(-25, 15); y2 = y1 + random(-60, 60);
    }
    brush.set("charcoal", (i % 5 === 0) ? C_PEWTER_DARK : C_IRON, random(1.2, 2.8));
    brush.line(x1, y1, x2, y2);
  }

  // 3. Authentic Wet-Plate "Comet Streaks" (Silver Nitrate Precipitate Trails)
  // Oriented along the collodion drain direction (~118 degrees toward bottom-left)
  brush.field("collodion_pour");

  for (let c = 0; c < 42; c++) {
    let cx = random(95, 1105);
    let cy = random(95, 1105);
    let dFocus = dist(cx, cy, FOCAL_X, FOCAL_Y);

    // Keep most heavy comets outside the dead-center hero carb so they enhance rather than obscure
    if (dFocus > 140 || random() > 0.7) {
      let isBrightComet = random() > 0.32;
      let headCol = isBrightComet ? C_SILVER_SPEC : C_IRON;
      let tailCol = isBrightComet ? C_SILVER_CREAM : C_CHOC_DEEP;
      let tailLen = random(18, 68);

      // Comet head dot (undissolved particle)
      brush.set("rotring", headCol, random(0.8, 1.5));
      brush.circle(cx, cy, random(1.2, 3.2), 0.2);

      // Tapering comet tail following the collodion pour vector field
      brush.set("2H", tailCol, random(0.45, 0.95));
      brush.flowLine(cx, cy, tailLen, 118 + random(-8, 8));
      if (isBrightComet) {
        brush.set("rotring", C_SILVER_BRIGHT, 0.35);
        brush.flowLine(cx, cy, tailLen * 0.55, 118);
      }
    }
  }

  brush.noField();

  // 4. Fine Plate Scratches & Dust Pinholes in the Collodion Emulsion
  for (let s = 0; s < 28; s++) {
    let sx = random(80, 1120);
    let sy = random(80, 1120);
    let sa = random(360);
    let slen = random(15, 55);
    brush.set("rotring", (s % 2 === 0) ? C_SILVER_DIM : C_CHOC_DEEP, 0.3);
    brush.line(sx, sy, sx + cos(sa) * slen, sy + sin(sa) * slen);
  }
}

