function draw() {
  translate(-width / 2, -height / 2);

  // Deep carmine-cloisonné enamel ground so zero light canvas ever exists
  background("#2e030a");
  brush.noStroke();
  brush.wash("#38040d", 255);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // 1. Build multi-scale Apollonian packing + under-layer interstitial wheels
  const { mainWheels, underWheels } = generatePackedCitrusLayout();

  // 2. Compute smooth power-diagram (radical-axis) boundaries for edge-to-edge contact
  computeWheelBoundaries(underWheels, false);
  computeWheelBoundaries(mainWheels, true);

  // 3. Render under-layer citrus wheels at all interstitial junctions
  for (let w of underWheels) {
    buildWheelInternalGeometry(w);
    renderCitrusWheel(w, true);
  }

  // 4. Render main edge-to-edge citrus wheels in structured enamel & cloisonné passes
  for (let w of mainWheels) {
    buildWheelInternalGeometry(w);
  }

  // Pass A: Wheel outer rind & gilded pith bed
  for (let w of mainWheels) {
    renderWheelBaseAndRind(w);
  }

  // Pass B: Flat glassy segment enamel bases + subtle vitrified edge bleed on hero slices
  renderAllSegmentEnamels(mainWheels);

  // Pass C: Hyperreal juice vesicles, seeds, cloisonné gold wires, and moist highlights
  for (let w of mainWheels) {
    renderWheelDetailsAndCloisonne(w, false);
  }

  noLoop();
}

function chooseFruitType(x, y, r, id) {
  // Diagonal S-curve ribbon for the "one accent" (chartreuse lime)
  let diagDist = abs((y - (0.72 * x + 110)) * 0.78 + sin(x * 0.25) * 95);
  let isAccentZone = diagDist < 125 && ((id * 37) % 100 < 52);

  if (isAccentZone) {
    return PALETTES.lime;
  }

  // Warm monochrome spectrum: Carmine Blood Orange, Intense Coral Grapefruit, Golden Citron
  if (r > 152) {
    return random() < 0.58 ? PALETTES.grapefruit : PALETTES.blood_orange;
  } else if (r > 95) {
    let p = random();
    if (p < 0.46) return PALETTES.blood_orange;
    if (p < 0.76) return PALETTES.grapefruit;
    return PALETTES.lemon;
  } else {
    let p = random();
    if (p < 0.42) return PALETTES.lemon;
    if (p < 0.78) return PALETTES.blood_orange;
    return PALETTES.grapefruit;
  }
}

function generatePackedCitrusLayout() {
  let mainWheels = [];
  let underWheels = [];
  let idCounter = 1;

  // Hand-curated anchor layout for balanced macro-composition, then greedy Apollonian fill
  const anchors = [
    { x: 240, y: 250, r: 195 },
    { x: 635, y: 210, r: 175 },
    { x: 1015, y: 235, r: 185 },
    { x: 145, y: 635, r: 170 },
    { x: 515, y: 575, r: 205 },
    { x: 915, y: 595, r: 180 },
    { x: 265, y: 985, r: 185 },
    { x: 675, y: 965, r: 175 },
    { x: 1045, y: 965, r: 165 }
  ];

  for (let a of anchors) {
    let jx = a.x + random(-18, 18);
    let jy = a.y + random(-18, 18);
    let jr = a.r + random(-10, 10);
    // Ensure non-overlapping with placed anchors
    let maxR = jr;
    for (let existing of mainWheels) {
      let d = dist(jx, jy, existing.x, existing.y);
      maxR = min(maxR, d - existing.r - 1);
    }
    if (maxR > 80) {
      mainWheels.push({
        id: idCounter++,
        x: jx,
        y: jy,
        r: maxR,
        rot: random(360),
        pal: chooseFruitType(jx, jy, maxR, idCounter)
      });
    }
  }

  // Greedy Apollonian tangent circle packing across [-70, 1270] x [-70, 1270]
  const minX = -70, maxX = 1270, minY = -70, maxY = 1270;
  for (let iter = 0; iter < 62; iter++) {
    let bestX = 0, bestY = 0, bestClearance = -9999;

    // Coarse grid search for largest empty circle
    let step = 16;
    for (let gx = minX; gx <= maxX; gx += step) {
      for (let gy = minY; gy <= maxY; gy += step) {
        let minClear = 9999;
        for (let w of mainWheels) {
          let c = dist(gx, gy, w.x, w.y) - w.r;
          if (c < minClear) minClear = c;
          if (minClear <= bestClearance) break;
        }
        if (minClear > bestClearance) {
          bestClearance = minClear;
          bestX = gx;
          bestY = gy;
        }
      }
    }

    // Fine local refinement around best candidate
    for (let refine = 8; refine >= 1; refine /= 2) {
      let cx = bestX, cy = bestY;
      for (let dx = -refine * 2; dx <= refine * 2; dx += refine) {
        for (let dy = -refine * 2; dy <= refine * 2; dy += refine) {
          let tx = constrain(cx + dx, minX, maxX);
          let ty = constrain(cy + dy, minY, maxY);
          let minClear = 9999;
          for (let w of mainWheels) {
            let c = dist(tx, ty, w.x, w.y) - w.r;
            if (c < minClear) minClear = c;
          }
          if (minClear > bestClearance) {
            bestClearance = minClear;
            bestX = tx;
            bestY = ty;
          }
        }
      }
    }

    if (bestClearance < 27) break;

    let newR = min(bestClearance + 0.5, 165);
    mainWheels.push({
      id: idCounter++,
      x: bestX,
      y: bestY,
      r: newR,
      rot: random(360),
      pal: chooseFruitType(bestX, bestY, newR, idCounter)
    });
  }

  // Find remaining tricorner pockets and place under-layer citrus wheels beneath them
  let pocketCenters = [];
  for (let gx = -20; gx <= 1220; gx += 22) {
    for (let gy = -20; gy <= 1220; gy += 22) {
      let minClear = 9999;
      for (let w of mainWheels) {
        let c = dist(gx, gy, w.x, w.y) - w.r;
        if (c < minClear) minClear = c;
      }
      if (minClear > 6.5) {
        // Check if far enough from already recorded pocket centers
        let tooClose = false;
        for (let p of pocketCenters) {
          if (dist(gx, gy, p.x, p.y) < 58) {
            if (minClear > p.clear) {
              p.x = gx;
              p.y = gy;
              p.clear = minClear;
            }
            tooClose = true;
            break;
          }
        }
        if (!tooClose) {
          pocketCenters.push({ x: gx, y: gy, clear: minClear });
        }
      }
    }
  }

  for (let p of pocketCenters) {
    let ur = constrain(p.clear * 2.8 + 34, 48, 86);
    underWheels.push({
      id: idCounter++,
      x: p.x,
      y: p.y,
      r: ur,
      rot: random(360),
      pal: chooseFruitType(p.x, p.y, ur, idCounter)
    });
  }

  return { mainWheels, underWheels };
}

function computeWheelBoundaries(wheels, usePowerDeform) {
  const numSamples = 120; // Every 3 degrees
  for (let i = 0; i < wheels.length; i++) {
    let w = wheels[i];
    let pal = w.pal;
    w.numSegs = floor(random(pal.segCount[0], pal.segCount[1] + 1));
    w.rSamples = new Array(numSamples);

    for (let k = 0; k < numSamples; k++) {
      let ang = k * (360 / numSamples);
      let ux = cos(ang);
      let uy = sin(ang);

      // Subtle botanical lobing per segment + organic noise
      let segPhase = (ang - w.rot) * w.numSegs;
      let lobe = 1.0 + 0.012 * cos(segPhase + 180) + 0.015 * (noise(w.id * 7.1 + ux * 1.5, uy * 1.5) - 0.5);

      if (!usePowerDeform) {
        w.rSamples[k] = w.r * lobe;
        continue;
      }

      // Exact radical-axis distance to all neighboring wheels so slices press edge-to-edge
      let rMaxAllow = min(w.r * 1.24, w.r + 28);
      let rPower = rMaxAllow;

      for (let j = 0; j < wheels.length; j++) {
        if (i === j) continue;
        let n = wheels[j];
        let dx = n.x - w.x;
        let dy = n.y - w.y;
        let d2 = dx * dx + dy * dy;
        let maxReach = w.r + n.r + 80;
        if (d2 > maxReach * maxReach) continue;

        let proj = dx * ux + dy * uy;
        if (proj > 0.05) {
          let radDist = (d2 + w.r * w.r - n.r * n.r) / (2.0 * proj);
          if (radDist < rPower) {
            rPower = radDist;
          }
        }
      }

      w.rSamples[k] = constrain(rPower, w.r * 0.84, rMaxAllow) * (0.992 + 0.008 * lobe);
    }

    // Smooth angularly (pillowy pressed fruit contour)
    let smoothed = new Array(numSamples);
    const kernel = [0.12, 0.22, 0.32, 0.22, 0.12];
    for (let k = 0; k < numSamples; k++) {
      let sum = 0;
      for (let m = -2; m <= 2; m++) {
        let idx = (k + m + numSamples) % numSamples;
        sum += w.rSamples[idx] * kernel[m + 2];
      }
      smoothed[k] = sum;
    }
    w.rSamples = smoothed;
  }
}

function evalWheelRadius(w, angleDeg) {
  let a = ((angleDeg % 360) + 360) % 360;
  let numSamples = w.rSamples.length;
  let f = (a / 360) * numSamples;
  let i0 = floor(f) % numSamples;
  let i1 = (i0 + 1) % numSamples;
  let t = f - floor(f);
  return lerp(w.rSamples[i0], w.rSamples[i1], t);
}

function buildWheelInternalGeometry(w) {
  let N = w.numSegs;
  let pal = w.pal;
  w.segAngles = [];

  // Slightly organic segment angular widths summing to 360
  let weights = [];
  let totalW = 0;
  for (let s = 0; s < N; s++) {
    let wt = 1.0 + random(-0.11, 0.11);
    weights.push(wt);
    totalW += wt;
  }
  let acc = w.rot;
  for (let s = 0; s <= N; s++) {
    w.segAngles.push(acc);
    if (s < N) acc += (weights[s] / totalW) * 360;
  }

  // Physical pixel half-width of the gold cloisonné septum wall
  let wallHalfPx = constrain(w.r * 0.022, 1.4, 3.8);

  w.segments = [];
  for (let s = 0; s < N; s++) {
    let a0 = w.segAngles[s];
    let a1 = w.segAngles[s + 1];
    let aMid = (a0 + a1) * 0.5;
    let span = a1 - a0;

    // Does this segment contain a sliced seed?
    let hasSeed = (w.r > 46) && (random() < pal.seedProb);
    let seed = null;
    if (hasSeed) {
      seed = {
        u: random(0.16, 0.30),
        v: random(-0.22, 0.22),
        du: random(0.11, 0.15),
        dv: random(0.24, 0.34),
        rotOffset: random(-12, 12)
      };
    }

    let seg = {
      index: s,
      a0,
      a1,
      aMid,
      span,
      wallHalfPx,
      midColor: random(pal.segMid),
      innerColor: random(pal.segInner),
      seed,
      outerPoly: [],
      innerPoly: [],
      vesicles: [],
      yJunction: null
    };

    // Coordinate mapping (u in [0..1], v in [-1..1]) -> canvas [x, y]
    function mapUV(u, v) {
      // Smooth corner rounding at dorsal outer shoulders (u -> 1) and inner apex (u -> 0)
      let shoulderFactor = 1.0;
      if (u > 0.78) {
        let t = constrain((u - 0.78) / 0.22, 0, 1);
        shoulderFactor = sqrt(max(0.02, 1.0 - t * t * 0.88));
      } else if (u < 0.16) {
        let t = constrain((0.16 - u) / 0.16, 0, 1);
        shoulderFactor = sqrt(max(0.05, 1.0 - t * t * 0.82));
      }

      let vEff = v * shoulderFactor;
      let prelimAng = aMid + vEff * (span * 0.5);
      let rBound = evalWheelRadius(w, prelimAng);

      let rCore = w.r * pal.coreFrac * (0.94 + 0.12 * noise(w.id * 3.3, s * 1.7));
      let rOuter = rBound * pal.pithFrac;

      // Pull outer dorsal arc slightly inward at corners for authentic Y-junction pith gusset
      let cornerPull = 1.0 - 0.038 * pow(abs(v), 2.2) * pow(u, 2.0);
      let r = lerp(rCore, rOuter * cornerPull, u);

      // Subtract physical septum wall thickness in angular degrees at radius r
      let angPad = (wallHalfPx / max(r, 8)) * (180 / PI);
      let halfSpan = max(1.2, span * 0.5 - angPad);
      let ang = aMid + vEff * halfSpan;

      return [w.x + r * cos(ang), w.y + r * sin(ang), r, ang];
    }

    seg.mapUV = mapUV;

    // Build closed segment boundary polygon (24 points around the rounded carpel)
    const boundaryUV = [
      [0.01, 0.0],
      [0.05, 0.55], [0.14, 0.88], [0.30, 0.98], [0.50, 1.0], [0.70, 1.0],
      [0.84, 0.96], [0.93, 0.82], [0.98, 0.52], [1.0, 0.18],
      [1.0, -0.18], [0.98, -0.52], [0.93, -0.82], [0.84, -0.96],
      [0.70, -1.0], [0.50, -1.0], [0.30, -0.98], [0.14, -0.88], [0.05, -0.55]
    ];

    for (let uv of boundaryUV) {
      let pt = mapUV(uv[0], uv[1]);
      seg.outerPoly.push([pt[0], pt[1]]);
      let ptIn = mapUV(lerp(0.52, uv[0], 0.78), uv[1] * 0.76);
      seg.innerPoly.push([ptIn[0], ptIn[1]]);
    }

    // Build Y-junction pith triangle at outer septum between segment s and s+1
    let rSep = evalWheelRadius(w, a1);
    let rZest = rSep * pal.zestFrac;
    let rTip = rSep * (pal.pithFrac - 0.055);
    let dAng = constrain((wallHalfPx * 2.5 / max(rSep, 20)) * (180 / PI), 2.2, 6.5);
    seg.yJunction = {
      pTip: [w.x + rTip * cos(a1), w.y + rTip * sin(a1)],
      pLeft: [w.x + rZest * cos(a1 - dAng), w.y + rZest * sin(a1 - dAng)],
      pRight: [w.x + rZest * cos(a1 + dAng), w.y + rZest * sin(a1 + dAng)],
      bossCenter: [w.x + lerp(rTip, rZest, 0.62) * cos(a1), w.y + lerp(rTip, rZest, 0.62) * sin(a1)],
      bossR: constrain(w.r * 0.018, 1.2, 3.6)
    };

    // Pack segment interior with radial-chevron teardrop juice vesicles
    let ranks;
    if (w.r > 145) {
      ranks = [
        { u0: 0.96, u1: 0.70, count: 8 },
        { u0: 0.75, u1: 0.45, count: 7 },
        { u0: 0.50, u1: 0.22, count: 5 },
        { u0: 0.26, u1: 0.04, count: 3 }
      ];
    } else if (w.r > 85) {
      ranks = [
        { u0: 0.96, u1: 0.64, count: 7 },
        { u0: 0.68, u1: 0.34, count: 5 },
        { u0: 0.38, u1: 0.06, count: 3 }
      ];
    } else {
      ranks = [
        { u0: 0.95, u1: 0.50, count: 5 },
        { u0: 0.55, u1: 0.08, count: 3 }
      ];
    }

    for (let rk = 0; rk < ranks.length; rk++) {
      let rank = ranks[rk];
      for (let m = 0; m < rank.count; m++) {
        let vNorm = rank.count === 1 ? 0 : map(m + 0.5, 0, rank.count, -0.88, 0.88);
        // Stagger alternate ranks like fish scales
        if (rk % 2 === 1 && rank.count > 1) {
          vNorm += (0.88 / rank.count) * (m % 2 === 0 ? 0.35 : -0.35);
        }
        vNorm = constrain(vNorm + random(-0.05, 0.05), -0.90, 0.90);

        let uStart = constrain(rank.u0 + random(-0.03, 0.02), 0.04, 0.97);
        let uEnd = constrain(rank.u1 + random(-0.03, 0.03), 0.03, uStart - 0.12);

        // Chevron convergence: vesicles angle slightly inward toward the carpel midline (v=0)
        let vStart = vNorm;
        let vEnd = vNorm * 0.74 + random(-0.04, 0.04);
        let uMid = lerp(uStart, uEnd, 0.55);
        let vMid = lerp(vStart, vEnd, 0.52) + (vNorm >= 0 ? 0.04 : -0.04);

        // If segment has a seed, push or omit vesicles overlapping the seed husk
        if (seed) {
          let du = (uMid - seed.u) / (seed.du * 1.25);
          let dv = (vMid - seed.v) / (seed.dv * 1.25);
          if (du * du + dv * dv < 1.0) continue;

          let duEnd = (uEnd - seed.u) / (seed.du * 1.15);
          let dvEnd = (vEnd - seed.v) / (seed.dv * 1.15);
          if (duEnd * duEnd + dvEnd * dvEnd < 1.0) {
            uEnd = max(seed.u + seed.du * 0.9, uStart - 0.14);
            if (uStart - uEnd < 0.10) continue;
            uMid = lerp(uStart, uEnd, 0.55);
          }
        }

        let p0 = mapUV(uStart, vStart);
        let pM = mapUV(uMid, vMid);
        let p1 = mapUV(uEnd, vEnd);

        // Compute physical pixel width of this vesicle slot
        let slotArcPx = (pM[2] * (span * (PI / 180))) / (rank.count + 0.6);
        let weightMult = constrain(slotArcPx / 11.5, 0.22, 1.35);

        // Botanical pigment variegation across the segment
        let nVal = noise(w.id * 11.3 + s * 0.9, uMid * 2.5, vMid * 2.5);
        let cIdx = floor(constrain(nVal * pal.vesicles.length * 1.25, 0, pal.vesicles.length - 1));
        if (random() < 0.25) cIdx = floor(random(pal.vesicles.length));
        let col = pal.vesicles[cIdx];
        let glowCol = pal.glows[cIdx % pal.glows.length];

        seg.vesicles.push({
          p0: [p0[0], p0[1]],
          pM: [pM[0], pM[1]],
          p1: [p1[0], p1[1]],
          weightMult,
          col,
          glowCol,
          hasHighlight: random() < 0.78
        });
      }
    }

    w.segments.push(seg);
  }
}

function renderCitrusWheel(w, isUnderLayer) {
  renderWheelBaseAndRind(w);
  for (let seg of w.segments) {
    // Dark enamel carpel bed
    brush.noStroke();
    brush.wash(w.pal.segDark, 250);
    drawPolyShape(seg.outerPoly, 0.12);
    brush. wash(seg.midColor, 220);
    drawPolyShape(seg.innerPoly, 0.15);
    brush.noWash();
  }
  renderWheelDetailsAndCloisonne(w, isUnderLayer);
}

function renderWheelBaseAndRind(w) {
  let pal = w.pal;
  let outerPts = [];
  let zestPts = [];
  let pithPts = [];

  const steps = 60;
  for (let i = 0; i < steps; i++) {
    let ang = i * (360 / steps);
    let r = evalWheelRadius(w, ang);
    outerPts.push([w.x + r * cos(ang), w.y + r * sin(ang)]);
    zestPts.push([w.x + r * pal.zestFrac * cos(ang), w.y + r * pal.zestFrac * sin(ang)]);
    pithPts.push([w.x + r * (pal.pithFrac + 0.015) * cos(ang), w.y + r * (pal.pithFrac + 0.015) * sin(ang)]);
  }

  w.outerPts = outerPts;
  w.zestPts = zestPts;

  // 1. Outer flavedo zest enamel wash
  brush.noStroke();
  brush.wash(pal.rindOuter, 255);
  drawPolyShape(outerPts, 0.08);

  // Inner brighter zest band
  let midZestPts = [];
  for (let i = 0; i < steps; i++) {
    let ang = i * (360 / steps);
    let r = evalWheelRadius(w, ang) * lerp(1.0, pal.zestFrac, 0.35);
    midZestPts.push([w.x + r * cos(ang), w.y + r * sin(ang)]);
  }
  brush.wash(pal.rindInner, 235);
  drawPolyShape(midZestPts, 0.08);

  // 2. Gilded ochre-ivory albedo pith bed (becomes the gold cloisonné partition bed)
  brush.wash(CLOISONNE.pithWarm, 250);
  drawPolyShape(zestPts, 0.08);
  brush.wash(CLOISONNE.pithBase, 240);
  drawPolyShape(pithPts, 0.08);
  brush.noWash();
}

function renderAllSegmentEnamels(wheels) {
  // Batch watercolor fills by fruit type for vitrified enamel depth on larger slices
  const types = ["blood_orange", "grapefruit", "lemon", "lime"];

  for (let tName of types) {
    for (let w of wheels) {
      if (w.pal.name !== tName) continue;

      for (let seg of w.segments) {
        // Crisp flat enamel base wash
        brush.noStroke();
        brush.wash(w.pal.segDark, 250);
        drawPolyShape(seg.outerPoly, 0.14);

        brush.wash(seg.midColor, 230);
        drawPolyShape(seg.innerPoly, 0.16);
        brush.noWash();
      }
    }

    // Subtle glassy watercolor glaze pass on hero slices (R > 110)
    for (let w of wheels) {
      if (w.pal.name !== tName || w.r <= 110) continue;
      for (let seg of w.segments) {
        brush.noStroke();
        brush.fill(seg.innerColor, 85);
        brush.fillBleed(0.035, "in");
        brush.fillTexture(0.22, 0.18);
        drawPolyShape(seg.innerPoly, 0.15);
        brush.noFill();
      }
    }
  }
}

function renderWheelDetailsAndCloisonne(w, isUnderLayer) {
  let pal = w.pal;

  // 1. Render hyperreal juice vesicles inside every segment
  for (let seg of w.segments) {
    // Pass 1A: Plump teardrop enamel vesicle bodies
    for (let v of seg.vesicles) {
      brush.set("vesicle_enamel", v.col, v.weightMult);
      brush.spline([
        [v.p0[0], v.p0[1], 0.25],
        [v.pM[0], v.pM[1], 1.30],
        [v.p1[0], v.p1[1], 0.55]
      ], 0.35);

      // Pass 1B: Inner luminous liquid sac glow
      if (w.r > 55) {
        let gx0 = lerp(v.p0[0], v.pM[0], 0.45);
        let gy0 = lerp(v.p0[1], v.pM[1], 0.45);
        let gx1 = lerp(v.pM[0], v.p1[0], 0.78);
        let gy1 = lerp(v.pM[1], v.p1[1], 0.78);
        brush.set("vesicle_glow", v.glowCol, v.weightMult * 0.82);
        brush.line(gx0, gy0, gx1, gy1);
      }
    }

    // Pass 1C: Delicate ochre-gold cloisonné membrane filaments around vesicles
    for (let v of seg.vesicles) {
      let dx = v.p1[0] - v.p0[0];
      let dy = v.p1[1] - v.p0[1];
      let len = max(1, sqrt(dx * dx + dy * dy));
      let nx = -dy / len;
      let ny = dx / len;
      let halfW = v.weightMult * 4.2;

      let side1 = [v.pM[0] + nx * halfW, v.pM[1] + ny * halfW];
      let side2 = [v.pM[0] - nx * halfW, v.pM[1] - ny * halfW];

      // Dark ruby-bronze micro-shadow between cells
      brush.set("rotring", pal.segDark, 0.24);
      brush.spline([v.p0, side2, v.p1], 0.45);

      // Gleaming thin ochre-gold cell wire
      brush.set("rotring", CLOISONNE.wireOchre, 0.28);
      brush.spline([v.p0, side1, v.p1], 0.45);

      // Pass 1D: Moist glistening specular highlights on the plump belly of the vesicle
      if (v.hasHighlight && !isUnderLayer) {
        let hx0 = lerp(v.p0[0], side1[0], 0.58) - nx * halfW * 0.32;
        let hy0 = lerp(v.p0[1], side1[1], 0.58) - ny * halfW * 0.32;
        let hxm = side1[0] - nx * halfW * 0.36;
        let hym = side1[1] - ny * halfW * 0.36;
        let hx1 = lerp(side1[0], v.p1[0], 0.48) - nx * halfW * 0.32;
        let hy1 = lerp(side1[1], v.p1[1], 0.48) - ny * halfW * 0.32;

        brush.set("rotring", pal.highlight, constrain(v.weightMult * 0.48, 0.22, 0.52));
        brush.spline([[hx0, hy0], [hxm, hym], [hx1, hy1]], 0.4);

        // Pinpoint wet bead glint near tip
        if (w.r > 75 && random() < 0.65) {
          let bx = lerp(hxm, v.p1[0], 0.52);
          let by = lerp(hym, v.p1[1], 0.52);
          brush.set("rotring", "#ffffff", constrain(v.weightMult * 0.55, 0.28, 0.6));
          brush.line(bx, by, bx + 0.8, by + 0.8);
        }
      }
    }
  }

  // 2. Render Y-junction cloisonné filigree triangles & radial pith septa
  for (let seg of w.segments) {
    let yj = seg.yJunction;
    brush.noStroke();
    brush.wash(CLOISONNE.pithWarm, 235);
    drawPolyShape([yj.pTip, yj.pLeft, yj.pRight], 0.05);
    brush.noWash();

    // Miniature gold cloisonné boss inside the Y-junction gusset
    if (w.r > 65) {
      brush.set("rotring", CLOISONNE.wireBronze, 0.28);
      brush.circle(yj.bossCenter[0], yj.bossCenter[1], yj.bossR, 0.05);
      brush.set("rotring", CLOISONNE.wireGlint, 0.25);
      brush.arc(yj.bossCenter[0], yj.bossCenter[1], yj.bossR * 0.8, 200, 330);
    }

    // 3-pass raised gold cloisonné wire around every segment boundary
    let shadowPoly = seg.outerPoly.map(p => [p[0] + 1.1, p[1] + 1.1]);
    brush.set("rotring", CLOISONNE.wireShadow, constrain(w.r * 0.0038, 0.3, 0.65));
    drawClosedSpline(shadowPoly, 0.15);

    brush.set("cloisonne_wire", CLOISONNE.wireOchre, constrain(w.r * 0.0045, 0.35, 0.78));
    drawClosedSpline(seg.outerPoly, 0.15);

    brush.set("rotring", CLOISONNE.wireGold, constrain(w.r * 0.0028, 0.22, 0.45));
    drawClosedSpline(seg.outerPoly, 0.15);

    // Central septum spine wire dividing adjacent segments
    let rCore = w.r * pal.coreFrac * 0.92;
    let rZest = evalWheelRadius(w, seg.a1) * pal.zestFrac;
    let sx0 = w.x + rCore * cos(seg.a1);
    let sy0 = w.y + rCore * sin(seg.a1);
    let sx1 = w.x + rZest * cos(seg.a1);
    let sy1 = w.y + rZest * sin(seg.a1);

    brush.set("rotring", CLOISONNE.wireBronze, constrain(w.r * 0.0032, 0.25, 0.52));
    brush.line(sx0 + 0.8, sy0 + 0.8, sx1 + 0.8, sy1 + 0.8);
    brush.set("rotring", CLOISONNE.wireGlint, constrain(w.r * 0.0028, 0.22, 0.42));
    brush.line(sx0, sy0, sx1, sy1);
  }

  // 3. Render sliced seeds (pips) embedded in segments with raised gold husks
  for (let seg of w.segments) {
    if (!seg.seed) continue;
    renderSeedInSegment(w, seg, seg.seed);
  }

  // 4. Render central pith core (columella) with star-rosette & vascular bundles
  renderCentralColumella(w);

  // 5. Render outer zest oil glands and master gold cloisonné rim wires
  renderZestGlandsAndRimWires(w, isUnderLayer);
}

function renderSeedInSegment(w, seg, seed) {
  let huskPoly = [];
  let kernelPoly = [];
  let shadowPoly = [];
  const numPts = 14;

  for (let i = 0; i < numPts; i++) {
    let a = i * (360 / numPts);
    // Teardrop seed cross-section (pointed toward inner core, plump outward)
    let ca = cos(a);
    let sa = sin(a);
    let taper = 0.78 + 0.22 * ca;
    let u = seed.u + seed.du * ca;
    let v = seed.v + seed.dv * sa * taper;

    let pt = seg.mapUV(constrain(u, 0.02, 0.92), constrain(v, -0.92, 0.92));
    huskPoly.push([pt[0], pt[1]]);
    shadowPoly.push([pt[0] + 1.4, pt[1] + 1.4]);

    let uk = seed.u + seed.du * 0.68 * ca;
    let vk = seed.v + seed.dv * 0.65 * sa * taper;
    let ptk = seg.mapUV(constrain(uk, 0.03, 0.90), constrain(vk, -0.90, 0.90));
    kernelPoly.push([ptk[0], ptk[1]]);
  }

  let centerPt = seg.mapUV(seed.u, seed.v);

  // Deep shadow halo in surrounding pulp
  brush.noStroke();
  brush.wash(w.pal.segDark, 235);
  drawPolyShape(shadowPoly, 0.2);

  // Golden-ochre seed husk (testa)
  brush.wash(CLOISONNE.seedHusk, 250);
  drawPolyShape(huskPoly, 0.2);

  // Creamy ivory-citron kernel (cotyledon)
  brush.wash(CLOISONNE.seedKernel, 250);
  drawPolyShape(kernelPoly, 0.2);
  brush.noWash();

  // Warm amber heart inside kernel
  brush.set("vesicle_enamel", CLOISONNE.seedCore, constrain(w.r * 0.004, 0.2, 0.45));
  brush.line(centerPt[0] - 1.5, centerPt[1] - 1.5, centerPt[0] + 1.5, centerPt[1] + 1.5);

  // Double gold cloisonné wire rim on seed husk
  brush.set("rotring", CLOISONNE.wireShadow, 0.42);
  drawClosedSpline(shadowPoly, 0.25);
  brush.set("cloisonne_wire", CLOISONNE.wireOchre, 0.48);
  drawClosedSpline(huskPoly, 0.25);
  brush.set("rotring", CLOISONNE.wireGlint, 0.30);
  drawClosedSpline(kernelPoly, 0.25);

  // Wet specular highlight bead on seed kernel
  brush.set("rotring", "#ffffff", 0.48);
  brush.line(centerPt[0] - 1.2, centerPt[1] - 1.2, centerPt[0] + 0.6, centerPt[1] - 0.2);
}

function renderCentralColumella(w) {
  let pal = w.pal;
  let corePts = [];
  let innerStarPts = [];
  let N = w.numSegs;

  for (let s = 0; s < N; s++) {
    let a0 = w.segAngles[s];
    let aMid = (w.segAngles[s] + w.segAngles[s + 1]) * 0.5;

    // Star-point flare into septum wall
    let rPeak = w.r * pal.coreFrac * (1.06 + 0.08 * noise(w.id * 2.1, s));
    corePts.push([w.x + rPeak * cos(a0), w.y + rPeak * sin(a0)]);

    // Concave indentation at segment apex
    let rValley = w.r * pal.coreFrac * (0.82 + 0.08 * noise(w.id * 4.3, s));
    corePts.push([w.x + rValley * cos(aMid), w.y + rValley * sin(aMid)]);

    let rInPeak = rPeak * 0.38;
    let rInVal = rValley * 0.26;
    innerStarPts.push([w.x + rInPeak * cos(a0), w.y + rInPeak * sin(a0)]);
    innerStarPts.push([w.x + rInVal * cos(aMid), w.y + rInVal * sin(aMid)]);
  }

  // Gilded pith core wash
  brush.noStroke();
  brush.wash(CLOISONNE.pithWarm, 250);
  drawPolyShape(corePts, 0.15);

  // Dark enamel central star-hollow
  brush.wash(pal.segDark, 245);
  drawPolyShape(innerStarPts, 0.15);
  brush.noWash();

  // Cloisonné wire framing of central star core
  brush.set("rotring", CLOISONNE.wireShadow, 0.42);
  drawClosedSpline(corePts.map(p => [p[0] + 0.9, p[1] + 0.9]), 0.2);
  brush.set("cloisonne_wire", CLOISONNE.wireOchre, 0.52);
  drawClosedSpline(corePts, 0.2);
  brush.set("rotring", CLOISONNE.wireGlint, 0.32);
  drawClosedSpline(innerStarPts, 0.2);

  // Ring of tiny vascular bundle beads inside the columella
  if (w.r > 65) {
    for (let s = 0; s < N; s++) {
      let aMid = (w.segAngles[s] + w.segAngles[s + 1]) * 0.5;
      let rDot = w.r * pal.coreFrac * 0.60;
      let dx = w.x + rDot * cos(aMid);
      let dy = w.y + rDot * sin(aMid);
      brush.set("rotring", CLOISONNE.wireBronze, 0.35);
      brush.line(dx, dy, dx + 0.6, dy + 0.6);
      brush.set("rotring", CLOISONNE.wireGlint, 0.28);
      brush.line(dx - 0.3, dy - 0.3, dx, dy);
    }
  }
}

function renderZestGlandsAndRimWires(w, isUnderLayer) {
  let pal = w.pal;

  // 1. Essential oil gland vesicles around the outer zest band
  if (!isUnderLayer && w.r > 48) {
    let glandCount = floor(w.r * 0.55);
    for (let i = 0; i < glandCount; i++) {
      let ang = i * (360 / glandCount) + random(-1.2, 1.2);
      let rBound = evalWheelRadius(w, ang);
      let rGland = rBound * lerp(pal.zestFrac, 1.0, random(0.32, 0.72));
      let gx = w.x + rGland * cos(ang);
      let gy = w.y + rGland * sin(ang);
      let gSize = constrain(w.r * 0.0038, 0.25, 0.62);

      // Luminous oil gland bead
      brush.set("rotring", pal.oilGland, gSize * 1.35);
      brush.line(gx, gy, gx + 0.5, gy + 0.5);

      // Tiny gold wire rim on larger slices
      if (w.r > 105 && i % 2 === 0) {
        brush.set("rotring", CLOISONNE.wireGold, 0.22);
        brush.circle(gx, gy, gSize * 2.2, 0.05);
      }
    }
  }

  // 2. Delicate radial filigree hatching across the albedo pith ring
  if (w.r > 70) {
    let hatchSteps = floor(w.r * 0.75);
    brush.set("rotring", CLOISONNE.pithDeep, 0.22);
    for (let i = 0; i < hatchSteps; i++) {
      let ang = i * (360 / hatchSteps);
      let rBound = evalWheelRadius(w, ang);
      let r0 = rBound * (pal.pithFrac + 0.008);
      let r1 = rBound * (pal.zestFrac - 0.006);
      brush.line(
        w.x + r0 * cos(ang), w.y + r0 * sin(ang),
        w.x + r1 * cos(ang), w.y + r1 * sin(ang)
      );
    }
  }

  // 3. Inner zest-to-pith gold cloisonné wire
  brush.set("rotring", CLOISONNE.wireBronze, constrain(w.r * 0.0038, 0.28, 0.58));
  drawClosedSpline(w.zestPts.map(p => [p[0] + 0.8, p[1] + 0.8]), 0.12);
  brush.set("cloisonne_wire", CLOISONNE.wireOchre, constrain(w.r * 0.0045, 0.35, 0.72));
  drawClosedSpline(w.zestPts, 0.12);
  brush.set("rotring", CLOISONNE.wireGlint, constrain(w.r * 0.0025, 0.20, 0.40));
  drawClosedSpline(w.zestPts, 0.12);

  // 4. Master outer rim gold cloisonné wire locking slices edge-to-edge
  brush.set("rotring", CLOISONNE.wireShadow, constrain(w.r * 0.0055, 0.45, 0.92));
  drawClosedSpline(w.outerPts.map(p => [p[0] + 1.3, p[1] + 1.3]), 0.12);

  brush.set("cloisonne_wire", CLOISONNE.wireOchre, constrain(w.r * 0.0065, 0.55, 1.05));
  drawClosedSpline(w.outerPts, 0.12);

  brush.set("rotring", CLOISONNE.wireGold, constrain(w.r * 0.0040, 0.32, 0.65));
  drawClosedSpline(w.outerPts, 0.12);

  // Specular pale-gold crest along top-left rim arc
  let glintPts = w.outerPts.slice(28, 52);
  if (glintPts.length > 3) {
    brush.set("rotring", CLOISONNE.wireGlint, constrain(w.r * 0.0032, 0.26, 0.52));
    brush.spline(glintPts, 0.15);
  }
}

function drawPolyShape(pts, curvature = 0.1) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function drawClosedSpline(pts, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  let closed = pts.concat([pts[0], pts[1]]);
  brush.spline(closed, curvature);
}

// Hyperreal Coloured Pencil Surrealism:
// Open vintage leather suitcase on an endless cracked salt flat,
// with a calm ocean pouring out of it toward a low off-centre vanishing point.

const VP_X = 275;
const HY = 524;
const FOCAL = 860;
const CAM_Y = 1.38;

// Suitcase 3D anchor & orientation on the ground plane (Y = 0)
const SUIT_X = 2.38;
const SUIT_Z = 4.32;
const SUIT_ANGLE = -11 * (Math.PI / 180);
const COS_A = Math.cos(SUIT_ANGLE);
const SIN_A = Math.sin(SUIT_ANGLE);

const SUIT_W = 1.86;     // u in [-0.93, +0.93]
const SUIT_D = 1.10;     // v in [-0.55, +0.55]
const BASE_H = 0.41;     // height of lower tray
const LID_T = 0.15;      // lid thickness
const LID_ANGLE = 101 * (Math.PI / 180); // open angle from horizontal

// Raking sunlight direction (from low left horizon casting shadows to +X)
const SH_X = 3.65;
const SH_Z = 0.24;

function project(X, Y, Z) {
  const safeZ = Math.max(0.25, Z);
  const s = FOCAL / safeZ;
  return {
    x: VP_X + X * s,
    y: HY + (CAM_Y - Y) * s,
    s: s,
    X: X,
    Y: Y,
    Z: safeZ
  };
}

// Convert suitcase local coordinates (u, y, v) to 3D world coordinates (X, Y, Z)
function suitWorld(u, y, v) {
  return {
    X: SUIT_X + u * COS_A + v * SIN_A,
    Y: y,
    Z: SUIT_Z - u * SIN_A + v * COS_A
  };
}

function suitProject(u, y, v) {
  const w = suitWorld(u, y, v);
  return project(w.X, w.Y, w.Z);
}

// Convert open lid local coordinates (u, s, d) to suitcase local (u, y, v)
// s in [0, SUIT_D] = distance up lid from hinge at (y = BASE_H, v = +SUIT_D/2)
// d in [-LID_T, 0] = depth into lid (0 is front rim facing viewer, -LID_T is outer back leather)
function lidLocal(u, s, d) {
  const sinL = Math.sin(LID_ANGLE);
  const cosL = Math.cos(LID_ANGLE); // negative since > 90 deg
  const upY = sinL;
  const upV = -cosL; // tilts slightly back (+v)
  const normY = -cosL; // points slightly up
  const normV = -sinL; // points forward (-v) toward viewer
  return {
    u: u,
    y: BASE_H + s * upY + d * normY,
    v: SUIT_D * 0.5 + s * upV + d * normV
  };
}

function lidProject(u, s, d) {
  const loc = lidLocal(u, s, d);
  return suitProject(loc.u, loc.y, loc.v);
}

// Project a 3D point onto the ground plane Y = 0 along the raking sun ray
function shadowProject(wPt, extraRun = 1.0) {
  const shX = wPt.X + wPt.Y * SH_X * extraRun;
  const shZ = wPt.Z + wPt.Y * SH_Z * extraRun;
  return project(shX, 0, shZ);
}

function lerp3(a, b, t) {
  return {
    X: a.X + (b.X - a.X) * t,
    Y: a.Y + (b.Y - a.Y) * t,
    Z: a.Z + (b.Z - a.Z) * t
  };
}

function bilerp3(p00, p10, p11, p01, u, v) {
  const top = lerp3(p00, p10, u);
  const bot = lerp3(p01, p11, u);
  return lerp3(top, bot, v);
}

function hexToRgb(hex) {
  const h = hex.replace("#", "");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgbToHex(r, g, b) {
  const c = (v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0");
  return "#" + c(r) + c(g) + c(b);
}

function mixHex(c1, c2, t) {
  const a = hexToRgb(c1);
  const b = hexToRgb(c2);
  const k = Math.max(0, Math.min(1, t));
  return rgbToHex(
    a[0] + (b[0] - a[0]) * k,
    a[1] + (b[1] - a[1]) * k,
    a[2] + (b[2] - a[2]) * k
  );
}

// Multi-stop color gradient sampler
function sampleGradient(stops, t) {
  const clamped = Math.max(0, Math.min(1, t));
  for (let i = 0; i < stops.length - 1; i++) {
    if (clamped >= stops[i].pos && clamped <= stops[i + 1].pos) {
      const localT = (clamped - stops[i].pos) / (stops[i + 1].pos - stops[i].pos || 1);
      return mixHex(stops[i].col, stops[i + 1].col, localT);
    }
  }
  return stops[stops.length - 1].col;
}

// Ocean centerline and half-width in ground coordinates (X, Z)
function oceanCenterX(Z) {
  const t = Math.max(0, (Z - 4.15) / 76.0);
  const baseCurve = 1.48 * Math.pow(4.15 / Math.max(3.8, Z), 0.78);
  const meander = 0.16 * Math.sin((Z - 4.15) * 0.32) * Math.exp(-t * 2.2);
  return baseCurve + meander;
}

function oceanHalfWidth(Z) {
  if (Z < 4.15) {
    return 0.78 * Math.max(0.2, 1.0 - (4.15 - Z) * 1.15);
  }
  return 0.78 + 0.125 * Math.pow(Z - 4.15, 0.85);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88412);

  // Fine burnished coloured-pencil custom tip
  brush.add("cpencil_fine", {
    type: "default",
    weight: 0.32,
    scatter: 0.08,
    sharpness: 0.78,
    grain: 12,
    opacity: 165,
    spacing: 0.14,
    pressure: [0.35, 1.05, 0.35],
    noise: 0.3
  });

  // Soft wax blender pencil tip for burnished tonal transitions
  brush.add("wax_burnish", {
    type: "default",
    weight: 1.15,
    scatter: 0.35,
    sharpness: 0.32,
    grain: 18,
    opacity: 68,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.2
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#F4EFE2");

  // 1. SKY: Burnished gradient from pale cobalt at zenith to Naples yellow at horizon
  drawSky();

  // 2. ENDLESS CRACKED SALT FLAT: Tonal ground base + 3D perspective polygonal salt crusts
  drawSaltFlatBase();
  drawSaltPolygons();

  // 3. LONG RAKING SHADOW OF THE SUITCASE across the salt flat
  drawSuitcaseRakingShadow();

  // 4. DISTANT & MIDGROUND OCEAN CHANNEL pouring toward the horizon
  drawOceanChannel();

  // 5. OPEN VINTAGE LEATHER SUITCASE (Lid, striped lining, leather body, straps, brass clasps)
  drawSuitcase();

  // 6. OCEAN INSIDE SUITCASE & TINY WAVES FOAMING AT THE LIP
  drawSuitcaseOceanAndFoamLip();

  // 7. FINAL HYPERREAL BURNISHING & ATMOSPHERIC GLAZES
  drawFinalBurnishDetails();

  noLoop();
}

// =============================================================================
// 1. SKY: PALE COBALT TO NAPLES YELLOW
// =============================================================================
const SKY_STOPS = [
  { pos: 0.00, col: "#5D7D9E" }, // Deep pale cobalt at zenith
  { pos: 0.22, col: "#7291B0" }, // Muted cobalt blue
  { pos: 0.45, col: "#8FA9C0" }, // Powder cobalt-slate
  { pos: 0.66, col: "#B4C3CB" }, // Hazy mineral celadon-grey
  { pos: 0.82, col: "#DACFB9" }, // Warm parchment transition
  { pos: 0.93, col: "#EEDBA3" }, // Luminous Naples yellow
  { pos: 1.00, col: "#F7E7B4" }  // Bright horizon Naples yellow
];

function drawSky() {
  brush.noStroke();
  brush.noHatch();

  // Base tonal wash bands
  const bands = 75;
  const bandH = (HY + 8) / bands;
  for (let i = 0; i < bands; i++) {
    const t = i / (bands - 1);
    const col = sampleGradient(SKY_STOPS, t);
    brush.wash(col, 235);
    brush.rect(-10, i * bandH - 2, width + 20, bandH + 6, "corner");
  }

  // Low off-centre solar glow in Naples yellow / cream near (VP_X - 55, HY)
  const glowX = VP_X - 55;
  const glowY = HY - 18;
  for (let r = 460; r >= 40; r -= 35) {
    const t = 1 - r / 460;
    const col = mixHex("#F3E1AA", "#FFF7DA", t);
    brush.wash(col, 14 + t * 14);
    brush.circle(glowX, glowY, r, 0.02);
  }
  brush.noWash();

  // Dense burnished coloured pencil strokes across the sky
  // Pass 1: Soft wax burnisher for seamless paper tooth saturation
  for (let i = 0; i < 420; i++) {
    const y = random(-5, HY + 2);
    const t = constrain(y / HY, 0, 1);
    const jitterT = constrain(t + random(-0.04, 0.04), 0, 1);
    let col = sampleGradient(SKY_STOPS, jitterT);
    const x1 = random(-40, width - 160);
    const len = random(180, 460);
    const x2 = Math.min(width + 40, x1 + len);
    const dy = random(-4, 4);

    // Warm near the left horizon sun
    const distToSun = dist((x1 + x2) * 0.5, y, glowX, glowY);
    if (distToSun < 380) {
      col = mixHex(col, "#FFF3C8", (1 - distToSun / 380) * 0.45);
    }

    brush.set("wax_burnish", col, random(0.85, 1.45));
    brush.line(x1, y, x2, y + dy);
  }

  // Pass 2: Fine directional coloured pencil grain (slight cross-hatch at ±2 deg)
  for (let i = 0; i < 620; i++) {
    const u = Math.pow(random(), 0.92);
    const y = u * HY;
    const t = constrain(y / HY, 0, 1);
    const shift = random(-0.05, 0.05);
    let col = sampleGradient(SKY_STOPS, constrain(t + shift, 0, 1));
    const x1 = random(-30, width - 80);
    const span = random(90, 290);
    const x2 = x1 + span;
    const slope = random(-3.2, 3.2);

    const distToSun = dist(x1 + span * 0.5, y, glowX, glowY);
    if (distToSun < 320) {
      col = mixHex(col, "#FFF8DE", (1 - distToSun / 320) * 0.5);
    }

    brush.set("cpencil", col, random(0.35, 0.72));
    brush.line(x1, y, x2, y + slope);
  }

  // Crisp, quiet horizon glow line
  for (let i = 0; i < 45; i++) {
    const x1 = random(-20, width - 100);
    const x2 = x1 + random(120, 320);
    const y = HY + random(-2.5, 2.5);
    const col = mixHex("#F5E4B0", "#D5DCE2", constrain((x1 - 200) / 900, 0, 0.65));
    brush.set("cpencil_fine", col, random(0.4, 0.75));
    brush.line(x1, y, x2, y);
  }
}

// =============================================================================
// 2. ENDLESS CRACKED SALT FLAT
// =============================================================================
const SALT_STOPS = [
  { pos: 0.00, col: "#E9DFC8" }, // Horizon: catches Naples yellow
  { pos: 0.12, col: "#DCE0E2" }, // Far distance: pale mineral silver
  { pos: 0.35, col: "#D3DBE2" }, // Midground: cool alabaster slate
  { pos: 0.68, col: "#DDE2E6" }, // Near midground: bone white & cool grey
  { pos: 1.00, col: "#E4E5E0" }  // Foreground: warm bone crust
];

function drawSaltFlatBase() {
  brush.noStroke();
  brush.noHatch();

  const bands = 55;
  const totalH = height - HY;
  const bandH = totalH / bands;
  for (let i = 0; i < bands; i++) {
    const t = i / (bands - 1);
    const col = sampleGradient(SALT_STOPS, t);
    brush.wash(col, 240);
    brush.rect(-10, HY + i * bandH - 1, width + 20, bandH + 4, "corner");
  }
  brush.noWash();

  // Burnished directional pencil base across the flat (radiating + horizontal)
  for (let i = 0; i < 380; i++) {
    const t = Math.pow(random(), 1.35);
    const y = HY + 3 + t * (height - HY - 3);
    const x = random(-20, width + 20);
    const span = 60 + t * 220;
    const baseCol = sampleGradient(SALT_STOPS, t);
    // Warmer on left (sunlit), cooler slate on right
    const lr = constrain(x / width, 0, 1);
    const col = mixHex(
      mixHex(baseCol, "#F7EBC8", 0.25 * (1 - lr)),
      "#B9C6D3",
      0.32 * lr + random(-0.08, 0.08)
    );
    brush.set("wax_burnish", col, 0.55 + t * 0.75);
    brush.line(x - span * 0.5, y, x + span * 0.5, y + random(-2, 2));
  }
}

function drawSaltPolygons() {
  // Build a topological hexagonal tiling in ground coordinates (X, Z)
  // Every shared vertex is jittered once so adjacent 6-sided polygons share exact ridges.
  const nRows = 29;
  const nCols = 32;
  const zRows = [];
  for (let r = 0; r <= nRows + 1; r++) {
    // Z progresses geometrically from 1.28 (foreground y=1200) to 34.0 (near horizon y=545)
    zRows.push(1.28 * Math.pow(1.116, r));
  }

  // Vertex grid: for each cell (r, c), a hexagon uses 6 vertices from a shared dual grid
  // Using a brick-wall topological equivalence where each cell (r, c) has 6 shared vertices:
  // Top-left, Top-mid, Top-right, Bot-right, Bot-mid, Bot-left.
  const vGrid = [];
  for (let r = 0; r <= nRows + 1; r++) {
    const Z0 = zRows[r];
    const Z1 = zRows[Math.min(nRows + 1, r + 1)];
    const dZ = Z1 - Z0;
    // Physical cell width grows gently with Z so distant polygons remain crisp while foreshortening
    const cellW = 0.52 + 0.032 * Z0;
    const rowArr = [];
    const shift = (r % 2) * 0.5;

    for (let k = 0; k <= nCols * 2 + 4; k++) {
      const uCol = (k * 0.5 - nCols * 0.5 + shift - 1.5);
      const baseX = (uCol + 1.8) * cellW;
      // Alternating ridge peaks for hexagonal crown shape
      const isPeak = ((k + r) % 2 === 0);
      const baseZ = Z0 + (isPeak ? -0.16 : 0.16) * dZ;

      const nVal1 = noise(r * 0.43 + 11.2, k * 0.37 + 5.7) - 0.5;
      const nVal2 = noise(r * 0.39 + 47.1, k * 0.41 + 19.3) - 0.5;

      const X = baseX + nVal1 * cellW * 0.42;
      const Z = Math.max(1.18, baseZ + nVal2 * dZ * 0.44);
      rowArr.push(project(X, 0, Z));
    }
    vGrid.push(rowArr);
  }

  // Render from horizon (far r) to foreground (near r = 0)
  for (let r = nRows - 1; r >= 0; r--) {
    const depthT = 1 - r / (nRows - 1); // 0 at horizon, 1 at foreground
    for (let c = 0; c < nCols; c++) {
      const k = c * 2 + (r % 2);
      const p0 = vGrid[r][k];         // front-left
      const p1 = vGrid[r][k + 1];     // front-mid
      const p2 = vGrid[r][k + 2];     // front-right
      const p3 = vGrid[r + 1][k + 2]; // back-right
      const p4 = vGrid[r + 1][k + 1]; // back-mid
      const p5 = vGrid[r + 1][k];     // back-left

      if (!p0 || !p1 || !p2 || !p3 || !p4 || !p5) continue;
      const pts = [p0, p1, p2, p3, p4, p5];

      // Bounding box check on screen
      let minX = 9999, maxX = -9999, minY = 9999, maxY = -9999;
      let cx = 0, cy = 0, cXWorld = 0, cZWorld = 0;
      for (let i = 0; i < 6; i++) {
        minX = Math.min(minX, pts[i].x);
        maxX = Math.max(maxX, pts[i].x);
        minY = Math.min(minY, pts[i].y);
        maxY = Math.max(maxY, pts[i].y);
        cx += pts[i].x;
        cy += pts[i].y;
        cXWorld += pts[i].X;
        cZWorld += pts[i].Z;
      }
      if (maxX < -60 || minX > width + 60 || maxY < HY || minY > height + 60) continue;
      cx /= 6;
      cy /= 6;
      cXWorld /= 6;
      cZWorld /= 6;

      // Check proximity to ocean stream so submerged center cells are skipped or muted
      const ocX = oceanCenterX(cZWorld);
      const ocHW = oceanHalfWidth(cZWorld);
      const distToOcean = Math.abs(cXWorld - ocX);
      if (cZWorld > 4.05 && distToOcean < ocHW * 0.62) continue;

      const isWetBank = (cZWorld > 3.9 && distToOcean < ocHW * 1.28);

      // Concave salt pan shading: left side of cell sits in the slight raking shadow of its left ridge
      const polyCoords = pts.map(p => [p.x, p.y]);
      const cellNoise = noise(c * 0.35, r * 0.35);

      if (depthT > 0.18) {
        let panCol = mixHex("#D2DBE3", "#E9E7DF", cellNoise);
        if (isWetBank) {
          panCol = mixHex(panCol, "#8899A8", 0.45);
        }
        const poly = new brush.Polygon(polyCoords);
        poly.wash(panCol, isWetBank ? 130 : 75);

        // Burnished coloured-pencil hatching inside foreground & midground salt pans
        if (depthT > 0.38 && maxX - minX > 28) {
          const hatchCol = isWetBank
            ? mixHex("#6C8094", "#92A3B2", cellNoise)
            : mixHex("#B8C5D1", "#EDE8DA", cellNoise);
          const spacing = map(depthT, 0.38, 1.0, 7.5, 4.2);
          brush.hatchStyle("cpencil_fine", hatchCol, map(depthT, 0.38, 1.0, 0.35, 0.58));
          poly.hatch(spacing, -4 + (cellNoise - 0.5) * 10, { rand: 0.06, gradient: 0.35 });
          brush.noHatch();
        }
      }

      // Draw each of the 6 raised salt-crust edges with raking shadow + sunlit crystalline crest
      const shadowOffset = (1.2 + depthT * 7.5);
      const ridgeW = 0.28 + depthT * 0.65;

      for (let e = 0; e < 6; e++) {
        // Draw each shared edge once (e = 0, 1, 2, 5) to avoid doubling, plus full foreground detail
        if (e === 3 || e === 4) continue;
        const a = pts[e];
        const b = pts[(e + 1) % 6];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const len = Math.hypot(dx, dy);
        if (len < 3) continue;

        // Steepness to sun (edges with larger |dy| block low left sunlight more strongly)
        const blockFactor = constrain(Math.abs(dy) / (len + 0.001) + 0.35, 0.25, 1.0);

        // 1. Long raking shadow to the right (+x) of the raised salt ridge
        const shCol = isWetBank
          ? "#4E6378"
          : mixHex("#8698AA", "#556A80", depthT * blockFactor);
        brush.set("cpencil", shCol, ridgeW * (0.85 + blockFactor * 0.55));
        brush.line(
          a.x + shadowOffset * 0.55,
          a.y + 0.6,
          b.x + shadowOffset * 0.55,
          b.y + 0.6
        );

        if (depthT > 0.45) {
          // Secondary softer shadow penumbra
          brush.set("cpencil_fine", mixHex(shCol, "#B5C2CE", 0.45), ridgeW * 0.7);
          brush.line(
            a.x + shadowOffset * 1.05,
            a.y + 1.1,
            b.x + shadowOffset * 1.05,
            b.y + 1.1
          );
        }

        // 2. Dark crack fissure right inside the salt seam
        if (depthT > 0.25) {
          brush.set("cpencil_fine", "#485B6E", ridgeW * 0.48);
          brush.line(a.x + 0.8, a.y + 0.3, b.x + 0.8, b.y + 0.3);
        }

        // 3. Sunlit crystalline salt ridge crest (catching warm Naples-cream raking sun)
        const crestCol = isWetBank
          ? "#DCE2E6"
          : mixHex("#F2ECE0", "#FFFDF4", depthT);
        brush.set("cpencil", crestCol, ridgeW * 0.95);
        brush.line(a.x, a.y, b.x, b.y);

        // 4. Foreground hyperreal salt nodules & encrusted texture bumps along the ridge
        if (depthT > 0.55 && len > 18) {
          const steps = Math.floor(len / 9);
          for (let s = 1; s < steps; s++) {
            const u = s / steps;
            const px = a.x + dx * u + random(-1.2, 1.2);
            const py = a.y + dy * u + random(-1.0, 1.0);
            const bumpH = random(1.8, 4.2) * depthT;
            // Shadow side of nodule
            brush.set("cpencil_fine", "#5D7287", 0.55);
            brush.line(px + 1.2, py, px + bumpH * 1.9, py + 0.6);
            // Sunlit left facet of salt crystal nodule
            brush.set("cpencil_fine", "#FFFDF7", 0.72);
            brush.line(px - 1.2, py + 0.4, px + 0.5, py - bumpH * 0.45);
          }
        }
      }
    }
  }
}

// =============================================================================
// 3. LONG RAKING SHADOW OF THE SUITCASE
// =============================================================================
function drawSuitcaseRakingShadow() {
  // Compute shadow footprint of base box + open upright lid on ground plane Y = 0
  const bFR = suitWorld(SUIT_W * 0.5, 0, -SUIT_D * 0.5);
  const bBR = suitWorld(SUIT_W * 0.5, 0, SUIT_D * 0.5);
  const bFL = suitWorld(-SUIT_W * 0.5, 0, -SUIT_D * 0.5);

  const bTopFL = suitWorld(-SUIT_W * 0.5, BASE_H, -SUIT_D * 0.5);
  const bTopFR = suitWorld(SUIT_W * 0.5, BASE_H, -SUIT_D * 0.5);

  const lTopL = suitWorld(
    lidLocal(-SUIT_W * 0.5, SUIT_D, -LID_T).u,
    lidLocal(-SUIT_W * 0.5, SUIT_D, -LID_T).y,
    lidLocal(-SUIT_W * 0.5, SUIT_D, -LID_T).v
  );
  const lTopR = suitWorld(
    lidLocal(SUIT_W * 0.5, SUIT_D, -LID_T).u,
    lidLocal(SUIT_W * 0.5, SUIT_D, -LID_T).y,
    lidLocal(SUIT_W * 0.5, SUIT_D, -LID_T).v
  );
  const lBotR = suitWorld(
    lidLocal(SUIT_W * 0.5, 0, -LID_T).u,
    lidLocal(SUIT_W * 0.5, 0, -LID_T).y,
    lidLocal(SUIT_W * 0.5, 0, -LID_T).v
  );

  // Soft multi-pass solar penumbra + dark umbra core
  const penumbraScales = [1.08, 1.04, 1.00, 0.96];
  const alphas = [45, 65, 95, 110];
  const cols = ["#6A7E92", "#556A80", "#41566B", "#314559"];

  for (let i = 0; i < penumbraScales.length; i++) {
    const sc = penumbraScales[i];
    const pFR = project(bFR.X, 0, bFR.Z);
    const pFL = project(bFL.X, 0, bFL.Z);
    const sTopFL = shadowProject(bTopFL, sc);
    const sLidL = shadowProject(lTopL, sc);
    const sLidR = shadowProject(lTopR, sc);
    const sBotR = shadowProject(lBotR, sc);
    const sTopFR = shadowProject(bTopFR, sc);

    const shPoly = new brush.Polygon([
      [pFL.x, pFL.y],
      [sTopFL.x, sTopFL.y],
      [sLidL.x, sLidL.y],
      [sLidR.x, sLidR.y],
      [sBotR.x, sBotR.y],
      [sTopFR.x, sTopFR.y],
      [pFR.x, pFR.y]
    ]);
    shPoly.wash(cols[i], alphas[i]);

    if (i === 2) {
      brush.hatchStyle("cpencil", "#2D4054", 0.52);
      shPoly.hatch(4.5, 3, { rand: 0.05, gradient: 0.25 });
      brush.noHatch();
    }
    if (i === 3) {
      brush.hatchStyle("cpencil_fine", "#1F3144", 0.42);
      shPoly.hatch(5.5, -14, { rand: 0.04, gradient: 0.35 });
      brush.noHatch();
    }
  }

  // Re-establish faint salt-crust ridges inside the cast shadow (key hyperreal detail)
  const pStart = project(bFR.X, 0, bFR.Z);
  const pEnd = shadowProject(lTopR, 1.0);
  for (let i = 0; i < 65; i++) {
    const t = random(0.05, 0.95);
    const sx = lerp(pStart.x - 40, Math.min(width + 30, pEnd.x), t);
    const sy = lerp(pStart.y - 110, pStart.y + 5, random());
    const len = random(18, 52);
    const ang = random(-15, 25) * (Math.PI / 180);
    const ex = sx + Math.cos(ang) * len;
    const ey = sy + Math.sin(ang) * len * 0.35;
    brush.set("cpencil_fine", "#5D738A", 0.42);
    brush.line(sx, sy, ex, ey);
    brush.set("cpencil_fine", "#1E2F42", 0.48);
    brush.line(sx + 2, sy + 0.8, ex + 2, ey + 0.8);
  }
}

// =============================================================================
// 4. CALM OCEAN CHANNEL POURING TOWARD THE HORIZON
// =============================================================================
function drawOceanChannel() {
  const nSteps = 95;
  const zMin = 4.02;
  const zMax = 88.0;

  const leftBank = [];
  const rightBank = [];
  const wetLeft = [];
  const wetRight = [];
  const innerLeft = [];
  const innerRight = [];

  for (let i = 0; i <= nSteps; i++) {
    const u = i / nSteps;
    // Non-linear Z sampling for high resolution in foreground and smooth horizon convergence
    const Z = zMin * Math.pow(zMax / zMin, Math.pow(u, 1.35));
    const cX = oceanCenterX(Z);
    const hw = oceanHalfWidth(Z);
    const edgeJitterL = (noise(i * 0.22, 1.7) - 0.5) * hw * 0.18;
    const edgeJitterR = (noise(i * 0.22, 8.3) - 0.5) * hw * 0.18;

    const xl = cX - hw + edgeJitterL;
    const xr = cX + hw + edgeJitterR;

    const pL = project(xl, 0, Z);
    const pR = project(xr, 0, Z);
    leftBank.push([pL.x, pL.y]);
    rightBank.push([pR.x, pR.y]);

    const pWL = project(xl - hw * 0.18, 0, Z);
    const pWR = project(xr + hw * 0.22, 0, Z);
    wetLeft.push([pWL.x, pWL.y]);
    wetRight.push([pWR.x, pWR.y]);

    const pIL = project(cX - (hw - edgeJitterL) * 0.72, 0, Z);
    const pIR = project(cX + (hw + edgeJitterR) * 0.72, 0, Z);
    innerLeft.push([pIL.x, pIL.y]);
    innerRight.push([pIR.x, pIR.y]);
  }

  // 1. Wet salt flat seepage border
  const wetPts = wetLeft.concat(wetRight.slice().reverse());
  const wetPoly = new brush.Polygon(wetPts);
  wetPoly.wash("#8F9FA9", 115);

  // 2. Shallow turquoise-cobalt margin over submerged white salt
  const bankPts = leftBank.concat(rightBank.slice().reverse());
  const oceanPoly = new brush.Polygon(bankPts);
  oceanPoly.wash("#466E85", 210);

  // 3. Deep calm cobalt-Prussian core
  const corePts = innerLeft.concat(innerRight.slice().reverse());
  const corePoly = new brush.Polygon(corePts);
  corePoly.wash("#1F4260", 220);

  // 4. Dense burnished coloured-pencil water surface, sky reflections & wavelets
  const totalRows = 240;
  for (let r = 0; r < totalRows; r++) {
    const t = r / (totalRows - 1); // 0 near suitcase, 1 at horizon
    const Z = zMin * Math.pow(zMax / zMin, Math.pow(t, 1.15));
    const cX = oceanCenterX(Z);
    const hw = oceanHalfWidth(Z);

    const pL = project(cX - hw * 0.96, 0, Z);
    const pR = project(cX + hw * 0.96, 0, Z);
    const y = pL.y;
    const spanW = pR.x - pL.x;
    if (spanW < 1.5) continue;

    // Base water pencil stroke across channel width
    const swell = Math.sin(Z * 3.4 + r * 0.5);
    const deepCol = sampleGradient([
      { pos: 0.0, col: "#17344E" },
      { pos: 0.4, col: "#254C6D" },
      { pos: 0.75, col: "#466E8B" },
      { pos: 1.0, col: "#7C9BB2" }
    ], t);

    // Draw 3-5 overlapping coloured pencil segments across the width at this Z
    const segs = t < 0.4 ? 5 : 3;
    for (let s = 0; s < segs; s++) {
      const u0 = constrain((s + random(-0.2, 0.1)) / segs, 0, 0.95);
      const u1 = constrain((s + 1 + random(-0.1, 0.2)) / segs, 0.05, 1);
      const x0 = lerp(pL.x, pR.x, u0);
      const x1 = lerp(pL.x, pR.x, u1);
      const midU = (u0 + u1) * 0.5;
      const edgeDist = Math.min(midU, 1 - midU) * 2; // 0 at shore, 1 at center

      let strokeCol = mixHex("#537D91", deepCol, Math.pow(edgeDist, 0.55));
      if (swell > 0.25 && edgeDist > 0.35) {
        // Reflect Naples yellow & pale sky cobalt in the calm swells
        const reflCol = mixHex("#9BB7CC", "#F3E1AC", Math.pow(1 - edgeDist * 0.5, 1.2) * (0.45 + 0.45 * t));
        strokeCol = mixHex(strokeCol, reflCol, (swell - 0.25) * 0.75);
      }

      brush.set("cpencil", strokeCol, map(t, 0, 1, 0.68, 0.28));
      brush.line(x0, y + random(-0.6, 0.6), x1, y + random(-0.6, 0.6));
    }

    // Sunlit Naples-yellow & cream shimmer streaks along the center-left flow line
    if (r % 2 === 0) {
      const shimmerU = 0.28 + 0.24 * noise(r * 0.18, 4.2);
      const sx0 = lerp(pL.x, pR.x, shimmerU - 0.11);
      const sx1 = lerp(pL.x, pR.x, shimmerU + 0.11);
      const shimCol = mixHex("#F5E5B3", "#D8E5EE", random(0.15, 0.65));
      brush.set("cpencil_fine", shimCol, map(t, 0, 1, 0.58, 0.25));
      brush.line(sx0, y, sx1, y);
    }

    // Lacy white foam trails &shoreline meniscus
    if (r % 3 === 0 && t < 0.78) {
      const foamW = Math.max(2, spanW * 0.06);
      brush.set("cpencil_fine", "#F4F6F6", map(t, 0, 0.8, 0.55, 0.25));
      brush.line(pL.x, y, pL.x + foamW, y + 0.4);
      brush.line(pR.x - foamW, y + 0.4, pR.x, y);

      // Raking shadow on the right bank lip
      brush.set("cpencil_fine", "#2C455C", map(t, 0, 0.8, 0.52, 0.25));
      brush.line(pR.x, y - 0.5, pR.x + foamW * 1.1, y + 0.3);
    }
  }

  // Perspective flow lines (foam ribbons) converging from suitcase splash pool to VP
  for (let f = 0; f < 14; f++) {
    const lane = map(f, 0, 13, -0.78, 0.78);
    const pts = [];
    for (let s = 0; s <= 26; s++) {
      const u = s / 26;
      const Z = 4.05 * Math.pow(36.0 / 4.05, u);
      const cX = oceanCenterX(Z);
      const hw = oceanHalfWidth(Z);
      const wobble = (noise(f * 2.1, s * 0.35) - 0.5) * 0.16 * hw;
      const p = project(cX + lane * hw + wobble, 0, Z);
      pts.push([p.x, p.y, map(u, 0, 1, 0.9, 0.2)]);
    }
    const col = f % 2 === 0 ? "#EBF1F5" : "#8FB0C6";
    brush.set("cpencil_fine", col, 0.38);
    brush.spline(pts, 0.4);
  }
}

// =============================================================================
// 5. OPEN VINTAGE LEATHER SUITCASE
// =============================================================================
// Helper: Draw a 3D quad with wash + dense perspective coloured pencil lines
function drawTexturedQuad3D(p00, p10, p11, p01, opts) {
  const s00 = project(p00.X, p00.Y, p00.Z);
  const s10 = project(p10.X, p10.Y, p10.Z);
  const s11 = project(p11.X, p11.Y, p11.Z);
  const s01 = project(p01.X, p01.Y, p01.Z);

  const poly = new brush.Polygon([
    [s00.x, s00.y],
    [s10.x, s10.y],
    [s11.x, s11.y],
    [s01.x, s01.y]
  ]);

  if (opts.washCol) {
    poly.wash(opts.washCol, opts.washAlpha !== undefined ? opts.washAlpha : 235);
  }

  // Primary perspective-aligned coloured pencil strokes
  if (opts.linesU) {
    const n = opts.linesU;
    const bName = opts.brushName || "cpencil";
    for (let i = 0; i <= n; i++) {
      const v = i / n;
      const a3 = lerp3(p00, p01, v);
      const b3 = lerp3(p10, p11, v);
      const sa = project(a3.X, a3.Y, a3.Z);
      const sb = project(b3.X, b3.Y, b3.Z);
      const col = typeof opts.colFn === "function" ? opts.colFn(v, i) : opts.strokeCol;
      const w = typeof opts.weightFn === "function" ? opts.weightFn(v, i) : (opts.weight || 0.5);
      brush.set(bName, col, w);
      brush.line(sa.x, sa.y, sb.x, sb.y);
    }
  }

  if (opts.linesV) {
    const n = opts.linesV;
    const bName = opts.brushNameV || opts.brushName || "cpencil";
    for (let i = 0; i <= n; i++) {
      const u = i / n;
      const a3 = lerp3(p00, p10, u);
      const b3 = lerp3(p01, p11, u);
      const sa = project(a3.X, a3.Y, a3.Z);
      const sb = project(b3.X, b3.Y, b3.Z);
      const col = typeof opts.colFnV === "function" ? opts.colFnV(u, i) : (opts.strokeColV || opts.strokeCol);
      const w = typeof opts.weightFnV === "function" ? opts.weightFnV(u, i) : (opts.weight || 0.5);
      brush.set(bName, col, w);
      brush.line(sa.x, sa.y, sb.x, sb.y);
    }
  }

  if (opts.outlineCol) {
    poly.draw(opts.outlineBrush || "cpencil_fine", opts.outlineCol, opts.outlineWeight || 0.55);
  }
  return poly;
}

function lidWorld(u, s, d) {
  const loc = lidLocal(u, s, d);
  return suitWorld(loc.u, loc.y, loc.v);
}

function drawSuitcase() {
  const hw = SUIT_W * 0.5; // 0.93
  const hd = SUIT_D * 0.5; // 0.55
  const rim = 0.065;       // leather frame border thickness
  const recess = -0.105;   // recessed depth of striped lining inside lid

  // ---------------------------------------------------------------------------
  // A. OPEN UPRIGHT LID: Exterior Left Wall, Recessed Striped Lining, Inner Walls
  // ---------------------------------------------------------------------------

  // 1. Left exterior thickness wall of the open lid (facing low sun on the left!)
  drawTexturedQuad3D(
    lidWorld(-hw, 0, -LID_T),
    lidWorld(-hw, 0, 0),
    lidWorld(-hw, SUIT_D, 0),
    lidWorld(-hw, SUIT_D, -LID_T),
    {
      washCol: "#D68E49",
      washAlpha: 245,
      linesV: 18,
      brushName: "cpencil",
      colFnV: (u) => mixHex("#B56827", "#EAB06E", 1 - Math.abs(u - 0.65)),
      weight: 0.52,
      linesU: 36,
      colFn: (v) => mixHex("#C87C38", "#F3C382", 0.3 + 0.5 * noise(v * 8)),
      outlineCol: "#6A3310",
      outlineWeight: 0.6
    }
  );

  // Top exterior thickness sliver of the open lid
  drawTexturedQuad3D(
    lidWorld(-hw, SUIT_D, -LID_T),
    lidWorld(hw, SUIT_D, -LID_T),
    lidWorld(hw, SUIT_D, 0),
    lidWorld(-hw, SUIT_D, 0),
    {
      washCol: "#C77D39",
      washAlpha: 240,
      linesU: 10,
      colFn: (v) => mixHex("#8F4A1A", "#E3A35E", v),
      weight: 0.48,
      outlineCol: "#5E2B0C"
    }
  );

  // 2. Recessed Striped Fabric Lining inside the Open Lid
  const uL = -hw + rim;
  const uR = hw - rim;
  const sB = rim * 0.85;
  const sT = SUIT_D - rim;

  // Base cream wash of lining panel
  const l00 = lidWorld(uL, sB, recess);
  const l10 = lidWorld(uR, sB, recess);
  const l11 = lidWorld(uR, sT, recess);
  const l01 = lidWorld(uL, sT, recess);

  drawTexturedQuad3D(l00, l10, l11, l01, {
    washCol: "#EBE3D0",
    washAlpha: 245
  });

  // Draw hyperreal vertical ticking stripes across the recessed lid panel
  const numStripes = 29;
  for (let i = 0; i < numStripes; i++) {
    const u0 = i / numStripes;
    const u1 = (i + 1) / numStripes;
    const ua = lerp(uL, uR, u0);
    const ub = lerp(uL, uR, u1);
    const isBlueStripe = (i % 2 === 1);

    // Subtle shadow cast from the left inner rim wall onto the left side of the lining
    const rimShadow = u0 < 0.14 ? (1 - u0 / 0.14) * 0.42 : 0;
    const baseStripeCol = isBlueStripe ? "#4B647B" : "#EFE7D4";
    const shadedCol = mixHex(baseStripeCol, "#2B3B4B", rimShadow);

    const pA0 = lidWorld(ua, sB, recess);
    const pB0 = lidWorld(ub, sB, recess);
    const pB1 = lidWorld(ub, sT, recess);
    const pA1 = lidWorld(ua, sT, recess);

    drawTexturedQuad3D(pA0, pB0, pB1, pA1, {
      washCol: shadedCol,
      washAlpha: 230,
      linesV: 4,
      brushName: "cpencil_fine",
      colFnV: (f) => {
        // Warm sepia pinstripe along the edge of each blue stripe
        if (isBlueStripe && (f < 0.15 || f > 0.85)) return mixHex("#8A623E", "#2B3B4B", rimShadow);
        return mixHex(shadedCol, isBlueStripe ? "#354B60" : "#DFD4BE", random(0.15, 0.45));
      },
      weight: 0.42
    });
  }

  // Horizontal fabric weave & subtle top-down recess shading on the striped lining
  drawTexturedQuad3D(l00, l10, l11, l01, {
    linesU: 34,
    brushName: "cpencil_fine",
    colFn: (v) => v > 0.82 ? "#3E5163" : (v < 0.18 ? "#7D7364" : "#C9C0AE"),
    weightFn: (v) => (v > 0.82 ? 0.55 : 0.28)
  });

  // Vintage gathered fabric pocket on the lower half of the lid lining (s from sB to sB + 0.42)
  const sPocket = sB + 0.41;
  const pk00 = lidWorld(uL, sB, recess + 0.015);
  const pk10 = lidWorld(uR, sB, recess + 0.015);
  const pk11 = lidWorld(uR, sPocket, recess + 0.025);
  const pk01 = lidWorld(uL, sPocket, recess + 0.025);

  // Cast shadow just below pocket elastic band & pleated vertical folds
  for (let i = 0; i <= 58; i++) {
    const u = i / 58;
    const pleat = Math.sin(i * 1.15) * 0.5 + 0.5;
    const top3 = lerp3(pk01, pk11, u);
    const bot3 = lerp3(pk00, pk10, u);
    const sTop = project(top3.X, top3.Y, top3.Z);
    const sBot = project(bot3.X, bot3.Y, bot3.Z);
    const isBlue = (Math.floor(u * numStripes) % 2 === 1);
    let col = isBlue ? "#425B72" : "#E8DEC9";
    col = mixHex(col, "#2D3E4E", pleat * 0.35 + (u < 0.12 ? 0.3 : 0));
    brush.set("cpencil_fine", col, 0.48);
    brush.line(sTop.x, sTop.y, sBot.x, sBot.y);
  }
  // Ruffled elastic top binding of the pocket
  for (let b = 0; b < 3; b++) {
    const a3 = lidWorld(uL, sPocket - b * 0.012, recess + 0.028);
    const b3 = lidWorld(uR, sPocket - b * 0.012, recess + 0.028);
    const sa = project(a3.X, a3.Y, a3.Z);
    const sb = project(b3.X, b3.Y, b3.Z);
    brush.set("cpencil", b === 2 ? "#374859" : (b === 0 ? "#F5EFE0" : "#9E7852"), 0.55);
    brush.line(sa.x, sa.y, sb.x, sb.y);
  }

  // 3. Inner side walls of the lid cavity (Top inner overhang + Right inner wall visible to viewer)
  // Top inner cavity wall (facing down, in warm umber-slate shadow)
  drawTexturedQuad3D(
    lidWorld(uL, sT, recess),
    lidWorld(uR, sT, recess),
    lidWorld(uR, sT, 0),
    lidWorld(uL, sT, 0),
    {
      washCol: "#4A3222",
      washAlpha: 235,
      linesU: 7,
      colFn: (v) => mixHex("#2E1D12", "#6E482B", v),
      weight: 0.48
    }
  );
  // Right inner cavity wall (facing left toward sun, catching warm light!)
  drawTexturedQuad3D(
    lidWorld(uR, sB, recess),
    lidWorld(uR, sB, 0),
    lidWorld(uR, sT, 0),
    lidWorld(uR, sT, recess),
    {
      washCol: "#C8AA88",
      washAlpha: 235,
      linesU: 24,
      colFn: (v) => (Math.floor(v * 14) % 2 === 0 ? "#D89A5B" : "#F0E6D2"),
      weight: 0.45
    }
  );

  // 4. Front Leather Frame Bevel of the Open Lid (d = 0)
  const frameBars = [
    // Left vertical leather bar
    [lidWorld(-hw, 0, 0), lidWorld(uL, 0, 0), lidWorld(uL, SUIT_D, 0), lidWorld(-hw, SUIT_D, 0)],
    // Right vertical leather bar
    [lidWorld(uR, 0, 0), lidWorld(hw, 0, 0), lidWorld(hw, SUIT_D, 0), lidWorld(uR, SUIT_D, 0)],
    // Top horizontal leather bar
    [lidWorld(-hw, sT, 0), lidWorld(hw, sT, 0), lidWorld(hw, SUIT_D, 0), lidWorld(-hw, SUIT_D, 0)],
    // Bottom hinge leather bar
    [lidWorld(-hw, 0, 0), lidWorld(hw, 0, 0), lidWorld(hw, sB, 0), lidWorld(-hw, sB, 0)]
  ];
  for (let b = 0; b < frameBars.length; b++) {
    const q = frameBars[b];
    drawTexturedQuad3D(q[0], q[1], q[2], q[3], {
      washCol: "#9E5727",
      washAlpha: 245,
      linesU: 12,
      colFn: (v) => mixHex("#6E3712", "#C97E42", 0.5 + 0.4 * Math.sin(v * 3.14)),
      weight: 0.48,
      outlineCol: "#4A2108",
      outlineWeight: 0.55
    });
  }

  // Cream saddle-stitching around the open lid rim
  drawStitchRect3D(
    lidWorld(-hw + 0.025, 0.025, 0.002),
    lidWorld(hw - 0.025, 0.025, 0.002),
    lidWorld(hw - 0.025, SUIT_D - 0.025, 0.002),
    lidWorld(-hw + 0.025, SUIT_D - 0.025, 0.002),
    36, 22
  );

  // Two brass latch hooks on the top rim of the open lid (u = -0.45 and u = +0.45)
  const hookUs = [-0.45, 0.45];
  for (let h = 0; h < hookUs.length; h++) {
    const hu = hookUs[h];
    drawTexturedQuad3D(
      lidWorld(hu - 0.065, sT + 0.01, 0.005),
      lidWorld(hu + 0.065, sT + 0.01, 0.005),
      lidWorld(hu + 0.055, SUIT_D + 0.045, 0.02),
      lidWorld(hu - 0.055, SUIT_D + 0.045, 0.02),
      {
        washCol: "#D4A742",
        washAlpha: 250,
        linesV: 8,
        colFnV: (u) => u < 0.35 ? "#FFF6CC" : (u > 0.75 ? "#6E4B10" : "#C99832"),
        weight: 0.45,
        outlineCol: "#4F3408"
      }
    );
  }

  // ---------------------------------------------------------------------------
  // B. BASE TRAY INTERIOR WALLS (Back & Right Striped Lining above waterline)
  // ---------------------------------------------------------------------------
  const waterY = BASE_H - 0.032;
  // Back inner lining strip
  drawTexturedQuad3D(
    suitWorld(-hw + rim, waterY, hd - rim),
    suitWorld(hw - rim, waterY, hd - rim),
    suitWorld(hw - rim, BASE_H, hd - rim),
    suitWorld(-hw + rim, BASE_H, hd - rim),
    {
      washCol: "#C5BDAE",
      washAlpha: 240,
      linesV: 32,
      colFnV: (u) => (Math.floor(u * numStripes) % 2 === 1 ? "#3F556B" : "#DFD5C0"),
      weight: 0.45
    }
  );
  // Right inner lining strip (catching sunlight)
  drawTexturedQuad3D(
    suitWorld(hw - rim, waterY, -hd + rim),
    suitWorld(hw - rim, waterY, hd - rim),
    suitWorld(hw - rim, BASE_H, hd - rim),
    suitWorld(hw - rim, BASE_H, -hd + rim),
    {
      washCol: "#E3DAC6",
      washAlpha: 240,
      linesV: 20,
      colFnV: (u) => (Math.floor(u * 16) % 2 === 1 ? "#4E6880" : "#F3EBD8"),
      weight: 0.45
    }
  );

  // Two leather stay-straps connecting inside of base tray to inside of open lid
  const stayUs = [-hw + 0.11, hw - 0.11];
  for (let i = 0; i < 2; i++) {
    const su = stayUs[i];
    const b0 = suitWorld(su - 0.02, BASE_H - 0.02, 0.15);
    const b1 = suitWorld(su + 0.02, BASE_H - 0.02, 0.15);
    const t1 = lidWorld(su + 0.02, 0.52, recess + 0.02);
    const t0 = lidWorld(su - 0.02, 0.52, recess + 0.02);
    drawTexturedQuad3D(b0, b1, t1, t0, {
      washCol: i === 0 ? "#6E3814" : "#B56A2D",
      washAlpha: 245,
      linesV: 4,
      colFnV: (u) => u < 0.4 ? "#E29E5A" : "#4E240A",
      weight: 0.48
    });
  }

  // ---------------------------------------------------------------------------
  // C. BASE TRAY EXTERIOR WALLS: Worn Tan Leather, Corner Patches, Straps, Clasps
  // ---------------------------------------------------------------------------

  // 1. Left Short Exterior Wall (u = -hw, directly facing the low left sun!)
  const lw00 = suitWorld(-hw, 0, hd);
  const lw10 = suitWorld(-hw, 0, -hd);
  const lw11 = suitWorld(-hw, BASE_H, -hd);
  const lw01 = suitWorld(-hw, BASE_H, hd);

  drawTexturedQuad3D(lw00, lw10, lw11, lw01, {
    washCol: "#CC833E",
    washAlpha: 250,
    linesU: 26,
    brushName: "cpencil",
    colFn: (v) => {
      // Rich burnished sunlit tan leather with warm golden highlights
      const n = noise(v * 6.5, 2.1);
      return mixHex("#9C5421", "#F0B771", 0.35 + 0.55 * n + (v > 0.7 ? 0.15 : 0));
    },
    weight: 0.58,
    linesV: 32,
    brushNameV: "cpencil_fine",
    colFnV: (u) => mixHex("#B3672A", "#F6CA88", noise(u * 9.2, 7.4)),
    weightFnV: () => 0.38,
    outlineCol: "#5C2B0C",
    outlineWeight: 0.65
  });

  // 2. Front Long Exterior Wall (v = -hd, hero facade with clasps, straps & handle)
  const fw00 = suitWorld(-hw, 0, -hd);
  const fw10 = suitWorld(hw, 0, -hd);
  const fw11 = suitWorld(hw, BASE_H, -hd);
  const fw01 = suitWorld(-hw, BASE_H, -hd);

  drawTexturedQuad3D(fw00, fw10, fw11, fw01, {
    washCol: "#9E5524",
    washAlpha: 252,
    linesU: 34,
    brushName: "cpencil",
    colFn: (v) => {
      // Burnished cognac & raw sienna leather, slightly darker near bottom & under rim
      const verticalTone = Math.sin(v * Math.PI);
      const grain = noise(v * 10.5, 4.3);
      return sampleGradient([
        { pos: 0.0, col: "#5E2B0D" },
        { pos: 0.35, col: "#8D491C" },
        { pos: 0.72, col: "#B96D33" },
        { pos: 1.0, col: "#DF9A57" }
      ], constrain(verticalTone * 0.65 + grain * 0.38, 0, 1));
    },
    weight: 0.62,
    linesV: 68,
    brushNameV: "cpencil_fine",
    colFnV: (u) => {
      // Warmer on the left (closer to sun), deeper cognac toward the right
      const sunGrad = 1 - u * 0.55;
      const scuff = noise(u * 18.0, 9.1);
      return mixHex("#683110", "#D9924E", constrain(sunGrad * 0.6 + scuff * 0.45, 0, 1));
    },
    weightFnV: () => 0.42,
    outlineCol: "#471F07",
    outlineWeight: 0.7
  });

  // Worn leather scuffs & pebble grain highlights on the front & left walls
  for (let s = 0; s < 95; s++) {
    const u = random(-hw + 0.05, hw - 0.05);
    const y = random(0.03, BASE_H - 0.04);
    const len = random(0.04, 0.14);
    const p1 = suitProject(u, y, -hd - 0.002);
    const p2 = suitProject(u + len, y + random(-0.02, 0.02), -hd - 0.002);
    const isScuff = random() < 0.42;
    brush.set("cpencil_fine", isScuff ? "#E5AA68" : "#59280B", random(0.3, 0.52));
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // 3. Stitched Darker Leather Corner Reinforcements (Front-Left, Front-Right, Back-Left)
  const patchW = 0.21;
  const patchD = 0.19;
  // Front-left corner wrap (front face + left face)
  drawCornerPatch(
    suitWorld(-hw, 0, -hd - 0.003),
    suitWorld(-hw + patchW, 0, -hd - 0.003),
    suitWorld(-hw + patchW, BASE_H, -hd - 0.003),
    suitWorld(-hw, BASE_H, -hd - 0.003),
    true
  );
  drawCornerPatch(
    suitWorld(-hw - 0.003, 0, -hd + patchD),
    suitWorld(-hw - 0.003, 0, -hd),
    suitWorld(-hw - 0.003, BASE_H, -hd),
    suitWorld(-hw - 0.003, BASE_H, -hd + patchD),
    true
  );
  // Back-left corner patch on left wall
  drawCornerPatch(
    suitWorld(-hw - 0.003, 0, hd),
    suitWorld(-hw - 0.003, 0, hd - patchD),
    suitWorld(-hw - 0.003, BASE_H, hd - patchD),
    suitWorld(-hw - 0.003, BASE_H, hd),
    true
  );
  // Front-right corner patch on front wall
  drawCornerPatch(
    suitWorld(hw - patchW, 0, -hd - 0.003),
    suitWorld(hw, 0, -hd - 0.003),
    suitWorld(hw, BASE_H, -hd - 0.003),
    suitWorld(hw - patchW, BASE_H, -hd - 0.003),
    false
  );

  // Cream saddle-stitching along the front wall perimeter
  drawStitchRect3D(
    suitWorld(-hw + 0.025, 0.025, -hd - 0.004),
    suitWorld(hw - 0.025, 0.025, -hd - 0.004),
    suitWorld(hw - 0.025, BASE_H - 0.025, -hd - 0.004),
    suitWorld(-hw + 0.025, BASE_H - 0.025, -hd - 0.004),
    42, 10
  );

  // 4. Vertical Leather Cinch Straps with Brass Buckles (u = -0.62 and u = +0.62)
  const strapUs = [-0.62, 0.62];
  for (let i = 0; i < strapUs.length; i++) {
    const su = strapUs[i];
    const sw = 0.048;
    // Cast shadow of strap to the right (+u)
    drawTexturedQuad3D(
      suitWorld(su + sw, 0, -hd - 0.004),
      suitWorld(su + sw + 0.032, 0, -hd - 0.004),
      suitWorld(su + sw + 0.032, BASE_H, -hd - 0.004),
      suitWorld(su + sw, BASE_H, -hd - 0.004),
      { washCol: "#3B1905", washAlpha: 175 }
    );
    // Leather strap body
    drawTexturedQuad3D(
      suitWorld(su - sw, 0, -hd - 0.006),
      suitWorld(su + sw, 0, -hd - 0.006),
      suitWorld(su + sw, BASE_H + 0.01, -hd - 0.006),
      suitWorld(su - sw, BASE_H + 0.01, -hd - 0.006),
      {
        washCol: "#783A14",
        washAlpha: 250,
        linesV: 8,
        colFnV: (u) => u < 0.28 ? "#E6A560" : (u > 0.78 ? "#4A2008" : "#8F481B"),
        weight: 0.48,
        outlineCol: "#3D1A06"
      }
    );
    // Brass buckle midway up the strap
    drawBrassBuckle(su, 0.14, 0.25, -hd - 0.012);
  }

  // 5. Two Ornate Vintage Brass Drawbolt Clasps (u = -0.39 and u = +0.39)
  drawBrassClasp(-0.39, -hd - 0.01);
  drawBrassClasp(0.39, -hd - 0.01);

  // 6. Sculpted Vintage Leather Handle in Center (u in [-0.22, +0.22])
  drawLeatherHandle(-hd - 0.01);
}

function drawCornerPatch(p00, p10, p11, p01, isSunlit) {
  drawTexturedQuad3D(p00, p10, p11, p01, {
    washCol: isSunlit ? "#8B471C" : "#693210",
    washAlpha: 248,
    linesU: 14,
    colFn: (v) => mixHex(isSunlit ? "#632D0D" : "#471E07", isSunlit ? "#C97D3D" : "#9B5222", v),
    weight: 0.48,
    outlineCol: "#3B1805",
    outlineWeight: 0.6
  });

  // Brass corner rivets
  const rivets = [
    bilerp3(p00, p10, p11, p01, 0.25, 0.22),
    bilerp3(p00, p10, p11, p01, 0.75, 0.22),
    bilerp3(p00, p10, p11, p01, 0.25, 0.78),
    bilerp3(p00, p10, p11, p01, 0.75, 0.78)
  ];
  for (let r = 0; r < rivets.length; r++) {
    const sp = project(rivets[r].X, rivets[r].Y, rivets[r].Z);
    brush.noFill();
    brush.set("cpencil_fine", "#3A1A06", 0.75);
    brush.circle(sp.x + 1.2, sp.y + 0.8, 2.2, 0.05);
    brush.wash("#D9AC45", 245);
    brush.circle(sp.x, sp.y, 2.1, 0.05);
    brush.noWash();
    brush.set("cpencil_fine", "#FFF8D4", 0.7);
    brush.line(sp.x - 1.2, sp.y - 0.8, sp.x + 0.4, sp.y - 1.2);
  }
}

function drawStitchRect3D(p00, p10, p11, p01, stepsU, stepsV) {
  const edges = [
    { a: p00, b: p10, n: stepsU },
    { a: p10, b: p11, n: stepsV },
    { a: p11, b: p01, n: stepsU },
    { a: p01, b: p00, n: stepsV }
  ];
  for (let e = 0; e < edges.length; e++) {
    const edge = edges[e];
    for (let i = 0; i < edge.n; i++) {
      if (i % 2 === 1) continue;
      const t0 = (i + 0.15) / edge.n;
      const t1 = (i + 0.85) / edge.n;
      const w0 = lerp3(edge.a, edge.b, t0);
      const w1 = lerp3(edge.a, edge.b, t1);
      const s0 = project(w0.X, w0.Y, w0.Z);
      const s1 = project(w1.X, w1.Y, w1.Z);
      brush.set("cpencil_fine", "#F2E4C6", 0.52);
      brush.line(s0.x, s0.y, s1.x, s1.y);
    }
  }
}

function drawBrassBuckle(uCenter, y0, y1, vPlane) {
  const bw = 0.062;
  const p00 = suitWorld(uCenter - bw, y0, vPlane);
  const p10 = suitWorld(uCenter + bw, y0, vPlane);
  const p11 = suitWorld(uCenter + bw, y1, vPlane);
  const p01 = suitWorld(uCenter - bw, y1, vPlane);

  drawTexturedQuad3D(p00, p10, p11, p01, {
    washCol: "#C99A35",
    washAlpha: 250,
    linesV: 9,
    colFnV: (u) => u < 0.3 ? "#FFF5C0" : (u > 0.75 ? "#6E4A10" : "#D8AC47"),
    weight: 0.48,
    outlineCol: "#4A2E06"
  });
  // Dark leather interior slot of buckle
  const in00 = suitWorld(uCenter - bw * 0.55, y0 + 0.022, vPlane - 0.002);
  const in10 = suitWorld(uCenter + bw * 0.55, y0 + 0.022, vPlane - 0.002);
  const in11 = suitWorld(uCenter + bw * 0.55, y1 - 0.022, vPlane - 0.002);
  const in01 = suitWorld(uCenter - bw * 0.55, y1 - 0.022, vPlane - 0.002);
  drawTexturedQuad3D(in00, in10, in11, in01, {
    washCol: "#59280B",
    washAlpha: 245
  });
  // Brass tongue pin
  const pinA = suitProject(uCenter, (y0 + y1) * 0.5, vPlane - 0.004);
  const pinB = suitProject(uCenter, y1 + 0.01, vPlane - 0.004);
  brush.set("cpencil_fine", "#FFF8D6", 0.72);
  brush.line(pinA.x, pinA.y, pinB.x, pinB.y);
}

function drawBrassClasp(uCenter, vPlane) {
  const cw = 0.078;
  const yBot = 0.21;
  const yTop = BASE_H - 0.015;

  // Raking cast shadow of brass clasp onto the leather wall to the right
  drawTexturedQuad3D(
    suitWorld(uCenter + cw * 0.5, yBot - 0.015, vPlane + 0.004),
    suitWorld(uCenter + cw + 0.048, yBot - 0.015, vPlane + 0.004),
    suitWorld(uCenter + cw + 0.048, yTop, vPlane + 0.004),
    suitWorld(uCenter + cw * 0.5, yTop, vPlane + 0.004),
    { washCol: "#361604", washAlpha: 195 }
  );

  // Main bevelled brass plate
  const p00 = suitWorld(uCenter - cw, yBot, vPlane);
  const p10 = suitWorld(uCenter + cw, yBot, vPlane);
  const p11 = suitWorld(uCenter + cw, yTop, vPlane);
  const p01 = suitWorld(uCenter - cw, yTop, vPlane);

  drawTexturedQuad3D(p00, p10, p11, p01, {
    washCol: "#C7962E",
    washAlpha: 252,
    linesU: 16,
    brushName: "cpencil_fine",
    colFn: (v) => sampleGradient([
      { pos: 0.0, col: "#69480D" },
      { pos: 0.35, col: "#D4A63E" },
      { pos: 0.65, col: "#F6DF8B" },
      { pos: 0.85, col: "#8C6318" },
      { pos: 1.0, col: "#FFF9D6" }
    ], v),
    weight: 0.52,
    linesV: 14,
    colFnV: (u) => u < 0.28 ? "#FFF7CC" : (u > 0.78 ? "#5E3E09" : "#D6A840"),
    weightFnV: () => 0.45,
    outlineCol: "#4A2E05",
    outlineWeight: 0.6
  });

  // Raised central brass drawbolt boss
  const bw = cw * 0.48;
  const b00 = suitWorld(uCenter - bw, yBot + 0.035, vPlane - 0.012);
  const b10 = suitWorld(uCenter + bw, yBot + 0.035, vPlane - 0.012);
  const b11 = suitWorld(uCenter + bw, yTop - 0.02, vPlane - 0.012);
  const b01 = suitWorld(uCenter - bw, yTop - 0.02, vPlane - 0.012);

  drawTexturedQuad3D(b00, b10, b11, b01, {
    washCol: "#E5BE5C",
    washAlpha: 250,
    linesV: 8,
    colFnV: (u) => u < 0.4 ? "#FFFBE0" : "#875E15",
    weight: 0.5,
    outlineCol: "#4A2E05"
  });

  // Keyhole slot at bottom of clasp
  const kh = suitProject(uCenter, yBot + 0.022, vPlane - 0.014);
  brush.set("cpencil_fine", "#2B1403", 0.95);
  brush.circle(kh.x, kh.y, 2.2, 0.04);
  brush.line(kh.x, kh.y, kh.x, kh.y + 4.5);

  // Specular glint on top-left bevel
  const g0 = suitProject(uCenter - cw + 0.008, yTop - 0.008, vPlane - 0.014);
  const g1 = suitProject(uCenter + cw * 0.4, yTop - 0.008, vPlane - 0.014);
  const g2 = suitProject(uCenter - cw + 0.008, yBot + 0.02, vPlane - 0.014);
  brush.set("cpencil_fine", "#FFFDF0", 0.78);
  brush.line(g0.x, g0.y, g1.x, g1.y);
  brush.line(g0.x, g0.y, g2.x, g2.y);
}

function drawLeatherHandle(vPlane) {
  const uL = -0.22;
  const uR = 0.22;
  const yMount = 0.20;

  // Brass handle mounts at left & right ends
  const mountUs = [uL, uR];
  for (let m = 0; m < 2; m++) {
    const mu = mountUs[m];
    drawTexturedQuad3D(
      suitWorld(mu - 0.032, yMount - 0.03, vPlane - 0.005),
      suitWorld(mu + 0.032, yMount - 0.03, vPlane - 0.005),
      suitWorld(mu + 0.032, yMount + 0.03, vPlane - 0.005),
      suitWorld(mu - 0.032, yMount + 0.03, vPlane - 0.005),
      {
        washCol: "#D6A840",
        washAlpha: 250,
        linesV: 6,
        colFnV: (u) => u < 0.38 ? "#FFF7CC" : "#6E4B10",
        weight: 0.48,
        outlineCol: "#472C05"
      }
    );
  }

  // Cast shadow of the arched leather handle onto the front suitcase wall
  const shPts = [];
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    const u = lerp(uL, uR, t) + 0.035;
    const arch = Math.sin(t * Math.PI);
    const y = yMount - 0.025 - arch * 0.055;
    const p = suitProject(u, y, vPlane);
    shPts.push([p.x, p.y, 0.8 + arch * 0.5]);
  }
  brush.set("charcoal", "#331403", 1.55);
  brush.spline(shPts, 0.45);

  // Sculpted leather handle arch (layered from dark underside to bright sunlit top ridge)
  const layers = [
    { dy: -0.022, col: "#421B06", w: 1.25 },
    { dy: -0.012, col: "#6E3210", w: 1.20 },
    { dy: 0.000, col: "#9E5322", w: 1.15 },
    { dy: 0.010, col: "#CC7F3E", w: 0.95 },
    { dy: 0.017, col: "#F0B673", w: 0.62 }
  ];
  for (let l = 0; l < layers.length; l++) {
    const lay = layers[l];
    const pts = [];
    for (let i = 0; i <= 16; i++) {
      const t = i / 16;
      const u = lerp(uL, uR, t);
      const arch = Math.sin(t * Math.PI);
      const y = yMount + lay.dy - arch * 0.035;
      const v = vPlane - 0.015 - arch * 0.055;
      const p = suitProject(u, y, v);
      pts.push([p.x, p.y, 0.6 + arch * 0.65]);
    }
    brush.set(l === 4 ? "cpencil_fine" : "cpencil", lay.col, lay.w);
    brush.spline(pts, 0.45);
  }
}

// =============================================================================
// 6. OCEAN INSIDE SUITCASE & TINY WAVES FOAMING AT THE LIP
// =============================================================================
function drawSuitcaseOceanAndFoamLip() {
  const hw = SUIT_W * 0.5;
  const hd = SUIT_D * 0.5;
  const rim = 0.065;
  const waterY = BASE_H - 0.018;

  // ---------------------------------------------------------------------------
  // A. Calm Ocean Surface Filling the Open Suitcase Tray
  // ---------------------------------------------------------------------------
  const w00 = suitWorld(-hw + rim * 0.3, waterY, -hd + rim * 0.3);
  const w10 = suitWorld(hw - rim, waterY, -hd + rim);
  const w11 = suitWorld(hw - rim, waterY, hd - rim);
  const w01 = suitWorld(-hw + rim * 0.3, waterY, hd - rim);

  drawTexturedQuad3D(w00, w10, w11, w01, {
    washCol: "#1B3D5A",
    washAlpha: 248,
    linesU: 44,
    brushName: "cpencil",
    colFn: (v, idx) => {
      const ripple = Math.sin(v * 28.0 + idx * 0.7);
      // Darker Prussian reflection under the upright lid on the back/right, brighter turquoise-cobalt near left lip
      const base = sampleGradient([
        { pos: 0.0, col: "#2C5E7A" },
        { pos: 0.45, col: "#1C4263" },
        { pos: 0.85, col: "#132D47" },
        { pos: 1.0, col: "#0E2238" }
      ], v);
      if (ripple > 0.35) {
        return mixHex(base, "#9EC0D4", (ripple - 0.35) * 0.65);
      }
      return base;
    },
    weight: 0.56,
    linesV: 38,
    brushNameV: "cpencil_fine",
    colFnV: (u) => {
      // Brighter turquoise & sky reflection on the left side where water accelerates to the lip
      return u < 0.38 ? mixHex("#4B8196", "#C8DEE8", (0.38 - u) * 1.4) : "#173754";
    },
    weightFnV: () => 0.38
  });

  // Top rim of the right and back walls of the base tray (framing the water on the non-spilling sides)
  drawTexturedQuad3D(
    suitWorld(hw - rim, BASE_H, -hd),
    suitWorld(hw, BASE_H, -hd),
    suitWorld(hw, BASE_H, hd),
    suitWorld(hw - rim, BASE_H, hd),
    {
      washCol: "#B36A2E",
      washAlpha: 250,
      linesV: 6,
      colFnV: (u) => u < 0.4 ? "#E5A35F" : "#6E3510",
      weight: 0.48,
      outlineCol: "#4A2108"
    }
  );
  // Right half of the front rim (u from +0.04 to +hw) where leather rim stays dry above water
  drawTexturedQuad3D(
    suitWorld(0.02, BASE_H, -hd),
    suitWorld(hw, BASE_H, -hd),
    suitWorld(hw, BASE_H, -hd + rim),
    suitWorld(0.02, BASE_H, -hd + rim),
    {
      washCol: "#BF7537",
      washAlpha: 250,
      linesU: 6,
      colFn: (v) => mixHex("#7A3C14", "#EAA965", 1 - v),
      weight: 0.48,
      outlineCol: "#4A2108"
    }
  );

  // ---------------------------------------------------------------------------
  // B. Translucent Waterfall Sheet Pouring Over the Left & Front-Left Rim
  // ---------------------------------------------------------------------------
  // 1. Spill over the Left Short Wall (u = -hw, v in [-hd, +hd * 0.65])
  const nFallL = 56;
  for (let i = 0; i <= nFallL; i++) {
    const t = i / nFallL;
    const v = lerp(-hd + 0.02, hd * 0.68, t);
    const waveCrest = 0.018 * Math.sin(t * 22.0) + 0.012;

    // Curve of falling water from inner water surface over the leather lip down to the salt flat
    const pts = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      // Arch over the rim at f = 0..0.25, then cascade down and outward (-u) to Y = 0
      const uPos = -hw + 0.06 * (1 - Math.min(1, f * 3.2)) - Math.pow(f, 1.35) * 0.22;
      const yPos = (BASE_H + waveCrest) * Math.cos(f * Math.PI * 0.5);
      const vPos = v - f * 0.06;
      const p = suitProject(uPos, Math.max(0, yPos), vPos);
      pts.push([p.x, p.y, 0.55 + 0.55 * Math.sin(f * Math.PI)]);
    }

    const isFoamStreak = (i % 3 === 0) || (Math.sin(t * 22.0) > 0.45);
    const col = isFoamStreak
      ? mixHex("#D6E8F0", "#FFFDF7", random(0.3, 0.85))
      : mixHex("#2C5E7A", "#689EB0", noise(t * 8.0, 2.3));
    brush.set(isFoamStreak ? "cpencil_fine" : "cpencil", col, isFoamStreak ? 0.52 : 0.62);
    brush.spline(pts, 0.45);
  }

  // 2. Spill over the Front-Left Long Rim (v = -hd, u in [-hw, +0.06])
  const nFallF = 48;
  for (let i = 0; i <= nFallF; i++) {
    const t = i / nFallF;
    const u = lerp(-hw + 0.01, 0.05, t);
    // Tapering flow height toward u = +0.05 where rim emerges dry
    const taper = Math.pow(1 - t, 0.45);
    const waveCrest = (0.022 * Math.sin(t * 19.0 + 1.2) + 0.015) * taper;

    const pts = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      const uPos = u - Math.pow(f, 1.4) * 0.14;
      const yPos = (BASE_H + waveCrest) * Math.cos(f * Math.PI * 0.5);
      const vPos = -hd + 0.05 * (1 - Math.min(1, f * 3.2)) - Math.pow(f, 1.25) * 0.16 * taper;
      const p = suitProject(uPos, Math.max(0, yPos), vPos);
      pts.push([p.x, p.y, 0.5 + 0.55 * Math.sin(f * Math.PI)]);
    }

    const isFoam = (i % 3 === 0) || (Math.sin(t * 19.0 + 1.2) > 0.4);
    const col = isFoam
      ? mixHex("#DFEDF4", "#FFFDF8", random(0.35, 0.9))
      : mixHex("#1F4766", "#588FA3", noise(t * 7.5, 5.1));
    brush.set(isFoam ? "cpencil_fine" : "cpencil", col, isFoam ? 0.5 : 0.58);
    brush.spline(pts, 0.45);
  }

  // ---------------------------------------------------------------------------
  // C. TINY WAVES FOAMING AT THE LIP (Hero Hyperreal Surrealist Detail)
  // ---------------------------------------------------------------------------
  // Draw miniature curling wavelets & lacy white sea-foam right along the suitcase lip
  const numWavelets = 11;
  for (let w = 0; w < numWavelets; w++) {
    const frac = w / (numWavelets - 1);
    // Distribute wavelets along the left rim (w = 0..5) and front-left rim (w = 5..10)
    let u0, v0, u1, v1;
    if (frac < 0.52) {
      const k0 = frac / 0.52;
      const k1 = (frac + 0.095) / 0.52;
      u0 = -hw + 0.02;
      u1 = -hw + 0.02;
      v0 = lerp(hd * 0.62, -hd, constrain(k0, 0, 1));
      v1 = lerp(hd * 0.62, -hd, constrain(k1, 0, 1));
    } else {
      const k0 = (frac - 0.52) / 0.48;
      const k1 = (frac - 0.52 + 0.095) / 0.48;
      u0 = lerp(-hw, 0.05, constrain(k0, 0, 1));
      u1 = lerp(-hw, 0.05, constrain(k1, 0, 1));
      v0 = -hd + 0.02;
      v1 = -hd + 0.02;
    }

    const waveH = 0.032 + 0.014 * Math.sin(w * 2.1);
    const pStart = suitProject(u0, BASE_H + 0.005, v0);
    const pMid = suitProject((u0 + u1) * 0.5 - 0.015, BASE_H + waveH, (v0 + v1) * 0.5 - 0.015);
    const pEnd = suitProject(u1, BASE_H + 0.005, v1);

    // 1. Dark cobalt wave trough shadow just beneath the curling lip
    brush.set("cpencil", "#10283E", 0.72);
    brush.spline([
      [pStart.x, pStart.y + 3.5, 0.4],
      [pMid.x + 1.5, pMid.y + 4.2, 1.0],
      [pEnd.x, pEnd.y + 3.5, 0.4]
    ], 0.5);

    // 2. Translucent aquamarine-turquoise curling wave face
    brush.set("cpencil", "#548E9E", 0.78);
    brush.spline([
      [pStart.x, pStart.y + 1.8, 0.5],
      [pMid.x, pMid.y + 2.0, 1.1],
      [pEnd.x, pEnd.y + 1.8, 0.5]
    ], 0.5);

    // 3. Bright sunlit foam crest & lacy foam filaments
    brush.set("cpencil", "#F8F9F6", 0.85);
    brush.spline([
      [pStart.x, pStart.y, 0.5],
      [pMid.x, pMid.y, 1.25],
      [pEnd.x, pEnd.y, 0.5]
    ], 0.55);

    brush.set("cpencil_fine", "#FFFDF8", 0.68);
    for (let f = 0; f < 10; f++) {
      const ft = f / 9;
      const fx = lerp(pStart.x, pEnd.x, ft) + random(-2.5, 2.5);
      const fy = lerp(pStart.y, pEnd.y, ft) - Math.sin(ft * Math.PI) * 5.5 + random(-1.8, 1.8);
      // Tiny foam cellular arcs & droplets at the lip
      brush.circle(fx, fy, random(1.2, 3.4), 0.18);
      brush.line(fx, fy, fx - random(2, 7), fy + random(3, 9));
    }
  }

  // ---------------------------------------------------------------------------
  // D. Churning Foam Collar at Base of Suitcase Where Waterfall Meets Salt Flat
  // ---------------------------------------------------------------------------
  for (let i = 0; i < 85; i++) {
    const t = i / 84;
    // Arc wrapping around the left and front-left base of the suitcase
    const u = lerp(-hw - 0.28, 0.04, t) + random(-0.04, 0.04);
    const v = (t < 0.52)
      ? lerp(hd * 0.58, -hd - 0.16, t / 0.52)
      : -hd - 0.16 + (t - 0.52) * 0.14;
    const p = suitProject(u, random(0.0, 0.025), v + random(-0.04, 0.04));

    const r = random(2.0, 6.5);
    const col = random() < 0.68 ? "#FAFBF9" : mixHex("#B9D3E0", "#FFF6D2", random());
    brush.set("cpencil_fine", col, random(0.45, 0.78));
    brush.arc(p.x, p.y, r, random(-30, 160), random(190, 340));
    brush.line(p.x - r, p.y + 1, p.x + r * 1.3, p.y + random(-1.5, 1.5));
  }

  // Fine spray mist & foam stipple around the lip and base splash
  const mistP1 = suitProject(-hw - 0.05, BASE_H, -hd * 0.2);
  const mistP2 = suitProject(-hw - 0.15, 0.05, -hd - 0.05);
  brush.set("spray", "#FFFDF8", 0.42);
  brush.line(mistP1.x - 15, mistP1.y, mistP1.x + 45, mistP1.y + 25);
  brush.line(mistP2.x - 25, mistP2.y, mistP2.x + 65, mistP2.y + 12);
}

