  for (let i = 0; i < 28; i++) {
    const t = i / 27;
    const v = lerp(-hd + 0.08, hd - 0.12, t);
    const uStart = lerp(-hw + 0.02, -0.15, random(0.0, 0.35));
    const uEnd = uStart + random(0.22, 0.55);
    const pA = suitProject(uStart, waterY, v);
    const pB = suitProject(Math.min(hw - 0.08, uEnd), waterY, v + random(-0.03, 0.03));

    const isHighlight = (i % 3 === 0);
    const col = isHighlight
      ? mixHex("#E8F1F5", "#F5E4AF", random(0.2, 0.6))
      : "#3A6D88";
    brush.set("cpencil_fine", col, isHighlight ? 0.52 : 0.42);
    brush.line(pA.x, pA.y, pB.x, pB.y);
  }

  // Crisp sunlit edge highlights along the left and top edges of the suitcase & lid
  const hlEdges = [
    [lidProject(-hw, 0, -LID_T), lidProject(-hw, SUIT_D, -LID_T)],
    [lidProject(-hw, SUIT_D, 0), lidProject(hw, SUIT_D, 0)],
    [suitProject(-hw, 0, -hd), suitProject(-hw, BASE_H, -hd)]
  ];
  for (let i = 0; i < hlEdges.length; i++) {
    const a = hlEdges[i][0];
    const b = hlEdges[i][1];
    brush.set("cpencil_fine", "#FCE0A2", 0.72);
    brush.line(a.x, a.y, b.x, b.y);
  }
}

// Hyperreal Swirled Resin Bowling Ball as an Antique Celestial Globe
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const CX = 600;
const CY = 595;
const R = 392;

// 3D Orientation of the Celestial Bowling Ball
const TILT_ROLL = 22;   // Clockwise axial tilt in screen plane (degrees)
const TILT_PITCH = 16;  // North pole tilted slightly toward viewer (degrees)
const RING_LON = 46;    // Meridian ring plane rotation around polar axis (degrees)

// Three Drilled Finger Holes in Camera-Space Sphere Normals (nx, ny, nz)
const FINGER_HOLES = [
  { name: "middle", nx: -0.33, ny: -0.22, rAng: 0.086, depth: 36 },
  { name: "ring",   nx: -0.09, ny: -0.27, rAng: 0.084, depth: 35 },
  { name: "thumb",  nx: -0.17, ny:  0.07, rAng: 0.102, depth: 42 }
];

// Primary Warm Museum Spotlight Direction (from top-left-front)
const LIGHT_MAIN = normalize3([-0.28, -0.76, 0.58]);
// Cool Museum Gallery Ambient Fill Direction (from left-front)
const LIGHT_COOL = normalize3([-0.68, -0.10, 0.72]);
// Warm Brass Bounce Light Direction (from bottom-right)
const LIGHT_BOUNCE = normalize3([0.48, 0.75, 0.45]);

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

function dot3(a, b) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

function cross3(a, b) {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
}

// Convert Globe Coordinates (gx, gy=polar axis, gz) -> Camera Coordinates (cx, cy, cz)
function globeToCam(gx, gy, gz) {
  let p = TILT_PITCH * Math.PI / 180;
  let r = TILT_ROLL * Math.PI / 180;

  // Pitch around X so North Pole (0, 1, 0) tilts toward viewer (+cz)
  // Note: screen Y is downward, so globe +Y maps to -cy before roll
  let x1 = gx;
  let y1 = -gy * Math.cos(p) + gz * Math.sin(p);
  let z1 = gy * Math.sin(p) + gz * Math.cos(p);

  // Roll in screen plane (cx, cy)
  let cx = x1 * Math.cos(r) - y1 * Math.sin(r);
  let cy = x1 * Math.sin(r) + y1 * Math.cos(r);
  let cz = z1;
  return [cx, cy, cz];
}

// Inverse: Camera Coordinates (cx, cy, cz) -> Globe Coordinates (gx, gy, gz)
function camToGlobe(cx, cy, cz) {
  let p = TILT_PITCH * Math.PI / 180;
  let r = -TILT_ROLL * Math.PI / 180;

  let x1 = cx * Math.cos(r) - cy * Math.sin(r);
  let y1 = cx * Math.sin(r) + cy * Math.cos(r);
  let z1 = cz;

  let gx = x1;
  let gy = -y1 * Math.cos(p) + z1 * Math.sin(p);
  let gz = y1 * Math.sin(p) + z1 * Math.cos(p);
  return [gx, gy, gz];
}

// Spherical (latDeg, lonDeg) -> Camera Unit Normal + Screen Point
function latLonToCam(latDeg, lonDeg) {
  let lat = latDeg * Math.PI / 180;
  let lon = lonDeg * Math.PI / 180;
  let cl = Math.cos(lat);
  let gx = cl * Math.sin(lon);
  let gy = Math.sin(lat);
  let gz = cl * Math.cos(lon);
  let c = globeToCam(gx, gy, gz);
  return {
    nx: c[0], ny: c[1], nz: c[2],
    x: CX + c[0] * R,
    y: CY + c[1] * R
  };
}

// Precompute Hole Centers in 3D
for (let h of FINGER_HOLES) {
  h.nz = Math.sqrt(Math.max(0, 1 - h.nx * h.nx - h.ny * h.ny));
  h.vec = [h.nx, h.ny, h.nz];
  h.cosR = Math.cos(h.rAng);
}

// Check if a 3D unit vector on the sphere falls inside any finger hole
function isInsideHole(nx, ny, nz, marginRad = 0) {
  for (let h of FINGER_HOLES) {
    let d = nx * h.nx + ny * h.ny + nz * h.nz;
    let thresh = Math.cos(h.rAng + marginRad);
    if (d > thresh) return true;
  }
  return false;
}

// Brass Meridian Ring 3D Basis in Camera Space
let RING_U, RING_V, RING_N;
function initRingBasis() {
  let lon = RING_LON * Math.PI / 180;
  // Ring spans the North Pole (0,1,0) and Equatorial point (sin(lon), 0, cos(lon))
  RING_U = globeToCam(Math.sin(lon), 0, Math.cos(lon));
  RING_V = globeToCam(0, 1, 0);
  RING_N = normalize3(cross3(RING_U, RING_V));
}

// Point on Brass Meridian Ring: angle thetaDeg (90 = North Pole), radius rad, axial offset zOff
function ringPoint3D(thetaDeg, rad, zOff = 0) {
  let th = thetaDeg * Math.PI / 180;
  let ct = Math.cos(th);
  let st = Math.sin(th);
  let cx = rad * (ct * RING_U[0] + st * RING_V[0]) + zOff * RING_N[0];
  let cy = rad * (ct * RING_U[1] + st * RING_V[1]) + zOff * RING_N[1];
  let cz = rad * (ct * RING_U[2] + st * RING_V[2]) + zOff * RING_N[2];
  return { x: CX + cx, y: CY + cy, cx, cy, cz };
}

// Check if a point on the sphere (nx, ny, nz) is shadowed by the front Brass Meridian Ring
function getRingShadowFactor(nx, ny, nz) {
  let px = nx * R, py = ny * R, pz = nz * R;
  let denom = dot3(LIGHT_MAIN, RING_N);
  if (Math.abs(denom) < 0.001) return 0;
  let pDotN = px * RING_N[0] + py * RING_N[1] + pz * RING_N[2];
  let t = -pDotN / denom;
  if (t <= 0) return 0;
  let ix = px + t * LIGHT_MAIN[0];
  let iy = py + t * LIGHT_MAIN[1];
  let iz = pz + t * LIGHT_MAIN[2];
  if (iz < 0) return 0; // Only front ring casts shadow onto visible front hemisphere
  let rHit = Math.hypot(ix, iy, iz);
  if (rHit > 406 && rHit < 476) {
    let centerDist = Math.abs(rHit - 441) / 35;
    return Math.max(0, 1 - centerDist * centerDist);
  }
  return 0;
}

// Evaluate 3D Domain-Warped Marbled Resin Value at Sphere Normal (nx, ny, nz)
function evalResin(nx, ny, nz) {
  let g = camToGlobe(nx, ny, nz);
  let gx = g[0], gy = g[1], gz = g[2];

  // Multi-octave 3D domain warping for poured reactive bowling-ball resin
  let s1 = 1.55;
  let qx = noise(gx * s1 + 11.2, gy * s1 + 3.7, gz * s1 + 7.1) - 0.5;
  let qy = noise(gx * s1 + 5.4,  gy * s1 + 17.8, gz * s1 + 2.3) - 0.5;
  let qz = noise(gx * s1 + 19.1, gy * s1 + 8.6,  gz * s1 + 13.9) - 0.5;

  let wx = gx + 1.55 * qx;
  let wy = gy + 1.55 * qy;
  let wz = gz + 1.55 * qz;

  let rx = noise(wx * 2.15 + 23.4, wy * 2.15 + 6.1,  wz * 2.15 + 9.8) - 0.5;
  let ry = noise(wx * 2.15 + 4.2,  wy * 2.15 + 15.3, wz * 2.15 + 21.7) - 0.5;
  let rz = noise(wx * 2.15 + 12.9, wy * 2.15 + 27.1, wz * 2.15 + 3.5) - 0.5;

  let swirl = noise(wx * 1.75 + rx * 2.1 + 4.5, wy * 1.75 + ry * 2.1 + 8.2, wz * 1.75 + rz * 2.1 + 14.6);
  let band  = noise(wx * 3.8 + rx * 3.2 + 1.1, wy * 3.8 + ry * 3.2 + 5.5, wz * 3.8 + rz * 3.2 + 9.0);
  let micro = noise(gx * 7.5 + qx * 4.0, gy * 7.5 + qy * 4.0, gz * 7.5 + qz * 4.0);

  return { swirl, band, micro };
}

// Compute Shaded Hex Color for a Point on the Bowling Ball Surface
function getShadedResinColor(nx, ny, nz, resin) {
  let { swirl, band, micro } = resin;

  // Base pigment selection: Marbled Cool Peacock Teal vs. Deep Oxblood Burgundy
  let rBase, gBase, bBase;
  let isBurgundy = swirl > 0.495;
  let seamDist = Math.abs(swirl - 0.495);

  if (!isBurgundy) {
    // Cool Teal / Viridian / Prussian Abyss marbling
    let t = constrain(map(swirl, 0.18, 0.495, 0, 1), 0, 1);
    let fold = 0.5 + 0.5 * Math.sin(band * 11.0 + micro * 3.5);
    // Deep abyssal teal to luminous peacock cyan-teal
    rBase = lerp(9,  38, t * 0.7 + fold * 0.3);
    gBase = lerp(42, 128, t * 0.55 + fold * 0.45);
    bBase = lerp(56, 138, t * 0.5 + fold * 0.5);

    // Subtle pearlescent sea-jade ribbon inside high band values
    if (fold > 0.78) {
      let p = (fold - 0.78) / 0.22;
      rBase = lerp(rBase, 92, p * 0.55);
      gBase = lerp(gBase, 168, p * 0.65);
      bBase = lerp(bBase, 165, p * 0.6);
    }
  } else {
    // Rich Marbled Burgundy / Oxblood / Wine-Garnet
    let t = constrain(map(swirl, 0.495, 0.82, 0, 1), 0, 1);
    let fold = 0.5 + 0.5 * Math.cos(band * 10.5 - micro * 3.0);
    rBase = lerp(52, 146, t * 0.6 + fold * 0.4);
    gBase = lerp(11, 32,  t * 0.4 + fold * 0.6);
    bBase = lerp(24, 52,  t * 0.45 + fold * 0.55);

    // Warm ruby-amber internal mica swirl
    if (fold > 0.76) {
      let p = (fold - 0.76) / 0.24;
      rBase = lerp(rBase, 178, p * 0.6);
      gBase = lerp(gBase, 74,  p * 0.5);
      bBase = lerp(bBase, 68,  p * 0.45);
    }
  }

  // Dark reaction vein & golden-amber border where teal and burgundy meet
  if (seamDist < 0.032) {
    let s = 1 - seamDist / 0.032;
    if (seamDist < 0.012) {
      rBase = lerp(rBase, 14, s * 0.8);
      gBase = lerp(gBase, 18, s * 0.8);
      bBase = lerp(bBase, 26, s * 0.8);
    } else {
      rBase = lerp(rBase, 145, s * 0.45);
      gBase = lerp(gBase, 112, s * 0.45);
      bBase = lerp(bBase, 62,  s * 0.45);
    }
  }

  // 3D Lighting Calculations
  let nVec = [nx, ny, nz];
  let diffMain = Math.max(0, dot3(nVec, LIGHT_MAIN));
  let diffCool = Math.max(0, dot3(nVec, LIGHT_COOL));
  let diffBounce = Math.max(0, dot3(nVec, LIGHT_BOUNCE));

  // Subsurface scattering inside translucent resin
  let sss = Math.pow(Math.max(0, diffMain * 0.85 + 0.15), 2.2);

  // Shadow from the front brass meridian ring
  let ringShad = getRingShadowFactor(nx, ny, nz);
  diffMain *= (1 - 0.68 * ringShad);

  // Fresnel rim darkening & gallery reflection at grazing angles (nz -> 0)
  let fresnel = Math.pow(1 - Math.max(0, nz), 2.6);

  // Combine illumination channels
  let lightR = 0.16 + 1.08 * diffMain + 0.18 * diffCool + 0.22 * diffBounce + 0.25 * sss;
  let lightG = 0.18 + 0.96 * diffMain + 0.25 * diffCool + 0.17 * diffBounce + 0.18 * sss;
  let lightB = 0.22 + 0.74 * diffMain + 0.34 * diffCool + 0.09 * diffBounce + 0.12 * sss;

  let r = rBase * lightR;
  let g = gBase * lightG;
  let b = bBase * lightB;

  // Yellowed antique amber varnish tint (stronger in warm lit midtones)
  let varnish = 0.18 + 0.22 * diffMain;
  r = lerp(r, r * 1.12 + 28, varnish);
  g = lerp(g, g * 1.02 + 16, varnish);
  b = lerp(b, b * 0.78,      varnish);

  // Cool gallery rim reflection vs dark core edge
  let rimLight = Math.max(0, -nx * 0.6 - ny * 0.5);
  r = lerp(r, 18 + 55 * rimLight, fresnel * 0.65);
  g = lerp(g, 28 + 78 * rimLight, fresnel * 0.65);
  b = lerp(b, 38 + 88 * rimLight, fresnel * 0.65);

  return color(constrain(r, 4, 252), constrain(g, 5, 248), constrain(b, 6, 242));
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88341);
  initRingBasis();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#070d12");

  // 1. Museum Spotlight Backdrop & Pedestal Shadow
  drawMuseumBackdrop();

  // 2. Back Half of the Brass Meridian Ring & Rear Mounts (cz < 0)
  drawBrassRingHalf(false);

  // 3. Base Watercolor & Wash Underpainting of the Bowling Ball Sphere
  drawSphereUnderpainting();

  // 4. Hyperreal 3D Domain-Warped Marbled Resin Flow Ribbons
  drawMarbledResinSwirls();

  // 5. Yellowed Amber Varnish Glaze & Subsurface Glow Passes
  drawAmberVarnishGlaze();

  // 6. Three Drilled Bowling Ball Finger Holes in 3D Perspective
  drawFingerHoles();

  // 7. Fine Sepia Pen Engraved Celestial Grid, Ecliptic & Constellations
  drawCelestialEngraving();

  // 8. Aged Craquelure Network across the Varnished Sphere
  drawCraquelure();

  // 9. Scuffed Lane Polish, Bowler's Track Scratches & Museum Spotlight Specular
  drawLanePolishAndSpecular();

  // 10. Front Half of the Brass Meridian Ring, Polar Trunnions & Cradle Mount (cz >= 0)
  drawPolarMountsAndCradle();
  drawBrassRingHalf(true);

  noLoop();
}

// =============================================================================
// 1. MUSEUM SPOTLIGHT BACKDROP & ATMOSPHERE
// =============================================================================
function drawMuseumBackdrop() {
  brush.noStroke();

  // Warm cone of museum light descending from top-left-center
  const conePasses = [
    { x: 510, y: 420, r: 580, col: "#101c24", op: 45 },
    { x: 490, y: 360, r: 460, col: "#16262e", op: 42 },
    { x: 465, y: 290, r: 350, col: "#1f3033", op: 38 },
    { x: 440, y: 210, r: 240, col: "#2b3833", op: 34 },
    { x: 600, y: 1090, r: 420, col: "#04070a", op: 75 }
  ];

  for (let p of conePasses) {
    brush.wash(p.col, p.op);
    brush.circle(p.x, p.y, p.r, 0.25);
  }
  brush.noWash();

  // Subtle museum wall texture & chiaroscuro rays
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    let ang = lerp(-135, 45, random());
    let dist = random(430, 780);
    let x1 = CX + Math.cos(ang * Math.PI / 180) * dist;
    let y1 = CY + Math.sin(ang * Math.PI / 180) * dist;
    if (x1 < -40 || x1 > 1240 || y1 < -40 || y1 > 1240) continue;

    let isTopLeft = (x1 < 680 && y1 < 560);
    let col = isTopLeft
      ? (random() < 0.5 ? "#243538" : "#333e36")
      : (random() < 0.6 ? "#091219" : "#0e1b24");
    brush.set("charcoal", col, random(0.4, 1.1));
    let len = random(60, 160);
    let rayAng = atan2(y1 + 220, x1 - 420);
    brush.line(x1, y1, x1 + cos(rayAng) * len, y1 + sin(rayAng) * len);
  }

  // Dark museum pedestal surface at the very bottom
  brush.set("charcoal", "#05090d", 1.2);
  for (let y = 1095; y <= 1198; y += 5) {
    brush.set("charcoal", y < 1130 ? "#12171a" : "#060a0e", random(0.6, 1.3));
    brush.line(40, y + random(-2, 2), 1160, y + random(-2, 2));
  }
  // Soft cast shadow of the globe & stand on pedestal
  for (let i = 0; i < 55; i++) {
    let sx = random(280, 960);
    let sy = random(1105, 1185);
    let span = map( abs(sy - 1140), 0, 45, 260, 90 );
    brush.set("charcoal", "#030507", random(0.5, 1.1));
    brush.line(sx - span * 0.4, sy, sx + span * 0.4, sy);
  }
}

// =============================================================================
// 2 & 10. BRASS MERIDIAN RING IN PERSPECTIVE (Back Half & Front Half)
// =============================================================================
function drawBrassRingHalf(isFront) {
  const R_IN = 414;
  const R_MID1 = 428;
  const R_MID2 = 452;
  const R_OUT = 468;
  const THICK = 18; // Half-thickness of the 3D brass ring

  // Collect angular segments belonging to back (cz < 0) or front (cz >= 0)
  let step = 2.0;
  for (let th = 0; th < 360; th += step) {
    let pMid = ringPoint3D(th + step * 0.5, (R_IN + R_OUT) * 0.5, 0);
    let inFront = pMid.cz >= -8;
    if (inFront !== isFront) continue;

    // On the back half, skip segments completely hidden behind the bowling ball sphere
    if (!isFront) {
      let dCenter = Math.hypot(pMid.x - CX, pMid.y - CY);
      if (dCenter < R - 6) continue;
    }

    // Calculate local surface normal and metallic specular lighting along the ring
    let radDir = normalize3([pMid.cx, pMid.cy, pMid.cz]);
    let tangPoint = ringPoint3D(th + 1, 440, 0);
    let tangDir = normalize3([tangPoint.cx - pMid.cx, tangPoint.cy - pMid.cy, tangPoint.cz - pMid.cz]);

    // Metallic anisotropic reflection along the brushed brass tangent
    let nDotL = dot3(RING_N, LIGHT_MAIN);
    let rDotL = dot3(radDir, LIGHT_MAIN);
    let specWave = Math.pow(Math.max(0, 1 - Math.abs(dot3(tangDir, LIGHT_MAIN))), 3.5);
    let highlight = constrain(0.32 + 0.45 * Math.abs(nDotL) + 0.35 * rDotL + 0.55 * specWave, 0, 1.35);
    if (!isFront) highlight *= 0.58; // Darker in rear shadow

    // Choose antique brass palette based on specular intensity
    let faceCol, rimDarkCol, rimLightCol;
    if (highlight > 1.02) {
      faceCol = "#edd38c";
      rimDarkCol = "#8a6d32";
      rimLightCol = "#fff5d6";
    } else if (highlight > 0.78) {
      faceCol = "#c9a654";
      rimDarkCol = "#5e481e";
      rimLightCol = "#f0d894";
    } else if (highlight > 0.54) {
      faceCol = "#9c7b34";
      rimDarkCol = "#3d2e12";
      rimLightCol = "#c7a656";
    } else if (highlight > 0.34) {
      faceCol = "#6b5322";
      rimDarkCol = "#241b0a";
      rimLightCol = "#8f7132";
    } else {
      faceCol = "#3d2f14";
      rimDarkCol = "#140f05";
      rimLightCol = "#59451c";
    }

    // 1) Draw 3D inner thickness wall (between zOff = -THICK and +THICK at R_IN)
    let pInBack  = ringPoint3D(th, R_IN, -THICK);
    let pInBack2 = ringPoint3D(th + step, R_IN, -THICK);
    let pInFront  = ringPoint3D(th, R_IN, THICK);
    let pInFront2 = ringPoint3D(th + step, R_IN, THICK);

    brush.set("marker", rimDarkCol, 0.85);
    brush.line(pInBack.x, pInBack.y, pInFront.x, pInFront.y);
    brush.set("2B", rimDarkCol, 0.45);
    brush.line(pInBack.x, pInBack.y, pInBack2.x, pInBack2.y);

    // 2) Draw broad flat front face of the brass ring (R_IN to R_OUT at zOff = +THICK)
    for (let rFrac = 0; rFrac <= 1.0; rFrac += 0.2) {
      let rr = lerp(R_IN, R_OUT, rFrac);
      let pa = ringPoint3D(th, rr, THICK);
      let pb = ringPoint3D(th + step + 0.3, rr, THICK);
      let c = (rFrac > 0.32 && rFrac < 0.68 && highlight > 0.65) ? rimLightCol : faceCol;
      brush.set("marker", c, 0.72);
      brush.line(pa.x, pa.y, pb.x, pb.y);
    }

    // Brushed metallic grain along the ring arc
    let pMidA = ringPoint3D(th, lerp(R_IN, R_OUT, random(0.1, 0.9)), THICK);
    let pMidB = ringPoint3D(th + step, lerp(R_IN, R_OUT, random(0.1, 0.9)), THICK);
    brush.set("cpencil", highlight > 0.7 ? rimLightCol : rimDarkCol, 0.28);
    brush.line(pMidA.x, pMidA.y, pMidB.x, pMidB.y);

    // 3) Engraved concentric divider circles & bevel highlights on the brass face
    let pOut1 = ringPoint3D(th, R_OUT, THICK);
    let pOut2 = ringPoint3D(th + step, R_OUT, THICK);
    let pM1a  = ringPoint3D(th, R_MID1, THICK);
    let pM1b  = ringPoint3D(th + step, R_MID1, THICK);
    let pM2a  = ringPoint3D(th, R_MID2, THICK);
    let pM2b  = ringPoint3D(th + step, R_MID2, THICK);

    // Outer thickness bevel
    let pOutBack = ringPoint3D(th, R_OUT, -THICK * 0.6);
    brush.set("2B", rimDarkCol, 0.45);
    brush.line(pOut1.x, pOut1.y, pOutBack.x, pOutBack.y);

    // Engraved dark grooves
    brush.set("rotring", "#1c1407", 0.22);
    brush.line(pInFront.x, pInFront.y, pInFront2.x, pInFront2.y);
    brush.line(pM1a.x, pM1a.y, pM1b.x, pM1b.y);
    brush.line(pM2a.x, pM2a.y, pM2b.x, pM2b.y);
    brush.line(pOut1.x, pOut1.y, pOut2.x, pOut2.y);

    // Bright bevel edge glints
    if (highlight > 0.5) {
      brush.set("rotring", rimLightCol, 0.2);
      let pGlint1 = ringPoint3D(th, R_IN + 2.5, THICK);
      let pGlint2 = ringPoint3D(th + step, R_IN + 2.5, THICK);
      brush.line(pGlint1.x, pGlint1.y, pGlint2.x, pGlint2.y);
    }

    // 4) Degree Graduation Ticks & Engraved Numerals on the Brass Ring
    let degInt = Math.round(th);
    if (degInt % 2 === 0) {
      let isTen = (degInt % 10 === 0);
      let isFive = (degInt % 5 === 0);
      let rEnd = isTen ? R_OUT - 3 : (isFive ? R_MID2 : R_MID1);
      let pt1 = ringPoint3D(th, R_IN + 2, THICK);
      let pt2 = ringPoint3D(th, rEnd, THICK);
      brush.set("rotring", "#1a1206", isTen ? 0.28 : 0.18);
      brush.line(pt1.x, pt1.y, pt2.x, pt2.y);

      // Tiny engraved numeral marks every 10 degrees
      if (isTen && isFront) {
        let pNum = ringPoint3D(th + 2.2, (R_MID1 + R_MID2) * 0.5, THICK);
        brush.set("rotring", "#241909", 0.2);
        brush.line(pNum.x - 2, pNum.y - 2, pNum.x + 2, pNum.y + 2);
        brush.line(pNum.x + 3, pNum.y - 2, pNum.x + 1, pNum.y + 3);
      }
    }
  }
}

// =============================================================================
// 3. SPHERE BASE WATERCOLOR & WASH UNDERPAINTING
// =============================================================================
function drawSphereUnderpainting() {
  brush.noStroke();

  // Solid dark abyssal ground inside the sphere silhouette
  brush.wash("#08161e", 235);
  brush.circle(CX, CY, R, 0.04);
  brush.noWash();

  // Soft watercolor washes batched by color for internal resin depth
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.25);

  const washLayers = [
    // Deep cool teal illuminated upper-left zones
    { x: CX - 95,  y: CY - 110, r: 270, col: "#124e5c", op: 55 },
    { x: CX - 135, y: CY - 145, r: 210, col: "#1e7485", op: 50 },
    { x: CX - 60,  y: CY - 180, r: 170, col: "#3294a1", op: 42 },
    // Marbled burgundy / oxblood internal masses
    { x: CX + 45,  y: CY - 65,  r: 220, col: "#4a1020", op: 52 },
    { x: CX - 75,  y: CY + 75,  r: 230, col: "#591427", op: 48 },
    { x: CX - 140, y: CY - 20,  r: 155, col: "#7a1e35", op: 44 },
    { x: CX + 90,  y: CY + 85,  r: 195, col: "#380b18", op: 50 },
    // Deep abyssal core shadow on lower-right hemisphere
    { x: CX + 115, y: CY + 125, r: 250, col: "#061017", op: 65 }
  ];

  for (let w of washLayers) {
    brush.fill(w.col, w.op);
    brush.circle(w.x, w.y, w.r, 0.22);
  }
  brush.noFill();
}

// =============================================================================
// 4. HYPERREAL 3D DOMAIN-WARPED MARBLED RESIN SWIRLS
// =============================================================================
function drawMarbledResinSwirls() {
  // Trace thousands of 3D tangent-following streamlines across the visible hemisphere
  // Step 1: Broad base pigment ribbons (marker & charcoal)
  traceResinStreamlines(2100, 10, 14, "marker", 0.58, 0.35);

  // Step 2: Medium folding liquid veins (cpencil & 2B)
  traceResinStreamlines(3400, 9, 12, "cpencil", 0.36, 0.5);

  // Step 3: Fine hyperreal internal striations, mica veins & subsurface depth (2H & HB)
  traceResinStreamlines(2800, 7, 10, "HB", 0.24, 0.55);
}

function traceResinStreamlines(count, numSteps, stepPx, brushName, baseWeight, curv) {
  let eps = 0.015;

  for (let i = 0; i < count; i++) {
    // Fibonacci-jittered sampling on the visible hemisphere
    let u = random();
    let v = random();
    let rad = Math.sqrt(u) * 0.992;
    let phi = v * Math.PI * 2;
    let nx = rad * Math.cos(phi);
    let ny = rad * Math.sin(phi);
    let nz = Math.sqrt(Math.max(0.001, 1 - nx * nx - ny * ny));

    if (isInsideHole(nx, ny, nz, 0.006)) continue;

    let resin0 = evalResin(nx, ny, nz);
    let col = getShadedResinColor(nx, ny, nz, resin0);

    // Construct tangent frame on sphere at (nx, ny, nz)
    let pts = [];
    let cx = nx, cy = ny, cz = nz;

    for (let s = 0; s < numSteps; s++) {
      if (cz <= 0.02 || isInsideHole(cx, cy, cz, 0.004)) break;

      let sx = CX + cx * R;
      let sy = CY + cy * R;
      let press = (s === 0 || s === numSteps - 1) ? 0.35 : 1.0;
      pts.push([sx, sy, press]);

      // Compute local tangent orthogonal basis T1, T2
      let up = Math.abs(cy) < 0.9 ? [0, 1, 0] : [1, 0, 0];
      let t1 = normalize3(cross3(up, [cx, cy, cz]));
      let t2 = cross3([cx, cy, cz], t1);

      // Finite difference gradient of resin swirl along T1 and T2
      let n1 = normalize3([cx + eps * t1[0], cy + eps * t1[1], cz + eps * t1[2]]);
      let n2 = normalize3([cx + eps * t2[0], cy + eps * t2[1], cz + eps * t2[2]]);
      let r0 = evalResin(cx, cy, cz);
      let r1 = evalResin(n1[0], n1[1], n1[2]);
      let r2 = evalResin(n2[0], n2[1], n2[2]);

      let g1 = (r1.swirl + 0.35 * r1.band) - (r0.swirl + 0.35 * r0.band);
      let g2 = (r2.swirl + 0.35 * r2.band) - (r0.swirl + 0.35 * r0.band);
      let gMag = Math.hypot(g1, g2) || 1;

      // Tangent to iso-contour is (-g2, g1)
      let dir1 = -g2 / gMag;
      let dir2 =  g1 / gMag;

      let stepArc = stepPx / R;
      cx += stepArc * (dir1 * t1[0] + dir2 * t2[0]);
      cy += stepArc * (dir1 * t1[1] + dir2 * t2[1]);
      cz += stepArc * (dir1 * t1[2] + dir2 * t2[2]);
      let norm = normalize3([cx, cy, cz]);
      cx = norm[0]; cy = norm[1]; cz = norm[2];
    }

    if (pts.length >= 3) {
      let edgeShorten = 0.55 + 0.45 * nz;
      brush.set(brushName, col, baseWeight * edgeShorten * random(0.82, 1.18));
      brush.spline(pts, curv);
    }
  }
}

// =============================================================================
// 5. YELLOWED AMBER VARNISH GLAZE & RIM SHADING
// =============================================================================
function drawAmberVarnishGlaze() {
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.35);

  // Translucent yellowed amber varnish glazes over the lit & midtone zones
  const amberGlazes = [
    { x: CX - 75, y: CY - 85, r: 285, col: "#b5812e", op: 22 },
    { x: CX - 20, y: CY - 30, r: 340, col: "#8f611c", op: 18 },
    { x: CX - 130, y: CY - 130, r: 190, col: "#d4a248", op: 20 }
  ];

  for (let g of amberGlazes) {
    brush.fill(g.col, g.op);
    brush.circle(g.x, g.y, g.r, 0.15);
  }
  brush.noFill();

  // Crisp spherical contour shading around the outer perimeter of the bowling ball
  for (let a = 0; a < 360; a += 1.5) {
    let rad = a * Math.PI / 180;
    let nx = Math.cos(rad);
    let ny = Math.sin(rad);
    let diff = Math.max(0, nx * LIGHT_MAIN[0] + ny * LIGHT_MAIN[1]);
    let rimCol = diff > 0.25 ? "#26383b" : "#050b10";
    let p1x = CX + nx * (R - 1);
    let p1y = CY + ny * (R - 1);
    let p2x = CX + nx * R + (-ny) * 18;
    let p2y = CY + ny * R + (nx) * 18;
    brush.set("charcoal", rimCol, 0.38);
    brush.line(p1x, p1y, p2x, p2y);
  }
}

// =============================================================================
// 6. THREE DRILLED FINGER HOLES (Hyperreal 3D Cylindrical Depth & Bevels)
// =============================================================================
function drawFingerHoles() {
  for (let h of FINGER_HOLES) {
    // Orthonormal tangent basis on the sphere at the hole center
    let N = h.vec;
    let up = [0, 1, 0];
    let T1 = normalize3(cross3(up, N));
    let T2 = cross3(N, T1);

    // Generate 3D rim points on the sphere surface
    let rimPts = [];
    let innerRimPts = [];
    let deepWallPts = [];
    let steps = 40;

    // Drilling axis goes inward along -N
    let drillDx = -N[0] * h.depth;
    let drillDy = -N[1] * h.depth;

    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * Math.PI * 2;
      let ca = Math.cos(ang);
      let sa = Math.sin(ang);

      // Outer chamfer rim
      let rOuter = h.rAng * 1.06;
      let pOut = normalize3([
        N[0] * Math.cos(rOuter) + (ca * T1[0] + sa * T2[0]) * Math.sin(rOuter),
        N[1] * Math.cos(rOuter) + (ca * T1[1] + sa * T2[1]) * Math.sin(rOuter),
        N[2] * Math.cos(rOuter) + (ca * T1[2] + sa * T2[2]) * Math.sin(rOuter)
      ]);
      rimPts.push([CX + pOut[0] * R, CY + pOut[1] * R]);

      // Inner chamfer lip
      let rInner = h.rAng * 0.96;
      let pIn = normalize3([
        N[0] * Math.cos(rInner) + (ca * T1[0] + sa * T2[0]) * Math.sin(rInner),
        N[1] * Math.cos(rInner) + (ca * T1[1] + sa * T2[1]) * Math.sin(rInner),
        N[2] * Math.cos(rInner) + (ca * T1[2] + sa * T2[2]) * Math.sin(rInner)
      ]);
      let ix = CX + pIn[0] * R;
      let iy = CY + pIn[1] * R;
      innerRimPts.push({ x: ix, y: iy, ca, sa, tx: ca * T1[0] + sa * T2[0], ty: ca * T1[1] + sa * T2[1], tz: ca * T1[2] + sa * T2[2] });
      deepWallPts.push({ x: ix + drillDx, y: iy + drillDy });
    }

    // 1) Dark abyssal fill for the drilled cavity
    brush.noStroke();
    brush.wash("#040609", 248);
    brush.beginShape(0.2);
    for (let p of innerRimPts) brush.vertex(p.x, p.y);
    brush.endShape(true);
    brush.noWash();

    // 2) Render the cylindrical inner wall (lit on the bottom-right wall facing the top-left spot)
    for (let i = 0; i < steps; i++) {
      let p1 = innerRimPts[i];
      let p2 = innerRimPts[(i + 1) % steps];

      // Inner cylinder wall normal points INWARD toward the hole axis: (-tx, -ty, -tz)
      let wallNx = -p1.tx;
      let wallNy = -p1.ty;
      let wallNz = -p1.tz;
      let wallLight = Math.max(0, wallNx * LIGHT_MAIN[0] + wallNy * LIGHT_MAIN[1] + wallNz * LIGHT_MAIN[2]);

      // Only draw visible side of inner cylinder wall (where wall normal faces viewer or light)
      for (let d = 0.05; d <= 1.0; d += 0.08) {
        let wx1 = lerp(p1.x, p1.x + drillDx * 1.15, d);
        let wy1 = lerp(p1.y, p1.y + drillDy * 1.15, d);
        let wx2 = lerp(p2.x, p2.x + drillDx * 1.15, d);
        let wy2 = lerp(p2.y, p2.y + drillDy * 1.15, d);

        // Clip to stay inside the innerRim ellipse
        let midX = (wx1 + wx2) * 0.5 - (CX + N[0] * R);
        let midY = (wy1 + wy2) * 0.5 - (CY + N[1] * R);
        let u1 = (midX * T1[0] + midY * T1[1]) / (R * Math.sin(h.rAng * 0.94));
        let u2 = (midX * T2[0] + midY * T2[1]) / (R * Math.sin(h.rAng * 0.94));
        if (u1 * u1 + u2 * u2 > 0.98) continue;

        // Deeper into the hole gets darker; outer core shows resin & filler strata
        let depthFade = Math.pow(1 - d, 1.4);
        let lit = wallLight * depthFade;
        let col;
        if (lit > 0.38) {
          col = (d < 0.28) ? "#6b3230" : "#4a3728"; // Warm lit resin/core wall
        } else if (lit > 0.18) {
          col = (d < 0.3) ? "#2e1820" : "#1c2629";
        } else if (lit > 0.06) {
          col = "#0d1318";
        } else {
          col = "#04070a";
        }
        brush.set("marker", col, 0.55);
        brush.line(wx1, wy1, wx2, wy2);
      }
    }

    // 3) Render the beveled outer chamfer lip (dark shadow on upper-left lip, bright glossy highlight on lower-right lip)
    for (let i = 0; i < steps; i++) {
      let iNext = (i + 1) % steps;
      let ro1 = rimPts[i], ro2 = rimPts[iNext];
      let ri1 = innerRimPts[i], ri2 = innerRimPts[iNext];

      // Bevel normal is tilted between sphere normal N and inward wall normal -T
      let bevNx = normalize3([N[0] - 1.1 * ri1.tx, N[1] - 1.1 * ri1.ty, N[2] - 1.1 * ri1.tz]);
      let bevLight = dot3(bevNx, LIGHT_MAIN);

      let bevCol;
      if (bevLight > 0.72) {
        bevCol = "#f5dfac"; // Razor-sharp specular highlight on lower-right chamfer
      } else if (bevLight > 0.52) {
        bevCol = "#b89658";
      } else if (bevLight > 0.25) {
        bevCol = "#3c6970";
      } else {
        bevCol = "#081117"; // Crisp lip shadow on upper-left chamfer
      }

      brush.set("cpencil", bevCol, 0.5);
      brush.line(ro1[0], ro1[1], ri1.x, ri1.y);
      brush.set("rotring", bevCol, bevLight > 0.65 ? 0.36 : 0.24);
      brush.line(ri1.x, ri1.y, ri2.x, ri2.y);
      brush.line(ro1[0], ro1[1], ro2[0], ro2[1]);
    }
  }
}

// =============================================================================
// 7. FINE SEPIA PEN ENGRAVED OVERLAY (Constellations, Meridians, Ecliptic, Stars)
// =============================================================================
function drawCelestialEngraving() {
  // Helper to draw a 3D spherical polyline in engraved sepia pen (dark incised groove + warm gilt/ochre edge)
  function drawEngravedSphericalCurve(latLonArray, weight = 0.22, isDouble = false, dashed = false) {
    let seg = [];
    let segLight = [];

    function flushSeg() {
      if (seg.length >= 2) {
        // Warm illuminated edge offset slightly toward the light
        brush.set("rotring", "#b58d52", weight * 0.82);
        brush.spline(segLight, 0.35);
        // Crisp dark sepia incised line
        brush.set("rotring", "#24160a", weight);
        brush.spline(seg, 0.35);
      }
      seg = [];
      segLight = [];
    }

    for (let i = 0; i < latLonArray.length; i++) {
      if (dashed && (i % 3 === 2)) {
        flushSeg();
        continue;
      }
      let pt = latLonToCam(latLonArray[i][0], latLonArray[i][1]);
      if (pt.nz <= 0.04 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.012)) {
        flushSeg();
        continue;
      }
      let press = 0.7 + 0.3 * pt.nz;
      seg.push([pt.x, pt.y, press]);
      segLight.push([pt.x + 0.85, pt.y + 0.85, press * 0.85]);
    }
    flushSeg();
  }

  // A) Meridians of Right Ascension (every 15 degrees)
  for (let lon = -180; lon < 180; lon += 15) {
    let pts = [];
    for (let lat = -86; lat <= 86; lat += 3) {
      pts.push([lat, lon]);
    }
    let isColure = (lon % 90 === 0);
    drawEngravedSphericalCurve(pts, isColure ? 0.28 : 0.18);
  }

  // B) Parallels of Declination (every 15 degrees)
  for (let lat = -75; lat <= 75; lat += 15) {
    if (lat === 0) continue; // Equator drawn separately below
    let pts = [];
    for (let lon = -180; lon <= 180; lon += 3) {
      pts.push([lat, lon]);
    }
    drawEngravedSphericalCurve(pts, 0.18);
  }

  // C) Celestial Equator (Double engraved ring with degree graduation ticks)
  for (let dLat of [-0.65, 0.65]) {
    let pts = [];
    for (let lon = -180; lon <= 180; lon += 2) pts.push([dLat, lon]);
    drawEngravedSphericalCurve(pts, 0.26);
  }
  for (let lon = -180; lon < 180; lon += 2) {
    let p1 = latLonToCam(-0.65, lon);
    let p2 = latLonToCam(0.65, lon);
    if (p1.nz > 0.06 && !isInsideHole(p1.nx, p1.ny, p1.nz, 0.012)) {
      brush.set("rotring", (lon % 10 === 0) ? "#d4af72" : "#2b1a0c", (lon % 10 === 0) ? 0.24 : 0.16);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // D) Tropics of Cancer & Capricorn (+/- 23.5 deg) and Polar Circles (+/- 66.5 deg)
  for (let specialLat of [-66.5, -23.5, 23.5, 66.5]) {
    let pts = [];
    for (let lon = -180; lon <= 180; lon += 2) pts.push([specialLat, lon]);
    drawEngravedSphericalCurve(pts, 0.21, false, true);
  }

  // E) The Ecliptic Great Circle (Tilted 23.5 deg to Celestial Equator, triple graduated band)
  function eclipticLatLon(ecLonDeg, latOffset = 0) {
    let l = ecLonDeg * Math.PI / 180;
    let ob = 23.5 * Math.PI / 180;
    let b = latOffset * Math.PI / 180;
    let x = Math.cos(b) * Math.sin(l);
    let y = Math.cos(b) * Math.cos(l) * Math.sin(ob) + Math.sin(b) * Math.cos(ob);
    let z = Math.cos(b) * Math.cos(l) * Math.cos(ob) - Math.sin(b) * Math.sin(ob);
    let lat = Math.asin(constrain(y, -1, 1)) * 180 / Math.PI;
    let lon = Math.atan2(x, z) * 180 / Math.PI;
    return [lat, lon];
  }

  for (let off of [-0.85, 0, 0.85]) {
    let pts = [];
    for (let el = -180; el <= 180; el += 2) pts.push(eclipticLatLon(el, off));
    drawEngravedSphericalCurve(pts, off === 0 ? 0.18 : 0.26);
  }
  for (let el = -180; el < 180; el += 1.5) {
    let p1 = latLonToCam(...eclipticLatLon(el, -0.85));
    let p2 = latLonToCam(...eclipticLatLon(el,  0.85));
    if (p1.nz > 0.06 && !isInsideHole(p1.nx, p1.ny, p1.nz, 0.012)) {
      let isZodiacBorder = (Math.round(el) % 30 === 0);
      brush.set("rotring", isZodiacBorder ? "#dec082" : "#26170a", isZodiacBorder ? 0.28 : 0.16);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // F) Engraved Mythological Constellation Figures & Anatomical Contour Hatching
  drawConstellationFigures(drawEngravedSphericalCurve);

  // G) Constellation Alignment Lines, Star Rosettes & Milky Way Stipple
  drawStarsAndMilkyWay(drawEngravedSphericalCurve);
}

function drawConstellationFigures(drawCurve) {
  // Helper to draw an engraved contour band with parallel sepia cross-hatching on the sphere
  function drawEngravedRibbon(spineLatLon, widthDeg, hatchDensity = 1.0) {
    let leftEdge = [];
    let rightEdge = [];

    for (let i = 0; i < spineLatLon.length; i++) {
      let [lat, lon] = spineLatLon[i];
      let next = spineLatLon[Math.min(i + 1, spineLatLon.length - 1)];
      let prev = spineLatLon[Math.max(i - 1, 0)];
      let dLat = next[0] - prev[0];
      let dLon = (next[1] - prev[1]) * Math.cos(lat * Math.PI / 180);
      let m = Math.hypot(dLat, dLon) || 1;
      let nLat = -dLon / m;
      let nLon = (dLat / m) / Math.max(0.2, Math.cos(lat * Math.PI / 180));

      let taper = spineLatLon[i][2] !== undefined ? spineLatLon[i][2] : 1.0;
      let w = widthDeg * taper;

      let pL = [lat + nLat * w, lon + nLon * w];
      let pR = [lat - nLat * w, lon - nLon * w];
      leftEdge.push(pL);
      rightEdge.push(pR);

      // Fine sepia engraving cross-hatching across the anatomical form
      if (random() < hatchDensity) {
        let cL = latLonToCam(pL[0], pL[1]);
        let cM = latLonToCam(lat, lon);
        let cR = latLonToCam(pR[0], pR[1]);
        if (cM.nz > 0.06 && !isInsideHole(cM.nx, cM.ny, cM.nz, 0.012)) {
          brush.set("rotring", "#332010", 0.15);
          brush.spline([[cL.x, cL.y, 0.4], [cM.x, cM.y + 1.2, 0.9], [cR.x, cR.y, 0.3]], 0.4);
          if (i % 2 === 0) {
            brush.set("rotring", "#bfa065", 0.13);
            brush.line(cL.x, cL.y, cM.x, cM.y);
          }
        }
      }
    }
    drawCurve(leftEdge, 0.22);
    drawCurve(rightEdge, 0.22);
  }

  // 1. DRACO (The Celestial Dragon) coiling around the North Pole & weaving between the Finger Holes!
  const dracoSpine = [
    [68, -45, 0.4], [64, -32, 0.7], [58, -18, 1.0], [50, -8, 1.15],
    [42, -16, 1.1], [35, -28, 1.0], [28, -36, 0.95], [20, -30, 0.9],
    [15, -18, 0.85], [18, -5, 0.8], [26, 6, 0.7], [34, 14, 0.55], [41, 20, 0.3]
  ];
  drawEngravedRibbon(dracoSpine, 2.4, 0.95);
  // Dragon dorsal crest fins & scales
  for (let i = 1; i < dracoSpine.length - 1; i++) {
    let [lat, lon] = dracoSpine[i];
    drawCurve([[lat, lon], [lat + 3.2, lon - 2.5], [lat + 1.5, lon + 1.8]], 0.17);
  }

  // 2. CYGNUS (The Swan) soaring across the upper-right hemisphere with feathered wings
  const cygnusBody = [
    [16, 10, 0.25], [22, 15, 0.45], [29, 20, 0.95], [36, 25, 1.15],
    [43, 30, 0.9], [49, 35, 0.55]
  ];
  drawEngravedRibbon(cygnusBody, 2.2, 0.9);
  // Outstretched feathered wings of Cygnus
  for (let f = 0; f < 9; f++) {
    let t = f / 8;
    let baseLat = lerp(27, 41, t);
    let baseLon = lerp(18, 28, t);
    let wingL = [
      [baseLat, baseLon],
      [baseLat + lerp(6, 2, t), baseLon - lerp(12, 18, t)],
      [baseLat + lerp(10, 4, t), baseLon - lerp(20, 26, t)]
    ];
    let wingR = [
      [baseLat, baseLon],
      [baseLat - lerp(6, 2, t), baseLon + lerp(12, 18, t)],
      [baseLat - lerp(10, 4, t), baseLon + lerp(20, 26, t)]
    ];
    drawCurve(wingL, 0.19);
    drawCurve(wingR, 0.19);
  }

  // 3. CETUS / HYDRA (The Sea Monster) coiling across the lower hemisphere
  const cetusSpine = [
    [-12, -48, 0.8], [-18, -36, 1.1], [-24, -22, 1.25], [-21, -8, 1.1],
    [-15, 4, 0.95], [-19, 16, 1.05], [-28, 24, 0.9], [-36, 18, 0.75],
    [-41, 8, 0.55], [-38, -2, 0.35]
  ];
  drawEngravedRibbon(cetusSpine, 2.6, 0.95);
  // Fluked tail & sea-scroll flourishes
  drawCurve([[-38, -2], [-43, -8], [-46, -4]], 0.2);
  drawCurve([[-38, -2], [-34, -9], [-37, -13]], 0.2);

  // 4. CASSIOPEIA / ANDROMEDA figure & flowing drapery in upper-right/polar zone
  const andromedaSpine = [
    [48, 42, 0.6], [42, 48, 0.95], [34, 52, 1.1], [25, 50, 1.0], [16, 46, 0.75]
  ];
  drawEngravedRibbon(andromedaSpine, 2.1, 0.85);

  // 5. ORION / OPHIUCHUS torso & billowing sash in left-equatorial zone (framing the thumb hole)
  const orionTorso = [
    [10, -48, 0.9], [4, -44, 1.2], [-3, -40, 1.0], [-10, -37, 1.1], [-17, -42, 0.85]
  ];
  drawEngravedRibbon(orionTorso, 2.5, 0.9);
  // Flowing celestial sash around the thumb hole
  const sash = [
    [4, -38, 0.5], [1, -28, 0.7], [-3, -18, 0.8], [-7, -8, 0.6], [-4, 2, 0.3]
  ];
  drawEngravedRibbon(sash, 1.4, 0.8);

  // 6. Ornate 18th-Century Baroque Cartouche Oval in the lower-left/center-bottom
  let cartLat = -38, cartLon = -26;
  for (let ring = 0; ring < 2; ring++) {
    let rLat = 6.2 + ring * 1.1;
    let rLon = 11.5 + ring * 1.6;
    let ovalPts = [];
    for (let a = 0; a <= 360; a += 8) {
      let rad = a * Math.PI / 180;
      let wobble = ring === 1 ? 0.6 * Math.sin(a * 6 * Math.PI / 180) : 0;
      ovalPts.push([cartLat + (rLat + wobble) * Math.sin(rad), cartLon + (rLon + wobble) * Math.cos(rad)]);
    }
    drawCurve(ovalPts, ring === 0 ? 0.24 : 0.18);
  }
  // Faux-calligraphic Latin inscription lines inside the cartouche
  for (let row = -3; row <= 3; row += 2) {
    let linePts = [];
    for (let dl = -7.5; dl <= 7.5; dl += 1.5) {
      linePts.push([cartLat + row + 0.35 * Math.sin(dl * 2), cartLon + dl]);
    }
    drawCurve(linePts, 0.16);
  }

  // 7. Engraved Calligraphic Constellation Banner Labels along the Sphere
  const banners = [
    { lat: 46, lon: -20, span: 14 }, // DRACO
    { lat: 33, lon: 14,  span: 12 }, // CYGNUS
    { lat: -14, lon: -18, span: 15 }, // CETUS
    { lat: 2,  lon: 12,  span: 16 }  // AEQUATOR
  ];
  for (let b of banners) {
    for (let dl = -b.span * 0.5; dl <= b.span * 0.5; dl += 1.4) {
      let p1 = latLonToCam(b.lat - 0.8, b.lon + dl);
      let p2 = latLonToCam(b.lat + 0.8, b.lon + dl + 0.5);
      if (p1.nz > 0.08 && !isInsideHole(p1.nx, p1.ny, p1.nz, 0.015)) {
        brush.set("rotring", "#2b1a0c", 0.18);
        brush.line(p1.x, p1.y, p2.x, p2.y);
        brush.set("rotring", "#cfa968", 0.14);
        brush.line(p1.x + 1.2, p1.y, p2.x + 0.8, p2.y);
      }
    }
  }
}

function drawStarsAndMilkyWay(drawCurve) {
  // 1) Via Lactea (Milky Way) dense stippled sepia & warm gold star band
  for (let i = 0; i < 650; i++) {
    let t = random(-80, 80);
    let mwLat = t + random(-7, 7);
    let mwLon = 22 * Math.sin(t * 0.045) + 12 + random(-11, 11);
    let pt = latLonToCam(mwLat, mwLon);
    if (pt.nz <= 0.05 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.01)) continue;

    let col = random() < 0.45 ? "#d4b070" : "#2e1c0e";
    brush.set("rotring", col, random(0.14, 0.26));
    brush.line(pt.x, pt.y, pt.x + random(-1.2, 1.2), pt.y + random(-1.2, 1.2));
  }

  // 2) Principal Constellation Star Networks & Engraved Star Rosettes
  const constellations = [
    // Cygnus Cross
    [[16, 10], [29, 20], [36, 25], [43, 30], [49, 35]],
    [[37, 8], [36, 25], [32, 42]],
    // Draco Coils
    [[68, -45], [64, -32], [58, -18], [50, -8], [42, -16], [35, -28], [28, -36], [20, -30], [15, -18], [18, -5], [26, 6], [34, 14]],
    // Cetus / Sea Monster
    [[-12, -48], [-18, -36], [-24, -22], [-21, -8], [-15, 4], [-19, 16], [-28, 24], [-36, 18], [-38, -2]],
    // Orion / Equatorial Triad
    [[10, -48], [4, -44], [-3, -40], [-10, -37], [-17, -42]],
    // Aquila & Delphinus
    [[8, 22], [12, 28], [15, 34], [9, 31], [4, 27]],
    // Cassiopeia W
    [[58, 28], [54, 36], [57, 44], [52, 52], [56, 60]]
  ];

  for (let chain of constellations) {
    drawCurve(chain, 0.19, false, true);
    for (let [lat, lon] of chain) {
      let pt = latLonToCam(lat, lon);
      if (pt.nz <= 0.06 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.015)) continue;
      drawStarRosette(pt.x, pt.y, random(4.5, 8.5), pt.nz);
    }
  }

  // Additional scattered 2nd–5th magnitude stars across the entire visible sphere
  for (let i = 0; i < 140; i++) {
    let lat = asin(random(-0.96, 0.96)); // degrees in p5 DEGREES mode
    let lon = random(-110, 110);
    let pt = latLonToCam(lat, lon);
    if (pt.nz <= 0.06 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.015)) continue;
    let r = random() < 0.22 ? random(4.0, 6.8) : random(1.8, 3.4);
    drawStarRosette(pt.x, pt.y, r, pt.nz);
  }
}

function drawStarRosette(x, y, rad, nz) {
  let r = rad * (0.65 + 0.35 * nz);
  let rays = r > 4.2 ? 8 : 4;

  // Dark sepia incised outer rays
  brush.set("rotring", "#1f1207", 0.2);
  for (let i = 0; i < rays; i++) {
    let a = i * (180 / rays);
    let len = (i % 2 === 0) ? r : r * 0.62;
    brush.line(x - cos(a) * len, y - sin(a) * len, x + cos(a) * len, y + sin(a) * len);
  }
  // Warm gilt/ochre star core
  brush.set("rotring", "#f0d394", r > 4.2 ? 0.36 : 0.24);
  brush.line(x - 0.8, y - 0.8, x + 0.8, y + 0.8);
}

// =============================================================================
// 8. AGED CRAQUELURE NETWORK ACROSS THE VARNISHED SPHERE
// =============================================================================
function drawCraquelure() {
  // Generate branching stress-crack paths in 3D sphere coordinates
  for (let c = 0; c < 68; c++) {
    let lat = random(-72, 75);
    let lon = random(-82, 82);
    let dir = random(360);
    let steps = int(random(8, 18));

    let crackPts = [];
    let crackGlint = [];

    for (let s = 0; s < steps; s++) {
      let pt = latLonToCam(lat, lon);
      if (pt.nz <= 0.05 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.01)) break;

      crackPts.push([pt.x, pt.y, 0.65]);
      crackGlint.push([pt.x + 0.75, pt.y + 0.75, 0.5]);

      // Branch secondary crack occasionally
      if (s === int(steps * 0.5) && random() < 0.65) {
        let bLat = lat, bLon = lon;
        let bDir = dir + (random() < 0.5 ? 78 : -82);
        let bPts = [];
        for (let bs = 0; bs < 6; bs++) {
          let bpt = latLonToCam(bLat, bLon);
          if (bpt.nz <= 0.05 || isInsideHole(bpt.nx, bpt.ny, bpt.nz, 0.01)) break;
          bPts.push([bpt.x, bpt.y, 0.5]);
          bLat += sin(bDir) * 1.9;
          bLon += cos(bDir) * 1.9 / Math.max(0.25, cos(bLat));
          bDir += random(-18, 18);
        }
        if (bPts.length >= 2) {
          brush.set("rotring", "#1a0f06", 0.14);
          brush.spline(bPts, 0.25);
        }
      }

      lat += sin(dir) * 2.2;
      lon += cos(dir) * 2.2 / Math.max(0.25, cos(lat));
      dir += random(-22, 22);
    }

    if (crackPts.length >= 3) {
      // Warm amber edge highlight along the crack lip
      brush.set("rotring", "#c9a362", 0.13);
      brush.spline(crackGlint, 0.25);
      // Dark oxidized varnish fissure
      brush.set("rotring", "#1a0f06", 0.16);
      brush.spline(crackPts, 0.25);
    }
  }
}

// =============================================================================
// 9. SCUFFED LANE POLISH, BOWLER'S TRACK SCRATCHES & MUSEUM SPOTLIGHT SPECULAR
// =============================================================================
function drawLanePolishAndSpecular() {
  // A) Bowler's Oil-Track Scuff Rings & Tangential Lane Scratches
  // Real bowling balls develop parallel sets of curved scuff arcs from rolling down the lane
  const trackBands = [
    { lat0: -35, lon0: -55, dLat: 1.8, dLon: 2.2, count: 26 },
    { lat0: 15,  lon0: -60, dLat: -1.4, dLon: 2.4, count: 22 },
    { lat0: -5,  lon0: 35,  dLat: 2.1, dLon: -1.5, count: 18 }
  ];

  for (let tb of trackBands) {
    for (let k = 0; k < tb.count; k++) {
      let lat = tb.lat0 + random(-14, 14);
      let lon = tb.lon0 + random(-18, 18);
      let pts = [];
      let steps = int(random(6, 13));
      let nSample = latLonToCam(lat, lon);
      let lightVal = dot3([nSample.nx, nSample.ny, nSample.nz], LIGHT_MAIN);

      for (let s = 0; s < steps; s++) {
        let p = latLonToCam(lat, lon);
        if (p.nz <= 0.08 || isInsideHole(p.nx, p.ny, p.nz, 0.012)) break;
        pts.push([p.x, p.y, (s === 0 || s === steps - 1) ? 0.25 : 0.85]);
        lat += tb.dLat + random(-0.25, 0.25);
        lon += tb.dLon + random(-0.25, 0.25);
      }

      if (pts.length >= 3) {
        let scuffCol = lightVal > 0.55 ? "#d9c79e" : (lightVal > 0.25 ? "#6e8e94" : "#283e45");
        brush.set("2H", scuffCol, random(0.14, 0.24));
        brush.spline(pts, 0.45);
      }
    }
  }

  // B) Diffuse & Glossy Museum Spotlight Specular Reflection (Upper-Left Hemisphere)
  // Center of specular reflection on sphere normal: halfway between viewer (0,0,1) and LIGHT_MAIN
  let H = normalize3([LIGHT_MAIN[0], LIGHT_MAIN[1], LIGHT_MAIN[2] + 1.0]);
  let specCx = CX + H[0] * R;
  let specCy = CY + H[1] * R;

  // Soft warm glow around the specular highlight
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fill("#e8cfa0", 28);
  brush.circle(specCx, specCy, 92, 0.25);
  brush.fill("#fff2d6", 34);
  brush.circle(specCx - 8, specCy - 6, 48, 0.2);
  brush.noFill();

  // Concentric scuffed polish swirl marks & broken specular arcs around H
  for (let i = 0; i < 135; i++) {
    let rAng = random(0.015, 0.24);
    let aStart = random(360);
    let aSpan = random(28, 95);

    // Local tangent basis around specular center H
    let up = [0, 1, 0];
    let T1 = normalize3(cross3(up, H));
    let T2 = cross3(H, T1);

    let pts = [];
    for (let a = aStart; a <= aStart + aSpan; a += 10) {
      let ca = cos(a);
      let sa = sin(a);
      let p = normalize3([
        H[0] * Math.cos(rAng) + (ca * T1[0] + sa * T2[0]) * Math.sin(rAng),
        H[1] * Math.cos(rAng) + (ca * T1[1] + sa * T2[1]) * Math.sin(rAng),
        H[2] * Math.cos(rAng) + (ca * T1[2] + sa * T2[2]) * Math.sin(rAng)
      ]);
      if (p[2] <= 0.1 || isInsideHole(p[0], p[1], p[2], 0.01)) break;
      pts.push([CX + p[0] * R, CY + p[1] * R, 0.8]);
    }

    if (pts.length >= 3) {
      let col = rAng < 0.08 ? "#fff8e8" : (rAng < 0.15 ? "#e6cfa2" : "#96b5b8");
      let w = rAng < 0.08 ? random(0.28, 0.52) : random(0.15, 0.28);
      brush.set(rAng < 0.09 ? "cpencil" : "2H", col, w);
      brush.spline(pts, 0.5);
    }
  }

  // Tiny lane-chatter impact pits & micro-nicks catching the light
  for (let i = 0; i < 85; i++) {
    let lat = random(-55, 65);
    let lon = random(-70, 65);
    let pt = latLonToCam(lat, lon);
    if (pt.nz <= 0.15 || isInsideHole(pt.nx, pt.ny, pt.nz, 0.015)) continue;
    let l = dot3([pt.nx, pt.ny, pt.nz], LIGHT_MAIN);
    if (l < 0.2) continue;

    brush.set("rotring", "#121a1e", 0.22);
    brush.line(pt.x - 1.5, pt.y - 0.8, pt.x + 1.2, pt.y + 0.5);
    brush.set("rotring", "#ebd5a7", 0.2);
    brush.line(pt.x - 1.0, pt.y + 1.1, pt.x + 1.6, pt.y + 1.4);
  }
}

// =============================================================================
// 10B. TURNED BRASS POLAR TRUNNION MOUNTS & BOTTOM CRADLE GUIDE
// =============================================================================
function drawPolarMountsAndCradle() {
  // 1) North Pole (theta = 90) and South Pole (theta = 270) turned brass axial pins
  const poles = [
    { th: 90,  isNorth: true },
    { th: 270, isNorth: false }
  ];

  for (let pole of poles) {
    let pBall = ringPoint3D(pole.th, R - 2, 0);
    let pRingIn = ringPoint3D(pole.th, 414, 0);
    let pFinial = ringPoint3D(pole.th, 494, 0);

    // Axis direction and perpendicular collar direction in 2D
    let dx = pRingIn.x - pBall.x;
    let dy = pRingIn.y - pBall.y;
    let len = Math.hypot(dx, dy) || 1;
    let ux = dx / len, uy = dy / len;
    let nx = -uy, ny = ux;

    // Turned brass socket collar on the sphere pole + cylindrical pin into the meridian ring
    for (let s = -14; s <= 14; s += 2) {
      let c = s < -4 ? "#362810" : (s < 5 ? "#b89443" : "#f0d58e");
      brush.set("marker", c, 0.55);
      // Collar at sphere surface
      brush.line(pBall.x + nx * s, pBall.y + ny * s, pBall.x + ux * 10 + nx * s * 0.85, pBall.y + uy * 10 + ny * s * 0.85);
      // Axial pin bridging to the meridian ring
      if (Math.abs(s) <= 8) {
        brush.line(pBall.x + ux * 8 + nx * s, pBall.y + uy * 8 + ny * s, pRingIn.x + nx * s, pRingIn.y + ny * s);
      }
      // Outer turned brass finial beyond the outer edge of the ring
      let pOut = ringPoint3D(pole.th, 468, 8);
      if (Math.abs(s) <= 9) {
        brush.line(pOut.x + nx * s, pOut.y + ny * s, pFinial.x + nx * s * 0.35, pFinial.y + ny * s * 0.35);
      }
    }
    // Crisp dark engraved grooves on the turned brass collar
    brush.set("rotring", "#1a1206", 0.24);
    brush.line(pBall.x - nx * 15, pBall.y - ny * 15, pBall.x + nx * 15, pBall.y + ny * 15);
    brush.line(pRingIn.x - nx * 11, pRingIn.y - ny * 11, pRingIn.x + nx * 11, pRingIn.y + ny * 11);
  }

  // 2) Bottom Antique Brass & Ebonized Wood Support Cradle (at bottom of Meridian Ring)
  // Find lowest point of the meridian ring near theta = 290..315
  let pBase = ringPoint3D(298, 455, 10);
  let bx = pBase.x;
  let by = pBase.y;

  // Turned pedestal pillar descending from the ring guide to the bottom of the frame
  for (let xOff = -38; xOff <= 38; xOff += 2.5) {
    let normX = xOff / 38;
    let shade = 0.5 - 0.45 * normX + 0.25 * Math.pow(Math.max(0, 1 - Math.abs(normX + 0.35) * 2.2), 2);
    let col = shade > 0.72 ? "#d4b262" : (shade > 0.48 ? "#8a6b2d" : (shade > 0.28 ? "#453415" : "#1c1508"));
    brush.set("marker", col, 0.7);
    // Upper brass cradle jaws gripping the meridian ring
    brush.line(bx + xOff * 0.75, by - 16, bx + xOff * 0.9, by + 26);
    // Flared turned dark wood & bronze column below
    let wCol = shade > 0.65 ? "#4a3321" : (shade > 0.38 ? "#261910" : "#0f0a07");
    brush.set("marker", wCol, 0.8);
    brush.line(bx + xOff * 0.85, by + 26, bx + xOff * 1.65, 1175);
  }

  // Turned brass molding rings and locking thumbscrew on the cradle
  for (let ry of [by - 15, by + 25, by + 42, 1135]) {
    let halfW = ry > 1100 ? 58 : 34;
    brush.set("marker", "#c9a552", 0.65);
    brush.line(bx - halfW, ry, bx + halfW * 0.4, ry);
    brush.set("marker", "#473514", 0.65);
    brush.line(bx + halfW * 0.4, ry, bx + halfW, ry);
    brush.set("rotring", "#140e04", 0.28);
    brush.line(bx - halfW - 2, ry + 3, bx + halfW + 2, ry + 3);
  }
}

