// ============================================================================
// CORE GEOMETRY & MARKER HELPERS
// ============================================================================

function drawPoly(pts, washCol, washAlpha, strokeBrush, strokeCol, strokeW, curvature = 0.08, hatchCol = null, hatchDist = 6, hatchAngle = 0, hatchW = 1.0) {
  if (!pts || pts.length < 3) return;
  brush.noField();
  brush.noFill();
  if (washCol) {
    brush.wash(washCol, washAlpha !== undefined ? washAlpha : 248);
  } else {
    brush.noWash();
  }
  if (hatchCol) {
    brush.hatchStyle("felt_chisel", hatchCol, hatchW);
    brush.hatch(hatchDist, hatchAngle, { rand: 0.03 });
  } else {
    brush.noHatch();
  }
  if (strokeCol && strokeBrush) {
    brush.set(strokeBrush, strokeCol, strokeW || 0.35);
  } else if (washCol) {
    brush.set("fine_liner", washCol, 0.2);
  } else {
    brush.set("fine_liner", "#1a0d08", 0.2);
  }
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
  brush.noHatch();
  brush.set("rotring", "#1a0d08", 0.3);
}

function evalCubic(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t, uu = u * u;
  let uuu = uu * u, ttt = tt * t;
  return [
    uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
    uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1]
  ];
}

function evalCubicTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let len = sqrt(dx * dx + dy * dy) || 1;
  return [dx / len, dy / len];
}

function makeEllipsePts(cx, cy, rx, ry, rotDeg, n = 28) {
  let pts = [];
  let ca = cos(rotDeg), sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let lx = cos(a) * rx;
    let ly = sin(a) * ry;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

