// ============================================================================
// 2. BUNDLED SUGARCANE (HYPERREAL NODES, WAX RINGS, ROOT DOTS, CUT ENDS)
// ============================================================================

function drawSugarcaneLeaf(x1, y1, cx, cy, x2, y2, w, baseCol, edgeCol, midribCol) {
  let steps = 16;
  let leftPts = [];
  let rightPts = [];
  let midPts = [];
  let p0 = [x1, y1], p1 = [lerp(x1, cx, 0.7), lerp(y1, cy, 0.7)], p2 = [lerp(cx, x2, 0.4), lerp(cy, y2, 0.4)], p3 = [x2, y2];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubic(p0, p1, p2, p3, t);
    let tan = evalCubicTangent(p0, p1, p2, p3, t);
    let nx = -tan[1], ny = tan[0];
    let profile = sin(t * 180) * (1 - 0.35 * t);
    if (t < 0.15) profile = map(t, 0, 0.15, 0.35, sin(0.15 * 180));
    let hw = w * 0.5 * profile;
    leftPts.push([pt[0] + nx * hw, pt[1] + ny * hw]);
    rightPts.unshift([pt[0] - nx * hw, pt[1] - ny * hw]);
    midPts.push([pt[0], pt[1], 0.9 - 0.6 * t]);
  }
  let poly = leftPts.concat(rightPts);
  drawPoly(poly, baseCol, 248, "fine_liner", "#04381a", 0.35, 0.08);

  // Parallel leaf venation
  brush.set("fine_liner", edgeCol, 0.22);
  for (let s of [-0.55, 0.55]) {
    let vPts = [];
    for (let i = 1; i < steps; i++) {
      let t = i / steps;
      let pt = evalCubic(p0, p1, p2, p3, t);
      let tan = evalCubicTangent(p0, p1, p2, p3, t);
      let nx = -tan[1], ny = tan[0];
      let hw = w * 0.5 * sin(t * 180) * (1 - 0.35 * t) * s;
      vPts.push([pt[0] + nx * hw, pt[1] + ny * hw, 0.6]);
    }
    brush.spline(vPts, 0.25);
  }

  // Crisp pale midrib
  brush.set("cpencil", midribCol, 0.55);
  brush.spline(midPts, 0.25);
  brush.set("fine_liner", "#ffffff", 0.22);
  brush.spline(midPts.slice(0, 12), 0.25);
}

function drawSingleSugarcaneStalk(x1, y1, x2, y2, w, scheme) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ux = dx / len, uy = dy / len;
  let nx = -uy, ny = ux;
  let ang = atan2(dy, dx);

  let palettes = {
    plum: { base: "#731430", mid: "#9e2042", dark: "#300512", light: "#d95b72", spec: "#ffd9e0" },
    vermilion: { base: "#b82918", mid: "#e04824", dark: "#4f0d05", light: "#ff8c59", spec: "#ffe4d1" },
    emerald: { base: "#147838", mid: "#28a64e", dark: "#063616", light: "#7be077", spec: "#e3ffde" },
    gold: { base: "#cf8508", mid: "#f0b418", dark: "#593202", light: "#ffe666", spec: "#fffbe0" },
    striped: { base: "#8f1d2c", mid: "#d99b16", dark: "#380810", light: "#ffe066", spec: "#fff5cc" }
  };
  let pal = palettes[scheme] || palettes.plum;

  let numNodes = floor(len / 56);
  let segLen = len / max(1, numNodes);

  // Draw internode segments
  for (let s = 0; s < numNodes; s++) {
    let d0 = s * segLen;
    let d1 = (s + 1) * segLen;
    let sx0 = x1 + ux * d0, sy0 = y1 + uy * d0;
    let sx1 = x1 + ux * d1, sy1 = y1 + uy * d1;
    let smx = (sx0 + sx1) * 0.5, smy = (sy0 + sy1) * 0.5;
    let hwEnd = w * 0.5;
    let hwMid = w * 0.46; // slight waist between nodes

    let segPoly = [
      [sx0 + nx * hwEnd, sy0 + ny * hwEnd],
      [smx + nx * hwMid, smy + ny * hwMid],
      [sx1 + nx * hwEnd, sy1 + ny * hwEnd],
      [sx1 - nx * hwEnd, sy1 - ny * hwEnd],
      [smx - nx * hwMid, smy - ny * hwMid],
      [sx0 - nx * hwEnd, sy0 - ny * hwEnd]
    ];
    drawPoly(segPoly, pal.base, 250, "fine_liner", pal.dark, 0.35, 0.05, pal.mid, 4, ang, 0.7);

    // Cylindrical stripes & longitudinal vascular fibres
    for (let f = -0.82; f <= 0.85; f += 0.16) {
      let col = pal.mid;
      let lw = 0.35;
      if (f < -0.5) { col = pal.dark; lw = 0.55; }
      else if (f > 0.55) { col = pal.dark; lw = 0.5; }
      else if (f > -0.25 && f < 0.15) { col = pal.light; lw = 0.48; }
      else if (scheme === "striped" && abs(sin(f * 360)) > 0.5) { col = "#248f40"; lw = 0.45; }

      brush.set("cpencil", col, lw);
      let lx0 = sx0 + nx * (hwEnd * f), ly0 = sy0 + ny * (hwEnd * f);
      let lmx = smx + nx * (hwMid * f), lmy = smy + ny * (hwMid * f);
      let lx1 = sx1 + nx * (hwEnd * f), ly1 = sy1 + ny * (hwEnd * f);
      brush.spline([[lx0, ly0, 0.8], [lmx, lmy, 1.0], [lx1, ly1, 0.8]], 0.2);
    }

    // Glossy specular highlight streak on each internode
    let hx0 = sx0 + ux * 6 - nx * (w * 0.12), hy0 = sy0 + uy * 6 - ny * (w * 0.12);
    let hx1 = sx1 - ux * 8 - nx * (w * 0.12), hy1 = sy1 - uy * 8 - ny * (w * 0.12);
    brush.set("fine_liner", pal.spec, 0.36);
    brush.line(hx0, hy0, hx1, hy1);

    // Waxy white/pale-blue bloom ring just below the upper node
    let wx0 = sx0 + ux * 7, wy0 = sy0 + uy * 7;
    for (let wRow = 0; wRow < 3; wRow++) {
      let wx = wx0 + ux * (wRow * 2.2), wy = wy0 + uy * (wRow * 2.2);
      brush.set("cpencil", wRow === 0 ? "#e8f4f8" : "#c5d8e0", 0.42);
      brush.line(wx - nx * (hwEnd * 0.9), wy - ny * (hwEnd * 0.9), wx + nx * (hwEnd * 0.9), wy + ny * (hwEnd * 0.9));
    }
  }

  // Hyperreal Nodes (growth rings, root primordia dots, alternating lateral buds)
  for (let s = 1; s < numNodes; s++) {
    let nd = s * segLen;
    let cx = x1 + ux * nd, cy = y1 + uy * nd;
    let hw = w * 0.54;

    // Swollen woody node ridge
    let nPoly = [
      [cx - ux * 3.5 + nx * hw, cy - uy * 3.5 + ny * hw],
      [cx + ux * 3.5 + nx * hw, cy + uy * 3.5 + ny * hw],
      [cx + ux * 3.5 - nx * hw, cy + uy * 3.5 - ny * hw],
      [cx - ux * 3.5 - nx * hw, cy - uy * 3.5 - ny * hw]
    ];
    drawPoly(nPoly, "#c49a6c", 245, "fine_liner", "#2b1204", 0.35, 0.1);

    // Dark scar line and pale rim
    brush.set("fine_liner", "#2b1204", 0.4);
    brush.line(cx + nx * hw, cy + ny * hw, cx - nx * hw, cy - ny * hw);
    brush.set("fine_liner", "#fff5d6", 0.25);
    brush.line(cx - ux * 2 + nx * (hw * 0.85), cy - uy * 2 + ny * (hw * 0.85), cx - ux * 2 - nx * (hw * 0.85), cy - uy * 2 - ny * (hw * 0.85));

    // Root primordia dots in two staggered rows
    for (let d = -0.78; d <= 0.8; d += 0.24) {
      let rx = cx + ux * 2.2 + nx * (hw * d);
      let ry = cy + uy * 2.2 + ny * (hw * d);
      brush.set("rotring", "#2b1204", 0.42);
      brush.line(rx - 0.8, ry - 0.8, rx + 0.8, ry + 0.8);
      brush.set("fine_liner", "#ffe8b3", 0.2);
      brush.line(rx - 0.4, ry - 0.4, rx + 0.2, ry + 0.2);
    }

    // Triangular lateral bud eye (alternating sides)
    let budSide = (s % 2 === 0 ? 0.35 : -0.35);
    let bx = cx - ux * 2 + nx * (hw * budSide);
    let by = cy - uy * 2 + ny * (hw * budSide);
    let budPoly = [
      [bx - nx * 3.2, by - ny * 3.2],
      [bx + nx * 3.2, by + ny * 3.2],
      [bx - ux * 7.5, by - uy * 7.5]
    ];
    drawPoly(budPoly, "#f0bd4f", 250, "fine_liner", "#3b1704", 0.3, 0.1);
  }

  // Cut fibrous cross-section at the top end (x2, y2)
  let endPts = makeEllipsePts(x2, y2, w * 0.24, w * 0.5, ang, 20);
  drawPoly(endPts, "#fff0b3", 255, "fine_liner", pal.dark, 0.45, 0.1);
  let innerPts = makeEllipsePts(x2, y2, w * 0.17, w * 0.38, ang, 16);
  drawPoly(innerPts, "#fae18c", 240, "fine_liner", "#d95b16", 0.28, 0.1);
  // Pith vascular dots
  brush.set("fine_liner", "#9e4411", 0.25);
  for (let k = 0; k < 7; k++) {
    let px = x2 + random(-w * 0.12, w * 0.12);
    let py = y2 + random(-w * 0.22, w * 0.22);
    brush.line(px - 0.6, py, px + 0.6, py);
  }
}

