function drawHyperrealMango(cx, cy, rx, ry, rotDeg, variant) {
  let pts = makeEllipsePts(cx, cy, rx, ry, rotDeg, 22);
  let baseCol = variant === 0 ? "#ff451f" : (variant === 1 ? "#ffd11a" : "#ff7b19");
  let secondCol = variant === 0 ? "#ffd11a" : (variant === 1 ? "#129e4a" : "#e62917");
  drawPoly(pts, baseCol, 252, "fine_liner", "#4a1204", 0.35, 0.12, secondCol, 4, rotDeg + 25, 0.85);

  // Blush shoulder
  let ca = cos(rotDeg), sa = sin(rotDeg);
  let bx = cx - rx * 0.25 * ca, by = cy - rx * 0.25 * sa;
  let blushPts = makeEllipsePts(bx, by, rx * 0.62, ry * 0.72, rotDeg, 16);
  drawPoly(blushPts, secondCol, 175, null, null, 0, 0.15);

  // Green crown kiss near stem
  let gx = cx - rx * 0.55 * ca, gy = cy - rx * 0.55 * sa;
  let greenPts = makeEllipsePts(gx, gy, rx * 0.32, ry * 0.48, rotDeg, 14);
  drawPoly(greenPts, "#169c48", 190, null, null, 0, 0.15);

  // Lenticel speckles on mango skin
  brush.set("fine_liner", "#4f1a06", 0.22);
  for (let i = 0; i < 16; i++) {
    let a = random(360), r = random(0.15, 0.82);
    let lx = cos(a) * rx * r, ly = sin(a) * ry * r;
    let px = cx + lx * ca - ly * sa;
    let py = cy + lx * sa + ly * ca;
    brush.line(px - 0.5, py, px + 0.5, py);
  }

  // Stem dimple & waxy specular highlight
  brush.set("rotring", "#291003", 0.45);
  brush.line(gx - 2, gy - 1, gx + 2, gy + 2);
  let hx = cx + (-rx * 0.15) * ca - (-ry * 0.38) * sa;
  let hy = cy + (-rx * 0.15) * sa + (-ry * 0.38) * ca;
  brush.set("cpencil", "#fff9d6", 0.65);
  brush.line(hx - 6 * ca, hy - 6 * sa, hx + 7 * ca, hy + 7 * sa);
}

function drawWovenBaskets() {
  // -------------------------------------------------------------------------
  // BASKET 2 (UPPER-CENTER-LEFT: COLORED HERRINGBONE TWILL BASKET)
  // -------------------------------------------------------------------------
  let b2TopY = 175, b2BotY = 445;
  let b2Cx = 535;
  let b2Rows = 12, b2Cols = 13;

  // Basket 2 silhouette base
  let b2Base = [];
  for (let i = 0; i <= b2Cols; i++) {
    let u = i / b2Cols;
    b2Base.push([b2Cx + (u - 0.5) * 285, b2TopY + sin(u * 180) * 18]);
  }
  for (let i = b2Cols; i >= 0; i--) {
    let u = i / b2Cols;
    b2Base.push([b2Cx + (u - 0.5) * 215, b2BotY + sin(u * 180) * 26]);
  }
  drawPoly(b2Base, "#421a05", 255, "rotring", "#240c02", 0.5, 0.05);

  // Basket 2 contents heaped above mouth (peppers, limes, garlic braids)
  let b2BackRim = makeEllipsePts(b2Cx, b2TopY + 6, 144, 34, -4, 24);
  drawPoly(b2BackRim, "#2e1103", 255, "rotring", "#1a0801", 0.4, 0.08);

  // Bright market cloth & produce in Basket 2
  drawPoly([[405, 182], [455, 130], [520, 152], [485, 195]], "#e62b17", 250, "fine_liner", "#590902", 0.35, 0.08, "#ff5c38", 4, 35, 0.8);
  drawPoly([[495, 175], [565, 122], [638, 155], [595, 196]], "#008f4c", 250, "fine_liner", "#02381c", 0.35, 0.08, "#29c46d", 4, -25, 0.8);

  // Scotch bonnet peppers & limes heaped in Basket 2
  let peppers = [
    [455, 165, 18, 14, "#ffd11a", "#c98200"],
    [488, 155, 20, 15, "#ff3319", "#7a0c02"],
    [522, 148, 19, 15, "#0eb866", "#044d26"],
    [555, 154, 21, 16, "#ffd11a", "#b87400"],
    [588, 162, 19, 14, "#ff3b1f", "#800e03"],
    [618, 172, 17, 13, "#ff9914", "#8c3d00"],
    [472, 176, 18, 14, "#14b058", "#04451f"],
    [508, 172, 21, 15, "#ff2e17", "#6e0902"],
    [542, 170, 20, 15, "#ffd624", "#a86800"],
    [575, 176, 18, 14, "#0eb866", "#03401c"]
  ];
  for (let p of peppers) {
    let pPts = makeEllipsePts(p[0], p[1], p[2], p[3], random(-25, 25), 16);
    drawPoly(pPts, p[4], 252, "fine_liner", p[5], 0.32, 0.12);
    // Pepper lobes & highlight
    brush.set("fine_liner", p[5], 0.25);
    brush.arc(p[0], p[1], p[3] * 0.65, 20, 160);
    brush.set("fine_liner", "#fffbe0", 0.3);
    brush.line(p[0] - 5, p[1] - 4, p[0] + 4, p[1] - 3);
    // Green stem pedicel
    brush.set("rotring", "#16692b", 0.45);
    brush.line(p[0], p[1] - p[3] * 0.7, p[0] + random(-4, 4), p[1] - p[3] * 1.25);
  }

  // Grid helper for Basket 2 wall
  function b2Pt(r, c) {
    let v = r / b2Rows;
    let u = c / b2Cols;
    let w = lerp(285, 212, v) + sin(v * 180) * 18;
    let x = b2Cx + (u - 0.5) * w - (1 - v) * 6;
    let y = lerp(b2TopY + 12, b2BotY, v) + sin(u * 180) * lerp(22, 28, v);
    return [x, y];
  }

  let twillPalette = ["#e89e38", "#d92b19", "#f5c45e", "#0047ab", "#c46d1b", "#008f4c"];
  for (let r = 0; r < b2Rows; r++) {
    for (let c = 0; c < b2Cols; c++) {
      let p00 = b2Pt(r, c), p10 = b2Pt(r, c + 1), p11 = b2Pt(r + 1, c + 1), p01 = b2Pt(r + 1, c);
      let colIdx = (r + c) % twillPalette.length;
      let cellCol = twillPalette[colIdx];
      let inset = 1.4;
      let cPoly = [
        [p00[0] + inset, p00[1] + inset],
        [p10[0] - inset, p10[1] + inset],
        [p11[0] - inset, p11[1] - inset],
        [p01[0] + inset, p01[1] - inset]
      ];
      drawPoly(cPoly, cellCol, 250, "fine_liner", "#2b1003", 0.28, 0.06);

      // Reed grain lines & center highlight
      let mx0 = (p00[0] + p01[0]) * 0.5, my0 = (p00[1] + p01[1]) * 0.5;
      let mx1 = (p10[0] + p11[0]) * 0.5, my1 = (p10[1] + p11[1]) * 0.5;
      brush.set("fine_liner", "#fff3cc", 0.22);
      brush.line(mx0 + 2, my0, mx1 - 2, my1);
      brush.set("fine_liner", "#240c02", 0.32);
      brush.line(p00[0], p00[1], p01[0], p01[1]);
    }
  }

  // Coiled rim of Basket 2
  for (let i = 0; i < 26; i++) {
    let u0 = i / 26, u1 = (i + 1) / 26;
    let p0 = b2Pt(0, u0 * b2Cols), p1 = b2Pt(0, u1 * b2Cols);
    let coilPoly = [
      [p0[0], p0[1] - 9],
      [p1[0], p1[1] - 9],
      [p1[0] + 2, p1[1] + 5],
      [p0[0] + 2, p0[1] + 5]
    ];
    drawPoly(coilPoly, i % 2 === 0 ? "#f2b857" : "#c77420", 252, "fine_liner", "#2e1103", 0.32, 0.1);
    brush.set("fine_liner", "#fff5d1", 0.22);
    brush.line((p0[0] + p1[0]) * 0.5, p0[1] - 6, (p0[0] + p1[0]) * 0.5 + 1, p0[1] + 2);
  }

  // -------------------------------------------------------------------------
  // BASKET 1 (LARGE FOREGROUND-LEFT ROUND REED *PANYE* BASKET WITH MANGOES)
  // -------------------------------------------------------------------------
  let b1Cx = 268, b1TopY = 235, b1BotY = 515;
  let b1Rows = 13, b1Cols = 14;

  // Dark mouth interior & back coiled rim
  let b1MouthPts = makeEllipsePts(b1Cx + 4, b1TopY - 6, 178, 56, -8, 30);
  drawPoly(b1MouthPts, "#2e1103", 255, "rotring", "#1a0801", 0.5, 0.08);
  let b1InnerRim = makeEllipsePts(b1Cx + 4, b1TopY - 2, 166, 46, -8, 26);
  drawPoly(b1InnerRim, "#471d07", 250, "fine_liner", "#1a0801", 0.35, 0.08);

  // Back rim coil stitches
  for (let i = 0; i < 22; i++) {
    let a = map(i, 0, 22, 185, 355);
    let ca = cos(-8), sa = sin(-8);
    let lx = cos(a) * 176, ly = sin(a) * 54;
    let rx = b1Cx + 4 + lx * ca - ly * sa;
    let ry = b1TopY - 6 + lx * sa + ly * ca;
    let stPts = makeEllipsePts(rx, ry, 7, 10, a + 80, 10);
    drawPoly(stPts, i % 2 === 0 ? "#d98932" : "#b36216", 250, "fine_liner", "#2b1003", 0.28, 0.1);
  }

  // Heaped Hyperreal Haitian *Mango Francique* inside Basket 1
  let mangoes = [
    [165, 222, 34, 24, -18, 0],
    [218, 202, 36, 25, 12, 1],
    [275, 192, 38, 26, -8, 2],
    [332, 195, 36, 25, 22, 0],
    [382, 208, 34, 24, -14, 1],
    [138, 244, 33, 23, 15, 2],
    [192, 234, 37, 26, -12, 0],
    [248, 224, 39, 27, 8, 1],
    [306, 220, 38, 26, -16, 2],
    [360, 226, 36, 25, 18, 0],
    [408, 232, 32, 22, -10, 1],
    [172, 256, 35, 24, 6, 1],
    [228, 252, 38, 26, -15, 0],
    [285, 246, 39, 27, 14, 2],
    [342, 246, 36, 25, -8, 1],
    [388, 248, 33, 23, 12, 0]
  ];
  for (let m of mangoes) {
    drawHyperrealMango(m[0], m[1], m[2], m[3], m[4], m[5]);
  }

  // Basket 1 curved cylindrical/bulbous wall grid
  function b1Pt(r, c) {
    let v = r / b1Rows;
    let u = c / b1Cols;
    let belly = sin(v * 180) * 34;
    let w = lerp(352, 254, v) + belly;
    let tiltY = (u - 0.5) * -42 * (1 - 0.35 * v);
    let archY = sin(u * 180) * lerp(48, 38, v);
    let x = b1Cx + (u - 0.5) * w;
    let y = lerp(b1TopY + 6, b1BotY, v) + tiltY + archY;
    return [x, y];
  }

  // Basket 1 dark under-shadow base
  let b1Outline = [];
  for (let c = 0; c <= b1Cols; c++) b1Outline.push(b1Pt(0, c));
  for (let r = 1; r <= b1Rows; r++) b1Outline.push(b1Pt(r, b1Cols));
  for (let c = b1Cols - 1; c >= 0; c--) b1Outline.push(b1Pt(b1Rows, c));
  for (let r = b1Rows - 1; r >= 1; r--) b1Outline.push(b1Pt(r, 0));
  drawPoly(b1Outline, "#381504", 255, "rotring", "#1f0a01", 0.55, 0.05);

  // Continuous vertical split-bamboo stakes (ribs)
  for (let c = 0; c <= b1Cols; c++) {
    let stakePts = [];
    for (let r = 0; r <= b1Rows; r++) {
      let pt = b1Pt(r, c);
      stakePts.push([pt[0], pt[1], 0.9]);
    }
    brush.set("felt_chisel", "#8c4610", 1.5);
    brush.spline(stakePts, 0.2);
    brush.set("fine_liner", "#ffdf94", 0.28);
    brush.spline(stakePts, 0.2);
  }

  // Individual woven horizontal reed strips passing over & under stakes
  let reedTones = ["#e89e3c", "#f5c56c", "#cf7b24", "#b55d14", "#f0b254", "#d9872b"];
  for (let r = 0; r < b1Rows; r++) {
    for (let c = 0; c < b1Cols; c++) {
      let p00 = b1Pt(r, c), p10 = b1Pt(r, c + 1), p11 = b1Pt(r + 1, c + 1), p01 = b1Pt(r + 1, c);
      let isOver = (r + c) % 2 === 0;
      let shade = c < 3 || c > b1Cols - 3 ? "#9e4d12" : reedTones[(r * 3 + c) % reedTones.length];
      if (!isOver) shade = "#873e0d";

      let padX = isOver ? -1.2 : 2.2;
      let padY = isOver ? 1.0 : 2.4;
      let cellPoly = [
        [p00[0] + padX, p00[1] + padY],
        [p10[0] - padX, p10[1] + padY],
        [p11[0] - padX, p11[1] - padY],
        [p01[0] + padX, p01[1] - padY]
      ];
      drawPoly(cellPoly, shade, 252, "fine_liner", "#2e1002", 0.28, 0.08);

      // Longitudinal bamboo fibre striations on each reed segment
      for (let g = 0.28; g <= 0.76; g += 0.22) {
        let gx0 = lerp(p00[0], p01[0], g), gy0 = lerp(p00[1], p01[1], g);
        let gx1 = lerp(p10[0], p11[0], g), gy1 = lerp(p10[1], p11[1], g);
        let gmx = (gx0 + gx1) * 0.5, gmy = (gy0 + gy1) * 0.5 - (isOver ? 1.5 : 0);
        brush.set("fine_liner", isOver && abs(g - 0.5) < 0.15 ? "#fff4c9" : "#522005", 0.22);
        brush.spline([[gx0 + 2, gy0, 0.6], [gmx, gmy, 1.0], [gx1 - 2, gy1, 0.6]], 0.2);
      }

      // Deep tuck shadows where weaver dives under vertical stake
      if (!isOver) {
        brush.set("rotring", "#1f0a01", 0.48);
        brush.line(p00[0] + 1.5, p00[1] + 1, p01[0] + 1.5, p01[1] - 1);
        brush.line(p10[0] - 1.5, p10[1] + 1, p11[0] - 1.5, p11[1] - 1);
      }
    }
  }

  // Heavy braided/coiled front rim of Basket 1
  for (let i = 0; i < 32; i++) {
    let u0 = i / 32, u1 = (i + 1) / 32;
    let p0 = b1Pt(0, u0 * b1Cols), p1 = b1Pt(0, u1 * b1Cols);
    let rPoly = [
      [p0[0] - 2, p0[1] - 11],
      [p1[0] + 1, p1[1] - 11],
      [p1[0] + 3, p1[1] + 7],
      [p0[0] + 1, p0[1] + 7]
    ];
    let rimCol = i % 2 === 0 ? "#f2b852" : "#c97620";
    drawPoly(rPoly, rimCol, 255, "fine_liner", "#2b1003", 0.35, 0.12);

    // Individual rattan wrap highlights
    let mx = (p0[0] + p1[0]) * 0.5, my = (p0[1] + p1[1]) * 0.5;
    brush.set("cpencil", "#fff6d6", 0.45);
    brush.line(mx - 1, my - 8, mx + 2, my + 4);
  }
}

// ============================================================================
// 4. CRATED HENS (WOODEN SLATS, STRAW, HYPERREAL FEATHER BARBS & COMBS)
// ============================================================================

function drawHyperrealFeather(x, y, len, wid, angDeg, baseCol, edgeCol, barbCol, shaftCol) {
  let ca = cos(angDeg), sa = sin(angDeg);
  let nx = -sa, ny = ca;
  let hw = wid * 0.5;

  let pts = [
    [x, y],
    [x + ca * (len * 0.35) + nx * (hw * 0.85), y + sa * (len * 0.35) + ny * (hw * 0.85)],
    [x + ca * (len * 0.78) + nx * hw, y + sa * (len * 0.78) + ny * hw],
    [x + ca * len, y + sa * len],
    [x + ca * (len * 0.78) - nx * hw, y + sa * (len * 0.78) - ny * hw],
    [x + ca * (len * 0.35) - nx * (hw * 0.85), y + sa * (len * 0.35) - ny * (hw * 0.85)]
  ];
  drawPoly(pts, baseCol, 248, "fine_liner", edgeCol, 0.25, 0.14);

  // Radiating individual feather barbs from central rachis
  brush.set("fibre_hair", barbCol, 0.22);
  for (let t = 0.22; t <= 0.88; t += 0.16) {
    let sx = x + ca * (len * t), sy = y + sa * (len * t);
    let bw = hw * sin(t * 180) * 0.95;
    let tipF = len * (t + 0.13);
    brush.line(sx, sy, x + ca * tipF + nx * bw, y + sa * tipF + ny * bw);
    brush.line(sx, sy, x + ca * tipF - nx * bw, y + sa * tipF - ny * bw);
  }

  // Crisp central feather shaft (rachis)
  brush.set("fine_liner", shaftCol, 0.22);
  brush.line(x + ca * 2, y + sa * 2, x + ca * (len * 0.94), y + sa * (len * 0.94));
}

function drawHenHead(hx, hy, dir, scaleF) {
  // Fleshy Vermilion Comb with serrated lobes and papillate bumps
  let combPts = [
    [hx - dir * 14 * scaleF, hy - 6 * scaleF],
    [hx - dir * 22 * scaleF, hy - 22 * scaleF],
    [hx - dir * 12 * scaleF, hy - 16 * scaleF],
    [hx - dir * 10 * scaleF, hy - 29 * scaleF],
    [hx - dir * 2 * scaleF, hy - 19 * scaleF],
    [hx + dir * 4 * scaleF, hy - 31 * scaleF],
    [hx + dir * 9 * scaleF, hy - 19 * scaleF],
    [hx + dir * 17 * scaleF, hy - 26 * scaleF],
