function drawHyperrealHenBody(cx, cy, dir, scaleF, style) {
  // 1. Arching Tail Plumes (drawn first at back of body)
  let tailBaseX = cx - dir * 52 * scaleF, tailBaseY = cy - 8 * scaleF;
  for (let t = 0; t < 8; t++) {
    let ang = dir === 1 ? map(t, 0, 7, 155, 228) : map(t, 0, 7, -48, 25);
    let fLen = (52 + (t % 3) * 10) * scaleF;
    let fWid = 15 * scaleF;
    let bCol = style === "barred" ? "#1c242b" : (t % 2 === 0 ? "#034d2c" : "#062147");
    let barbCol = style === "barred" ? "#e6eef5" : (t % 2 === 0 ? "#24cf7a" : "#3b82f6");
    drawHyperrealFeather(tailBaseX, tailBaseY + (3 - t) * 4 * scaleF, fLen, fWid, ang, bCol, "#050a08", barbCol, "#c9e8d5");
  }

  // 2. Plump Body Base Contour
  let bodyPts = makeEllipsePts(cx, cy + 6 * scaleF, 58 * scaleF, 42 * scaleF, -dir * 8, 24);
  let baseBodyCol = style === "barred" ? "#262b30" : (style === "creole" ? "#9e2411" : "#c77416");
  drawPoly(bodyPts, baseBodyCol, 252, "fine_liner", "#1a0802", 0.35, 0.1);

  // 3. Layered Body & Flank Feathers (back to front)
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 6; col++) {
      let fx = cx + dir * map(col, 0, 5, 36, -38) * scaleF;
      let fy = cy + map(row, 0, 4, -20, 26) * scaleF + (col % 2) * 4 * scaleF;
      let fAng = dir === 1 ? 175 + (row - 2) * 7 : 5 - (row - 2) * 7;
      let bCol, edgeCol, barbCol, shaftCol;
      if (style === "barred") {
        bCol = (row + col) % 2 === 0 ? "#1f2429" : "#d9e2ec";
        edgeCol = "#0d1014";
        barbCol = (row + col) % 2 === 0 ? "#e8f1f8" : "#222830";
        shaftCol = "#ffffff";
      } else if (style === "creole") {
        bCol = row < 2 ? "#d92b16" : (row === 2 ? "#b83c14" : "#801c0b");
        edgeCol = "#2e0802";
        barbCol = row < 2 ? "#ff9447" : "#f06824";
        shaftCol = "#ffe299";
      } else {
        bCol = (row + col) % 2 === 0 ? "#e89c1e" : "#123824";
        edgeCol = "#140902";
        barbCol = "#ffd659";
        shaftCol = "#fff2b3";
      }
      drawHyperrealFeather(fx, fy, 24 * scaleF, 13 * scaleF, fAng, bCol, edgeCol, barbCol, shaftCol);
    }
  }

  // 4. Wing Bow, Coverts & Flight Primaries
  for (let w = 0; w < 7; w++) {
    let wx = cx + dir * (16 - w * 6) * scaleF;
    let wy = cy + (-4 + w * 3.5) * scaleF;
    let wAng = dir === 1 ? 162 + w * 4 : 18 - w * 4;
    let wCol = style === "barred" ? (w % 2 === 0 ? "#181d22" : "#cfd9e2") : (w < 3 ? "#e6321f" : (w < 5 ? "#008f4c" : "#d98214"));
    let wBarb = style === "barred" ? "#ffffff" : (w < 3 ? "#ff884d" : (w < 5 ? "#66f099" : "#ffe066"));
    drawHyperrealFeather(wx, wy, 32 * scaleF, 12 * scaleF, wAng, wCol, "#140802", wBarb, "#fff3c4");
  }

  // 5.Neck Hackles (Cascade of lanceolate golden/vermilion/barred feathers)
  let neckTopX = cx + dir * 40 * scaleF, neckTopY = cy - 36 * scaleF;
  for (let n = 0; n < 14; n++) {
    let t = n / 13;
    let nx = lerp(neckTopX, cx + dir * 24 * scaleF, t) + random(-5, 5) * scaleF;
    let ny = lerp(neckTopY, cy - 2 * scaleF, t);
    let nAng = dir === 1 ? 132 + random(-14, 14) : 48 + random(-14, 14);
    let hCol = style === "barred" ? (n % 2 === 0 ? "#20262b" : "#e6eef5") : (n % 2 === 0 ? "#ffbe19" : "#e63b19");
    let hBarb = style === "barred" ? "#ffffff" : "#fff085";
    drawHyperrealFeather(nx, ny, 22 * scaleF, 8.5 * scaleF, nAng, hCol, "#290c02", hBarb, "#fff9d6");
  }
}

function drawWoodSlat(x1, y1, x2, y2, h, tone) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let nx = -dy / len, ny = dx / len;
  let ang = atan2(dy, dx);
  let hw = h * 0.5;

  let slatPts = [
    [x1 + nx * hw, y1 + ny * hw],
    [x2 + nx * hw, y2 + ny * hw],
    [x2 - nx * hw, y2 - ny * hw],
    [x1 - nx * hw, y1 - ny * hw]
  ];
  let baseCol = tone === "light" ? "#cf8e46" : (tone === "mid" ? "#b36e29" : "#784212");
  let hatchCol = tone === "light" ? "#e6ab63" : (tone === "mid" ? "#995718" : "#592d08");
  drawPoly(slatPts, baseCol, 254, "fine_liner", "#2b1203", 0.4, 0.04, hatchCol, 5, ang, 0.85);

  // Top edge sunlit bevel & bottom shadow bevel
  brush.set("cpencil", "#ffe4a8", 0.55);
  brush.line(x1 - nx * (hw - 1.5), y1 - ny * (hw - 1.5), x2 - nx * (hw - 1.5), y2 - ny * (hw - 1.5));
  brush.set("rotring", "#2b1203", 0.5);
  brush.line(x1 + nx * hw, y1 + ny * hw, x2 + nx * hw, y2 + ny * hw);

  // Hyperreal wood grain lines & cathedral arches
  for (let g = -0.75; g <= 0.78; g += 0.24) {
    let gx1 = x1 + nx * (hw * g), gy1 = y1 + ny * (hw * g);
    let gx2 = x2 + nx * (hw * g), gy2 = y2 + ny * (hw * g);
    let gmx = (gx1 + gx2) * 0.5 + nx * sin(g * 360) * 3.5;
    let gmy = (gy1 + gy2) * 0.5 + ny * sin(g * 360) * 3.5;
    brush.set("fine_liner", g < 0 ? "#5c2c09" : "#804313", 0.25);
    brush.spline([[gx1, gy1, 0.7], [gmx, gmy, 1.0], [gx2, gy2, 0.7]], 0.25);
  }

  // Wood knots
  for (let k = 0; k < 2; k++) {
    let kt = 0.25 + k * 0.48 + random(-0.08, 0.08);
    let kx = lerp(x1, x2, kt), ky = lerp(y1, y2, kt);
    let kPts = makeEllipsePts(kx, ky, 7, 3.2, ang, 12);
    drawPoly(kPts, "#4a2006", 240, "fine_liner", "#240d02", 0.25, 0.1);
  }
}

function drawNailHead(x, y) {
  let nPts = makeEllipsePts(x, y, 3.2, 3.2, 0, 10);
  drawPoly(nPts, "#33221a", 255, "fine_liner", "#120804", 0.3, 0.1);
  brush.set("fine_liner", "#d9e2ec", 0.28);
  brush.line(x - 1.2, y - 1.2, x + 0.8, y - 0.8);
}

