    drawHyperrealFeather(nx, ny, 20, 8, 38 + random(-10, 10), n % 2 === 0 ? "#1c2229" : "#e8f0f7", "#0d1014", "#ffffff", "#ffffff");
  }
  drawHenHead(706, 496, -1, 0.96);

  // 4. Magnificent Crown Hen Perched on Top of the Crate (y = 265..435)
