  for (let footX of [852, 892]) {
    // Tarsus leg
    drawPoly([[footX - 4, 395], [footX + 4, 395], [footX + 5, 428], [footX - 3, 428]], "#f2b718", 255, "fine_liner", "#4a2702", 0.32, 0.08);
    // Scutellate leg scales
    for (let sy = 398; sy <= 425; sy += 4.5) {
      brush.set("fine_liner", "#5c3104", 0.25);
      brush.line(footX - 3.5, sy, footX + 4, sy);
