      let b0 = [lerp(p1[0], p0[0], s), lerp(p1[1], p0[1], s)];
      let b1 = [lerp(p1[0], p2[0], s), lerp(p1[1], p2[1], s)];
      brush.line(b0[0], b0[1], b1[0], b1[1]);
    }
  }

  // Crisp specular ridge creases & crinkle highlights across tarp folds
  let brightRidges = [
    [tNodes.A, tNodes.G], [tNodes.B, tNodes.G], [tNodes.B, tNodes.H], [tNodes.C, tNodes.H],
    [tNodes.C, tNodes.I], [tNodes.D, tNodes.I], [tNodes.D, tNodes.J], [tNodes.F, tNodes.L],
    [tNodes.G, tNodes.L], [tNodes.H, tNodes.M], [tNodes.H, tNodes.N], [tNodes.I, tNodes.N],
    [tNodes.L, tNodes.P], [tNodes.L, tNodes.Q], [tNodes.M, tNodes.R], [tNodes.N, tNodes.R]
  ];
  for (let r of brightRidges) {
    let p0 = r[0], p1 = r[1];
    let mx = (p0[0] + p1[0]) * 0.5 + random(-6, 6);
    let my = (p0[1] + p1[1]) * 0.5 + random(-6, 6);
    brush.set("cpencil", "#99caff", 0.75);
    brush.spline([[p0[0], p0[1], 0.6], [mx, my, 1.1], [p1[0], p1[1], 0.6]], 0.2);
    brush.set("fine_liner", "#ffffff", 0.38);
    brush.spline([[p0[0], p0[1], 0.5], [mx, my, 1.0], [p1[0], p1[1], 0.5]], 0.2);
  }

  // Stitched reinforced tarp border hem & shiny brass grommets (eyelets)
  let hemPath = [tNodes.A, tNodes.F, tNodes.K, tNodes.P, tNodes.Q, tNodes.R, tNodes.S, tNodes.O, tNodes.J, tNodes.E, tNodes.D, tNodes.C, tNodes.B, tNodes.A];
  for (let i = 0; i < hemPath.length - 1; i++) {
    let p0 = hemPath[i], p1 = hemPath[i + 1];
    brush.set("rotring", "#001436", 0.55);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    // White double-stitching dashes
    for (let t = 0.08; t < 0.92; t += 0.1) {
      let sx0 = lerp(p0[0], p1[0], t), sy0 = lerp(p0[1], p1[1], t);
      let sx1 = lerp(p0[0], p1[0], t + 0.05), sy1 = lerp(p0[1], p1[1], t + 0.05);
      brush.set("fine_liner", "#fff8e0", 0.26);
      brush.line(sx0, sy0, sx1, sy1);
    }
  }

  // Brass Grommets at tarp perimeter corners
  let grommetList = [tNodes.A, tNodes.F, tNodes.K, tNodes.P, tNodes.Q, tNodes.R, tNodes.S, tNodes.O, tNodes.E, tNodes.C, tNodes.B];
  for (let g of grommetList) {
    let outerRing = makeEllipsePts(g[0], g[1], 8.5, 8.5, 0, 16);
    drawPoly(outerRing, "#ffd11a", 255, "fine_liner", "#4a2802", 0.38, 0.1);
    let innerHole = makeEllipsePts(g[0], g[1], 4.2, 4.2, 0, 12);
    drawPoly(innerHole, "#170c04", 255, "fine_liner", "#4a2802", 0.3, 0.1);
    brush.set("rotring", "#ffffff", 0.42);
    brush.arc(g[0], g[1], 6.4, 200, 320);
  }
}

// ============================================================================
// 6. STACKED HYPERREAL PLANTAINS (RIDGES, BRUISED SKINS, FIBROUS TIPS)
// ============================================================================

function drawHyperrealPlantain(p0, p1, p2, p3, maxW, ripeness) {
  let steps = 20;
  let upperPts = [];
  let lowerPts = [];
  let ridgePts = [];
  let spinePts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubic(p0, p1, p2, p3, t);
    let tan = evalCubicTangent(p0, p1, p2, p3, t);
    let nx = -tan[1], ny = tan[0];

    // Characteristic angular tapering plantain profile (narrow neck + snout tip)
    let profile = sin(pow(t, 0.85) * 180);
    if (t < 0.16) profile = map(t, 0, 0.16, 0.24, sin(pow(0.16, 0.85) * 180));
    if (t > 0.86) profile = map(t, 0.86, 1.0, sin(pow(0.86, 0.85) * 180), 0.18);

    let hw = maxW * 0.5 * profile;
    let rw = hw * 0.18 * sin(t * 180);

    upperPts.push([pt[0] + nx * hw, pt[1] + ny * hw]);
    lowerPts.push([pt[0] - nx * hw, pt[1] - ny * hw]);
    ridgePts.push([pt[0] + nx * rw, pt[1] + ny * rw]);
    spinePts.push({ pt, nx, ny, hw, t });
  }

  let pal;
  if (ripeness === "green") {
    pal = { top: "#28b852", bot: "#066e2c", ridge: "#a8f056", neck: "#008f4c", hatchTop: "#62db44", hatchBot: "#034a1c" };
  } else if (ripeness === "turning") {
    pal = { top: "#ffd617", bot: "#189642", ridge: "#fff480", neck: "#109946", hatchTop: "#aae024", hatchBot: "#0a6328" };
  } else if (ripeness === "yellow") {
    pal = { top: "#ffdb1f", bot: "#d98c00", ridge: "#fff8a6", neck: "#38b043", hatchTop: "#ffbe00", hatchBot: "#a85d00" };
  } else {
    pal = { top: "#ffae19", bot: "#b84d09", ridge: "#ffe875", neck: "#859e21", hatchTop: "#e67300", hatchBot: "#782803" };
  }

  let chordAng = atan2(p3[1] - p0[1], p3[0] - p0[0]);

  // Facet 1 (Upper/Sunlit longitudinal plane)
  let facet1 = upperPts.concat(ridgePts.slice().reverse());
  drawPoly(facet1, pal.top, 254, "fine_liner", "#291404", 0.3, 0.06, pal.hatchTop, 4, chordAng, 0.75);

  // Facet 2 (Lower/Shadowed longitudinal plane)
  let facet2 = ridgePts.concat(lowerPts.slice().reverse());
  drawPoly(facet2, pal.bot, 254, "fine_liner", "#241002", 0.32, 0.06, pal.hatchBot, 4, chordAng, 0.75);

  // Greenish pedicel neck wash near stem end (t = 0..0.22)
  let neckPoly = upperPts.slice(0, 5).concat(lowerPts.slice(0, 5).reverse());
  drawPoly(neckPoly, pal.neck, 215, "fine_liner", "#1a3308", 0.25, 0.08);

  // Hyperreal Bruised Plantain Skin Patches, Scrapes & Freckles
  let numBruises = ripeness === "green" ? 3 : (ripeness === "ripe" ? 8 : 5);
  for (let b = 0; b < numBruises; b++) {
    let bt = random(0.18, 0.84);
    let idx = constrain(floor(bt * steps), 2, steps - 2);
    let sp = spinePts[idx];
    let bOff = random(-0.65, 0.65) * sp.hw;
    let bx = sp.pt[0] + sp.nx * bOff;
    let by = sp.pt[1] + sp.ny * bOff;
    let bRx = random(6, 15), bRy = random(2.8, 5.8);
    let bPts = makeEllipsePts(bx, by, bRx, bRy, chordAng + random(-18, 18), 12);
    let bCol = b % 2 === 0 ? "#2b120d" : "#4f1e11";
    drawPoly(bPts, bCol, 225, "fine_liner", "#170804", 0.22, 0.15);

    // Darker necrotic center of bruise
    if (bRx > 9) {
      let cPts = makeEllipsePts(bx, by, bRx * 0.5, bRy * 0.5, chordAng, 8);
      drawPoly(cPts, "#140705", 240, null, null, 0, 0.15);
    }
  }

  // Sugar freckles & longitudinal vascular striations
  brush.set("fine_liner", "#361808", 0.24);
  for (let s = 0; s < 26; s++) {
    let idx = floor(random(2, steps - 1));
    let sp = spinePts[idx];
    let off = random(-0.82, 0.82) * sp.hw;
    let fx = sp.pt[0] + sp.nx * off;
    let fy = sp.pt[1] + sp.ny * off;
    brush.line(fx - 0.7, fy - 0.4, fx + 0.7, fy + 0.4);
  }

  // Sharp angular dorsal ridge highlight & dark vascular seam
  let ridgeSpline = ridgePts.map(p => [p[0], p[1], 0.9]);
  brush.set("cpencil", pal.ridge, 0.65);
  brush.spline(ridgeSpline, 0.25);
  brush.set("fine_liner", "#3b2007", 0.26);
  brush.spline(ridgeSpline, 0.25);

  // Outer contour definition
  let topSpline = upperPts.map(p => [p[0], p[1], 0.85]);
  let botSpline = lowerPts.map(p => [p[0], p[1], 0.85]);
  brush.set("fine_liner", "#241002", 0.35);
  brush.spline(topSpline, 0.25);
  brush.spline(botSpline, 0.25);

  // Crusty black-brown distal floral scar at tip (p3)
  let tipPts = makeEllipsePts(p3[0], p3[1], maxW * 0.18, maxW * 0.14, chordAng, 10);
  drawPoly(tipPts, "#1c0e07", 255, "rotring", "#0d0603", 0.38, 0.1);
  brush.set("fine_liner", "#7a583b", 0.25);
  brush.line(p3[0] - 2, p3[1] - 1, p3[0] + 2, p3[1] + 1);
}

function drawPlantainHand(crownX, crownY, baseAng, count, spreadLen, maxW, ripenessList) {
  for (let i = 0; i < count; i++) {
    let u = (i / max(1, count - 1)) - 0.5;
    let ang = baseAng + u * 52;
    let len = spreadLen * (1 - abs(u) * 0.14);
    let sx = crownX + u * 22 * sin(baseAng);
    let sy = crownY - u * 22 * cos(baseAng);

    let p0 = [sx, sy];
    let p1 = [sx + cos(ang + 18) * (len * 0.35), sy + sin(ang + 18) * (len * 0.35)];
    let p2 = [sx + cos(ang - 12) * (len * 0.72), sy + sin(ang - 12) * (len * 0.72)];
    let p3 = [sx + cos(ang - 34) * len, sy + sin(ang - 34) * len];

    let ripe = ripenessList[i % ripenessList.length];
    drawHyperrealPlantain(p0, p1, p2, p3, maxW, ripe);
  }

  // Fibrous woody crown cushion where the plantain hand was chopped from the stalk
  let crownPts = makeEllipsePts(crownX, crownY, 24, 15, baseAng + 75, 16);
  drawPoly(crownPts, "#4a2910", 255, "rotring", "#1c0c02", 0.45, 0.12);
  let cutPts = makeEllipsePts(crownX - cos(baseAng) * 4, crownY - sin(baseAng) * 4, 16, 9, baseAng + 75, 12);
  drawPoly(cutPts, "#c99b5b", 250, "fine_liner", "#331905", 0.3, 0.1);
  brush.set("fine_liner", "#241002", 0.25);
  for (let k = 0; k < 8; k++) {
    brush.line(crownX + random(-10, 10), crownY + random(-6, 6), crownX + random(-10, 10), crownY + random(-6, 6));
  }
}

