// ============================================================================
// 7. HYPERREAL SISAL ROPES & STRAY FIBRES LASHING THE CARGO
// ============================================================================

function drawHyperrealRope(pts, diam) {
  if (!pts || pts.length < 2) return;

  // Resample polyline into uniform steps
  let samples = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let segLen = dist(p0[0], p0[1], p1[0], p1[1]);
    let steps = max(2, floor(segLen / (diam * 0.48)));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = lerp(p0[0], p1[0], t);
      let y = lerp(p0[1], p1[1], t);
      let ang = atan2(p1[1] - p0[1], p1[0] - p0[0]);
      samples.push({ x, y, ang });
    }
  }
  let last = pts[pts.length - 1];
  let prev = pts[pts.length - 2];
  samples.push({ x: last[0], y: last[1], ang: atan2(last[1] - prev[1], last[0] - prev[0]) });

  // Draw individual 3-strand helical twist lobes along the rope
  for (let i = 0; i < samples.length; i++) {
    let sm = samples[i];
    let lobePts = makeEllipsePts(sm.x, sm.y, diam * 0.56, diam * 0.42, sm.ang + 34, 12);
    let shade = i % 2 === 0 ? "#d99841" : "#c47d26";
    drawPoly(lobePts, shade, 255, "fine_liner", "#331503", 0.32, 0.12);

    // Individual yarn ply lines inside each strand lobe
    let ca = cos(sm.ang + 34), sa = sin(sm.ang + 34);
    let nx = -sa, ny = ca;
    for (let p = -0.5; p <= 0.55; p += 0.34) {
      let px0 = sm.x - ca * (diam * 0.38) + nx * (diam * 0.28 * p);
      let py0 = sm.y - sa * (diam * 0.38) + ny * (diam * 0.28 * p);
      let px1 = sm.x + ca * (diam * 0.38) + nx * (diam * 0.28 * p);
      let py1 = sm.y + sa * (diam * 0.38) + ny * (diam * 0.28 * p);
      brush.set("fine_liner", p < 0 ? "#fff2c2" : "#5e2a07", 0.22);
      brush.line(px0, py0, px1, py1);
    }

    // Stray fuzzy golden sisal fibres sprouting off the rope edges
    if (i % 2 === 0) {
      for (let f = 0; f < 3; f++) {
        let side = random() < 0.5 ? -1 : 1;
        let fx = sm.x + cos(sm.ang + 90 * side) * (diam * 0.42);
        let fy = sm.y + sin(sm.ang + 90 * side) * (diam * 0.42);
        let fAng = sm.ang + side * random(28, 78);
        let fLen = random(5, 12);
        brush.set("fibre_hair", f % 2 === 0 ? "#ffe89e" : "#8c4a12", 0.2);
        brush.line(fx, fy, fx + cos(fAng) * fLen, fy + sin(fAng) * fLen);
      }
    }
  }
}

