// ============================================================================
// 8. ORNATE PAINTED HAITIAN TAP-TAP BUS PANEL (HAND-LETTERED BORDERS, NO WORDS)
// ============================================================================

function drawCalligraphicScroll(x1, y1, cx1, cy1, cx2, cy2, x2, y2, mainCol, shadowCol, highlightCol, weight) {
  let steps = 18;
  let ptsMain = [];
  let ptsShad = [];
  let ptsHigh = [];
  let p0 = [x1, y1], p1 = [cx1, cy1], p2 = [cx2, cy2], p3 = [x2, y2];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubic(p0, p1, p2, p3, t);
    let pr = 0.35 + sin(t * 180) * 0.95;
    ptsMain.push([pt[0], pt[1], pr]);
    ptsShad.push([pt[0] + 2.5, pt[1] + 2.5, pr]);
    ptsHigh.push([pt[0] - 1.0, pt[1] - 1.0, pr * 0.65]);
  }
  brush.set("rotring", shadowCol, weight * 1.15);
  brush.spline(ptsShad, 0.25);
  brush.set("cpencil", mainCol, weight);
  brush.spline(ptsMain, 0.25);
  brush.set("fine_liner", highlightCol, weight * 0.45);
  brush.spline(ptsHigh, 0.25);

  // Terminal pearl teardrops at scroll ends
  for (let ep of [p0, p3]) {
    let dPts = makeEllipsePts(ep[0], ep[1], 3.8, 3.8, 0, 10);
    drawPoly(dPts, mainCol, 255, "fine_liner", shadowCol, 0.3, 0.1);
  }
}

function drawFolkFlower(cx, cy, r, petalCol, centerCol, ringCol) {
  for (let i = 0; i < 8; i++) {
    let a = i * 45;
    let px = cx + cos(a) * (r * 0.58);
    let py = cy + sin(a) * (r * 0.58);
    let pPts = makeEllipsePts(px, py, r * 0.44, r * 0.26, a, 12);
    drawPoly(pPts, i % 2 === 0 ? petalCol : ringCol, 255, "fine_liner", "#140802", 0.3, 0.12);
    brush.set("fine_liner", "#fff8d6", 0.24);
    brush.line(cx + cos(a) * (r * 0.2), cy + sin(a) * (r * 0.2), cx + cos(a) * (r * 0.78), cy + sin(a) * (r * 0.78));
  }
  let cPts = makeEllipsePts(cx, cy, r * 0.32, r * 0.32, 0, 14);
  drawPoly(cPts, centerCol, 255, "rotring", "#140802", 0.35, 0.1);
  let iPts = makeEllipsePts(cx, cy, r * 0.14, r * 0.14, 0, 10);
  drawPoly(iPts, "#ffffff", 255, "fine_liner", "#140802", 0.25, 0.1);
}

function drawOrnateCornerFan(cx, cy, r, startAng, endAng) {
  let cols = ["#ffd11a", "#e62b17", "#008f4c", "#0047ab"];
  let rings = 4;
  for (let k = rings; k >= 1; k--) {
    let rad = (k / rings) * r;
    let pts = [[cx, cy]];
    for (let a = startAng; a <= endAng; a += 6) {
      pts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
    }
    drawPoly(pts, cols[k % cols.length], 255, "fine_liner", "#140802", 0.3, 0.05);
  }
}

