// ============================================================================
// 3D CARD SURFACE GEOMETRY, BEND DEFORMATION & SURFACE NORMAL LIGHTING
// ============================================================================

function getCardElevation(card, u, v) {
  let z = 0;
  if (card.bent) {
    // Diagonal crimp / bridge bend across the Queen of Hearts
    let vCrease = -0.11 + 0.23 * u;
    let d = v - vCrease;
    // Arching bridge + sharp mechanical paper fold ridge at d = 0
    let arch = Math.exp(-(d * d) / 0.28);
    let ridge = Math.exp(-Math.abs(d) / 0.14);
    z = card.camber * (0.68 * arch + 0.32 * ridge);
    // Slight inward flare at the edges of the bend
    z *= 1.0 + 0.14 * (u * u);
    // Subtle corner lift at top-left dog-ear
    let dTL = Math.hypot(u + 1, v + 1);
    if (dTL < 0.35) z += 14 * Math.pow(1 - dTL / 0.35, 1.6);
    let dBR = Math.hypot(u - 1, v - 1);
    if (dBR < 0.3) z += 10 * Math.pow(1 - dBR / 0.3, 1.6);
  } else {
    // Natural used-card camber + worn corner curl
    z = card.camber * (1 - 0.45 * (u * u + v * v));
    let corners = [
      [-1, -1, card.cornerWear[0]],
      [1, -1, card.cornerWear[1]],
      [1, 1, card.cornerWear[2]],
      [-1, 1, card.cornerWear[3]]
    ];
    for (let c of corners) {
      let dc = Math.hypot(u - c[0], v - c[1]);
      if (dc < 0.28 && c[2] > 0.6) {
        z += 12 * c[2] * Math.pow(1 - dc / 0.28, 1.5);
      }
    }
  }
  return Math.max(0, z);
}

function cardToWorld(card, u, v, plateShift) {
  let su = u;
  let sv = v;

  // Foreshortening along the bent Queen's arch so paper length is conserved
  if (card.bent) {
    let vCrease = -0.11 + 0.23 * u;
    let d = v - vCrease;
    sv -= 0.042 * Math.tanh(d * 3.2);
    // Slight perspective waist pinch at the lifted bridge
    let arch = Math.exp(-(d * d) / 0.28);
    su *= 1.0 - 0.026 * arch * (1 - 0.3 * u);
  }

  let lx = su * card.hw;
  let ly = sv * card.hh;

  let rad = (card.angle * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);

  let wx = card.cx + lx * ca - ly * sa;
  let wy = card.cy + lx * sa + ly * ca;

  // 3D elevation displacement toward upper-left camera viewpoint
  let z = getCardElevation(card, u, v);
  wx += z * 0.22;
  wy -= z * 0.64;

  if (plateShift) {
    wx += plateShift.dx;
    wy += plateShift.dy;
  }

  return [wx, wy];
}

// Compute local shading (0 = pure highlight, 1 = deep shadow) and crease ridge
function getCardShading(card, u, v) {
  let shade = 0.04;
  let ridgeHighlight = 0;

  if (card.bent) {
    let vCrease = -0.11 + 0.23 * u;
    let d = v - vCrease;

    // Slope across crease: d < 0 faces upper-left light, d > 0 tilts away into shadow
    if (d > -0.015 && d < 0.42) {
      let t = (d + 0.015) / 0.435;
      shade += 0.56 * Math.sin(t * Math.PI) * Math.exp(-t * 1.1);
    } else if (d <= -0.015 && d > -0.25) {
      // Lit upper slope
      shade -= 0.03;
    }

    // Sharp paper crease ridge highlight right at d ≈ -0.015
    let distRidge = Math.abs(d + 0.012);
    if (distRidge < 0.022) {
      ridgeHighlight = 1.0 - distRidge / 0.022;
      shade *= 0.15;
    }

    // Secondary subtle counter-bend shadow near bottom
    if (v > 0.45) {
      shade += 0.18 * ((v - 0.45) / 0.55);
    }
  } else {
    // Gentle directional gradient across flat cards + overlap shadows from upper cards
    shade += 0.06 * (0.5 * u + 0.5 * v + 0.5);
  }

  // Cast shadow on underlying cards from the Bent Queen (QH) or adjacent cards
  if (card.id === "AS") {
    // Right side of Ace of Spades sits directly under the lifted left edge of QH
    if (u > 0.15) {
      let s = Math.min(1, (u - 0.15) / 0.65);
      shade += 0.52 * Math.pow(s, 1.2);
    }
  } else if (card.id === "7C") {
    // Left side of 7 of Clubs sits under the lifted right edge of QH
    if (u < -0.1) {
      let s = Math.min(1, (-0.1 - u) / 0.65);
      shade += 0.48 * Math.pow(s, 1.2);
    }
  } else if (card.id === "10D") {
    if (u > 0.05) {
      shade += 0.45 * Math.min(1, (u - 0.05) / 0.6);
    }
  } else if (card.id === "JD") {
    if (u < -0.05) {
      shade += 0.42 * Math.min(1, (-0.05 - u) / 0.6);
    }
  } else if (card.id === "KS") {
    if (v < 0.2) {
      shade += 0.55 * Math.min(1, (0.2 - v) / 0.7);
    }
  }

  // Worn corner patina / finger-oil toning near card edges and dog-ears
  let edgeDist = Math.min(1 - Math.abs(u), 1 - Math.abs(v));
  if (edgeDist < 0.08) {
    shade += 0.14 * (1 - edgeDist / 0.08);
  }

  let corners = [
    [-1, -1, card.cornerWear[0]],
    [1, -1, card.cornerWear[1]],
    [1, 1, card.cornerWear[2]],
    [-1, 1, card.cornerWear[3]]
  ];
  for (let c of corners) {
    let dc = Math.hypot(u - c[0], v - c[1]);
    if (dc < 0.26) {
      let w = c[2] * (1 - dc / 0.26);
      shade += 0.34 * w;
    }
  }

  return {
    shade: constrain(shade, 0, 0.95),
    ridge: ridgeHighlight
  };
}

// Generate card perimeter polygon in (u, v) with authentic worn, frayed corners
function getCardUVOutline(card, stepsPerSide = 22) {
  let pts = [];
  let rx = 0.105;
  let ry = 0.075;

  // 4 corners in clockwise order: TL, TR, BR, BL
  let cornerDefs = [
    { cx: -1 + rx, cy: -1 + ry, startA: 180, endA: 270, wear: card.cornerWear[0], idx: 0 },
    { cx: 1 - rx, cy: -1 + ry, startA: 270, endA: 360, wear: card.cornerWear[1], idx: 1 },
    { cx: 1 - rx, cy: 1 - ry, startA: 0, endA: 90, wear: card.cornerWear[2], idx: 2 },
    { cx: -1 + rx, cy: 1 - ry, startA: 90, endA: 180, wear: card.cornerWear[3], idx: 3 }
  ];

  for (let c = 0; c < 4; c++) {
    let cd = cornerDefs[c];
    let cSteps = 10;
    for (let i = 0; i <= cSteps; i++) {
      let t = i / cSteps;
      let ang = ((cd.startA + t * (cd.endA - cd.startA)) * Math.PI) / 180;
      // Worn corners flatten slightly and have micro-fray irregularity
      let flatten = 1.0 - 0.24 * cd.wear * Math.sin(t * Math.PI);
      let fray =
        cd.wear *
        0.012 *
        (noise(card.seed + c * 31 + i * 0.7) - 0.55);
      let u = cd.cx + (rx * flatten + fray) * Math.cos(ang);
      let v = cd.cy + (ry * flatten + fray) * Math.sin(ang);
      pts.push([u, v]);
    }

    // Straight/bent edge between this corner and the next
    let nextC = cornerDefs[(c + 1) % 4];
    let u0 = pts[pts.length - 1][0];
    let v0 = pts[pts.length - 1][1];
    let angNext = (nextC.startA * Math.PI) / 180;
    let u1 = nextC.cx + rx * Math.cos(angNext);
    let v1 = nextC.cy + ry * Math.sin(angNext);

    for (let s = 1; s < stepsPerSide; s++) {
      let st = s / stepsPerSide;
      let u = lerp(u0, u1, st);
      let v = lerp(v0, v1, st);
      // Tiny paper edge nicks
      let nick = 0.0025 * (noise(card.seed + c * 97 + s * 0.4) - 0.5);
      pts.push([u + nick, v + nick]);
    }
  }
  return pts;
}

function getCardWorldPolygon(card, plateShift, expandUV = 0) {
  let uvPts = getCardUVOutline(card, 18);
  return uvPts.map(([u, v]) =>
    cardToWorld(card, u * (1 + expandUV), v * (1 + expandUV), plateShift)
  );
}

// ============================================================================
// GEOMETRIC CLIPPING & MODULATED CMYK HATCHING ENGINE
// ============================================================================

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0],
      yi = poly[i][1];
    let xj = poly[j][0],
      yj = poly[j][1];
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

// Intersect a scanline (origin ox, oy, unit direction dx, dy) with a polygon
function clipLineToPolygon(ox, oy, dx, dy, poly) {
  let tValues = [];
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % n];
    let ex = p2[0] - p1[0];
    let ey = p2[1] - p1[1];
    let denom = dx * ey - dy * ex;
    if (Math.abs(denom) < 1e-7) continue;
    let rx = p1[0] - ox;
    let ry = p1[1] - oy;
    let t = (rx * ey - ry * ex) / denom;
    let u = (rx * dy - ry * dx) / denom;
    if (u >= 0 && u <= 1) {
      tValues.push(t);
    }
  }
  if (tValues.length < 2) return [];
  tValues.sort((a, b) => a - b);
  let segments = [];
  for (let i = 0; i + 1 < tValues.length; i += 2) {
    let t0 = tValues[i];
    let t1 = tValues[i + 1];
    if (t1 - t0 > 1.5) {
      segments.push([
        ox + t0 * dx,
        oy + t0 * dy,
        ox + t1 * dx,
        oy + t1 * dy
      ]);
    }
  }
  return segments;
}

// Hatch a 2D polygon in world space at a given CMYK screen angle
function hatchWorldPolygon(poly, spacing, angleDeg, brushName, colorHex, weight, jitter = 0.6) {
  if (!poly || poly.length < 3) return;
  let minX = Infinity,
    minY = Infinity,
    maxX = -Infinity,
    maxY = -Infinity;
  for (let p of poly) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  let cx = 0.5 * (minX + maxX);
  let cy = 0.5 * (minY + maxY);
  let radius = 0.5 * Math.hypot(maxX - minX, maxY - minY) + 4;

  let rad = (angleDeg * Math.PI) / 180;
  let dx = Math.cos(rad);
  let dy = Math.sin(rad);
  let nx = -dy;
  let ny = dx;

  brush.set(brushName, colorHex, weight);
  let steps = Math.ceil((2 * radius) / spacing);
  for (let i = -steps; i <= steps; i++) {
    let d = i * spacing + (random() - 0.5) * jitter;
    let ox = cx + d * nx;
    let oy = cy + d * ny;
    let segs = clipLineToPolygon(ox, oy, dx, dy, poly);
    for (let s of segs) {
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }
}

// Hatch a polygon defined in card (u, v) space so lines warp in 3D across the Bent Queen!
function hatchCardUVPolygon(
  card,
  uvPoly,
  spacingUV,
  angleDeg,
  plate,
  weight,
  brushName = "engraver",
  subSteps = 5
) {
  if (!uvPoly || uvPoly.length < 3) return;
  let minU = Infinity,
    minV = Infinity,
    maxU = -Infinity,
    maxV = -Infinity;
  for (let p of uvPoly) {
    if (p[0] < minU) minU = p[0];
    if (p[1] < minV) minV = p[1];
    if (p[0] > maxU) maxU = p[0];
    if (p[1] > maxV) maxV = p[1];
  }
  let cu = 0.5 * (minU + maxU);
  let cv = 0.5 * (minV + maxV);
  let radUV = 0.5 * Math.hypot(maxU - minU, maxV - minV) + 0.02;

  // Screen angle relative to canvas converted to card UV angle
  let relAngle = ((angleDeg - card.angle) * Math.PI) / 180;
  let du = Math.cos(relAngle);
  // Adjust for aspect ratio (hh / hw ≈ 1.4)
  let dv = Math.sin(relAngle) * (card.hw / card.hh);
  let len = Math.hypot(du, dv);
  du /= len;
  dv /= len;
  let nu = -dv;
  let nv = du;

  brush.set(brushName, plate.hex, weight);
  let steps = Math.ceil((2 * radUV) / spacingUV);

  for (let i = -steps; i <= steps; i++) {
    let d = i * spacingUV;
    let ou = cu + d * nu;
    let ov = cv + d * nv;
    let segs = clipLineToPolygon(ou, ov, du, dv, uvPoly);
    for (let s of segs) {
      let u0 = s[0],
        v0 = s[1],
        u1 = s[2],
        v1 = s[3];
      let segLen = Math.hypot(u1 - u0, v1 - v0);
      if (card.bent && segLen > 0.09) {
        let pts = [];
        let kSteps = Math.max(3, Math.ceil(segLen / 0.07));
        for (let k = 0; k <= kSteps; k++) {
          let kt = k / kSteps;
          let uu = lerp(u0, u1, kt);
          let vv = lerp(v0, v1, kt);
          let wp = cardToWorld(card, uu, vv, plate);
          let sh = getCardShading(card, uu, vv);
          let pMult = 0.85 + 0.55 * sh.shade - 0.45 * sh.ridge;
          pts.push([wp[0], wp[1], constrain(pMult, 0.35, 1.45)]);
        }
        brush.spline(pts, 0.15);
      } else {
        let p0 = cardToWorld(card, u0, v0, plate);
        let p1 = cardToWorld(card, u1, v1, plate);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }
}

// Stroke a closed or open path in card (u, v) space warped through 3D and plate shift
function strokeCardUVPath(card, uvPts, plate, weight, closed = true, brushName = "rotring") {
  if (!uvPts || uvPts.length < 2) return;
  brush.set(brushName, plate.hex, weight);
  let n = uvPts.length;
  let limit = closed ? n : n - 1;
  for (let i = 0; i < limit; i++) {
    let a = uvPts[i];
    let b = uvPts[(i + 1) % n];
    let wa = cardToWorld(card, a[0], a[1], plate);
    let wb = cardToWorld(card, b[0], b[1], plate);
    brush.line(wa[0], wa[1], wb[0], wb[1]);
  }
}

// Wash a polygon in card (u, v) space using p5.brush Polygon
function washCardUVPolygon(card, uvPts, colorHex, opacity, plateShift) {
  if (!uvPts || uvPts.length < 3) return;
  let worldPts = uvPts.map(([u, v]) => cardToWorld(card, u, v, plateShift));
  let poly = new brush.Polygon(worldPts);
  poly.wash(colorHex, opacity);
}

// ============================================================================
// STAGE 1: GREEN BAIZE TABLE, CMYK HALFTONE SCREENS & WOOLLEN BAIZE NAP
// ============================================================================

function drawGreenBaize() {
  // Base warm archival print stock wash
  let fullCanvas = new brush.Polygon([
    [-20, -20],
    [1220, -20],
    [1220, 1220],
    [-20, 1220]
  ]);
  fullCanvas.wash("#F5F0E2", 255);

  // Shifted CMYK plate washes to build deep casino emerald green (Cyan + Yellow + shadow M/K)
  let yPoly = new brush.Polygon([
    [10 + PLATES.Y.dx, 10 + PLATES.Y.dy],
    [1190 + PLATES.Y.dx, 10 + PLATES.Y.dy],
    [1190 + PLATES.Y.dx, 1190 + PLATES.Y.dy],
    [10 + PLATES.Y.dx, 1190 + PLATES.Y.dy]
  ]);
  yPoly.wash(PLATES.Y.washHex, 155);

  let cPoly = new brush.Polygon([
    [10 + PLATES.C.dx, 10 + PLATES.C.dy],
    [1190 + PLATES.C.dx, 10 + PLATES.C.dy],
    [1190 + PLATES.C.dx, 1190 + PLATES.C.dy],
    [10 + PLATES.C.dx, 1190 + PLATES.C.dy]
  ]);
  cPoly.wash(PLATES.C.washHex, 168);

  // Raking light falloff washes in Magenta and Black around upper/outer baize
  brush.noStroke();
  brush.fill(PLATES.C.washHex, 65);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.25);
  brush.rect(0, 0, 1200, 1200);

  brush.fill(PLATES.M.washHex, 32);
  brush.fillBleed(0.3, "in");
  brush.rect(0, 0, 1200, 1200);
  brush.noFill();

  // Check if a point is deep inside the opaque card fan interior (to optimize baize strokes)
  function isDeepUnderCards(x, y) {
    // Keep a generous 28px margin around card edges so all CMYK fringes are crisp
    for (let i = CARDS.length - 1; i >= 0; i--) {
      let c = CARDS[i];
      let dx = x - c.cx;
      let dy = y - c.cy;
      let rad = (-c.angle * Math.PI) / 180;
      let lx = dx * Math.cos(rad) - dy * Math.sin(rad);
      let ly = dx * Math.sin(rad) + dy * Math.cos(rad);
      if (Math.abs(lx) < c.hw - 36 && Math.abs(ly) < c.hh - 36) {
        return true;
      }
    }
    return false;
  }

  // Baize lighting density function (0 = bright raking center, 1 = deep corner vignette)
  function baizeShadow(x, y) {
    let d = Math.hypot((x - 540) / 720, (y - 380) / 680);
    let n = noise(x * 0.0035, y * 0.0035);
    return constrain(0.18 + 0.58 * d * d + 0.22 * n, 0.1, 0.98);
  }

  // Draw the 4 overlapping CMYK cross-hatch screens across the green baize
  function drawBaizeScreenPass(plate, angleDeg, spacing, minShadow, weightBase) {
    let rad = (angleDeg * Math.PI) / 180;
    let dx = Math.cos(rad);
    let dy = Math.sin(rad);
    let nx = -dy;
    let ny = dx;

    let cx = 600 + plate.dx;
    let cy = 600 + plate.dy;
    let maxR = 880;
    let steps = Math.ceil((2 * maxR) / spacing);

    brush.set("engraver", plate.hex, weightBase);

    for (let i = -steps; i <= steps; i++) {
      let offset = i * spacing;
      let ox = cx + offset * nx;
      let oy = cy + offset * ny;

      // Clip scanline to [0, 1200] x [0, 1200]
      let tMin = -maxR,
        tMax = maxR;
      let segStart = null;

      let stepLen = 34;
      for (let t = tMin; t <= tMax; t += stepLen) {
        let px = ox + t * dx;
        let py = oy + t * dy;
        let inBounds = px >= -5 && px <= 1205 && py >= -5 && py <= 1205;
        let visible = inBounds && !isDeepUnderCards(px, py);
        let sh = visible ? baizeShadow(px, py) : 0;

        if (visible && sh >= minShadow) {
          if (segStart === null) segStart = [px, py];
        } else {
          if (segStart !== null) {
            let prevX = ox + (t - stepLen) * dx;
            let prevY = oy + (t - stepLen) * dy;
            if (Math.hypot(prevX - segStart[0], prevY - segStart[1]) > 4) {
              brush.line(segStart[0], segStart[1], prevX, prevY);
            }
            segStart = null;
          }
        }
      }
      if (segStart !== null) {
        let endX = ox + tMax * dx;
        let endY = oy + tMax * dy;
        brush.line(segStart[0], segStart[1], endX, endY);
      }
    }
  }

  // 1. YELLOW BAIZE SCREEN (0° and 90°)
  drawBaizeScreenPass(PLATES.Y, PLATES.Y.angle1, 8.5, 0.05, 0.72);
  drawBaizeScreenPass(PLATES.Y, PLATES.Y.angle2, 11.5, 0.22, 0.62);

  // 2. CYAN BAIZE SCREEN (15° and 105°)
  drawBaizeScreenPass(PLATES.C, PLATES.C.angle1, 8.0, 0.05, 0.72);
  drawBaizeScreenPass(PLATES.C, PLATES.C.angle2, 10.5, 0.18, 0.65);

  // 3. MAGENTA BAIZE SHADOW SCREEN (75° and 165° in mid-to-deep tones)
  drawBaizeScreenPass(PLATES.M, PLATES.M.angle1, 11.5, 0.32, 0.55);
  drawBaizeScreenPass(PLATES.M, PLATES.M.angle2, 16.0, 0.56, 0.50);

  // 4. BLACK BAIZE KEY SCREEN (45° and 135° in shadow/raking zones)
  drawBaizeScreenPass(PLATES.K, PLATES.K.angle1, 10.5, 0.26, 0.58);
  drawBaizeScreenPass(PLATES.K, PLATES.K.angle2, 14.5, 0.48, 0.54);

  // 5. HYPERREAL DIRECTIONAL BAIZE NAP (short curled wool fibers catching raking light)
  brush.field("waves");
  brush.wiggle(2.2);

  let napPlates = [
    { plate: PLATES.C, count: 650, weight: 0.48, len: [10, 24] },
    { plate: PLATES.Y, count: 600, weight: 0.55, len: [10, 22] },
    { plate: PLATES.K, count: 520, weight: 0.42, len: [8, 18] },
    { plate: PLATES.M, count: 320, weight: 0.38, len: [8, 16] }
  ];

  for (let np of napPlates) {
    brush.set("2B", np.plate.hex, np.weight);
    for (let i = 0; i < np.count; i++) {
      let rx = random(0, 1200);
      let ry = random(0, 1200);
      if (isDeepUnderCards(rx, ry)) continue;
      // Directional brush nap across the card table
      let napAngle =
        -18 +
        38 * noise(rx * 0.004, ry * 0.004) +
        (random() - 0.5) * 28;
      let l = random(np.len[0], np.len[1]);
      brush.flowLine(rx + np.plate.dx, ry + np.plate.dy, l, napAngle);
    }
  }

  // Fine bright yellow & cyan wool highlights where raking light grazes the baize nap
  brush.noField();
  brush.set("rotring", PLATES.Y.hex, 0.42);
  for (let i = 0; i < 360; i++) {
    let rx = random(40, 1160);
    let ry = random(40, 900);
    if (isDeepUnderCards(rx, ry)) continue;
    let a0 = random(0, 360);
    brush.arc(rx, ry, random(3, 7), a0, a0 + random(75, 160));
  }
  brush.set("rotring", PLATES.C.hex, 0.38);
  for (let i = 0; i < 320; i++) {
    let rx = random(40, 1160);
    let ry = random(40, 900);
    if (isDeepUnderCards(rx, ry)) continue;
    let a0 = random(0, 360);
    brush.arc(rx, ry, random(3, 7), a0, a0 + random(75, 160));
  }
}

// ============================================================================
// STAGE 2: CAST SHADOWS, CMYK KNOCKOUT FRINGES & CARD PAPER SHADING
// ============================================================================

function drawCardCastShadow(card) {
  let uvPts = getCardUVOutline(card, 14);

  // Project card perimeter onto the table plane along the upper-left key light vector
  let shadowWorldPts = uvPts.map(([u, v]) => {
    let z = getCardElevation(card, u, v);
    let base = cardToWorld(card, u, v, null);
    // Displace shadow down-right proportional to elevation z
    let sx = base[0] - z * 0.22 + (14 + z * 0.85);
    let sy = base[1] + z * 0.64 + (18 + z * 1.05);
    return [sx, sy];
  });

  // Translucent CMYK shadow washes
  let shPolyC = new brush.Polygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.C.dx, p[1] + PLATES.C.dy])
  );
  shPolyC.wash(PLATES.C.washHex, 55);

  let shPolyM = new brush.Polygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.M.dx, p[1] + PLATES.M.dy])
  );
  shPolyM.wash(PLATES.M.washHex, 48);

  let shPolyK = new brush.Polygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.K.dx, p[1] + PLATES.K.dy])
  );
  shPolyK.wash(PLATES.K.washHex, 78);

  // Dense CMYK cross-hatching inside the cast shadow
  hatchWorldPolygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.C.dx, p[1] + PLATES.C.dy]),
    6.5,
    PLATES.C.angle1,
    "engraver",
    PLATES.C.hex,
    0.58
  );
  hatchWorldPolygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.M.dx, p[1] + PLATES.M.dy]),
    7.0,
    PLATES.M.angle1,
    "engraver",
    PLATES.M.hex,
    0.54
  );
  hatchWorldPolygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.K.dx, p[1] + PLATES.K.dy]),
    5.5,
    PLATES.K.angle1,
    "engraver",
    PLATES.K.hex,
    0.66
  );
  hatchWorldPolygon(
    shadowWorldPts.map((p) => [p[0] + PLATES.K.dx, p[1] + PLATES.K.dy]),
    7.5,
    PLATES.K.angle2,
    "engraver",
    PLATES.K.hex,
    0.52
  );
}

function drawCardBodyAndFringes(card) {
  let uvOutline = getCardUVOutline(card, 18);

  // 1. Misregistered CMYK knockout ghost fringes around the card perimeter
  let polyY = new brush.Polygon(getCardWorldPolygon(card, PLATES.Y, 0.005));
  polyY.wash(PLATES.Y.hex, 175);
  strokeCardUVPath(card, uvOutline, PLATES.Y, 0.72, true, "rotring");

  let polyC = new brush.Polygon(getCardWorldPolygon(card, PLATES.C, 0.005));
  polyC.wash(PLATES.C.hex, 165);
  strokeCardUVPath(card, uvOutline, PLATES.C, 0.68, true, "rotring");

  let polyM = new brush.Polygon(getCardWorldPolygon(card, PLATES.M, 0.005));
  polyM.wash(PLATES.M.hex, 155);
  strokeCardUVPath(card, uvOutline, PLATES.M, 0.65, true, "rotring");

  // 2. Opaque warm ivory card stock knockout
  let corePoly = new brush.Polygon(getCardWorldPolygon(card, { dx: 0, dy: 0 }, 0));
  corePoly.wash("#FAF6EB", 248);

  // Subtle aged paper warmth wash shifted in Y
  let warmPoly = new brush.Polygon(
    getCardWorldPolygon(card, { dx: PLATES.Y.dx * 0.4, dy: PLATES.Y.dy * 0.4 }, -0.01)
  );
  warmPoly.wash("#FFF4B8", 38);

  // 3. 3D paper shading & Bent Queen diagonal crease across the card surface
  drawCardSurfaceShading(card, uvOutline);

  // 4. Worn, dog-eared, delaminated corners and frayed paper fibers
  drawWornCorners(card);

  // 5. Crisp 4-plate misregistered outer card edge lines and card-stock thickness bevel
  strokeCardUVPath(card, uvOutline, PLATES.Y, 0.62, true, "rotring");
  strokeCardUVPath(card, uvOutline, PLATES.C, 0.58, true, "rotring");
  strokeCardUVPath(card, uvOutline, PLATES.M, 0.55, true, "rotring");
  strokeCardUVPath(card, uvOutline, PLATES.K, 0.78, true, "rotring");

  // Double-ply card stock thickness bevel along bottom and right edges
  let bevelShift = { dx: PLATES.K.dx + 2.8, dy: PLATES.K.dy + 3.4 };
  strokeCardUVPath(card, uvOutline.slice(12, 56), { hex: PLATES.K.hex, ...bevelShift }, 0.55, false, "rotring");
}

function drawCardSurfaceShading(card, uvOutline) {
  // Modulated CMYK surface hatching based on getCardShading(card, u, v)
  let plateConfigs = [
    { plate: PLATES.Y, spacingUV: 0.022, minShade: 0.14, weight: 0.48, angle: PLATES.Y.angle1 },
    { plate: PLATES.C, spacingUV: 0.020, minShade: 0.16, weight: 0.46, angle: PLATES.C.angle1 },
    { plate: PLATES.M, spacingUV: 0.024, minShade: 0.22, weight: 0.44, angle: PLATES.M.angle1 },
    { plate: PLATES.K, spacingUV: 0.022, minShade: 0.25, weight: 0.48, angle: PLATES.K.angle1 },
    // Cross-hatch pass in deep shadow zones (under overlaps & inside the Queen's bend)
    { plate: PLATES.C, spacingUV: 0.026, minShade: 0.36, weight: 0.44, angle: PLATES.C.angle2 },
    { plate: PLATES.K, spacingUV: 0.026, minShade: 0.42, weight: 0.46, angle: PLATES.K.angle2 }
  ];

  // If this is the Bent Queen, lay down soft CMYK washes inside the diagonal fold shadow band
  if (card.bent) {
    let bandUV = [];
    for (let s = 0; s <= 16; s++) {
      let u = -0.98 + (1.96 * s) / 16;
      bandUV.push([u, -0.10 + 0.23 * u]);
    }
    for (let s = 16; s >= 0; s--) {
      let u = -0.98 + (1.96 * s) / 16;
      bandUV.push([u, 0.24 + 0.23 * u]);
    }
    washCardUVPolygon(card, bandUV, PLATES.C.washHex, 26, PLATES.C);
    washCardUVPolygon(card, bandUV, PLATES.M.washHex, 20, PLATES.M);
    washCardUVPolygon(card, bandUV, PLATES.Y.washHex, 24, PLATES.Y);
    washCardUVPolygon(card, bandUV, PLATES.K.washHex, 30, PLATES.K);
  }

  for (let cfg of plateConfigs) {
    let relAngle = ((cfg.angle - card.angle) * Math.PI) / 180;
    let du = Math.cos(relAngle);
    let dv = Math.sin(relAngle) * (card.hw / card.hh);
    let len = Math.hypot(du, dv);
    du /= len;
    dv /= len;
    let nu = -dv;
    let nv = du;

    let maxR = 1.45;
    let steps = Math.ceil((2 * maxR) / cfg.spacingUV);
    brush.set("engraver", cfg.plate.hex, cfg.weight);

    for (let i = -steps; i <= steps; i++) {
      let d = i * cfg.spacingUV;
      let ou = d * nu;
      let ov = d * nv;
      let segs = clipLineToPolygon(ou, ov, du, dv, uvOutline);
      for (let s of segs) {
        let u0 = s[0],
          v0 = s[1],
          u1 = s[2],
          v1 = s[3];
        let totalLen = Math.hypot(u1 - u0, v1 - v0);
        let subN = Math.max(4, Math.ceil(totalLen / 0.055));
        let activePts = [];

        for (let k = 0; k <= subN; k++) {
          let kt = k / subN;
          let uu = lerp(u0, u1, kt);
          let vv = lerp(v0, v1, kt);
          let sh = getCardShading(card, uu, vv);
          if (sh.shade >= cfg.minShade && sh.ridge < 0.45) {
            let wp = cardToWorld(card, uu, vv, cfg.plate);
            let pressure = map(sh.shade, cfg.minShade, 0.85, 0.45, 1.35, true);
            activePts.push([wp[0], wp[1], pressure]);
          } else {
            if (activePts.length >= 2) {
              if (activePts.length >= 3) {
                brush.spline(activePts, 0.15);
              } else {
                brush.line(
                  activePts[0][0],
                  activePts[0][1],
                  activePts[1][0],
                  activePts[1][1]
                );
              }
            }
            activePts = [];
          }
        }
        if (activePts.length >= 2) {
          if (activePts.length >= 3) {
            brush.spline(activePts, 0.15);
          } else {
            brush.line(
              activePts[0][0],
              activePts[0][1],
              activePts[1][0],
              activePts[1][1]
            );
          }
        }
      }
    }
  }

  // Crisp paper-crease ridge micro-fissures and highlight edge on the Bent Queen
  if (card.bent) {
    let ridgePts = [];
    for (let s = 0; s <= 24; s++) {
      let u = -0.99 + (1.98 * s) / 24;
      let v = -0.11 + 0.23 * u + 0.005 * Math.sin(s * 0.9);
      ridgePts.push([u, v]);
    }
    // Delicate misregistered crease lines in C, Y, and K
    strokeCardUVPath(card, ridgePts, PLATES.Y, 0.55, false, "engraver");
    strokeCardUVPath(card, ridgePts, PLATES.C, 0.42, false, "engraver");
    strokeCardUVPath(card, ridgePts, PLATES.K, 0.38, false, "engraver");

    // Tiny perpendicular paper-fiber stress ticks along the fold ridge
    for (let s = 1; s < 24; s++) {
      if (s % 2 === 0) continue;
      let u = -0.95 + (1.9 * s) / 24;
      let v = -0.11 + 0.23 * u;
      let tick = [
        [u - 0.008, v - 0.025],
        [u + 0.008, v + 0.032]
      ];
      strokeCardUVPath(card, tick, PLATES.C, 0.35, false, "engraver");
      strokeCardUVPath(card, tick, PLATES.K, 0.35, false, "engraver");
    }
  }
}

function drawWornCorners(card) {
  let cornerPositions = [
    { su: -1, sv: -1, wear: card.cornerWear[0] },
    { su: 1, sv: -1, wear: card.cornerWear[1] },
    { su: 1, sv: 1, wear: card.cornerWear[2] },
    { su: -1, sv: 1, wear: card.cornerWear[3] }
  ];

  for (let c of cornerPositions) {
    if (c.wear < 0.45) continue;

    // 1. Diagonal dog-ear crease across worn corner tip
    let d1 = 0.14 + 0.08 * c.wear;
    let d2 = 0.11 + 0.07 * c.wear;
    let creaseLine = [
      [c.su * (1 - d1), c.sv * 0.98],
      [c.su * (1 - 0.52 * d1), c.sv * (1 - 0.48 * d2)],
      [c.su * 0.98, c.sv * (1 - d2)]
    ];
    strokeCardUVPath(card, creaseLine, PLATES.Y, 0.55 * c.wear, false, "engraver");
    strokeCardUVPath(card, creaseLine, PLATES.M, 0.42 * c.wear, false, "engraver");
    strokeCardUVPath(card, creaseLine, PLATES.C, 0.45 * c.wear, false, "engraver");
    strokeCardUVPath(card, creaseLine, PLATES.K, 0.52 * c.wear, false, "engraver");

    // Second delaminated paper ply arc right at the corner tip
    let plyArc = [];
    let steps = 7;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let u = lerp(c.su * (1 - 0.095), c.su * 0.99, t);
      let v = lerp(c.sv * 0.99, c.sv * (1 - 0.075), t);
      plyArc.push([u, v]);
    }
    strokeCardUVPath(card, plyArc, PLATES.Y, 0.65, false, "rotring");
    strokeCardUVPath(card, plyArc, PLATES.K, 0.48, false, "rotring");

    // Frayed microscopic paper fibers radiating from scuffed corner
    let fiberCount = Math.floor(10 * c.wear);
    for (let f = 0; f < fiberCount; f++) {
      let ft = (f + 0.5) / fiberCount;
      let u0 = lerp(c.su * 0.90, c.su * 0.985, ft);
      let v0 = lerp(c.sv * 0.985, c.sv * 0.92, ft);
      let u1 = u0 + c.su * random(0.012, 0.028);
      let v1 = v0 + c.sv * random(0.010, 0.022);
      let pl = f % 3 === 0 ? PLATES.Y : f % 3 === 1 ? PLATES.K : PLATES.M;
      strokeCardUVPath(card, [[u0, v0], [u1, v1]], pl, 0.36, false, "engraver");
    }
  }
}

// ============================================================================
// STAGE 3: SUIT PIPS, RANK INDICES & COURT CARD ILLUSTRATIONS IN 4-COLOR CMYK
// ============================================================================

function getPipUVPolygon(suit, cx, cy, su, sv, flip = false) {
  let dir = flip ? -1 : 1;
  let pts = [];

  if (suit === "H") {
    // Classic French Heart pip
    let steps = 28;
    for (let i = 0; i < steps; i++) {
      let t = (i / steps) * Math.PI * 2;
      let x = 16 * Math.pow(Math.sin(t), 3) / 16;
      let y =
        -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) /
        16;
      pts.push([cx + x * su, cy + y * sv * dir]);
    }
  } else if (suit === "D") {
    // Slightly concave-edged classic Diamond pip
    let steps = 24;
    for (let i = 0; i < steps; i++) {
      let t = (i / steps) * Math.PI * 2;
      let c = Math.cos(t);
      let s = Math.sin(t);
      let x = Math.sign(c) * Math.pow(Math.abs(c), 1.18) * 0.88;
      let y = Math.sign(s) * Math.pow(Math.abs(s), 1.18) * 1.08;
      pts.push([cx + x * su, cy + y * sv * dir]);
    }
  } else if (suit === "S") {
    // Pointed Spade pip with flared pedestal stem
    let raw = [
      [0, -1.08],
      [0.28, -0.68],
      [0.72, -0.22],
      [0.92, 0.16],
      [0.82, 0.48],
      [0.52, 0.62],
      [0.24, 0.50],
      [0.14, 0.36],
      [0.22, 0.78],
      [0.42, 1.02],
      [-0.42, 1.02],
      [-0.22, 0.78],
      [-0.14, 0.36],
      [-0.24, 0.50],
      [-0.52, 0.62],
      [-0.82, 0.48],
      [-0.92, 0.16],
      [-0.72, -0.22],
      [-0.28, -0.68]
    ];
    pts = raw.map(([x, y]) => [cx + x * su, cy + y * sv * dir]);
  } else if (suit === "C") {
    // Three-lobed trefoil Club pip with flared stem
    let raw = [];
    // Top lobe
    for (let a = -140; a <= 140; a += 28) {
      let r = (a * Math.PI) / 180;
      raw.push([0.46 * Math.sin(r), -0.48 - 0.46 * Math.cos(r)]);
    }
    // Right lobe
    for (let a = -50; a <= 210; a += 28) {
      let r = (a * Math.PI) / 180;
      raw.push([0.48 + 0.46 * Math.sin(r), 0.12 - 0.46 * Math.cos(r)]);
    }
    // Stem
    raw.push([0.16, 0.35], [0.24, 0.78], [0.42, 1.02], [-0.42, 1.02], [-0.24, 0.78], [-0.16, 0.35]);
    // Left lobe
    for (let a = -210; a <= 50; a += 28) {
      let r = (a * Math.PI) / 180;
      raw.push([-0.48 + 0.46 * Math.sin(r), 0.12 - 0.46 * Math.cos(r)]);
    }
    pts = raw.map(([x, y]) => [cx + x * su, cy + y * sv * dir]);
  }
  return pts;
}

// Render a single pip through all 4 misregistered CMYK plates
function drawPipCMYK(card, suit, cx, cy, su, sv, flip = false) {
  let poly = getPipUVPolygon(suit, cx, cy, su, sv, flip);
  let isRed = suit === "H" || suit === "D";

  if (isRed) {
    // Vivid Crimson Red = Saturated Yellow + Saturated Magenta + Cyan/Black shadow & ghost fringes
    washCardUVPolygon(card, poly, PLATES.Y.washHex, 195, PLATES.Y);
    washCardUVPolygon(card, poly, PLATES.M.washHex, 185, PLATES.M);

    hatchCardUVPolygon(card, poly, 0.011, PLATES.Y.angle1, PLATES.Y, 0.65);
    hatchCardUVPolygon(card, poly, 0.014, PLATES.Y.angle2, PLATES.Y, 0.55);
    hatchCardUVPolygon(card, poly, 0.010, PLATES.M.angle1, PLATES.M, 0.68);
    hatchCardUVPolygon(card, poly, 0.014, PLATES.M.angle2, PLATES.M, 0.56);

    // Subtle Cyan & Black cross-hatch in the shaded right half of the pip + misregistered ghost outline
    let halfPoly = poly.filter((p) => p[0] >= cx - 0.15 * su);
    if (halfPoly.length >= 3) {
      hatchCardUVPolygon(card, halfPoly, 0.018, PLATES.C.angle1, PLATES.C, 0.42);
      hatchCardUVPolygon(card, halfPoly, 0.022, PLATES.K.angle1, PLATES.K, 0.38);
    }

    strokeCardUVPath(card, poly, PLATES.Y, 0.58, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.C, 0.38, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.M, 0.68, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.K, 0.42, true, "rotring");
  } else {
    // Rich Process Black = Under-color C + M + Y + Dense K cross-hatch (giving CMY fringes around every black pip!)
    washCardUVPolygon(card, poly, PLATES.Y.washHex, 110, PLATES.Y);
    washCardUVPolygon(card, poly, PLATES.C.washHex, 145, PLATES.C);
    washCardUVPolygon(card, poly, PLATES.M.washHex, 130, PLATES.M);
    washCardUVPolygon(card, poly, PLATES.K.washHex, 185, PLATES.K);

    hatchCardUVPolygon(card, poly, 0.014, PLATES.Y.angle1, PLATES.Y, 0.52);
    hatchCardUVPolygon(card, poly, 0.012, PLATES.C.angle1, PLATES.C, 0.62);
    hatchCardUVPolygon(card, poly, 0.013, PLATES.M.angle1, PLATES.M, 0.58);
    hatchCardUVPolygon(card, poly, 0.010, PLATES.K.angle1, PLATES.K, 0.72);
    hatchCardUVPolygon(card, poly, 0.012, PLATES.K.angle2, PLATES.K, 0.64);

    strokeCardUVPath(card, poly, PLATES.Y, 0.52, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.C, 0.58, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.M, 0.55, true, "rotring");
    strokeCardUVPath(card, poly, PLATES.K, 0.78, true, "rotring");
  }
}

// Draw corner rank index ("Q", "A", "10", "7", "J", "K") + mini pip in all 4 shifted CMYK plates
function drawCornerIndexCMYK(card, rank, suit, cx, cy, flip = false) {
  let dir = flip ? -1 : 1;
  let w = 0.056 * dir;
  let h = 0.068 * dir;
  let isRed = suit === "H" || suit === "D";

  // Build vector strokes for the rank character
  let strokes = [];
  let serifs = [];

  if (rank === "Q") {
    let oval = [];
    for (let i = 0; i <= 20; i++) {
      let a = (i / 20) * Math.PI * 2;
      oval.push([cx + 0.85 * w * Math.cos(a), cy + h * Math.sin(a)]);
    }
    strokes.push(oval);
    // Inner counter contour for bold engraved feel
    let ovalIn = [];
    for (let i = 0; i <= 16; i++) {
      let a = (i / 16) * Math.PI * 2;
      ovalIn.push([cx + 0.52 * w * Math.cos(a), cy + 0.68 * h * Math.sin(a)]);
    }
    strokes.push(ovalIn);
    // Swash tail of Q
    strokes.push([
      [cx + 0.1 * w, cy + 0.45 * h],
      [cx + 0.55 * w, cy + 0.95 * h],
      [cx + 0.98 * w, cy + 1.15 * h],
      [cx + 1.22 * w, cy + 0.95 * h]
    ]);
  } else if (rank === "A") {
    strokes.push([
      [cx - 0.85 * w, cy + h],
      [cx, cy - h],
      [cx + 0.85 * w, cy + h]
    ]);
    strokes.push([
      [cx - 0.52 * w, cy + 0.28 * h],
      [cx + 0.52 * w, cy + 0.28 * h]
    ]);
    serifs.push(
      [[cx - 1.05 * w, cy + h], [cx - 0.55 * w, cy + h]],
      [[cx + 0.55 * w, cy + h], [cx + 1.05 * w, cy + h]]
    );
  } else if (rank === "10") {
    // "1"
    strokes.push([
      [cx - 0.78 * w, cy - h],
      [cx - 0.78 * w, cy + h]
    ]);
    serifs.push(
      [[cx - 1.02 * w, cy - 0.82 * h], [cx - 0.78 * w, cy - h]],
      [[cx - 1.05 * w, cy + h], [cx - 0.52 * w, cy + h]]
    );
    // "0"
    let zero = [];
    for (let i = 0; i <= 18; i++) {
      let a = (i / 18) * Math.PI * 2;
      zero.push([cx + 0.35 * w + 0.62 * w * Math.cos(a), cy + h * Math.sin(a)]);
    }
    strokes.push(zero);
  } else if (rank === "7") {
    strokes.push([
      [cx - 0.8 * w, cy - 0.65 * h],
      [cx - 0.8 * w, cy - h],
      [cx + 0.85 * w, cy - h],
      [cx - 0.25 * w, cy + h]
    ]);
  } else if (rank === "J") {
    strokes.push([
      [cx + 0.35 * w, cy - h],
      [cx + 0.35 * w, cy + 0.45 * h],
      [cx + 0.1 * w, cy + 0.95 * h],
      [cx - 0.45 * w, cy + 0.95 * h],
      [cx - 0.72 * w, cy + 0.55 * h]
    ]);
    serifs.push([[cx - 0.1 * w, cy - h], [cx + 0.8 * w, cy - h]]);
  } else if (rank === "K") {
    strokes.push([[cx - 0.75 * w, cy - h], [cx - 0.75 * w, cy + h]]);
    strokes.push([[cx + 0.78 * w, cy - h], [cx - 0.65 * w, cy + 0.08 * h]]);
    strokes.push([[cx - 0.25 * w, cy - 0.22 * h], [cx + 0.85 * w, cy + h]]);
  }

  let plateWeights = isRed
    ? [
        { plate: PLATES.Y, w: 0.92 },
        { plate: PLATES.C, w: 0.42 },
        { plate: PLATES.M, w: 0.88 },
        { plate: PLATES.K, w: 0.46 }
      ]
    : [
        { plate: PLATES.Y, w: 0.62 },
        { plate: PLATES.C, w: 0.75 },
        { plate: PLATES.M, w: 0.72 },
        { plate: PLATES.K, w: 0.96 }
      ];

  for (let pw of plateWeights) {
    for (let st of strokes) {
      strokeCardUVPath(card, st, pw.plate, pw.w, false, "rotring");
      // Double-stroke offset for bold display letterform thickness
      let stOffset = st.map(([u, v]) => [u + 0.008 * dir, v]);
      strokeCardUVPath(card, stOffset, pw.plate, pw.w * 0.82, false, "rotring");
    }
    for (let sf of serifs) {
      strokeCardUVPath(card, sf, pw.plate, pw.w * 0.75, false, "rotring");
    }
  }

  // Mini suit pip directly under the rank index
  drawPipCMYK(card, suit, cx, cy + 0.155 * dir, 0.052, 0.042, flip);
}

// ============================================================================
// ORNATE ACE OF SPADES & COURT CARD ILLUSTRATIONS (Q♥, J♦, K♠)
// ============================================================================

function drawOrnateAceOfSpades(card) {
  // Monumental central Spade with negative-space baroque engraving & concentric rings
  let outerSpade = getPipUVPolygon("S", 0, -0.02, 0.48, 0.42, false);

  // Shifted CMYK base washes
  washCardUVPolygon(card, outerSpade, PLATES.Y.washHex, 105, PLATES.Y);
  washCardUVPolygon(card, outerSpade, PLATES.C.washHex, 145, PLATES.C);
  washCardUVPolygon(card, outerSpade, PLATES.M.washHex, 130, PLATES.M);
  washCardUVPolygon(card, outerSpade, PLATES.K.washHex, 175, PLATES.K);

  // Dense 4-plate cross-hatching inside the giant spade
  hatchCardUVPolygon(card, outerSpade, 0.013, PLATES.Y.angle1, PLATES.Y, 0.56);
  hatchCardUVPolygon(card, outerSpade, 0.011, PLATES.C.angle1, PLATES.C, 0.68);
  hatchCardUVPolygon(card, outerSpade, 0.012, PLATES.M.angle1, PLATES.M, 0.62);
  hatchCardUVPolygon(card, outerSpade, 0.009, PLATES.K.angle1, PLATES.K, 0.76);
  hatchCardUVPolygon(card, outerSpade, 0.011, PLATES.K.angle2, PLATES.K, 0.68);

  // Outer multi-plate misregistered borders
  for (let pl of [PLATES.Y, PLATES.C, PLATES.M, PLATES.K]) {
    strokeCardUVPath(card, outerSpade, pl, 0.78, true, "rotring");
  }

  // Negative-space ornate circular medallion inside the Ace of Spades
  let medCenter = [0, -0.02];
  let medPoly = [];
  for (let i = 0; i < 32; i++) {
    let a = (i / 32) * Math.PI * 2;
    medPoly.push([medCenter[0] + 0.24 * Math.cos(a), medCenter[1] + 0.175 * Math.sin(a)]);
  }
  washCardUVPolygon(card, medPoly, "#FAF6EB", 240, { dx: 0, dy: 0 });

  // Concentric engraved rosette rings & radiating sunburst lines in C, M, Y, K
  let rings = [0.23, 0.19, 0.11, 0.05];
  for (let r of rings) {
    let ringPts = [];
    for (let i = 0; i <= 28; i++) {
      let a = (i / 28) * Math.PI * 2;
      ringPts.push([medCenter[0] + r * Math.cos(a), medCenter[1] + r * 0.73 * Math.sin(a)]);
    }
    strokeCardUVPath(card, ringPts, PLATES.Y, 0.52, true, "engraver");
    strokeCardUVPath(card, ringPts, PLATES.C, 0.55, true, "engraver");
    strokeCardUVPath(card, ringPts, PLATES.M, 0.48, true, "engraver");
    strokeCardUVPath(card, ringPts, PLATES.K, 0.65, true, "engraver");
  }

  // Radiating guilloche spokes inside the medallion
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * Math.PI * 2;
    let p0 = [medCenter[0] + 0.055 * Math.cos(a), medCenter[1] + 0.04 * Math.sin(a)];
    let p1 = [medCenter[0] + 0.185 * Math.cos(a), medCenter[1] + 0.135 * Math.sin(a)];
    let pl = i % 2 === 0 ? PLATES.K : PLATES.C;
    strokeCardUVPath(card, [p0, p1], pl, 0.45, false, "engraver");
  }

  // Inner mini spade at the heart of the medallion
  drawPipCMYK(card, "S", 0, -0.02, 0.065, 0.055, false);

  // Ornamental ribbon banner below the Ace of Spades
  let ribbon = [
    [-0.36, 0.52],
    [0, 0.48],
    [0.36, 0.52],
    [0.32, 0.59],
    [0, 0.55],
    [-0.32, 0.59]
  ];
  hatchCardUVPolygon(card, ribbon, 0.014, PLATES.Y.angle1, PLATES.Y, 0.5);
  strokeCardUVPath(card, ribbon, PLATES.C, 0.48, true, "engraver");
  strokeCardUVPath(card, ribbon, PLATES.M, 0.45, true, "engraver");
  strokeCardUVPath(card, ribbon, PLATES.K, 0.62, true, "engraver");
}

// ============================================================================
// THE BENT QUEEN OF HEARTS (Q♥) — FULL DOUBLE-ENDED CMYK COURT ILLUSTRATION
// ============================================================================

function drawQueenOfHearts(card) {
  // 1. Inner court frame box (warped across the 3D bend!)
  let fx = 0.72,
    fy = 0.76;
  let outerFrame = [
    [-fx, -fy],
    [fx, -fy],
    [fx, fy],
    [-fx, fy]
  ];
  let innerFrame = [
    [-fx + 0.025, -fy + 0.018],
    [fx - 0.025, -fy + 0.018],
    [fx - 0.025, fy - 0.018],
    [-fx + 0.025, fy - 0.018]
  ];

  // Gold & Cyan-Blue border frame bands
  for (let pl of [PLATES.Y, PLATES.C, PLATES.M, PLATES.K]) {
    let w = pl.id === "K" ? 0.75 : 0.62;
    strokeCardUVPath(card, outerFrame, pl, w, true, "rotring");
    strokeCardUVPath(card, innerFrame, pl, w * 0.85, true, "rotring");
  }

  // Draw both upright top half (dir = 1) and inverted bottom half (dir = -1)
  drawQueenHalf(card, 1);
  drawQueenHalf(card, -1);

  // Diagonal dividing sash across the center of the court card
  let sash = [
    [-fx + 0.025, 0.09],
    [fx - 0.025, -0.09],
    [fx - 0.025, -0.03],
    [-fx + 0.025, 0.15]
  ];
  let sash2 = [
    [-fx + 0.025, -0.15],
    [fx - 0.025, 0.03],
    [fx - 0.025, 0.09],
    [-fx + 0.025, -0.09]
  ];
  for (let sPoly of [sash, sash2]) {
    washCardUVPolygon(card, sPoly, PLATES.Y.washHex, 175, PLATES.Y);
    hatchCardUVPolygon(card, sPoly, 0.012, PLATES.Y.angle1, PLATES.Y, 0.62);
    hatchCardUVPolygon(card, sPoly, 0.018, PLATES.M.angle1, PLATES.M, 0.45);
    strokeCardUVPath(card, sPoly, PLATES.C, 0.52, true, "rotring");
    strokeCardUVPath(card, sPoly, PLATES.M, 0.55, true, "rotring");
    strokeCardUVPath(card, sPoly, PLATES.K, 0.72, true, "rotring");
  }
}

function drawQueenHalf(card, dir) {
  // Helper to transform half-card coordinates (x, y) into (u, v) for upright (dir=1) or inverted (dir=-1)
  const T = (pts) => pts.map(([x, y]) => [x * dir, y * dir]);

