// Simplified geometric court pattern for the cropped Jack of Diamonds (J♦) & King of Spades (K♠)
function drawCroppedCourtCard(card) {
  let fx = 0.72,
    fy = 0.76;
  let frame = [
    [-fx, -fy],
    [fx, -fy],
    [fx, fy],
    [-fx, fy]
  ];
  for (let pl of [PLATES.Y, PLATES.C, PLATES.M, PLATES.K]) {
    strokeCardUVPath(card, frame, pl, 0.65, true, "rotring");
  }

  for (let dir of [1, -1]) {
    const T = (pts) => pts.map(([x, y]) => [x * dir, y * dir]);

    let robe = T([
      [-0.68, -0.04],
      [-0.68, -0.45],
      [0.68, -0.45],
      [0.68, -0.04]
    ]);
    washCardUVPolygon(card, robe, PLATES.Y.washHex, 165, PLATES.Y);
    washCardUVPolygon(card, robe, PLATES.M.washHex, 165, PLATES.M);
    hatchCardUVPolygon(card, robe, 0.013, PLATES.Y.angle1, PLATES.Y, 0.62);
    hatchCardUVPolygon(card, robe, 0.012, PLATES.M.angle1, PLATES.M, 0.65);
    hatchCardUVPolygon(card, robe, 0.015, PLATES.C.angle1, PLATES.C, 0.55);
    hatchCardUVPolygon(card, robe, 0.016, PLATES.K.angle1, PLATES.K, 0.58);
    strokeCardUVPath(card, robe, PLATES.K, 0.7, true, "rotring");

    let crown = T([
      [-0.32, -0.58],
      [-0.36, -0.73],
      [0.0, -0.68],
      [0.36, -0.73],
      [0.32, -0.58]
    ]);
    washCardUVPolygon(card, crown, PLATES.Y.washHex, 200, PLATES.Y);
    hatchCardUVPolygon(card, crown, 0.011, PLATES.Y.angle1, PLATES.Y, 0.68);
    strokeCardUVPath(card, crown, PLATES.M, 0.55, true, "rotring");
    strokeCardUVPath(card, crown, PLATES.K, 0.72, true, "rotring");

    let face = T([
      [-0.17, -0.58],
      [0.17, -0.58],
      [0.15, -0.38],
      [-0.15, -0.38]
    ]);
    washCardUVPolygon(card, face, "#FAF6EB", 240, { dx: 0, dy: 0 });
    hatchCardUVPolygon(card, face, 0.016, PLATES.C.angle1, PLATES.C, 0.38);
    strokeCardUVPath(card, face, PLATES.K, 0.68, true, "rotring");

    drawPipCMYK(card, card.suit, 0.48 * dir, -0.54 * dir, 0.13, 0.105, dir === -1);
  }
}

// ============================================================================
// MASTER CARD GRAPHICS DISPATCHER
