function drawCardGraphics(card) {
  // Corner indices at top-left (-0.85, -0.81) and inverted bottom-right (0.85, 0.81)
  drawCornerIndexCMYK(card, card.rank, card.suit, -0.85, -0.80, false);
  drawCornerIndexCMYK(card, card.rank, card.suit, 0.85, 0.80, true);

  if (card.id === "QH") {
    drawQueenOfHearts(card);
  } else if (card.id === "AS") {
    drawOrnateAceOfSpades(card);
  } else if (card.id === "10D") {
    // 10 of Diamonds pip layout
    let ys = [-0.66, -0.22, 0.22, 0.66];
    for (let y of ys) {
      drawPipCMYK(card, "D", -0.42, y, 0.13, 0.105, y > 0);
      drawPipCMYK(card, "D", 0.42, y, 0.13, 0.105, y > 0);
    }
    drawPipCMYK(card, "D", 0, -0.44, 0.13, 0.105, false);
    drawPipCMYK(card, "D", 0, 0.44, 0.13, 0.105, true);
  } else if (card.id === "7C") {
    // 7 of Clubs pip layout
    let ys = [-0.64, 0.0, 0.64];
    for (let y of ys) {
      drawPipCMYK(card, "C", -0.42, y, 0.135, 0.11, y > 0);
      drawPipCMYK(card, "C", 0.42, y, 0.135, 0.11, y > 0);
    }
    drawPipCMYK(card, "C", 0, -0.32, 0.135, 0.11, false);
  } else if (card.id === "JD" || card.id === "KS") {
    drawCroppedCourtCard(card);
  }
}

