function draw() {
  translate(-width / 2, -height / 2);

  // 1. Render green baize table in 4 misregistered CMYK hatched layers + woollen nap
  drawGreenBaize();

  // 2. Render each card back-to-front with cast shadows, CMYK fringes, 3D bend & graphics
  for (let card of CARDS) {
    drawCardCastShadow(card);
    drawCardBodyAndFringes(card);
    drawCardGraphics(card);
  }

  noLoop();
}

// Hyperreal Coloured Pencil vs. Unfinished Colouring-Book Page
// A sleeping tabby cat on a cast-iron radiator with a drying wool sock

function getBoundaryX(y) {
  // Base diagonal sweep from top-center-left to bottom-center
  let base = 515 + (y - 600) * 0.05;
  // Medium ragged blocks (like sections colored by hand)
  let med = (noise(y * 0.009, 1.7) - 0.5) * 115;
  // Sharp jagged diagonal pencil-stroke teeth along the working edge
  let toothPhase = (y * 0.14) + noise(y * 0.03, 4.2) * 3.0;
  let teeth = (abs((toothPhase % 2) - 1) - 0.5) * 42;
  // Extra jutting out over the cat's shoulder/back where coloring is active
  let catBump = (y > 260 && y < 525) ? sin(map(y, 260, 525, 0, 180)) * 28 : 0;
  return base + med + teeth - catBump;
}

// Returns < 0 in pure coloring-book left zone, 0..1 in ragged transition fringe, > 1 in full hyperreal right zone
function colorFactor(x, y) {
  let bx = getBoundaryX(y);
  return (x - bx) / 52.0;
}

// Helper for closed filled shapes using beginShape/vertex
function drawFilledPoly(pts, col, opacity, bleed = 0.05, tex = 0.25, curv = 0.15) {
  if (pts.length < 3) return;
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.2);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawWashedPoly(pts, col, opacity, curv = 0.1) {
  if (pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// Clips a polyline or draws segments only where predicate(x, y) holds
function drawClippedCurve(pts, brushName, col, weight, keepFn, curv = 0.25) {
  if (pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  let sub = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (keepFn(p[0], p[1])) {
      sub.push(p);
    } else {
      if (sub.length >= 2) {
        brush.spline(sub, curv);
      } else if (sub.length === 1 && i > 0) {
        brush.line(sub[0][0], sub[0][1], (sub[0][0] + p[0]) * 0.5, (sub[0][1] + p[1]) * 0.5);
      }
      sub = [];
    }
  }
  if (sub.length >= 2) {
    brush.spline(sub, curv);
  }
}

function drawClippedLine(x1, y1, x2, y2, brushName, col, weight, keepFn, steps = 16) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    pts.push([lerp(x1, x2, t), lerp(y1, y2, t)]);
  }
  drawClippedCurve(pts, brushName, col, weight, keepFn, 0);
}

