    opacity: 62,
    spacing: 0.32,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.3
  });

  // Razor-sharp opaque white/ivory whisker stylus
  brush.add("whiskerTip", {
    type: "default",
    weight: 0.42,
    scatter: 0.01,
    sharpness: 0.97,
    grain: 3,
    opacity: 252,
    spacing: 0.09,
    pressure: [1.05, 0.72, 0.04],
    noise: 0.06
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#faf7f0");

  // Predicate for coloring-book line art: present on left side and fading out across the boundary fringe
  const isLineVisible = (x, y) => {
    let cf = colorFactor(x, y);
    if (cf < 0.05) return true;
    if (cf > 0.68) return false;
    return noise(x * 0.06, y * 0.06) > map(cf, 0.05, 0.68, 0.1, 0.95);
  };

  // Predicate for hyperreal colored pencil: present on right side and raggedly entering the fringe
  const isColorVisible = (x, y) => {
    let cf = colorFactor(x, y);
    return cf > -0.15;
  };

  // =========================================================================
  // 1. RIGHT-SIDE BACKGROUND: WALL, WAINSCOTING & FLOOR (COLORED PENCIL)
  // =========================================================================
  renderRightBackground(isColorVisible);

  // =========================================================================
  // 2. RIGHT-SIDE CAST-IRON RADIATOR (HYPERREAL CREAM ENAMEL, RUST & CHIPS)
  // =========================================================================
  renderRightRadiator(isColorVisible);

  // =========================================================================
  // 3. RIGHT-SIDE DRYING SOCK (RIBBED CHARCOAL WOOL WITH GINGER STRIPES)
  // =========================================================================
  renderDryingSock(isColorVisible);

  // =========================================================================
  // 4. RIGHT-SIDE SLEEPING TABBY CAT (FUR PELAGE, GINGER PATCHES, WHISKERS)
  // =========================================================================
  renderRightCat(isColorVisible);

  // =========================================================================
  // 5. RAGGED MID-WORK BOUNDARY TRANSITION (ACTIVE PENCIL HATCHING FRINGE)
  // =========================================================================
  renderBoundaryFringe();

  // =========================================================================
  // 6. LEFT-SIDE COLOURING-BOOK LINE ART (CRISP UNIFORM BLACK OUTLINES)
  // =========================================================================
  renderLeftColoringBookOutlines(isLineVisible);

  // =========================================================================
  // 7. FINAL HYPERREAL HIGHLIGHTS, STRAY FIBERS & WHISKERS (RIGHT SIDE)
  // =========================================================================
  renderFinalHyperrealAccents();

  noLoop();
}

// ===========================================================================
// SECTION 1: RIGHT-SIDE WALL & FLOOR (WARM MONOCHROME + HEAT SHADOW)
// ===========================================================================
function renderRightBackground(keepFn) {
  // Subtle warm stone-grey tonal shading on upper wall and deep heat-shadow behind radiator
  let wallRightPts = [];
  for (let y = 30; y <= 230; y += 25) wallRightPts.push([max(480, getBoundaryX(y)), y]);
  wallRightPts.push([1160, 230], [1160, 30]);
  drawFilledPoly(wallRightPts, "#e5e0d5", 95, 0.08, 0.35);

  // Lower wall behind and around radiator
  let lowerWallPts = [];
  for (let y = 230; y <= 940; y += 30) lowerWallPts.push([max(460, getBoundaryX(y)), y]);
  lowerWallPts.push([1160, 940], [1160, 230]);
  drawFilledPoly(lowerWallPts, "#d9d3c7", 125, 0.08, 0.4);

  // Deep cast shadow directly behind radiator columns and under cat/sock
  let radShadowPts = [];
  for (let y = 495; y <= 995; y += 25) radShadowPts.push([max(480, getBoundaryX(y) + 10), y]);
  radShadowPts.push([1055, 995], [1055, 495]);
  drawWashedPoly(radShadowPts, "#23211f", 215);

  // Floorboards tonal base on the right
  let floorPts = [];
  for (let y = 940; y <= 1165; y += 30) floorPts.push([max(480, getBoundaryX(y)), y]);
  floorPts.push([1160, 1165], [1160, 940]);
  drawFilledPoly(floorPts, "#cdc5b8", 130, 0.06, 0.35);

  // Colored pencil cross-hatching on the wall and rising heat-convection smudges above the cat
  brush.noFill();
  brush.noWash();
  for (let y = 42; y < 935; y += 5) {
    let bx = getBoundaryX(y);
    let startX = max(460, bx + random(-18, 12));
    if (startX < 1150) {
      let isMolding = (y > 218 && y < 262);
      let col = isMolding ? "#9e9689" : (y < 220 ? "#c7c0b4" : "#b5ada0");
      let w = isMolding ? 0.55 : 0.42;
      brush.set("cpencil", col, w);
      brush.line(startX, y + random(-1, 1), random(1135, 1158), y + random(-1, 1));
    }
  }

  // Diagonal colored-pencil grain on wall behind cat to create soft atmospheric depth
  for (let i = 0; i < 380; i++) {
    let x = random(510, 1140);
    let y = random(45, 510);
    let cf = colorFactor(x, y);
    if (cf > 0.1) {
      // Darker warm charcoal halo directly behind the sleeping cat's backlit ears and head
      let distToHead = dist(x, y, 735, 360);
      let col = distToHead < 210 ? "#6e675f" : (distToHead < 310 ? "#968e84" : "#bfb8ac");
      let len = map(constrain(cf, 0, 1), 0, 1, 18, 48);
      let ang = -58 + random(-8, 8);
      brush.set("burnish", col, random(0.45, 0.85));
      brush.line(
        x, y,
        x + cos(ang) * len,
        y + sin(ang) * len
      );
    }
  }

  // Moldings (chair rail y=220..258 & baseboard y=925..1045) rendered with hyperreal pencil modeling
  let moldingRows = [
    { y: 220, c: "#6b655c", w: 0.7 },
    { y: 224, c: "#f7f3eb", w: 0.8 },
    { y: 233, c: "#878075", w: 0.65 },
    { y: 251, c: "#544f48", w: 0.8 },
    { y: 258, c: "#aba396", w: 0.6 },
    { y: 926, c: "#635d55", w: 0.7 },
    { y: 938, c: "#ded7ca", w: 0.8 },
    { y: 954, c: "#787167", w: 0.6 },
    { y: 1044, c: "#3b3733", w: 0.9 }
  ];
  for (let m of moldingRows) {
    let sx = max(470, getBoundaryX(m.y));
    brush.set("cpencil", m.c, m.w);
    brush.line(sx, m.y, 1155, m.y);
  }

  // Floor shadow under the radiator & wood grain on the right
  drawFilledPoly([
    [max(510, getBoundaryX(1045)), 1038],
    [1080, 1038],
    [1110, 1120],
    [max(500, getBoundaryX(1120)), 1120]
  ], "#5e5850", 145, 0.12, 0.4);

  for (let y = 1046; y < 1160; y += 3.5) {
    let sx = max(480, getBoundaryX(y) + random(-15, 10));
    let isUnderRad = (y < 1105);
    let col = isUnderRad ? (random() < 0.5 ? "#3d3934" : "#59534b") : (random() < 0.5 ? "#8c8478" : "#a89f92");
    brush.set("cpencil", col, random(0.4, 0.75));
    brush.line(sx, y, random(1130, 1158), y + random(-1.5, 1.5));
  }
}

// ===========================================================================
// SECTION 2: RIGHT-SIDE CAST-IRON RADIATOR (COLUMNS 3..8 + RIGHT VALVE)
// ===========================================================================
function getColX(col) {
  return 212 + col * 96;
}

function renderRightRadiator(keepFn) {
  const topY = 516;
  const botY = 984;

  // Render columns 3 through 8 (Col 3 is right on the ragged transition, 4..8 are fully rendered)
  for (let col = 3; col <= 8; col++) {
    let cx = getColX(col);
    let isEndCol = (col === 8);
    let colBotY = isEndCol ? 1068 : botY;

    // 1. Recessed back column tube & horizontal manifolds (dark cast-iron in shadow)
    let backCx = cx + 22;
    if (col < 8) {
      // Top & bottom connecting bosses in the gap
      drawWashedPoly([
        [cx + 24, 552], [cx + 74, 552], [cx + 74, 594], [cx + 24, 594]
      ], "#2d2a27", 230);
      drawWashedPoly([
        [cx + 24, 912], [cx + 74, 912], [cx + 74, 954], [cx + 24, 954]
      ], "#262320", 235);

      // Recessed rear column cylinder in the gap
      drawWashedPoly([
        [backCx - 16, 528], [backCx + 24, 528],
        [backCx + 24, 974], [backCx - 16, 974]
      ], "#45413c", 220);

      // Vertical pencil shading on rear column
      for (let rx = backCx - 10; rx <= backCx + 22; rx += 3.5) {
        let shade = rx < backCx + 4 ? "#6b655d" : "#2b2825";
        drawClippedLine(rx, 532, rx, 970, "cpencil", shade, 0.55, keepFn, 14);
      }
    }

    // 2. Front Column Base Enamel (Warm Cream #efe7d6 -> Cool Slate Shadow #7a736a)
    let frontPts = [];
    for (let a = 180; a <= 360; a += 30) {
      frontPts.push([cx + cos(a) * 32, (topY + 32) + sin(a) * 32]);
    }
    if (isEndCol) {
      // Flared ornate cast-iron foot on column 8
      frontPts.push(
        [cx + 32, 960], [cx + 42, 1030], [cx + 46, 1068],
        [cx + 22, 1068], [cx + 14, 1005], [cx - 14, 1005],
        [cx - 22, 1068], [cx - 44, 1068], [cx - 38, 1030], [cx - 32, 960]
      );
    } else {
      for (let a = 0; a <= 180; a += 30) {
        frontPts.push([cx + cos(a) * 32, (botY - 32) + sin(a) * 32]);
      }
    }

    // Clip polygon vertices to right of boundary for Col 3
    let clippedFront = frontPts.map(p => [max(getBoundaryX(p[1]) - 8, p[0]), p[1]]);
    drawWashedPoly(clippedFront, "#e6decb", 235);

    // 3. Cylindrical 3D colored-pencil modeling across each cast-iron column
    for (let dx = -31; dx <= 31; dx += 2.2) {
      let x = cx + dx;
      let norm = dx / 32.0; // -1 (left light edge) to +1 (right shadow edge)
      let domeOffset = sqrt(max(0, 1 - norm * norm)) * 30;
      let y1 = (topY + 32) - domeOffset;
      let y2 = (botY - 32) + domeOffset;

      // Determine cylindrical enamel tone
      let colTone;
      if (norm < -0.55) colTone = "#cfc6b4"; // reflected edge
      else if (norm < -0.15) colTone = "#f7f2e6"; // bright cream specular zone
      else if (norm < 0.25) colTone = "#e3dac8"; // warm cream midtone
      else if (norm < 0.65) colTone = "#aba293"; // cool turn of form
      else colTone = "#69635a"; // core shadow & edge

      drawClippedLine(x, y1, x, y2, "burnish", colTone, 0.55, keepFn, 18);

      // Fine colored-pencil grain & vertical cast-iron pit texture
      if (abs(dx) % 4.4 < 2.2) {
        let grainCol = norm < 0 ? "#fcf9f2" : (norm < 0.45 ? "#c4bba9" : "#4f4a43");
        drawClippedLine(x + random(-0.6, 0.6), y1 + 8, x + random(-0.6, 0.6), y2 - 8, "cpencil", grainCol, 0.38, keepFn, 18);
      }
    }

    // 4. Central Vertical Raised Rib / Flute on each column
    for (let dy = 552; dy <= 948; dy += 5) {
      if (keepFn(cx, dy)) {
        // Left highlight of center rib, right shadow of center rib
        brush.set("cpencil", "#fffcf5", 0.5);
        brush.line(cx - 8, dy, cx - 8, dy + 4);
        brush.set("cpencil", "#7d756b", 0.5);
        brush.line(cx + 8, dy, cx + 8, dy + 4);
        brush.set("cpencil", "#b8afa0", 0.35);
        brush.line(cx - 7, dy, cx + 7, dy + 2);
      }
    }

    // Ornate cast-iron crown scroll at top (y=545) and bottom (y=952) of each column
    if (keepFn(cx, 548)) {
      brush.set("cpencil", "#6e675e", 0.55);
      brush.arc(cx, 550, 14, 195, 345);
      brush.set("cpencil", "#fffdf7", 0.45);
      brush.arc(cx, 548, 14, 195, 345);
    }
    if (keepFn(cx, 950)) {
      brush.set("cpencil", "#544e47", 0.55);
      brush.arc(cx, 948, 14, 15, 165);
    }

    // 5. Warm Ginger/Amber Reflected Light & Cast Shadow under the Sleeping Cat (Cols 3..7)
    if (col >= 3 && col <= 7) {
      for (let dx = -30; dx <= 30; dx += 3) {
        let x = cx + dx;
        if (keepFn(x, 525)) {
          // Deep contact shadow directly beneath cat's body/fur
          brush.set("cpencil", "#2b2520", 0.65);
          brush.line(x, 515, x, 534 + random(0, 12));
          // Subtle warm ginger bounce light on the cream paint just below the cat
          if (col >= 4 && col <= 6) {
            brush.set("burnish", "#c97438", 0.38);
            brush.line(x, 530, x, 565 + random(0, 18));
          }
        }
      }
    }

    // 6. Chipped Cream Radiator Paint (Revealing dark cast-iron + rust-ginger halos + 3D bottom lip highlight)
    let chips = getRadiatorChipsForCol(col, cx);
    for (let ch of chips) {
      if (keepFn(ch.x, ch.y)) {
        renderPaintChip(ch.x, ch.y, ch.w, ch.h, ch.rust);
      }
    }

    // If End Column 8: render the ornate curved legs in dark-shaded cream & chipped iron
    if (isEndCol) {
      for (let lx = -40; lx <= 42; lx += 3) {
        if (abs(lx) > 15) {
          let side = lx < 0 ? -1 : 1;
          let xTop = cx + side * 24 + (lx - side * 28) * 0.5;
          let xBot = cx + lx;
          let legCol = (lx < -25 || (lx > 15 && lx < 28)) ? "#dfd6c3" : "#5c564e";
          brush.set("cpencil", legCol, 0.5);
          brush.line(xTop, 965, xBot, 1068);
        }
      }
      // Chipped iron feet tips resting on floorboards
      renderPaintChip(cx - 32, 1055, 18, 16, true);
      renderPaintChip(cx + 34, 1052, 20, 18, true);
    }
  }

  // 7. Right-Side Bleed Valve & Return Pipe (x = 1015..1068)
  // Top brass/aged-copper bleed valve at (1026, 568)
  drawWashedPoly([
    [1014, 556], [1042, 556], [1048, 564], [1048, 576], [1042, 582], [1014, 582]
  ], "#59483b", 230);
  // Warm ginger/brass metallic glint on bleed valve
  brush.set("cpencil", "#d47a34", 0.65);
  brush.line(1015, 561, 1044, 561);
  brush.set("cpencil", "#f7cfa6", 0.55);
  brush.line(1016, 564, 1040, 564);
  brush.set("cpencil", "#29221d", 0.7);
  brush.line(1015, 576, 1045, 576);
  // Subtle rusty mineral drip stain below the bleed valve on Col 8 edge
  for (let dy = 582; dy < 665; dy += 4) {
    brush.set("fineHair", "#b85a25", map(dy, 582, 665, 0.55, 0.15));
    brush.line(1014 + random(-2, 2), dy, 1014 + random(-2, 2), dy + 6);
  }

  // Bottom right return pipe & hex nut (x = 1014..1062, y = 916..1072)
  drawWashedPoly([
    [1014, 918], [1058, 918], [1058, 1072], [1028, 1072], [1028, 952], [1014, 952]
  ], "#6e675e", 225);
  for (let px = 1028; px <= 1058; px += 2.5) {
    let pCol = px < 1038 ? "#e0d7c5" : (px < 1048 ? "#8f877c" : "#38342f");
    brush.set("cpencil", pCol, 0.5);
    brush.line(px, 922, px, 1070);
  }
  renderPaintChip(1036, 932, 16, 14, true);
}

function getRadiatorChipsForCol(col, cx) {
  // Deterministic list of realistic enamel chips along the ribs and crowns
  let list = [];
  if (col === 3) {
    list.push({ x: cx + 8, y: 635, w: 15, h: 24, rust: true });
    list.push({ x: cx - 6, y: 785, w: 12, h: 18, rust: false });
  } else if (col === 4) {
    list.push({ x: cx - 10, y: 572, w: 18, h: 26, rust: true });
    list.push({ x: cx + 6, y: 695, w: 14, h: 34, rust: true });
    list.push({ x: cx - 14, y: 845, w: 16, h: 20, rust: false });
    list.push({ x: cx + 4, y: 928, w: 18, h: 15, rust: true });
  } else if (col === 5) {
    list.push({ x: cx + 10, y: 612, w: 16, h: 28, rust: true });
    list.push({ x: cx - 8, y: 742, w: 20, h: 38, rust: true });
    list.push({ x: cx + 8, y: 882, w: 14, h: 22, rust: false });
  } else if (col === 6) {
    list.push({ x: cx - 12, y: 588, w: 22, h: 30, rust: true });
    list.push({ x: cx - 6, y: 668, w: 15, h: 22, rust: false });
    list.push({ x: cx + 7, y: 805, w: 19, h: 32, rust: true });
    list.push({ x: cx - 9, y: 935, w: 16, h: 18, rust: true });
  } else if (col === 7) {
    list.push({ x: cx - 8, y: 825, w: 21, h: 34, rust: true });
    list.push({ x: cx + 9, y: 912, w: 15, h: 22, rust: false });
  } else if (col === 8) {
    list.push({ x: cx - 10, y: 560, w: 18, h: 25, rust: true });
    list.push({ x: cx + 6, y: 648, w: 22, h: 42, rust: true });
    list.push({ x: cx - 8, y: 765, w: 16, h: 28, rust: true });
    list.push({ x: cx + 10, y: 890, w: 19, h: 26, rust: false });
  }
  return list;
}

function renderPaintChip(cx, cy, w, h, hasRust) {
  // Build jagged polygon for the flaked-off cream paint chip
  let pts = [];
  let steps = 10;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let rMod = 0.7 + noise(cx * 0.1 + i, cy * 0.1) * 0.55;
    pts.push([
      cx + cos(a) * (w * 0.5) * rMod,
      cy + sin(a) * (h * 0.5) * rMod
    ]);
  }

  // 1. Warm rust/ginger oxidation halo staining the surrounding cream paint edge
  if (hasRust) {
    let haloPts = pts.map(p => [
      cx + (p[0] - cx) * 1.32,
      cy + (p[1] - cy) * 1.32 + 2
    ]);
    drawFilledPoly(haloPts, "#c4622b", 115, 0.15, 0.5, 0.1);
  }

  // 2. Dark matte exposed cast-iron interior
  drawWashedPoly(pts, "#292624", 240, 0.05);

  // 3. Textured dark graphite/iron hatching + rust flecks inside the chip
  for (let sy = cy - h * 0.4; sy <= cy + h * 0.4; sy += 2.2) {
    brush.set("fineHair", random() < 0.35 && hasRust ? "#9e4318" : "#171514", 0.55);
    brush.line(cx - w * 0.35, sy, cx + w * 0.35, sy + random(-1, 1));
  }

  // 4. Top recessed shadow lip (thickness of top paint edge casting shadow onto iron)
  brush.set("fineHair", "#0d0c0b", 0.7);
  for (let i = 5; i < 9; i++) {
    let p1 = pts[i % steps];
    let p2 = pts[(i + 1) % steps];
    brush.line(p1[0], p1[1] + 1, p2[0], p2[1] + 1);
  }

  // 5. Crisp bright cream/white highlight along the lower chipped enamel rim (crucial 3D illusion!)
  brush.set("whiskerTip", "#fffdf9", 0.58);
  for (let i = 0; i < 5; i++) {
    let p1 = pts[i];
    let p2 = pts[(i + 1) % steps];
    brush.line(p1[0], p1[1] + 1.2, p2[0], p2[1] + 1.2);
  }
}

// ===========================================================================
// SECTION 3: DRYING SOCK BESIDE THE CAT (COLUMNS 7 & 8, x = 845..1012)
// ===========================================================================
function renderDryingSock(keepFn) {
  // Cast shadow of the hanging sock onto Radiator Columns 7 and 8
  let shadowPts = [
    [852, 520], [998, 515], [1016, 565], [1004, 625],
    [972, 635], [968, 798], [862, 804], [848, 775], [846, 555]
  ];
  drawFilledPoly(shadowPts, "#1d1b18", 175, 0.12, 0.4, 0.2);

  // Sock silhouette: Foot & Heel resting over top of radiator (x=855..1005, y=476..615),
  // Ankle & Ribbed Cuff hanging down in front of Column 7 (x=854..964, y=525..788)
  let sockBodyPts = [
    [858, 502], // left ankle top near cat's paw
    [892, 476], // arch over radiator crown
    [952, 474], // top foot arch
    [996, 492], // toe rounding over back-right
    [1008, 535], // toe tip drooping
    [995, 588], // underside of toe/sole
    [965, 610], // heel pocket curve
    [958, 650], // back of ankle hanging down
    [956, 776], // bottom right cuff corner
    [910, 788], // bottom cuff curve
    [860, 778], // bottom left cuff corner
    [854, 665], // front/left ankle edge
    [852, 558]  // front fold over radiator lip
  ];

  // Base heather-charcoal wool tone
  drawWashedPoly(sockBodyPts, "#4a4744", 242, 0.18);

  // Darker charcoal core shadow on the right/underside of the hanging sock and under heel fold
  let sockShadowPts = [
    [922, 488], [996, 492], [1008, 535], [995, 588],
    [965, 610], [958, 650], [956, 776], [915, 786],
    [912, 620], [935, 540]
  ];
  drawFilledPoly(sockShadowPts, "#282624", 185, 0.12, 0.45, 0.2);

  // Warm ginger/terracotta heel reinforcement patch (x=942..1006, y=500..592)
  let heelPatchPts = [
    [955, 492], [996, 494], [1007, 535], [994, 585],
    [964, 598], [944, 565], [942, 522]
  ];
  drawWashedPoly(heelPatchPts, "#b85220", 225, 0.2);

  // Two Ginger Accent Stripes around the ribbed cuff (Stripe 1: y=704..724, Stripe 2: y=736..754)
  let stripe1Pts = [
    [856, 702], [908, 712], [956, 700],
    [956, 722], [908, 732], [857, 722]
  ];
  let stripe2Pts = [
    [858, 734], [908, 744], [956, 732],
    [956, 752], [908, 762], [859, 752]
  ];
  drawWashedPoly(stripe1Pts, "#cf5e24", 235, 0.15);
  drawWashedPoly(stripe2Pts, "#cf5e24", 235, 0.15);

  // Obsessive Hyperreal Knit Texture:
  // 1. Upper foot & heel pocket (curved knit courses following the 3D volume)
  for (let row = 0; row < 28; row++) {
    let t = row / 27.0;
    let yLeft = lerp(498, 615, t);
    let yMid = lerp(477, 602, t);
    let yRight = lerp(495, 588, t);
    let xLeft = lerp(858, 853, t);
    let xRight = lerp(996, 965, t);

    for (let s = 0; s <= 22; s++) {
      let u = s / 22.0;
      let sx = lerp(xLeft, xRight, u);
      let sy = (1 - u) * (1 - u) * yLeft + 2 * (1 - u) * u * yMid + u * u * yRight;

      let inHeel = (sx > 944 && sy > 495 && sy < 595);
      let lightVal = u < 0.42 ? 1 : (u < 0.72 ? 0 : -1);
      let stitchCol;
      if (inHeel) {
        stitchCol = lightVal > 0 ? "#f08c4b" : (lightVal === 0 ? "#c4551e" : "#6e290b");
      } else {
        stitchCol = lightVal > 0 ? "#9e9890" : (lightVal === 0 ? "#5c5853" : "#292725");
      }

      // Draw tiny V-shaped knit stitch in colored pencil
      brush.set("fineHair", stitchCol, 0.52);
      brush.line(sx - 2, sy - 2.5, sx, sy + 2.5);
      brush.line(sx + 2, sy - 2.5, sx, sy + 2.5);
    }
  }

  // 2. Vertical Ribbed Leg & Cuff (y = 595..785, 16 distinct 3D knit ribs)
  let numRibs = 16;
  for (let r = 0; r < numRibs; r++) {
    let u = r / (numRibs - 1); // 0 (left sunlit edge) to 1 (right shaded edge)
    let xTop = lerp(854, 960, u);
    let xBot = lerp(860, 955, u);

    for (let y = 598; y <= 780; y += 3.2) {
      let v = (y - 598) / (780 - 598);
      let rx = lerp(xTop, xBot, v) + sin(v * 180) * (0.5 - u) * 5;
      let ry = y + sin(u * 180) * 10; // cuff curve

      let inStripe1 = (ry >= 704 && ry <= 725);
      let inStripe2 = (ry >= 736 && ry <= 755);
      let isGinger = inStripe1 || inStripe2;

      // Each rib has a bright left ridge and a recessed purl groove on its right
      let hiCol, midCol, darkCol;
      if (isGinger) {
        hiCol = u < 0.55 ? "#f79c5c" : "#c75b24";
        midCol = u < 0.55 ? "#d96528" : "#9c3e12";
        darkCol = "#4f1c06";
      } else {
        hiCol = u < 0.45 ? "#b8b2a8" : (u < 0.75 ? "#7a756e" : "#4a4743");
        midCol = u < 0.45 ? "#75706a" : "#3d3a37";
        darkCol = "#1c1a19";
      }

      // Left highlight stitch of rib
      brush.set("fineHair", hiCol, 0.5);
      brush.line(rx - 1.8, ry - 1.5, rx - 0.3, ry + 2.0);
      // Right midtone stitch of rib
      brush.set("fineHair", midCol, 0.5);
      brush.line(rx + 1.8, ry - 1.5, rx + 0.3, ry + 2.0);
      // Deep purl valley between ribs
      if (r < numRibs - 1) {
        brush.set("fineHair", darkCol, 0.45);
        brush.line(rx + 3.1, ry - 2, rx + 3.1, ry + 2);
      }
    }
  }

  // Tension fold creases where the sock bends over the front radiator lip (y=515..575)
  for (let c = 0; c < 6; c++) {
    let cy = 522 + c * 9;
    brush.set("cpencil", "#211f1d", 0.55);
    brush.spline([
      [854, cy + 4], [888, cy - 3], [928, cy + 2], [956, cy + 10]
    ], 0.3);
    brush.set("fineHair", "#aba49a", 0.45);
    brush.spline([
      [855, cy + 1.5], [888, cy - 5.5], [926, cy - 0.5]
    ], 0.3);
  }
}

