    [512, 270], // 5: high shoulder blades
    [598, 286], // 6: nape dip
    [632, 298], // 7: base of left ear (viewer's left)
    [628, 258], // 8: left ear outer tip
    [662, 274], // 9: left ear inner slope
    [694, 306], // 10: left temple / forehead
    [734, 302], // 11: crown of head between ears
    [772, 308], // 12: right ear inner base
