function renderRightCat(keepFn) {
  let catPts = getCatSilhouettePts();

  // 1. Base Undercoat Washes on the Right Side of the Cat
  let rightCatPoly = [];
  for (let p of catPts) {
    rightCatPoly.push([max(getBoundaryX(p[1]) - 12, p[0]), p[1]]);
  }
  // Warm agouti grey-taupe undercoat
  drawWashedPoly(rightCatPoly, "#91877b", 235, 0.15);

  // 2. Strategic Warm Ginger / Rufous Accent Zones on the Tabby Cat:
  //    - Nose bridge & forehead blaze
  //    - Warm ginger cheek & ear base patches
  //    - Warm rufous glow on shoulder & foreleg between dark mackerel stripes
  let gingerZones = [
    // Forehead & nose bridge blaze
    { pts: [[714, 338], [754, 338], [752, 446], [716, 446]], col: "#d96d29", op: 215 },
    // Left cheek warm ginger patch
    { pts: [[645, 405], [702, 418], [705, 468], [642, 465]], col: "#d46826", op: 195 },
    // Right cheek warm ginger patch
    { pts: [[762, 418], [822, 402], [818, 462], [760, 466]], col: "#cf6220", op: 195 },
    // Warm ginger glow on shoulder & upper foreleg
    { pts: [[535, 315], [635, 325], [658, 465], [548, 472]], col: "#c96428", op: 165 },
    // Inner ear warm amber-pink glow (left & right ears)
    { pts: [[636, 268], [662, 282], [678, 336], [634, 332]], col: "#cf7446", op: 190 },
    { pts: [[780, 336], [812, 280], [826, 320], [796, 355]], col: "#cf7446", op: 190 },
    // Pale cream/ivory chin, whisker pads, and eye spectacles
    { pts: [[680, 452], [788, 452], [784, 504], [684, 504]], col: "#f2ece1", op: 225 },
    { pts: [[656, 396], [722, 398], [720, 434], [658, 432]], col: "#ebe3d5", op: 210 },
    { pts: [[750, 398], [810, 396], [808, 434], [752, 434]], col: "#ebe3d5", op: 210 }
  ];
  for (let gz of gingerZones) {
    drawFilledPoly(gz.pts, gz.col, gz.op, 0.14, 0.35, 0.2);
  }

  // 3. Dark Charcoal Tabby Stripe Masses (Right Back, Shoulder, Crown & Forelegs)
  let darkStripeZones = [
    // Dorsal spine dark stripe
    [[480, 272], [625, 292], [620, 318], [480, 302]],
    // Mackerel shoulder stripes sweeping down and back
    [[495, 290], [522, 292], [502, 455], [476, 450]],
    [[542, 296], [568, 302], [552, 468], [526, 462]],
    [[585, 312], [612, 322], [608, 478], [582, 468]],
    // Foreleg bracelets (horizontal tabby rings across the draping left paw & tucked right paw)
    [[598, 472], [692, 468], [695, 486], [598, 490]],
    [[602, 502], [698, 500], [698, 516], [604, 518]],
    [[752, 472], [838, 476], [836, 492], [750, 488]]
  ];
  for (let ds of darkStripeZones) {
    let clipped = ds.map(p => [max(getBoundaryX(p[1]), p[0]), p[1]]);
    drawFilledPoly(clipped, "#24211e", 195, 0.1, 0.4, 0.2);
  }

  // 4. OBSESSIVE DIRECTIONAL COLOURED-PENCIL FUR RENDERING
  //    Organized by anatomical pelage flow fields so every single hair follows the 3D musculature!

  // 4A. Mid-back, Shoulder & Flank Fur (x = 450..665, y = 270..515)
  for (let i = 0; i < 1650; i++) {
    let x = random(445, 665);
    let y = random(272, 514);
    if (!keepFn(x, y)) continue;

    // Check if inside cat dorsal/belly bounds at this x
    let topEdge = map(x, 445, 635, 272, 296) - sin(map(x, 445, 635, 30, 160)) * 10;
    if (y < topEdge || y > 515) continue;

    // Pelage angle flows from nape/spine backwards and downwards along the ribs
    let normY = (y - topEdge) / (515 - topEdge);
    let furAngle = lerp(172, 118, normY) + sin(x * 0.04) * 10 + random(-6, 6);
    let furLen = random(11, 22);

    // Mackerel tabby stripe pattern function
    let stripeWave = sin((x + normY * 38) * 3.8 + sin(y * 0.05) * 35);
    let isDarkStripe = (stripeWave > 0.32) || (normY < 0.14);
    let isGingerBand = (!isDarkStripe && stripeWave > -0.25 && x > 515 && normY > 0.22 && normY < 0.82);

    let hairCol;
    if (isDarkStripe) {
      hairCol = random() < 0.65 ? "#1f1d1b" : (random() < 0.5 ? "#38332e" : "#59483b");
    } else if (isGingerBand) {
      hairCol = random() < 0.55 ? "#d96c27" : (random() < 0.6 ? "#f0934d" : "#a84813");
    } else {
      // Silver-agouti ticked fur (pale cream tips over warm grey-taupe base)
      let r = random();
      hairCol = r < 0.35 ? "#e8e0d1" : (r < 0.7 ? "#9c9286" : "#635c54");
    }

    // Backlit sunlit rim along top of spine!
    if (normY < 0.08 && random() < 0.65) {
      hairCol = "#fffcf5";
    }

    brush.set(random() < 0.65 ? "fineHair" : "cpencil", hairCol, random(0.42, 0.78));
    brush.line(
      x, y,
      x + cos(furAngle) * furLen,
      y + sin(furAngle) * furLen
    );
  }

  // 4B. Draping Left Forepaw & Tucked Right Forepaw (x = 575..852, y = 455..562)
  // Shadow directly under the draping left paw on Column 5
  drawFilledPoly([
    [598, 524], [705, 520], [704, 578], [658, 586], [608, 572]
  ], "#1c1917", 195, 0.1, 0.4, 0.2);

  for (let i = 0; i < 680; i++) {
    let x = random(585, 850);
    let y = random(458, 560);
    let inLeftPaw = (x >= 588 && x <= 706 && y >= 458 && y <= 560);
    let inRightPaw = (x >= 742 && x <= 850 && y >= 468 && y <= 518);
    if (!inLeftPaw && !inRightPaw) continue;

    let ang = inLeftPaw ? lerp(110, 75, (x - 588) / 118) : lerp(15, -12, (y - 468) / 50);
    let len = random(8, 15);

    // Tabby leg bars vs warm ginger/cream toe tufts
    let isToeTip = (inLeftPaw && y > 532) || (inRightPaw && x > 822);
    let isLegBar = !isToeTip && (sin(y * 11 + x * 2) > 0.45);
    let col;
    if (isToeTip) {
      col = random() < 0.65 ? "#f2ece1" : "#cfc6b6";
    } else if (isLegBar) {
      col = random() < 0.7 ? "#24211e" : "#4a3d33";
    } else {
      col = random() < 0.45 ? "#d97330" : (random() < 0.5 ? "#bdb3a4" : "#80776c");
    }

    brush.set("fineHair", col, random(0.45, 0.72));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Crisp dark separation lines between the 4 soft toes of the draping left forepaw
  let toeClefts = [
    [[630, 556], [634, 535], [636, 522]],
    [[656, 561], [658, 538], [659, 522]],
    [[681, 556], [681, 536], [680, 522]]
  ];
  for (let tc of toeClefts) {
    brush.set("fineHair", "#1f1c19", 0.75);
    brush.spline(tc, 0.25);
    brush.set("fineHair", "#fffdf9", 0.5);
    brush.line(tc[0][0] - 2.5, tc[0][1] - 2, tc[1][0] - 2.5, tc[1][1]);
  }

  // 4C. Ears (Left Ear x=622..695, Right Ear x=765..838)
  renderCatEars();

  // 4D. Cranium, Forehead Tabby 'M', Cheeks & Facial Fur (x = 632..834, y = 302..502)
  for (let i = 0; i < 1500; i++) {
    let x = random(634, 832);
    let y = random(302, 498);
    // Elliptical head boundary check
    let dx = (x - 734) / 98.0;
    let dy = (y - 398) / 96.0;
    if (dx * dx + dy * dy > 1.05) continue;

    // Facial fur radiates outward from nose bridge (734, 425)
    let angFromNose = atan2(y - 432, x - 734);
    // Adjust angle for natural forehead (upward) and cheek ruff (sweeping outward & down)
    let furAng = angFromNose;
    if (y < 395) {
      furAng = -90 + (x - 734) * 0.45; // sweeping up over crown
    } else if (abs(x - 734) > 38) {
      furAng = (x < 734) ? lerp(195, 135, (y - 390) / 100) : lerp(-15, 45, (y - 390) / 100);
    }

    let furLen = map(dist(x, y, 734, 445), 10, 110, 5.5, 15.0);

    // Facial markings:
    // 1. Classic Tabby 'M' on forehead (y = 335..392)
    let inForeheadM = false;
    if (y > 325 && y < 395 && abs(x - 734) < 58) {
      let mx = (x - 734) / 52.0; // -1 to 1
      let mCurve = 368 - cos(mx * 360) * 18 + abs(mx) * 10;
      if (abs(y - mCurve) < 8.5 || abs(abs(x - 734) - 16) < 4.5 || abs(abs(x - 734) - 42) < 5.5) {
        inForeheadM = true;
      }
    }

    // 2. Dark eyeliner & cheek pencil stripes sweeping from outer eye corners
    let inCheekStripe = (
      (x < 685 && abs((y - 415) - (675 - x) * 0.25) < 5.5) ||
      (x < 690 && abs((y - 438) - (680 - x) * 0.35) < 5.5) ||
      (x > 782 && abs((y - 416) - (x - 792) * 0.25) < 5.5) ||
      (x > 778 && abs((y - 440) - (x - 788) * 0.35) < 5.5)
    );

    // 3. Pale spectacles around eyes & white/cream muzzle/whisker pads
    let distLeftEye = dist(x, y, 692, 414);
    let distRightEye = dist(x, y, 778, 416);
    let inSpectacles = (distLeftEye < 28 || distRightEye < 28);
    let inMuzzle = (abs(x - 734) < 48 && y > 448 && y < 498);

    // 4. Rich ginger blaze on nose bridge and ginger cheek patches
    let inNoseBlaze = (abs(x - 734) < 17 && y > 375 && y < 446);
    let inGingerCheek = (!inCheekStripe && !inSpectacles && y > 395 && y < 468 && abs(x - 734) > 25 && abs(x - 734) < 76);

    let hCol;
    if (inForeheadM || inCheekStripe) {
      hCol = random() < 0.75 ? "#1c1917" : "#3d332c";
    } else if (inMuzzle) {
      hCol = random() < 0.72 ? "#fbf8f2" : "#dfd7c8";
    } else if (inSpectacles) {
      hCol = random() < 0.65 ? "#f5efe4" : "#c9bfb0";
    } else if (inNoseBlaze) {
      hCol = random() < 0.6 ? "#e07128" : (random() < 0.6 ? "#f59d56" : "#b34b12");
    } else if (inGingerCheek) {
      hCol = random() < 0.55 ? "#d66824" : (random() < 0.5 ? "#eda05f" : "#99491d");
    } else {
      let r = random();
      hCol = r < 0.32 ? "#ede5d8" : (r < 0.68 ? "#8f8579" : "#3b3631");
    }

    brush.set("fineHair", hCol, random(0.38, 0.68));
    brush.line(x, y, x + cos(furAng) * furLen, y + sin(furAng) * furLen);
  }

  // 4E. Hyperreal Facial Features: Closed Sleeping Eyes, Terracotta Nose & Whisker Follicles
  renderCatFacialDetails();
}

function renderCatEars() {
  // Left Ear (viewer's left: tip at 628, 258) & Right Ear (viewer's right: tip at 818, 272)
  // Outer dark charcoal-grey rim and dorsal ear fur
  for (let i = 0; i < 240; i++) {
    let t = random();
    // Left ear outer edge
    let lx = lerp(632, 628, t) + random(-3, 14);
    let ly = lerp(318, 258, t) + random(-2, 12);
    let lCol = t > 0.7 ? "#1f1d1b" : (random() < 0.5 ? "#575048" : "#d17336");
    brush.set("fineHair", lCol, 0.5);
    brush.line(lx, ly, lx - 6, ly - 10);

    // Right ear outer edge
    let rx = lerp(828, 818, t) + random(-14, 3);
    let ry = lerp(338, 272, t) + random(-2, 12);
    let rCol = t > 0.7 ? "#1f1d1b" : (random() < 0.5 ? "#575048" : "#d17336");
    brush.set("fineHair", rCol, 0.5);
    brush.line(rx, ry, rx + 7, ry - 9);
  }

  // Inner ear conch shading + delicate long cream ear-furnishing tufts
  for (let i = 0; i < 65; i++) {
    let t = i / 64.0;
    // Left ear furnishings fanning from inner base across conch
    let lx1 = lerp(672, 646, t);
    let ly1 = lerp(332, 282, t);
    let lLen = random(14, 26) * sin(t * 180);
    brush.set("fineHair", random() < 0.7 ? "#faf5eb" : "#e3bfa3", 0.48);
    brush.line(lx1, ly1, lx1 - lLen * 0.85, ly1 - lLen * 0.35);

    // Right ear furnishings
    let rx1 = lerp(780, 810, t);
    let ry1 = lerp(338, 288, t);
    let rLen = random(14, 26) * sin(t * 180);
    brush.set("fineHair", random() < 0.7 ? "#faf5eb" : "#e3bfa3", 0.48);
    brush.line(rx1, ry1, rx1 + rLen * 0.85, ry1 - rLen * 0.35);
  }
}

