// ===========================================================================
// SECTION 5: RAGGED BOUNDARY FRINGE (MID-WORK PENCIL STROKES OVER LINE ART)
// ===========================================================================
function renderBoundaryFringe() {
  // Along x = getBoundaryX(y) ± 45, draw energetic, slightly looser colored-pencil
  // hatching strokes so the eye sees the coloring process actively advancing from right to left!
  for (let y = 55; y < 1140; y += 3.2) {
    let bx = getBoundaryX(y);
    let inCat = (y >= 272 && y <= 516);
    let inRad = (y > 516 && y <= 985);

    // Choose pigment appropriate to the zone being colored
    let strokeCol;
    let weight = random(0.45, 0.78);
    if (inCat) {
      let r = random();
      strokeCol = r < 0.38 ? "#d46a26" : (r < 0.72 ? "#36312c" : "#8c8275");
    } else if (inRad) {
      strokeCol = random() < 0.6 ? "#dfd6c3" : (random() < 0.5 ? "#7d756b" : "#b85c28");
    } else {
      strokeCol = random() < 0.6 ? "#bab2a4" : "#877f73";
    }

    // Diagonal working strokes jutting slightly left of the boundary onto the white paper
    let xStart = bx + random(8, 42);
    let xEnd = bx - random(4, 34);
    let angOffset = inCat ? random(-8, 12) : random(-18, -8);

    brush.set("cpencil", strokeCol, weight);
    brush.line(xStart, y, xEnd, y + angOffset);
  }

  // Partially colored tabby stripe on the cat's mid-back right at the boundary (x ≈ 455..510)
  // where the black outline is only half-filled with ginger and charcoal pencil!
  for (let i = 0; i < 95; i++) {
    let y = random(285, 495);
    let bx = getBoundaryX(y);
    let x = bx - random(0, 38);
    let col = (sin(x * 0.12 + y * 0.04) > 0) ? "#2e2925" : "#d96e28";
    brush.set("cpencil", col, 0.52);
    brush.line(x, y, x + random(14, 28), y + random(-5, 8));
  }
}

// ===========================================================================
// SECTION 6: LEFT-SIDE COLOURING-BOOK LINE ART (UNIFORM BLACK PEN OUTLINES)
// ===========================================================================
function renderLeftColoringBookOutlines(keepFn) {
  const penCol = "#171615";
  const penW = 1.05;
  const innerPenW = 0.82;

  // 1. Architectural Background Outlines (Left Side: Wall Panel, Chair Rail, Baseboard, Floorboards)
  // Upper recessed wainscoting panel box (x = 95..530, y = 52..182)
  drawClippedLine(95, 52, 530, 52, "coloringPen", penCol, innerPenW, keepFn);
  drawClippedLine(95, 182, 530, 182, "coloringPen", penCol, innerPenW, keepFn);
  drawClippedLine(95, 52, 95, 182, "coloringPen", penCol, innerPenW, keepFn);
  drawClippedLine(112, 68, 515, 68, "coloringPen", penCol, 0.65, keepFn);
  drawClippedLine(112, 166, 515, 166, "coloringPen", penCol, 0.65, keepFn);
  drawClippedLine(112, 68, 112, 166, "coloringPen", penCol, 0.65, keepFn);

  // Horizontal chair-rail molding lines (y = 220, 232, 252, 258)
  for (let my of [220, 232, 252, 258]) {
    drawClippedLine(45, my, 620, my, "coloringPen", penCol, my === 220 || my === 252 ? penW : 0.72, keepFn, 28);
