function isInsideCatTail(x, y) {
  if (y < 466 || y > 732 || x < 172 || x > 262) return false;
  let t = (y - 468) / (728 - 468);
  let centerX = lerp(204, 238, t) - sin(t * 170) * 14;
  let halfW = lerp(23, 18, t) * (t > 0.9 ? sin(map(t, 0.9, 1, 90, 15)) : 1);
  return abs(x - centerX) <= halfW;
}

