// Hyperreal Gee's Bend Patched Rural Shed Wall
// Rendered with p5.js v2 + p5.brush in WEBGL

function lerp2D(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

// Bilinear interpolation inside a crooked quadrilateral [TL, TR, BR, BL]
function qPt(q, u, v) {
  let top = lerp2D(q[0], q[1], u);
  let bot = lerp2D(q[3], q[2], u);
  return lerp2D(top, bot, v);
}

// Extract a sub-quadrilateral [u0..u1, v0..v1] from parent quad q
function qSub(q, u0, v0, u1, v1) {
  return [
    qPt(q, u0, v0),
    qPt(q, u1, v0),
    qPt(q, u1, v1),
    qPt(q, u0, v1)
  ];
}

// Draw a filled/washed quad safely using beginShape/vertex/endShape
function fillQuad(q, col, alphaVal, useWatercolor = false, bleedVal = 0.08) {
  brush.noStroke();
  brush.noHatch();
  if (useWatercolor) {
    brush.fill(col, alphaVal);
    brush.fillBleed(bleedVal, "in");
    brush.fillTexture(0.45, 0.3);
  } else {
    brush.wash(col, alphaVal);
  }
  brush.beginShape(0);
  brush.vertex(q[0][0], q[0][1]);
  brush.vertex(q[1][0], q[1][1]);
  brush.vertex(q[2][0], q[2][1]);
  brush.vertex(q[3][0], q[3][1]);
  brush.endShape(true);
  brush.noFill();
  brush.noWash();
}

// Hatch inside a crooked quad
function hatchQuad(q, brushName, col, weight, dist, angleDeg, opts = { rand: 0.04 }) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angleDeg, opts);
  brush.beginShape(0);
  brush.vertex(q[0][0], q[0][1]);
  brush.vertex(q[1][0], q[1][1]);
  brush.vertex(q[2][0], q[2][1]);
  brush.vertex(q[3][0], q[3][1]);
  brush.endShape(true);
  brush.noHatch();
}

// Draw a line in normalized quad coordinates (u0,v0) -> (u1,v1)
function qLine(q, u0, v0, u1, v1, brushName, col, weight) {
  let p0 = qPt(q, u0, v0);
  let p1 = qPt(q, u1, v1);
  brush.set(brushName, col, weight);
  brush.line(p0[0], p0[1], p1[0], p1[1]);
}

// Draw a spline through normalized quad coordinates [[u,v,pressure], ...]
function qSpline(q, uvPts, brushName, col, weight, curv = 0.5) {
  if (uvPts.length < 2) return;
  let pts = [];
  for (let i = 0; i < uvPts.length; i++) {
    let p = qPt(q, uvPts[i][0], uvPts[i][1]);
    pts.push([p[0], p[1], uvPts[i][2] !== undefined ? uvPts[i][2] : 1]);
  }
  brush.set(brushName, col, weight);
  brush.spline(pts, curv);
}

// Cast a realistic daylight drop shadow from edges of an overlapping patch
// Daylight comes from upper-left, so bottom and right edges cast strong shadows
function drawOverlapShadow(q, edges, maxOffset = 9) {
  let steps = 4;
  for (let s = 1; s <= steps; s++) {
    let frac = s / steps;
    let off = maxOffset * frac;
    let w = map(s, 1, steps, 1.3, 0.5);
    let col = s <= 2 ? "#140D08" : "#2B1D13";
    let bName = s <= 2 ? "charcoal" : "2B";

    if (edges.includes("bottom")) {
      brush.set(bName, col, w);
      brush.line(q[3][0] + off * 0.4, q[3][1] + off, q[2][0] + off * 0.6, q[2][1] + off);
    }
    if (edges.includes("right")) {
      brush.set(bName, col, w);
      brush.line(q[1][0] + off * 0.85, q[1][1] + off * 0.4, q[2][0] + off * 0.85, q[2][1] + off * 0.8);
    }
    if (edges.includes("left")) {
      brush.set("2B", "#1A110B", 0.65 * (1 - frac * 0.5));
      brush.line(q[0][0] - s * 0.8, q[0][1], q[3][0] - s * 0.8, q[3][1]);
    }
    if (edges.includes("top")) {
      brush.set("2B", "#1A110B", 0.65 * (1 - frac * 0.5));
      brush.line(q[0][0], q[0][1] - s * 0.8, q[1][0], q[1][1] - s * 0.8);
    }
  }
}

// Render an individual hyperreal nail head (rusted iron, galvanized roofing, or square cut)
function drawNail(x, y, r = 3.5, type = "rust", streakLen = 0) {
  // Weeping rust or tannin streak below nail
  if (streakLen > 0) {
    let sw = Math.max(0.3, r * 0.16);
    brush.set("cpencil", type === "galv" ? "#8E623E" : "#54220E", sw);
    brush.line(x + random(-0.8, 0.8), y + r * 0.5, x + random(-1.5, 1.5), y + streakLen);
    if (streakLen > 12) {
      brush.set("rotring", "#331408", sw * 0.7);
      brush.line(x, y + r * 0.4, x + random(-0.6, 0.6), y + streakLen * 0.55);
    }
  }

  // Wood dimple / shadow under nail head
  let sx = x + r * 0.48;
  let sy = y + r * 0.58;
  brush.set("charcoal", "#120A06", r * 0.28);
  brush.line(sx - r * 0.45, sy, sx + r * 0.45, sy);
  brush.line(sx, sy - r * 0.45, sx, sy + r * 0.45);

  // Nail head body
  let headCol = type === "galv" ? "#8C8D86" : (type === "bright" ? "#B0AAA0" : "#3E1D10");
  let rimCol = type === "galv" ? "#5A5C57" : "#241008";
  brush.set("marker", headCol, r * 0.36);
  brush.line(x - r * 0.35, y, x + r * 0.35, y);

  brush.set("rotring", rimCol, 0.45);
  brush.circle(x, y, r * 0.75, 0.15);

  // Lead washer ring for roofing nails
  if (type === "galv") {
    brush.set("pen", "#6D706A", 0.38);
    brush.circle(x, y, r * 1.15, 0.1);
    if (random() < 0.65) {
      brush.set("cpencil", "#9E461A", 0.4);
      brush.arc(x, y, r * 0.9, 20, 190);
    }
  }

  // Crisp upper-left daylight specular glint
  let glintCol = type === "rust" ? "#D99B72" : "#FBF6EC";
  brush.set("pen", glintCol, 0.48);
  brush.line(x - r * 0.38, y - r * 0.32, x + r * 0.08, y - r * 0.42);
}

// ============================================================================
// MATERIAL 1: FADED BARN-RED & WEATHERED WOOD BOARDS
// ============================================================================
function renderBarnBoards(q, numBoards, isVertical, opts = {}) {
  let baseRed = opts.redPalette || ["#8A2B19", "#9E3722", "#732011", "#B04A33", "#C2624A"];
  let underCol = opts.underCol || "#C49B58"; // warm ochre primer / sun-baked pine
  let woodLight = opts.woodLight || "#CBB69B";
  let woodMid = opts.woodMid || "#9E866C";
  let woodDark = opts.woodDark || "#5E4936";
  let paintCoverage = opts.coverage !== undefined ? opts.coverage : 0.68;
  let seedOff = opts.seedOff || random(100, 900);
  let hasSawMarks = opts.sawMarks || false;
  let secondCoat = opts.secondCoat || null; // e.g. peeling cream over barn red

  for (let b = 0; b < numBoards; b++) {
    let t0 = b / numBoards;
    let t1 = (b + 1) / numBoards;
    // Slight gap for dark interior shed shadow between boards
    let gap = 0.008;
    let b0 = t0 + (b === 0 ? 0 : gap);
    let b1 = t1 - (b === numBoards - 1 ? 0 : gap);

    let bQuad = isVertical
      ? qSub(q, b0, 0, b1, 1)
      : qSub(q, 0, b0, 1, b1);

    // Slightly warp individual board ends for crooked Gee's Bend charm
    bQuad[0][0] += random(-2.5, 2.5);
    bQuad[1][1] += random(-2.5, 2.5);
    bQuad[2][0] += random(-2.5, 2.5);

    // 1. Base bare weathered wood wash
    fillQuad(bQuad, b % 2 === 0 ? woodLight : "#BFA88C", 225, false);
    fillQuad(bQuad, woodMid, 95, true, 0.06);

    // 2. Wood grain & radial growth checks along plank length
    let grainLines = Math.floor(isVertical
      ? (dist(bQuad[0][0], bQuad[0][1], bQuad[1][0], bQuad[1][1]) * 0.55)
      : (dist(bQuad[0][0], bQuad[0][1], bQuad[3][0], bQuad[3][1]) * 0.55));
    grainLines = constrain(grainLines, 18, 52);

    // Optional knot in this board
    let hasKnot = random() < 0.55;
    let ku = random(0.25, 0.75);
    let kv = random(0.22, 0.78);

    for (let g = 0; g <= grainLines; g++) {
      let gf = g / grainLines;
      let pts = [];
      let steps = 14;
      for (let s = 0; s <= steps; s++) {
        let sf = s / steps;
        let u = isVertical ? gf : sf;
        let v = isVertical ? sf : gf;

        // Deflect grain around knot
        if (hasKnot) {
          let du = u - ku;
          let dv = v - kv;
          let d = Math.sqrt(du * du + dv * dv * 2.5);
          if (d < 0.22 && d > 0.001) {
            let pushAmt = (0.22 - d) * 0.28 * Math.exp(-d * 8);
            if (isVertical) u = constrain(u + (du >= 0 ? pushAmt : -pushAmt), 0.01, 0.99);
            else v = constrain(v + (dv >= 0 ? pushAmt : -pushAmt), 0.01, 0.99);
          }
        }

        let wobble = (noise(seedOff + b * 13 + gf * 4, sf * 3) - 0.5) * 0.03;
        if (isVertical) u = constrain(u + wobble, 0.01, 0.99);
        else v = constrain(v + wobble, 0.01, 0.99);

        pts.push([u, v, 0.7 + 0.5 * noise(g, s)]);
      }
      let gCol = g % 3 === 0 ? woodDark : (g % 2 === 0 ? "#7A624B" : "#DFCBB2");
      let gW = g % 4 === 0 ? 0.48 : 0.32;
      qSpline(bQuad, pts, g % 3 === 0 ? "rotring" : "cpencil", gCol, gW, 0.4);
    }

    // Draw knot core if present
    if (hasKnot) {
      let kp = qPt(bQuad, ku, kv);
      brush.set("charcoal", "#2A180D", 0.9);
      brush.circle(kp[0], kp[1], random(5, 9), 0.25);
      brush.set("rotring", "#140A05", 0.5);
      brush.circle(kp[0], kp[1], random(2.5, 4.5), 0.2);
      // Radial check crack through knot
      if (isVertical) {
        qLine(bQuad, ku, Math.max(0.02, kv - 0.12), ku, Math.min(0.98, kv + 0.14), "rotring", "#170C06", 0.55);
      } else {
        qLine(bQuad, Math.max(0.02, ku - 0.12), kv, Math.min(0.98, ku + 0.14), kv, "rotring", "#170C06", 0.55);
      }
    }

    // 3. Peeling Barn-Red Paint Stratigraphy (and optional cream topcoat)
    let strips = grainLines;
    for (let st = 0; st < strips; st++) {
      let f0 = (st + 0.5) / strips;
      let segs = 26;
      for (let sg = 0; sg < segs; sg++) {
        let s0 = sg / segs;
        let s1 = (sg + 1) / segs;
        let sm = (s0 + s1) * 0.5;

        // Coherent noise field for paint survival (wears more at board edges & ends)
        let edgeFade = Math.min(f0, 1 - f0) * 3.8;
        edgeFade = constrain(edgeFade, 0.15, 1.0);
        let endFade = Math.min(sm, 1 - sm) * 4.5;
        endFade = constrain(endFade, 0.25, 1.0);

        let nVal = noise(seedOff + b * 31 + f0 * 5.5, sm * 6.5);
        let threshold = (1.0 - paintCoverage) / (edgeFade * 0.65 + endFade * 0.35);

        let uA = isVertical ? f0 : s0;
        let vA = isVertical ? s0 : f0;
        let uB = isVertical ? f0 : s1;
        let vB = isVertical ? s1 : f0;

        if (nVal > threshold) {
          // Paint survives here!
          let colIdx = Math.floor(noise(seedOff + f0 * 9, sm * 9) * baseRed.length) % baseRed.length;
          let pCol = baseRed[colIdx];
          qLine(bQuad, uA, vA, uB, vB, "marker", pCol, 1.15);
          if ((st + sg) % 2 === 0) {
            qLine(bQuad, uA, vA, uB, vB, "cpencil", baseRed[(colIdx + 1) % baseRed.length], 0.65);
          }

          // Optional second coat (peeling warm cream over barn red)
          if (secondCoat && noise(seedOff + 99 + f0 * 7, sm * 8) > 0.44) {
            qLine(bQuad, uA, vA, uB, vB, "marker", secondCoat, 1.05);
            // Curled cream flake edge
            if (noise(seedOff + 99 + f0 * 7, (sm + 0.04) * 8) <= 0.44) {
              qLine(bQuad, uA, vA, uB, vB, "rotring", "#4A180D", 0.45);
              qLine(bQuad, uA, vA, uB, vB, "pen", "#FFF8EB", 0.42);
            }
          }
        } else if (nVal > threshold - 0.085) {
          // Peeling edge zone! Expose ochre primer + cast sharp 3D flake shadow & sunlit curl
          qLine(bQuad, uA, vA, uB, vB, "cpencil", underCol, 0.75);
          let offF = isVertical ? 0.008 : 0;
          let offS = isVertical ? 0 : 0.008;
          // Dark shadow under lifted paint flake
          qLine(bQuad, uA + offF, vA + offS, uB + offF, vB + offS, "rotring", "#260D07", 0.48);
          // Bright sunlit edge on curled paint lip
          qLine(bQuad, uA - offF * 0.6, vA - offS * 0.6, uB - offF * 0.6, vB - offS * 0.6, "pen", "#E89B7E", 0.42);
        }
      }
    }

    // 4. Rough-sawn circular saw kerf marks & deep wood checks
    if (hasSawMarks) {
      for (let k = 0; k < 14; k++) {
        let kvPos = random(0.06, 0.94);
        let u0 = isVertical ? 0.05 : kvPos;
        let v0 = isVertical ? kvPos : 0.05;
        let u1 = isVertical ? 0.95 : kvPos + random(-0.03, 0.03);
        let v1 = isVertical ? kvPos + random(-0.03, 0.03) : 0.95;
        qLine(bQuad, u0, v0, u1, v1, "2B", "#4A1B10", 0.35);
      }
    }

    // Deep weather checks (splits) at board ends
    for (let c = 0; c < 5; c++) {
      let cf = random(0.12, 0.88);
      let cLen = random(0.06, 0.19);
      let atStart = random() < 0.5;
      let sA = atStart ? 0.0 : 1.0 - cLen;
      let sB = atStart ? cLen : 1.0;
      if (isVertical) {
        qLine(bQuad, cf, sA, cf, sB, "rotring", "#1A0D07", 0.58);
        qLine(bQuad, cf + 0.006, sA, cf + 0.006, sB, "pen", "#DFC6A8", 0.35);
      } else {
        qLine(bQuad, sA, cf, sB, cf, "rotring", "#1A0D07", 0.58);
        qLine(bQuad, sA, cf + 0.006, sB, cf + 0.006, "pen", "#DFC6A8", 0.35);
      }
    }

    // 5. Board edge bevel highlights & deep gap shadows
    if (isVertical) {
      // Left edge sunlit bevel, right edge shadow into gap
      qLine(bQuad, 0.01, 0, 0.01, 1, "pen", "#E8B89A", 0.45);
      qLine(bQuad, 0.99, 0, 0.99, 1, "rotring", "#160B06", 0.85);
      qLine(bQuad, 0, 0.005, 1, 0.005, "pen", "#DFC2A6", 0.4);
      qLine(bQuad, 0, 0.995, 1, 0.995, "rotring", "#1A0D07", 0.75);
    } else {
      // Top edge sunlit bevel, bottom edge shadow into gap
      qLine(bQuad, 0, 0.015, 1, 0.015, "pen", "#EBD0B5", 0.48);
      qLine(bQuad, 0, 0.985, 1, 0.985, "rotring", "#140A05", 0.9);
      qLine(bQuad, 0.005, 0, 0.005, 1, "pen", "#DFC2A6", 0.4);
      qLine(bQuad, 0.995, 0, 0.995, 1, "rotring", "#1A0D07", 0.75);
    }

    // 6. Nails in rows across the board
    let nailRows = opts.nailRows || [0.06, 0.52, 0.94];
    for (let nr of nailRows) {
      for (let np of [0.24, 0.76]) {
        let nu = isVertical ? np + random(-0.04, 0.04) : nr + random(-0.015, 0.015);
        let nv = isVertical ? nr + random(-0.015, 0.015) : np + random(-0.04, 0.04);
        let nPt = qPt(bQuad, nu, nv);
        drawNail(nPt[0], nPt[1], random(2.8, 3.6), "rust", random(8, 24));
      }
    }
  }
}

// ============================================================================
// MATERIAL 2: CORRUGATED GALVANIZED & RUSTED TIN
// ============================================================================
function renderCorrugatedTin(q, numRibs, isHorizontal, rustLevel = 0.45, spangleLevel = 0.75) {
  let seedOff = random(100, 900);

  // Base metallic midtone wash
  fillQuad(q, "#B5ADA0", 235, false);

  // Subdivide into sinusoidal corrugation ribs
  let subBands = 7; // 7 shading facets per wave cycle for smooth 3D cylindrical volume
  let bandColors = [
    "#EFE8D8", // 0: Bright warm daylight crest
    "#FAF5E8", // 1: Specular ridge highlight
    "#C8C0B2", // 2: Upper sunlit slope
    "#8E918A", // 3: Mid-slope transition
    "#4B4740", // 4: Deep shadow trough
    "#6B5B4B", // 5: Warm bounced-light core in trough
    "#A6A196"  // 6: Rising slope toward next crest
  ];

  for (let r = 0; r < numRibs; r++) {
    let r0 = r / numRibs;
    let r1 = (r + 1) / numRibs;

    for (let sb = 0; sb < subBands; sb++) {
      let b0 = r0 + (r1 - r0) * (sb / subBands);
      let b1 = r0 + (r1 - r0) * ((sb + 1) / subBands);
      let stripQ = isHorizontal ? qSub(q, 0, b0, 1, b1) : qSub(q, b0, 0, b1, 1);

      fillQuad(stripQ, bandColors[sb], 220, false);

      // Fine longitudinal brushed metal lines along rib
      let numStrokes = 3;
      for (let k = 0; k < numStrokes; k++) {
        let f = (k + 0.5) / numStrokes;
        let bm = b0 + (b1 - b0) * f;
        let bName = (sb === 1) ? "pen" : (sb === 4 ? "charcoal" : "cpencil");
        let w = (sb === 1 || sb === 4) ? 0.55 : 0.42;
        if (isHorizontal) {
          qLine(q, 0, bm, 1, bm, bName, bandColors[sb], w);
        } else {
          qLine(q, bm, 0, bm, 1, bName, bandColors[sb], w);
        }
      }
    }
  }

  // Crystalline Galvanized Spangle Facets (angular zinc crystals catching light)
  let spangleCount = Math.floor(260 * spangleLevel);
  let spangleCols = ["#F7F2E6", "#6D736E", "#DFD3BE", "#848A84", "#FAF6EE", "#585D59"];
  for (let i = 0; i < spangleCount; i++) {
    let u = random(0.02, 0.98);
    let v = random(0.02, 0.98);
    // Check if this spot is covered by heavy rust
    let rNoise = noise(seedOff + u * 4.2, v * 4.2);
    if (rNoise < 1.0 - rustLevel * 0.75) {
      let center = qPt(q, u, v);
      let sCol = random(spangleCols);
      let rad = random(3.5, 9.5);
      let a0 = random(360);
      // Draw tiny angular crystal shard / feathery zinc star
      brush.set("marker", sCol, random(0.45, 0.85));
      let x1 = center[0] + cos(a0) * rad;
      let y1 = center[1] + sin(a0) * rad;
      let x2 = center[0] + cos(a0 + 115) * rad * 0.7;
      let y2 = center[1] + sin(a0 + 115) * rad * 0.7;
      brush.line(center[0], center[1], x1, y1);
      brush.line(center[0], center[1], x2, y2);
      brush.set("pen", sCol === "#F7F2E6" ? "#FFFFFF" : "#4E524E", 0.3);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Oxidized Rust Patina & Water Run Streaks
  let rustCols = ["#5E200B", "#8F3412", "#BA4E1A", "#D47228", "#752A0F"];
  let gridU = 38;
  let gridV = 38;
  for (let iu = 0; iu < gridU; iu++) {
    for (let iv = 0; iv < gridV; iv++) {
      let u = (iu + 0.5) / gridU;
      let v = (iv + 0.5) / gridV;
      // Rust congregates near seams, bottom edges, and noise clusters
      let edgeBias = (1.0 - Math.min(u, 1 - u, v, 1 - v) * 3.5) * 0.22;
      let nVal = noise(seedOff + u * 4.5, v * 4.5) + Math.max(0, edgeBias);
      if (nVal > (1.0 - rustLevel * 0.82)) {
        let p = qPt(q, u, v);
        let intensity = map(nVal, 1.0 - rustLevel * 0.82, 1.0, 0, 1, true);
        let cIdx = Math.floor(intensity * (rustCols.length - 0.01));
        let rCol = rustCols[rustCols.length - 1 - cIdx];
        brush.set(intensity > 0.55 ? "charcoal" : "cpencil", rCol, map(intensity, 0, 1, 0.5, 1.25));
        let len = random(6, 16);
        // Rust follows corrugation slightly + drips downward with gravity
        let ang = isHorizontal ? random(-12, 12) : random(78, 102);
        brush.line(p[0], p[1], p[0] + cos(ang) * len, p[1] + sin(ang) * len);
      }
    }
  }

  // Chalky white-zinc oxidation streaks
  for (let z = 0; z < 35; z++) {
    let u = random(0.05, 0.95);
    let v = random(0.05, 0.85);
    let p = qPt(q, u, v);
    brush.set("cpencil", "#E6DFD3", 0.35);
    brush.line(p[0], p[1], p[0] + random(-2, 2), p[1] + random(8, 25));
  }

  // Sheared metal perimeter & wavy cut end shadows
  for (let r = 0; r < numRibs; r++) {
    let rm = (r + 0.15) / numRibs; // Crest of each rib
    // Nails along two purlin/stud lines
    for (let nl of [0.07, 0.52, 0.93]) {
      if (random() < 0.82) {
        let nu = isHorizontal ? nl + random(-0.01, 0.01) : rm;
        let nv = isHorizontal ? rm : nl + random(-0.01, 0.01);
        let np = qPt(q, nu, nv);
        drawNail(np[0], np[1], 3.8, random() < 0.6 ? "galv" : "rust", random(6, 20));
      }
    }
  }

  // Crisp cut-metal rim highlight on top/left & dark sheared edge on bottom/right
  qLine(q, 0, 0, 1, 0, "pen", "#FAF4E8", 0.55);
  qLine(q, 0, 0, 0, 1, "pen", "#EFE8D8", 0.5);
  qLine(q, 0, 1, 1, 1, "rotring", "#241911", 0.75);
  qLine(q, 1, 0, 1, 1, "rotring", "#241911", 0.75);
}

// ============================================================================
// MATERIAL 3: SALVAGED TEAL FARMHOUSE DOOR PANEL (HERO CENTERPIECE)
// ============================================================================
function renderTealDoorPanel(q) {
  let tealPalette = ["#245E5E", "#2F7370", "#3E8983", "#529E96", "#1B4848", "#6EB5AC"];
  let primerCol = "#C99238"; // Warm mustard-ochre undercoat
  let cypressWood = "#735F4C";
  let seedOff = 512.7;

  // Helper to paint a door component (stile, rail, or recessed panel) with grain & peeling teal
  function paintDoorPiece(subQ, isVertGrain, peelBias = 0.0) {
    // 1. Bare wood & mustard primer base
    fillQuad(subQ, cypressWood, 235, false);
    fillQuad(subQ, primerCol, 155, true, 0.07);

    // 2. Wood grain & checks
    let lines = isVertGrain ? 24 : 18;
    for (let i = 0; i <= lines; i++) {
      let f = i / lines;
      let col = i % 3 === 0 ? "#47382A" : (i % 2 === 0 ? "#917A62" : "#B89A67");
      if (isVertGrain) qLine(subQ, f, 0, f, 1, "cpencil", col, 0.36);
      else qLine(subQ, 0, f, 1, f, "cpencil", col, 0.36);
    }

    // 3. Peeling vintage teal paint islands with 3D curled flake edges
    let strips = isVertGrain ? 28 : 22;
    let segs = 24;
    for (let st = 0; st < strips; st++) {
      let f = (st + 0.5) / strips;
      for (let sg = 0; sg < segs; sg++) {
        let s0 = sg / segs;
        let s1 = (sg + 1) / segs;
        let sm = (s0 + s1) * 0.5;

        let uA = isVertGrain ? f : s0;
        let vA = isVertGrain ? s0 : f;
        let uB = isVertGrain ? f : s1;
        let vB = isVertGrain ? s1 : f;

        let pA = qPt(subQ, uA, vA);
        let nVal = noise(seedOff + pA[0] * 0.022, pA[1] * 0.022);
        let thresh = 0.33 + peelBias;

        if (nVal > thresh) {
          let cIdx = Math.floor(noise(pA[0] * 0.04, pA[1] * 0.04) * tealPalette.length) % tealPalette.length;
          qLine(subQ, uA, vA, uB, vB, "marker", tealPalette[cIdx], 1.15);
          if ((st + sg) % 2 === 0) {
            qLine(subQ, uA, vA, uB, vB, "cpencil", tealPalette[(cIdx + 2) % tealPalette.length], 0.6);
          }
          // Alligatoring / craquelure cracks in old enamel
          if (random() < 0.14) {
            qLine(subQ, uA, vA, uB, vB, "rotring", "#133333", 0.32);
          }
        } else if (nVal > thresh - 0.085) {
          // Curled paint flake boundary exposing mustard ochre primer
          qLine(subQ, uA, vA, uB, vB, "marker", "#D69E42", 0.8);
          let du = isVertGrain ? 0.012 : 0;
          let dv = isVertGrain ? 0 : 0.012;
          // Dark shadow under curled teal flake
          qLine(subQ, uA + du, vA + dv, uB + du, vB + dv, "rotring", "#0E2626", 0.5);
          // Bright sunlit seafoam-white rim on curled flake
          qLine(subQ, uA - du * 0.7, vA - dv * 0.7, uB - du * 0.7, vB - dv * 0.7, "pen", "#B8EAE2", 0.45);
        }
      }
    }
  }

  // Door Carpentry Proportions:
  // Stiles: Left [0..0.19], Right [0.81..1.0]
  // Rails: Top [0..0.13], Middle Lock Rail [0.45..0.59], Bottom [0.85..1.0]
  // Recessed Panels: Upper [0.19..0.81, 0.13..0.45], Lower [0.19..0.81, 0.59..0.85]
  let topRail = qSub(q, 0.19, 0.0, 0.81, 0.13);
  let midRail = qSub(q, 0.19, 0.45, 0.81, 0.59);
  let botRail = qSub(q, 0.19, 0.85, 0.81, 1.0);
  let leftStile = qSub(q, 0.0, 0.0, 0.19, 1.0);
  let rightStile = qSub(q, 0.81, 0.0, 1.0, 1.0);
  let upPanel = qSub(q, 0.22, 0.155, 0.78, 0.425);
  let lowPanel = qSub(q, 0.22, 0.615, 0.78, 0.825);

  // Paint rails (horizontal grain), stiles (vertical grain), and recessed panels (vertical grain)
  paintDoorPiece(topRail, false, 0.04);
  paintDoorPiece(midRail, false, 0.02);
  paintDoorPiece(botRail, false, 0.08);
  paintDoorPiece(leftStile, true, 0.03);
  paintDoorPiece(rightStile, true, 0.05);
  paintDoorPiece(upPanel, true, -0.03);
  paintDoorPiece(lowPanel, true, 0.01);

  // Draw the 3D Recessed Molding Bevels around Upper and Lower Panels!
  // Under upper-left daylight:
  // Top & Left bevels are in DEEP SHADOW; Bottom & Right bevels catch BRIGHT SUNLIGHT
  let panels = [
    { outer: [0.19, 0.13, 0.81, 0.45], inner: [0.23, 0.16, 0.77, 0.42] },
    { outer: [0.19, 0.59, 0.81, 0.85], inner: [0.23, 0.62, 0.77, 0.82] }
  ];

  for (let p of panels) {
    let [ou0, ov0, ou1, ov1] = p.outer;
    let [iu0, iv0, iu1, iv1] = p.inner;

    let pTL_o = qPt(q, ou0, ov0), pTR_o = qPt(q, ou1, ov0), pBR_o = qPt(q, ou1, ov1), pBL_o = qPt(q, ou0, ov1);
    let pTL_i = qPt(q, iu0, iv0), pTR_i = qPt(q, iu1, iv0), pBR_i = qPt(q, iu1, iv1), pBL_i = qPt(q, iu0, iv1);

    // Top shadow bevel
    fillQuad([pTL_o, pTR_o, pTR_i, pTL_i], "#112E2E", 215, false);
    // Left shadow bevel
    fillQuad([pTL_o, pTL_i, pBL_i, pBL_o], "#173A3A", 205, false);
    // Bottom sunlit bevel
    fillQuad([pBL_i, pBR_i, pBR_o, pBL_o], "#8FD1C6", 195, false);
    // Right sunlit bevel
    fillQuad([pTR_i, pTR_o, pBR_o, pBR_i], "#78BFB4", 185, false);

    // Crisp molding shadow & highlight hairlines
    qLine(q, ou0, ov0, ou1, ov0, "rotring", "#091A1A", 0.85);
    qLine(q, ou0, ov0, ou0, ov1, "rotring", "#091A1A", 0.85);
    qLine(q, iu0, iv0, iu1, iv0, "charcoal", "#0D2424", 0.95);
    qLine(q, iu0, iv0, iu0, iv1, "charcoal", "#0D2424", 0.95);

    qLine(q, iu0, iv1, iu1, iv1, "pen", "#D4F5EE", 0.65);
    qLine(q, iu1, iv0, iu1, iv1, "pen", "#C2EDE4", 0.6);
    qLine(q, ou0, ov1, ou1, ov1, "rotring", "#1A3D3B", 0.55);
    qLine(q, ou1, ov0, ou1, ov1, "rotring", "#1A3D3B", 0.55);

    // Miter lines at the 4 molding corners
    brush.set("rotring", "#0E2626", 0.5);
    brush.line(pTL_o[0], pTL_o[1], pTL_i[0], pTL_i[1]);
    brush.line(pTR_o[0], pTR_o[1], pTR_i[0], pTR_i[1]);
    brush.line(pBR_o[0], pBR_o[1], pBR_i[0], pBR_i[1]);
    brush.line(pBL_o[0], pBL_o[1], pBL_i[0], pBL_i[1]);
  }

  // Carpentry mortise-and-tenon joinery hairlines between stiles and rails
  for (let rv of [0.0, 0.13, 0.45, 0.59, 0.85, 1.0]) {
    if (rv > 0 && rv < 1) {
      qLine(q, 0.19, rv - 0.02, 0.19, rv + 0.02, "rotring", "#102929", 0.7);
      qLine(q, 0.81, rv - 0.02, 0.81, rv + 0.02, "rotring", "#102929", 0.7);
    }
  }
  qLine(q, 0.19, 0.0, 0.19, 0.13, "rotring", "#0E2828", 0.75);
  qLine(q, 0.19, 0.45, 0.19, 0.59, "rotring", "#0E2828", 0.75);
  qLine(q, 0.19, 0.85, 0.19, 1.0, "rotring", "#0E2828", 0.75);
  qLine(q, 0.81, 0.0, 0.81, 0.13, "rotring", "#0E2828", 0.75);
  qLine(q, 0.81, 0.45, 0.81, 0.59, "rotring", "#0E2828", 0.75);
  qLine(q, 0.81, 0.85, 0.81, 1.0, "rotring", "#0E2828", 0.75);

  // Vintage Rusted Cast-Iron Keyhole Escutcheon & Doorknob Spindle Hole on Left Stile
  let escQ = qSub(q, 0.055, 0.465, 0.135, 0.575);
  drawOverlapShadow(escQ, ["bottom", "right"], 4);
  fillQuad(escQ, "#3B1C10", 240, false);
  fillQuad(escQ, "#6E2E14", 140, true, 0.05);
  qLine(escQ, 0, 0, 1, 0, "pen", "#C97D52", 0.5);
  qLine(escQ, 0, 0, 0, 1, "pen", "#C97D52", 0.5);
  // Doorknob hole (top) & keyhole slot (bottom)
  let knobPt = qPt(escQ, 0.5, 0.3);
  let keyPt = qPt(escQ, 0.5, 0.68);
  brush.set("charcoal", "#0C0705", 1.3);
  brush.circle(knobPt[0], knobPt[1], 4.5, 0.1);
  brush.circle(keyPt[0], keyPt[1], 2.5, 0.1);
  brush.set("rotring", "#0C0705", 1.2);
  brush.line(keyPt[0], keyPt[1], keyPt[0], keyPt[1] + 7);
  // Rust stain weeping down from escutcheon plate
  for (let rs = 0; rs < 6; rs++) {
    let ru = map(rs, 0, 5, 0.06, 0.13);
    qLine(q, ru, 0.575, ru + random(-0.005, 0.005), 0.66 + random(0, 0.06), "cpencil", "#6B2810", 0.48);
  }

  // Perimeter nails holding the salvaged door panel flat against the shed wall
  for (let nv of [0.04, 0.28, 0.52, 0.74, 0.96]) {
    let pL = qPt(q, 0.035, nv);
    let pR = qPt(q, 0.965, nv);
    drawNail(pL[0], pL[1], 3.8, "rust", 18);
    drawNail(pR[0], pR[1], 3.8, "rust", 18);
  }
  for (let nu of [0.32, 0.5, 0.68]) {
    let pT = qPt(q, nu, 0.035);
    let pB = qPt(q, nu, 0.965);
    drawNail(pT[0], pT[1], 3.6, "rust", 15);
    drawNail(pB[0], pB[1], 3.6, "rust", 12);
  }

  // Outer door frame highlight & shadow rim
  qLine(q, 0, 0, 1, 0, "pen", "#B8EAE0", 0.65);
  qLine(q, 0, 0, 0, 1, "pen", "#9EDBD0", 0.6);
  qLine(q, 0, 1, 1, 1, "rotring", "#0D2121", 0.9);
  qLine(q, 1, 0, 1, 1, "rotring", "#0D2121", 0.9);
}

// ============================================================================
// MATERIAL 4: WEATHERED ROTARY-CUT PLYWOOD WITH GRAIN CHECKS & DELAMINATION
// ============================================================================
function renderWeatheredPlywood(q, hasDelamCorner = false) {
  let seedOff = random(200, 800);

  // 1. Warm golden-amber & raw sienna plywood base
  fillQuad(q, "#D6B485", 240, false);
  fillQuad(q, "#B5844E", 110, true, 0.08);

  // 2. Rotary-peeled "Cathedral" swirling topological contour grain
  let cols = 58;
  let rows = 58;
  for (let iv = 0; iv < rows; iv++) {
    let v0 = iv / rows;
    let v1 = (iv + 1) / rows;
    for (let iu = 0; iu < cols; iu++) {
      let u = (iu + 0.5) / cols;
      // Skip top-right corner if delaminated
      if (hasDelamCorner && (u - 0.62) > (v0 * 1.15)) continue;

      // Swirling cathedral noise field
      let n = noise(seedOff + u * 3.4 + sin(v0 * 180) * 0.25, v0 * 2.2);
      // Create rhythmic concentric growth ring bands
      let ring = (n * 9.0) % 1.0;
      if (ring < 0.38) {
        let gCol = ring < 0.16 ? "#784D28" : "#9E6D3E";
        let w = ring < 0.16 ? 0.65 : 0.48;
        qLine(q, u, v0, u + (noise(u * 8, v0 * 8) - 0.5) * 0.015, v1, "cpencil", gCol, w);
      } else if (ring > 0.78) {
        qLine(q, u, v0, u, v1, "pen", "#DFB888", 0.38);
      }
    }
  }

  // 3. The Signature of Weathered Plywood: Hundreds of Vertical Face-Veneer Checks!
  let checkCount = 155;
  for (let c = 0; c < checkCount; c++) {
    let u = random(0.02, 0.98);
    let vStart = random(0.01, 0.88);
    let vLen = random(0.05, 0.18);
    let vEnd = Math.min(0.99, vStart + vLen);

    if (hasDelamCorner && (u - 0.60) > (vStart * 1.15)) continue;

    // Dark split crevice
    qLine(q, u, vStart, u, vEnd, "rotring", "#2E1B0E", random(0.32, 0.55));
    // Sunlit microscopic lip beside the check
    qLine(q, u + 0.004, vStart, u + 0.004, vEnd, "pen", "#F0DAC0", 0.3);
  }

  // 4. Optional Delaminated Top-Right Corner (peeled top ply exposing perpendicular dark glue core!)
  if (hasDelamCorner) {
    let tearPtsUV = [
      [0.62, 0.0],
      [0.68, 0.09],
      [0.77, 0.16],
      [0.86, 0.25],
      [1.0, 0.33]
    ];
    let delamPoly = [
      qPt(q, 0.62, 0.0),
      qPt(q, 1.0, 0.0),
      qPt(q, 1.0, 0.33),
      qPt(q, 0.77, 0.16)
    ];
    fillQuad(delamPoly, "#4D321C", 245, false);

    // Horizontal cross-band core grain & dark phenolic glue lines in the exposed corner
    for (let cv = 0.01; cv < 0.32; cv += 0.016) {
      let uStart = 0.62 + (cv / 0.33) * 0.38;
      qLine(q, uStart, cv, 0.99, cv, "charcoal", cv % 0.032 < 0.016 ? "#2B190C" : "#6E492B", 0.55);
    }

    // Jagged torn veneer edge with shadow and bright splintered wood lip
    for (let i = 0; i < tearPtsUV.length - 1; i++) {
      let [u0, v0] = tearPtsUV[i];
      let [u1, v1] = tearPtsUV[i + 1];
      qLine(q, u0 + 0.008, v0 - 0.006, u1 + 0.008, v1 - 0.006, "charcoal", "#170C05", 0.9);
      qLine(q, u0, v0, u1, v1, "rotring", "#2A160B", 0.6);
      qLine(q, u0 - 0.005, v0 + 0.005, u1 - 0.005, v1 + 0.005, "pen", "#F5E2C6", 0.55);
    }
  }

  // 5. Water staining at bottom edge & perimeter nails
  for (let st = 0; st < 40; st++) {
    let u = random(0.02, 0.98);
    let h = random(0.05, 0.18);
    qLine(q, u, 1.0 - h, u, 1.0, "cpencil", "#543B26", 0.5);
  }

  for (let t = 0.08; t <= 0.92; t += 0.21) {
    let pL = qPt(q, 0.04, t);
    let pR = qPt(q, 0.96, t);
    let pB = qPt(q, t, 0.95);
    drawNail(pL[0], pL[1], 3.1, "rust", 12);
    if (!(hasDelamCorner && t < 0.35)) drawNail(pR[0], pR[1], 3.1, "rust", 12);
    drawNail(pB[0], pB[1], 3.1, "rust", 6);
  }

  qLine(q, 0, 0, 1, 0, "pen", "#F0DEC4", 0.5);
  qLine(q, 0, 0, 0, 1, "pen", "#EAD4B6", 0.5);
  qLine(q, 0, 1, 1, 1, "rotring", "#21130A", 0.8);
  qLine(q, 1, 0, 1, 1, "rotring", "#21130A", 0.8);
}

// ============================================================================
// MATERIAL 5: VINTAGE LITHOGRAPHED METAL FEED-SACK SIGN STRIP
// ============================================================================
function renderFeedSackSign(q) {
  // 1. Warm golden-saffron baked enamel ground
  fillQuad(q, "#E4B236", 245, false);
  fillQuad(q, "#D19620", 110, true, 0.06);

  // Cream upper band for feed-sack checkerboard border
  let topBand = qSub(q, 0, 0, 1, 0.24);
  fillQuad(topBand, "#F0E2C4", 235, false);

  // Lower crimson banner strip
  let botBand = qSub(q, 0, 0.78, 1, 1.0);
  fillQuad(botBand, "#9E2516", 235, false);

  // 2. Classic Feed-Sack Checkerboard / Sawtooth Border along top edge
  let numChecks = 16;
  for (let c = 0; c < numChecks; c++) {
    let u0 = c / numChecks;
    let u1 = (c + 1) / numChecks;
    // Two rows of alternating barn-red & deep charcoal-blue/warm-umber squares
    for (let row = 0; row < 2; row++) {
      if ((c + row) % 2 === 0) {
        let cq = qSub(q, u0, row * 0.11, u1, (row + 1) * 0.11);
        fillQuad(cq, row === 0 ? "#A62818" : "#291B14", 225, false);
      }
    }
  }
  qLine(q, 0, 0.24, 1, 0.24, "rotring", "#26160E", 0.65);
  qLine(q, 0, 0.78, 1, 0.78, "pen", "#F5E8CE", 0.55);

  // 3. Bold Embossed Block Typography: "SUN-GOLD" (cropped/sheared like salvaged sign tin)
  // Helper to draw thick vintage block strokes in quad UV space
  function signStroke(u0, v0, u1, v1, w = 2.1) {
    // Cream 3D emboss highlight offset
    qLine(q, u0 - 0.004, v0 - 0.008, u1 - 0.004, v1 - 0.008, "pen", "#FAF0D7", 0.65);
    // Crimson drop-shade offset
    qLine(q, u0 + 0.006, v0 + 0.012, u1 + 0.006, v1 + 0.012, "marker", "#9C2414", w * 0.75);
    // Deep warm espresso-black letter body
    qLine(q, u0, v0, u1, v1, "marker", "#24150E", w);
    qLine(q, u0, v0, u1, v1, "rotring", "#1A0E08", 0.55);
  }

  let yt = 0.33, ym = 0.51, yb = 0.70;
  // 'S' (0.06..0.14)
  signStroke(0.14, yt, 0.06, yt);
  signStroke(0.06, yt, 0.06, ym);
  signStroke(0.06, ym, 0.14, ym);
  signStroke(0.14, ym, 0.14, yb);
  signStroke(0.14, yb, 0.06, yb);

  // 'U' (0.18..0.26)
  signStroke(0.18, yt, 0.18, yb);
  signStroke(0.18, yb, 0.26, yb);
  signStroke(0.26, yt, 0.26, yb);

  // 'N' (0.30..0.39)
  signStroke(0.30, yb, 0.30, yt);
  signStroke(0.30, yt, 0.39, yb);
  signStroke(0.39, yb, 0.39, yt);

  // '-' (0.42..0.47)
  signStroke(0.42, ym, 0.47, ym, 1.8);

  // 'G' (0.50..0.59)
  signStroke(0.59, yt, 0.50, yt);
  signStroke(0.50, yt, 0.50, yb);
  signStroke(0.50, yb, 0.59, yb);
  signStroke(0.59, yb, 0.59, ym);
  signStroke(0.54, ym, 0.59, ym);

  // 'O' (0.63..0.72)
  signStroke(0.63, yt, 0.72, yt);
  signStroke(0.72, yt, 0.72, yb);
  signStroke(0.72, yb, 0.63, yb);
  signStroke(0.63, yb, 0.63, yt);

  // 'L' (0.76..0.83)
  signStroke(0.76, yt, 0.76, yb);
  signStroke(0.76, yb, 0.83, yb);

  // 'D' (0.86..0.95)
  signStroke(0.86, yt, 0.86, yb);
  signStroke(0.86, yt, 0.93, yt + 0.04);
  signStroke(0.93, yt + 0.04, 0.93, yb - 0.04);
  signStroke(0.93, yb - 0.04, 0.86, yb);

  // Cropped small sub-text along the bottom red banner ("100 LBS. LAYING MASH")
  for (let tx = 0.08; tx < 0.92; tx += 0.028) {
    if (Math.abs(tx - 0.32) > 0.02 && Math.abs(tx - 0.64) > 0.02) {
      qLine(q, tx, 0.84, tx, 0.95, "pen", "#F5E6C8", 0.55);
      if (random() < 0.6) qLine(q, tx, 0.84, tx + 0.014, 0.84, "pen", "#F5E6C8", 0.45);
    }
  }

  // 4. Enamel Chipped Spots, Diagonal Crease & Rust Blooms
  // Diagonal bend crease across the metal sign
  qLine(q, 0.38, 0.0, 0.54, 1.0, "charcoal", "#4A1D0B", 0.75);
  qLine(q, 0.385, 0.0, 0.545, 1.0, "pen", "#FFF3D6", 0.55);

  // Chipped porcelain/enamel patches with dark iron core & rust halo
  let chips = [
    [0.12, 0.42, 7], [0.35, 0.62, 9], [0.58, 0.26, 8],
    [0.74, 0.55, 11], [0.89, 0.82, 8], [0.22, 0.14, 6], [0.46, 0.86, 7]
  ];
  for (let [cu, cv, cr] of chips) {
    let cp = qPt(q, cu, cv);
    brush.set("marker", "#7A280E", cr * 0.25);
    brush.line(cp[0] - cr * 0.5, cp[1], cp[0] + cr * 0.5, cp[1]);
    brush.set("charcoal", "#361408", cr * 0.18);
    brush.line(cp[0] - cr * 0.3, cp[1], cp[0] + cr * 0.3, cp[1]);
    brush.set("pen", "#FFF5DE", 0.4);
    brush.arc(cp[0], cp[1], cr * 0.65, 180, 350);
  }

  // Surface scratches & warm dust patina
  for (let sc = 0; sc < 32; sc++) {
    let u0 = random(0.03, 0.95);
    let v0 = random(0.05, 0.95);
    qLine(q, u0, v0, u0 + random(-0.08, 0.08), v0 + random(-0.08, 0.08), "cpencil", "#8C3A16", 0.35);
  }

  // Perimeter nails & bullet/puncture dimple
  for (let nu of [0.05, 0.28, 0.52, 0.76, 0.95]) {
    let ptT = qPt(q, nu, 0.06);
    let ptB = qPt(q, nu, 0.92);
    drawNail(ptT[0], ptT[1], 3.3, "rust", 14);
    drawNail(ptB[0], ptB[1], 3.3, "rust", 10);
  }

  qLine(q, 0, 0, 1, 0, "pen", "#FFF6E0", 0.6);
  qLine(q, 0, 1, 1, 1, "rotring", "#2B1108", 0.85);
}

// ============================================================================
// MATERIAL 6: TAR-PAPER FELT & PINE LATH BATTEN LADDER (GEE'S BEND MOTIF)
// ============================================================================
function renderTarPaperAndBattens(q, numBattens = 3) {
  // 1. Sun-baked warm charcoal-brown asphalt felt base
  fillQuad(q, "#332A24", 245, false);
  fillQuad(q, "#4A3D34", 120, true, 0.08);

  // Fine mineral granule texture & horizontal felt fiber lines
  hatchQuad(q, "cpencil", "#241D18", 0.45, 5, 2, { rand: 0.08 });
  hatchQuad(q, "cpencil", "#5E5044", 0.38, 7, 178, { rand: 0.1 });

  for (let s = 0; s < 90; s++) {
    let p = qPt(q, random(0.03, 0.97), random(0.03, 0.97));
    brush.set("spray", s % 2 === 0 ? "#7A6B5C" : "#1C1511", random(0.4, 0.75));
    brush.line(p[0], p[1], p[0] + random(-6, 6), p[1] + random(-3, 3));
  }

  // Diagonal tear/crease in the tar paper
  qLine(q, 0.15, 0.0, 0.65, 1.0, "charcoal", "#16100C", 0.85);
  qLine(q, 0.16, 0.0, 0.66, 1.0, "cpencil", "#786858", 0.45);

  // 2. Crooked Horizontal Unpainted Pine Lath Strips (Gee's Bend Rhythm!)
  for (let b = 0; b < numBattens; b++) {
    let vCenter = map(b, 0, numBattens - 1, 0.20, 0.82) + random(-0.02, 0.02);
    let halfH = 0.068;
    let tiltL = random(-0.025, 0.025);
    let tiltR = random(-0.025, 0.025);

    let bQ = [
      qPt(q, 0.02, vCenter - halfH + tiltL),
      qPt(q, 0.98, vCenter - halfH + tiltR),
      qPt(q, 0.98, vCenter + halfH + tiltR),
      qPt(q, 0.02, vCenter + halfH + tiltL)
    ];

    // Crisp drop shadow onto dark tar paper
    drawOverlapShadow(bQ, ["bottom", "right"], 7);

    // Warm sun-bleached pine lath
    fillQuad(bQ, "#D8BA8E", 240, false);
    for (let g = 0; g <= 8; g++) {
      let gf = g / 8;
      qLine(bQ, 0, gf, 1, gf, "cpencil", g % 2 === 0 ? "#9E7A50" : "#EFE0C6", 0.42);
    }
    qLine(bQ, 0, 0.04, 1, 0.04, "pen", "#FAF0DC", 0.55);
    qLine(bQ, 0, 0.96, 1, 0.96, "rotring", "#24150A", 0.7);

    // Nails securing the lath strip
    for (let nu of [0.10, 0.50, 0.88]) {
      let np = qPt(bQ, nu, 0.5);
      drawNail(np[0], np[1], 3.2, "rust", 8);
    }
  }
}

// ============================================================================
// MATERIAL 7: FLAT HIGH-SPANGLE GALVANIZED FLASHING SHEET
// ============================================================================
function renderGalvanizedFlashing(q) {
  fillQuad(q, "#C9C2B4", 240, false);
  fillQuad(q, "#DFD8C8", 130, true, 0.07);

  // Subtle diagonal oil-canning sheet metal wave (3D light & shadow modulation)
  for (let i = 0; i < 45; i++) {
    let f = i / 44;
    let wave = sin(f * 360 * 1.5);
    let col = wave > 0.2 ? "#F2ECE0" : (wave < -0.2 ? "#7C807A" : "#B2ACA0");
    qLine(q, 0, f, 1, constrain(f + 0.12, 0, 1), "marker", col, 1.3);
  }

  // Dense Large Crystalline Zinc Spangle Facets
  let facetCols = ["#FBF7EC", "#646B66", "#E2D6C0", "#878E88", "#4D534F", "#EFE7D6"];
  for (let s = 0; s < 220; s++) {
    let u = random(0.03, 0.97);
    let v = random(0.03, 0.97);
    let p = qPt(q, u, v);
    let r = random(5, 13);
    let a = random(360);
    let c = random(facetCols);
    brush.set("marker", c, random(0.6, 1.1));
    brush.line(p[0], p[1], p[0] + cos(a) * r, p[1] + sin(a) * r);
    brush.line(p[0], p[1], p[0] + cos(a + 70) * r * 0.75, p[1] + sin(a + 70) * r * 0.75);
    brush.set("pen", c === "#FBF7EC" ? "#FFFFFF" : "#3E4340", 0.32);
    brush.line(p[0] + cos(a) * r, p[1] + sin(a) * r, p[0] + cos(a + 70) * r * 0.75, p[1] + sin(a + 70) * r * 0.75);
  }

  // Faintly stenciled mill-stamp mark: "26 GA - USS GALV"
  let stCol = "#525854";
  for (let dx = 0; dx < 9; dx++) {
    let u0 = 0.18 + dx * 0.068;
    qLine(q, u0, 0.46, u0 + 0.038, 0.46, "rotring", stCol, 0.42);
    qLine(q, u0, 0.46, u0, 0.53, "rotring", stCol, 0.42);
    if (dx % 2 === 0) qLine(q, u0, 0.53, u0 + 0.038, 0.53, "rotring", stCol, 0.42);
    if (dx % 3 !== 0) qLine(q, u0 + 0.038, 0.46, u0 + 0.038, 0.53, "rotring", stCol, 0.42);
  }

  // Crease & rust spots around perimeter roofing nails
  qLine(q, 0.0, 0.34, 1.0, 0.28, "rotring", "#494D49", 0.5);
  qLine(q, 0.0, 0.346, 1.0, 0.286, "pen", "#FFFDF7", 0.55);

  for (let t = 0.07; t <= 0.93; t += 0.14) {
    let pL = qPt(q, 0.05, t);
    let pR = qPt(q, 0.95, t);
    drawNail(pL[0], pL[1], 3.4, t % 0.28 < 0.14 ? "galv" : "rust", 14);
    drawNail(pR[0], pR[1], 3.4, "galv", 10);
  }
  for (let u = 0.18; u <= 0.84; u += 0.22) {
    let pT = qPt(q, u, 0.05);
    let pB = qPt(q, u, 0.95);
    drawNail(pT[0], pT[1], 3.4, "galv", 12);
    drawNail(pB[0], pB[1], 3.4, "rust", 8);
  }

  qLine(q, 0, 0, 1, 0, "pen", "#FFFDF8", 0.65);
  qLine(q, 0, 0, 0, 1, "pen", "#F7F2E6", 0.6);
  qLine(q, 0, 1, 1, 1, "rotring", "#2B2620", 0.85);
}

// ============================================================================
// MAIN SETUP & DRAW
// ============================================================================
async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);
