        let ny = row / field[0].length;
        let pourAngle = 58 + 34 * Math.sin(ny * 4.2 + nx * 2.1);
        let coilSwirl = 48 * Math.cos((nx - 0.54) * 5.2 - (ny - 0.72) * 4.4);
        field[col][row] = pourAngle + coilSwirl;
      }
    }
    return field;
  });
}

