// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPolyShape(pts, curvature = 0.3, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function makeEllipsePts(cx, cy, rx, ry, rotDeg = 0, numPts = 28, jitter = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < numPts; i++) {
    let a = (i / numPts) * 360;
    let rMod = 1 + (jitter > 0 ? random(-jitter, jitter) : 0);
    let lx = rx * rMod * cos(a);
    let ly = ry * rMod * sin(a);
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function makeSweepRibbon(spinePts, halfWidths) {
  let n = spinePts.length;
  let tangents = [];
  let normals = [];

  for (let i = 0; i < n; i++) {
    let pPrev = spinePts[max(0, i - 1)];
    let pNext = spinePts[min(n - 1, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = Math.hypot(dx, dy) || 1;
    let tx = dx / len;
    let ty = dy / len;
    tangents.push([tx, ty]);
    // Normal pointing toward lower-left / right depending on flow
    normals.push([-ty, tx]);
  }

  return {
    spine: spinePts,
    widths: halfWidths,
    tangents,
    normals,
    length: n,
    pt(idx, u) {
      let i = constrain(Math.floor(idx), 0, n - 1);
      let c = spinePts[i];
      let nm = normals[i];
      let w = halfWidths[i];
      return [c[0] + nm[0] * w * u, c[1] + nm[1] * w * u];
    }
  };
}

function getRibbonStripPts(ribbon, iStart, iEnd, uMinFn, uMaxFn, step = 1) {
  let pts = [];
  let s = max(0, Math.floor(iStart));
  let e = min(ribbon.length - 1, Math.floor(iEnd));
  if (e <= s) return pts;

  for (let i = s; i <= e; i += step) {
    let t = (i - s) / (e - s);
    pts.push(ribbon.pt(i, uMinFn(t, i)));
  }
  for (let i = e; i >= s; i -= step) {
    let t = (i - s) / (e - s);
    pts.push(ribbon.pt(i, uMaxFn(t, i)));
  }
  return pts;
}

