  ];

  for (let i = 0; i < 68; i++) {
    let col = fieldColors[i % fieldColors.length];
    let bName = i % 3 === 0 ? "cpencil" : (i % 3 === 1 ? "2B" : "charcoal");
    let wt = random(0.45, 1.15);
    brush.set(bName, col, wt);
    // Concentrate around the diagonal pour & coil corridor
    let t = random(0.05, 0.95);
    let bx = lerp(180, 780, t) + random(-240, 240);
    let by = lerp(160, 980, t) + random(-180, 180);
    brush.flowLine(bx, by, random(70, 210), random(-25, 85));
  }

  resetBrushState();
}

