// ============================================================================
// 3. HYPERREAL WOODEN HONEY DIPPER (UPPER LEFT, OFF-KILTER)
// ============================================================================

function drawHyperrealDipper() {
  resetBrushState();

  // Dipper local coordinate system:
  // Enters from upper-left (-40, 102) along angle alpha = 25.5 degrees
  const x0 = -30;
  const y0 = 105;
  const alpha = 25.5;
  const tx = cos(alpha);
  const ty = sin(alpha);
  const nx = -sin(alpha); // points down-left
  const ny = cos(alpha);

  function dPt(s, n) {
    return [x0 + s * tx + n * nx, y0 + s * ty + n * ny];
  }

  // --- A. TURNED WOODEN HANDLE SHAFT (s = 0 to 275) ---
  let shaftSpine = [];
  let shaftWidths = [];
  const shaftSteps = 22;
  for (let i = 0; i <= shaftSteps; i++) {
    let t = i / shaftSteps;
    let s = lerp(-20, 278, t);
    shaftSpine.push(dPt(s, 0));
    // Taper down then flare at neck collar around s = 255
    let w = 24 - 7 * sin(t * 150) + (t > 0.82 ? 12 * sin(((t - 0.82) / 0.18) * 180) : 0);
    shaftWidths.push(w);
  }
  let shaftRib = makeSweepRibbon(shaftSpine, shaftWidths);

  // Base opaque wood wash
  brush.wash(PALETTE.woodMid, 235);
  drawPolyShape(
    getRibbonStripPts(shaftRib, 0, shaftSteps, () => -1, () => 1),
    0.25,
    true
  );
  resetBrushState();

  // Warm lit wood core (upper half, n < 0)
  brush.fill(PALETTE.woodLight, 155);
  brush.fillBleed(0.08, "in");
  drawPolyShape(
    getRibbonStripPts(shaftRib, 0, shaftSteps, () => -0.88, () => 0.05),
    0.25,
    true
  );

  // Deep burnt umber shadow underside (lower half, n > 0)
  brush.fill(PALETTE.woodDark, 185);
  brush.fillBleed(0.1, "in");
  drawPolyShape(
    getRibbonStripPts(shaftRib, 0, shaftSteps, () => 0.18, () => 1.0),
    0.25,
    true
  );

  // Cool skylight reflection along the upper edge of the turned wood
  brush.fill(PALETTE.windowCyan, 130);
  brush.fillBleed(0.05, "in");
  drawPolyShape(
    getRibbonStripPts(shaftRib, 0, shaftSteps, () => -0.95, () => -0.58),
    0.25,
    true
  );
  resetBrushState();

  // Fine wood grain lines & cross-contour turning marks on handle
  for (let g = -0.85; g <= 0.85; g += 0.17) {
    let col = g < -0.3 ? PALETTE.woodLight : (g > 0.25 ? PALETTE.burntUmber : PALETTE.woodWarm);
    brush.set("2B", col, 0.55);
    let grainPts = [];
    for (let i = 0; i <= shaftSteps; i += 2) {
      let jitter = 0.06 * sin(i * 45 + g * 200);
      grainPts.push(shaftRib.pt(i, g + jitter));
    }
    brush.spline(grainPts, 0.4);
  }

  // --- B. GROOVED HONEY-DIPPER BARREL HEAD (s = 282 to 510) ---
  // 6 turned wooden ribs separated by deep honey-filled slots
  const ribs = [
    { s: 294, r: 50, thick: 22, honeyHang: 8 },
    { s: 332, r: 68, thick: 24, honeyHang: 22 },
    { s: 372, r: 78, thick: 25, honeyHang: 38 },
    { s: 412, r: 78, thick: 25, honeyHang: 42 },
    { s: 452, r: 67, thick: 24, honeyHang: 26 },
    { s: 488, r: 46, thick: 20, honeyHang: 10 }
  ];

  // Central wooden core spindle inside the slots
  let corePts = [
    dPt(280, -24),
    dPt(502, -22),
    dPt(502, 28),
    dPt(280, 28)
  ];
  brush.wash(PALETTE.darkUmber, 245);
  drawPolyShape(corePts, 0.15, true);
  resetBrushState();

  // Render each rib back-to-front (painter's order along s)
  for (let idx = 0; idx < ribs.length; idx++) {
    let rb = ribs[idx];
    let sBack = rb.s - rb.thick * 0.5;
    let sFront = rb.s + rb.thick * 0.5;
    let perspRx = rb.r * 0.36; // foreshortened ellipse semi-axis along T
    let perspRy = rb.r;        // full radius along N

    // 1. Deep slot shadow behind the rib
    if (idx > 0) {
      let prevS = ribs[idx - 1].s + ribs[idx - 1].thick * 0.5;
      let slotMid = (prevS + sBack) * 0.5;
      let slotCenter = dPt(slotMid, 4);
      let slotR = (ribs[idx - 1].r + rb.r) * 0.48;
      // Dark amber-umber trapped honey in the slot
      brush.wash(PALETTE.mahogany, 230);
      drawPolyShape(makeEllipsePts(slotCenter[0], slotCenter[1], slotR * 0.38, slotR * 0.96, alpha, 24), 0.25, true);
      // Glowing saffron subsurface light at the top & bottom of the honey bridge
      brush.fill(PALETTE.amberGlow, 160);
      brush.fillBleed(0.1, "in");
      let glowCenter = dPt(slotMid, slotR * 0.55);
      drawPolyShape(makeEllipsePts(glowCenter[0], glowCenter[1], slotR * 0.28, slotR * 0.42, alpha, 20), 0.3, true);
      resetBrushState();
    }

    // 2. Cylindrical rim of the wooden disc (connecting sBack to sFront)
    let rimPts = [];
    const rimSamples = 14;
    for (let i = 0; i <= rimSamples; i++) {
      let a = map(i, 0, rimSamples, -90, 90);
      let nOff = sin(a) * perspRy;
      let sOff = -cos(a) * perspRx;
      rimPts.push(dPt(sBack + sOff, nOff));
    }
    for (let i = rimSamples; i >= 0; i--) {
      let a = map(i, 0, rimSamples, -90, 90);
      let nOff = sin(a) * perspRy;
      let sOff = cos(a) * perspRx;
      rimPts.push(dPt(sFront + sOff, nOff));
    }

    // Base warm wood wash on the rib cylinder
    brush.wash(PALETTE.woodWarm, 240);
    drawPolyShape(rimPts, 0.2, true);
    resetBrushState();

    // Lit upper half of the wooden rib (saffron-warmed wood)
    let upperRimPts = [
      dPt(sBack, -perspRy * 0.98),
      dPt(sFront, -perspRy * 0.98),
      dPt(sFront + perspRx * 0.5, -perspRy * 0.15),
      dPt(sBack - perspRx * 0.5, -perspRy * 0.15)
    ];
    brush.fill(PALETTE.woodLight, 175);
    brush.fillBleed(0.08, "in");
    drawPolyShape(upperRimPts, 0.25, true);

    // Dark burnt-umber core shadow on the lower half of the rib
    let lowerRimPts = [
      dPt(sBack - perspRx * 0.4, perspRy * 0.1),
      dPt(sFront + perspRx * 0.4, perspRy * 0.1),
      dPt(sFront, perspRy * 0.98),
      dPt(sBack, perspRy * 0.98)
    ];
    brush.fill(PALETTE.darkUmber, 195);
    brush.fillBleed(0.1, "in");
    drawPolyShape(lowerRimPts, 0.25, true);
    resetBrushState();

    // Front flat face of the wooden disc (foreshortened ellipse at sFront)
    let frontCenter = dPt(sFront, 0);
    let frontFacePts = makeEllipsePts(frontCenter[0], frontCenter[1], perspRx, perspRy, alpha, 28);
    brush.wash(PALETTE.woodMid, 215);
    drawPolyShape(frontFacePts, 0.25, true);
    resetBrushState();

    // Wood grain & lathe rings on the front face
    brush.set("2B", PALETTE.burntUmber, 0.6);
    drawPolyShape(frontFacePts, 0.25, true);
    resetBrushState();

    // 3. GLOSSY HONEY ENVELOPE CLINGING & DRIPPING FROM THIS RIB
    // On the lower side (n > 0), viscous honey swells into a glowing amber lobe
    let lobePts = [];
    for (let i = 0; i <= 24; i++) {
      let a = (i / 24) * 360;
      let sLocal = cos(a) * (perspRx + 7);
      let nLocal = sin(a) * (perspRy + 5);
      // Bulge downward toward the dripping stream
      if (sin(a) > 0) {
        nLocal += rb.honeyHang * Math.pow(sin(a), 1.6);
        sLocal *= 1 + 0.22 * sin(a);
      }
      lobePts.push(dPt(rb.s + sLocal, nLocal));
    }

    // Translucent golden-amber honey glaze over the rib
    brush.fill(PALETTE.amberGlow, 115);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.35, 0.25);
    drawPolyShape(lobePts, 0.3, true);

    // Glowing saffron meniscus at the bottom drip bulge
    if (rb.honeyHang > 12) {
      let dripCenter = dPt(rb.s + 4, perspRy + rb.honeyHang * 0.55);
      brush.fill(PALETTE.saffronLight, 170);
      brush.fillBleed(0.08, "in");
      drawPolyShape(
        makeEllipsePts(dripCenter[0], dripCenter[1], perspRx * 0.75, rb.honeyHang * 0.55, alpha + 15, 18),
        0.3,
        true
      );
    }
    resetBrushState();

    // 4. COOL WINDOW REFLECTIONS ON THE WET HONEY-COATED RIB
    // Upper-left sky reflection bar + crisp white window specular
    let skyReflPts = [
      dPt(sBack + 2, -perspRy * 0.82),
      dPt(sFront - 1, -perspRy * 0.82),
      dPt(sFront + perspRx * 0.25, -perspRy * 0.42),
      dPt(sBack - perspRx * 0.15, -perspRy * 0.42)
    ];
    brush.wash(PALETTE.windowSky, 185);
    drawPolyShape(skyReflPts, 0.2, true);

    let specPts = [
      dPt(sBack + 3, -perspRy * 0.72),
      dPt(sFront - 2, -perspRy * 0.72),
      dPt(sFront - 1, -perspRy * 0.56),
      dPt(sBack + 3, -perspRy * 0.56)
    ];
    brush.wash(PALETTE.pureWhite, 240);
    drawPolyShape(specPts, 0.15, true);

    // Secondary specular crescent on the hanging honey bulge
    let lowerSpec1 = dPt(rb.s - perspRx * 0.35, perspRy * 0.55 + rb.honeyHang * 0.25);
    let lowerSpec2 = dPt(rb.s + perspRx * 0.25, perspRy * 0.72 + rb.honeyHang * 0.45);
    brush.set("liquidNeedle", PALETTE.windowCyan, 1.35);
    brush.line(lowerSpec1[0], lowerSpec1[1], lowerSpec2[0], lowerSpec2[1]);
    brush.set("liquidNeedle", PALETTE.pureWhite, 0.9);
    brush.line(lowerSpec1[0] + 2, lowerSpec1[1] - 1, lowerSpec2[0] - 2, lowerSpec2[1] - 1);
    resetBrushState();
  }

  // Turned wooden spherical tip cap at the front end of the dipper (s = 502)
  let tipCenter = dPt(496, 0);
  brush.wash(PALETTE.woodDark, 225);
  drawPolyShape(makeEllipsePts(tipCenter[0], tipCenter[1], 14, 34, alpha, 22), 0.3, true);
  brush.fill(PALETTE.amberGlow, 150);
  brush.fillBleed(0.08, "in");
  drawPolyShape(makeEllipsePts(tipCenter[0] + 2, tipCenter[1] + 5, 11, 26, alpha, 20), 0.3, true);
  brush.wash(PALETTE.windowCyan, 210);
  drawPolyShape(makeEllipsePts(tipCenter[0] - 3, tipCenter[1] - 14, 5, 9, alpha - 15, 14), 0.3, true);

  resetBrushState();
}

// ============================================================================
// 4. HYPERREAL COILING HONEY FOLDS, FALLING RIBBON & BUBBLES
// ============================================================================

function renderHyperrealHoneyTube(ribbon, opts = {}) {
  const n = ribbon.length;
  const flipLight = opts.flipLight || false;
  const sgn = flipLight ? -1 : 1;

  resetBrushState();

  // 1. Opaque Warm Amber-Gold Base Wash (gives solid hyperreal body over background)
  brush.wash(opts.baseColor || PALETTE.honeyMid, opts.baseOpacity || 225);
  drawPolyShape(
    getRibbonStripPts(ribbon, 0, n - 1, () => -1.0, () => 1.0),
    0.28,
    true
  );
  resetBrushState();

  // 2. Watercolor Translucent Amber Layer (soft internal bloom)
  brush.fill(PALETTE.amberGlow, 130);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.3, 0.2);
  drawPolyShape(
    getRibbonStripPts(ribbon, 0, n - 1, () => -0.92, () => 0.92),
    0.28,
    true
  );
  resetBrushState();

  // 3. Deep Burnt-Umber & Mahogany Fresnel Core Shadow (underside / refractive edge)
  brush.wash(PALETTE.mahogany, 215);
  drawPolyShape(
    getRibbonStripPts(ribbon, 0, n - 1, () => 0.52 * sgn, () => 0.98 * sgn),
    0.25,
    true
  );

  brush.wash(PALETTE.darkUmber, 220);
  drawPolyShape(
    getRibbonStripPts(ribbon, 0, n - 1, () => 0.76 * sgn, () => 1.0 * sgn),
    0.25,
    true
  );

  // Opposite thin dark refractive rim
  brush.wash(PALETTE.deepAmber, 195);
  drawPolyShape(
    getRibbonStripPts(ribbon, 0, n - 1, () => -1.0 * sgn, () => -0.82 * sgn),
    0.25,
    true
  );

  // 4. Internal Refracted Saffron & Pale-Gold Caustic Core
  // Light passing through the liquid cylinder concentrates on the side opposite the sky
  brush.wash(PALETTE.saffron, 215);
  drawPolyShape(
    getRibbonStripPts(
      ribbon,
      1,
      n - 2,
      (t) => (0.02 + 0.08 * sin(t * 180)) * sgn,
      (t) => (0.58 - 0.08 * cos(t * 180)) * sgn
    ),
    0.28,
    true
  );

  brush.wash(PALETTE.saffronLight, 225);
  drawPolyShape(
    getRibbonStripPts(
      ribbon,
      2,
      n - 3,
      (t) => (0.14 + 0.05 * sin(t * 240)) * sgn,
      (t) => (0.44 + 0.04 * cos(t * 240)) * sgn
    ),
    0.28,
    true
  );

  // Intense neon-gold caustic filament inside the thickest bends
  brush.wash(PALETTE.paleGold, 210);
  drawPolyShape(
    getRibbonStripPts(
      ribbon,
      Math.floor(n * 0.15),
      Math.floor(n * 0.85),
      () => 0.23 * sgn,
      () => 0.34 * sgn
    ),
    0.25,
    true
  );

  // 5. LIQUID SKIN MIRRORING THE COOL WINDOW (Upper-left convex ridge)
  // First: Cool North-Sky Blue Glaze mirrored along the highlight zone
  brush.wash(PALETTE.windowSky, 185);
  drawPolyShape(
    getRibbonStripPts(
      ribbon,
      1,
      n - 2,
      () => -0.78 * sgn,
      () => -0.22 * sgn
    ),
    0.25,
    true
  );

  // Second: Warped Multi-Pane Window Reflections (icy cyan & crisp pure white panes separated by muntin bars)
  let paneSegments = opts.windowPanes || [
    [0.08, 0.32],
    [0.37, 0.64],
    [0.69, 0.91]
  ];

  for (let seg of paneSegments) {
    let i0 = Math.floor(seg[0] * (n - 1));
    let i1 = Math.floor(seg[1] * (n - 1));
    if (i1 - i0 < 2) continue;

    // Upper row of reflected window panes (pure white core + icy cyan halo)
    brush.wash(PALETTE.windowCyan, 225);
    drawPolyShape(
      getRibbonStripPts(ribbon, i0, i1, () => -0.72 * sgn, () => -0.46 * sgn),
      0.2,
      true
    );
    brush.wash(PALETTE.pureWhite, 250);
    drawPolyShape(
      getRibbonStripPts(ribbon, i0, i1, () => -0.67 * sgn, () => -0.51 * sgn),
      0.18,
      true
    );

    // Lower parallel row of reflected window panes (separated by the central window mullion)
    brush.wash(PALETTE.windowCyan, 200);
    drawPolyShape(
      getRibbonStripPts(ribbon, i0, i1, () => -0.39 * sgn, () => -0.21 * sgn),
      0.2,
      true
    );
    brush.wash(PALETTE.iceWhite, 235);
    drawPolyShape(
      getRibbonStripPts(ribbon, i0, i1, () => -0.35 * sgn, () => -0.25 * sgn),
      0.18,
      true
    );
  }

  // 6. Crisp Micro-Contour & Specular Edge Polish
  brush.set("liquidNeedle", PALETTE.darkUmber, 0.95);
  let botEdge = [];
  let topEdge = [];
  for (let i = 0; i < n; i++) {
    botEdge.push(ribbon.pt(i, 0.96 * sgn));
    topEdge.push(ribbon.pt(i, -0.96 * sgn));
  }
  brush.spline(botEdge, 0.35);
  brush.set("liquidNeedle", PALETTE.deepAmber, 0.75);
  brush.spline(topEdge, 0.35);

  resetBrushState();
}

function drawHyperrealHoneySystem() {
  resetBrushState();

  // --- LAYER 1: THE BASAL HONEY POOL (cx: 632, cy: 952) ---
  // Thick, glossy elliptical puddle with rounded meniscus rim
  const poolCx = 632;
  const poolCy = 950;
  const poolRx = 212;
  const poolRy = 60;
  const poolRot = -8;

  // Outer dark mahogany-amber rim
  brush.wash(PALETTE.mahogany, 240);
  drawPolyShape(makeEllipsePts(poolCx, poolCy, poolRx, poolRy, poolRot, 36), 0.3, true);

  // Mid translucent golden-amber body
  brush.wash(PALETTE.honeyMid, 235);
  drawPolyShape(makeEllipsePts(poolCx - 2, poolCy - 2, poolRx * 0.94, poolRy * 0.9, poolRot, 36), 0.3, true);

