// =============================================================================
// GEOMETRY HELPERS
// =============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Returns half-width of the lancet arch at height y (for y <= ARCH_SPRING_Y)
function lancetHalfWidth(y, inset = 0) {
  const r = ARCH_R - inset;
  if (y >= ARCH_SPRING_Y) {
    return (ARCH_RIGHT - ARCH_LEFT) / 2 - inset;
  }
  const dy = ARCH_SPRING_Y - y;
  if (dy >= r) return 0;
  const dx = Math.sqrt(Math.max(0, r * r - dy * dy));
  // Left arc center is at ARCH_CX_L = 602, so left x = 602 - dx
  const xLeft = ARCH_CX_L - dx;
  return Math.max(0, CX - xLeft);
}

// Generates a closed polygon for the lancet window opening with optional inset
function getLancetPolygon(inset = 0, bottomY = SILL_Y) {
  const pts = [];
  const halfW = (ARCH_RIGHT - ARCH_LEFT) / 2 - inset;
  pts.push([CX - halfW, bottomY]);
  pts.push([CX - halfW, ARCH_SPRING_Y]);

  const steps = 28;
  // Left curve from spring line up to apex
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const y = lerp(ARCH_SPRING_Y, ARCH_APEX_Y + inset * 1.15, t);
    const hw = lancetHalfWidth(y, inset);
    pts.push([CX - hw, y]);
  }
  // Right curve from apex down to spring line
  for (let i = steps - 1; i >= 1; i--) {
    const t = i / steps;
    const y = lerp(ARCH_SPRING_Y, ARCH_APEX_Y + inset * 1.15, t);
    const hw = lancetHalfWidth(y, inset);
    pts.push([CX + hw, y]);
  }

  pts.push([CX + halfW, ARCH_SPRING_Y]);
  pts.push([CX + halfW, bottomY]);
  return pts;
}

// Sub-lancet arch helper (left or right light of the double lancet)
function getSubLancetPoints(centerX, halfW, springY, apexY, bottomY) {
  const pts = [];
  pts.push([centerX - halfW, bottomY]);
  pts.push([centerX - halfW, springY]);
  const steps = 16;
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const ang = t * 90;
    const x = centerX - halfW * cos(ang * 0.85);
    const y = springY - (springY - apexY) * sin(ang);
    pts.push([x, y]);
  }
  for (let i = steps - 1; i >= 1; i--) {
    const t = i / steps;
    const ang = t * 90;
    const x = centerX + halfW * cos(ang * 0.85);
    const y = springY - (springY - apexY) * sin(ang);
    pts.push([x, y]);
  }
  pts.push([centerX + halfW, springY]);
  pts.push([centerX + halfW, bottomY]);
  return pts;
}

