function drawPaperGround() {
  brush.noStroke();
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.55, 0.35);

  // Warm raw-umber & parchment outer wash
  brush.fill("#cbbba0", 70);
  brush.rect(20, 20, 1160, 1160);

  // Subtle paper fiber grain via faint hatching
  brush.hatchStyle("2H", "#b8a78c", 0.6);
  brush.hatch(14, 0, { rand: 0.08 });
  brush.rect(0, 0, 1200, 1200);
  brush.noHatch();
}

// =============================================================================
// 2. BACKLIT GOTHIC LANCET WINDOW GLASS
// =============================================================================

function drawBacklitWindowGlass() {
  brush.noStroke();

  // Solid luminous parchment-amber base inside the lancet opening
  const lancetOuter = getLancetPolygon(0, SILL_Y);
  brush.wash("#f3e5c8", 235);
  drawPoly(lancetOuter);

  // Layered watercolour glazes for backlit antique crown glass
  // Outer deeper earth-amber rim inside the lancet
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.6, 0.45);
  brush.fill("#b89868", 85);
  drawPoly(getLancetPolygon(0, SILL_Y));

  // Mid warm golden-ochre glaze in upper arch
  brush.fill("#cfa970", 75);
  drawPoly(getLancetPolygon(28, 600));

  // Individual stained-glass quarry tints (earthy buffs, pale sage-ochre, warm honey)
  const quarryTints = ["#e6d1a7", "#d4b580", "#c9aa78", "#dfd0b2", "#ebdcbb"];
  const qSizeX = 76;
  const qSizeY = 96;

  for (let tIdx = 0; tIdx < quarryTints.length; tIdx++) {
    brush.fill(quarryTints[tIdx], 62);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.5, 0.4);

    for (let row = -1; row < 9; row++) {
      const cy = 110 + row * qSizeY;
      if (cy > 660) continue; // lower area is covered by jars and bright backlight
      const hw = lancetHalfWidth(cy, 24);
      const maxCols = Math.floor(hw / qSizeX);
      for (let col = -maxCols; col <= maxCols; col++) {
        // Deterministic symmetrical assignment to tint batch
        const symHash = (Math.abs(col) * 7 + row * 13) % quarryTints.length;
        if (symHash !== tIdx) continue;

        const cx = CX + col * qSizeX + (row % 2 !== 0 ? (col >= 0 ? 19 : -19) : 0);
        // Make symmetric pair if col != 0
        if (Math.abs(cx - CX) + 32 > hw) continue;
        const diamond = [
          [cx, cy - qSizeY * 0.46],
          [cx + qSizeX * 0.46, cy],
