// =============================================================================
// 4. GOTHIC TRACERY & WINDOW LEADING BEHIND JARS
// =============================================================================

function drawWindowTraceryAndLeading() {
  // A. Diamond Quarry Leading Grid inside the Lancet Window
  const qSizeX = 76;
  const qSizeY = 96;

  brush.set("rotring", "#2b241e", 1.15);
  // Diagonal lead cames (left-leaning and right-leaning) clipped to lancet
  for (let k = -12; k <= 12; k++) {
    // Draw segmented diamond grid lines within the lancet bounds
    const steps = 28;
    for (let dir of [-1, 1]) {
      let prev = null;
      for (let s = 0; s <= steps; s++) {
        const y = lerp(ARCH_APEX_Y + 12, SILL_Y, s / steps);
        const x = CX + k * qSizeX + dir * ((y - 300) * (qSizeX / qSizeY));
        const hw = lancetHalfWidth(y, 14);
        if (Math.abs(x - CX) <= hw) {
          if (prev) {
            brush.line(prev[0], prev[1], x, y);
          }
          prev = [x, y];
        } else {
          prev = null;
        }
      }
    }
  }

  // B. Horizontal iron saddle-bars (stay-bars) across the lancet window
  const saddleRows = [215, 345, 455, 565, 680, 785];
  brush.set("leadCame", "#1a1512", 1.35);
  for (let sy of saddleRows) {
    const hw = lancetHalfWidth(sy, 8);
    if (hw > 10) {
      brush.line(CX - hw, sy, CX + hw, sy);
    }
  }

  // C. Gothic Sub-Arches & Central Mullion
  const subSpringY = 555;
  const subApexY = 355;
  const subLeftCX = 371;
  const subRightCX = 829;
  const subHalfW = 221;

  // Heavy charcoal-black tracery ribs
  brush.set("leadCame", "#171310", 2.4);
  // Central vertical mullion from sub-arch intersection down to sill
  brush.line(CX, 345, CX, SILL_Y);
  brush.set("charcoal", "#2e2620", 1.6);
  brush.line(CX - 5, 355, CX - 5, SILL_Y);
  brush.line(CX + 5, 355, CX + 5, SILL_Y);

  // Left and Right Sub-Lancet Arches
  for (let scx of [subLeftCX, subRightCX]) {
    const pts = getSubLancetPoints(scx, subHalfW, subSpringY, subApexY, SILL_Y);
    brush.set("leadCame", "#171310", 2.1);
    for (let i = 1; i < pts.length - 1; i++) {
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
    // Inner cusped foil line
    const ptsInner = getSubLancetPoints(scx, subHalfW - 14, subSpringY, subApexY + 16, SILL_Y);
    brush.set("rotring", "#241e19", 1.25);
    for (let i = 1; i < ptsInner.length - 1; i++) {
      brush.line(ptsInner[i][0], ptsInner[i][1], ptsInner[i + 1][0], ptsInner[i + 1][1]);
    }
  }

  // D. Upper Gothic Rose / Quatrefoil Oculus in the Lancet Head (centered at 600, 248)
  const roseCX = CX;
  const roseCY = 248;
  const roseR = 104;

  // Warm pot-metal glazes inside the upper rose oculus
  brush.noStroke();
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.55, 0.45);
  brush.fill("#c98838", 95);
  brush.circle(roseCX, roseCY, roseR * 0.92, 0.04);

  // 8-foiled cusps around the rose
  const numLobes = 8;
  brush.fill("#8c2d26", 105);
  for (let i = 0; i < numLobes; i += 2) {
    const ang = i * (360 / numLobes);
    const lx = roseCX + cos(ang) * (roseR * 0.56);
    const ly = roseCY + sin(ang) * (roseR * 0.56);
    brush.circle(lx, ly, roseR * 0.32, 0.05);
  }
  brush.fill("#5c2648", 105);
  for (let i = 1; i < numLobes; i += 2) {
    const ang = i * (360 / numLobes);
    const lx = roseCX + cos(ang) * (roseR * 0.56);
    const ly = roseCY + sin(ang) * (roseR * 0.56);
    brush.circle(lx, ly, roseR * 0.32, 0.05);
  }
  // Center jewel of the rose
  brush.fill("#f2c464", 150);
  brush.circle(roseCX, roseCY, roseR * 0.34, 0.04);
  brush.noFill();

  // Leading for the Rose Oculus
  brush.set("leadCame", "#14100d", 2.3);
  brush.circle(roseCX, roseCY, roseR, 0.03);
  brush.set("leadCame", "#14100d", 1.7);
  brush.circle(roseCX, roseCY, roseR * 0.86, 0.03);
  brush.circle(roseCX, roseCY, roseR * 0.34, 0.03);

  for (let i = 0; i < numLobes; i++) {
    const ang = i * (360 / numLobes);
    const lx = roseCX + cos(ang) * (roseR * 0.56);
    const ly = roseCY + sin(ang) * (roseR * 0.56);
    brush.set("leadCame", "#171310", 1.45);
    brush.circle(lx, ly, roseR * 0.31, 0.04);
    // Radial spoke
    const x1 = roseCX + cos(ang) * (roseR * 0.34);
    const y1 = roseCY + sin(ang) * (roseR * 0.34);
    const x2 = roseCX + cos(ang) * (roseR * 0.86);
    const y2 = roseCY + sin(ang) * (roseR * 0.86);
    brush.line(x1, y1, x2, y2);
  }

  // Small trefoil/spandrel circles tucked around the rose
  for (let sx of [CX - 118, CX + 118]) {
    brush.set("leadCame", "#171310", 1.6);
    brush.circle(sx, 342, 26, 0.04);
  }
  brush.circle(CX, 114, 24, 0.04);
}

// =============================================================================
// 5. STONE LANCET ARCH SURROUND & SPANDRELS
// =============================================================================

function drawStoneArchSurround() {
  brush.noStroke();

  // Build left and right outer stone wall spandrel polygons (outside the lancet arch)
  const steps = 32;
  const leftSpandrel = [[0, 0], [CX, 0], [CX, ARCH_APEX_Y]];
  for (let i = 1; i <= steps; i++) {
    const y = lerp(ARCH_APEX_Y, ARCH_SPRING_Y, i / steps);
    const hw = lancetHalfWidth(y, 0);
    leftSpandrel.push([CX - hw, y]);
  }
  leftSpandrel.push([ARCH_LEFT, SILL_Y]);
  leftSpandrel.push([0, SILL_Y]);

  const rightSpandrel = [[1200, 0], [CX, 0], [CX, ARCH_APEX_Y]];
  for (let i = 1; i <= steps; i++) {
    const y = lerp(ARCH_APEX_Y, ARCH_SPRING_Y, i / steps);
    const hw = lancetHalfWidth(y, 0);
    rightSpandrel.push([CX + hw, y]);
  }
  rightSpandrel.push([ARCH_RIGHT, SILL_Y]);
  rightSpandrel.push([1200, SILL_Y]);

  // Opaque base wash for stone masonry surround
  brush.wash("#4a3d31", 235);
  drawPoly(leftSpandrel);
  drawPoly(rightSpandrel);
  brush.noWash();

  // Deep earthy watercolour glazes over the stone surround
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.7, 0.55);
  brush.fill("#2e241c", 130);
  drawPoly(leftSpandrel);
  drawPoly(rightSpandrel);

  // Darker upper-corner vignette washes
  brush.fill("#1c1510", 135);
  drawPoly([[0, 0], [460, 0], [210, 360], [0, 520]]);
  drawPoly([[1200, 0], [740, 0], [990, 360], [1200, 520]]);
  brush.noFill();

  // Cross-hatched stone texture in the spandrels
  brush.hatchStyle("charcoal", "#211a14", 0.85);
  brush.hatch(14, 35, { rand: 0.12 });
  drawPoly(leftSpandrel);
  drawPoly(rightSpandrel);
  brush.hatch(16, -35, { rand: 0.12 });
  drawPoly(leftSpandrel);
  drawPoly(rightSpandrel);
  brush.noHatch();

  // Stone Arch Voussoirs (Radial Arch Blocks around the Lancet Opening)
  const voussoirDepth = 64;
  const numVoussoirs = 18;

  // Draw vertical jamb blocks below spring line (y from ARCH_SPRING_Y to SILL_Y)
  const jambRows = 6;
  const jambH = (SILL_Y - ARCH_SPRING_Y) / jambRows;
  for (let r = 0; r < jambRows; r++) {
    const y1 = ARCH_SPRING_Y + r * jambH;
    const y2 = y1 + jambH;
    const blockW = r % 2 === 0 ? voussoirDepth : voussoirDepth * 0.86;
    const shade = r % 2 === 0 ? "#695847" : "#574738";

    brush.noStroke();
    brush.wash(shade, 175);
    // Left jamb stone
    drawPoly([
      [ARCH_LEFT - blockW, y1],
      [ARCH_LEFT, y1],
      [ARCH_LEFT, y2],
      [ARCH_LEFT - blockW, y2]
    ]);
    // Right jamb stone
    drawPoly([
      [ARCH_RIGHT, y1],
      [ARCH_RIGHT + blockW, y1],
      [ARCH_RIGHT + blockW, y2],
      [ARCH_RIGHT, y2]
    ]);
    brush.noWash();

    brush.set("charcoal", "#1a1410", 1.3);
    brush.line(ARCH_LEFT - blockW, y1, ARCH_LEFT, y1);
    brush.line(ARCH_LEFT - blockW, y1, ARCH_LEFT - blockW, y2);
    brush.line(ARCH_RIGHT, y1, ARCH_RIGHT + blockW, y1);
    brush.line(ARCH_RIGHT + blockW, y1, ARCH_RIGHT + blockW, y2);
  }

  // Curved Arch Voussoirs from spring line up to apex
  for (let i = 0; i < numVoussoirs; i++) {
    const t1 = i / numVoussoirs;
    const t2 = (i + 1) / numVoussoirs;
    const y1 = lerp(ARCH_SPRING_Y, ARCH_APEX_Y, t1);
    const y2 = lerp(ARCH_SPRING_Y, ARCH_APEX_Y, t2);
    const hwIn1 = lancetHalfWidth(y1, 0);
    const hwIn2 = lancetHalfWidth(y2, 0);
    const hwOut1 = lancetHalfWidth(y1, -voussoirDepth);
    const hwOut2 = lancetHalfWidth(y2, -voussoirDepth);

    const shade = i % 2 === 0 ? "#6e5c4a" : "#59493a";
    brush.noStroke();
    brush.wash(shade, 165);
    // Left voussoir
    drawPoly([
      [CX - hwIn1, y1],
      [CX - hwOut1, y1 - 8],
      [CX - hwOut2, y2 - 8],
      [CX - hwIn2, y2]
    ]);
    // Right voussoir
    drawPoly([
      [CX + hwIn1, y1],
      [CX + hwOut1, y1 - 8],
      [CX + hwOut2, y2 - 8],
      [CX + hwIn2, y2]
    ]);
    brush.noWash();

    // Mortar joint lines
    brush.set("charcoal", "#1a1410", 1.25);
    brush.line(CX - hwIn1, y1, CX - hwOut1, y1 - 8);
    brush.line(CX + hwIn1, y1, CX + hwOut1, y1 - 8);
  }

  // Deep bevelled inner reveal (splay) of the lancet arch catching warm backlight
  const innerPoly = getLancetPolygon(0, SILL_Y);
  const splayPoly = getLancetPolygon(16, SILL_Y);

  // Heavy charcoal-black outer & inner arch frame leading
  brush.set("leadCame", "#120e0b", 2.8);
  for (let i = 0; i < innerPoly.length - 1; i++) {
    brush.line(innerPoly[i][0], innerPoly[i][1], innerPoly[i + 1][0], innerPoly[i + 1][1]);
  }
  brush.set("leadCame", "#1c1612", 2.0);
  for (let i = 0; i < splayPoly.length - 1; i++) {
    brush.line(splayPoly[i][0], splayPoly[i][1], splayPoly[i + 1][0], splayPoly[i + 1][1]);
  }
}

