// Compute key vertical landmarks for a jar
function getJarMetrics(jar) {
  const topY = jar.baseY - jar.h;
  const lidBottomY = topY + jar.lidH;
  const shoulderY = lidBottomY + jar.h * 0.11;
  const meniscusY = shoulderY + jar.h * 0.05;
  const heelY = jar.baseY - jar.h * 0.08;
  const hw = jar.w / 2;
  const nHw = jar.neckW / 2;
  return { topY, lidBottomY, shoulderY, meniscusY, heelY, hw, nHw };
}

// Returns closed polygon for the glass body of a jar
function getJarBodyPolygon(jar, inset = 0) {
  const m = getJarMetrics(jar);
  const hw = m.hw - inset;
  const nHw = m.nHw - inset * 0.8;
  return [
    [jar.cx - nHw, m.lidBottomY + inset],
    [jar.cx + nHw, m.lidBottomY + inset],
    [jar.cx + hw * 0.96, m.shoulderY],
    [jar.cx + hw, m.shoulderY + 26],
    [jar.cx + hw, m.heelY],
    [jar.cx + hw * 0.88, jar.baseY - inset],
    [jar.cx - hw * 0.88, jar.baseY - inset],
    [jar.cx - hw, m.heelY],
    [jar.cx - hw, m.shoulderY + 26],
    [jar.cx - hw * 0.96, m.shoulderY]
  ];
}

function drawAllJars(jars) {
  // PASS 1: Cast shadow on sill directly under each jar base
  brush.noStroke();
  for (let jar of jars) {
    brush.wash("#1f1711", 210);
    drawPoly([
      [jar.cx - jar.w * 0.46, jar.baseY - 4],
      [jar.cx + jar.w * 0.46, jar.baseY - 4],
      [jar.cx + jar.w * 0.54, jar.baseY + 18],
      [jar.cx - jar.w * 0.54, jar.baseY + 18]
    ], 0.3);
  }
  brush.noWash();

  // PASS 2: Multi-layered Pot-Metal Watercolour Glazes & Jewel Cells
  for (let jar of jars) {
    drawJarPotMetalGlazes(jar);
  }

  // PASS 3: Suspended Fruit Pieces & Rising Air Bubbles inside Jelly
  for (let jar of jars) {
    drawJarFruitAndBubbles(jar);
  }

  // PASS 4: Heavy Charcoal-Black Leading Splitting Glass into Jewel-Like Cells
  for (let jar of jars) {
    drawJarLeadingAndCells(jar);
  }

  // PASS 5: Handwritten Curling Labels on Jar Bellies
  for (let jar of jars) {
    drawJarCurlingLabel(jar);
  }

  // PASS 6: Gingham Fabric Bonnets, Pleated Skirts & Hemp Twine Bows
  for (let jar of jars) {
    drawJarGinghamBonnet(jar);
  }

  // PASS 7: Sharp White Specular Glints on Jar Rims, Shoulders & Heels
  for (let jar of jars) {
    drawJarSharpGlints(jar);
  }
}

// -----------------------------------------------------------------------------
// PASS 2: POT-METAL WATERCOLOUR GLAZES
// -----------------------------------------------------------------------------

function drawJarPotMetalGlazes(jar) {
  const m = getJarMetrics(jar);
  const pal = jar.palette;

  brush.noStroke();

  // 1. Base warm luminous ground wash inside the jar so it glows from within
  brush.wash(pal.glowCore, 200);
  drawPoly(getJarBodyPolygon(jar, 2));

  // Clear/amber backlit headspace above the meniscus
  brush.wash("#f5e3be", 215);
  drawPoly([
    [jar.cx - m.nHw + 4, m.lidBottomY + 6],
    [jar.cx + m.nHw - 4, m.lidBottomY + 6],
    [jar.cx + m.hw - 4, m.meniscusY],
    [jar.cx - m.hw + 4, m.meniscusY]
  ]);

  // Thick glass bottom heel refraction band
  brush.wash("#d6be96", 185);
  drawPoly([
    [jar.cx - m.hw + 4, m.heelY],
    [jar.cx + m.hw - 4, m.heelY],
    [jar.cx + m.hw * 0.88, jar.baseY - 2],
    [jar.cx - m.hw * 0.88, jar.baseY - 2]
  ]);
  brush.noWash();

  // 2. Deep pot-metal watercolour glazes (layered from outside in like stained glass)
  // Full jelly body glaze
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.65, 0.5);
  brush.fill(pal.midPot, 125);
  drawPoly([
    [jar.cx - m.hw + 2, m.meniscusY],
    [jar.cx + m.hw - 2, m.meniscusY],
    [jar.cx + m.hw - 2, m.heelY + 6],
    [jar.cx - m.hw + 2, m.heelY + 6]
  ]);

  // Left and Right deep cylindrical shadow columns (dark pot-metal glass thickness)
  const edgeColW = m.hw * 0.42;
  brush.fillBleed(0.24, "in");
  brush.fill(pal.darkPot, 145);
  // Left column
  drawPoly([
    [jar.cx - m.hw + 2, m.shoulderY],
    [jar.cx - m.hw + edgeColW, m.meniscusY],
    [jar.cx - m.hw + edgeColW * 0.9, m.heelY],
    [jar.cx - m.hw + 2, m.heelY]
  ]);
  // Right column
  drawPoly([
    [jar.cx + m.hw - edgeColW, m.meniscusY],
    [jar.cx + m.hw - 2, m.shoulderY],
    [jar.cx + m.hw - 2, m.heelY],
    [jar.cx + m.hw - edgeColW * 0.9, m.heelY]
  ]);

  // Deepest basal sediment & upper shoulder shadow glazes
  brush.fill(pal.deepEdge, 140);
  drawPoly([
    [jar.cx - m.hw + 3, m.heelY - 42],
    [jar.cx + m.hw - 3, m.heelY - 42],
    [jar.cx + m.hw - 3, m.heelY + 8],
    [jar.cx - m.hw + 3, m.heelY + 8]
  ]);
  drawPoly([
    [jar.cx - m.hw + 3, m.meniscusY - 6],
    [jar.cx + m.hw - 3, m.meniscusY - 6],
    [jar.cx + m.hw - 3, m.meniscusY + 34],
    [jar.cx - m.hw + 3, m.meniscusY + 34]
  ]);

  // 3. Individual Jewel-Cell Facet Glazes (splitting the interior into leaded glass tones)
  const jellyH = m.heelY - m.meniscusY;
  const rows = 4;
  const cols = 3;
  const cellW = (jar.w - 10) / cols;
  const cellH = jellyH / rows;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x1 = jar.cx - m.hw + 5 + c * cellW;
      const x2 = x1 + cellW;
      const y1 = m.meniscusY + r * cellH;
      const y2 = y1 + cellH;

      // Center column and mid rows glow brightest; outer cells deepen
      const isCenterCol = c === 1;
      const isMidRow = r === 1 || r === 2;

      let cellColor = pal.midPot;
      let alpha = 95;
      if (isCenterCol && isMidRow) {
        cellColor = pal.glowCore;
        alpha = 135;
      } else if (isCenterCol || isMidRow) {
        cellColor = pal.brightPot;
        alpha = 115;
      } else {
        cellColor = pal.darkPot;
        alpha = 110;
      }

      // Slight arched distortion to match cylindrical refraction
      const archBulge = (c - 1) * 6;
      brush.fillBleed(0.18, "in");
      brush.fillTexture(0.55, 0.45);
      brush.fill(cellColor, alpha);
      drawPoly([
        [x1 + 3, y1 + 3],
        [x2 - 3, y1 + 3 + archBulge],
        [x2 - 3, y2 - 3 + archBulge],
        [x1 + 3, y2 - 3]
      ], 0.12);
    }
  }

  // 4. Incandescent Backlit Heart in the Center of the Preserve
  const heartY = (m.meniscusY + m.heelY) * 0.52;
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.4, 0.25);
  brush.fill(pal.glowCore, 155);
  brush.circle(jar.cx, heartY, m.hw * 0.62, 0.08);

  brush.fill(pal.hotCore, 165);
  brush.circle(jar.cx, heartY - 12, m.hw * 0.36, 0.08);

  brush.noFill();
}

// -----------------------------------------------------------------------------
// PASS 3: SUSPENDED FRUIT PIECES & AIR BUBBLES
// -----------------------------------------------------------------------------

function drawJarFruitAndBubbles(jar) {
  const m = getJarMetrics(jar);
  const pal = jar.palette;
  const jellyTop = m.meniscusY + 12;
  const jellyBot = m.heelY - 16;

  // A. SUSPENDED FRUIT PIECES (Flavor-specific hyperreal shapes)
  if (jar.flavor === "apricot") {
    // Suspended glowing apricot halves (crescent domes)
    const halves = [
      { dx: -32, dy: 0.24, rx: 32, ry: 22, rot: -18 },
      { dx: 30, dy: 0.28, rx: 30, ry: 21, rot: 22 },
      { dx: -24, dy: 0.56, rx: 34, ry: 23, rot: 14 },
      { dx: 28, dy: 0.62, rx: 32, ry: 22, rot: -16 },
      { dx: 0, dy: 0.40, rx: 36, ry: 24, rot: 5 },
      { dx: -18, dy: 0.80, rx: 28, ry: 18, rot: -8 },
      { dx: 22, dy: 0.82, rx: 28, ry: 18, rot: 10 }
    ];
    for (let h of halves) {
      const fx = jar.cx + h.dx;
      const fy = lerp(jellyTop, jellyBot, h.dy);
      // Translucent apricot flesh rim
      brush.noStroke();
      brush.wash(pal.fruitRim, 175);
      brush.circle(fx, fy, h.rx, 0.14);
      // Deep burnt-sienna stone cavity core
      brush.wash(pal.fruitDark, 195);
      brush.circle(fx + (h.dx >= 0 ? -4 : 4), fy + 3, h.rx * 0.58, 0.12);
      brush.noWash();
      // Delicate internal fruit fiber lines
      brush.set("2B", pal.deepEdge, 0.75);
      brush.arc(fx, fy, h.rx * 0.85, 20 + h.rot, 170 + h.rot);
    }
  } else if (jar.flavor === "raspberry") {
    // Crushed & whole raspberry drupelet clusters + suspended golden seeds
    const berries = [
      { dx: -44, dy: 0.20, r: 22 },
      { dx: 44, dy: 0.20, r: 22 },
      { dx: 0, dy: 0.25, r: 25 },
      { dx: -36, dy: 0.42, r: 24 },
      { dx: 36, dy: 0.42, r: 24 },
      { dx: -48, dy: 0.66, r: 21 },
      { dx: 48, dy: 0.66, r: 21 },
      { dx: -20, dy: 0.82, r: 23 },
      { dx: 20, dy: 0.82, r: 23 }
    ];
    for (let b of berries) {
      const bx = jar.cx + b.dx;
      const by = lerp(jellyTop, jellyBot, b.dy);
      // Cluster of drupelets
      for (let d = 0; d < 7; d++) {
        const ang = d * 51;
        const dr = d === 0 ? 0 : b.r * 0.48;
        const dx = bx + cos(ang) * dr;
        const dy = by + sin(ang) * dr;
        brush.noStroke();
        brush.wash(pal.fruitDark, 190);
        brush.circle(dx, dy, b.r * 0.36, 0.08);
        brush.wash(pal.hotCore, 130);
        brush.circle(dx - 2, dy - 2, b.r * 0.16, 0.05);
        brush.noWash();
      }
      brush.set("cpencil", pal.deepEdge, 0.75);
      brush.circle(bx, by, b.r * 0.82, 0.15);
    }
    // Tiny pale-gold raspberry seeds suspended throughout the ruby jelly
    for (let s = 0; s < 38; s++) {
      const sy = lerp(jellyTop + 6, jellyBot - 6, ((s * 19) % 37) / 37);
      const spread = (m.hw - 14) * sin(((s * 29) % 180));
      const sx = jar.cx + (s % 2 === 0 ? spread : -spread) * 0.85;
      brush.set("glintPen", "#f7ce86", 0.75);
      brush.line(sx - 2, sy - 1, sx + 2, sy + 1);
      brush.set("rotring", pal.deepEdge, 0.55);
      brush.line(sx - 2, sy, sx + 1, sy + 2);
    }
  } else if (jar.flavor === "damson") {
    // Whole & split dark damson plums with glowing violet-rose skins
    const plums = [
      { dx: -26, dy: 0.24, r: 26 },
      { dx: 26, dy: 0.26, r: 25 },
      { dx: 0, dy: 0.42, r: 28 },
      { dx: -28, dy: 0.62, r: 25 },
      { dx: 28, dy: 0.64, r: 25 },
      { dx: 0, dy: 0.82, r: 26 }
    ];
    for (let p of plums) {
      const px = jar.cx + p.dx;
      const py = lerp(jellyTop, jellyBot, p.dy);
      brush.noStroke();
      brush.wash(pal.fruitRim, 175);
      brush.circle(px, py, p.r * 1.05, 0.1);
      brush.wash(pal.fruitDark, 215);
      brush.circle(px, py, p.r * 0.82, 0.09);
      brush.noWash();
      // Curling plum skin highlight arc
      brush.set("pen", pal.hotCore, 0.8);
      brush.arc(px, py, p.r * 0.75, 200, 320);
    }
  }

  // B. SUSPENDED AIR BUBBLES IN THE JELLY
  // Rising streams of tiny & medium bubbles catching transmitted light
  const numBubbles = 32;
  for (let i = 0; i < numBubbles; i++) {
    // Deterministic symmetrical-feel distribution
    const tY = ((i * 23 + 7) % 100) / 100;
    const by = lerp(jellyTop + 4, jellyBot - 8, tY);
    const normX = (((i * 41 + 13) % 100) / 50 - 1) * 0.84;
    const bx = jar.cx + normX * m.hw;
    const br = 2.2 + ((i * 17) % 5) * 1.35;

    // Bubble interior glow
    brush.noStroke();
    brush.wash(pal.hotCore, 165);
    brush.circle(bx, by, br, 0.03);
    brush.noWash();

    // Dark refractive rim of bubble
    brush.set("rotring", pal.deepEdge, 0.75);
    brush.circle(bx, by, br, 0.04);

    // Pinpoint white specular crescent on upper-inner side of bubble
    brush.set("glintPen", "#fffef7", 0.85);
    brush.arc(bx, by, br * 0.72, 200, 325);
  }

  // Dense foam/bubble ring along the liquid meniscus at the top of the preserve
  const meniscusBubbles = 18;
  for (let i = 0; i <= meniscusBubbles; i++) {
    const t = i / meniscusBubbles;
    const bx = lerp(jar.cx - m.hw + 8, jar.cx + m.hw - 8, t);
    const curveY = m.meniscusY + sin(t * 180) * 5;
    const br = 2.4 + (i % 3) * 1.1;

    brush.noStroke();
    brush.wash(pal.hotCore, 195);
    brush.circle(bx, curveY, br, 0.03);
    brush.noWash();

    brush.set("rotring", pal.deepEdge, 0.7);
    brush.circle(bx, curveY, br, 0.03);
  }
}

// -----------------------------------------------------------------------------
// PASS 4: HEAVY CHARCOAL-BLACK LEADING & JEWEL-CELL SPLITTING
// -----------------------------------------------------------------------------

function drawJarLeadingAndCells(jar) {
  const m = getJarMetrics(jar);
  const bodyPoly = getJarBodyPolygon(jar, 0);

  // 1. Internal Jewel-Cell Leading Network (curving with the cylindrical glass)
  const jellyTop = m.meniscusY;
  const jellyBot = m.heelY;
  const hSpan = jellyBot - jellyTop;

  // Horizontal curved lead cames across the jar (meniscus, 3 internal ribs, heel top)
  const yFracs = [0, 0.24, 0.50, 0.76, 1.0];
  const rowPoints = [];

  for (let r = 0; r < yFracs.length; r++) {
    const f = yFracs[r];
    const baseY = jellyTop + f * hSpan;
    // Slight downward cylindrical curve
    const sag = (f - 0.35) * 10;
    const pLeft = [jar.cx - m.hw + 2, baseY];
    const pMidL = [jar.cx - m.hw * 0.36, baseY + sag];
    const pCenter = [jar.cx, baseY + sag * 1.25];
    const pMidR = [jar.cx + m.hw * 0.36, baseY + sag];
    const pRight = [jar.cx + m.hw - 2, baseY];

    rowPoints.push([pLeft, pMidL, pCenter, pMidR, pRight]);

    brush.set("leadCame", "#14100d", r === 0 || r === yFracs.length - 1 ? 1.85 : 1.45);
    brush.spline([pLeft, pMidL, pCenter, pMidR, pRight], 0.35);
    brush.set("charcoal", "#241d17", 1.1);
    brush.spline([pLeft, pMidL, pCenter, pMidR, pRight], 0.35);
  }

  // Vertical curved cylindrical lead cames splitting the jar into 3 main columns + shoulder facets
  for (let c of [1, 3]) {
    const colSpline = [];
    // Start up at the neck under the lid
    const neckX = jar.cx + (c === 1 ? -m.nHw * 0.42 : m.nHw * 0.42);
    colSpline.push([neckX, m.lidBottomY + 8]);
    for (let r = 0; r < rowPoints.length; r++) {
      colSpline.push(rowPoints[r][c]);
    }
    // Down into the glass base heel
    const heelX = jar.cx + (c === 1 ? -m.hw * 0.32 : m.hw * 0.32);
    colSpline.push([heelX, jar.baseY - 3]);

    brush.set("leadCame", "#14100d", 1.55);
    brush.spline(colSpline, 0.25);
    brush.set("charcoal", "#241d17", 1.05);
    brush.spline(colSpline, 0.25);
  }

  // Diagonal jewel-facet lead lines in the upper shoulder and corners
  brush.set("leadCame", "#171310", 1.3);
  brush.line(jar.cx - m.nHw + 6, m.lidBottomY + 12, rowPoints[0][1][0], rowPoints[0][1][1]);
  brush.line(jar.cx + m.nHw - 6, m.lidBottomY + 12, rowPoints[0][3][0], rowPoints[0][3][1]);
  brush.line(rowPoints[0][1][0], rowPoints[0][1][1], rowPoints[1][0][0], rowPoints[1][0][1]);
  brush.line(rowPoints[0][3][0], rowPoints[0][3][1], rowPoints[1][4][0], rowPoints[1][4][1]);
  brush.line(rowPoints[3][0][0], rowPoints[3][0][1], rowPoints[4][1][0], rowPoints[4][1][1]);
  brush.line(rowPoints[3][4][0], rowPoints[3][4][1], rowPoints[4][3][0], rowPoints[4][3][1]);

  // Solder-joint nodes where internal lead cames intersect
  brush.noStroke();
  brush.wash("#120e0b", 235);
  for (let r = 0; r < rowPoints.length; r++) {
    for (let c of [0, 1, 3, 4]) {
      brush.circle(rowPoints[r][c][0], rowPoints[r][c][1], 3.2, 0.05);
    }
  }
  brush.noWash();

  // 2. Thick Glass Punt (Concave Bottom Dome) & Base Moulding
  brush.set("leadCame", "#14100d", 1.75);
  brush.spline([
    [jar.cx - m.hw * 0.85, jar.baseY - 3],
    [jar.cx - m.hw * 0.35, m.heelY + 6],
    [jar.cx, m.heelY + 4],
    [jar.cx + m.hw * 0.35, m.heelY + 6],
    [jar.cx + m.hw * 0.85, jar.baseY - 3]
  ], 0.4);

  // 3. Heavy Charcoal-Black Outer Contour Leading of the Jar
  brush.set("leadCame", "#0f0c0a", 2.45);
  for (let i = 0; i < bodyPoly.length; i++) {
    const p1 = bodyPoly[i];
    const p2 = bodyPoly[(i + 1) % bodyPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Rich charcoal over-stroke for textured hand-drawn density
  brush.set("charcoal", "#1c1612", 1.55);
  for (let i = 0; i < bodyPoly.length; i++) {
    const p1 = bodyPoly[i];
    const p2 = bodyPoly[(i + 1) % bodyPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// -----------------------------------------------------------------------------
// PASS 5: HANDWRITTEN LABELS CURLING AT THE EDGES
// -----------------------------------------------------------------------------

function drawJarCurlingLabel(jar) {
  const m = getJarMetrics(jar);
  const labelCY = lerp(m.meniscusY, m.heelY, 0.48);
  const lw = jar.w * 0.66;
  const lh = jar.h * 0.21;
  const lhw = lw / 2;
  const lhh = lh / 2;

  const leftX = jar.cx - lhw;
  const rightX = jar.cx + lhw;
  const topY = labelCY - lhh;
  const botY = labelCY + lhh;

  // Curl offsets on the outer top & bottom corners
  const curlIn = lw * 0.16;
  const curlDrop = lh * 0.22;

  // 1. Dark cast shadows on the glowing glass directly behind the curled-up corners!
  brush.noStroke();
  brush.wash("#140d0a", 215);
  // Left-top & left-bottom curl shadows
  drawPoly([
    [leftX - 5, topY + 2],
    [leftX + curlIn + 4, topY + 2],
    [leftX + curlIn, botY + 6],
    [leftX - 6, botY - 2]
  ], 0.2);
  // Right-top & right-bottom curl shadows
  drawPoly([
    [rightX - curlIn - 4, topY + 2],
    [rightX + 5, topY + 2],
    [rightX + 6, botY - 2],
    [rightX - curlIn, botY + 6]
  ], 0.2);

  // Subtle shadow under the bottom edge of the label
  brush.wash("#1a110d", 170);
  drawPoly([
    [leftX + curlIn * 0.6, botY],
    [rightX - curlIn * 0.6, botY],
    [rightX - curlIn * 0.7, botY + 6],
    [leftX + curlIn * 0.7, botY + 6]
  ]);

  // 2. Main Parchment Label Body (bowed slightly with cylinder, corners peeled inward)
  const labelPoly = [
    [leftX + curlIn * 0.85, topY],
    [jar.cx, topY + 3],
    [rightX - curlIn * 0.85, topY],
    [rightX - curlIn * 0.35, labelCY],
    [rightX - curlIn * 0.9, botY],
    [jar.cx, botY + 3],
    [leftX + curlIn * 0.9, botY],
    [leftX + curlIn * 0.35, labelCY]
  ];

  brush.wash("#efe3ca", 248);
  drawPoly(labelPoly, 0.15);
  brush.noWash();

  // Warm aged parchment stain at edges of label
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.5, 0.45);
  brush.fill("#cbb48c", 85);
  drawPoly(labelPoly, 0.15);
  brush.noFill();

  // 3. Double-Ruled Vintage Apothecary Border in Sepia Ink
  const inset = 6;
  brush.set("rotring", "#4a3525", 0.85);
  brush.spline([
    [leftX + curlIn * 0.85 + inset, topY + inset],
    [jar.cx, topY + 3 + inset],
    [rightX - curlIn * 0.85 - inset, topY + inset]
  ], 0.2);
  brush.spline([
    [leftX + curlIn * 0.9 + inset, botY - inset],
    [jar.cx, botY + 3 - inset],
    [rightX - curlIn * 0.9 - inset, botY - inset]
  ], 0.2);
  brush.line(leftX + curlIn * 0.85 + inset, topY + inset, leftX + curlIn * 0.9 + inset, botY - inset);
  brush.line(rightX - curlIn * 0.85 - inset, topY + inset, rightX - curlIn * 0.9 - inset, botY - inset);

  // Inner thin hairline border
  const inset2 = 9.5;
  brush.set("rotring", "#6e523b", 0.55);
  brush.line(leftX + curlIn + inset2, topY + inset2, rightX - curlIn - inset2, topY + inset2);
  brush.line(leftX + curlIn + inset2, botY - inset2, rightX - curlIn - inset2, botY - inset2);

  // 4. Handwritten Cursive Calligraphy & Ornament on the Label
  // Small botanical sprig / diamond flourish at top center of label
  brush.set("pen", jar.palette.darkPot, 0.8);
  brush.line(jar.cx - 14, topY + 15, jar.cx + 14, topY + 15);
  brush.circle(jar.cx, topY + 15, 2.5, 0.05);

  // Simulated handwritten script for the preserve name (cursive loops & ascenders/descenders)
  drawCalligraphyWord(jar.cx, labelCY - 2, lw * 0.54, jar.flavor);

  // Secondary smaller date line ("1926") below main script
  drawDateScript(jar.cx, labelCY + lh * 0.24, lw * 0.26);

  // 5. The Curled-Back Paper Flaps at Left & Right Corners (showing shaded underside)
  brush.noStroke();
  brush.wash("#d4be98", 245);
  // Top-left curl flap
  const tlCurl = [
    [leftX + curlIn * 0.85, topY],
    [leftX + curlIn * 1.35, topY + curlDrop * 0.65],
    [leftX + curlIn * 0.4, topY + curlDrop * 1.15],
    [leftX + curlIn * 0.35, labelCY * 0.5 + topY * 0.5]
  ];
  drawPoly(tlCurl, 0.25);

  // Bottom-left curl flap
  const blCurl = [
    [leftX + curlIn * 0.9, botY],
    [leftX + curlIn * 1.35, botY - curlDrop * 0.65],
    [leftX + curlIn * 0.4, botY - curlDrop * 1.15],
    [leftX + curlIn * 0.35, labelCY * 0.5 + botY * 0.5]
  ];
  drawPoly(blCurl, 0.25);

  // Top-right curl flap
  const trCurl = [
    [rightX - curlIn * 0.85, topY],
    [rightX - curlIn * 1.35, topY + curlDrop * 0.65],
    [rightX - curlIn * 0.4, topY + curlDrop * 1.15],
    [rightX - curlIn * 0.35, labelCY * 0.5 + topY * 0.5]
  ];
  drawPoly(trCurl, 0.25);

  // Bottom-right curl flap
  const brCurl = [
    [rightX - curlIn * 0.9, botY],
    [rightX - curlIn * 1.35, botY - curlDrop * 0.65],
    [rightX - curlIn * 0.4, botY - curlDrop * 1.15],
    [rightX - curlIn * 0.35, labelCY * 0.5 + botY * 0.5]
  ];
  drawPoly(brCurl, 0.25);
  brush.noWash();

  // Crisp charcoal & sepia outline around the label and its curling flaps
  brush.set("rotring", "#241a12", 1.05);
  for (let i = 0; i < labelPoly.length; i++) {
    const p1 = labelPoly[i];
    const p2 = labelPoly[(i + 1) % labelPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let curl of [tlCurl, blCurl, trCurl, brCurl]) {
    brush.spline([curl[0], curl[1], curl[2], curl[3]], 0.35);
    // Highlight along the rolled spine of the paper curl
    brush.set("glintPen", "#faf3e3", 0.9);
    brush.line(curl[0][0], curl[0][1], curl[2][0], curl[2][1]);
    brush.set("rotring", "#241a12", 1.0);
  }
}

// Expressive iron-gall ink calligraphy simulator for the jar labels
function drawCalligraphyWord(cx, cy, spanW, flavor) {
  const startX = cx - spanW * 0.5;
  const endX = cx + spanW * 0.5;
  const numWaves = flavor === "raspberry" ? 15 : (flavor === "apricot" ? 12 : 11);

  // Capital Initial Flourish
  brush.set("rotring", "#261911", 1.15);
  brush.spline([
    [startX - 4, cy + 5],
    [startX + 2, cy - 10],
    [startX + 9, cy - 8],
    [startX + 5, cy + 4],
    [startX + 11, cy + 2]
  ], 0.45);

  // Connected cursive body with authentic ascenders and descenders
  const pts = [];
  for (let i = 0; i <= numWaves; i++) {
    const t = i / numWaves;
    const x = lerp(startX + 10, endX, t);
    let dy = (i % 2 === 0 ? -3.5 : 3.2);
    // Ascenders ('b', 'd', 't', 'l') and descenders ('p', 'y', 'g')
    if (flavor === "raspberry" && (i === 5 || i === 13)) dy = 10;
    if (flavor === "raspberry" && i === 7) dy = -9;
    if (flavor === "apricot" && i === 2) dy = 9;
    if (flavor === "apricot" && (i === 5 || i === 11)) dy = -8;
    if (flavor === "damson" && i === 1) dy = -9;
    pts.push([x, cy + dy]);
  }
  brush.set("rotring", "#291b12", 1.0);
  brush.spline(pts, 0.45);

  // Delicate underline flourish
  brush.set("rotring", "#543b28", 0.65);
  brush.spline([
    [cx - spanW * 0.36, cy + 12],
    [cx, cy + 10],
    [cx + spanW * 0.36, cy + 12]
  ], 0.3);
}

function drawDateScript(cx, cy, spanW) {
  brush.set("rotring", "#4a3525", 0.7);
  const sx = cx - spanW * 0.5;
  const ex = cx + spanW * 0.5;
  const pts = [];
  for (let i = 0; i <= 7; i++) {
    const x = lerp(sx, ex, i / 7);
    const y = cy + (i % 2 === 0 ? -2 : 2);
    pts.push([x, y]);
  }
  brush.spline(pts, 0.35);
}

// -----------------------------------------------------------------------------
// PASS 6: GINGHAM LIDS (PLEATED CLOTH BONNETS & HEMP TWINE BOWS)
// -----------------------------------------------------------------------------

function drawJarGinghamBonnet(jar) {
  const m = getJarMetrics(jar);
  const pal = jar.palette;

  const capTopY = m.topY;
  const cinchY = m.lidBottomY - 6; // where twine ties around the neck
  const skirtBotY = m.lidBottomY + jar.skirtDrop;

  const capTopHW = m.nHw * 1.03;
  const cinchHW = m.nHw * 0.95;
  const skirtBotHW = m.hw * 1.08; // flares out wider than the jar shoulder!

  const numPleats = 9;

  // Build scalloped bottom hem points of the pleated gingham skirt
  const hemPts = [];
  const pleatSteps = numPleats * 2;
  for (let i = 0; i <= pleatSteps; i++) {
    const t = i / pleatSteps;
    const x = lerp(jar.cx - skirtBotHW, jar.cx + skirtBotHW, t);
    const archCurve = sin(t * 180) * 8;
    const pleatWave = (i % 2 === 0 ? -4.5 : 4.5);
    hemPts.push([x, skirtBotY + archCurve + pleatWave]);
  }

  // 1. Cast shadow of the ruffled gingham skirt onto the glass shoulder below
  const shadowPts = [
    [jar.cx - m.hw + 2, cinchY + 12],
    [jar.cx + m.hw - 2, cinchY + 12]
  ];
  for (let i = hemPts.length - 1; i >= 0; i--) {
    const hx = constrain(hemPts[i][0], jar.cx - m.hw + 2, jar.cx + m.hw - 2);
    shadowPts.push([hx, hemPts[i][1] + 13]);
  }
  brush.noStroke();
  brush.wash("#140c09", 185);
  drawPoly(shadowPts, 0.15);

  // 2. Base Linen/Ecru Fabric Shape (Top Crown + Flared Skirt)
  const bonnetPoly = [
    [jar.cx - capTopHW * 0.92, capTopY + 5],
    [jar.cx, capTopY],
    [jar.cx + capTopHW * 0.92, capTopY + 5],
    [jar.cx + capTopHW, cinchY - 12],
    [jar.cx + cinchHW, cinchY]
  ];
  for (let i = hemPts.length - 1; i >= 0; i--) {
    bonnetPoly.push(hemPts[i]);
  }
  bonnetPoly.push([jar.cx - cinchHW, cinchY]);
  bonnetPoly.push([jar.cx - capTopHW, cinchY - 12]);

  brush.wash(pal.ginghamLight, 248);
  drawPoly(bonnetPoly, 0.12);
  brush.noWash();

  // Warm backlit parchment glow on the outer ruffled edges of the cloth
  brush.fillBleed(0.2, "in");
  brush.fillTexture(0.5, 0.4);
  brush.fill("#d4c3a3", 85);
  drawPoly(bonnetPoly, 0.12);
  brush.noFill();

  // 3. Woven Gingham Check Pattern (Following the 3D Folds of Crown & Skirt)
  // Vertical warp stripes across the crown and radiating down the pleated skirt
  brush.noStroke();
  for (let i = 0; i < pleatSteps; i += 2) {
    const t1 = i / pleatSteps;
    const t2 = (i + 1) / pleatSteps;

    // Crown vertical stripe
    const cx1 = lerp(jar.cx - capTopHW, jar.cx + capTopHW, t1);
    const cx2 = lerp(jar.cx - capTopHW, jar.cx + capTopHW, t2);
    const nx1 = lerp(jar.cx - cinchHW, jar.cx + cinchHW, t1);
    const nx2 = lerp(jar.cx - cinchHW, jar.cx + cinchHW, t2);

    brush.wash(pal.ginghamMid, 165);
    drawPoly([
      [cx1, capTopY + 4],
      [cx2, capTopY + 4],
      [nx2, cinchY],
      [nx1, cinchY]
    ]);

    // Skirt radiating pleat stripe
    const sx1 = hemPts[i][0];
    const sy1 = hemPts[i][1];
    const sx2 = hemPts[i + 1][0];
    const sy2 = hemPts[i + 1][1];

    drawPoly([
      [nx1, cinchY],
      [nx2, cinchY],
      [sx2, sy2],
      [sx1, sy1]
    ]);
  }

  // Horizontal weft stripes across the crown (2 bands) and skirt (2 bands)
  // Where horizontal weft crosses vertical warp, we draw darker gingham intersection squares!
  const hBands = [
    { y1: capTopY + 10, y2: capTopY + 21, w1: capTopHW * 0.98, w2: capTopHW },
    { y1: capTopY + 30, y2: cinchY - 4, w1: capTopHW, w2: cinchHW * 1.02 },
    { y1: cinchY + 7, y2: cinchY + 19, w1: cinchHW * 1.03, w2: lerp(cinchHW, skirtBotHW, 0.45) },
    { y1: cinchY + 27, y2: skirtBotY - 2, w1: lerp(cinchHW, skirtBotHW, 0.65), w2: skirtBotHW * 0.98 }
  ];

  for (let b of hBands) {
    brush.wash(pal.ginghamMid, 155);
    drawPoly([
      [jar.cx - b.w1, b.y1],
      [jar.cx + b.w1, b.y1],
      [jar.cx + b.w2, b.y2],
      [jar.cx - b.w2, b.y2]
    ]);

    // Dark gingham check intersections
    brush.wash(pal.ginghamDark, 195);
    for (let i = 0; i < pleatSteps; i += 2) {
      const t1 = i / pleatSteps;
      const t2 = (i + 1) / pleatSteps;
      const ix1Top = lerp(jar.cx - b.w1, jar.cx + b.w1, t1);
      const ix2Top = lerp(jar.cx - b.w1, jar.cx + b.w1, t2);
      const ix1Bot = lerp(jar.cx - b.w2, jar.cx + b.w2, t1);
      const ix2Bot = lerp(jar.cx - b.w2, jar.cx + b.w2, t2);
      drawPoly([
        [ix1Top, b.y1],
        [ix2Top, b.y1],
        [ix2Bot, b.y2],
        [ix1Bot, b.y2]
      ]);
    }
  }
  brush.noWash();

  // 4. Deep Pleat Crease Lines & Woven Thread Texture
  brush.set("2B", "#2b2119", 0.95);
  for (let i = 1; i < pleatSteps; i += 2) {
    const t = i / pleatSteps;
    const nx = lerp(jar.cx - cinchHW, jar.cx + cinchHW, t);
    const hx = hemPts[i][0];
    const hy = hemPts[i][1];
    // Pleat valley shadow line
    brush.line(nx, cinchY, hx, hy);
    // Upper crown gather crease
    const tx = lerp(jar.cx - capTopHW * 0.85, jar.cx + capTopHW * 0.85, t);
    brush.line(nx, cinchY, tx, capTopY + 12);
  }

  // Heavy charcoal outline around the gingham bonnet & scalloped hem
  brush.set("leadCame", "#17120e", 1.75);
  brush.spline([
    [jar.cx - capTopHW, cinchY - 12],
    [jar.cx - capTopHW * 0.92, capTopY + 5],
    [jar.cx, capTopY],
    [jar.cx + capTopHW * 0.92, capTopY + 5],
    [jar.cx + capTopHW, cinchY - 12]
  ], 0.35);
  brush.line(jar.cx - capTopHW, cinchY - 12, jar.cx - cinchHW, cinchY);
  brush.line(jar.cx + capTopHW, cinchY - 12, jar.cx + cinchHW, cinchY);
  brush.spline(hemPts, 0.35);
  brush.line(jar.cx - cinchHW, cinchY, hemPts[0][0], hemPts[0][1]);
  brush.line(jar.cx + cinchHW, cinchY, hemPts[hemPts.length - 1][0], hemPts[hemPts.length - 1][1]);

  // 5. Natural Hemp Twine Wrapped Around the Neck & Symmetrical Bow
  // Multiple twine strands cinched at cinchY
  for (let s = -1; s <= 1; s++) {
    const ty = cinchY + s * 2.5;
    brush.set("cpencil", "#4a3723", 1.5);
    brush.spline([
      [jar.cx - cinchHW - 2, ty - 2],
      [jar.cx, ty + 3],
      [jar.cx + cinchHW + 2, ty - 2]
    ], 0.3);
    brush.set("glintPen", "#d4b587", 0.85);
    brush.spline([
      [jar.cx - cinchHW, ty - 3],
      [jar.cx, ty + 2],
      [jar.cx + cinchHW, ty - 3]
    ], 0.3);
  }

  // Symmetrical Twine Bow at (jar.cx, cinchY + 2)
  const bowY = cinchY + 2;
  const loopW = 24;
  const loopH = 12;

  // Bow shadow on skirt
  brush.noStroke();
  brush.wash("#1a120c", 180);
  brush.circle(jar.cx, bowY + 4, 16, 0.1);
  brush.noWash();

  // Left & Right twine bow loops + hanging tails
  for (let side of [-1, 1]) {
    // Dark twine base
    brush.set("leadCame", "#3b2a19", 1.45);
    brush.spline([
      [jar.cx, bowY],
      [jar.cx + side * loopW * 0.7, bowY - loopH],
      [jar.cx + side * loopW, bowY + 2],
      [jar.cx + side * loopW * 0.5, bowY + loopH * 0.6],
      [jar.cx, bowY + 1]
    ], 0.45);
    // Hanging twine tail
    brush.spline([
      [jar.cx + side * 2, bowY + 2],
      [jar.cx + side * 12, bowY + 24],
      [jar.cx + side * 19, bowY + 46]
    ], 0.35);

    // Warm hemp highlight on twine loop & tail
    brush.set("glintPen", "#dec092", 0.9);
    brush.spline([
      [jar.cx, bowY - 1],
      [jar.cx + side * loopW * 0.7, bowY - loopH + 1],
      [jar.cx + side * loopW * 0.95, bowY + 1]
    ], 0.45);
    brush.spline([
      [jar.cx + side * 2, bowY + 2],
      [jar.cx + side * 11, bowY + 23],
      [jar.cx + side * 18, bowY + 44]
    ], 0.35);
  }

  // Center knot of the twine bow
  brush.noStroke();
  brush.wash("#b89564", 240);
  brush.circle(jar.cx, bowY, 4.5, 0.05);
  brush.noWash();
  brush.set("rotring", "#2b1d10", 0.9);
  brush.circle(jar.cx, bowY, 4.5, 0.05);
}

// -----------------------------------------------------------------------------
// PASS 7: SHARP WHITE GLINTS ON JAR RIMS, SHOULDERS & REFRACTION BARS
// -----------------------------------------------------------------------------

function drawJarSharpGlints(jar) {
  const m = getJarMetrics(jar);

  // 1. Sharp White Glints on the Molded Glass Shoulder Rim (just below the gingham skirt)
  const rimY = m.shoulderY + 8;
  const leftRimX = jar.cx - m.hw + 7;
  const rightRimX = jar.cx + m.hw - 7;

  // Opaque razor-sharp white specular crescents on the glass rim bevels
  brush.noStroke();
  brush.wash("#ffffff", 240);
  drawPoly([
    [leftRimX, rimY],
    [leftRimX + 26, rimY + 6],
    [leftRimX + 22, rimY + 12],
    [leftRimX + 2, rimY + 8]
  ]);
  drawPoly([
    [rightRimX - 26, rimY + 6],
    [rightRimX, rimY],
    [rightRimX - 2, rimY + 8],
    [rightRimX - 22, rimY + 12]
  ]);

  // 2. Vertical Cylindrical Specular Glint Bars along Left & Right Glass Walls
  const barTopY = m.meniscusY + 10;
  const barBotY = m.heelY - 14;
  const barXLeft = jar.cx - m.hw + 9;
  const barXRight = jar.cx + m.hw - 9;

  // Upper vertical glint segment
  brush.wash("#fffdf5", 225);
  drawPoly([
    [barXLeft, barTopY],
    [barXLeft + 5.5, barTopY + 4],
    [barXLeft + 4.5, barTopY + (barBotY - barTopY) * 0.42],
    [barXLeft, barTopY + (barBotY - barTopY) * 0.42]
  ]);
  drawPoly([
    [barXRight - 5.5, barTopY + 4],
    [barXRight, barTopY],
    [barXRight, barTopY + (barBotY - barTopY) * 0.42],
    [barXRight - 4.5, barTopY + (barBotY - barTopY) * 0.42]
  ]);

  // Lower vertical glint segment
  drawPoly([
    [barXLeft, barTopY + (barBotY - barTopY) * 0.56],
    [barXLeft + 4.5, barTopY + (barBotY - barTopY) * 0.56],
    [barXLeft + 5.5, barBotY - 4],
    [barXLeft, barBotY]
  ]);
  drawPoly([
    [barXRight - 4.5, barTopY + (barBotY - barTopY) * 0.56],
    [barXRight, barTopY + (barBotY - barTopY) * 0.56],
    [barXRight, barBotY],
    [barXRight - 5.5, barBotY - 4]
  ]);
  brush.noWash();

  // 3. Razor-Sharp Stroke Glints along Meniscus Rim, Heel Rim & Glass Threads
  brush.set("glintPen", "#ffffff", 1.35);
  // Meniscus rim glints catching transmitted light
  brush.line(jar.cx - m.hw + 12, m.meniscusY - 2, jar.cx - m.hw + 44, m.meniscusY + 2);
  brush.line(jar.cx + m.hw - 44, m.meniscusY + 2, jar.cx + m.hw - 12, m.meniscusY - 2);

  // Center meniscus sparkle
  brush.set("glintPen", "#fffef7", 1.1);
  brush.line(jar.cx - 18, m.meniscusY + 4, jar.cx + 18, m.meniscusY + 4);

  // Thick glass base heel rim glints (left, center punt, right)
  brush.set("glintPen", "#ffffff", 1.45);
  brush.line(jar.cx - m.hw + 8, m.heelY + 3, jar.cx - m.hw + 38, m.heelY + 7);
  brush.line(jar.cx + m.hw - 38, m.heelY + 7, jar.cx + m.hw - 8, m.heelY + 3);
  brush.line(jar.cx - 26, jar.baseY - 6, jar.cx + 26, jar.baseY - 6);

  // Glass neck ring glints peeking right through/under the gingham pleats
  brush.set("glintPen", "#ffffff", 1.25);
  brush.line(jar.cx - m.nHw + 10, m.lidBottomY + 18, jar.cx - m.nHw + 28, m.lidBottomY + 20);
  brush.line(jar.cx + m.nHw - 28, m.lidBottomY + 20, jar.cx + m.nHw - 10, m.lidBottomY + 18);
}

