function drawForegroundTieIn(jars) {
  // Heavy charcoal leading line along the front edge of the kitchen sill
  brush.set("leadCame", "#14100d", 2.3);
  brush.line(0, SILL_FRONT_Y, 1200, SILL_FRONT_Y);
  brush.set("leadCame", "#14100d", 1.8);
  brush.line(0, SILL_BOTTOM_Y, 1200, SILL_BOTTOM_Y);

  // Back edge of the sill between the jars
  brush.set("leadCame", "#1c1612", 1.6);
  brush.line(ARCH_LEFT, SILL_Y, jars[0].cx - jars[0].w * 0.48, SILL_Y);
  brush.line(jars[0].cx + jars[0].w * 0.48, SILL_Y, jars[2].cx - jars[2].w * 0.48, SILL_Y);
  brush.line(jars[2].cx + jars[2].w * 0.48, SILL_Y, jars[4].cx - jars[4].w * 0.48, SILL_Y);
  brush.line(jars[4].cx + jars[4].w * 0.48, SILL_Y, jars[3].cx - jars[3].w * 0.48, SILL_Y);
  brush.line(jars[3].cx + jars[3].w * 0.48, SILL_Y, jars[1].cx - jars[1].w * 0.48, SILL_Y);
  brush.line(jars[1].cx + jars[1].w * 0.48, SILL_Y, ARCH_RIGHT, SILL_Y);

  // Bright caustic focal lines on the sill lip directly in front of each jar
  for (let jar of jars) {
    brush.set("glintPen", jar.palette.hotCore, 1.35);
    brush.line(jar.cx - 24, SILL_FRONT_Y - 2, jar.cx + 24, SILL_FRONT_Y - 2);
    brush.set("glintPen", "#fffdf5", 1.1);
    brush.line(jar.cx - 10, SILL_FRONT_Y - 1, jar.cx + 10, SILL_FRONT_Y - 1);
  }

  // Subtle double-ruled museum border around the entire 1200x1200 plate
  brush.set("leadCame", "#1a1410", 2.2);
  brush.rect(16, 16, 1168, 1168);
  brush.set("rotring", "#3d3024", 0.9);
  brush.rect(24, 24, 1152, 1152);
}

