function draw() {
  translate(-width / 2, -height / 2);
  background("#0d121a");
  brush.noField();

  // 1. DIM WORKSHOP BACKGROUND & RAKING SIDE LIGHT
  drawWorkshopBackground();

  // 2. LADDER STRUCTURE (BACK RAILS, LOWER RUNGS & SHADOWS)
  const ladder = getLadderGeometry();
  drawLadderBaseAndLowerRungs(ladder);

  // 3. HANGING LINEN PANELS (BACK LAYER FOLD TAILS FIRST)
  const panels = getPanelConfigs();
  for (let p of panels) {
    drawPanelBackTail(p);
  }

  // 4. UPPER LADDER RUNGS (WHERE CLOTHS WRAP OVER)
  drawUpperLadderRungs(ladder);

  // 5. HYPERREAL WET ARASHI LINEN PANELS (WATERCOLOR + VOLUMETRIC DRAPERY)
  for (let p of panels) {
    drawHyperrealLinenPanel(p, ladder);
  }

  // 6. FOREGROUND VAT LIQUID, RIPPLES & STAINED VAT RIM
  drawIndigoVatAndRim(panels);

  // 7. FALLING DROPLETS, DRIP THREADS & RAKING LIGHT ATMOSPHERE
  for (let p of panels) {
    drawPanelDropletsAndDrips(p);
  }
  drawAtmosphericSideLight();

  noLoop();
}

// ============================================================================
// 1. WORKSHOP BACKGROUND & DUSKY TWILIGHT RAKING LIGHT
// ============================================================================
function drawWorkshopBackground() {
  brush.noStroke();

  // Deep twilight shadow washes on right and bottom
  const darkZones = [
    [[0, 0], [1200, 0], [1200, 1200], [0, 1200]],
    [[450, 0], [1200, 0], [1200, 1100], [250, 1100]],
    [[720, 0], [1200, 0], [1200, 1200], [580, 1200]]
  ];
  for (let poly of darkZones) {
    brush.wash("#0b1018", 110);
    drawPolyShape(poly, 0.1);
  }
  brush.noWash();

  // Dusky twilight raking light beam from upper-left
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.5, 0.2);

  const lightBeams = [
    { col: "#1e2938", alpha: 75, pts: [[0, 0], [780, 0], [520, 980], [0, 820]] },
    { col: "#283647", alpha: 65, pts: [[0, 0], [560, 0], [380, 880], [0, 680]] },
    { col: "#364554", alpha: 55, pts: [[0, 40], [380, 120], [260, 720], [0, 540]] },
    { col: "#4c565e", alpha: 42, pts: [[0, 80], [240, 160], [160, 520], [0, 400]] }
  ];
  for (let b of lightBeams) {
    brush.fill(b.col, b.alpha);
    drawPolyShape(b.pts, 0.2);
  }
  brush.noFill();

  // Subtle vertical weathered timber planks on workshop wall
  const plankX = [95, 215, 340, 470, 605, 740, 875, 1015, 1140];
  for (let i = 0; i < plankX.length; i++) {
    let x = plankX[i];
    let litFactor = map(x, 0, 1200, 1.0, 0.15);
    brush.set("charcoal", "#080b11", 1.2);
    brush.line(x + random(-3, 3), 0, x + random(-4, 4), 1020);

    if (litFactor > 0.35) {
      brush.set("2B", "#3d4854", 0.65 * litFactor);
      brush.line(x + 2, 40, x + 2, 780);
    }

    // Faint vertical wood texture in background
    for (let k = 0; k < 14; k++) {
      let gx = x - 110 + random(10, 105);
      let gy1 = random(0, 700);
      let gy2 = gy1 + random(80, 260);
      let col = gx < 450 ? (random() < 0.5 ? "#232e3c" : "#2f3842") : "#141b24";
      brush.set("soft_wash", col, random(0.6, 1.4));
      brush.line(gx, gy1, gx + random(-2, 2), gy2);
    }
  }
}

// ============================================================================
// 2. WOODEN LADDER GEOMETRY & RENDERING
// ============================================================================
function getLadderGeometry() {
  // Leaning heavy wooden workshop ladder in slight three-quarter perspective
  const leftRailTop = { x: 205, y: 20 };
  const leftRailBot = { x: 68, y: 1050 };
  const rightRailTop = { x: 935, y: 55 };
  const rightRailBot = { x: 1115, y: 1050 };

  const rungT = [0.125, 0.255, 0.405, 0.565, 0.735, 0.905];
  const rungs = rungT.map((t, idx) => {
    let lx = lerp(leftRailTop.x, leftRailBot.x, t);
    let ly = lerp(leftRailTop.y, leftRailBot.y, t);
    let rx = lerp(rightRailTop.x, rightRailBot.x, t);
    let ry = lerp(rightRailTop.y, rightRailBot.y, t);
    let radius = lerp(12, 17, t);
    return { idx, t, lx, ly, rx, ry, radius };
  });

  return { leftRailTop, leftRailBot, rightRailTop, rightRailBot, rungs };
}

function drawWoodenBeam(x1, y1, x2, y2, w1, w2, isRail, sideLit) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  // Base shadow wash
  brush.noStroke();
  brush.wash("#1c1510", 190);
  drawPolyShape([
    [x1 - nx * w1, y1 - ny * w1],
    [x2 - nx * w2, y2 - ny * w2],
    [x2 + nx * w2, y2 + ny * w2],
    [x1 + nx * w1, y1 + ny * w1]
  ], 0.05);
  brush.noWash();

  // Wood grain fibers along the beam
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let offset = lerp(-1, 1, f);
    let sx1 = x1 + nx * w1 * offset;
    let sy1 = y1 + ny * w1 * offset;
    let sx2 = x2 + nx * w2 * offset;
    let sy2 = y2 + ny * w2 * offset;

    // Determine wood color from cylindrical/chamfered lighting + indigo stains
    let col;
    if (f < 0.22) {
      col = sideLit ? (f < 0.1 ? "#c7b199" : "#9c826b") : "#6e5643";
    } else if (f < 0.55) {
      col = sideLit ? "#5c4534" : "#423125";
    } else if (f < 0.82) {
      col = "#261c15";
    } else {
      // Reflected indigo light on underside/shadow edge
      col = "#1a2838";
    }

    brush.set(f < 0.2 ? "cpencil" : "2B", col, random(0.7, 1.35));
    let midX = lerp(sx1, sx2, 0.5) + nx * random(-1.5, 1.5);
    let midY = lerp(sy1, sy2, 0.5) + ny * random(-1.5, 1.5);
    brush.spline([[sx1, sy1, 0.7], [midX, midY, 1.0], [sx2, sy2, 0.7]], 0.3);
  }

  // Indigo dye stains and wet dark marks on the wood
  for (let s = 0; s < 9; s++) {
    let t1 = random(0.08, 0.85);
    let t2 = constrain(t1 + random(0.04, 0.14), 0, 0.96);
    let off = random(-0.7, 0.7);
    let px1 = lerp(x1, x2, t1) + nx * lerp(w1, w2, t1) * off;
    let py1 = lerp(y1, y2, t1) + ny * lerp(w1, w2, t1) * off;
    let px2 = lerp(x1, x2, t2) + nx * lerp(w1, w2, t2) * off;
    let py2 = lerp(y1, y2, t2) + ny * lerp(w1, w2, t2) * off;
    brush.set("arashi_bleed", random() < 0.6 ? "#11243b" : "#1c3b40", random(0.6, 1.2));
    brush.line(px1, py1, px2, py2);
  }

  // Sharp raking highlight along top/left edge
  brush.set("wet_glint", sideLit ? "#dfd2c3" : "#8f7965", 0.85);
  brush.line(
    x1 - nx * w1 * 0.85,
    y1 - ny * w1 * 0.85,
    x2 - nx * w2 * 0.85,
    y2 - ny * w2 * 0.85
  );
}

function drawLadderBaseAndLowerRungs(ladder) {
  // Draw lower rungs 2, 3, 4, 5 first (behind hanging cloth panels)
  for (let i = 2; i < ladder.rungs.length; i++) {
    let r = ladder.rungs[i];
    drawWoodenBeam(r.lx, r.ly, r.rx, r.ry, r.radius, r.radius * 1.05, false, true);
  }

  // Draw Left Rail (strongly lit by left side-light)
  drawWoodenBeam(
    ladder.leftRailTop.x, ladder.leftRailTop.y,
    ladder.leftRailBot.x, ladder.leftRailBot.y,
    18, 25, true, true
  );

  // Draw Right Rail (further right in dusky shadow, inner face catches raking light)
  drawWoodenBeam(
    ladder.rightRailTop.x, ladder.rightRailTop.y,
    ladder.rightRailBot.x, ladder.rightRailBot.y,
    19, 27, true, false
  );

  // Mortise tenon dark joints on rails
  for (let r of ladder.rungs) {
    brush.set("charcoal", "#120c08", 1.1);
    brush.circle(r.lx - 4, r.ly, 6, 0.25);
    brush.circle(r.rx + 5, r.ry, 7, 0.25);
  }
}

function drawUpperLadderRungs(ladder) {
  // Rung 0 and Rung 1 drawn after back cloth tails so front cloths wrap over them convincingly
  for (let i = 0; i <= 1; i++) {
    let r = ladder.rungs[i];
    drawWoodenBeam(r.lx, r.ly, r.rx, r.ry, r.radius, r.radius * 1.05, false, true);
  }
}

