// Evaluates 3D position, normal, fold height, arashi resist, and oxidation at (u, v) in [0,1]^2
function evalClothPoint(panel, ladder, u, v) {
  let rung = ladder.rungs[panel.rungIdx];
  let topX1 = lerp(rung.lx, rung.rx, panel.uStart);
  let topY1 = lerp(rung.ly, rung.ry, panel.uStart);
  let topX2 = lerp(rung.lx, rung.rx, panel.uEnd);
  let topY2 = lerp(rung.ly, rung.ry, panel.uEnd);

  let baseTopX = lerp(topX1, topX2, u);
  let baseTopY = lerp(topY1, topY2, u);
  let panelW = topX2 - topX1;

  // Weighty wet sag: horizontal inward cling in middle, slight flare & heavy droop at hem
  let wetPinch = sin(v * 170) * 0.055 * (1 - 0.3 * v);
  let uPinched = 0.5 + (u - 0.5) * (1 - wetPinch);
  let x = lerp(topX1, topX2, uPinched);

  // Subtle lateral sway from heavy wet drape
  let sway = sin(v * 140 + panel.id * 55) * 6 * v;
  x += sway;

  // Vertical coordinate from top of rung (v=0) to sagging hem (v=1)
  let topWrapOffset = -rung.radius * 0.95 * cos(constrain(v / 0.06, 0, 1) * 90);
  let yLinear = lerp(baseTopY, panel.yBottom, v) + (v < 0.06 ? topWrapOffset : 0);

  // Multi-harmonic vertical fold flutes
  let foldEnv = pow(constrain(v, 0.01, 1), 0.55);
  let waveAngle = u * panel.foldCount * 360 + panel.foldPhase * 57 + v * 38 * sin(u * 180);
  let primaryWave = sin(waveAngle);
  let secondaryWave = 0.42 * sin(waveAngle * 2.0 + 35) + 0.18 * cos(waveAngle * 3.0 - 20);
  let crinkleNoise = (noise(u * 8 + panel.id * 10, v * 12) - 0.5) * 0.7;

  let zFold = (primaryWave + secondaryWave + crinkleNoise) * panel.foldDepth * foldEnv;

  // Horizontal gathering around fold crests & troughs
  let dxFold = cos(waveAngle) * (panel.foldDepth * 0.55) * foldEnv;
  x += dxFold;

  // Weighty wet catenary sag at the hem and in heavy fold bellies
  let catenarySag = sin(u * 180) * 26 * pow(v, 1.4);
  let fluteSag = (primaryWave * 0.5 + 0.5) * 18 * pow(v, 1.6);
  let y = yLinear + catenarySag + fluteSag;

  // Interaction with underlying ladder rungs (gentle forward bulge when hanging over lower rungs)
  for (let rIdx = panel.rungIdx + 1; rIdx < ladder.rungs.length; rIdx++) {
    let lr = ladder.rungs[rIdx];
    let rungYAtX = lerp(lr.ly, lr.ry, constrain((x - lr.lx) / (lr.rx - lr.lx), 0, 1));
    let distY = abs(y - rungYAtX);
    if (distY < 32) {
      let bump = cos((distY / 32) * 90);
      zFold += bump * 6;
      x -= bump * 2.5;
    }
  }

  // Approximate surface normal nx (positive = facing left toward raking side-light)
  let nx = -cos(waveAngle) * foldEnv - (u - 0.5) * 0.35;
  // Left edge of panel strongly faces left light
  if (u < 0.12) nx += map(u, 0, 0.12, 1.1, 0);
  if (u > 0.88) nx -= map(u, 0.88, 1.0, 0, 0.8);

  // Arashi pole-wrap diagonal phase (warped organically by 3D folds and wet sag)
  let slope = tan(panel.arashiAngle);
  let aspect = (panel.yBottom - baseTopY) / panelW;
  let diagCoord = u + v * aspect * slope * 0.42 + zFold * 0.0028;
  let nWarp = (noise(u * 6 + panel.id * 7, v * 9 + panel.id * 3) - 0.5) * 0.16;
  let arashiPhase = (diagCoord + nWarp) * panel.arashiFreq;
  let bandFract = arashiPhase - floor(arashiPhase);

  // Distance from the center of the resist ridge (0 = tightest pole wrap ghost line, 0.5 = deepest indigo dye)
  let distFromRidge = abs(bandFract - 0.5) * 2.0; // 0 at center, 1 at edge
  let resist = pow(constrain(1.0 - distFromRidge, 0, 1), 2.2);

  // Secondary micro-pleat ghost line within each arashi wrap
  let subPleat = pow(constrain(1.0 - abs(bandFract - 0.22) * 5.0, 0, 1), 3.0) * 0.55;
  resist = max(resist, subPleat);

  // Green oxidation concentration (strongest at air-exposed edges, top fold, and damp lower patches)
  let edgeFactor = pow(constrain(1.0 - min(u, 1.0 - u) / 0.22, 0, 1), 1.5);
  let hemFactor = pow(constrain((v - 0.65) / 0.35, 0, 1), 1.3);
  let topFactor = pow(constrain((0.2 - v) / 0.2, 0, 1), 1.4);
  let patchNoise = noise(u * 4.5 + panel.id * 13, v * 5.5 + 9);
  let oxidation = constrain((edgeFactor * 0.65 + hemFactor * 0.45 + topFactor * 0.35) * patchNoise * 1.8 * panel.oxidStrength, 0, 1);

  return { x, y, z: zFold, nx, resist, oxidation, primaryWave, bandFract, panelW };
}

// ============================================================================
// 4. BACK LAYER FOLD TAILS (HANGING BEHIND THE RUNGS)
// ============================================================================
function drawPanelBackTail(panel) {
  let ladder = getLadderGeometry();
  // The back half of the linen length hanging behind the front half, slightly shorter and shifted right/down in shadow
  let tailBottom = panel.yBottom - 55;
  let outline = [];
  let steps = 18;

  for (let i = 0; i <= steps; i++) {
    let v = i / steps;
    let pt = evalClothPoint(panel, ladder, 0.02, v);
    outline.push([pt.x - 10, lerp(pt.y, tailBottom, 0.12)]);
  }
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let pt = evalClothPoint(panel, ladder, u, 1.0);
    outline.push([pt.x + (u - 0.5) * 18, pt.y - 42 + sin(u * 540) * 8]);
  }
  for (let i = steps; i >= 0; i--) {
    let v = i / steps;
    let pt = evalClothPoint(panel, ladder, 0.98, v);
    outline.push([pt.x + 12, lerp(pt.y, tailBottom, 0.12)]);
  }

  brush.noStroke();
  brush.wash("#071221", 215);
  drawPolyShape(outline, 0.15);
  brush.noWash();

  // Faint diagonal arashi ghost lines on the shadowed back layer
  for (let k = 0; k < 22; k++) {
    let vStart = random(0.15, 0.92);
    let u1 = random() < 0.5 ? 0.0 : 0.78;
    let u2 = u1 + 0.2;
    let p1 = evalClothPoint(panel, ladder, u1, vStart);
    let p2 = evalClothPoint(panel, ladder, u2, constrain(vStart + 0.08, 0, 0.95));
    brush.set("2B", "#1d3854", 0.7);
    brush.line(p1.x - 6, p1.y - 35, p2.x + 6, p2.y - 35);
  }
}

// ============================================================================
// 5. HYPERREAL LINEN PANEL RENDERING (WATERCOLOR + ARASHI + FOLDS)
// ============================================================================
function drawHyperrealLinenPanel(panel, ladder) {
  // --- PASS A: Solid dark base silhouette so background never leaks through wet linen ---
  let silPts = [];
  let edgeSteps = 32;
  for (let i = 0; i <= edgeSteps; i++) {
    let u = i / edgeSteps;
    let p = evalClothPoint(panel, ladder, u, 0);
    silPts.push([p.x, p.y - 6]);
  }
  for (let i = 1; i <= edgeSteps; i++) {
    let v = i / edgeSteps;
    let p = evalClothPoint(panel, ladder, 1, v);
    silPts.push([p.x, p.y]);
  }
  for (let i = edgeSteps; i >= 0; i--) {
    let u = i / edgeSteps;
    let p = evalClothPoint(panel, ladder, u, 1);
    silPts.push([p.x, p.y]);
  }
  for (let i = edgeSteps - 1; i >= 1; i--) {
    let v = i / edgeSteps;
    let p = evalClothPoint(panel, ladder, 0, v);
    silPts.push([p.x, p.y]);
  }

  brush.noStroke();
  brush.wash(panel.palette.mid, 210);
  drawPolyShape(silPts, 0.1);
  brush.noWash();

  // --- PASS B: Layered Watercolor Indigo, Woad & Oxidized Green Patches ---
  // Group watercolor patches by color for fast caching and authentic wet bleed
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.6, 0.35);

  let colsU = 5;
  let rowsV = 7;
  let batches = {
    pale: [],
    woad: [],
    oxid: [],
    mid: [],
    deep: []
  };

  for (let iu = 0; iu < colsU; iu++) {
    for (let iv = 0; iv < rowsV; iv++) {
      let u0 = constrain((iu - 0.15) / colsU, 0, 1);
      let u1 = constrain((iu + 1.15) / colsU, 0, 1);
      let v0 = constrain((iv - 0.12) / rowsV, 0, 1);
      let v1 = constrain((iv + 1.12) / rowsV, 0, 1);

      let midPt = evalClothPoint(panel, ladder, (u0 + u1) * 0.5, (v0 + v1) * 0.5);
      let p00 = evalClothPoint(panel, ladder, u0, v0);
      let p10 = evalClothPoint(panel, ladder, u1, v0);
      let p11 = evalClothPoint(panel, ladder, u1, v1);
      let p01 = evalClothPoint(panel, ladder, u0, v1);

      let poly = [[p00.x, p00.y], [p10.x, p10.y], [p11.x, p11.y], [p01.x, p01.y]];

      if (midPt.oxidation > 0.35) {
        batches.oxid.push(poly);
      } else if (midPt.nx > 0.25 && iv < rowsV - 2) {
        batches.pale.push(poly);
      } else if (iv >= rowsV - 2 || midPt.nx < -0.25) {
        batches.deep.push(poly);
      } else if (midPt.resist > 0.35) {
        batches.woad.push(poly);
      } else {
        batches.mid.push(poly);
      }
    }
  }

  const batchDefs = [
    { key: "pale", col: panel.palette.pale, alpha: 95 },
    { key: "woad", col: panel.palette.woad, alpha: 105 },
    { key: "oxid", col: panel.palette.oxidLight, alpha: 90 },
    { key: "mid", col: panel.palette.mid, alpha: 110 },
    { key: "deep", col: panel.palette.deep, alpha: 125 }
  ];

  for (let b of batchDefs) {
    for (let poly of batches[b.key]) {
      brush.fill(b.col, b.alpha);
      drawPolyShape(poly, 0.25);
    }
  }
  brush.noFill();

  // --- PASS C: Diagonal Arashi Pole-Wrap Resist Streaks & Watercolor Bleeds ---
  // Trace along the diagonal arashi wraps so every band warps naturally over the 3D vertical folds
  let vSlices = 145;
  let uSamples = 18;

  for (let iv = 0; iv <= vSlices; iv++) {
    let v = iv / vSlices;
    // Trace diagonal trajectories starting from this v
    for (let s = 0; s < 2; s++) {
      let uStart = s === 0 ? random(0.0, 0.35) : random(0.32, 0.72);
      let uSpan = random(0.28, 0.48);
      let uEnd = constrain(uStart + uSpan, 0, 1);

      let pts = [];
      let avgResist = 0;
      let avgOxid = 0;
      let avgNx = 0;

      let segs = 7;
      for (let k = 0; k <= segs; k++) {
        let t = k / segs;
        let uk = lerp(uStart, uEnd, t);
        // Move v along the arashi diagonal angle so the stroke follows the pole-wrap resist line
        let slopeDir = panel.arashiAngle > 0 ? -1 : 1;
        let vk = constrain(v + (uk - uStart) * 0.24 * slopeDir, 0.005, 0.995);
        let cp = evalClothPoint(panel, ladder, uk, vk);
        pts.push([cp.x, cp.y, 0.65 + 0.5 * sin(t * 180)]);
        avgResist += cp.resist;
        avgOxid += cp.oxidation;
        avgNx += cp.nx;
      }

      avgResist /= (segs + 1);
      avgOxid /= (segs + 1);
      avgNx /= (segs + 1);

      // Choose brush & pigment based on arashi resist, oxidation, vertical wet saturation, and raking light
      if (avgResist > 0.56) {
        // White / pale woad ghost reserve band with soft indigo bleed edges
        brush.set("arashi_bleed", avgOxid > 0.35 ? panel.palette.oxidBright : panel.palette.pale, random(0.75, 1.25));
        brush.spline(pts, 0.35);

        // Crisp bone-white reserve core line
        let ghostCol = (avgNx > 0.1 && v < 0.85) ? panel.palette.ghost : panel.palette.pale;
        brush.set("cpencil", ghostCol, random(0.65, 1.15));
        brush.spline(pts, 0.35);
      } else if (avgOxid > 0.32) {
        // Oxidizing green-teal edge / fold
        let oxCol = avgNx > 0 ? panel.palette.oxidLight : panel.palette.oxidDark;
        brush.set("arashi_bleed", oxCol, random(0.85, 1.45));
        brush.spline(pts, 0.35);
      } else {
        // Saturated Prussian to woad indigo band
        let indCol;
        if (v > 0.78 || avgNx < -0.25) {
          indCol = panel.palette.deep;
        } else if (avgNx > 0.28) {
          indCol = panel.palette.woad;
        } else {
          indCol = panel.palette.mid;
        }
        brush.set("arashi_bleed", indCol, random(0.9, 1.55));
        brush.spline(pts, 0.35);
      }
    }
  }

  // --- PASS D: Sharp White Ghost Lines Left in Reserve & Accordion Crinkle Memory ---
  // Trace continuous diagonal ghost creases across the full width of the cloth
  let numStripes = floor(panel.arashiFreq * 1.45);
  for (let b = -4; b <= numStripes; b++) {
    // Each stripe corresponds to a pole-wrap ridge
    for (let sub = 0; sub < 2; sub++) {
      let targetOffset = sub === 0 ? 0.5 : 0.22;
      let ridgePts = [];
      let stepsU = 22;

      for (let iu = 0; iu <= stepsU; iu++) {
        let u = iu / stepsU;
        let slope = tan(panel.arashiAngle);
        let vApprox = ((b + targetOffset) / panel.arashiFreq - u) / (slope * 0.65);

        if (vApprox >= 0.01 && vApprox <= 0.985) {
          let cp = evalClothPoint(panel, ladder, u, vApprox);
          // Modulate pressure: brighter and thicker on lit fold crests, thinner in deep fold crevices
          let press = constrain(0.45 + cp.nx * 0.45 + (1 - vApprox) * 0.25, 0.15, 1.25);
          ridgePts.push({ x: cp.x, y: cp.y, p: press, nx: cp.nx, v: vApprox, oxid: cp.oxidation });
        }
      }

      if (ridgePts.length >= 3) {
        // Break into natural segments so ghost lines feel organically dyed into the linen weave
        let segStart = 0;
        while (segStart < ridgePts.length - 2) {
          let segLen = floor(random(3, 8));
          let segEnd = min(segStart + segLen, ridgePts.length - 1);
          let chunk = [];
          let chunkNx = 0;
          let chunkV = 0;
          let chunkOxid = 0;

          for (let k = segStart; k <= segEnd; k++) {
            chunk.push([
              ridgePts[k].x + random(-0.7, 0.7),
              ridgePts[k].y + random(-0.7, 0.7),
              ridgePts[k].p
            ]);
            chunkNx += ridgePts[k].nx;
            chunkV += ridgePts[k].v;
            chunkOxid += ridgePts[k].oxid;
          }
          let count = segEnd - segStart + 1;
          chunkNx /= count;
          chunkV /= count;
          chunkOxid /= count;

          // Soft watercolor halo around the white ghost line
          let haloCol = chunkOxid > 0.35 ? panel.palette.oxidBright : panel.palette.pale;
          brush.set("2B", haloCol, sub === 0 ? 1.15 : 0.75);
          brush.spline(chunk, 0.4);

          // Crisp white/cream linen reserve line
          if (chunkV < 0.92) {
            let coreCol = chunkNx > -0.15 ? panel.palette.ghost : panel.palette.pale;
            brush.set("linen_thread", coreCol, sub === 0 ? random(0.95, 1.45) : random(0.55, 0.85));
            brush.spline(chunk, 0.4);
          }

          // Fine perpendicular crinkle ticks (from compressing cloth along the arashi pole)
          if (sub === 0 && random() < 0.65) {
            let midK = floor((segStart + segEnd) * 0.5);
            let mp = ridgePts[midK];
            let perpAng = panel.arashiAngle + 90 + random(-15, 15);
            let tickLen = random(4, 11);
            brush.set("linen_thread", mp.nx > 0 ? panel.palette.ghost : panel.palette.woad, 0.6);
            brush.line(
              mp.x - cos(perpAng) * tickLen,
              mp.y - sin(perpAng) * tickLen,
              mp.x + cos(perpAng) * tickLen,
              mp.y + sin(perpAng) * tickLen
            );
          }

          segStart = segEnd + (random() < 0.3 ? 1 : 0);
        }
      }
    }
  }

  // --- PASS E: Volumetric Vertical Fold Shadows, Wet Crevices & Raking Side Light ---
  let uFoldSamples = 46;
  let vFoldSteps = 28;

  for (let iu = 0; iu <= uFoldSamples; iu++) {
    let u = iu / uFoldSamples;

    for (let iv = 0; iv < vFoldSteps; iv++) {
      let v1 = iv / vFoldSteps;
      let v2 = (iv + 1) / vFoldSteps;
      let p1 = evalClothPoint(panel, ladder, u, v1);
      let p2 = evalClothPoint(panel, ladder, u, v2);

      // Deep fold valleys & lower heavy wet saturation
      if (p1.nx < -0.18 || p1.primaryWave < -0.35 || v1 > 0.82) {
        let shadowWeight = map(constrain(-p1.nx, 0, 1) + (v1 > 0.8 ? 0.4 : 0), 0, 1.4, 0.5, 1.6);
        brush.set("2B", panel.palette.deep, shadowWeight);
        brush.line(p1.x, p1.y, p2.x, p2.y);

        if (p1.primaryWave < -0.55 || v1 > 0.88) {
          brush.set("charcoal", "#040b17", shadowWeight * 0.75);
          brush.line(p1.x + random(-1, 1), p1.y, p2.x + random(-1, 1), p2.y);
        }
      }

      // Oxidized green-gold sheen along turning edges and damp fold flanks
      if (p1.oxidation > 0.28 && random() < 0.75) {
        let oxCol = p1.nx > 0.1 ? panel.palette.oxidBright : (p1.nx > -0.2 ? panel.palette.oxidLight : panel.palette.oxidDark);
        brush.set("cpencil", oxCol, random(0.65, 1.2));
        brush.line(p1.x + random(-1.5, 1.5), p1.y, p2.x + random(-1.5, 1.5), p2.y);
      }

      // Raking side-light grazing the left-facing fold crests & wet sheen
      if (p1.nx > 0.32 && v1 < 0.94) {
        let litWeight = map(p1.nx, 0.32, 1.2, 0.4, 1.25) * panel.lightBoost;
        let litCol = p1.resist > 0.4 ? panel.palette.ghost : (p1.oxidation > 0.3 ? panel.palette.oxidBright : panel.palette.pale);
        brush.set("cpencil", litCol, litWeight);
        brush.line(p1.x, p1.y, p2.x, p2.y);

        // Specular wet linen glint on the sharpest lit ridges
        if (p1.nx > 0.62 && random() < 0.55) {
          brush.set("wet_glint", "#f4f6f2", litWeight * 0.65);
          brush.line(p1.x, p1.y, p2.x, p2.y);
        }
      }
    }
  }

  // --- PASS F: Top Loop Over the Wooden Rung & Bottom Sagging Hem Contour ---
  // Top loop shadow & highlight where wet cloth wraps tightly over the cylindrical rung
  for (let iu = 0; iu < 36; iu++) {
    let u1 = iu / 36;
    let u2 = (iu + 1) / 36;
    let pt1 = evalClothPoint(panel, ladder, u1, 0.008);
    let pt2 = evalClothPoint(panel, ladder, u2, 0.008);
    brush.set("cpencil", u1 < 0.6 ? panel.palette.ghost : panel.palette.pale, 0.95);
    brush.line(pt1.x, pt1.y - 3, pt2.x, pt2.y - 3);

    // Underside shadow just below the rung wrap
    let pb1 = evalClothPoint(panel, ladder, u1, 0.055);
    let pb2 = evalClothPoint(panel, ladder, u2, 0.055);
    brush.set("2B", panel.palette.deep, 1.1);
    brush.line(pb1.x, pb1.y, pb2.x, pb2.y);
  }

  // Heavy wet undulating bottom hem (thick rolled selvedge, dark pooled dye + oxidized green rim)
  let hemPts = [];
  let hemSteps = 54;
  for (let iu = 0; iu <= hemSteps; iu++) {
    let u = iu / hemSteps;
    let hp = evalClothPoint(panel, ladder, u, 1.0);
    hemPts.push(hp);
  }

  for (let i = 0; i < hemPts.length - 1; i++) {
    let a = hemPts[i];
    let b = hemPts[i + 1];
    // Dark saturated indigo pool at hem
    brush.set("charcoal", "#040c1a", 1.35);
    brush.line(a.x, a.y - 2, b.x, b.y - 2);

    // Oxidized green-teal edge along the wet hem
    brush.set("cpencil", a.nx > 0 ? panel.palette.oxidBright : panel.palette.oxidDark, 1.05);
    brush.line(a.x, a.y, b.x, b.y);

    // Wet specular rim highlight on the hem folds facing left
    if (a.nx > 0.05) {
      brush.set("wet_glint", "#d8e6ec", 0.75);
      brush.line(a.x, a.y + 1, b.x, b.y + 1);
    }

    // Fine wet frayed linen selvedge whiskers at hem
    if (random() < 0.45) {
      brush.set("linen_thread", a.nx > 0 ? "#c5d8e0" : "#2b525c", 0.55);
      brush.line(a.x, a.y, a.x + random(-1.5, 1.5), a.y + random(3, 8));
    }
  }

  // Left and right selvedge edges (crisp wet edge with raking highlight on the left)
  for (let iv = 0; iv < 42; iv++) {
    let v1 = iv / 42;
    let v2 = (iv + 1) / 42;
    let l1 = evalClothPoint(panel, ladder, 0, v1);
    let l2 = evalClothPoint(panel, ladder, 0, v2);
    let r1 = evalClothPoint(panel, ladder, 1, v1);
    let r2 = evalClothPoint(panel, ladder, 1, v2);

    // Left selvedge catches bright raking side-light & green oxidation
    brush.set("cpencil", panel.palette.oxidBright, 1.1);
    brush.line(l1.x + 1.5, l1.y, l2.x + 1.5, l2.y);
    brush.set("wet_glint", "#f2f5f0", 0.9);
    brush.line(l1.x, l1.y, l2.x, l2.y);

    // Right selvedge in shadow with deep Prussian & dark verdigris edge
    brush.set("2B", panel.palette.deep, 1.15);
    brush.line(r1.x, r1.y, r2.x, r2.y);
  }
}

// ============================================================================
// 6. FOREGROUND STAINED VAT RIM & INDIGO LIQUID SURFACE
// ============================================================================
function drawIndigoVatAndRim(panels) {
  // The indigo vat occupies the bottom foreground (y: 965..1200)
  // 1. Dark mirror-like indigo liquid surface (y: 965..1110)
  brush.noStroke();
  brush.wash("#050d1a", 235);
  drawPolyShape([[0, 965], [1200, 965], [1200, 1130], [0, 1130]], 0.05);
  brush.noWash();

  // Submerged vertical reflections of the hanging cloths in the dark vat liquid
  let ladder = getLadderGeometry();
  for (let p of panels) {
    for (let k = 0; k < 34; k++) {
      let u = k / 33;
      let hp = evalClothPoint(p, ladder, u, 1.0);
      let rx = hp.x + random(-4, 4);
      let ry1 = 972 + random(0, 12);
      let ry2 = ry1 + random(35, 95);
      let refCol = hp.nx > 0.2 ? "#214469" : (hp.oxidation > 0.3 ? "#1a3d3b" : "#0b1c33");
      brush.set("soft_wash", refCol, random(0.7, 1.3));
      brush.line(rx, ry1, rx + random(-6, 6), min(ry2, 1095));
    }
  }

  // Horizontal liquid sheen & indigo flower (ai-no-hana violet-copper-blue foam) on the vat surface
  for (let i = 0; i < 85; i++) {
    let lx1 = random(0, 1120);
    let ly = random(970, 1090);
    let lx2 = lx1 + random(30, 140);
    let col = lx1 < 550
      ? (random() < 0.4 ? "#2e4f73" : "#17314f")
      : (random() < 0.5 ? "#091729" : "#12263d");
    brush.set("arashi_bleed", col, random(0.6, 1.2));
    brush.line(lx1, ly, lx2, ly + random(-1.5, 1.5));
  }

  // Clusters of frothy "indigo flower" (ai-no-hana) floating on the vat liquid
  const foamClusters = [
    { x: 180, y: 1025, r: 45 },
    { x: 460, y: 1045, r: 55 },
    { x: 760, y: 1030, r: 50 },
    { x: 1020, y: 1050, r: 40 }
  ];
  for (let fc of foamClusters) {
    for (let j = 0; j < 26; j++) {
      let fx = fc.x + random(-fc.r, fc.r);
      let fy = fc.y + random(-fc.r * 0.28, fc.r * 0.28);
      let fCol = random() < 0.35 ? "#7a89ab" : (random() < 0.6 ? "#425278" : "#3b615c");
      brush.set("cpencil", fCol, random(0.5, 1.1));
      brush.circle(fx, fy, random(1.5, 4.5), 0.3);
    }
  }

  // 2. Massive Stained Vat Rim Crossing the Foreground (curved in perspective)
  // Top inner lip of the foreground vat rim curves from (0, 1068) down to (600, 1102) and up to (1200, 1076)
  let rimTopPts = [];
  let rimMidPts = [];
  let rimBotPts = [];
  let rSteps = 30;
  for (let i = 0; i <= rSteps; i++) {
    let t = i / rSteps;
    let rx = t * 1200;
    let curveY = sin(t * 180) * 32;
    let topY = 1066 + curveY;
    rimTopPts.push([rx, topY]);
    rimMidPts.push([rx, topY + 38]);
    rimBotPts.push([rx, 1205]);
  }

  // Base dark wood/stone rim body
  let rimPoly = [...rimTopPts, ...rimBotPts.slice().reverse()];
  brush.noStroke();
  brush.wash("#12161f", 245);
  drawPolyShape(rimPoly, 0.05);
  brush.noWash();

  // Watercolor indigo & oxidized green stains crusted on the vat rim
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.65, 0.45);
  for (let k = 0; k < 12; k++) {
    let sx = random(20, 1120);
    let sy = 1075 + sin((sx / 1200) * 180) * 30 + random(0, 55);
    let sw = random(55, 150);
    let sh = random(18, 42);
    let stainCol = random() < 0.65 ? "#0b213d" : (random() < 0.5 ? "#1c3f5e" : "#234742");
    brush.fill(stainCol, 115);
    drawPolyShape([
      [sx, sy],
      [sx + sw, sy + random(-4, 4)],
      [sx + sw * 0.9, sy + sh],
      [sx - sw * 0.1, sy + sh]
    ], 0.3);
  }
  brush.noFill();

  // Texture, grain, indigo crusts, and raking side-light across the top bevel of the vat rim
  for (let i = 0; i < rSteps; i++) {
    let p1 = rimTopPts[i];
    let p2 = rimTopPts[i + 1];
    let m1 = rimMidPts[i];
    let m2 = rimMidPts[i + 1];
    let lit = map(i, 0, rSteps, 1.0, 0.25);

    for (let s = 0; s <= 14; s++) {
      let f = s / 14;
      let yA = lerp(p1[1], m1[1], f);
      let yB = lerp(p2[1], m2[1], f);

      let col;
      if (f < 0.25) {
        col = lit > 0.5 ? "#7a8c99" : "#435666";
      } else if (f < 0.65) {
        col = random() < 0.5 ? "#1a314a" : "#2b2623";
      } else {
        col = "#0c131c";
      }
      brush.set("2B", col, random(0.8, 1.4));
      brush.line(p1[0], yA, p2[0], yB);
    }

    // Front vertical face of the vat rim (in deep twilight shadow with vertical dye runs)
    for (let d = 0; d < 5; d++) {
      let dx = lerp(p1[0], p2[0], random());
      let dy1 = lerp(m1[1], m2[1], 0.5);
      brush.set("charcoal", random() < 0.6 ? "#081221" : "#14293d", random(0.9, 1.5));
      brush.line(dx, dy1, dx + random(-3, 3), 1200);
    }

    // Wet specular highlight along the inner & upper lip of the vat rim
    if (lit > 0.3) {
      brush.set("wet_glint", lit > 0.65 ? "#dce6ed" : "#89a4ba", 0.95 * lit);
      brush.line(p1[0], p1[1] + 2, p2[0], p2[1] + 2);
    }
  }

  // Wet indigo puddles sitting on top of the flat vat rim
  const rimPuddles = [
    { x: 165, w: 65 },
    { x: 390, w: 85 },
    { x: 645, w: 70 },
    { x: 890, w: 60 }
  ];
  for (let rp of rimPuddles) {
    let py = 1082 + sin((rp.x / 1200) * 180) * 32;
    brush.set("arashi_bleed", "#071a33", 1.5);
    brush.line(rp.x - rp.w * 0.5, py, rp.x + rp.w * 0.5, py + 2);
    brush.set("wet_glint", "#c8dce8", 0.8);
    brush.line(rp.x - rp.w * 0.45, py - 1.5, rp.x + rp.w * 0.25, py - 0.5);
  }
}

// ============================================================================
// 7. WATER DROPLETS AT HEM, FALLING DRIPS & VAT RIPPLES
// ============================================================================
function drawPanelDropletsAndDrips(panel) {
  let ladder = getLadderGeometry();

  // Locate lowest sagging fold troughs along the hem where water collects and drips
  let numDripSites = 11;
  for (let i = 0; i < numDripSites; i++) {
    let u = map(i, 0, numDripSites - 1, 0.04, 0.96) + random(-0.02, 0.02);
    let hp = evalClothPoint(panel, ladder, constrain(u, 0.02, 0.98), 1.0);

    // Draw clinging water bead at the hem
    drawWaterDroplet(hp.x, hp.y + 3.5, random(2.8, 4.6), hp.nx > -0.2);

    // Falling drip thread & mid-air droplets descending into the vat
    let impactY = random(982, 1062);
    let distY = impactY - (hp.y + 5);

    if (distY > 15) {
      // Glistening thin water thread right below the hem
      let threadLen = random(14, min(42, distY * 0.55));
      brush.set("linen_thread", "#5282a8", 0.75);
      brush.line(hp.x, hp.y + 4, hp.x, hp.y + 4 + threadLen);
      brush.set("wet_glint", "#e6f0f5", 0.65);
      brush.line(hp.x - 0.6, hp.y + 4, hp.x - 0.6, hp.y + 4 + threadLen * 0.8);

      // 2 to 4 discrete falling droplets along the vertical path
      let numDrops = floor(random(2, 5));
      for (let d = 0; d < numDrops; d++) {
        let dy = lerp(hp.y + threadLen + 8, impactY - 6, (d + random(0.1, 0.8)) / numDrops);
        let dx = hp.x + random(-1.2, 1.2);
        let dropR = random(1.6, 3.4);

        // Motion streak
        brush.set("linen_thread", "#8ab4d4", 0.55);
        brush.line(dx, dy - dropR * 2.5, dx, dy + dropR);

        // Hyperreal water droplet
        drawWaterDroplet(dx, dy, dropR, true);
      }

      // Concentric elliptical ripple where the drip hits the indigo vat liquid
      if (random() < 0.75) {
        drawVatRipple(hp.x, impactY, random(14, 36), hp.x < 700);
      }
    }
  }
}

function drawWaterDroplet(x, y, r, isLit) {
  // Dark indigo refracted core
  brush.set("pen", "#071a30", 1.1);
  brush.circle(x, y, r, 0.15);

  // Oxidized cyan-green refraction on right edge of droplet
  brush.set("linen_thread", "#5aa198", 0.75);
  brush.arc(x, y, r * 0.85, -45, 75);

  // Bright raking specular highlight on upper-left of droplet
  if (isLit) {
    brush.set("wet_glint", "#f5f8fa", 0.95);
    brush.arc(x - r * 0.2, y - r * 0.2, r * 0.7, 135, 265);
    brush.circle(x - r * 0.35, y - r * 0.35, max(0.6, r * 0.25), 0.05);
  }
}

function drawVatRipple(cx, cy, maxRx, isBright) {
  let rings = 3;
  for (let k = 1; k <= rings; k++) {
    let rx = (maxRx * k) / rings;
    let ry = rx * 0.24; // Foreshortened ellipse on the horizontal liquid plane

    let topPts = [];
    let botPts = [];
    for (let a = 0; a <= 180; a += 30) {
      topPts.push([cx - cos(a) * rx, cy - sin(a) * ry]);
      botPts.push([cx - cos(a) * rx, cy + sin(a) * ry]);
    }

    let col = k === 1
      ? (isBright ? "#c4dae8" : "#6c92b0")
      : (isBright ? "#527c9e" : "#284969");

    brush.set(k === 1 ? "wet_glint" : "linen_thread", col, map(k, 1, rings, 0.85, 0.45));
    brush.spline(topPts, 0.4);
    brush.spline(botPts, 0.4);
  }

  // Tiny central splash bead jumping up from the impact point
  brush.set("wet_glint", "#e8f2f8", 0.8);
  brush.line(cx, cy, cx, cy - random(3, 7));
  brush.circle(cx, cy - random(5, 9), 1.2, 0.1);
}

