// 8. ATMOSPHERIC RAKING SIDE LIGHT & MOISTURE GLAZE
// ============================================================================
function drawAtmosphericSideLight() {
  // Subtle diagonal raking light rays and floating moisture motes in the left workshop air
  for (let i = 0; i < 48; i++) {
    let x = random(15, 720);
    let y = random(30, 960);
    let distFactor = map(x, 0, 750, 1.0, 0.15);
    if (random() < distFactor) {
      brush.set("wet_glint", random() < 0.5 ? "#cad8e3" : "#9bb0bf", random(0.35, 0.75) * distFactor);
      brush.circle(x, y, random(0.5, 1.4), 0.1);
    }
  }

  // Gentle warm-cool twilight air glaze along the top-left entrance of the light
  for (let k = 0; k < 12; k++) {
    let x1 = 0;
    let y1 = random(20, 380);
    let x2 = random(260, 580);
    let y2 = y1 + (x2 - x1) * 0.38;
    brush.set("soft_wash", "#6c7d8c", random(0.45, 0.85));
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// HELPER: Draw closed shape via brush.beginShape / brush.vertex
// ============================================================================
function drawPolyShape(pts, curvature = 0.15) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Hyperrealism: Worn Denim Jacket Lapel with Saguaro Enamel Pin
// Rendered with p5.js v2 and p5.brush in WEBGL (1200x1200)

const PX = 600;
const PY = 455;
const PROT = -10;
const PR = 114;

const BX = 408;
const BY = 762;
const BROT = -23;

const RX = 876;
const RY = 882;

// Pucker lobes radiating from the enamel pin post
const PUCKER_LOBES = [
  { ang: -148, len: 255, amp: 1.0, width: 22 },
  { ang: -102, len: 195, amp: 0.65, width: 18 },
  { ang: -52,  len: 230, amp: 0.85, width: 20 },
  { ang: 14,   len: 220, amp: 0.90, width: 21 },
  { ang: 66,   len: 265, amp: 1.05, width: 24 },
  { ang: 132,  len: 240, amp: 0.95, width: 22 },
  { ang: 174,  len: 210, amp: 0.75, width: 19 }
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7492);
  noiseSeed(7492);

  // Custom micro-detail brushes for hyperreal pencil & metallic glint work
  brush.add("needle", {
    type: "default",
    weight: 0.28,
    scatter: 0.08,
    sharpness: 0.88,
    grain: 14,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.35
  });

  brush.add("cotton_slub", {
    type: "default",
    weight: 0.55,
    scatter: 0.22,
    sharpness: 0.65,
    grain: 22,
    opacity: 185,
    spacing: 0.15,
    pressure: [0.2, 1.15, 0.2],
    noise: 0.6
  });

  // Vector field that follows the diagonal denim twill and warps around the pin pucker
  brush.addField("denimTwill", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = (col / field.length) * width;
        let y = (row / field[0].length) * height;
        let baseAngle = -53;
        if (x < getLapelOuterX(y)) {
          baseAngle = -76; // Recessed chest panel grain
        } else if (isBelowYokeSeam(x, y)) {
          baseAngle = -48; // Lower pocket/welt panel grain
        }
        let pucker = getPuckerData(x, y);
        field[col][row] = baseAngle + pucker.angleShift + (noise(col * 0.08, row * 0.08) - 0.5) * 4;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Soft overcast daylight paper ground (cool cotton rag)
  background("#dde4ea");

  // 1. Base Watercolor & Undertone Washes (Indigo & Overcast Slate)
  drawUnderpaintingWashes();

  // 2. Out-of-Focus Recessed Left Chest Panel (Shallow Depth of Field)
  drawRecessedChestPanel();

  // 3. Fabric Pucker Shading & Radial Tension Folds around the Pin
  drawPinPuckerTonalStructure();

  // 4. Hyperreal Diagonal Indigo Twill Weave (Multi-pass Pencil & Warp/Weft Grain)
  drawHyperrealDenimTwill();

  // 5. Lapel Roll, Felled Seams, Roping Fades & Heavy Contrast Stitching
  drawSeamsAndRoping();

  // 6. Frayed Keyhole Buttonhole on the Lower Lapel
  drawFrayedButtonhole();

  // 7. Burnished Copper Rivet at the Yoke/Pocket Seam Junction
  drawCopperRivet();

  // 8. Saguaro Cactus Enamel Pin (Gold Die-Struck, Sage & Sunset-Pink, Window Reflection, Scratch)
  drawSaguaroEnamelPin();

  // 9. Stray Lint, Loose Cotton Fibers, Edge Halo Fuzz & Shallow DOF Vignette
  drawLintAndAtmosphere();

  noLoop();
}

// ============================================================================
// GEOMETRY & PUCKER HELPERS
// ============================================================================

function getLapelOuterX(y) {
  if (y < 292) {
    return map(y, -40, 292, 336, 236);
  } else if (y < 368) {
    let t = constrain((y - 292) / (368 - 292), 0, 1);
    return lerp(236, 128, sin(t * 90));
  } else {
    let t = constrain((y - 368) / (1240 - 368), 0, 1);
    return lerp(128, 514, pow(t, 1.05)) - sin(t * 180) * 16;
  }
}

function getLapelRollX(y) {
  return map(y, -40, 1240, 585, 1085) + sin((y / 1200) * 180) * 22;
}

function getYokeSeamY(x) {
  return map(x, 730, 1240, 932, 760);
}

function isBelowYokeSeam(x, y) {
  let rollX = getLapelRollX(y);
  return x > rollX - 30 && y > getYokeSeamY(x);
}

function pinPt(lx, ly) {
  let c = cos(PROT);
  let s = sin(PROT);
  return {
    x: PX + lx * c - ly * s,
    y: PY + lx * s + ly * c
  };
}

function btnPt(lx, ly) {
  let c = cos(BROT);
  let s = sin(BROT);
  return {
    x: BX + lx * c - ly * s,
    y: BY + lx * s + ly * c
  };
}

function getPuckerData(x, y) {
  let dx = x - PX;
  let dy = y - PY;
  let d = sqrt(dx * dx + dy * dy);
  if (d < 70 || d > 310) {
    return { ridge: 0, angleShift: 0, pinch: 0 };
  }
  let ang = atan2(dy, dx);
  let radialEnv = sin(map(constrain(d, 75, 305), 75, 305, 0, 180));
  radialEnv = pow(max(0, radialEnv), 1.35);

  let totalRidge = 0;
  let totalShift = 0;

  for (let i = 0; i < PUCKER_LOBES.length; i++) {
    let lobe = PUCKER_LOBES[i];
    let diff = ang - lobe.ang;
    while (diff > 180) diff -= 360;
    while (diff < -180) diff += 360;

    let distEnv = constrain(1 - (d - 85) / lobe.len, 0, 1);
    if (abs(diff) < lobe.width * 1.8 && distEnv > 0) {
      let norm = diff / lobe.width;
      // Mexican-hat profile: raised crest in center, pinched troughs on sides
      let profile = (1 - 1.65 * norm * norm) * exp(-0.85 * norm * norm);
      let slope = -norm * exp(-0.85 * norm * norm);
      totalRidge += profile * lobe.amp * radialEnv * distEnv;
      totalShift += slope * lobe.amp * radialEnv * distEnv * 14;
    }
  }

  // Slight circular pull right around the pin rim
  let rimPull = d < 142 ? map(d, 70, 142, -0.45, 0) : 0;

  return {
    ridge: totalRidge + rimPull,
    angleShift: totalShift,
    pinch: radialEnv
  };
}

// Evaluate tonal value of the denim at (x, y): -1 (deep shadow) to +1 (faded highlight)
function getDenimTone(x, y) {
  let outerX = getLapelOuterX(y);
  let rollX = getLapelRollX(y);

  // Recessed left chest panel
  if (x < outerX) {
    let distFromEdge = outerX - x;
    let castShadow = exp(-distFromEdge / 42) * -0.95;
    let baseRecessed = -0.35 + (noise(x * 0.005, y * 0.005) - 0.5) * 0.35;
    return constrain(baseRecessed + castShadow, -1, 0.3);
  }

  let tone = 0.05;

  // Broad cylindrical highlight along the lapel center & roll line
  let lapelW = rollX - outerX;
  let u = (x - outerX) / max(1, lapelW);
  if (u >= 0 && u <= 1.05) {
    // Gentle swell across the lapel face
    tone += sin(constrain(u, 0, 1) * 180) * 0.26;
    // Extra worn fade along the soft lapel roll
    let rollDist = abs(x - (rollX - 35));
    if (rollDist < 95) {
      tone += pow(1 - rollDist / 95, 2) * 0.28;
    }
  } else {
    // Right chest panel recedes slightly behind the roll
    tone -= 0.18;
  }

  // Edge fade & seam trough along outer lapel edge
  let edgeDist = x - outerX;
  if (edgeDist >= 0 && edgeDist < 58) {
    if (edgeDist < 12) tone += 0.32; // Worn folded edge highlight
    else if (edgeDist < 22) tone -= 0.35; // First stitch trough
    else if (edgeDist < 36) tone += 0.28; // Raised roping ridge between seams
    else if (edgeDist < 46) tone -= 0.32; // Second stitch trough
    else tone += 0.15;
  }

  // Collar notch fold shadow (upper lapel)
  if (y < 325 && x > outerX) {
    let notchLineY = map(x, 236, 610, 292, -30);
    let dNotch = y - notchLineY;
    if (abs(dNotch) < 42) {
      if (dNotch > 0 && dNotch < 18) tone -= 0.65 * (1 - dNotch / 18); // Under-collar shadow
      else if (dNotch <= 0 && dNotch > -24) tone += 0.32 * (1 + dNotch / 24); // Collar lip highlight
    }
  }

  // Yoke seam shadow & highlight on lower right
  let yokeY = getYokeSeamY(x);
  if (x > rollX - 40 && abs(y - yokeY) < 48) {
    let dy = y - yokeY;
    if (dy > -12 && dy < 6) tone -= 0.55;
    else if (dy >= 6 && dy < 28) tone += 0.35;
  }

  // Pin pucker modulation
  let pucker = getPuckerData(x, y);
  tone += pucker.ridge * 0.62;

  // Cast shadow of the Saguaro Pin (overcast light from upper-left)
  let pdx = x - (PX + 14);
  let pdy = y - (PY + 20);
  let pd = sqrt(pdx * pdx + pdy * pdy);
  if (pd > PR - 8 && pd < PR + 36) {
    let sAmt = pow(1 - (pd - (PR - 8)) / 44, 1.8);
    // Stronger on lower-right side
    let dirFactor = map(pdx * 0.6 + pdy * 0.8, -PR, PR, 0.25, 1.15);
    tone -= sAmt * dirFactor * 0.85;
  }

  // Copper rivet tension & shadow
  let rdx = x - RX;
  let rdy = y - RY;
  let rd = sqrt(rdx * rdx + rdy * rdy);
  if (rd > 22 && rd < 75) {
    if (rd < 42) tone -= pow(1 - (rd - 22) / 20, 1.6) * 0.75;
    else tone += sin(((rd - 42) / 33) * 180) * 0.22 * cos(atan2(rdy, rdx) * 4);
  }

  // Organic slub & vintage wash noise
  let n1 = noise(x * 0.008, y * 0.008) - 0.48;
  let n2 = (noise(x * 0.035, y * 0.035) - 0.5) * 0.22;
  return constrain(tone + n1 * 0.42 + n2, -1, 1);
}

// ============================================================================
// 1. UNDERPAINTING WASHES
// ============================================================================

function drawUnderpaintingWashes() {
  brush.noStroke();

  // Base cool indigo wash across the entire canvas
  brush.wash("#334a66", 115);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Deep slate-indigo fill on the recessed left chest panel
  brush.fill("#162538", 155);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.35);
  brush.beginShape(0.2);
  brush.vertex(-30, -30);
  brush.vertex(350, -30);
  for (let y = 0; y <= 1230; y += 120) {
    brush.vertex(getLapelOuterX(y) + 18, y);
  }
  brush.vertex(-30, 1230);
  brush.endShape(CLOSE);

  // Mid-indigo body wash for the main lapel and chest
  brush.fill("#283e58", 120);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.6, 0.4);
  brush.beginShape(0.2);
  for (let y = -30; y <= 1230; y += 120) {
    brush.vertex(getLapelOuterX(y), y);
  }
  brush.vertex(1230, 1230);
  brush.vertex(1230, -30);
  brush.endShape(CLOSE);

  // Darker indigo shadow pools: under collar notch, around pin, and lower-right corner
  brush.fill("#142236", 130);
  brush.fillBleed(0.32, "out");
  // Shadow pool around & below the pin
  brush.circle(PX + 18, PY + 24, 155, 0.35);
  // Shadow pool at collar notch
  brush.circle(310, 220, 110, 0.4);
  // Shadow pool at lower-right pocket corner
  brush.circle(1020, 1020, 240, 0.4);

  // Luminous faded cotton-blue wash along the lapel roll and upper lapel highlight
  brush.fill("#8aa4bd", 75);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);
  brush.beginShape(0.3);
  brush.vertex(380, 120);
  brush.vertex(660, 140);
  brush.vertex(890, 740);
  brush.vertex(520, 880);
  brush.vertex(270, 440);
  brush.endShape(CLOSE);

  // Pale overcast daylight wash around the pin highlight ridges
  brush.fill("#c5d5e3", 65);
  brush.fillBleed(0.25, "out");
  brush.circle(PX - 40, PY - 35, 195, 0.3);

  brush.noFill();
}

// ============================================================================
// 2. OUT-OF-FOCUS RECESSED LEFT CHEST PANEL
// ============================================================================

function drawRecessedChestPanel() {
  // Soft hatched base in deep Prussian/indigo
  let panelPts = [[-20, -20], [345, -20]];
  for (let y = 0; y <= 1220; y += 80) {
    panelPts.push([getLapelOuterX(y) + 4, y]);
  }
  panelPts.push([-20, 1220]);

  let poly = new brush.Polygon(panelPts);
  brush.hatchStyle("charcoal", "#121f30", 1.15);
  brush.hatch(9, -76, { rand: 0.12, gradient: 0.25 });
  poly.hatch(9, -76, { rand: 0.12 });
  brush.noHatch();

  // Second softer cross-grain pass for out-of-focus depth
  brush.hatchStyle("2B", "#1e324a", 0.9);
  poly.hatch(7, -68, { rand: 0.15 });
  brush.noHatch();

  // Blurred diagonal twill bands using soft charcoal and cpencil
  for (let xStart = -250; xStart < 480; xStart += 6.5) {
    let x1 = xStart;
    let y1 = -20;
    let x2 = xStart - 290;
    let y2 = 1220;

    // Sample midpoint
    for (let seg = 0; seg < 14; seg++) {
      let t1 = seg / 14;
      let t2 = (seg + 1) / 14;
      let sx1 = lerp(x1, x2, t1);
      let sy1 = lerp(y1, y2, t1);
      let sx2 = lerp(x1, x2, t2);
      let sy2 = lerp(y1, y2, t2);

      let edgeX = getLapelOuterX((sy1 + sy2) * 0.5);
      if (sx1 < edgeX - 3 && sx2 < edgeX - 3) {
        let distEdge = edgeX - sx1;
        let col = distEdge < 48 ? "#0b1422" : (random() < 0.5 ? "#1b2e45" : "#2b425e");
        let w = distEdge < 48 ? 1.15 : 0.85;
        brush.set("charcoal", col, w);
        brush.line(sx1, sy1, sx2, sy2);

        if (distEdge > 55 && random() < 0.35) {
          brush.set("cpencil", "#546e8a", 0.65);
          brush.line(sx1 + 2.2, sy1, sx2 + 2.2, sy2);
        }
      }
    }
  }

  // Deep ambient occlusion shadow cast by the lapel edge onto the chest panel
  for (let y = -10; y < 1210; y += 4.5) {
    let ex = getLapelOuterX(y);
    brush.set("charcoal", "#08101c", random(0.9, 1.45));
    brush.line(ex + 1, y, ex - random(18, 42), y + random(8, 22));
    brush.set("2B", "#0d1829", 0.85);
    brush.line(ex, y, ex - random(8, 18), y + 6);
  }
}

// ============================================================================
// 3. PIN PUCKER TONAL STRUCTURE
// ============================================================================

function drawPinPuckerTonalStructure() {
  brush.noStroke();

  // Watercolor & wash sculpting for each tension lobe radiating from the pin
  for (let i = 0; i < PUCKER_LOBES.length; i++) {
    let lobe = PUCKER_LOBES[i];
    let rStart = 96;
    let rEnd = 96 + lobe.len * 0.92;

    // Raised crest highlight wash
    let cAng = lobe.ang;
    let wAng = lobe.width * 0.48;
    brush.fill("#b8cce0", 52);
    brush.fillBleed(0.2, "out");
    brush.beginShape(0.35);
    brush.vertex(PX + cos(cAng - wAng) * rStart, PY + sin(cAng - wAng) * rStart);
    brush.vertex(PX + cos(cAng) * rEnd, PY + sin(cAng) * rEnd);
    brush.vertex(PX + cos(cAng + wAng) * rStart, PY + sin(cAng + wAng) * rStart);
    brush.endShape(CLOSE);

    // Pinched trough shadows flanking each lobe
    for (let side of [-1, 1]) {
      let sAng = lobe.ang + side * lobe.width * 0.95;
      let swAng = lobe.width * 0.42;
      brush.fill("#132236", 68);
      brush.fillBleed(0.22, "out");
      brush.beginShape(0.35);
      brush.vertex(PX + cos(sAng - swAng) * rStart, PY + sin(sAng - swAng) * rStart);
      brush.vertex(PX + cos(sAng) * (rEnd * 0.88), PY + sin(sAng) * (rEnd * 0.88));
      brush.vertex(PX + cos(sAng + swAng) * rStart, PY + sin(sAng + swAng) * rStart);
      brush.endShape(CLOSE);
    }
  }
  brush.noFill();

  // Fine directional graphite & indigo shading along the pucker troughs and crests
  for (let i = 0; i < PUCKER_LOBES.length; i++) {
    let lobe = PUCKER_LOBES[i];
    for (let r = 98; r < 95 + lobe.len; r += 3.2) {
      let t = (r - 98) / lobe.len;
      let env = sin(t * 180) * lobe.amp;
      if (env <= 0.05) continue;

      // Crest highlight strokes (pale ice-blue / cotton white cross-ridge marks)
      let cx = PX + cos(lobe.ang) * r;
      let cy = PY + sin(lobe.ang) * r;
      let perp = lobe.ang + 90;
      let span = map(t, 0, 1, 14, 4) * lobe.amp;

      brush.set("cpencil", "#d8e4ef", 0.55 * env);
      brush.line(
        cx - cos(perp) * span,
        cy - sin(perp) * span,
        cx + cos(perp) * span,
        cy + sin(perp) * span
      );

      if (t < 0.65) {
        brush.set("2H", "#f0f5f9", 0.42 * env);
        brush.line(
          cx - cos(perp) * span * 0.55,
          cy - sin(perp) * span * 0.55,
          cx + cos(perp) * span * 0.55,
          cy + sin(perp) * span * 0.55
        );
      }

      // Flanking trough shadow strokes in deep Prussian blue
      for (let side of [-1, 1]) {
        let tAng = lobe.ang + side * lobe.width * 0.92;
        let tx = PX + cos(tAng) * r;
        let ty = PY + sin(tAng) * r;
        brush.set("2B", "#101d30", 0.58 * env);
        brush.line(
          tx - cos(lobe.ang) * 7,
          ty - sin(lobe.ang) * 7,
          tx + cos(lobe.ang) * 7,
          ty + sin(lobe.ang) * 7
        );
      }
    }
  }
}

// ============================================================================
// 4. HYPERREAL DIAGONAL INDIGO TWILL WEAVE
// ============================================================================

function drawHyperrealDenimTwill() {
  // Pass A: Vector-field guided indigo pencil base layer across the lapel & chest
  brush.field("denimTwill");
  for (let i = 0; i < 950; i++) {
    let x = random(120, 1190);
    let y = random(-10, 1210);
    if (x < getLapelOuterX(y) + 2) continue;
    // Skip interior of pin
    if (dist(x, y, PX, PY) < PR - 4) continue;

    let tone = getDenimTone(x, y);
    let col;
    let w;
    if (tone < -0.35) {
      col = random(["#0d1828", "#132238", "#1a2d47"]);
      w = random(0.55, 0.85);
    } else if (tone < 0.15) {
      col = random(["#1f3450", "#294160", "#355070"]);
      w = random(0.45, 0.72);
    } else {
      col = random(["#466282", "#5d7a99", "#7895b2"]);
      w = random(0.4, 0.65);
    }

    brush.set("cpencil", col, w);
    brush.flowLine(x, y, random(32, 68), -53);
  }
  brush.noField();

  // Pass B: Precision Diagonal Twill Wales (The signature 3x1 diagonal ribs of real denim)
  // Wale direction ~ -53 deg (dx = cos(-53) = 0.6018, dy = sin(-53) = -0.7986)
  // We step perpendicular to the wale across the entire jacket crop
  let waleAngle = -53;
  let dirX = cos(waleAngle);
  let dirY = sin(waleAngle);
  let perpX = -dirY; // +0.7986
  let perpY = dirX;  // +0.6018

  let waleSpacing = 4.6;
  let stepLen = 13.5;

  for (let p = -620; p < 1520; p += waleSpacing) {
    let anchorX = 600 + perpX * p;
    let anchorY = 600 + perpY * p;

    let waleIndex = round(p / waleSpacing);
    let phaseOffset = (waleIndex * 4.7) % stepLen;

    for (let s = -920 + phaseOffset; s < 920; s += stepLen) {
      let x1 = anchorX + dirX * s;
      let y1 = anchorY + dirY * s;

      if (x1 < 115 || x1 > 1205 || y1 < -15 || y1 > 1215) continue;
      let outerX = getLapelOuterX(y1);
      if (x1 < outerX + 3) continue;

      // Skip inside the enamel pin or inside the rivet/buttonhole slit
      let dPin = dist(x1, y1, PX, PY);
      if (dPin < PR - 2) continue;
      if (dist(x1, y1, RX, RY) < 25) continue;

      // Slight direction shift below the chest yoke seam
      let localAngle = isBelowYokeSeam(x1, y1) ? -47 : waleAngle;
      let pucker = getPuckerData(x1, y1);
      let finalAngle = localAngle + pucker.angleShift;

      let ldx = cos(finalAngle);
      let ldy = sin(finalAngle);

      // Warp displacement over pucker ridges for physical 3D distortion
      let dispX = -ldy * pucker.ridge * 4.5;
      let dispY = ldx * pucker.ridge * 4.5;

      let sx1 = x1 + dispX;
      let sy1 = y1 + dispY;
      let segL = stepLen * 0.78;
      let sx2 = sx1 + ldx * segL;
      let sy2 = sy1 + ldy * segL;

      let tone = getDenimTone(sx1, sy1);

      // Shallow depth-of-field check (soften far upper-right and far lower-right corners)
      let cornerDist = max(
        map(sx1 - sy1, 650, 1200, 0, 1, true),
        map(sx1 + sy1, 1950, 2400, 0, 1, true)
      );

      // 1. Draw the dark indigo warp float (the diagonal ridge of the twill)
      let warpColor;
      let warpWeight;
      if (tone < -0.45) {
        warpColor = "#0a1322";
        warpWeight = 0.72;
      } else if (tone < -0.15) {
        warpColor = "#15253b";
        warpWeight = 0.64;
      } else if (tone < 0.18) {
        warpColor = "#223854";
        warpWeight = 0.56;
      } else if (tone < 0.45) {
        warpColor = "#344f6e";
        warpWeight = 0.48;
      } else {
        warpColor = "#4d6b8a";
        warpWeight = 0.42;
      }

      let bName = cornerDist > 0.45 ? "2B" : "HB";
      brush.set(bName, warpColor, warpWeight);
      brush.line(sx1, sy1, sx2, sy2);

      // 2. Draw the recessed furrow next to the wale in deeper indigo
      if (tone < 0.35 && cornerDist < 0.65) {
        let fx = sx1 + perpX * 1.9;
        let fy = sy1 + perpY * 1.9;
        let fCol = tone < -0.2 ? "#08101c" : "#172940";
        brush.set("2H", fCol, 0.36);
        brush.line(fx, fy, fx + ldx * (segL * 0.65), fy + ldy * (segL * 0.65));
      }

      // 3. Draw the pale cotton weft crossing tick (gives hyperreal woven texture!)
      if (cornerDist < 0.5 && (tone > -0.25 || random() < 0.35)) {
        let wx = sx2 + ldx * 1.4;
        let wy = sy2 + ldy * 1.4;
        // Weft crosses nearly horizontally/diagonally across the warp wale
        let weftAng = finalAngle + 72;
        let wLen = map(tone, -0.3, 0.8, 1.6, 3.1, true);
        let weftCol;
        if (tone > 0.42) weftCol = "#e4edf5";
        else if (tone > 0.15) weftCol = "#bfd0e0";
        else if (tone > -0.1) weftCol = "#8ea5bc";
        else weftCol = "#5b748f";

        brush.set("needle", weftCol, map(tone, -0.3, 0.8, 0.65, 1.05, true));
        brush.line(
          wx - cos(weftAng) * wLen * 0.5,
          wy - sin(weftAng) * wLen * 0.5,
          wx + cos(weftAng) * wLen * 0.5,
          wy + sin(weftAng) * wLen * 0.5
        );
      }
    }
  }

  // Pass C: High-resolution cotton slubs and vintage fade highlights on raised areas
  for (let i = 0; i < 620; i++) {
    let x = random(135, 1150);
    let y = random(20, 1180);
    if (x < getLapelOuterX(y) + 6) continue;
    if (dist(x, y, PX, PY) < PR + 2) continue;
    if (dist(x, y, RX, RY) < 28) continue;

    let tone = getDenimTone(x, y);
    if (tone > 0.12) {
      // Vertical/warp slub or horizontal weft yarn highlight
      let isWarp = random() < 0.65;
      let ang = isWarp ? -53 + getPuckerData(x, y).angleShift : 22;
      let len = random(4, 13) * map(tone, 0.1, 0.9, 0.6, 1.3);
      let col = tone > 0.45 ? "#e9f0f6" : (tone > 0.28 ? "#c7d6e5" : "#9ab0c7");
      brush.set("cotton_slub", col, random(0.45, 0.85));
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    } else if (tone < -0.3) {
      // Deep indigo crevice accent
      let ang = -53 + getPuckerData(x, y).angleShift;
      let len = random(6, 16);
      brush.set("2H", "#07101d", random(0.4, 0.65));
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }
}

// ============================================================================
// 5. LAPEL ROLL, FELLED SEAMS, ROPING FADES & HEAVY CONTRAST STITCHING
// ============================================================================

function drawSeamsAndRoping() {
  // A. Folded Outer Edge of the Lapel (Thick denim fold with roping ridges)
  for (let y = -20; y < 1220; y += 3.2) {
    let ex = getLapelOuterX(y);
    let exNext = getLapelOuterX(y + 3.2);
    let tang = atan2(3.2, exNext - ex);
    let normX = sin(tang);
    let normY = -cos(tang);

    // Extreme outer rim highlight (overcast sky grazing the folded denim edge)
    let rimCol = (y > 320 && y < 410) ? "#eef4f8" : (random() < 0.6 ? "#cad9e8" : "#94acc4");
    brush.set("cpencil", rimCol, random(0.5, 0.85));
    brush.line(ex + normX * 2.5, y + normY * 2.5, exNext + normX * 4.5, y + 3.2 + normY * 4.5);

    // Dark turned-under edge shadow
    brush.set("2B", "#0a1320", 0.65);
    brush.line(ex, y, exNext, y + 3.2);
  }

  // B. Roping Effect (Diagonal puckered fade ridges between the double stitch lines)
  // Classic vintage denim "train track" & "roping" abrasion along the lapel hem
  for (let y = -10; y < 1215; y += 7.5) {
    let ex = getLapelOuterX(y);
    let exNext = getLapelOuterX(y + 8);
    let seamAng = atan2(8, exNext - ex);
    let ropeAng = seamAng - 42; // Skewed roping twist angle

    // Roping between outer edge and Stitch Line 1 (offset ~ 9px)
    let rx1 = ex + 10;
    let ry1 = y;
    brush.set("cotton_slub", "#d5e2ee", random(0.55, 0.9));
    brush.line(rx1 - cos(ropeAng) * 4.5, ry1 - sin(ropeAng) * 4.5, rx1 + cos(ropeAng) * 4.5, ry1 + sin(ropeAng) * 4.5);

    // Roping ridge between Stitch Line 1 (18px) and Stitch Line 2 (39px)
    let rx2 = ex + 28.5 + (noise(y * 0.05) - 0.5) * 3;
    let ry2 = y;
    // Dark valley before the rope crest
    brush.set("2B", "#101e30", 0.55);
    brush.line(
      rx2 - 3 - cos(ropeAng) * 6,
      ry2 - sin(ropeAng) * 6,
      rx2 - 3 + cos(ropeAng) * 6,
      ry2 + sin(ropeAng) * 6
    );
    // Bright abraded cotton crest of the rope
    brush.set("cotton_slub", "#dce7f2", random(0.65, 1.05));
    brush.line(
      rx2 - cos(ropeAng) * 6.5,
      ry2 - sin(ropeAng) * 6.5,
      rx2 + cos(ropeAng) * 6.5,
      ry2 + sin(ropeAng) * 6.5
    );
    // Fine bright center highlight on the highest warp threads
    if (random() < 0.7) {
      brush.set("needle", "#f2f7fb", 0.75);
      brush.line(
        rx2 - cos(ropeAng) * 3.5,
        ry2 - sin(ropeAng) * 3.5,
        rx2 + cos(ropeAng) * 3.5,
        ry2 + sin(ropeAng) * 3.5
      );
    }
  }

  // C. Double-Row Heavy Lockstitching along the Lapel Edge & Collar Notch
  drawStitchTrack((t) => {
    let y = map(t, 0, 1, 366, 1225);
    return { x: getLapelOuterX(y) + 18, y: y };
  }, 64);

  drawStitchTrack((t) => {
    let y = map(t, 0, 1, 374, 1225);
    return { x: getLapelOuterX(y) + 39, y: y };
  }, 63);

  // Upper lapel peak horizontal return stitches (from peak inward to notch)
  drawStitchTrack((t) => {
    let y = map(t, 0, 1, 294, 366);
    return { x: getLapelOuterX(y) + 17, y: y };
  }, 9);

  drawStitchTrack((t) => {
    let y = map(t, 0, 1, 304, 374);
    return { x: getLapelOuterX(y) + 37, y: y };
  }, 8);

  // Upper collar edge stitches (above the notch)
  drawStitchTrack((t) => {
    let y = map(t, 0, 1, -20, 290);
    return { x: getLapelOuterX(y) + 17, y: y };
  }, 24);

  drawStitchTrack((t) => {
    let y = map(t, 0, 1, -20, 282);
    return { x: getLapelOuterX(y) + 37, y: y };
  }, 23);

  // Collar fold seam running from notch vertex (236, 292) up-right to (605, -20)
  for (let s = 0; s < 1; s += 0.008) {
    let sx = lerp(236, 605, s);
    let sy = lerp(292, -20, s);
    // Deep fold crevice
    brush.set("2B", "#091220", 0.95);
    brush.line(sx, sy, sx + 5, sy - 4);
    // Roping highlight on upper collar lip
    brush.set("cotton_slub", "#cedbe8", 0.75);
    brush.line(sx - 4, sy - 5, sx + 1, sy - 11);
  }
  drawStitchTrack((t) => {
    return { x: lerp(244, 595, t), y: lerp(276, -20, t) };
  }, 34);

  // D. Lower-Right Chest Yoke & Pocket Seam (leading into the Copper Rivet)
  for (let x = 755; x < 1220; x += 4) {
    let yy = getYokeSeamY(x);
    // Deep felled seam shadow
    brush.set("2B", "#08111e", 1.05);
    brush.line(x, yy, x + 4, yy - 1.5);
    // Roping ridge below the seam
    let rAng = -62;
    brush.set("cotton_slub", "#c7d6e6", 0.8);
    brush.line(x, yy + 10, x + cos(rAng) * 8, yy + 10 + sin(rAng) * 8);
    brush.set("cotton_slub", "#d5e2ef", 0.7);
    brush.line(x, yy + 28, x + cos(rAng) * 7, yy + 28 + sin(rAng) * 7);
  }

  // Double stitching along the chest yoke seam
  drawStitchTrack((t) => {
    let x = lerp(765, 1215, t);
    return { x: x, y: getYokeSeamY(x) + 15 };
  }, 34);

  drawStitchTrack((t) => {
    let x = lerp(772, 1215, t);
    return { x: x, y: getYokeSeamY(x) + 34 };
  }, 33);

  // Vertical pocket welt seam dropping down from the Copper Rivet
  for (let t = 0; t < 1; t += 0.012) {
    let vx = lerp(RX - 4, 985, t);
    let vy = lerp(RY + 18, 1225, t);
    brush.set("2B", "#091322", 0.95);
    brush.line(vx, vy, vx + 2, vy + 5);
    brush.set("cotton_slub", "#bfd0e0", 0.75);
    brush.line(vx + 9, vy, vx + 14, vy + 6);
  }
  drawStitchTrack((t) => {
    return { x: lerp(RX + 14, 998, t), y: lerp(RY + 22, 1220, t) };
  }, 24);
}

// Helper to draw hyperreal heavy twisted denim topstitching along a parametric path
function drawStitchTrack(pathFn, numStitches) {
  // First pass: continuous depressed seam trough
  for (let i = 0; i < numStitches; i++) {
    let p1 = pathFn(i / numStitches);
    let p2 = pathFn((i + 1) / numStitches);
    brush.set("2B", "#0d1828", 0.85);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Second pass: individual needle holes, thread shadows, twisted ochre-slate threads & highlights
  for (let i = 0; i < numStitches; i++) {
    let p1 = pathFn((i + 0.08) / numStitches);
    let p2 = pathFn((i + 0.86) / numStitches);

    // Slight characteristic lockstitch slant
    let dx = p2.x - p1.x;
    let dy = p2.y - p1.y;
    let nx = -dy * 0.08;
    let ny = dx * 0.08;

    let sx1 = p1.x - nx;
    let sy1 = p1.y - ny;
    let sx2 = p2.x + nx;
    let sy2 = p2.y + ny;

    // Needle puncture holes at stitch ends
    brush.set("rotring", "#060c16", 0.95);
    brush.line(sx1, sy1, sx1 + dx * 0.08, sy1 + dy * 0.08);
    brush.line(sx2, sy2, sx2 - dx * 0.08, sy2 - dy * 0.08);

    // Underside shadow of the plump thread
    brush.set("2B", "#151a22", 0.8);
    brush.line(sx1 + 1.2, sy1 + 1.4, sx2 + 1.2, sy2 + 1.4);

    // Main body of weathered golden-tan / muted amber-slate contrast thread
    brush.set("cpencil", "#8a7352", 0.95);
    brush.line(sx1, sy1, sx2, sy2);

    brush.set("cpencil", "#ad936b", 0.78);
    brush.line(
      lerp(sx1, sx2, 0.12) - 0.5,
      lerp(sy1, sy2, 0.12) - 0.5,
      lerp(sx1, sx2, 0.88) - 0.5,
      lerp(sy1, sy2, 0.88) - 0.5
    );

    // Sunlit twisted ply highlight on the center of each stitch
    brush.set("needle", "#d9c5a0", 0.85);
    brush.line(
      lerp(sx1, sx2, 0.22) - 0.8,
      lerp(sy1, sy2, 0.22) - 0.8,
      lerp(sx1, sx2, 0.78) - 0.8,
      lerp(sy1, sy2, 0.78) - 0.8
    );
  }
}

// ============================================================================
// 6. FRAYED KEYHOLE BUTTONHOLE ON LOWER LAPEL
// ============================================================================

function drawFrayedButtonhole() {
  // Local buttonhole coordinates:
  // Keyhole eyelet centered at (-42, 0), slit extending to (+54, 0), bar-tack at (+54..+66, 0)

  // 1. Raised fabric welt & shadow around the buttonhole
  brush.noStroke();
  brush.fill("#111e30", 145);
  brush.fillBleed(0.18, "out");
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 30) {
    let rx = a > 90 && a < 270 ? -42 + cos(a) * 24 : 58 + cos(a) * 18;
    let ry = sin(a) * (a > 90 && a < 270 ? 22 : 15);
    let p = btnPt(rx, ry + 3);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);

  // Dark cut slit interior (revealing dark shadow inside the buttonhole)
  brush.wash("#070d17", 240);
  brush.beginShape(0.2);
  let slitPts = [
    [-51, -4], [-46, -8], [-38, -8], [-32, -4],
    [52, -3.5], [55, 0], [52, 3.5],
    [-32, 4], [-38, 8], [-46, 8], [-51, 4]
  ];
  for (let pt of slitPts) {
    let p = btnPt(pt[0], pt[1]);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();
  brush.noFill();

  // Deep ink reinforcement inside the slit
  for (let lx = -48; lx <= 52; lx += 2.5) {
    let halfH = lx < -32 ? map(abs(lx + 42), 0, 10, 7.2, 3.2, true) : 3.0;
    let p1 = btnPt(lx, -halfH);
    let p2 = btnPt(lx, halfH);
    brush.set("rotring", "#050a12", 1.1);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // 2. Dense radial purl / whip stitching around the keyhole eyelet (-42, 0)
  for (let a = 32; a <= 328; a += 7.5) {
    let rIn = 6.8;
    let rOut = 18.5 + (noise(a * 0.1) - 0.5) * 3;
    let pIn = btnPt(-42 + cos(a) * rIn, sin(a) * rIn * 0.92);
    let pOut = btnPt(-42 + cos(a) * rOut, sin(a) * rOut * 0.92);

    // Shadow between purl stitches
    brush.set("2B", "#0b1524", 0.75);
    brush.line(pIn.x + 1, pIn.y + 1, pOut.x + 1, pOut.y + 1);

    // Slate-indigo & weathered thread purl stitch
    let isLit = sin(a + BROT) < 0;
    let tCol = isLit ? (random() < 0.5 ? "#6a829c" : "#889fb8") : "#2a3e57";
    brush.set("cpencil", tCol, 0.82);
    brush.line(pIn.x, pIn.y, pOut.x, pOut.y);

    // Purl knot bead along the inner rim
    let kCol = isLit ? "#b5c7d9" : "#445b75";
    brush.set("needle", kCol, 0.95);
    let pKnot = btnPt(-42 + cos(a) * (rIn + 2.2), sin(a) * (rIn + 2.2) * 0.92);
    brush.line(pIn.x, pIn.y, pKnot.x, pKnot.y);
  }

  // 3. Upper and Lower Lip Purl Stitches along the straight slit (-31 to +50)
  for (let lx = -31; lx <= 50; lx += 2.6) {
    // Upper lip (lit from top-left)
    let uIn = btnPt(lx, -3.2);
    let uOut = btnPt(lx + random(-0.8, 0.8), -14.5 + (noise(lx * 0.2) - 0.5) * 2.5);
    brush.set("2B", "#0d1829", 0.7);
    brush.line(uIn.x + 1, uIn.y + 1, uOut.x + 1, uOut.y + 1);
    brush.set("cpencil", random(["#546d88", "#6d86a1", "#3d546e"]), 0.78);
    brush.line(uIn.x, uIn.y, uOut.x, uOut.y);
    brush.set("needle", "#b8cada", 0.75);
    let uBead = btnPt(lx, -5.8);
    brush.line(uIn.x, uIn.y, uBead.x, uBead.y);

    // Lower lip (more in shadow, with bright top purl edge)
    let lIn = btnPt(lx, 3.2);
    let lOut = btnPt(lx + random(-0.8, 0.8), 14.5 + (noise(lx * 0.2 + 9) - 0.5) * 2.5);
    brush.set("2B", "#091220", 0.78);
    brush.line(lIn.x + 1, lIn.y + 1, lOut.x + 1, lOut.y + 1);
    brush.set("cpencil", random(["#24374f", "#334963", "#465e78"]), 0.78);
    brush.line(lIn.x, lIn.y, lOut.x, lOut.y);
    brush.set("needle", "#9cb2c7", 0.8);
    let lBead = btnPt(lx, 5.8);
    brush.line(lIn.x, lIn.y, lBead.x, lBead.y);
  }

  // 4. Heavy Bar-Tack at the inner tail of the buttonhole (+50 to +65)
  for (let lx = 50; lx <= 65; lx += 2.0) {
    let t1 = btnPt(lx, -12);
    let t2 = btnPt(lx, 12);
    brush.set("2B", "#0e1a2b", 0.75);
    brush.line(t1.x + 1, t1.y + 1, t2.x + 1, t2.y + 1);
    brush.set("cpencil", random(["#4e6680", "#69829c", "#7f96ae"]), 0.75);
    brush.line(t1.x, t1.y, t2.x, t2.y);
  }

  // 5. FRAYED RAW WHITE & PALE INDIGO COTTON THREADS bursting from the cut slit & rim!
  let fraySeeds = [
    { lx: -45, ly: -5, ang: -125, len: 22, curl: -35 },
    { lx: -41, ly: -6, ang: -85,  len: 28, curl: 42 },
    { lx: -36, ly: -5, ang: -55,  len: 19, curl: -28 },
    { lx: -28, ly: -4, ang: -110, len: 25, curl: 30 },
    { lx: -21, ly: -4, ang: -70,  len: 31, curl: 55 },
    { lx: -14, ly: -3, ang: -95,  len: 17, curl: -25 },
    { lx: -6,  ly: -4, ang: -60,  len: 24, curl: 38 },
    { lx: 4,   ly: -3, ang: -105, len: 29, curl: -48 },
    { lx: 12,  ly: -4, ang: -80,  len: 21, curl: 25 },
    { lx: 22,  ly: -3, ang: -50,  len: 26, curl: 45 },
    { lx: 33,  ly: -4, ang: -90,  len: 18, curl: -30 },
    { lx: 43,  ly: -3, ang: -65,  len: 22, curl: 35 },
    // Lower edge frays
    { lx: -46, ly: 5,  ang: 135,  len: 24, curl: 40 },
    { lx: -38, ly: 6,  ang: 95,   len: 32, curl: -50 },
    { lx: -30, ly: 4,  ang: 75,   len: 20, curl: 30 },
    { lx: -20, ly: 4,  ang: 110,  len: 27, curl: -35 },
    { lx: -11, ly: 3,  ang: 65,   len: 34, curl: 55 },
    { lx: -2,  ly: 4,  ang: 90,   len: 22, curl: -25 },
    { lx: 8,   ly: 3,  ang: 120,  len: 28, curl: 45 },
    { lx: 18,  ly: 4,  ang: 80,   len: 19, curl: -38 },
    { lx: 28,  ly: 4,  ang: 60,   len: 25, curl: 32 },
    { lx: 38,  ly: 3,  ang: 100,  len: 21, curl: -42 },
    // Short unruly tufts inside the keyhole
    { lx: -49, ly: 0,  ang: 175,  len: 16, curl: 28 },
    { lx: -35, ly: 1,  ang: 15,   len: 14, curl: -32 },
    { lx: 0,   ly: 0,  ang: -25,  len: 15, curl: 35 },
    { lx: 15,  ly: 1,  ang: 35,   len: 16, curl: -30 }
  ];

  for (let f of fraySeeds) {
    // Draw main frayed yarn and 1-2 micro-fibrils splitting off the tip
    for (let sub = 0; sub < 2; sub++) {
      let p0 = btnPt(f.lx + sub * 1.2, f.ly);
      let a1 = BROT + f.ang + sub * 12;
      let a2 = a1 + f.curl * 0.55;
      let a3 = a1 + f.curl;
      let l = f.len * (sub === 0 ? 1.0 : 0.72);

      let p1 = { x: p0.x + cos(a1) * (l * 0.35), y: p0.y + sin(a1) * (l * 0.35) };
      let p2 = { x: p1.x + cos(a2) * (l * 0.35), y: p1.y + sin(a2) * (l * 0.35) };
      let p3 = { x: p2.x + cos(a3) * (l * 0.30), y: p2.y + sin(a3) * (l * 0.30) };

      // Cast shadow of the frayed cotton thread onto the dark buttonhole stitches
      brush.set("2B", "#08101c", 0.48);
      brush.spline([
        [p0.x + 1.5, p0.y + 2.0, 0.5],
        [p1.x + 1.8, p1.y + 2.2, 0.7],
        [p2.x + 2.0, p2.y + 2.4, 0.5],
        [p3.x + 2.0, p3.y + 2.4, 0.2]
      ], 0.5);

      // Raw ecru/white cotton fiber
      let fiberCol = sub === 0 ? "#f0f2f5" : "#cad8e6";
      brush.set("cotton_slub", fiberCol, sub === 0 ? 0.72 : 0.48);
      brush.spline([
        [p0.x, p0.y, 0.7],
        [p1.x, p1.y, 0.9],
        [p2.x, p2.y, 0.7],
        [p3.x, p3.y, 0.3]
      ], 0.55);

      // Crisp highlight on the bend of the thread
      if (sub === 0) {
        brush.set("needle", "#ffffff", 0.65);
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }
    }
  }
}

// ============================================================================
// 7. BURNISHED COPPER RIVET AT YOKE / POCKET SEAM JUNCTION
// ============================================================================

function drawCopperRivet() {
  let rBurr = 25.5;
  let rPost = 9.8;

  // 1. Cast shadow & recessed fabric dimple around the copper washer
  brush.noStroke();
  brush.fill("#070f1b", 185);
  brush.fillBleed(0.15, "out");
  brush.circle(RX + 4.5, RY + 6.0, rBurr + 4.5, 0.12);

  // 2. Base metallic washes for the copper burr (washer)
  // Deep burnt umber / mahogany copper core
  brush.wash("#4a2014", 240);
  brush.circle(RX, RY, rBurr, 0.06);

  // Warm burnished copper midtone
  brush.fill("#b55835", 175);
  brush.fillBleed(0.08, "in");
  brush.circle(RX - 1.5, RY - 1.5, rBurr - 1.5, 0.06);
  brush.noFill();
  brush.noWash();

  // 3. Radial metallic pencil rendering across the domed copper washer
  for (let a = 0; a < 360; a += 2.5) {
    let rad1 = rPost + 1.5;
    let rad2 = rBurr - 0.8;

    // Metallic anisotropic reflection zones (bright at upper-left -130 deg and lower-right +45 deg)
    let refl1 = cos(a + 132);
    let refl2 = cos((a - 42) * 2);

    let col;
    let w = 0.65;
    if (refl1 > 0.65) {
      col = refl1 > 0.88 ? "#ffe8d6" : "#eb9971";
      w = 0.75;
    } else if (refl1 > 0.15) {
      col = "#cc6f47";
    } else if (refl2 > 0.55 && a > 0 && a < 110) {
      // Secondary warm bounce reflection on lower-right
      col = "#d97e54";
    } else if (a > 65 && a < 165) {
      // Deep dark reflection of the indigo denim
      col = "#2e1510";
      w = 0.75;
    } else {
      col = "#7a3620";
    }

    brush.set("cpencil", col, w);
    brush.line(
      RX + cos(a) * rad1,
      RY + sin(a) * rad1,
      RX + cos(a) * rad2,
      RY + sin(a) * rad2
    );
  }

  // 4. Concentric stamped ring & micro-embossed lettering impressions ("LS & CO - SF")
  brush.set("rotring", "#2b120b", 0.55);
  brush.arc(RX, RY, rBurr, 0, 360);
  brush.arc(RX, RY, rBurr - 5.2, 0, 360);

  // Tiny stamped geometric character ticks around the flange (r = 14 to 18.5)
  for (let a = 12; a < 350; a += 18) {
    if (abs(a - 180) < 22) continue; // Small gap between stamped words
    let rMid = 16.2;
    let lx = RX + cos(a) * rMid;
    let ly = RY + sin(a) * rMid;
    let tang = a + 90;

    // Stamped recess shadow
    brush.set("needle", "#2e130c", 0.75);
    brush.line(lx - cos(tang) * 1.8, ly - sin(tang) * 1.8, lx + cos(tang) * 1.8, ly + sin(tang) * 1.8);
    brush.line(lx - cos(a) * 1.6, ly - sin(a) * 1.6, lx + cos(a) * 1.6, ly + sin(a) * 1.6);

    // Bright copper catchlight on the stamped letter edge
    brush.set("needle", "#f7b694", 0.65);
    brush.line(
      lx + 0.7 - cos(tang) * 1.5,
      ly + 0.7 - sin(tang) * 1.5,
      lx + 0.7 + cos(tang) * 1.5,
      ly + 0.7 + sin(tang) * 1.5
    );
  }

  // 5. Subtle verdigris / cool oxidation patina tucked in the lower-left crevice
  for (let a = 125; a <= 205; a += 6) {
    brush.set("cpencil", "#668c82", 0.55);
    brush.line(
      RX + cos(a) * (rPost + 0.8),
      RY + sin(a) * (rPost + 0.8),
      RX + cos(a) * (rPost + 3.2),
      RY + sin(a) * (rPost + 3.2)
    );
  }

  // Outer bevel highlight on upper-left rim of the copper burr
  brush.set("cpencil", "#ffd8bf", 0.85);
  brush.arc(RX, RY, rBurr - 1.2, 190, 295);
  brush.set("needle", "#ffffff", 0.8);
  brush.arc(RX, RY, rBurr - 1.0, 212, 268);

  // 6. Central Peened Copper Post (Protruding riveted center)
  // Dark crevice moat around the post
  brush.set("rotring", "#1f0c07", 0.9);
  brush.arc(RX, RY, rPost + 1.0, 0, 360);

  // Domed post fill
  brush.noStroke();
  brush.wash("#592616", 245);
  brush.circle(RX, RY, rPost, 0.08);
  brush.noWash();

  // Hammered facets on the peened copper post
  for (let a = 0; a < 360; a += 8) {
    let isBright = a > 195 && a < 305;
    let c = isBright ? "#f2a77e" : (a > 30 && a < 145 ? "#33140c" : "#a84e2c");
    brush.set("cpencil", c, 0.65);
    brush.line(RX, RY, RX + cos(a) * (rPost - 0.8), RY + sin(a) * (rPost - 0.8));
  }

  // Specular sky highlight on the dome of the central post
  brush.set("cpencil", "#ffe5d1", 0.9);
  brush.arc(RX - 0.5, RY - 0.5, rPost * 0.62, 200, 290);
  brush.set("needle", "#ffffff", 0.95);
  brush.line(RX - 5.2, RY - 3.8, RX - 1.8, RY - 5.5);

  // Tiny tuft of white cotton denim thread pinched under the top-right edge of the rivet
  brush.set("cotton_slub", "#e6eef5", 0.65);
  brush.spline([
    [RX + 19, RY - 17, 0.6],
    [RX + 25, RY - 23, 0.8],
    [RX + 31, RY - 21, 0.3]
  ], 0.5);
}

// ============================================================================
// 8. SAGUARO CACTUS ENAMEL PIN (HYPERREAL CENTERPIECE)
// ============================================================================

function drawSaguaroEnamelPin() {
  // --------------------------------------------------------------------------
  // STEP 1: Deep multi-layered Cast Shadow & Warm Gold Bounce Light on Denim
  // --------------------------------------------------------------------------
  brush.noStroke();
  // Soft ambient occlusion & overcast shadow offset to (+13, +19)
  brush.fill("#07101d", 175);
  brush.fillBleed(0.24, "out");
  brush.circle(PX + 14, PY + 20, PR + 10, 0.14);

  brush.wash("#050b14", 215);
  brush.circle(PX + 8, PY + 11, PR + 3, 0.08);
  brush.noWash();

  // Warm gold reflection bouncing off the metal bezel onto the adjacent denim ridges
  brush.fill("#b89550", 42);
  brush.fillBleed(0.25, "out");
  brush.circle(PX - 12, PY - 10, PR + 16, 0.2);
  brush.noFill();

  // Crisp contact shadow hatched with dark indigo right under the pin rim
  for (let a = -35; a <= 195; a += 2.2) {
    let sLen = map(sin(a - 45), -1, 1, 6, 24);
    let r0 = PR - 1;
    let x0 = PX + cos(a) * r0;
    let y0 = PY + sin(a) * r0;
    brush.set("2B", "#050b14", 0.85);
    brush.line(x0, y0, x0 + cos(a) * (sLen * 0.55) + 4, y0 + sin(a) * (sLen * 0.55) + 6);
  }

  // --------------------------------------------------------------------------
  // STEP 2: 3D Gold Metal Outer Wall (Thickness of the die-struck brass pin)
  // --------------------------------------------------------------------------
  // The pin has physical depth (~7.5px visible on lower-right rim)
  for (let a = 0; a < 360; a += 1.5) {
    let pTop = { x: PX + cos(a) * PR, y: PY + sin(a) * PR };
    // Thickness vector shifts toward (+4.5, +6.5) on the lower-right
    let rimShift = max(0, cos(a - 52)) * 6.5 + 1.8;
    let pBot = {
      x: pTop.x + cos(52) * rimShift,
      y: pTop.y + sin(52) * rimShift
    };

    // Metallic banding around the cylindrical gold edge
    let refl = cos((a + 135) * 2);
    let col;
    if (a > 195 && a < 275) col = "#f5df9d";
    else if (refl > 0.55) col = "#d6ad54";
    else if (refl < -0.45) col = "#3b280e";
    else col = "#8f6926";

    brush.set("cpencil", col, 0.85);
    brush.line(pTop.x, pTop.y, pBot.x, pBot.y);
  }

  // Solid base disc of the pin face (dark bronze-gold backing)
  brush.noStroke();
  brush.wash("#614518", 255);
  brush.circle(PX, PY, PR, 0.02);
  brush.noWash();

  // --------------------------------------------------------------------------
  // STEP 3: SUNSET-PINK ENAMEL FILLS (Smooth vitrified hard-enamel cells)
  // --------------------------------------------------------------------------
  let rEnamel = 100; // Inner radius of the outer gold bezel

  // 3A. Upper Sunset Sky Dome (Warm dusty sunset-pink / rose-terracotta)
  brush.noStroke();
  brush.wash("#d98074", 250);
  brush.circle(PX, PY, rEnamel, 0.02);
  brush.noWash();

  // Soft watercolor & pastel gradient inside the sunset sky (warmer coral near horizon)
  brush.fill("#eb9b8e", 130);
  brush.fillBleed(0.08, "in");
  brush.circle(PX, PY, rEnamel - 3, 0.03);
  brush.noFill();

  // 3B. Radiant Desert Sun Disc Cell at local (-28, -22), radius 33
  let sunC = pinPt(-28, -22);
  brush.noStroke();
  brush.wash("#f5bca9", 245);
  brush.circle(sunC.x, sunC.y, 33, 0.02);
  brush.noWash();

  // 3C. Mid-Horizon Band (y_local from +14 to +54): Deeper sunset rose-coral
  brush.noStroke();
  brush.wash("#c86b60", 245);
  brush.beginShape(0.1);
  for (let a = 8; a <= 172; a += 6) {
    let p = pinPt(cos(a) * rEnamel, sin(a) * rEnamel);
    brush.vertex(p.x, p.y);
  }
  for (let lx = -96; lx <= 96; lx += 12) {
    let ly = 16 - cos((lx / 96) * 90) * 8;
    let p = pinPt(lx, ly);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // 3D. Foreground Desert Dune Band (y_local from +50 to bottom): Muted mauve-terracotta pink
  brush.noStroke();
  brush.wash("#b35850", 248);
  brush.beginShape(0.1);
  for (let a = 30; a <= 150; a += 6) {
    let p = pinPt(cos(a) * rEnamel, sin(a) * rEnamel);
    brush.vertex(p.x, p.y);
  }
  for (let lx = -84; lx <= 84; lx += 12) {
    let ly = 52 + sin((lx / 84) * 180) * 6;
    let p = pinPt(lx, ly);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Dense, velvety colored-pencil & marker polishing across the pink enamel cells
  // so the surface reads as smooth, glossy fired enamel with subtle meniscus shading
  for (let ly = -96; ly <= 96; ly += 1.6) {
    let halfW = sqrt(max(0, rEnamel * rEnamel - ly * ly)) - 1.5;
    if (halfW <= 2) continue;

    let horizonY1 = 16 - cos((0) * 90) * 8;
    let baseCol;
    if (ly < 12) {
      baseCol = map(ly, -96, 12, 0, 1) < 0.5 ? "#d67b70" : "#e69386";
    } else if (ly < 50) {
      baseCol = "#c7695e";
    } else {
      baseCol = "#b2574f";
    }

    let pLeft = pinPt(-halfW, ly);
    let pRight = pinPt(halfW, ly);
    brush.set("cpencil", baseCol, 0.72);
    brush.line(pLeft.x, pLeft.y, pRight.x, pRight.y);

    // Subtle Lighter Center Sheen on the pink enamel
    if (halfW > 18) {
      let pMidL = pinPt(-halfW * 0.65, ly);
      let pMidR = pinPt(halfW * 0.65, ly);
      let sheenCol = ly < 12 ? "#f0a699" : (ly < 50 ? "#d97e73" : "#c46a62");
      brush.set("cpencil", sheenCol, 0.55);
      brush.line(pMidL.x, pMidL.y, pMidR.x, pMidR.y);
    }

    // Concave meniscus darkening right inside the outer gold bezel
    let pRimL1 = pinPt(-halfW, ly);
    let pRimL2 = pinPt(-halfW + 6, ly);
    brush.set("cpencil", "#96443d", 0.65);
    brush.line(pRimL1.x, pRimL1.y, pRimL2.x, pRimL2.y);

    let pRimR1 = pinPt(halfW - 6, ly);
    let pRimR2 = pinPt(halfW, ly);
    brush.set("cpencil", "#9e4942", 0.65);
    brush.line(pRimR1.x, pRimR1.y, pRimR2.x, pRimR2.y);
  }

  // Polish the Sun Disc Cell in luminous warm coral-peach pink
  for (let sy = -31; sy <= 31; sy += 1.6) {
    let shw = sqrt(max(0, 31 * 31 - sy * sy));
    let p1 = pinPt(-28 - shw, -22 + sy);
    let p2 = pinPt(-28 + shw, -22 + sy);
    brush.set("cpencil", sy < 0 ? "#f7c4b2" : "#edb09d", 0.68);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // --------------------------------------------------------------------------
  // STEP 4: SAGE ENAMEL SAGUARO CACTUS FILLS
  // --------------------------------------------------------------------------
  let saguaroOutlineLocal = getSaguaroContourPoints();

  // Base opaque wash of muted desert sage green
  brush.noStroke();
  brush.wash("#6c8c76", 252);
  brush.beginShape(0.08);
  for (let pt of saguaroOutlineLocal) {
    let p = pinPt(pt[0], pt[1]);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Vertical enamel polishing & meniscus shading inside the Saguaro Cactus
  // Main trunk (lx: -16.5 to +16.5, ly: -74 to +98)
  for (let lx = -16; lx <= 16; lx += 1.3) {
    let domeCut = sqrt(max(0, 16.5 * 16.5 - lx * lx));
    let lyTop = -58 - domeCut;
    let lyBot = sqrt(max(0, rEnamel * rEnamel - lx * lx)) - 1;

    // Determine cell color between internal gold ribs (at lx = -5.5 and lx = +5.5)
    let distEdge = min(abs(lx - (-16.5)), abs(lx - 16.5), abs(lx - (-5.5)), abs(lx - 5.5));
    let col = distEdge < 2.2 ? "#4e6b57" : (lx < 4 ? "#82a38c" : "#6b8c75");

    let p1 = pinPt(lx, lyTop);
    let p2 = pinPt(lx, lyBot);
    brush.set("cpencil", col, 0.72);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Left Arm Sage Polishing (centerline curves from (-16, 16) to (-52, 16) up to (-52, -40))
  drawSaguaroArmEnamel(-1);
  // Right Arm Sage Polishing (centerline curves from (16, -2) to (52, -2) up to (52, -52))
  drawSaguaroArmEnamel(1);

  // Tiny Sunset-Pink & Coral Blossoms crowning the Saguaro Trunk and Arms
  let blossoms = [
    { lx: 0,   ly: -77, r: 6.5 },
    { lx: -52, ly: -52, r: 5.5 },
    { lx: 52,  ly: -64, r: 5.5 }
  ];
  for (let b of blossoms) {
    let bc = pinPt(b.lx, b.ly);
    brush.noStroke();
    brush.wash("#f2a898", 250);
    brush.circle(bc.x, bc.y, b.r, 0.05);
    brush.noWash();
    brush.set("cpencil", "#ffd1c4", 0.65);
    brush.circle(bc.x - 1, bc.y - 1, b.r * 0.55, 0.05);
  }

  // --------------------------------------------------------------------------
  // STEP 5: GOLD DIE-STRUCK BORDERS (Raised Cloisonné Walls with 3D Bevels)
  // --------------------------------------------------------------------------
  // A. Sun Disc Gold Ring (masked behind the saguaro)
  let sunRingPts = [];
  for (let a = 0; a <= 360; a += 6) {
    let lx = -28 + cos(a) * 33;
    let ly = -22 + sin(a) * 33;
    if (!isInsideSaguaro(lx, ly)) {
      sunRingPts.push([lx, ly]);
    } else if (sunRingPts.length > 1) {
      drawGoldCloisonPath(sunRingPts, 1.45, false);
      sunRingPts = [];
    } else {
      sunRingPts = [];
    }
  }
  if (sunRingPts.length > 1) drawGoldCloisonPath(sunRingPts, 1.45, false);

  // B. Upper Horizon Gold Line (y_local ~ 16)
  let hLine1 = [];
  for (let lx = -97; lx <= 97; lx += 3) {
    let ly = 16 - cos((lx / 98) * 90) * 8;
    if (lx * lx + ly * ly < rEnamel * rEnamel && !isInsideSaguaro(lx, ly)) {
      hLine1.push([lx, ly]);
    } else if (hLine1.length > 1) {
      drawGoldCloisonPath(hLine1, 1.5, false);
      hLine1 = [];
    } else {
      hLine1 = [];
    }
  }
  if (hLine1.length > 1) drawGoldCloisonPath(hLine1, 1.5, false);

  // C. Lower Dune Gold Line (y_local ~ 52)
  let hLine2 = [];
  for (let lx = -86; lx <= 86; lx += 3) {
    let ly = 52 + sin((lx / 86) * 180) * 6;
    if (lx * lx + ly * ly < rEnamel * rEnamel && !isInsideSaguaro(lx, ly)) {
      hLine2.push([lx, ly]);
    } else if (hLine2.length > 1) {
      drawGoldCloisonPath(hLine2, 1.5, false);
      hLine2 = [];
    } else {
      hLine2 = [];
    }
  }
  if (hLine2.length > 1) drawGoldCloisonPath(hLine2, 1.5, false);

  // D. Saguaro Cactus Outer Gold Die-Struck Contour
  drawGoldCloisonPath(saguaroOutlineLocal, 1.95, true);

  // E. Internal Gold Ribs inside the Saguaro Trunk & Arms
  // Left trunk rib
  let ribL = [];
  for (let ly = -71; ly <= 97; ly += 4) ribL.push([-5.8, ly]);
  drawGoldCloisonPath(ribL, 1.35, false);

  // Right trunk rib
  let ribR = [];
  for (let ly = -71; ly <= 97; ly += 4) ribR.push([5.8, ly]);
  drawGoldCloisonPath(ribR, 1.35, false);

  // Left arm center gold rib
  let armRibL = [
    [-16.5, 16], [-36, 16], [-46, 13], [-51, 5], [-52, -6], [-52, -46]
  ];
  drawGoldCloisonPath(armRibL, 1.3, false);

  // Right arm center gold rib
  let armRibR = [
    [16.5, -2], [36, -2], [46, -5], [51, -13], [52, -24], [52, -58]
  ];
  drawGoldCloisonPath(armRibR, 1.3, false);

  // Tiny gold spine ticks along the cactus contour
  let spineLocs = [
    [-17, -48, -155], [-17, -22, -165], [-17, 42, -160], [-17, 70, -165],
    [17, -45, -20],   [17, -22, -15],   [17, 25, -20],   [17, 58, -15],
    [-64, -28, -165], [-64, -6, -155],  [-40, -24, -20],
    [64, -40, -15],   [64, -18, -25],   [40, -36, -160]
  ];
  for (let sp of spineLocs) {
    let p0 = pinPt(sp[0], sp[1]);
    let p1 = pinPt(sp[0] + cos(sp[2]) * 5.2, sp[1] + sin(sp[2]) * 5.2);
    brush.set("needle", "#4a3310", 0.75);
    brush.line(p0.x + 0.8, p0.y + 0.8, p1.x + 0.8, p1.y + 0.8);
    brush.set("needle", "#f5da8e", 0.8);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Gold borders around the 3 crown blossoms
  for (let b of blossoms) {
    let bPts = [];
    for (let a = 0; a <= 360; a += 20) {
      bPts.push([b.lx + cos(a) * b.r, b.ly + sin(a) * b.r]);
    }
    drawGoldCloisonPath(bPts, 1.15, true);
  }

  // F. Outer Thick Gold Die-Struck Bezel Ring (r = 99 to 114)
  drawOuterGoldBezel(rEnamel, PR);

  // --------------------------------------------------------------------------
  // STEP 6: REFLECTED WINDOW HIGHLIGHT (4-Pane Overcast Studio Window)
  // --------------------------------------------------------------------------
  drawWindowReflectionOnPin(rEnamel);

  // --------------------------------------------------------------------------
  // STEP 7: THE TINY SCRATCH (Across the Sage Arm, Gold Border & Pink Enamel)
  // --------------------------------------------------------------------------
  drawPinScratch();
}

// Helper for Saguaro Arm Sage Enamel Polishing
function drawSaguaroArmEnamel(side) {
  let yBase = side < 0 ? 16 : -2;
  let yTip = side < 0 ? -40 : -52;
  let xArm = side * 52;

  // Vertical riser of the arm
  for (let dr = -10.5; dr <= 10.5; dr += 1.3) {
    let lx = xArm + dr;
    let dome = sqrt(max(0, 11 * 11 - dr * dr));
    let ly1 = yTip - dome;
    let ly2 = yBase + 4;
    let col = abs(dr) > 8.5 ? "#4c6955" : (dr < 0 ? "#85a68f" : "#688871");
    let p1 = pinPt(lx, ly1);
    let p2 = pinPt(lx, ly2);
    brush.set("cpencil", col, 0.7);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Horizontal elbow connecting arm to main trunk
  for (let dy = -10.5; dy <= 10.5; dy += 1.3) {
    let ly = yBase + dy;
    let lx1 = side * 16;
    let lx2 = xArm + side * 6;
    let col = abs(dy) > 8.5 ? "#4c6955" : (dy < 0 ? "#82a38c" : "#64846d");
    let p1 = pinPt(lx1, ly);
    let p2 = pinPt(lx2, ly);
    brush.set("cpencil", col, 0.7);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Construct local points for the Saguaro Cactus contour
function getSaguaroContourPoints() {
  let pts = [];
  // Start at bottom-left of main trunk where it meets the gold bezel (r = 99)
  pts.push([-16.5, 97.5]);
  pts.push([-16.5, 27.5]);

  // Left arm underside elbow
  pts.push([-43, 27.5]);
  pts.push([-55, 24.5]);
  pts.push([-61.5, 17.5]);
  pts.push([-63.5, 7]);
  pts.push([-63.5, -40]);

  // Left arm rounded dome tip (center (-52, -40), r = 11.5)
  for (let a = 180; a <= 360; a += 20) {
    pts.push([-52 + cos(a) * 11.5, -40 + sin(a) * 11.5]);
  }

  // Left arm inner side down to trunk
  pts.push([-40.5, 5]);
  pts.push([-37, 6.5]);
  pts.push([-16.5, 6.5]);

  // Main trunk left side up to crown
  pts.push([-16.5, -58]);

  // Main trunk rounded crown (center (0, -58), r = 16.5)
  for (let a = 180; a <= 360; a += 15) {
    pts.push([cos(a) * 16.5, -58 + sin(a) * 16.5]);
  }

  // Main trunk right side down to right arm
  pts.push([16.5, -11.5]);
  pts.push([37, -11.5]);
  pts.push([40.5, -13]);

  // Right arm inner side up to tip
  pts.push([40.5, -52]);

  // Right arm rounded dome tip (center (52, -52), r = 11.5)
  for (let a = 180; a <= 360; a += 20) {
    pts.push([52 + cos(a) * 11.5, -52 + sin(a) * 11.5]);
  }

  // Right arm outer side & elbow
  pts.push([63.5, -11]);
  pts.push([61.5, -0.5]);
  pts.push([55, 6.5]);
  pts.push([43, 9.5]);
  pts.push([16.5, 9.5]);

  // Main trunk right side down to bottom bezel
  pts.push([16.5, 97.5]);
  return pts;
}

// Point-in-saguaro test (local pin coordinates) for masking background lines
function isInsideSaguaro(lx, ly) {
  // Main trunk
  if (abs(lx) <= 17.8 && ly >= -58 && ly <= 99) return true;
  if (dist(lx, ly, 0, -58) <= 17.8) return true;
  // Left arm
  if (lx >= -64.5 && lx <= -16 && ly >= 5.5 && ly <= 28.5) return true;
  if (lx >= -64.5 && lx <= -39.5 && ly >= -40 && ly <= 18) return true;
  if (dist(lx, ly, -52, -40) <= 12.5) return true;
  // Right arm
  if (lx >= 16 && lx <= 64.5 && ly >= -12.5 && ly <= 10.5) return true;
  if (lx >= 39.5 && lx <= 64.5 && ly >= -52 && ly <= 0) return true;
  if (dist(lx, ly, 52, -52) <= 12.5) return true;
  return false;
}

// Render a raised 3D gold die-struck cloisonné border path
function drawGoldCloisonPath(localPts, widthScale, closed) {
  if (localPts.length < 2) return;
  let n = closed ? localPts.length : localPts.length - 1;

  // Pass 1: Recessed meniscus shadow on the lower-right side of the gold wall
  for (let i = 0; i < n; i++) {
    let a = localPts[i];
    let b = localPts[(i + 1) % localPts.length];
    let p1 = pinPt(a[0] + 1.4, a[1] + 1.6);
    let p2 = pinPt(b[0] + 1.4, b[1] + 1.6);
    brush.set("2B", "#3b2316", 0.65 * widthScale);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Pass 2: Dark bronze-umber bevel edge
  for (let i = 0; i < n; i++) {
    let a = localPts[i];
    let b = localPts[(i + 1) % localPts.length];
    let p1 = pinPt(a[0] + 0.5, a[1] + 0.6);
    let p2 = pinPt(b[0] + 0.5, b[1] + 0.6);
    brush.set("rotring", "#543b14", 0.88 * widthScale);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Pass 3: Rich 18k flat-polished gold body
  for (let i = 0; i < n; i++) {
    let a = localPts[i];
    let b = localPts[(i + 1) % localPts.length];
    let p1 = pinPt(a[0], a[1]);
    let p2 = pinPt(b[0], b[1]);
    brush.set("cpencil", "#d4aa4c", 0.82 * widthScale);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Pass 4: Specular champagne-gold highlight on the upper-left bevel
  for (let i = 0; i < n; i++) {
    let a = localPts[i];
    let b = localPts[(i + 1) % localPts.length];
    let p1 = pinPt(a[0] - 0.6, a[1] - 0.6);
    let p2 = pinPt(b[0] - 0.6, b[1] - 0.6);
    // Check if inside window highlight zone for extra white-gold gleam
    let inWin = (a[0] > -75 && a[0] < 22 && a[1] > -75 && a[1] < 18);
    let hCol = inWin ? "#ffffff" : "#faebb8";
    brush.set("needle", hCol, (inWin ? 0.95 : 0.72) * widthScale);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Render the thick outer gold bezel ring of the circular enamel pin
function drawOuterGoldBezel(rIn, rOut) {
  // Inner meniscus shadow where the bezel meets the enamel
  brush.set("2B", "#3d2218", 0.9);
  brush.arc(PX + 1.2, PY + 1.4, rIn - 0.5, 0, 360);

  // Radial metallic reflections around the flat-polished gold bezel
  for (let a = 0; a < 360; a += 1.2) {
    let p1 = { x: PX + cos(a) * rIn, y: PY + sin(a) * rIn };
    let p2 = { x: PX + cos(a) * rOut, y: PY + sin(a) * rOut };

    // Anisotropic gold reflections
    let w1 = cos(a + 135);
    let w2 = cos((a - 35) * 3);

    let col;
    if (w1 > 0.78) col = "#fff7d6";
    else if (w1 > 0.35) col = "#e6c367";
    else if (w1 > -0.15) col = "#c4983d";
    else if (w2 > 0.55) col = "#dfb95b";
    else if (a > 40 && a < 125) col = "#593e14";
    else col = "#8c6724";

    brush.set("cpencil", col, 0.78);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Crisp inner and outer gold bevel rims
  brush.set("rotring", "#47300d", 0.65);
  brush.arc(PX, PY, rOut, 0, 360);
  brush.arc(PX, PY, rIn, 0, 360);

  // Brilliant specular arcs on upper-left outer rim & lower-right inner rim
  brush.set("cpencil", "#fff4c2", 0.9);
  brush.arc(PX, PY, rOut - 1.2, 185, 295);
  brush.arc(PX, PY, rIn + 1.0, 10, 115);

  brush.set("needle", "#ffffff", 0.95);
  brush.arc(PX, PY, rOut - 1.0, 208, 265);
  brush.arc(PX, PY, rIn + 0.8, 32, 85);
}

// Render the 4-pane overcast studio window reflection across the glossy enamel & gold
function drawWindowReflectionOnPin(rEnamel) {
  // 4 window panes in local pin coordinates (skewed slightly by perspective)
  // Cross-mullion gap sits around wx = -24 and wy = -26
  let panes = [
    { x1: -68, x2: -28, y1: -64, y2: -30 }, // Top-left pane
    { x1: -19, x2:  20, y1: -64, y2: -30 }, // Top-right pane
    { x1: -68, x2: -28, y1: -21, y2:  14 }, // Bottom-left pane
    { x1: -19, x2:  20, y1: -21, y2:  14 }  // Bottom-right pane
  ];

  // Helper to warp window coordinates slightly for optical curvature across the pin
  function winLocalPt(wx, wy) {
    let skewX = wx - wy * 0.18;
    let skewY = wy + wx * 0.08;
    // Slight spherical bulge near the outer bezel
    let r2 = (skewX * skewX + skewY * skewY) / (rEnamel * rEnamel);
    return {
      lx: skewX * (1 + r2 * 0.08),
      ly: skewY * (1 + r2 * 0.08)
    };
  }

  for (let pane of panes) {
    // Soft translucent daylight glaze for each window pane
    brush.noStroke();
    brush.fill("#f5f9fc", 62);
    brush.fillBleed(0.05, "in");
    brush.beginShape(0.15);
    let corners = [
      winLocalPt(pane.x1, pane.y1),
      winLocalPt(pane.x2, pane.y1),
      winLocalPt(pane.x2, pane.y2),
      winLocalPt(pane.x1, pane.y2)
    ];
    for (let c of corners) {
      let p = pinPt(c.lx, c.ly);
      brush.vertex(p.x, p.y);
    }
    brush.endShape(CLOSE);
    brush.noFill();

    // Fine scanline reflection sheen across the pane (modulating color over pink, sage & gold)
    for (let wy = pane.y1 + 1.2; wy <= pane.y2 - 1.2; wy += 1.5) {
      for (let wx = pane.x1 + 1.5; wx <= pane.x2 - 3.5; wx += 3.5) {
        let w1 = winLocalPt(wx, wy);
        let w2 = winLocalPt(wx + 3.5, wy);

        // Clip to inner enamel circle
        if (w1.lx * w1.lx + w1.ly * w1.ly > (rEnamel - 3) * (rEnamel - 3)) continue;

        let p1 = pinPt(w1.lx, w1.ly);
        let p2 = pinPt(w2.lx, w2.ly);

        // Intensity fades slightly from top-left to bottom-right of the window reflection
        let fade = map(wy + wx, -130, 35, 1.0, 0.45, true);
        let inSag = isInsideSaguaro(w1.lx, w1.ly);
        let onGold = abs(w1.lx - (-16.5)) < 2.2 || abs(w1.lx - 16.5) < 2.2 ||
                     abs(w1.lx - (-5.8)) < 1.8 || abs(w1.lx - 5.8) < 1.8;

        if (onGold) {
          brush.set("needle", "#ffffff", 0.95 * fade);
        } else if (inSag) {
          brush.set("cpencil", "#d8ebe0", 0.62 * fade);
        } else {
          brush.set("cpencil", "#ffe8e2", 0.65 * fade);
        }
        brush.line(p1.x, p1.y, p2.x, p2.y);

        // Extra crisp white specular sheen in the upper-left panes
        if (fade > 0.72 && random() < 0.65) {
          brush.set("needle", "#ffffff", 0.58 * fade);
          brush.line(p1.x, p1.y, p2.x, p2.y);
        }
      }
    }
  }
}

// Render the tiny scratch across the saguaro arm, gold border, and sunset-pink enamel
function drawPinScratch() {
  // Main hairline scratch path in local pin coordinates:
  // Starts on the main sage trunk (-4, 8), cuts across the right gold rib & border,
  // scores the right sage elbow, crosses the outer gold contour at (39, 9.5),
  // and trails off across the sunset-pink enamel to (62, 24)
  let scratchLocal = [
    [-5, 6],
    [8, 9.5],
    [22, 12.5],
    [38, 16.8],
    [51, 21.2],
    [61, 25.0]
  ];

  let upperPts = [];
  let lowerPts = [];
  for (let i = 0; i < scratchLocal.length; i++) {
    let pt = scratchLocal[i];
    let pressure = (i === 0 || i === scratchLocal.length - 1) ? 0.3 : 1.0;
    let pU = pinPt(pt[0], pt[1]);
    let pL = pinPt(pt[0] - 0.3, pt[1] + 1.25);
    upperPts.push([pU.x, pU.y, pressure]);
    lowerPts.push([pL.x, pL.y, pressure]);
  }

  // Dark upper shadow groove of the scratch (turned away from top-left light)
  brush.set("rotring", "#2b1c1a", 0.42);
  brush.spline(upperPts, 0.35);

  // Brilliant white catchlight on the lower bevel lip of the scratch
  brush.set("needle", "#ffffff", 0.92);
  brush.spline(lowerPts, 0.35);

  // Tiny bright metallic nicks where the scratch gouges the raised gold borders
  let goldNickLocs = [
    [5.8, 8.8],
    [16.5, 11.2],
    [38.5, 17.0]
  ];
  for (let nk of goldNickLocs) {
    let pn = pinPt(nk[0], nk[1]);
    brush.set("rotring", "#241608", 0.65);
    brush.line(pn.x - 1.5, pn.y - 1.0, pn.x + 1.5, pn.y + 0.5);
    brush.set("needle", "#ffffff", 1.1);
    brush.line(pn.x - 1.8, pn.y + 0.8, pn.x + 2.2, pn.y + 1.8);
  }

  // Secondary micro-scuff inside the window reflection (visible only in the specular sheen)
  let scuff1 = pinPt(-36, -34);
  let scuff2 = pinPt(-24, -27);
  brush.set("needle", "#ffffff", 0.65);
  brush.line(scuff1.x, scuff1.y, scuff2.x, scuff2.y);
}

