    brush.line(ex + 1, y, ex + 1 + cos(ang) * len, y + sin(ang) * len);
  }

  // 2. Stray Lint, Dust Motes & White Cotton Fibers caught in the coarse twill
  let lintParticles = [
    // Sharp in-focus lint near the pin, pucker ridges, buttonhole, and rivet
    { x: 510, y: 315, len: 18, ang: 28,  curl: 45,  sharp: true },
    { x: 755, y: 395, len: 14, ang: -42, curl: -55, sharp: true },
    { x: 472, y: 545, len: 22, ang: 112, curl: 38,  sharp: true },
