    { x: 585, y: 710, len: 13, ang: 65,  curl: -40, sharp: true },
    { x: 335, y: 620, len: 52, ang: 34,  curl: 28,  sharp: true }, // Fine stray coat hair / long thread
    { x: 785, y: 790, len: 19, ang: -75, curl: 48,  sharp: true },
    { x: 940, y: 830, len: 15, ang: 18,  curl: -35, sharp: true },
    { x: 645, y: 245, len: 17, ang: 82,  curl: 50,  sharp: true },
    { x: 255, y: 465, len: 14, ang: -25, curl: 42,  sharp: true },
    { x: 495, y: 895, len: 21, ang: 48,  curl: -52, sharp: true },
    // Softer out-of-focus lint near the edges
    { x: 180, y: 190, len: 16, ang: 40,  curl: 30,  sharp: false },
    { x: 890, y: 180, len: 20, ang: -30, curl: 45,  sharp: false },
    { x: 1050,y: 520, len: 18, ang: 70,  curl: -35, sharp: false },
    { x: 690, y: 1080,len: 22, ang: -15, curl: 40,  sharp: false },
    { x: 1060,y: 1060,len: 19, ang: 55,  curl: -30, sharp: false }
  ];

  for (let lp of lintParticles) {
    let p0 = { x: lp.x, y: lp.y };
    let a1 = lp.ang;
    let a2 = a1 + lp.curl * 0.5;
    let a3 = a1 + lp.curl;
    let s = lp.len / 3;

    let p1 = { x: p0.x + cos(a1) * s, y: p0.y + sin(a1) * s };
    let p2 = { x: p1.x + cos(a2) * s, y: p1.y + sin(a2) * s };
    let p3 = { x: p2.x + cos(a3) * s, y: p2.y + sin(a3) * s };

    if (lp.sharp) {
      // Tiny drop shadow under the lint fiber
      brush.set("2B", "#0a1424", 0.45);
      brush.spline([
        [p0.x + 1.4, p0.y + 1.8, 0.4],
        [p1.x + 1.6, p1.y + 2.0, 0.7],
        [p2.x + 1.6, p2.y + 2.0, 0.6],
        [p3.x + 1.4, p3.y + 1.8, 0.3]
      ], 0.5);

      // Crisp pale cotton fiber
      brush.set("cotton_slub", "#edf3f8", 0.65);
      brush.spline([
        [p0.x, p0.y, 0.5],
        [p1.x, p1.y, 0.9],
        [p2.x, p2.y, 0.8],
        [p3.x, p3.y, 0.3]
      ], 0.5);

      brush.set("needle", "#ffffff", 0.72);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    } else {
      // Soft out-of-focus lint
      brush.set("cpencil", "#b4c6d8", 0.85);
      brush.spline([
        [p0.x, p0.y, 0.4],
        [p1.x, p1.y, 0.8],
        [p2.x, p2.y, 0.7],
        [p3.x, p3.y, 0.3]
      ], 0.5);
    }
  }

  // Tiny dust specks & cotton pills scattered across the denim weave
  for (let i = 0; i < 65; i++) {
    let dx = random(150, 1140);
    let dy = random(40, 1160);
    if (dist(dx, dy, PX, PY) < PR + 8) continue;
    if (dist(dx, dy, RX, RY) < 30) continue;

    let isFocus = dist(dx, dy, PX, PY) < 380 || dist(dx, dy, BX, BY) < 180;
    if (isFocus) {
      brush.set("2B", "#0b1524", 0.5);
      brush.line(dx + 1, dy + 1.2, dx + 2.5, dy + 2.2);
      brush.set("needle", random(["#ffffff", "#e3ecf5", "#c8d8e8"]), random(0.65, 0.95));
      brush.line(dx, dy, dx + random(-2.2, 2.2), dy + random(-2.2, 2.2));
    } else {
      brush.set("cpencil", "#a8bdd1", 0.7);
      brush.line(dx, dy, dx + 2, dy + 1.5);
    }
  }

  // 3. Shallow Depth-of-Field Atmospheric Softening at the extreme corners
  // Fine spray grain & soft charcoal mist in the far corners to anchor the macro lens feel
  let dofCorners = [
    { x: 90,   y: 90,   r: 220, col: "#122033" },
    { x: 1110, y: 80,   r: 210, col: "#253b54" },
    { x: 1120, y: 1120, r: 240, col: "#111e30" },
    { x: 80,   y: 1110, r: 210, col: "#152438" }
  ];
  for (let c of dofCorners) {
    for (let k = 0; k < 28; k++) {
      let a = random(360);
      let d = random(c.r);
      let sx = c.x + cos(a) * d;
      let sy = c.y + sin(a) * d;
      brush.set("spray", c.col, random(0.8, 1.35));
      brush.line(sx, sy, sx + random(-25, 25), sy + random(-25, 25));
    }
  }
}

