// Pear coordinate frame & lighting constants
const PEAR_CX = 718;
const PEAR_CY = 712;
const PEAR_TILT = -6.5; // degrees
const PEAR_COS = Math.cos((PEAR_TILT * Math.PI) / 180);
const PEAR_SIN = Math.sin((PEAR_TILT * Math.PI) / 180);

// Keyhole center & dimensions in canvas coordinates
const KH_X = 656;
const KH_Y_TOP = 638;
const KH_Y_NECK = 674;
const KH_Y_BOT = 818;
const KH_R_VOID = 50;
const KH_W_NECK = 22;
const KH_W_BOT = 38;
const KH_BEVEL_W = 19;

// Key light from upper-right-front (creates dramatic shadow to the left & illuminates inner left stairwell)
const LIGHT_DIR = (() => {
  let lx = 0.52, ly = -0.55, lz = 0.653;
  let len = Math.hypot(lx, ly, lz);
