  renderCastShadow();

  // 4. Woody stalk with peeling bark & cut growth rings (drawn before top pear rim overlap)
  renderPearStalk();

  // 5. Hyperreal pear body: translucent base washes, 3D cross-contour shading, bruise & lenticels
  renderPearBaseWashes();
