// ============================================================================
// GEOMETRY & 3D SURFACE FUNCTIONS
// ============================================================================

function toPearLocal(x, y) {
  let dx = x - PEAR_CX;
  let dy = y - PEAR_CY;
  return {
    u: dx * PEAR_COS - dy * PEAR_SIN,
    v: dx * PEAR_SIN + dy * PEAR_COS
  };
}

function toCanvasCoords(u, v) {
  return {
    x: PEAR_CX + u * PEAR_COS + v * PEAR_SIN,
    y: PEAR_CY - u * PEAR_SIN + v * PEAR_COS
  };
}

// Returns half-widths { wL, wR } at vertical coordinate v in [-305, 305]
function getPearWidths(v) {
  const V_TOP = -302;
  const V_BOT = 304;
  if (v < V_TOP || v > V_BOT) return { wL: 0, wR: 0, t: -1 };

  let t = (v - V_TOP) / (V_BOT - V_TOP); // 0 at stem crown, 1 at base

  // Smooth organic pear profile: rounded crown, concave neck waist, lush swelling belly, rounded base
  let crownCap = Math.pow(Math.min(1, t / 0.075), 0.52);
  let baseCap = Math.pow(Math.min(1, (1 - t) / 0.14), 0.56);

  // Neck width + belly Gaussian swell
  let neck = 78 + 32 * Math.sin(t * Math.PI * 0.85);
  let pinch = -18 * Math.exp(-Math.pow((t - 0.24) / 0.11, 2));
  let bellyL = 162 * Math.exp(-Math.pow((t - 0.67) / 0.26, 2));
  let bellyR = 148 * Math.exp(-Math.pow((t - 0.64) / 0.25, 2));

  // Subtle asymmetry: left hip swells lower and fuller, right neck curves slightly inward
  let wL = (neck + pinch + bellyL) * crownCap * baseCap;
  let wR = (neck + pinch * 1.15 + bellyR) * crownCap * baseCap;

  return { wL, wR, t };
}

// Signed distance & 3D height Z(x, y) of the pear surface
function evalPearHeight(x, y) {
  let loc = toPearLocal(x, y);
  let u = loc.u;
  let v = loc.v;

  // Slight spine curvature inside local frame
  let spineShift = -9 * Math.sin(((v + 302) / 606) * Math.PI * 1.2);
  let uRel = u - spineShift;

  let { wL, wR, t } = getPearWidths(v);
  if (t < 0 || wL <= 0.1) return { inside: false, z: 0, t: 0, s: 0, u, v };

  let halfW = uRel < 0 ? wL : wR;
  let s = uRel / halfW; // -1 at left edge, +1 at right edge

  // Top stem collar dimple & bottom calyx dimple
  let topDimple = 0;
  if (t < 0.055 && Math.abs(s) < 0.45) {
    topDimple = 0.018 * Math.pow(1 - t / 0.055, 2) * Math.cos((s / 0.45) * (Math.PI / 2));
  }
  let botDimple = 0;
  if (t > 0.94 && Math.abs(s) < 0.42) {
    botDimple = 0.022 * Math.pow((t - 0.94) / 0.06, 2) * Math.cos((s / 0.42) * (Math.PI / 2));
  }

  let effT = t - topDimple + botDimple;
  if (effT <= 0.002 || effT >= 0.998 || Math.abs(s) >= 1.0) {
    return { inside: false, z: 0, t, s, u, v };
  }

  // Base 3D sphere-like revolution height
  let avgW = 0.5 * (wL + wR);
  let radFactor = Math.sqrt(Math.max(0, 1 - s * s));
  let vertCap = Math.pow(Math.sin(effT * Math.PI), 0.35);
  let z = avgW * radFactor * vertCap;

  // Subtle 5-lobed organic fluting near the lower belly & base
  let lobeStrength = Math.pow(Math.max(0, (t - 0.52) / 0.48), 1.6) * (1 - s * s);
  let lobes = 6.5 * lobeStrength * Math.cos(s * Math.PI * 3.2 + 0.4);
  z += lobes;

  // Sunken collar pucker around the stalk insertion at top
  let dStalk = Math.hypot(uRel, v + 286);
  if (dStalk < 46) {
    let q = 1 - dStalk / 46;
    z -= 18 * q * q + 4 * Math.cos(Math.atan2(v + 286, uRel) * 7) * q;
  }

  // Bruised blush depression on the lower-left cheek (around u = -112, v = 135)
  let dBruise = Math.hypot((u - -112) / 92, (v - 135) / 108);
  let bruiseVal = 0;
  if (dBruise < 1.25) {
    let b = Math.max(0, 1 - dBruise / 1.25);
    let nBruise = noise(x * 0.018, y * 0.018);
    bruiseVal = Math.min(1, b * b * (0.75 + 0.5 * nBruise));
    // Flatten & slightly indent the 3D surface where the pear is bruised
    z -= 14.5 * Math.pow(bruiseVal, 1.35);
  }

  // Subtle organic skin bumps
  let microBump = (noise(x * 0.025, y * 0.025) - 0.5) * 3.2 * radFactor;
  z += microBump;

  return { inside: true, z: Math.max(0.1, z), t, s, u, v, halfW, bruiseVal };
}

// Full 3D surface evaluation with finite-difference normal
function getPearSurface(x, y) {
  let c = evalPearHeight(x, y);
  if (!c.inside) return c;

  const eps = 1.5;
  let rx = evalPearHeight(x + eps, y);
  let lx = evalPearHeight(x - eps, y);
  let dyP = evalPearHeight(x, y + eps);
  let dyM = evalPearHeight(x, y - eps);

  let dzdx = ((rx.inside ? rx.z : 0) - (lx.inside ? lx.z : 0)) / (2 * eps);
  let dzdy = ((dyP.inside ? dyP.z : 0) - (dyM.inside ? dyM.z : 0)) / (2 * eps);

  let nx = -dzdx;
  let ny = -dzdy;
  let nz = 1.0;
  let len = Math.hypot(nx, ny, nz);
  c.nx = nx / len;
  c.ny = ny / len;
  c.nz = nz / len;

  // Russeting distribution: heavy near stem collar, calyx base, and organic drifted patches
  let nRus1 = noise(x * 0.012 + 10, y * 0.012 + 20);
  let nRus2 = noise(x * 0.045 + 70, y * 0.045 + 30);
  let crownRus = Math.exp(-Math.pow(c.t / 0.13, 2)) * 0.85;
  let baseRus = Math.exp(-Math.pow((1 - c.t) / 0.11, 2)) * 0.78;
  let patchRus = Math.max(0, (nRus1 * 0.7 + nRus2 * 0.3 - 0.54) * 2.4);
  c.russetVal = constrain(crownRus + baseRus + patchRus, 0, 1);

  return c;
}

// Signed distance to the inner keyhole aperture (negative = inside void, positive = outside void)
function keyholeSignedDist(x, y) {
  // Distance to top circular ward
  let dx = x - KH_X;
  let dyC = y - KH_Y_TOP;
  let dCircle = Math.hypot(dx, dyC) - KH_R_VOID;

  // Distance to lower trapezoidal slot (extending from KH_Y_TOP + 20 down to KH_Y_BOT)
  const ySlotTop = KH_Y_TOP + 22;
  let ty = constrain((y - ySlotTop) / (KH_Y_BOT - ySlotTop), 0, 1);
  let halfW = lerp(KH_W_NECK, KH_W_BOT, ty);

  let dxSlot = Math.abs(dx) - halfW;
  let dySlot = Math.max(ySlotTop - y, y - KH_Y_BOT);
  let dSlotOut = Math.hypot(Math.max(dxSlot, 0), Math.max(dySlot, 0));
  let dSlotIn = Math.min(Math.max(dxSlot, dySlot), 0);
  let dSlot = dSlotOut + dSlotIn;

  // Smooth union at the neck junction so the brass corner has a crisp realistic fillet
  let k = 4.5;
  let h = constrain(0.5 + (0.5 * (dSlot - dCircle)) / k, 0, 1);
  return lerp(dSlot, dCircle, h) - k * h * (1 - h);
}

// ============================================================================
// LAYER 1 & 2: POSTER PAPER, SCRUBBED GOUACHE FIELD & CAST SHADOW
// ============================================================================

function renderPaperStockTexture() {
  // Cool stone-bone paper grain
  brush.noFill();
  brush.noWash();
  for (let i = 0; i < 220; i++) {
    let x1 = random(20, 1180);
    let y1 = random(20, 1180);
    let len = random(40, 220);
    let ang = random(-8, 8) + (random() < 0.5 ? 0 : 90);
    brush.set("2H", random() < 0.5 ? "#bec5ba" : "#dce0d8", random(0.4, 0.9));
    brush.line(
      x1,
      y1,
      x1 + len * cos(ang),
      y1 + len * sin(ang)
    );
  }
}

function renderGouacheGround() {
  // Deliberately imbalanced, hand-painted mustard-ochre poster block
  const leftX = 82;
  const rightX = 1118;
  const topY = 74;
  const botY = 1126;

  // 1. Opaque base wash pass so the mustard-ochre reads as flat, dense poster gouache
  brush.noStroke();
  brush.wash("#b59b3b", 230);
  brush.beginShape(0.05);
  brush.vertex(leftX + 6, topY + 8);
  brush.vertex(rightX - 10, topY + 4);
  brush.vertex(rightX - 4, botY - 12);
  brush.vertex(leftX + 12, botY - 6);
  brush.endShape(true);
  brush.noWash();

  // 2. Layered textured watercolor/gouache blocks for cool olive-mustard depth
  const gouacheLayers = [
    { col: "#a48c31", op: 95, x1: 88, y1: 80, x2: 1110, y2: 1118 },
    { col: "#c4aa46", op: 80, x1: 110, y1: 95, x2: 980, y2: 880 },
    { col: "#8f7c2c", op: 75, x1: 84, y1: 680, x2: 1114, y2: 1122 },
    { col: "#7a6f32", op: 55, x1: 86, y1: 76, x2: 490, y2: 520 }
  ];

  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.65, 0.38);
  for (let g of gouacheLayers) {
    brush.fill(g.col, g.op);
    brush.beginShape(0.12);
    brush.vertex(g.x1 + random(-8, 8), g.y1 + random(-8, 8));
    brush.vertex(g.x2 + random(-8, 8), g.y1 + random(-8, 8));
    brush.vertex(g.x2 + random(-8, 8), g.y2 + random(-8, 8));
    brush.vertex(g.x1 + random(-8, 8), g.y2 + random(-8, 8));
    brush.endShape(true);
  }
  brush.noFill();

  // 3. Hand-scrubbed horizontal & diagonal gouache bristle tracks across the entire field
  const scrubColors = [
    "#b89e3d",
    "#a89034",
    "#c7ae4c",
    "#96822f",
    "#857631",
    "#ceb656",
    "#786c2e"
  ];

  for (let row = 0; row < 155; row++) {
    let yBase = map(row, 0, 154, topY + 4, botY - 4);
    let segments = floor(random(2, 5));
    for (let s = 0; s < segments; s++) {
      let xStart = map(s, 0, segments, leftX, rightX - 180) + random(-28, 28);
      let xEnd = xStart + random(160, 420);
      xStart = constrain(xStart, leftX - 16, rightX - 40);
      xEnd = constrain(xEnd, xStart + 50, rightX + 16);

      let col = random(scrubColors);
      let dy = random(-7, 7);
      brush.set("gouache_scrub", col, random(1.1, 2.4));
      brush.line(xStart, yBase + random(-3, 3), xEnd, yBase + dy);
    }
  }

  // Vertical & cross-scrubbed dry gouache incidents in the vast upper-left negative space
  for (let i = 0; i < 65; i++) {
    let x = random(leftX + 10, rightX - 10);
    let y1 = random(topY + 10, botY - 140);
    let y2 = y1 + random(60, 210);
    let col = random() < 0.45 ? "#9c8833" : random() < 0.75 ? "#c5ac48" : "#6e652d";
    brush.set("gouache_scrub", col, random(0.8, 1.6));
    brush.line(x, y1, x + random(-12, 12), y2);
  }

  // 4. Rough crayon & charcoal edges framing the mustard-ochre field (Polish poster hallmark)
  const edgePalette = ["#272b24", "#464224", "#6e5c1f", "#8a7529", "#363d36", "#d2d6ce"];

  // Top & Bottom ragged crayon edges
  for (let x = leftX - 10; x < rightX + 10; x += 6) {
    // Top border scrub
    let yT = topY + (noise(x * 0.03, 1) - 0.5) * 22;
    let cT = random(edgePalette);
    brush.set("crayon_edge", cT, random(0.6, 1.45));
    brush.line(x + random(-8, 8), yT + random(-8, 8), x + random(18, 52), yT + random(-6, 6));

    // Bottom border scrub
    let yB = botY + (noise(x * 0.03, 9) - 0.5) * 22;
    let cB = random(edgePalette);
    brush.set("crayon_edge", cB, random(0.6, 1.5));
    brush.line(x + random(-8, 8), yB + random(-8, 8), x + random(18, 52), yB + random(-6, 6));
  }

  // Left & Right ragged crayon edges
  for (let y = topY - 8; y < botY + 8; y += 6) {
    // Left border scrub
    let xL = leftX + (noise(2, y * 0.03) - 0.5) * 22;
    let cL = random(edgePalette);
    brush.set("crayon_edge", cL, random(0.6, 1.45));
    brush.line(xL + random(-8, 8), y + random(-8, 8), xL + random(-6, 12), y + random(18, 48));

    // Right border scrub
    let xR = rightX + (noise(8, y * 0.03) - 0.5) * 22;
    let cR = random(edgePalette);
    brush.set("crayon_edge", cR, random(0.6, 1.5));
    brush.line(xR + random(-12, 8), y + random(-8, 8), xR + random(-8, 8), y + random(18, 48));
  }

  // Expressive hand-drawn charcoal registration lines & dry-crayon skips along the edges
  for (let i = 0; i < 42; i++) {
    let side = i % 4;
    brush.set("charcoal", random() < 0.65 ? "#242924" : "#595226", random(0.45, 0.95));
    if (side === 0) {
      let x = random(leftX, rightX - 140);
      brush.line(x, topY + random(-6, 10), x + random(60, 170), topY + random(-6, 10));
    } else if (side === 1) {
      let x = random(leftX, rightX - 140);
      brush.line(x, botY + random(-10, 6), x + random(60, 170), botY + random(-10, 6));
    } else if (side === 2) {
      let y = random(topY, botY - 140);
      brush.line(leftX + random(-6, 10), y, leftX + random(-6, 10), y + random(60, 170));
    } else {
      let y = random(topY, botY - 140);
      brush.line(rightX + random(-10, 6), y, rightX + random(-10, 6), y + random(60, 170));
    }
  }
}

function renderCastShadow() {
  // Long, ominous cast shadow extending to the left from the pear's base
  const shCx = 485;
  const shCy = 964;
  const shRx = 335;
  const shRy = 58;

  // Soft watercolor umber-slate shadow wash
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.3);
  brush.fill("#4a4722", 115);
  brush.beginShape(0.4);
  for (let a = 0; a < 360; a += 15) {
    let rad = a;
    let x = shCx + shRx * cos(rad) + (a > 90 && a < 270 ? -25 : 15);
    let y = shCy + shRy * sin(rad) * (x < 450 ? 0.72 : 1.05);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Deeper core shadow directly beneath the pear belly
  brush.fill("#23271e", 150);
  brush.beginShape(0.4);
  for (let a = 0; a < 360; a += 18) {
    let x = 655 + 175 * cos(a);
    let y = 988 + 34 * sin(a);
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noFill();

  // Horizontal charcoal & graphite shadow hatching blending into the mustard ground
  for (let i = 0; i < 420; i++) {
    let t = random();
    let ang = random(360);
    let r = Math.pow(random(), 0.65);
    let x = shCx + r * shRx * cos(ang);
    let y = shCy + r * shRy * sin(ang) * (x < 480 ? 0.68 : 1.0);

    // Core vs penumbra
    let dCore = Math.hypot((x - 675) / 165, (y - 992) / 32);
    let len = map(constrain(dCore, 0, 2), 0, 2, 24, 65) * random(0.6, 1.3);

    let col =
      dCore < 0.85
        ? "#181c18"
        : dCore < 1.35
        ? "#2c3122"
        : random() < 0.5
        ? "#4a4823"
        : "#635c26";
    let br = dCore < 1.1 ? "charcoal" : "2B";
    brush.set(br, col, random(0.45, 1.05));
    brush.line(x - len * 0.5, y + random(-1.5, 1.5), x + len * 0.5, y + random(-2, 2));
  }
}

// ============================================================================
// LAYER 3: WOODY STALK WITH PEELING BARK
// ============================================================================

function getStalkSpine(t) {
  // t = 0 at pear collar (inside top dimple), t = 1 at cut top tip
  let p0 = toCanvasCoords(-2, -282);
  let p1 = { x: p0.x - 6, y: p0.y - 52 };
  let p2 = { x: p0.x + 18, y: p0.y - 102 };
  let p3 = { x: p0.x + 48, y: p0.y - 144 };

  let mt = 1 - t;
  let x =
    mt * mt * mt * p0.x +
    3 * mt * mt * t * p1.x +
    3 * mt * t * t * p2.x +
    t * t * t * p3.x;
  let y =
    mt * mt * mt * p0.y +
    3 * mt * mt * t * p1.y +
    3 * mt * t * t * p2.y +
    t * t * t * p3.y;

  // Tangent
  let tx =
    3 * mt * mt * (p1.x - p0.x) +
    6 * mt * t * (p2.x - p1.x) +
    3 * t * t * (p3.x - p2.x);
  let ty =
    3 * mt * mt * (p1.y - p0.y) +
    6 * mt * t * (p2.y - p1.y) +
    3 * t * t * (p3.y - p2.y);
  let tLen = Math.hypot(tx, ty);
  tx /= tLen;
  ty /= tLen;

  // Normal pointing right of stalk
  let nx = -ty;
  let ny = tx;

  // Gnarled woody radius profile: flared base, slender waist, knotted top
  let baseFlare = 16 * Math.pow(1 - t, 2.2);
  let topKnot = 5.5 * Math.exp(-Math.pow((t - 0.92) / 0.14, 2));
  let midSwirl = 2.2 * Math.sin(t * Math.PI * 3.5);
  let radius = 10.5 + baseFlare + topKnot + midSwirl;

  return { x, y, tx, ty, nx, ny, radius };
}

function renderPearStalk() {
  // 1. Base solid wash for the woody stalk
  brush.noStroke();
  brush.wash("#332922", 240);
  brush.beginShape(0.1);
  for (let i = 0; i <= 24; i++) {
    let s = getStalkSpine(i / 24);
    brush.vertex(s.x - s.nx * s.radius, s.y - s.ny * s.radius);
  }
  for (let i = 24; i >= 0; i--) {
    let s = getStalkSpine(i / 24);
    brush.vertex(s.x + s.nx * s.radius, s.y + s.ny * s.radius);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Longitudinal fibrous bark ridges & 3D cylindrical lighting
  const numFibers = 85;
  for (let f = 0; f < numFibers; f++) {
    let sPos = map(f, 0, numFibers - 1, -0.98, 0.98) + random(-0.04, 0.04);
    let tStart = random(0.0, 0.75);
    let tEnd = constrain(tStart + random(0.22, 0.48), 0.1, 1.0);

    let pts = [];
    for (let k = 0; k <= 5; k++) {
      let t = lerp(tStart, tEnd, k / 5);
      let sp = getStalkSpine(t);
      let jitter = (noise(f * 0.4, t * 6) - 0.5) * 3.2;
      let px = sp.x + sp.nx * (sPos * sp.radius + jitter);
      let py = sp.y + sp.ny * (sPos * sp.radius + jitter);
      pts.push([px, py, random(0.5, 1.1)]);
    }

    // Lighting across the cylindrical stem (light from right: sPos > 0 is illuminated)
    let col;
    let nVal = noise(f * 0.35, tStart * 4);
    if (sPos < -0.35) {
      col = nVal < 0.5 ? "#1b1614" : "#2c241e";
    } else if (sPos < 0.15) {
      col = nVal < 0.4 ? "#473a30" : nVal < 0.75 ? "#5c4d3e" : "#3a332b";
    } else if (sPos < 0.65) {
      // Exposed warm cinnamon bast wood & cool lichen-grey bark
      col = nVal < 0.35 ? "#8c6540" : nVal < 0.7 ? "#767a6d" : "#614f3d";
    } else {
      col = nVal < 0.5 ? "#a39f8e" : "#b89668";
    }

    brush.set(random() < 0.6 ? "cpencil" : "2B", col, random(0.45, 0.9));
    brush.spline(pts, 0.35);
  }

  // Deep bark fissures & cross-cracks with rotring/fine_needle
  for (let i = 0; i < 45; i++) {
    let t = random(0.05, 0.95);
    let sp = getStalkSpine(t);
    let s1 = random(-0.9, 0.6);
    let x1 = sp.x + sp.nx * s1 * sp.radius;
    let y1 = sp.y + sp.ny * s1 * sp.radius;
    brush.set("fine_needle", "#171311", random(0.5, 0.95));
    if (random() < 0.65) {
      // Longitudinal fissure
      let sp2 = getStalkSpine(constrain(t + random(0.08, 0.18), 0, 1));
      let x2 = sp2.x + sp2.nx * s1 * sp2.radius;
      let y2 = sp2.y + sp2.ny * s1 * sp2.radius;
      brush.line(x1, y1, x2, y2);
    } else {
      // Transverse bark crack
      let s2 = constrain(s1 + random(0.25, 0.55), -0.95, 0.95);
      let x2 = sp.x + sp.nx * s2 * sp.radius;
      let y2 = sp.y + sp.ny * s2 * sp.radius;
      brush.line(x1, y1, x2, y2);
    }
  }

  // 3. Peeling Bark Strips curling off the left and right edges of the stalk!
  const peels = [
    { tBase: 0.24, side: -1, len: 28, curl: -1.15, w: 4.5 },
    { tBase: 0.52, side: -1, len: 34, curl: -1.35, w: 5.2 },
    { tBase: 0.76, side: -1, len: 21, curl: -0.95, w: 3.6 },
    { tBase: 0.36, side: 1, len: 32, curl: 1.25, w: 5.0 },
    { tBase: 0.66, side: 1, len: 26, curl: 1.1, w: 4.2 },
    { tBase: 0.44, side: 0.35, len: 24, curl: 0.85, w: 4.0 }
  ];

  for (let p of peels) {
    let sp = getStalkSpine(p.tBase);
    let bx = sp.x + sp.nx * p.side * (sp.radius * 0.92);
    let by = sp.y + sp.ny * p.side * (sp.radius * 0.92);

    // Shadow cast onto the stem beneath the peeling strip
    brush.set("2B", "#14100e", 0.9);
    brush.line(bx, by, bx - sp.tx * (p.len * 0.55), by - sp.ty * (p.len * 0.55));

    // Exposed warm cinnamon inner wood on the stalk where the bark peeled off
    brush.set("cpencil", "#9e6e42", 0.85);
    brush.line(
      bx - sp.nx * p.side * 2,
      by,
      bx - sp.tx * (p.len * 0.5) - sp.nx * p.side * 2,
      by - sp.ty * (p.len * 0.5)
    );

    // Build curved peeling strip points
    let outerPts = [];
    let innerPts = [];
    let baseAng = atan2(sp.ty, sp.tx) + p.side * 24;
    let cx = bx;
    let cy = by;
    for (let k = 0; k <= 6; k++) {
      let u = k / 6;
      let a = baseAng + p.curl * u * u * 58;
      let wCur = p.w * (1 - u * 0.72);
      let nx = -sin(a);
      let ny = cos(a);
      outerPts.push([cx + nx * wCur * 0.5, cy + ny * wCur * 0.5, 1 - u * 0.5]);
      innerPts.push([cx - nx * wCur * 0.5, cy - ny * wCur * 0.5, 1 - u * 0.5]);
      cx += cos(a) * (p.len / 6);
      cy += sin(a) * (p.len / 6);
    }

    // Warm papery underside vs cool ash-brown outer side of the curled bark
    brush.set("cpencil", p.side > 0 ? "#b88c5a" : "#785739", 0.85);
    brush.spline(innerPts, 0.45);
    brush.set("cpencil", p.side > 0 ? "#857f72" : "#382e26", 0.8);
    brush.spline(outerPts, 0.45);

    // Crisp ragged edge & curled tip fiber
    brush.set("fine_needle", "#1a1512", 0.7);
    brush.spline(outerPts, 0.45);
    let tip = outerPts[outerPts.length - 1];
    brush.line(tip[0], tip[1], tip[0] + p.side * 4, tip[1] - 4);
  }

  // 4. Cut woody top end of the stalk (growth rings & pith)
  let top = getStalkSpine(1.0);
  let cutAng = atan2(top.ny, top.nx);
  push();
  translate(top.x, top.y);
  rotate(cutAng - 12);

  // Pale sapwood face
  brush.noStroke();
  brush.wash("#a88f6b", 235);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 30) {
    brush.vertex(top.radius * 0.95 * cos(a), top.radius * 0.48 * sin(a));
  }
  brush.endShape(true);
  brush.noWash();

  // Concentric growth rings & dark bark rim
  const ringCols = ["#241d18", "#6e553b", "#cab592", "#523d29"];
  for (let r = 0; r < 4; r++) {
    let sc = map(r, 0, 3, 1.0, 0.25);
    brush.set("fine_needle", ringCols[r], r === 0 ? 1.0 : 0.6);
    let ringPts = [];
    for (let a = 0; a <= 360; a += 30) {
      ringPts.push([top.radius * sc * cos(a), top.radius * 0.48 * sc * sin(a)]);
    }
    brush.spline(ringPts, 0.4);
  }
  // Radial pith drying crack
  brush.set("fine_needle", "#1c1511", 0.75);
  brush.line(-top.radius * 0.6, -1, top.radius * 0.5, 1.5);
  pop();
}

// ============================================================================
// LAYER 4: HYPERREAL PEAR SKIN, VOLUMETRIC SHADING, BRUISE & FRECKLES
// ============================================================================

function buildPearOutlinePoints(scaleU = 1.0, scaleV = 1.0, shiftU = 0, shiftV = 0) {
  let pts = [];
  const steps = 44;
  // Left side from top to bottom
  for (let i = 0; i <= steps; i++) {
    let v = lerp(-298, 298, i / steps);
    let { wL } = getPearWidths(v);
    let spineShift = -9 * Math.sin(((v + 302) / 606) * Math.PI * 1.2);
    let u = (spineShift - wL) * scaleU + shiftU;
    let p = toCanvasCoords(u, v * scaleV + shiftV);
    pts.push(p);
  }
  // Right side from bottom to top
  for (let i = steps; i >= 0; i--) {
    let v = lerp(-298, 298, i / steps);
    let { wR } = getPearWidths(v);
    let spineShift = -9 * Math.sin(((v + 302) / 606) * Math.PI * 1.2);
    let u = (spineShift + wR) * scaleU + shiftU;
    let p = toCanvasCoords(u, v * scaleV + shiftV);
    pts.push(p);
  }
  return pts;
}

function renderPearBaseWashes() {
  // 1. Opaque underpainting wash so the mustard gouache never muddies the hyperreal pear
  let fullOutline = buildPearOutlinePoints(0.995, 0.995, 0, 0);
  brush.noStroke();
  brush.wash("#6b8259", 248);
  brush.beginShape(0.25);
  for (let p of fullOutline) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noWash();

  // 2. Layered watercolor washes for cool celadon light, deep slate-forest shadow, and bruised blush
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.3);

  // Cool shadow side wash (left flank & underside)
  let shadowOutline = buildPearOutlinePoints(0.62, 0.94, -68, 12);
  brush.fill("#2f4238", 135);
  brush.beginShape(0.3);
  for (let p of shadowOutline) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // Illuminated side wash (right neck & upper-right belly)
  let lightOutline = buildPearOutlinePoints(0.62, 0.88, 62, -16);
  brush.fill("#b2c48e", 130);
  brush.beginShape(0.3);
  for (let p of lightOutline) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // Bruised blush wash on the lower-left cheek
  let bruiseCenter = toCanvasCoords(-112, 135);
  brush.fill("#4d3142", 145);
  brush.circle(bruiseCenter.x, bruiseCenter.y, 92, 0.35);

  // Russet crown & base washes
  let crownCenter = toCanvasCoords(-4, -245);
  brush.fill("#735334", 115);
  brush.circle(crownCenter.x, crownCenter.y, 58, 0.3);

  brush.noFill();
}

// Compute hyperreal RGB color at any surface point (x, y) on the pear
function evaluatePearColor(surf, x, y) {
  let nx = surf.nx, ny = surf.ny, nz = surf.nz;

  // Direct key light (upper-right-front)
  let ndotl = Math.max(0, nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z);

  // Subsurface wax glow around the terminator
  let sss = Math.exp(-Math.pow((ndotl - 0.28) / 0.22, 2)) * 0.38;

  // Cool sky fill light from upper-left
  let skyFill = Math.max(0, -0.65 * nx - 0.55 * ny + 0.52 * nz) * 0.42;

  // Warm mustard-ochre ground bounce from below
  let bounce = Math.max(0, 0.15 * nx + 0.85 * ny + 0.35 * nz) * Math.pow(surf.t, 1.3) * 0.58;

  // Specular highlights (broad waxy sheen + crisp highlight on upper-right belly & neck)
  // Half-vector between LIGHT_DIR and view (0, 0, 1)
  let hx = LIGHT_DIR.x, hy = LIGHT_DIR.y, hz = LIGHT_DIR.z + 1.0;
  let hLen = Math.hypot(hx, hy, hz);
  let ndoth = Math.max(0, (nx * hx + ny * hy + nz * hz) / hLen);
  let specBroad = Math.pow(ndoth, 14) * 0.36 * (1 - surf.russetVal * 0.65) * (1 - surf.bruiseVal * 0.8);
  let specSharp = Math.pow(ndoth, 52) * 0.48 * (1 - surf.russetVal * 0.75) * (1 - surf.bruiseVal * 0.9);

  // Ambient occlusion at rim and inside stem/calyx dimples
  let rimDark = Math.pow(surf.nz, 0.38);

  // Base cool pear palette (RGB arrays)
  // Deep shadow: cool slate-pine [32, 49, 44]
  // Midtone: cool sage-celadon [106, 132, 92]
  // Lit skin: cool willow-chartreuse [176, 196, 138]
  // SSS glow: olive-gold [152, 162, 86]
  let r = 32, g = 49, b = 44;

  // Blend midtone and lit skin by ndotl
  let litT = Math.pow(ndotl, 0.82);
  let midW = Math.sin( Math.min(1, ndotl * 1.4) * Math.PI );
  r = lerp(r, 108, Math.min(1, ndotl * 1.8));
  g = lerp(g, 134, Math.min(1, ndotl * 1.8));
  b = lerp(b, 94, Math.min(1, ndotl * 1.8));

  r = lerp(r, 182, litT);
  g = lerp(g, 202, litT);
  b = lerp(b, 144, litT);

  // Subsurface scattering
  r += sss * 58;
  g += sss * 62;
  b += sss * 18;

  // Cool sky fill on left flank
  r = lerp(r, 86, skyFill * (1 - ndotl * 0.7));
  g = lerp(g, 112, skyFill * (1 - ndotl * 0.7));
  b = lerp(b, 114, skyFill * (1 - ndotl * 0.7));

  // Mustard-ochre bounce on lower belly
  r = lerp(r, 164, bounce * 0.68);
  g = lerp(g, 144, bounce * 0.68);
  b = lerp(b, 62, bounce * 0.68);

  // Subtle organic mottling
  let m = (noise(x * 0.032, y * 0.032) - 0.5) * 22;
  r += m;
  g += m * 1.1;
  b += m * 0.7;

  // Blend Bruised Blush (cool plum-damson core + oxidized amber-rose halo)
  if (surf.bruiseVal > 0.01) {
    let bv = surf.bruiseVal;
    // Halo around bruise edge (bv in 0.1..0.45) vs deep sunken bruise core (bv > 0.45)
    let halo = Math.sin(Math.min(1, bv * 2.2) * Math.PI) * 0.55;
    r = lerp(r, 128, halo);
    g = lerp(g, 82, halo);
    b = lerp(b, 78, halo);

    // Core bruised plum-violet & slate-umber
    let bruiseLight = 0.45 + 0.55 * ndotl;
    let brR = 68 * bruiseLight + 18;
    let brG = 38 * bruiseLight + 14;
    let brB = 58 * bruiseLight + 22;
    let coreW = Math.pow(bv, 0.85) * 0.86;
    r = lerp(r, brR, coreW);
    g = lerp(g, brG, coreW);
    b = lerp(b, brB, coreW);
  }

  // Blend Russeting (cinnamon-umber & cork-taupe)
  if (surf.russetVal > 0.08) {
    let rv = Math.pow((surf.russetVal - 0.08) / 0.92, 1.15);
    let rusLight = 0.35 + 0.68 * ndotl + 0.25 * bounce;
    let rr = 132 * rusLight + 16;
    let rg = 94 * rusLight + 12;
    let rb = 56 * rusLight + 10;
    r = lerp(r, rr, rv * 0.82);
    g = lerp(g, rg, rv * 0.82);
    b = lerp(b, rb, rv * 0.82);
  }

  // Apply rim darkening
  r *= 0.62 + 0.38 * rimDark;
  g *= 0.64 + 0.36 * rimDark;
  b *= 0.66 + 0.34 * rimDark;

  // Add waxy specular sheen (cool ivory-celadon highlight)
  let spec = specBroad + specSharp;
  r = lerp(r, 242, Math.min(1, spec));
  g = lerp(g, 248, Math.min(1, spec));
  b = lerp(b, 224, Math.min(1, spec));

  return color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
}

function renderPearVolumetricShading() {
  // Pass 1: Dense 3D cross-contour latitude strokes wrapping around the pear's volume
  const numLatRows = 128;
  for (let rIdx = 0; rIdx < numLatRows; rIdx++) {
    let v = map(rIdx, 0, numLatRows - 1, -296, 298);
    let { wL, wR, t } = getPearWidths(v);
    if (wL < 8) continue;

    let spineShift = -9 * Math.sin(((v + 302) / 606) * Math.PI * 1.2);
    let totalW = wL + wR;
    let numSegs = Math.max(5, floor(totalW / 24));

    // Curvature of cross-contour arcs (bends upward near top, downward near bottom)
    let latBow = map(t, 0, 1, -18, 34);

    for (let sIdx = 0; sIdx < numSegs; sIdx++) {
      let s0 = map(sIdx, 0, numSegs, -0.98, 0.98 - 1.9 / numSegs) + random(-0.04, 0.04);
      let s1 = constrain(s0 + (2.35 / numSegs) * random(0.85, 1.25), -0.99, 0.99);
      let sMid = 0.5 * (s0 + s1);

      let uMid = spineShift + (sMid < 0 ? sMid * wL : sMid * wR);
      let vMid = v + latBow * Math.sqrt(Math.max(0, 1 - sMid * sMid)) + random(-2.5, 2.5);
      let cMid = toCanvasCoords(uMid, vMid);

      // Skip inside keyhole aperture + inner brass margin
      if (keyholeSignedDist(cMid.x, cMid.y) < KH_BEVEL_W - 4) continue;

      let surf = getPearSurface(cMid.x, cMid.y);
      if (!surf.inside) continue;

      let col = evaluatePearColor(surf, cMid.x, cMid.y);

      // Build 3-point curved latitude stroke
      let u0 = spineShift + (s0 < 0 ? s0 * wL : s0 * wR);
      let v0 = v + latBow * Math.sqrt(Math.max(0, 1 - s0 * s0));
      let u1 = spineShift + (s1 < 0 ? s1 * wL : s1 * wR);
      let v1 = v + latBow * Math.sqrt(Math.max(0, 1 - s1 * s1));

      let p0 = toCanvasCoords(u0, v0);
      let p1 = toCanvasCoords(u1, v1);

      brush.set("skin_velvet", col, random(0.95, 1.65));
      brush.spline(
        [
          [p0.x, p0.y, 0.4],
          [cMid.x, cMid.y, 1.1],
          [p1.x, p1.y, 0.4]
        ],
        0.4
      );
    }
  }

  // Pass 2: Fine longitudinal meridian strokes with "cpencil" and "2B" for hyperreal skin grain
  const numMeridians = 88;
  for (let mIdx = 0; mIdx < numMeridians; mIdx++) {
    let sBase = map(mIdx, 0, numMeridians - 1, -0.97, 0.97);
    const vSteps = 26;
    for (let k = 0; k < vSteps; k++) {
      let v0 = map(k, 0, vSteps, -294, 294) + random(-4, 4);
      let v1 = constrain(v0 + random(24, 38), -294, 295);
      let vMid = 0.5 * (v0 + v1);

      let sCur = constrain(sBase + random(-0.03, 0.03), -0.98, 0.98);
      let wMid = getPearWidths(vMid);
      let spineMid = -9 * Math.sin(((vMid + 302) / 606) * Math.PI * 1.2);
      let uMid = spineMid + (sCur < 0 ? sCur * wMid.wL : sCur * wMid.wR);
      let cMid = toCanvasCoords(uMid, vMid);

      if (keyholeSignedDist(cMid.x, cMid.y) < KH_BEVEL_W - 2) continue;

      let surf = getPearSurface(cMid.x, cMid.y);
      if (!surf.inside) continue;

      let col = evaluatePearColor(surf, cMid.x, cMid.y);

      let w0 = getPearWidths(v0);
      let spine0 = -9 * Math.sin(((v0 + 302) / 606) * Math.PI * 1.2);
      let p0 = toCanvasCoords(spine0 + (sCur < 0 ? sCur * w0.wL : sCur * w0.wR), v0);

      let w1 = getPearWidths(v1);
      let spine1 = -9 * Math.sin(((v1 + 302) / 606) * Math.PI * 1.2);
      let p1 = toCanvasCoords(spine1 + (sCur < 0 ? sCur * w1.wL : sCur * w1.wR), v1);

      let bName = surf.bruiseVal > 0.25 || surf.russetVal > 0.35 ? "2B" : "cpencil";
      brush.set(bName, col, random(0.55, 1.05));
      brush.spline(
        [
          [p0.x, p0.y, 0.3],
          [cMid.x, cMid.y, 1.0],
          [p1.x, p1.y, 0.3]
        ],
        0.35
      );
    }
  }

  // Pass 3: Focused micro-shading on the Bruised Blush, Stem Collar Dimple & Specular Belly
  // A. Bruised blush micro-hatching & mottled violet-slate veining
  let bruiseC = toCanvasCoords(-112, 135);
  for (let i = 0; i < 320; i++) {
    let ang = random(360);
    let r = Math.pow(random(), 0.72) * 105;
    let x = bruiseC.x + r * cos(ang) * 0.92;
    let y = bruiseC.y + r * sin(ang) * 1.08;
    if (keyholeSignedDist(x, y) < KH_BEVEL_W) continue;

    let surf = getPearSurface(x, y);
    if (!surf.inside || surf.bruiseVal < 0.08) continue;

    let col = evaluatePearColor(surf, x, y);
    let strokeAng = atan2(surf.ny, surf.nx) + 90 + random(-22, 22);
    let len = random(8, 22);
    brush.set(random() < 0.65 ? "cpencil" : "HB", col, random(0.45, 0.85));
    brush.line(
      x - len * 0.5 * cos(strokeAng),
      y - len * 0.5 * sin(strokeAng),
      x + len * 0.5 * cos(strokeAng),
      y + len * 0.5 * sin(strokeAng)
    );
  }

  // B. Stem collar puckers & radial creases at the top of the neck
  let collarC = toCanvasCoords(-2, -280);
  for (let i = 0; i < 95; i++) {
    let ang = random(15, 165); // fanning downward and outward from stalk base
    let r1 = random(8, 18);
    let r2 = r1 + random(14, 34);
    let x1 = collarC.x + r1 * cos(ang);
    let y1 = collarC.y + r1 * sin(ang) * 0.65;
    let x2 = collarC.x + r2 * cos(ang);
    let y2 = collarC.y + r2 * sin(ang) * 0.72;

    let col = random() < 0.55 ? "#332519" : random() < 0.8 ? "#57432a" : "#7d683f";
    brush.set("fine_needle", col, random(0.45, 0.85));
    brush.line(x1, y1, x2, y2);
  }

  // C. Crisp contour definition along the pear's outer silhouette
  let silPts = buildPearOutlinePoints(1.0, 1.0, 0, 0);
  for (let i = 0; i < silPts.length; i++) {
    let pA = silPts[i];
    let pB = silPts[(i + 1) % silPts.length];
    let mx = 0.5 * (pA.x + pB.x);
    let my = 0.5 * (pA.y + pB.y);
    // Left edge is dark cool forest-slate; right edge has crisp celadon-ochre rim contrast
    let isLeft = mx < PEAR_CX;
    let edgeCol = isLeft ? "#1f2b25" : my < 680 ? "#697a49" : "#525c2f";
    brush.set("2B", edgeCol, isLeft ? 0.85 : 0.6);
    brush.line(pA.x, pA.y, pB.x, pB.y);
  }
}

function renderPearRussetAndFreckles() {
  // 1. Webbed russeting patches (fine cross-hatched corky network)
  for (let i = 0; i < 650; i++) {
    let u = random(-240, 230);
    let v = random(-292, 294);
    let pt = toCanvasCoords(u, v);
    if (keyholeSignedDist(pt.x, pt.y) < KH_BEVEL_W) continue;

    let surf = getPearSurface(pt.x, pt.y);
    if (!surf.inside) continue;

    if (random() < surf.russetVal * 0.95) {
      let ndotl = Math.max(0, surf.nx * LIGHT_DIR.x + surf.ny * LIGHT_DIR.y + surf.nz * LIGHT_DIR.z);
      let col =
        ndotl > 0.55
          ? random() < 0.5
            ? "#9c7848"
            : "#826139"
          : random() < 0.5
          ? "#59412a"
          : "#3e2e1f";
      let a = random(360);
      let len = random(4, 11) * surf.nz;
      brush.set("fine_needle", col, random(0.35, 0.7));
      brush.line(pt.x, pt.y, pt.x + len * cos(a), pt.y + len * sin(a));
    }
  }

  // 2. Hyperreal Lenticels (Freckles): ~1,450 tiny foreshortened pores across the entire pear
  for (let i = 0; i < 1450; i++) {
    let u = random(-242, 232);
    let v = random(-292, 294);
    let pt = toCanvasCoords(u, v);
    if (keyholeSignedDist(pt.x, pt.y) < KH_BEVEL_W + 1) continue;

    let surf = getPearSurface(pt.x, pt.y);
    if (!surf.inside || surf.nz < 0.18) continue;

    let ndotl = Math.max(0, surf.nx * LIGHT_DIR.x + surf.ny * LIGHT_DIR.y + surf.nz * LIGHT_DIR.z);

    // Foreshorten freckle width near the silhouette edge
    let sz = random(1.2, 3.2) * (0.45 + 0.55 * surf.nz);
    let tangAng = atan2(surf.ny, surf.nx) + 90;

    // Dark russet-umber rim of the lenticel
    let rimCol =
      surf.bruiseVal > 0.35
        ? "#2b1c26"
        : ndotl > 0.5
        ? "#5c452b"
        : "#33261a";
    brush.set("fine_needle", rimCol, random(0.55, 0.95));
    brush.line(
      pt.x - sz * cos(tangAng),
      pt.y - sz * sin(tangAng),
      pt.x + sz * cos(tangAng),
      pt.y + sz * sin(tangAng)
    );

    // Tiny pale corky core inside the lenticel (catches the light on the illuminated flank)
    if (ndotl > 0.22 && random() < 0.78) {
      let coreCol = ndotl > 0.6 ? "#d8d1b0" : "#a89f7d";
      brush.set("fine_needle", coreCol, random(0.4, 0.7));
      brush.line(
        pt.x - sz * 0.4 * cos(tangAng) + 0.5,
        pt.y - sz * 0.4 * sin(tangAng) - 0.4,
        pt.x + sz * 0.4 * cos(tangAng) + 0.5,
        pt.y + sz * 0.4 * sin(tangAng) - 0.4
      );
    }
  }
}

// ============================================================================
// LAYER 5: CUT PEAR FLESH, SPIRAL STAIRCASE & BRASS KEYHOLE ESCUTCHEON
// ============================================================================

function buildKeyholeContour(offsetDist, numSteps = 90) {
  // Trace boundary where keyholeSignedDist(x, y) == offsetDist using radial marching from center
  let pts = [];
  const cx = KH_X;
  const cyMid = 0.5 * (KH_Y_TOP + KH_Y_BOT);

  // Sample perimeter parameter around the keyhole
  for (let i = 0; i < numSteps; i++) {
    let ang = map(i, 0, numSteps, -90, 270);
    // Anchor center shifts from KH_Y_TOP in upper half to slot spine in lower half
    let anchorY =
      sin(ang) < 0.25
        ? KH_Y_TOP
        : map(sin(ang), 0.25, 1.0, KH_Y_TOP + 28, KH_Y_BOT - 18);

    let dx = cos(ang);
    let dy = sin(ang);
    // Binary search along ray from (cx, anchorY) for keyholeSignedDist == offsetDist
    let rLo = 5;
    let rHi = 195;
    for (let iter = 0; iter < 14; iter++) {
      let rMid = 0.5 * (rLo + rHi);
      let d = keyholeSignedDist(cx + dx * rMid, anchorY + dy * rMid);
      if (d < offsetDist) rLo = rMid;
      else rHi = rMid;
    }
    let rFinal = 0.5 * (rLo + rHi);
    pts.push({ x: cx + dx * rFinal, y: anchorY + dy * rFinal, ang });
  }
  return pts;
}

function renderKeyholeCutAndFlesh() {
  // Around the outer edge of the brass escutcheon (offsetDist from 18 to 24px),
  // the pear skin is sliced open, revealing a thin rim of pale oxidized pear flesh
  // and a deep countersunk crevice shadow.
  for (let y = KH_Y_TOP - 82; y <= KH_Y_BOT + 32; y += 1.5) {
    for (let x = KH_X - 82; x <= KH_X + 82; x += 1.5) {
      let d = keyholeSignedDist(x, y);
      if (d >= KH_BEVEL_W - 1.5 && d <= KH_BEVEL_W + 6.5) {
        let nx = (keyholeSignedDist(x + 1, y) - keyholeSignedDist(x - 1, y)) * 0.5;
        let ny = (keyholeSignedDist(x, y + 1) - keyholeSignedDist(x, y - 1)) * 0.5;
        let tang = atan2(ny, nx) + 90;

        if (d < KH_BEVEL_W + 1.2) {
          // Deep crevice incision shadow right against the brass rim
          brush.set("fine_needle", "#151a14", 0.8);
          brush.line(x, y, x + 2.5 * cos(tang), y + 2.5 * sin(tang));
        } else if (d < KH_BEVEL_W + 4.2) {
          // Exposed moist pear flesh (cool ivory-cream oxidized with warm russet)
          let lightSide = nx * -LIGHT_DIR.x + ny * -LIGHT_DIR.y;
          let fleshCol =
            lightSide > 0.1
              ? random() < 0.7
                ? "#d8dcc6"
                : "#b5986b"
              : random() < 0.6
              ? "#7a5b3a"
              : "#948c6c";
          brush.set("fine_needle", fleshCol, 0.65);
          brush.line(x, y, x + 2.2 * cos(tang), y + 2.2 * sin(tang));
        } else {
          // Sliced dark green/russet skin lip
          brush.set("fine_needle", "#2e3824", 0.6);
          brush.line(x, y, x + 2.0 * cos(tang), y + 2.0 * sin(tang));
        }
      }
    }
  }
}

function renderSpiralStaircaseInterior() {
  // 1. Dark subterranean void wash inside the keyhole aperture
  let voidContour = buildKeyholeContour(0.5, 72);
  brush.noStroke();
  brush.wash("#0d1212", 252);
  brush.beginShape(0.1);
  for (let p of voidContour) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noWash();

  // 2. Build exact 1px-resolution 3D Z-buffer for the spiral staircase inside the keyhole!
  const xMin = Math.floor(KH_X - KH_R_VOID - 2);
  const xMax = Math.ceil(KH_X + KH_R_VOID + 2);
  const yMin = Math.floor(KH_Y_TOP - KH_R_VOID - 2);
  const yMax = Math.ceil(KH_Y_BOT + 2);
  const gw = xMax - xMin + 1;
  const gh = yMax - yMin + 1;

  // Buffers: zBuf (camera depth), typeBuf, stepIdBuf, shadeBuf, normXBuf, normYBuf
  const zBuf = new Float32Array(gw * gh).fill(1e9);
  const typeBuf = new Uint8Array(gw * gh); // 0=abyss, 1=wall, 2=col, 3=tread, 4=riser, 5=rail, 6=baluster
  const stepBuf = new Int16Array(gw * gh).fill(-1);
  const shadeBuf = new Float32Array(gw * gh);
  const mortarBuf = new Uint8Array(gw * gh);

  // Stairwell 3D projection helper:
  // Vertical depth h in [0, 260], horizontal polar (r, deg)
  // Camera looks steeply down (~56 degrees) and slightly left into the shaft
  const TILT_Y = 0.52; // vertical compression of horizontal circles
  function projectStair(r, deg, h) {
    let rad = (deg * Math.PI) / 180;
    let persp = 1.0 / (1.0 + h * 0.0024);
    let rx = r * Math.cos(rad);
    let rz = r * Math.sin(rad); // rz > 0 is front (closer to viewer), rz < 0 is back (further)
    let sx = KH_X + 3 - h * 0.035 + rx * persp;
    let sy = KH_Y_TOP - 40 + h * 0.88 + rz * TILT_Y * persp;
    // Camera depth: smaller camZ is closer to viewer
    let camZ = h * 0.52 - rz * 0.85;
    return { sx, sy, camZ, rx, rz, persp };
  }

  function writePixel(sx, sy, camZ, type, stepId, shade, isMortar = 0) {
    let ix = Math.round(sx) - xMin;
    let iy = Math.round(sy) - yMin;
    if (ix < 0 || ix >= gw || iy < 0 || iy >= gh) return;
    let idx = iy * gw + ix;
    if (camZ < zBuf[idx]) {
      zBuf[idx] = camZ;
      typeBuf[idx] = type;
      stepBuf[idx] = stepId;
      shadeBuf[idx] = constrain(shade, 0, 1);
      mortarBuf[idx] = isMortar;
    }
  }

  const R_WALL = 54;
  const R_COL = 10.5;

  // A. Rasterize curved stone stairwell back wall (deg from 165 to 375)
  for (let h = 0; h <= 275; h += 0.65) {
    let courseRow = Math.floor(h / 13.5);
    let isHorizMortar = Math.abs((h % 13.5) - 0) < 0.75;
    for (let deg = 165; deg <= 375; deg += 0.9) {
      let p = projectStair(R_WALL, deg, h);
      let blockShift = (courseRow % 2) * 18;
      let isVertMortar = Math.abs(((deg + blockShift) % 36) - 0) < 1.3;
      let mortar = isHorizMortar || isVertMortar ? 1 : 0;

      // Wall normal points inward (-cos(deg), -sin(deg)); light comes from upper-right (+x, -y)
      // Therefore left side of inner wall (deg around 180..250) catches the incoming light!
      let rad = (deg * Math.PI) / 180;
      let wallLit = Math.max(0, -Math.cos(rad) * 0.78 + Math.sin(rad) * 0.35 + 0.25);
      let depthAtten = Math.exp(-h * 0.0085);
      // Subterranean eerie glow deep at the bottom (h around 210..260)
      let deepGlow = Math.exp(-Math.pow((h - 225) / 38, 2)) * 0.22;
      let shade = wallLit * depthAtten * 0.72 + deepGlow + 0.05;
      if (mortar) shade *= 0.45;

      writePixel(p.sx, p.sy, p.camZ, 1, courseRow, shade, mortar);
    }
  }

  // B. Rasterize central cylindrical stone newel column (deg from -15 to 195)
  for (let h = 0; h <= 275; h += 0.6) {
    let isRing = Math.abs((h % 28) - 0) < 0.8;
    for (let deg = -15; deg <= 195; deg += 3.0) {
      let p = projectStair(R_COL, deg, h);
      let rad = (deg * Math.PI) / 180;
      // Column normal points outward (+cos(deg), +sin(deg)); right side (deg around 0..65) catches light
      let colLit = Math.max(0, Math.cos(rad) * 0.75 + Math.sin(rad) * 0.45 + 0.15);
      let depthAtten = Math.exp(-h * 0.0078);
      let deepGlow = Math.exp(-Math.pow((h - 220) / 40, 2)) * 0.24;
      let shade = colLit * depthAtten * 0.85 + deepGlow + 0.06;
      if (isRing) shade *= 0.55;
      writePixel(p.sx, p.sy, p.camZ, 2, Math.floor(h / 28), shade, isRing ? 1 : 0);
    }
  }

  // C. Rasterize 17 Helical Stone Steps spiraling clockwise downward!
  const NUM_STEPS = 17;
  const STEP_DH = 14.2;
  const STEP_DA = 25.5;
  const START_DEG = 152; // Starts on the upper-left, spirals across front, right, back, and left again!

  for (let i = 0; i < NUM_STEPS; i++) {
    let hTop = 12 + i * STEP_DH;
    let hBot = hTop + STEP_DH + 2;
    let a0 = START_DEG - i * STEP_DA; // Leading edge (lower)
    let a1 = a0 + STEP_DA + 2.5;      // Trailing edge (tucks under step i-1)

    let depthAtten = Math.exp(-hTop * 0.0068);
    let deepGlow = Math.exp(-Math.pow((hTop - 215) / 42, 2)) * 0.28;

    // 1. Top Horizontal Tread of step i
    for (let r = R_COL; r <= R_WALL; r += 0.65) {
      for (let a = a0; a <= a1; a += 0.9) {
        let p = projectStair(r, a, hTop);
        // Cast shadow from step (i-1) onto the back portion of tread i (near a1)
        let fracA = (a - a0) / (a1 - a0);
        let stepAO = fracA > 0.72 ? map(fracA, 0.72, 1.0, 1.0, 0.35) : 1.0;
        // Shadow from keyhole right rim onto right side of stairwell
        let rimShadow = p.sx > KH_X + 18 ? map(p.sx, KH_X + 18, KH_X + 50, 1.0, 0.32) : 1.0;
        // Bright nosing highlight right along the leading edge (fracA < 0.08)
        let nosingBoost = fracA < 0.08 ? 0.24 * depthAtten : 0;

        let radialGrad = map(r, R_COL, R_WALL, 0.92, 0.75);
        let shade = (0.82 * radialGrad * stepAO * rimShadow * depthAtten) + nosingBoost + deepGlow + 0.07;

        let isNosing = fracA < 0.06 ? 1 : 0;
        writePixel(p.sx, p.sy, p.camZ, 3, i, shade, isNosing);
      }
    }

    // 2. Vertical Risers at a0 and a1 (whichever faces the camera has smaller camZ)
    for (let side of [0, 1]) {
      let aEdge = side === 0 ? a0 : a1;
      let rad = (aEdge * Math.PI) / 180;
      // Tangent normal of riser at aEdge
      let nx = side === 0 ? -Math.sin(rad) : Math.sin(rad);
      let rzNorm = side === 0 ? Math.cos(rad) : -Math.cos(rad);
      let riserLit = Math.max(0.08, nx * 0.55 + rzNorm * 0.35 + 0.22);

      for (let h = hTop + 0.4; h <= hBot; h += 0.65) {
        let underStepAO = map(h, hTop, hBot, 0.55, 1.0);
        for (let r = R_COL; r <= R_WALL; r += 0.7) {
          let p = projectStair(r, aEdge, h);
          let shade = riserLit * underStepAO * depthAtten * 0.54 + deepGlow * 0.6 + 0.04;
          writePixel(p.sx, p.sy, p.camZ, 4, i, shade, 0);
        }
      }
    }

    // 3. Slender wrought-iron vertical baluster & helical handrail along the outer curve (r = R_WALL - 5)
    let rRail = R_WALL - 5.5;
    let aBal = a0 + 4.5;
    let hRail = hTop - 21;
    if (hRail > 0) {
      for (let h = hRail; h <= hTop; h += 0.7) {
        let p = projectStair(rRail, aBal, h);
        writePixel(p.sx, p.sy, p.camZ - 0.6, 6, i, 0.14 * depthAtten + 0.04, 0);
      }
      // Helical handrail segment from step i to step i+1
      let hRailNext = hTop + STEP_DH - 21;
      for (let u = 0; u <= 1; u += 0.05) {
        let aCur = lerp(aBal, aBal - STEP_DA, u);
        let hCur = lerp(hRail, hRailNext, u);
        let p = projectStair(rRail, aCur, hCur);
        writePixel(p.sx, p.sy, p.camZ - 0.8, 5, i, 0.85 * depthAtten + 0.12, 0);
        writePixel(p.sx, p.sy + 1.2, p.camZ - 0.7, 5, i, 0.12, 0);
      }
    }
  }

  // 3. Render the Z-buffer into hyperreal p5.brush graphite/ink strokes clipped to the keyhole void!
  // Map shade [0, 1] and surface type to cool limestone/slate architectural palette
  function stairColorFromShade(sh, type) {
    if (type === 5) {
      // Wrought-iron handrail with cool metallic glint
      return sh > 0.45 ? "#d2dcd8" : "#1c2424";
    }
    if (type === 6) {
      return "#182020";
    }
    // Cool limestone & subterranean slate tones
    let r = lerp(12, 212, Math.pow(sh, 0.88));
    let g = lerp(17, 222, Math.pow(sh, 0.86));
    let b = lerp(18, 214, Math.pow(sh, 0.84));
    // Warm ochre-cyan subterranean tint in mid-low values
    if (sh > 0.15 && sh < 0.45) {
      r += 8;
      g += 12;
      b += 6;
    }
    return color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
  }

  // Pass A: Dense horizontal & surface-aligned tonal shading strokes across every pixel of the keyhole void
  for (let iy = 1; iy < gh - 1; iy += 1) {
    let sy = yMin + iy;
    let runStart = -1;
    let runType = 0;
    let runStep = -1;
    let shadeSum = 0;
    let runCount = 0;

    for (let ix = 1; ix < gw - 1; ix++) {
      let sx = xMin + ix;
      let insideVoid = keyholeSignedDist(sx, sy) < -0.5;
      let idx = iy * gw + ix;
      let t = insideVoid ? typeBuf[idx] : 0;
      let st = insideVoid ? stepBuf[idx] : -1;
      let sh = insideVoid ? shadeBuf[idx] : 0;

      let canContinue =
        insideVoid &&
        runStart >= 0 &&
        t === runType &&
        st === runStep &&
        ix - runStart < 11 &&
        Math.abs(sh - shadeSum / runCount) < 0.14;

      if (canContinue) {
        shadeSum += sh;
        runCount++;
      } else {
        if (runStart >= 0 && runCount >= 2 && runType > 0) {
          let avgSh = shadeSum / runCount;
          let col = stairColorFromShade(avgSh, runType);
          let x1 = xMin + runStart;
          let x2 = xMin + ix - 1;
          brush.set("fine_needle", col, random(0.65, 1.05));
          brush.line(x1, sy, x2 + 0.6, sy + (runType === 4 ? 0.5 : 0));
        }
        if (insideVoid && t > 0) {
          runStart = ix;
          runType = t;
          runStep = st;
          shadeSum = sh;
          runCount = 1;
        } else {
          runStart = -1;
          runCount = 0;
        }
      }
    }
    if (runStart >= 0 && runCount >= 2 && runType > 0) {
      let avgSh = shadeSum / runCount;
      let col = stairColorFromShade(avgSh, runType);
      brush.set("fine_needle", col, 0.85);
      brush.line(xMin + runStart, sy, xMin + gw - 2, sy);
    }
  }

  // Pass B: Crisp architectural drafting lines along step nosings, risers, column edges & mortar joints
  for (let iy = 2; iy < gh - 2; iy += 1) {
    for (let ix = 2; ix < gw - 2; ix += 1) {
      let sx = xMin + ix;
      let sy = yMin + iy;
      if (keyholeSignedDist(sx, sy) >= -1.0) continue;

      let idx = iy * gw + ix;
      let t = typeBuf[idx];
      let st = stepBuf[idx];
      let sh = shadeBuf[idx];
      let mort = mortarBuf[idx];
      if (t === 0) continue;

      // Detect structural edge with right or bottom neighbor
      let tR = typeBuf[idx + 1];
      let stR = stepBuf[idx + 1];
      let tB = typeBuf[idx + gw];
      let stB = stepBuf[idx + gw];

      let isEdge = t !== tR || t !== tB || st !== stR || st !== stB;

      if (isEdge) {
        // Dark crisp architectural line at step/riser/wall boundaries
        brush.set("fine_needle", "#0b1010", 0.72);
        let dx = t !== tB || st !== stB ? 1.8 : 0.3;
        let dy = t !== tR || st !== stR ? 1.8 : 0.3;
        brush.line(sx, sy, sx + dx, sy + dy);
      } else if (mort === 1 && t === 3) {
        // Crisp luminous limestone nosing highlight on the front edge of each step tread!
        if (sh > 0.32 && ix % 2 === 0) {
          let hiCol = sh > 0.65 ? "#e6ede8" : "#a8b5af";
          brush.set("fine_needle", hiCol, 0.68);
          brush.line(sx, sy, sx + 2.2, sy + 0.4);
        }
      } else if (mort === 1 && (t === 1 || t === 2) && (ix + iy) % 2 === 0) {
        // Stone course mortar line
        brush.set("fine_needle", "#141c1c", 0.55);
        brush.line(sx, sy, sx + 1.5, sy + 0.4);
      }
    }
  }

  // Pass C: Deep shadow vignette cast by the top & right brass keyhole lip into the stairwell
  for (let i = 0; i < 160; i++) {
    let ang = random(-75, 85);
    let r = random(KH_R_VOID - 14, KH_R_VOID - 1);
    let sx = KH_X + r * cos(ang);
    let sy = KH_Y_TOP + r * sin(ang);
    if (keyholeSignedDist(sx, sy) < -1.0) {
      brush.set("2B", "#0a0e0e", random(0.45, 0.85));
      brush.line(sx - 6, sy + 2, sx + 2, sy - 2);
    }
  }
}

function renderBrassKeyholeEscutcheon() {
  // Render the 3D countersunk antique brass keyhole rim & inner brass wall:
  // 1. Inner 3D brass wall (voidDist in [-4.5, 0.5]) visible on the left/bottom sill due to perspective
  // 2. Inner bevel chamfer (voidDist in [0, 4.5])
  // 3. Flat brushed-brass escutcheon plate (voidDist in [4.5, 14.0])
  // 4. Outer countersunk bevel (voidDist in [14.0, 19.0])

  const yStart = KH_Y_TOP - KH_R_VOID - KH_BEVEL_W - 4;
  const yEnd = KH_Y_BOT + KH_BEVEL_W + 4;
  const xStart = KH_X - KH_R_VOID - KH_BEVEL_W - 4;
  const xEnd = KH_X + KH_R_VOID + KH_BEVEL_W + 4;

  // Step 1: Dense metallic radial & tangential micro-strokes across the brass escutcheon
  for (let y = yStart; y <= yEnd; y += 1.4) {
    for (let x = xStart; x <= xEnd; x += 1.4) {
      let d = keyholeSignedDist(x, y);

      // Outward 2D gradient of keyhole contour
      let gx = (keyholeSignedDist(x + 1, y) - keyholeSignedDist(x - 1, y)) * 0.5;
      let gy = (keyholeSignedDist(x, y + 1) - keyholeSignedDist(x, y - 1)) * 0.5;
      let gLen = Math.hypot(gx, gy) || 1;
      gx /= gLen;
      gy /= gLen;

      // Inner 3D brass wall thickness (visible along the left wall and bottom sill)
      let wallThickness = Math.max(0, -gx * 4.2 + gy * 3.2 + 1.8);
      if (d >= -wallThickness && d < 0.2) {
        // Inner wall normal points inward (-gx, -gy, 0.25)
        let wLit = Math.max(0, -gx * LIGHT_DIR.x - gy * LIGHT_DIR.y + 0.22);
        let wSpec = Math.pow(wLit, 6) * 0.7;
        let col =
          wSpec > 0.35
            ? "#f2e6aa"
            : wLit > 0.45
            ? "#bda14c"
            : wLit > 0.22
            ? "#6e5c28"
            : "#241e10";
        let tang = atan2(gy, gx) + 90;
        brush.set("fine_needle", col, 0.75);
        brush.line(x, y, x + 2.4 * cos(tang), y + 2.4 * sin(tang));
        continue;
      }

      if (d < 0.2 || d > KH_BEVEL_W) continue;

      // Compute 3D surface normal of the beveled brass plate
      let bnx = 0, bny = 0, bnz = 1.0;
      if (d < 4.5) {
        // Inner bevel sloping into the keyhole aperture
        let tilt = map(d, 0.2, 4.5, 0.82, 0.25);
        bnx = -gx * tilt;
        bny = -gy * tilt;
        bnz = Math.sqrt(Math.max(0.1, 1 - tilt * tilt));
      } else if (d < 14.2) {
        // Flat brushed brass plate face (follows underlying pear surface slightly)
        let ps = getPearSurface(x, y);
        bnx = ps.inside ? ps.nx * 0.65 : -0.15;
        bny = ps.inside ? ps.ny * 0.65 : 0.05;
        bnz = 0.88;
      } else {
        // Outer bevel sloping outward to meet the incised pear skin
        let tilt = map(d, 14.2, KH_BEVEL_W, 0.25, 0.85);
        bnx = gx * tilt;
        bny = gy * tilt;
        bnz = Math.sqrt(Math.max(0.1, 1 - tilt * tilt));
      }

      let nLen = Math.hypot(bnx, bny, bnz);
      bnx /= nLen;
      bny /= nLen;
      bnz /= nLen;

      // Anisotropic metallic reflection model for antique tarnished brass
      let ndotl = Math.max(0, bnx * LIGHT_DIR.x + bny * LIGHT_DIR.y + bnz * LIGHT_DIR.z);
      // Tangential brushed-metal banding
      let angleAround = atan2(y - (KH_Y_TOP + 60), x - KH_X);
      let anisoBand =
        0.5 +
        0.5 * Math.sin(angleAround * 3.0 + 1.15) * 0.65 +
        0.35 * Math.cos(angleAround * 5.0 - 0.6);

      let metalVal = ndotl * 0.62 + anisoBand * 0.38;
      let spec = Math.pow(Math.max(0, ndotl * 0.75 + anisoBand * 0.3), 7);

      // Cool verdigris patina in the recessed bevel corners
      let verdigris =
        (d > 3.5 && d < 6.0) || (d > 13.0 && d < 15.5)
          ? Math.max(0, noise(x * 0.08, y * 0.08) - 0.55) * 1.8
          : 0;

      let r, g, b;
      if (spec > 0.58) {
        // Razor-sharp pale champagne-gold specular glint
        r = lerp(218, 252, (spec - 0.58) / 0.42);
        g = lerp(198, 246, (spec - 0.58) / 0.42);
        b = lerp(118, 212, (spec - 0.58) / 0.42);
      } else if (metalVal > 0.58) {
        // Bright antique brass
        let t = (metalVal - 0.58) / 0.42;
        r = lerp(148, 214, t);
        g = lerp(126, 192, t);
        b = lerp(58, 108, t);
      } else if (metalVal > 0.32) {
        // Midtone olive-bronze
        let t = (metalVal - 0.32) / 0.26;
        r = lerp(74, 148, t);
        g = lerp(64, 126, t);
        b = lerp(32, 58, t);
      } else {
        // Deep dark umber-bronze reflection
        let t = metalVal / 0.32;
        r = lerp(26, 74, t);
        g = lerp(23, 64, t);
        b = lerp(14, 32, t);
      }

      if (verdigris > 0.05) {
        r = lerp(r, 68, verdigris);
        g = lerp(g, 112, verdigris);
        b = lerp(b, 98, verdigris);
      }

      let tang = atan2(gy, gx) + 90;
      brush.set("fine_needle", color(r, g, b), random(0.65, 1.0));
      brush.line(x, y, x + 2.6 * cos(tang), y + 2.6 * sin(tang));
    }
  }

  // Step 2: Crisp contour rings at the inner rim (d=0), bevel ridges (d=4.5, d=14.2), and outer edge (d=19)
  const ridges = [
    { d: 0.2, hi: "#f7efc2", lo: "#1a160c", w: 0.8 },
    { d: 4.5, hi: "#f5ecc0", lo: "#2b2412", w: 0.75 },
    { d: 14.2, hi: "#e8d68b", lo: "#262010", w: 0.7 },
    { d: KH_BEVEL_W - 0.2, hi: "#9c8844", lo: "#17140b", w: 0.85 }
  ];

  for (let rg of ridges) {
    let pts = buildKeyholeContour(rg.d, 110);
    for (let i = 0; i < pts.length; i++) {
      let p0 = pts[i];
      let p1 = pts[(i + 1) % pts.length];
      let dx = p1.x - p0.x;
      let dy = p1.y - p0.y;
      // Normal to ridge segment
      let nx = dy, ny = -dx;
      let nLen = Math.hypot(nx, ny) || 1;
      nx /= nLen;
      ny /= nLen;
      let lit = nx * LIGHT_DIR.x + ny * LIGHT_DIR.y;
      let col = lit > 0.15 ? rg.hi : rg.lo;
      brush.set("fine_needle", col, rg.w);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Step 3: Three tiny countersunk slotted brass screws on the flat escutcheon face!
  const screws = [
    { x: KH_X, y: KH_Y_TOP - KH_R_VOID - 9.4, slotAng: 32 },
    { x: KH_X - KH_W_BOT - 9.4, y: KH_Y_BOT - 12, slotAng: -48 },
    { x: KH_X + KH_W_BOT + 9.4, y: KH_Y_BOT - 12, slotAng: 64 }
  ];

  for (let sc of screws) {
    let sr = 4.2;
    // Countersunk dark recess ring
    brush.set("fine_needle", "#1f1a0d", 0.75);
    brush.circle(sc.x, sc.y, sr, 0.15);

    // Metallic screw head fill
    for (let ry = -sr + 0.8; ry <= sr - 0.8; ry += 0.9) {
      let hw = Math.sqrt(Math.max(0, sr * sr - ry * ry)) * 0.85;
      let cCol = ry < 0 ? "#dec978" : "#6b5926";
      brush.set("fine_needle", cCol, 0.7);
      brush.line(sc.x - hw, sc.y + ry, sc.x + hw, sc.y + ry);
    }

    // Slotted screwdriver groove + bright bottom-left highlight edge
    let dx = (sr - 0.6) * cos(sc.slotAng);
    let dy = (sr - 0.6) * sin(sc.slotAng);
    brush.set("fine_needle", "#141108", 0.95);
    brush.line(sc.x - dx, sc.y - dy, sc.x + dx, sc.y + dy);
    brush.set("fine_needle", "#f7f0c6", 0.6);
    brush.line(sc.x - dx + 0.6, sc.y - dy + 0.8, sc.x + dx + 0.6, sc.y + dy + 0.8);
  }
}

function renderMoistureDroplets() {
  // Subtle hyperreal beads of pear juice/moisture clinging below the cut keyhole
  const drops = [
    { x: KH_X - 24, y: KH_Y_BOT + 29, rx: 4.2, ry: 5.8 },
    { x: KH_X + 19, y: KH_Y_BOT + 34, rx: 3.0, ry: 4.0 },
    { x: KH_X - 21, y: KH_Y_BOT + 46, rx: 2.1, ry: 2.6 }
  ];

  for (let d of drops) {
    // Faint wet trail above the droplet
    brush.set("fine_needle", "#576944", 0.6);
    brush.line(d.x + 0.5, d.y - d.ry - 8, d.x, d.y - d.ry);

    // Cast shadow beneath droplet (to the lower-left since light is from upper-right)
    for (let a = 110; a <= 230; a += 20) {
      let sx = d.x + (d.rx + 1.4) * cos(a);
      let sy = d.y + (d.ry + 1.8) * sin(a);
      brush.set("fine_needle", "#1e291d", 0.75);
      brush.line(sx, sy, sx - 1.5, sy + 1.5);
    }

    // Refracted interior of droplet (dark upper-right, luminous chartreuse lower-left caustic)
    for (let py = -d.ry; py <= d.ry; py += 0.9) {
      let hw = d.rx * Math.sqrt(Math.max(0, 1 - (py * py) / (d.ry * d.ry)));
      for (let px = -hw; px <= hw; px += 0.9) {
        let u = px / d.rx;
        let v = py / d.ry;
        let col =
          u > 0.1 && v < -0.1
            ? "#2d3d29"
            : u < -0.1 && v > 0.1
            ? "#d4e3a8"
            : "#7f9660";
        brush.set("fine_needle", col, 0.65);
        brush.line(d.x + px, d.y + py, d.x + px + 0.8, d.y + py);
      }
    }

    // Pinpoint white-cream specular reflection on upper-right of the droplet
    brush.set("fine_needle", "#f7faeb", 0.95);
    brush.line(d.x + d.rx * 0.32, d.y - d.ry * 0.38, d.x + d.rx * 0.48, d.y - d.ry * 0.22);
  }
}

function renderPosterFinish() {
  // Subtle dry-media stipple & raw poster texture across the negative space
  brush.set("spray", "#424736", 0.45);
  for (let i = 0; i < 18; i++) {
    let x = random(90, 1110);
    let y = random(85, 1115);
    if (evalPearHeight(x, y).inside) continue;
    brush.line(x, y, x + random(-35, 35), y + random(-35, 35));
  }

  // A few raw graphite/crayon scratches in the lower-left and upper-left corners of the mustard ground
  const scratches = [
    [135, 1065, 245, 1062],
    [122, 1074, 198, 1073],
    [118, 142, 116, 235],
    [1055, 1085, 1098, 1082]
  ];
  for (let s of scratches) {
    brush.set("2H", "#454225", 0.65);
    brush.line(s[0], s[1], s[2], s[3]);
  }
}

// Hyperreal Butterfly Swimmer — Broken Broadcast Still
// p5.js 2.x + p5.brush (WEBGL)

