  turquoise: "#0099b8",
  chlorineCyan: "#00cde8",
  electricAqua: "#48e5ff",
  foamIce: "#baf6ff",
  pureWhite: "#f4fdff",

  // Wet hyperreal skin tones (cool-lit arena + turquoise bounce)
  skinDeepShadow: "#28151c",
  skinCoolShadow: "#43252c",
  skinplumMid: "#63383c",
  skinBronze: "#87504b",
  skinWarmMid: "#aa6d60",
  skinLit: "#c98e7c",
  skinHigh: "#e3b3a1",
  skinSpecular: "#d9f7ff",
  skinCyanBounce: "#3c8ea1",

  // Lane rope & racing gear
  capDark: "#091321",
  capMid: "#162b45",
  capSlate: "#2d4c6e",
