  laneBlueMid: "#124e96",
  laneBlueHigh: "#4ea3eb",
  laneRedDark: "#5e1119",
  laneRedMid: "#b82532",
  laneRedHigh: "#ff5c66",

  // Corrupted chroma noise (hot magenta & acid lime)
  magentaDeep: "#b80058",
