  // Broadcast frame
  letterbox: "#04080c"
};

const FRAME_TOP = 135;
const FRAME_BOT = 1065;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(7391);
  noiseSeed(7391);

  setupCustomBrushes();
  setupCorruptedField();
}

function setupCustomBrushes() {
  // Broad slick marker for smooth anatomical & water gradients
  brush.add("slickMarkerLg", {
    type: "marker",
    weight: 11,
    scatter: 0.04,
    opacity: 34,
    spacing: 0.22,
    pressure: [0.85, 1.0, 0.85],
    rotate: "natural",
    markerTip: false,
    noise: 0.12
  });

  // Medium blending marker for muscle striations and water facets
  brush.add("slickMarkerMd", {
    type: "marker",
    weight: 5.5,
    scatter: 0.03,
    opacity: 45,
    spacing: 0.2,
    pressure: [0.7, 1.1, 0.7],
    rotate: "natural",
    markerTip: false,
    noise: 0.1
  });

  // Crisp detail marker for goggle strap, droplets, and specular sheen
  brush.add("slickMarkerSm", {
    type: "marker",
    weight: 2.0,
    scatter: 0.02,
    opacity: 85,
    spacing: 0.16,
    pressure: [0.6, 1.2, 0.6],
    rotate: "natural",
    markerTip: false,
    noise: 0.05
  });

  // Flat digital slab tip for razor-sharp smeared pixels
  brush.add("pixelSlab", {
    type: "custom",
    weight: 6,
    scatter: 0.0,
    opacity: 190,
    spacing: 0.12,
    pressure: [1.0, 1.0, 1.0],
    tip: (_m) => {
      _m.rect(-2, -1, 4, 2);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.0
  });

  // High-velocity chroma streak brush for motion vector corruption
  brush.add("chromaVector", {
    type: "default",
    weight: 1.35,
    scatter: 0.08,
    sharpness: 0.92,
    grain: 0.28,
    opacity: 175,
    spacing: 0.15,
    pressure: [1.2, 0.9, 0.15],
    rotate: "natural",
    noise: 0.2
  });

  // Fine atomized spray for water mist and high-ISO broadcast grain
  brush.add("waterMist", {
    type: "spray",
    weight: 9,
    scatter: 1.8,
    opacity: 38,
    spacing: 0.6,
    pressure: [0.6, 1.0, 0.6]
  });
}

function setupCorruptedField() {
  // Motion vector field combining diagonal frame drag (-31 deg) with horizontal step-shears
  brush.addField("corruptedMotion", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        // Quantized macroblock step
        let qRow = floor(row / 2) * 2;
        let nVal = noise(nx * 3.5, qRow * 0.25, t * 0.1);
        if (ny > 0.24 && ny < 0.36 && nx > 0.38) {
          // Horizontal lane-rope pixel-bleed shear
          field[col][row] = -4 + (nVal - 0.5) * 16;
        } else if (nVal > 0.62) {
          // Diagonal macroblock drag vector
          field[col][row] = -31 + (nVal - 0.62) * 25;
        } else {
          // Hydrodynamic wake + diagonal drift
          field[col][row] = -24 + sin(nx * 360 + ny * 180) * 18;
        }
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.abyssTeal);

  // Clip main photographic pass to the widescreen broadcast frame
  brush.clip([0, FRAME_TOP, 1200, FRAME_BOT]);

  // 1. Soft photographic water passages & subsurface caustics
  drawPoolEnvironment();

  // 2. Background Olympic lane rope in perspective
  drawLaneRope();

  // 3. Hyperreal butterfly swimmer in slick marker gradients
  drawSwimmerTorsoAndShoulders();
  drawSwimmerHeadAndGoggles();
  drawSwimmerArms();

  // 4. Turbulent bow wave, glassy sheets & hyperreal water droplets
  drawWaterSheetsAndFoam();
  drawHyperrealDroplets();

  brush.noClip();

  // 5. THE GLITCH: Razor-sharp diagonal macroblocks, smeared cyan face slab,
  //    sideways skin-tone pixel bleed into the lane rope, and chroma flow streaks
  drawDiagonalGlitchBlocks();
  drawSkinPixelBleedIntoLaneRope();
  drawChromaMotionVectors();

  // 6. Cinematic letterbox bars & broken broadcast border artifacts
  drawBroadcastFrame();

  noLoop();
}

// ============================================================================
// 1. POOL ENVIRONMENT & SUBSURFACE CAUSTICS
// ============================================================================
function drawPoolEnvironment() {
  brush.noStroke();

  // Color-batched underwater washes for soft photographic depth
  brush.wash(PALETTE.deepPool, 220);
  brush.rect(0, FRAME_TOP, 1200, 310, "corner");

  brush.wash(PALETTE.troughTeal, 190);
  brush.rect(0, 390, 1200, 320, "corner");

  brush.wash(PALETTE.poolMid, 175);
  brush.rect(0, 560, 1200, 505, "corner");

  // Watercolor bleed passages for luminous turquoise subsurface scatter
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.2);

  brush.fill(PALETTE.turquoise, 95);
  brush.rect(120, 440, 960, 420, "corner");
  brush.rect(60, 620, 1080, 360, "corner");

  brush.fill(PALETTE.chlorineCyan, 75);
  brush.rect(200, 470, 780, 290, "corner");

