}

// ============================================================================
// 2. OLYMPIC LANE ROPE (BACKGROUND TROUGH)
// ============================================================================
function drawLaneRope() {
  // Lane rope runs from left (0, 392) to right (1200, 336)
  let x0 = -20, y0 = 392;
  let x1 = 1220, y1 = 336;

  // Dark underwater trough shadow beneath lane rope
  brush.set("slickMarkerLg", PALETTE.abyssTeal, 1.8);
  brush.line(x0, y0 + 24, x1, y1 + 24);
  brush.line(x0, y0 + 14, x1, y1 + 14);

  // Steel tension cable core
  brush.set("slickMarkerSm", PALETTE.strapBlack, 1.5);
  brush.line(x0, y0, x1, y1);

  // Individual cylindrical wave-quelling floats
  let numFloats = 44;
  for (let i = 0; i < numFloats; i++) {
    let t = i / numFloats;
    let fx = lerp(x0, x1, t);
    let fy = lerp(y0, y1, t) + sin(i * 38) * 3.5;
    let fw = 24;
    let fh = 38;

    // Color pattern: red 5m marker zone near center-right, alternating cobalt & white elsewhere
    let cDark, cMid, cHigh;
    if (i >= 18 && i <= 26) {
      cDark = PALETTE.laneRedDark;
      cMid = PALETTE.laneRedMid;
      cHigh = PALETTE.laneRedHigh;
    } else if (i % 6 < 4) {
      cDark = PALETTE.laneBlueDark;
      cMid = PALETTE.laneBlueMid;
      cHigh = PALETTE.laneBlueHigh;
    } else {
      cDark = PALETTE.poolMid;
      cMid = PALETTE.foamIce;
      cHigh = PALETTE.pureWhite;
    }

    // Vertical marker gradient slices across each disc float
    for (let s = -fh / 2; s <= fh / 2; s += 4.5) {
      let norm = (s + fh / 2) / fh; // 0 = top, 1 = bottom
      let sliceCol = norm < 0.28 ? cHigh : (norm < 0.68 ? cMid : cDark);
      let weight = norm < 0.35 ? 0.9 : 1.1;
      brush.set("slickMarkerMd", sliceCol, weight);
      let curveOffset = sin(norm * 180) * 4;
      brush.line(fx + curveOffset, fy + s, fx + fw + curveOffset, fy + s - 1);
    }

    // Specular wet glint on top ridge of each float
    brush.set("slickMarkerSm", PALETTE.pureWhite, 0.8);
    brush.line(fx + 4, fy - fh * 0.32, fx + fw - 3, fy - fh * 0.32 - 1);

    // Dark moulded groove ring inside the float
    brush.set("slickMarkerSm", PALETTE.abyssTeal, 0.7);
    brush.line(fx + 2, fy - fh * 0.45, fx + 2, fy + fh * 0.45);
  }

  // Turquoise water lapping over the bottom half of the lane line
  for (let i = 0; i < 32; i++) {
    let wx = random(0, 1180);
    let wy = lerp(y0, y1, wx / 1200) + random(6, 26);
    brush.set("slickMarkerMd", i % 2 === 0 ? PALETTE.turquoise : PALETTE.chlorineCyan, 0.9);
    brush.line(wx, wy, wx + random(35, 95), wy - random(2, 8));
  }
}

