  brush.vertex(920, 610);
  brush.vertex(760, 770);
  brush.vertex(480, 790);
  brush.vertex(310, 690);
  brush.endShape(true);
  brush.noWash();

  // --- A. STRAINING TRAPEZIUS & UPPER BACK (x: 490..720, y: 380..490) ---
  drawMarkerGradientPatch(
    [
      [485, 435], [565, 388], [670, 395], [745, 445],
      [690, 505], [585, 500], [490, 475]
    ],
    [
      PALETTE.skinCoolShadow,
      PALETTE.skinplumMid,
      PALETTE.skinBronze,
      PALETTE.skinWarmMid,
      PALETTE.skinLit,
      PALETTE.skinHigh
    ],
    28,
    "slickMarkerMd"
  );

  // --- B. HERO STRAINING RIGHT SHOULDER / DELTOID (x: 535..835, y: 430..695) ---
  // Built in three anatomical heads (anterior, lateral, posterior deltoid) with slick marker gradients
  let deltoidRings = 38;
  let cx = 675, cy = 535;
  for (let i = deltoidRings; i >= 0; i--) {
    let t = i / deltoidRings; // 1 = outer shadow/bounce, 0 = peak highlight
    let rx = lerp(18, 165, t);
    let ry = lerp(12, 118, t);

    let col;
    if (t > 0.86) col = PALETTE.skinDeepShadow;
    else if (t > 0.72) col = PALETTE.skinCyanBounce; // Turquoise pool reflection on underside
    else if (t > 0.56) col = PALETTE.skinCoolShadow;
    else if (t > 0.42) col = PALETTE.skinBronze;
    else if (t > 0.26) col = PALETTE.skinWarmMid;
    else if (t > 0.14) col = PALETTE.skinLit;
    else if (t > 0.06) col = PALETTE.skinHigh;
    else col = PALETTE.skinSpecular;

    let bName = t > 0.3 ? "slickMarkerMd" : "slickMarkerSm";
    brush.set(bName, col, map(t, 0, 1, 0.85, 1.35));

    // Sculpted anatomical contour around deltoid peak
    let pts = [];
    for (let a = -165; a <= 175; a += 28) {
      let radA = a * (PI / 180);
      let asymX = a > 0 ? rx * 1.08 : rx * 0.88;
      let asymY = a > 20 ? ry * 1.12 : ry * 0.82;
      let px = cx + cos(radA) * asymX - (1 - t) * 18;
      let py = cy + sin(radA) * asymY - (1 - t) * 24;
      pts.push([px, py, 0.9]);
    }
    brush.spline(pts, 0.55);
  }

  // Deltoid muscle fiber striations & wet specular ridges
  for (let s = 0; s < 34; s++) {
    let u = s / 33;
    let startX = lerp(545, 640, u);
    let startY = lerp(475, 445, u);
    let midX = lerp(615, 745, u);
    let midY = lerp(545, 510, u);
    let endX = lerp(700, 825, u);
    let endY = lerp(640, 585, u);

    let fiberCol =
      u > 0.35 && u < 0.68
        ? (s % 2 === 0 ? PALETTE.skinSpecular : PALETTE.skinHigh)
        : (u < 0.25 ? PALETTE.skinCyanBounce : PALETTE.skinWarmMid);

    brush.set("slickMarkerSm", fiberCol, random(0.65, 1.15));
    brush.spline([
      [startX, startY, 0.5],
      [midX, midY - sin(u * 180) * 14, 1.1],
      [endX, endY, 0.4]
    ], 0.5);
  }

  // --- C. CLAVICLE, STERNUM & PECTORAL STRAIN (x: 360..610, y: 495..710) ---
  for (let i = 0; i < 26; i++) {
    let t = i / 25;
    let yLine = lerp(500, 690, t);
    let col =
      t < 0.22 ? PALETTE.skinHigh :
      t < 0.45 ? PALETTE.skinWarmMid :
      t < 0.7 ? PALETTE.skinBronze :
      PALETTE.skinCyanBounce;
    brush.set("slickMarkerMd", col, 1.1);
    brush.spline([
      [350 + t * 30, yLine + 18, 0.6],
      [455, yLine - sin(t * 180) * 16, 1.0],
      [565, yLine + 8, 1.0],
      [645 - t * 20, yLine + 32, 0.5]
    ], 0.5);
  }

  // Clavicle bone ridge & suprasternal notch shadow
  brush.set("slickMarkerMd", PALETTE.skinDeepShadow, 1.2);
  brush.spline([[425, 535, 0.5], [485, 520, 1.1], [555, 492, 0.8], [605, 468, 0.4]], 0.5);
  brush.set("slickMarkerSm", PALETTE.skinSpecular, 1.0);
  brush.spline([[435, 543, 0.4], [495, 527, 1.2], [565, 498, 0.9], [610, 475, 0.3]], 0.5);
}

