    { x1: 555, y1: 488, x2: 830, y2: 554, mode: "shoulderDrag1" },
    { x1: 635, y1: 554, x2: 925, y2: 612, mode: "shoulderDrag2" },
    { x1: 455, y1: 575, x2: 675, y2: 632, mode: "chestCyanSlice" },
    // Left arm glitch block
    { x1: 135, y1: 545, x2: 345, y2: 598, mode: "cyanFoamDrag" }
  ];

  for (let b of faceSlabs) {
    let w = b.x2 - b.x1;
    let h = b.y2 - b.y1;

    // Enforce razor-sharp rectangular block edges via brush.clip
    brush.clip([b.x1, b.y1, b.x2, b.y2]);

    // Solid opaque wash base so the block cleanly replaces the underlying frame
    brush.noStroke();
    if (b.mode === "cyanFaceSlab" || b.mode === "cyanFoamDrag" || b.mode === "chestCyanSlice") {
      brush.wash(PALETTE.troughTeal, 250);
      brush.rect(b.x1 - 4, b.y1 - 4, w + 8, h + 8, "corner");
    } else {
      brush.wash(PALETTE.skinDeepShadow, 248);
      brush.rect(b.x1 - 4, b.y1 - 4, w + 8, h + 8, "corner");
    }
    brush.noWash();

    if (b.mode === "cyanFaceSlab") {
      // Smeared slab of chlorine-cyan water sliding diagonally (-31 deg) across the swimmer's face
      let stripeCount = 36;
      for (let i = 0; i < stripeCount; i++) {
        let t = i / (stripeCount - 1);
        let col =
          t < 0.16 ? PALETTE.deepPool :
          t < 0.36 ? PALETTE.turquoise :
          t < 0.64 ? PALETTE.chlorineCyan :
          t < 0.85 ? PALETTE.electricAqua :
          PALETTE.pureWhite;

        brush.set(t > 0.7 ? "slickMarkerSm" : "slickMarkerMd", col, random(1.0, 1.55));
        let sx = lerp(b.x1 - 90, b.x2 + 30, t);
        // Diagonal smear angle (-31 deg) + horizontal scanline smear
        brush.line(sx, b.y2 + 18, sx + 145, b.y1 - 18);
      }

      // Horizontal digital smear bands inside the chlorine-cyan slab
      for (let py = b.y1 + 3; py < b.y2; py += 5.5) {
        let n = noise(py * 0.15);
        let sCol = n > 0.62 ? PALETTE.pureWhite : (n > 0.35 ? PALETTE.electricAqua : PALETTE.chlorineCyan);
        brush.set("pixelSlab", sCol, 1.1);
        let runStart = b.x1 + random(0, 65);
        let runEnd = b.x2 - random(0, 45);
        brush.line(runStart, py, runEnd, py);
      }

      // Sliced droplets trapped inside the previous-instant water slab
      for (let d = 0; d < 9; d++) {
        drawSingleDroplet(random(b.x1 + 20, b.x2 - 20), random(b.y1 + 8, b.y2 - 8), random(4.5, 8.5), false);
      }
    } else if (b.mode === "displacedGoggleCap") {
      // Previous-instant frame block shifted diagonally (+72px, -44px):
      // Shows displaced mirrored goggle lens, strap buckle, and chlorine-cyan splash
      for (let py = b.y1 + 2; py < b.y2; py += 5) {
        let normY = (py - b.y1) / h;
        let c = normY < 0.45 ? PALETTE.capSlate : (normY < 0.75 ? PALETTE.electricAqua : PALETTE.skinHigh);
        brush.set("pixelSlab", c, 1.0);
        brush.line(b.x1, py, b.x2, py);
      }
      // Displaced mirrored goggle lens ghost shifted up-right
      for (let k = 0; k < 8; k++) {
        let ly = b.y1 + 12 + k * 4;
        brush.set("slickMarkerSm", k % 2 === 0 ? PALETTE.electricAqua : PALETTE.pureWhite, 1.1);
        brush.line(b.x1 + 65, ly, b.x1 + 165, ly - 14);
      }
      // Displaced goggle strap ghost
      brush.set("slickMarkerSm", PALETTE.strapBlack, 1.3);
      brush.line(b.x1 + 155, b.y1 + 38, b.x2 - 15, b.y1 + 8);
      brush.set("slickMarkerSm", PALETTE.pureWhite, 0.9);
      brush.line(b.x1 + 155, b.y1 + 34, b.x2 - 15, b.y1 + 4);
    } else if (b.mode === "shoulderDrag1" || b.mode === "shoulderDrag2") {
      // Displaced straining shoulder muscle striations dragged diagonally from previous instant
      for (let i = 0; i < 28; i++) {
        let t = i / 27;
        let col =
          t < 0.2 ? PALETTE.chlorineCyan :
          t < 0.42 ? PALETTE.skinSpecular :
          t < 0.65 ? PALETTE.skinHigh :
          t < 0.85 ? PALETTE.skinWarmMid :
          PALETTE.skinDeepShadow;
        let sx = lerp(b.x1 - 50, b.x2 + 20, t);
        brush.set("slickMarkerMd", col, 1.2);
        brush.line(sx, b.y2 + 12, sx + 115, b.y1 - 12);
      }
      // Displaced shoulder droplets inside the glitch block
      for (let d = 0; d < 6; d++) {
        drawSingleDroplet(random(b.x1 + 18, b.x2 - 18), random(b.y1 + 10, b.y2 - 10), random(5, 8.5), true);
      }
    } else {
      // Chlorine-cyan & whitewater foam drag slab
      for (let i = 0; i < 24; i++) {
        let t = i / 23;
        let col = t < 0.35 ? PALETTE.poolMid : (t < 0.72 ? PALETTE.chlorineCyan : PALETTE.foamIce);
        let sx = lerp(b.x1 - 40, b.x2 + 20, t);
        brush.set("slickMarkerMd", col, 1.25);
        brush.line(sx, b.y2 + 10, sx + 95, b.y1 - 10);
      }
    }

    brush.noClip();

    // Razor-sharp micro-edge highlight & chroma sub-pixel fringe on the block boundary
    brush.set("slickMarkerSm", PALETTE.pureWhite, 0.55);
    brush.line(b.x1, b.y1, b.x2, b.y1);
    brush.set("slickMarkerSm", PALETTE.abyssTeal, 0.65);
    brush.line(b.x1, b.y2, b.x2, b.y2);
  }
}

// ============================================================================
// 5B. SKIN-TONE PIXEL BLEED SIDEWAYS INTO THE LANE ROPE
// ============================================================================
function drawSkinPixelBleedIntoLaneRope() {
  // "A streak of skin-tone pixels bleeds sideways into the lane rope."
  // Originates from swimmer's upper head/shoulder/neck and streaks horizontally
  // across x: 465..1145, y: 315..412 right through the cobalt & red lane rope floats.

  let skinPalette = [
    PALETTE.skinDeepShadow,
    PALETTE.skinCoolShadow,
    PALETTE.skinBronze,
    PALETTE.skinWarmMid,
    PALETTE.skinLit,
    PALETTE.skinHigh,
    PALETTE.skinSpecular,
    PALETTE.skinCyanBounce
  ];

  // 1. Dense horizontal pixel-sorted bands bleeding sideways into the lane rope
  let bandRows = 22;
  for (let r = 0; r < bandRows; r++) {
    let ry = 318 + r * 4.3;
    let rowProgress = r / bandRows;
    // Stagger start near the head/temple/shoulder and extend far right into the lane rope
    let xStart = 465 + sin(r * 29) * 38 + (rowProgress > 0.6 ? 55 : 0);
    let xMax = 1135 - abs(rowProgress - 0.45) * 260;

    let curX = xStart;
    while (curX < xMax) {
      let cellW = random([12, 18, 26, 38, 52, 68]);
      let gap = random() < 0.22 ? random(8, 28) : 0;
      if (curX + cellW > xMax) cellW = xMax - curX;

      let cIdx = floor(
        map(noise(curX * 0.015, r * 0.35), 0.15, 0.85, 0, skinPalette.length)
      );
      let pCol = skinPalette[constrain(cIdx, 0, skinPalette.length - 1)];

      brush.set("pixelSlab", pCol, 0.95);
      brush.line(curX, ry, curX + cellW, ry);

      curX += cellW + gap;
    }
  }

  // 2. Discrete razor-sharp 16x16 & 24x12 macroblock skin pixels scattered into the lane floats
  for (let i = 0; i < 48; i++) {
    let px = random(530, 1140);
    let py = random(312, 412);
    // Quantize to 8px broadcast grid
    px = floor(px / 8) * 8;
    py = floor(py / 8) * 8;
    let pw = random([8, 16, 24, 32]);
    let ph = random([8, 8, 16]);
    let pCol = random([
      PALETTE.skinBronze,
      PALETTE.skinWarmMid,
      PALETTE.skinLit,
      PALETTE.skinHigh,
      PALETTE.skinSpecular,
      PALETTE.skinCoolShadow
    ]);

    brush.clip([px, py, px + pw, py + ph]);
    brush.set("pixelSlab", pCol, 1.4);
    for (let yy = py + 2; yy < py + ph; yy += 4) {
      brush.line(px, yy, px + pw, yy);
    }
    brush.noClip();
  }
}

// ============================================================================
// 5C. CORRUPTED MOTION-VECTOR FLOW STREAKS (HOT MAGENTA & ACID LIME)
// ============================================================================
function drawChromaMotionVectors() {
  // "Flow-field streaks carry colour along the corrupted motion vectors
  //  in hot magenta and acid lime chroma noise."
  brush.field("corruptedMotion");
  brush.refreshField(1.0);

  // Anchor zones along the glitch block seams, face slab, shoulder tear, and lane-rope bleed
  let vectorSeeds = [
    // Face slab & goggle tear
    { x: 295, y: 445, count: 26, len: [65, 195] },
    { x: 440, y: 395, count: 28, len: [75, 220] },
    { x: 565, y: 365, count: 24, len: [60, 180] },
    // Skin pixel bleed into lane rope
    { x: 640, y: 355, count: 22, len: [80, 240] },
    { x: 840, y: 348, count: 20, len: [70, 210] },
    // Straining shoulder & deltoid glitch blocks
    { x: 575, y: 535, count: 26, len: [70, 210] },
    { x: 715, y: 565, count: 24, len: [65, 190] },
    { x: 480, y: 610, count: 18, len: [55, 165] },
    // Left arm & wake tear
    { x: 210, y: 565, count: 16, len: [55, 160] }
  ];

  for (let z of vectorSeeds) {
    for (let i = 0; i < z.count; i++) {
      let sx = z.x + random(-85, 85);
      let sy = z.y + random(-38, 38);
      let sLen = random(z.len[0], z.len[1]);

      // Alternate hot magenta and acid lime chroma noise (with occasional neon accents)
      let isMagenta = (i + floor(sx)) % 2 === 0;
      let col;
      if (isMagenta) {
        col = random() < 0.7 ? PALETTE.hotMagenta : (random() < 0.5 ? PALETTE.magentaNeon : PALETTE.magentaDeep);
      } else {
        col = random() < 0.7 ? PALETTE.acidLime : (random() < 0.5 ? PALETTE.limeNeon : PALETTE.limeDeep);
      }

      let dir = sy < 415 && sx > 520 ? random(-8, 6) : random(-38, -22);
      brush.set("chromaVector", col, random(0.65, 1.45));
      brush.flowLine(sx, sy, sLen, dir);
    }
  }

  brush.noField();

  // Crisp MPEG motion-vector debug ticks & 16x16 chroma macroblock artifacts
  for (let i = 0; i < 55; i++) {
    let gx = floor(random(160, 1080) / 16) * 16;
    let gy = floor(random(290, 660) / 16) * 16;
    let c = i % 2 === 0 ? PALETTE.hotMagenta : PALETTE.acidLime;

    if (random() < 0.45) {
      // Razor-sharp 16x16 macroblock boundary artifact
      brush.set("slickMarkerSm", c, 0.55);
      brush.rect(gx, gy, 16, 16, "corner");
    } else {
      // Diagonal motion vector arrow/streak with origin dot
      let vx = gx + 28;
      let vy = gy - 17;
      brush.set("chromaVector", c, 0.9);
      brush.line(gx, gy, vx, vy);
      brush.set("pixelSlab", PALETTE.pureWhite, 0.6);
      brush.line(gx - 2, gy, gx + 2, gy);
    }
  }

  // Subtle chroma noise spray along the primary face & shoulder glitch seams
  brush.set("waterMist", PALETTE.hotMagenta, 0.75);
  brush.line(290, 448, 620, 355);
  brush.set("waterMist", PALETTE.acidLime, 0.75);
  brush.line(340, 385, 820, 545);
}

