  brush.line(265, FRAME_BOT + 3, 410, FRAME_BOT + 3);
  brush.set("chromaVector", PALETTE.hotMagenta, 0.85);
  brush.line(295, FRAME_BOT + 9, 435, FRAME_BOT + 9);
  brush.noClip();
}

// ============================================================================
// HELPER: MULTI-STEP SLICK MARKER GRADIENT PATCH
// ============================================================================
function drawMarkerGradientPatch(polyPts, colors, steps, brushName) {
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let cIdx = floor(t * (colors.length - 1));
    let col = colors[constrain(cIdx, 0, colors.length - 1)];

    let p0 = polyPts[0];
    let p1 = polyPts[1];
    let p2 = polyPts[2];
    let p3 = polyPts[3];
    let p4 = polyPts[4];
    let p5 = polyPts[5];

    let sx = lerp(p0[0], p5[0], t);
    let sy = lerp(p0[1], p5[1], t);
    let mx = lerp(p1[0], p4[0], t);
    let my = lerp(p1[1], p4[1], t);
    let ex = lerp(p2[0], p3[0], t);
    let ey = lerp(p2[1], p3[1], t);

    brush.set(brushName, col, 1.15);
    brush.spline([
      [sx, sy, 0.7],
      [mx, my, 1.1],
      [ex, ey, 0.7]
    ], 0.5);
  }
}

