// ============================================================================
// 1. COARSE GREYISH PAPER GROUND
// ============================================================================
function drawCoarseGreyPaper() {
  background("#c8c1b4");

  // Subtle mottled warm-grey paper washes
  brush.noStroke();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.25);

  const washes = [
    { x: 600, y: 600, w: 1180, h: 1180, c: "#c2baac", a: 45 },
    { x: 350, y: 320, w: 700, h: 650, c: "#d1cabd", a: 40 },
    { x: 860, y: 840, w: 720, h: 680, c: "#b8b0a1", a: 42 },
    { x: 250, y: 920, w: 600, h: 500, c: "#beb6a7", a: 35 },
    { x: 920, y: 260, w: 560, h: 520, c: "#bab1a2", a: 35 }
  ];
  for (let w of washes) {
    brush.fill(w.c, w.a);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }
  brush.noFill();

  // Coarse paper grain & unbleached rag fibres
  brush.set("spray", "#9c9486", 0.9);
  for (let i = 0; i < 65; i++) {
    let y = map(i, 0, 64, 20, 1180);
    brush.line(20, y + random(-8, 8), 1180, y + random(-8, 8));
  }

  brush.set("2H", "#aba395", 0.35);
  for (let i = 0; i < 420; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    let ang = random(360);
    let len = random(4, 18);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  brush.set("2H", "#dcd6c9", 0.3);
  for (let i = 0; i < 260; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    let ang = random(360);
    let len = random(3, 12);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// ============================================================================
// 2. NAIVE WOODCUT BORDER & OUT-OF-REGISTER STENCIL COLOURS
// ============================================================================
function drawWoodcutFrame() {
  // Frame coordinates
  const ox1 = 54, oy1 = 54, ox2 = 1146, oy2 = 1146;
  const ix1 = 186, iy1 = 186, ix2 = 1014, iy2 = 968;

  // --- PASS A: Under-layer of out-of-register stencil dabs (slipping outside lines) ---
  drawStencilPass(0.65);

  // --- PASS B: Heavy Black Woodblock Base Panels ---
  brush.noStroke();
  brush.wash("#171412", 242);
  // Top bar
  brush.rect(ox1, oy1, ox2 - ox1, iy1 - oy1, "corner");
  // Bottom banner bar
  brush.rect(ox1, iy2, ox2 - ox1, oy2 - iy2, "corner");
  // Left bar
  brush.rect(ox1, iy1, ix1 - ox1, iy2 - iy1, "corner");
  // Right bar
  brush.rect(ix2, iy1, ox2 - ix2, iy2 - iy1, "corner");
  brush.noWash();

  // --- PASS C: Carved Woodcut Motifs (Paper-colored gouges into the black block) ---
  const paperCol = "#cbc4b6";
  const paperWarm = "#d4cdbf";

  // Outer & inner double-gouged framing lines
  drawGougeRect(ox1 + 10, oy1 + 10, ox2 - ox1 - 20, oy2 - oy1 - 20, paperCol, 1.3);
  drawGougeRect(ox1 + 20, oy1 + 20, ox2 - ox1 - 40, oy2 - oy1 - 40, paperCol, 0.8);
  drawGougeRect(ix1 - 10, iy1 - 10, ix2 - ix1 + 20, iy2 - iy1 + 20, paperCol, 1.3);
  drawGougeRect(ix1 - 19, iy1 - 19, ix2 - ix1 + 38, iy2 - iy1 + 38, paperCol, 0.85);

  // Sawtooth / chip-carved border along inner edge
  drawChipCarvedStrip(ix1 - 10, iy1 - 19, ix2 + 10, iy1 - 19, 26, -12, true, paperCol);
  drawChipCarvedStrip(ix1 - 10, iy2 + 19, ix2 + 10, iy2 + 19, 26, 12, true, paperCol);
  drawChipCarvedStrip(ix1 - 19, iy1 - 10, ix1 - 19, iy2 + 10, 26, -12, false, paperCol);
  drawChipCarvedStrip(ix2 + 19, iy1 - 10, ix2 + 19, iy2 + 10, 26, 12, false, paperCol);

  // Four Corner Folk Rosettes (Top-Left, Top-Right, Bottom-Left, Bottom-Right)
  drawWoodcutCornerRosette(120, 120, 48, paperCol);
  drawWoodcutCornerRosette(1080, 120, 48, paperCol);
  drawWoodcutCornerRosette(120, 1057, 52, paperCol);
  drawWoodcutCornerRosette(1080, 1057, 52, paperCol);

  // Top Folk Scrollwork & Center Stylized Fish/Sun Medallion
  drawWoodcutTopMedallion(600, 120, paperCol);
  drawWoodcutFolkVineHorizontal(205, 515, 120, 34, 1, paperCol);
  drawWoodcutFolkVineHorizontal(995, 685, 120, 34, -1, paperCol);

  // Left & Right Vertical Folk Scrolls (Leaves, Tulips, Berries)
  drawWoodcutFolkVineVertical(120, 210, 945, 36, 1, paperCol);
  drawWoodcutFolkVineVertical(1080, 210, 945, 36, -1, paperCol);

  // Bottom Carved Woodcut Banner & Block Lettering: "SMOKED MACKEREL"
  drawWoodcutBanner(600, 1057, 690, 102, paperCol, paperWarm);

  // Stray woodblock chatter marks across border
  brush.set("woodgouge", paperCol, 0.65);
  for (let i = 0; i < 160; i++) {
    let side = floor(random(4));
    let gx, gy, ga;
    if (side === 0) { gx = random(70, 1130); gy = random(65, 175); ga = 0; }
    else if (side === 1) { gx = random(70, 1130); gy = random(980, 1135); ga = 0; }
    else if (side === 2) { gx = random(65, 175); gy = random(190, 960); ga = 90; }
    else { gx = random(1025, 1135); gy = random(190, 960); ga = 90; }
    let l = random(8, 22);
    brush.line(gx, gy, gx + cos(ga + random(-8, 8)) * l, gy + sin(ga + random(-8, 8)) * l);
  }

  // --- PASS D: Loose Out-of-Register Stencil Colour Laid Over the Border ---
  // Slips out of register over both the black ink and the carved gouges
  drawStencilPass(1.0);

  // --- PASS E: Heavy Pooled Black Ink at Woodcut Outlines ---
  // "the ink sits heavy at the outlines"
  drawHeavyWoodcutEdgeInk(ox1, oy1, ox2, oy2, ix1, iy1, ix2, iy2);
}

function drawStencilPass(alphaMult) {
  // Stencil palette: Crimson, Saffron, Leaf Green (warm folk tones)
  const crimson = "#be2829";
  const crimsonDark = "#981b1d";
  const saffron = "#e89c18";
  const saffronWarm = "#d98410";
  const leafGreen = "#497d34";
  const leafDark = "#366324";

  // Intentional misregistration offsets!
  const dxC = 15, dyC = -11; // Crimson slips right and up
  const dxS = -13, dyS = 10; // Saffron slips left and down
  const dxG = 12, dyG = 13;  // Leaf green slips right and down

  // 1. Corner Rosettes Stencil Dabs (Crimson & Saffron)
  const corners = [
    { x: 120, y: 120, r: 44 },
    { x: 1080, y: 120, r: 44 },
    { x: 120, y: 1057, r: 48 },
    { x: 1080, y: 1057, r: 48 }
  ];
  for (let c of corners) {
    dabStencilCircle(c.x + dxC, c.y + dyC, c.r * 0.95, crimson, crimsonDark, 155 * alphaMult);
    dabStencilCircle(c.x + dxS, c.y + dyS, c.r * 0.52, saffron, saffronWarm, 175 * alphaMult);
  }

  // 2. Top Medallion Stencil (Saffron & Crimson)
  dabStencilOval(600 + dxS, 120 + dyS, 130, 74, saffron, saffronWarm, 165 * alphaMult);
  dabStencilCircle(600 + dxC, 120 + dyC, 28, crimson, crimsonDark, 170 * alphaMult);

  // 3. Top & Side Folk Leaves (Leaf Green & Crimson Berries & Saffron Buds)
  // Top left & right vines
  for (let i = 0; i < 4; i++) {
    let txL = lerp(235, 485, i / 3);
    let txR = lerp(965, 715, i / 3);
    let ty = 120 + (i % 2 === 0 ? -16 : 16);
    dabStencilOval(txL + dxG, ty + dyG, 52, 28, leafGreen, leafDark, 155 * alphaMult);
    dabStencilOval(txR + dxG, ty + dyG, 52, 28, leafGreen, leafDark, 155 * alphaMult);
    if (i % 2 === 1) {
      dabStencilCircle(txL + dxC, ty - 22 + dyC, 16, crimson, crimsonDark, 165 * alphaMult);
      dabStencilCircle(txR + dxC, ty - 22 + dyC, 16, crimson, crimsonDark, 165 * alphaMult);
    } else {
      dabStencilCircle(txL + dxS, ty + 20 + dyS, 15, saffron, saffronWarm, 165 * alphaMult);
      dabStencilCircle(txR + dxS, ty + 20 + dyS, 15, saffron, saffronWarm, 165 * alphaMult);
    }
  }

  // Left & Right vertical vines
  for (let i = 0; i < 9; i++) {
    let vy = lerp(235, 920, i / 8);
    let vxOff = (i % 2 === 0) ? -18 : 18;
    // Left border
    dabStencilOval(120 + vxOff + dxG, vy + dyG, 32, 54, leafGreen, leafDark, 150 * alphaMult);
    // Right border
    dabStencilOval(1080 - vxOff + dxG, vy + dyG, 32, 54, leafGreen, leafDark, 150 * alphaMult);

    if (i % 3 === 0) {
      dabStencilCircle(120 - vxOff + dxC, vy + dyC, 19, crimson, crimsonDark, 170 * alphaMult);
      dabStencilCircle(1080 + vxOff + dxC, vy + dyC, 19, crimson, crimsonDark, 170 * alphaMult);
    } else if (i % 3 === 1) {
      dabStencilCircle(120 - vxOff + dxS, vy + dyS, 17, saffron, saffronWarm, 170 * alphaMult);
      dabStencilCircle(1080 + vxOff + dxS, vy + dyS, 17, saffron, saffronWarm, 170 * alphaMult);
    }
  }

  // 4. Bottom Banner Stencil Blocks (Saffron ribbon body, Crimson ribbon ends, Green flanking leaves)
  dabStencilRect(600 + dxS, 1057 + dyS, 650, 78, saffron, saffronWarm, 155 * alphaMult);
  dabStencilRect(235 + dxC, 1057 + dyC, 76, 68, crimson, crimsonDark, 165 * alphaMult);
  dabStencilRect(965 + dxC, 1057 + dyC, 76, 68, crimson, crimsonDark, 165 * alphaMult);
  dabStencilOval(205 + dxG, 1015 + dyG, 48, 28, leafGreen, leafDark, 150 * alphaMult);
  dabStencilOval(995 + dxG, 1015 + dyG, 48, 28, leafGreen, leafDark, 150 * alphaMult);
  dabStencilOval(205 + dxG, 1098 + dyG, 48, 28, leafGreen, leafDark, 150 * alphaMult);
  dabStencilOval(995 + dxG, 1098 + dyG, 48, 28, leafGreen, leafDark, 150 * alphaMult);
}

function dabStencilCircle(cx, cy, r, colMain, colEdge, alphaVal) {
  brush.noStroke();
  brush.wash(colMain, alphaVal * 0.72);
  brush.circle(cx, cy, r, 0.25);
  brush.noWash();

  // Dry stencil-dabbed stipple texture
  brush.set("stencil_dab", colMain, 1.1);
  for (let i = 0; i < 10; i++) {
    let a = random(360);
    let d = random(0, r * 0.85);
    brush.line(
      cx + cos(a) * d, cy + sin(a) * d,
      cx + cos(a + 35) * (d + 8), cy + sin(a + 35) * (d + 8)
    );
  }
  // Heavier pigment build-up at stencil cut edge
  brush.set("charcoal", colEdge, 1.3);
  brush.arc(cx, cy, r * 0.96, random(0, 60), random(220, 340));
}

function dabStencilOval(cx, cy, w, h, colMain, colEdge, alphaVal) {
  brush.noStroke();
  brush.wash(colMain, alphaVal * 0.7);
  brush.beginShape(0.45);
  for (let a = 0; a < 360; a += 45) {
    let radX = (w / 2) * (1 + random(-0.08, 0.08));
    let radY = (h / 2) * (1 + random(-0.08, 0.08));
    brush.vertex(cx + cos(a) * radX, cy + sin(a) * radY);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  brush.set("stencil_dab", colEdge, 0.95);
  brush.line(cx - w * 0.32, cy, cx + w * 0.32, cy + random(-4, 4));
}

function dabStencilRect(cx, cy, w, h, colMain, colEdge, alphaVal) {
  brush.noStroke();
  brush.wash(colMain, alphaVal * 0.62);
  brush.rect(cx, cy, w, h, "center");
  brush.noWash();

  brush.set("stencil_dab", colMain, 1.35);
  for (let i = 0; i < 24; i++) {
    let x1 = cx + random(-w * 0.46, w * 0.46);
    let y1 = cy + random(-h * 0.42, h * 0.42);
    brush.line(x1, y1, x1 + random(-28, 28), y1 + random(-10, 10));
  }
  brush.set("charcoal", colEdge, 1.4);
  brush.line(cx - w * 0.48, cy - h * 0.48, cx + w * 0.48, cy - h * 0.46);
  brush.line(cx - w * 0.47, cy + h * 0.48, cx + w * 0.49, cy + h * 0.47);
}

function drawGougeRect(x, y, w, h, col, wt) {
  brush.set("woodgouge", col, wt);
  brush.line(x, y, x + w, y);
  brush.line(x + w, y, x + w, y + h);
  brush.line(x + w, y + h, x, y + h);
  brush.line(x, y + h, x, y);
}

function drawChipCarvedStrip(x1, y1, x2, y2, count, depth, horiz, col) {
  brush.set("woodgouge", col, 0.95);
  for (let i = 0; i < count; i++) {
    let t0 = i / count;
    let t1 = (i + 0.5) / count;
    let t2 = (i + 1) / count;
    if (horiz) {
      let xa = lerp(x1, x2, t0);
      let xb = lerp(x1, x2, t1);
      let xc = lerp(x1, x2, t2);
      brush.line(xa, y1, xb, y1 + depth);
      brush.line(xb, y1 + depth, xc, y1);
    } else {
      let ya = lerp(y1, y2, t0);
      let yb = lerp(y1, y2, t1);
      let yc = lerp(y1, y2, t2);
      brush.line(x1, ya, x1 + depth, yb);
      brush.line(x1 + depth, yb, x1, yc);
    }
  }
}

function drawWoodcutCornerRosette(cx, cy, r, col) {
  brush.set("woodgouge", col, 1.25);
  brush.circle(cx, cy, r, 0.15);
  brush.set("woodgouge", col, 0.9);
  brush.circle(cx, cy, r * 0.32, 0.15);

  // 8 carved folk petals
  for (let a = 0; a < 360; a += 45) {
    let x1 = cx + cos(a) * (r * 0.36);
    let y1 = cy + sin(a) * (r * 0.36);
    let x2 = cx + cos(a) * (r * 0.88);
    let y2 = cy + sin(a) * (r * 0.88);
    let xm1 = cx + cos(a - 16) * (r * 0.65);
    let ym1 = cy + sin(a - 16) * (r * 0.65);
    let xm2 = cx + cos(a + 16) * (r * 0.65);
    let ym2 = cy + sin(a + 16) * (r * 0.65);

    brush.set("woodgouge", col, 1.15);
    brush.spline([[x1, y1, 0.5], [xm1, ym1, 1.1], [x2, y2, 0.5]], 0.5);
    brush.spline([[x1, y1, 0.5], [xm2, ym2, 1.1], [x2, y2, 0.5]], 0.5);
    brush.set("woodgouge", col, 0.8);
    brush.line(x1, y1, x2, y2);
  }
}

function drawWoodcutTopMedallion(cx, cy, col) {
  brush.set("woodgouge", col, 1.35);
  // Folk oval cartouche
  brush.beginShape(0.5);
  for (let a = 0; a < 360; a += 30) {
    brush.vertex(cx + cos(a) * 68, cy + sin(a) * 38);
  }
  brush.endShape(CLOSE);

  // Inner folk rosette / compass star
  for (let a = 0; a < 360; a += 30) {
    let rIn = 8;
    let rOut = (a % 60 === 0) ? 32 : 20;
    let rx = (a % 60 === 0) ? 54 : 30;
    brush.set("woodgouge", col, a % 60 === 0 ? 1.2 : 0.85);
    brush.line(cx + cos(a) * rIn, cy + sin(a) * 6, cx + cos(a) * rx, cy + sin(a) * rOut);
  }
  brush.set("woodgouge", col, 1.3);
  brush.circle(cx, cy, 9, 0.1);
}

function drawWoodcutFolkVineHorizontal(xStart, xEnd, yMid, amp, dir, col) {
  let steps = 24;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(xStart, xEnd, t);
    let y = yMid + sin(t * 360 * 1.5) * amp * 0.55;
    pts.push([x, y, 0.9 + 0.3 * sin(t * 180)]);
  }
  brush.set("woodgouge", col, 1.45);
  brush.spline(pts, 0.5);

  // Carved folk leaves & spiral tendrils along vine
  for (let i = 1; i < steps; i += 3) {
    let t = i / steps;
    let x = lerp(xStart, xEnd, t);
    let y = yMid + sin(t * 360 * 1.5) * amp * 0.55;
    let side = (i % 2 === 0) ? 1 : -1;
    let lx = x + dir * 22;
    let ly = y + side * 24;
    brush.set("woodgouge", col, 1.25);
    brush.spline([[x, y, 0.6], [x + dir * 10, y + side * 22, 1.3], [lx, ly, 0.5]], 0.5);
    brush.spline([[x, y, 0.6], [x + dir * 20, y + side * 8, 1.2], [lx, ly, 0.5]], 0.5);
    // Leaf central vein & gouge hatches
    brush.set("woodgouge", col, 0.75);
    brush.line(x, y, lx, ly);
    // Folk berry cluster
    brush.set("woodgouge", col, 1.1);
    brush.circle(x - dir * 8, y - side * 16, 5.5, 0.15);
    brush.circle(x + dir * 4, y - side * 20, 4.5, 0.15);
  }
}

function drawWoodcutFolkVineVertical(xMid, yStart, yEnd, amp, dir, col) {
  let steps = 36;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(yStart, yEnd, t);
    let x = xMid + sin(t * 360 * 3.0) * amp * 0.55 * dir;
    pts.push([x, y, 1.0]);
  }
  brush.set("woodgouge", col, 1.5);
  brush.spline(pts, 0.5);

  for (let i = 2; i < steps - 1; i += 3) {
    let t = i / steps;
    let y = lerp(yStart, yEnd, t);
    let x = xMid + sin(t * 360 * 3.0) * amp * 0.55 * dir;
    let side = (i % 2 === 0) ? 1 : -1;
    let lx = x + side * 28;
    let ly = y + 18;
    brush.set("woodgouge", col, 1.25);
    brush.spline([[x, y, 0.6], [x + side * 26, y + 4, 1.3], [lx, ly, 0.5]], 0.5);
    brush.spline([[x, y, 0.6], [x + side * 10, y + 20, 1.2], [lx, ly, 0.5]], 0.5);
    brush.set("woodgouge", col, 0.75);
    brush.line(x, y, lx, ly);

    // Opposite spiral scroll
    brush.set("woodgouge", col, 1.05);
    brush.arc(x - side * 16, y - 6, 10, 0, 250);
    brush.circle(x - side * 16, y - 6, 3.5, 0.1);
  }
}

function drawWoodcutBanner(cx, cy, w, h, col, colWarm) {
  let xL = cx - w / 2;
  let xR = cx + w / 2;
  let yT = cy - h / 2;
  let yB = cy + h / 2;

  // Carved light banner background with woodgrain horizontal gouges
  brush.set("woodgouge", col, 1.6);
  for (let y = yT + 7; y <= yB - 7; y += 4.2) {
    let wave = sin((y - yT) * 9) * 1.5;
    brush.line(xL + 8, y + wave, xR - 8, y - wave);
  }

  // Banner ribbon folds at left and right ends
  const foldW = 62;
  brush.set("woodgouge", colWarm, 1.4);
  // Left ribbon swallowtail
  brush.line(xL, yT + 10, xL - foldW, yT + 18);
  brush.line(xL - foldW, yT + 18, xL - foldW + 24, cy);
  brush.line(xL - foldW + 24, cy, xL - foldW, yB - 18);
  brush.line(xL - foldW, yB - 18, xL, yB - 10);
  for (let y = yT + 22; y < yB - 20; y += 6.5) {
    brush.set("woodgouge", col, 1.0);
    brush.line(xL - foldW + 18, y, xL - 4, y - 3);
  }

  // Right ribbon swallowtail
  brush.set("woodgouge", colWarm, 1.4);
  brush.line(xR, yT + 10, xR + foldW, yT + 18);
  brush.line(xR + foldW, yT + 18, xR + foldW - 24, cy);
  brush.line(xR + foldW - 24, cy, xR + foldW, yB - 18);
  brush.line(xR + foldW, yB - 18, xR, yB - 10);
  for (let y = yT + 22; y < yB - 20; y += 6.5) {
    brush.set("woodgouge", col, 1.0);
    brush.line(xR + 4, y - 3, xR + foldW - 18, y);
  }

  // Bold Black Woodblock Border around Banner
  brush.set("charcoal", "#12100e", 2.2);
  brush.line(xL, yT, xR, yT);
  brush.line(xR, yT, xR, yB);
  brush.line(xR, yB, xL, yB);
  brush.line(xL, yB, xL, yT);

  // Carved Block Letters: "SMOKED MACKEREL" in heavy black woodblock ink
  const textStr = "SMOKED MACKEREL";
  const letterW = 28;
  const letterH = 52;
  const tracking = 40;
  let startX = cx - ((textStr.length - 1) * tracking) / 2;

  for (let i = 0; i < textStr.length; i++) {
    let ch = textStr[i];
    if (ch !== " ") {
      drawWoodblockLetter(ch, startX + i * tracking, cy, letterW, letterH, "#14110f");
    } else {
      // Diamond interpunct between words
      let dx = startX + i * tracking;
      brush.set("charcoal", "#14110f", 1.8);
      brush.line(dx, cy - 8, dx + 7, cy);
      brush.line(dx + 7, cy, dx, cy + 8);
      brush.line(dx, cy + 8, dx - 7, cy);
      brush.line(dx - 7, cy, dx, cy - 8);
    }
  }
}

function drawWoodblockLetter(ch, cx, cy, w, h, col) {
  let xL = cx - w / 2;
  let xR = cx + w / 2;
  let yT = cy - h / 2;
  let yB = cy + h / 2;

  // Helper for thick woodcut strokes with chisel serifs
  const stem = (x1, y1, x2, y2, wt = 2.5) => {
    brush.set("charcoal", col, wt);
    brush.line(x1, y1, x2, y2);
    brush.set("rotring", col, wt * 0.9);
    brush.line(x1 + 1.5, y1, x2 + 1.5, y2);
  };
  const serif = (x, y, s = 5) => {
    brush.set("charcoal", col, 1.7);
    brush.line(x - s, y, x + s, y);
  };

  if (ch === "S") {
    stem(xR, yT + 9, xR - 4, yT);
    stem(xR - 4, yT, xL + 4, yT);
    stem(xL + 4, yT, xL, yT + 12);
    stem(xL, yT + 12, xR, cy + 8);
    stem(xR, cy + 8, xR - 4, yB);
    stem(xR - 4, yB, xL + 4, yB);
    stem(xL + 4, yB, xL, yB - 10);
  } else if (ch === "M") {
    stem(xL, yB, xL, yT);
    stem(xR, yB, xR, yT);
    stem(xL, yT, cx, cy + 8, 2.1);
    stem(xR, yT, cx, cy + 8, 2.1);
    serif(xL, yB); serif(xR, yB); serif(xL, yT); serif(xR, yT);
  } else if (ch === "O") {
    stem(xL + 3, yT, xR - 3, yT);
    stem(xR - 3, yT, xR, yT + 10);
    stem(xR, yT + 10, xR, yB - 10);
    stem(xR, yB - 10, xR - 3, yB);
    stem(xR - 3, yB, xL + 3, yB);
    stem(xL + 3, yB, xL, yB - 10);
    stem(xL, yB - 10, xL, yT + 10);
    stem(xL, yT + 10, xL + 3, yT);
  } else if (ch === "K") {
    stem(xL, yT, xL, yB);
    stem(xR, yT, xL + 3, cy + 2, 2.2);
    stem(xL + 5, cy - 3, xR, yB, 2.3);
    serif(xL, yT); serif(xL, yB); serif(xR, yT); serif(xR, yB);
  } else if (ch === "E") {
    stem(xL, yT, xL, yB);
    stem(xL, yT, xR, yT, 2.2);
    stem(xL, cy, xR - 5, cy, 2.0);
    stem(xL, yB, xR, yB, 2.2);
    serif(xL, yT); serif(xL, yB);
    stem(xR, yT, xR, yT + 8, 1.8);
    stem(xR, yB, xR, yB - 8, 1.8);
  } else if (ch === "D") {
    stem(xL, yT, xL, yB);
    stem(xL, yT, xR - 6, yT, 2.2);
    stem(xR - 6, yT, xR, yT + 12, 2.2);
    stem(xR, yT + 12, xR, yB - 12, 2.4);
    stem(xR, yB - 12, xR - 6, yB, 2.2);
    stem(xR - 6, yB, xL, yB, 2.2);
    serif(xL, yT); serif(xL, yB);
  } else if (ch === "A") {
    stem(cx, yT, xL, yB, 2.3);
    stem(cx, yT, xR, yB, 2.3);
    stem(xL + 5, cy + 8, xR - 5, cy + 8, 2.0);
    serif(xL, yB); serif(xR, yB);
  } else if (ch === "C") {
    stem(xR, yT + 11, xR - 4, yT, 2.1);
    stem(xR - 4, yT, xL + 4, yT, 2.2);
    stem(xL + 4, yT, xL, yT + 12, 2.3);
    stem(xL, yT + 12, xL, yB - 12, 2.5);
    stem(xL, yB - 12, xL + 4, yB, 2.3);
    stem(xL + 4, yB, xR - 4, yB, 2.2);
    stem(xR - 4, yB, xR, yB - 11, 2.1);
  } else if (ch === "R") {
    stem(xL, yT, xL, yB);
    stem(xL, yT, xR - 4, yT, 2.2);
    stem(xR - 4, yT, xR, yT + 11, 2.2);
    stem(xR, yT + 11, xR - 4, cy, 2.2);
    stem(xR - 4, cy, xL, cy, 2.1);
    stem(cx - 1, cy, xR, yB, 2.3);
    serif(xL, yT); serif(xL, yB); serif(xR, yB);
  } else if (ch === "L") {
    stem(xL, yT, xL, yB);
    stem(xL, yB, xR, yB, 2.3);
    stem(xR, yB, xR, yB - 10, 1.9);
    serif(xL, yT); serif(xL, yB);
  }
}

function drawHeavyWoodcutEdgeInk(ox1, oy1, ox2, oy2, ix1, iy1, ix2, iy2) {
  // Heavy, pooled black ink where woodblock edges press hard into the coarse paper
  brush.set("charcoal", "#0f0d0b", 2.6);
  brush.line(ox1, oy1, ox2, oy1);
  brush.line(ox2, oy1, ox2, oy2);
  brush.line(ox2, oy2, ox1, oy2);
  brush.line(ox1, oy2, ox1, oy1);

  brush.line(ix1, iy1, ix2, iy1);
  brush.line(ix2, iy1, ix2, iy2);
  brush.line(ix2, iy2, ix1, iy2);
  brush.line(ix1, iy2, ix1, iy1);

  // Extra irregular ink bead & splatter along block edges
  brush.set("rotring", "#0c0a09", 1.8);
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    let tNext = (i + 0.7) / 40;
    brush.line(lerp(ox1, ox2, t), oy1 + random(-1.5, 1.5), lerp(ox1, ox2, tNext), oy1 + random(-1.5, 1.5));
    brush.line(lerp(ox1, ox2, t), oy2 + random(-1.5, 1.5), lerp(ox1, ox2, tNext), oy2 + random(-1.5, 1.5));
    brush.line(lerp(ix1, ix2, t), iy1 + random(-1.5, 1.5), lerp(ix1, ix2, tNext), iy1 + random(-1.5, 1.5));
    brush.line(lerp(ix1, ix2, t), iy2 + random(-1.5, 1.5), lerp(ix1, ix2, tNext), iy2 + random(-1.5, 1.5));
  }
}

// ============================================================================
// 3. HYPERREAL CRUMPLED NEWSPRINT
// ============================================================================
function drawCrumpledNewsprint() {
  // Outer vertices of the crumpled newspaper sheet (overlapping the woodcut inner frame at corners!)
  // Grid of 5x5 control points forming 16 quad / 32 triangle facets
  const gx = [
    [162, 365, 588, 815, 1028],
    [192, 382, 575, 792, 995],
    [174, 398, 608, 822, 1018],
    [205, 412, 592, 788, 986],
    [178, 388, 614, 832, 1008]
  ];
  const gy = [
    [192, 168, 204, 174, 212],
    [372, 355, 392, 362, 398],
    [568, 542, 582, 548, 576],
    [762, 748, 778, 738, 768],
    [945, 972, 938, 966, 932]
  ];

  // --- 3A. Realistic Cast Shadow of the Crumpled Newsprint onto Paper & Frame ---
  const outerLoop = [
    [gx[0][0], gy[0][0]], [gx[0][1], gy[0][1]], [gx[0][2], gy[0][2]], [gx[0][3], gy[0][3]], [gx[0][4], gy[0][4]],
    [gx[1][4], gy[1][4]], [gx[2][4], gy[2][4]], [gx[3][4], gy[3][4]], [gx[4][4], gy[4][4]],
    [gx[4][3], gy[4][3]], [gx[4][2], gy[4][2]], [gx[4][1], gy[4][1]], [gx[4][0], gy[4][0]],
    [gx[3][0], gy[3][0]], [gx[2][0], gy[2][0]], [gx[1][0], gy[1][0]]
  ];

  // Soft outer penumbra + crisp contact shadow
  const shadowPasses = [
    { dx: 18, dy: 22, col: "#6e675c", a: 55 },
    { dx: 11, dy: 14, col: "#4c463e", a: 75 },
    { dx: 5, dy: 7, col: "#2b2722", a: 105 }
  ];
  brush.noStroke();
  for (let sp of shadowPasses) {
    brush.wash(sp.col, sp.a);
    brush.beginShape(0.12);
    for (let pt of outerLoop) {
      brush.vertex(pt[0] + sp.dx, pt[1] + sp.dy);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // --- 3B. Faceted 3D Newsprint Planes ---
  // Each quad [r,c] is split into two triangles with distinct light values to create crisp 3D crumple facets
  const facetTones = [
    "#ebe5d7", "#dfd8c8", "#d1c9b8", "#e6dfd0",
    "#c6beac", "#ded7c6", "#b8af9d", "#e9e2d3",
    "#d5cdbc", "#cbc2b0", "#e3dccb", "#bfb6a4"
  ];

  let facetIdx = 0;
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      let p00 = [gx[r][c], gy[r][c]];
      let p10 = [gx[r][c + 1], gy[r][c + 1]];
      let p01 = [gx[r + 1][c], gy[r + 1][c]];
      let p11 = [gx[r + 1][c + 1], gy[r + 1][c + 1]];

      // Center crumple sub-vertex inside quad for realistic paper buckling
      let pm = [
        (p00[0] + p10[0] + p01[0] + p11[0]) * 0.25 + ((r + c) % 2 === 0 ? 12 : -14),
        (p00[1] + p10[1] + p01[1] + p11[1]) * 0.25 + ((r * 3 + c) % 2 === 0 ? -11 : 13)
      ];

      const tris = [
        { pts: [p00, p10, pm], tone: facetTones[(facetIdx + 0) % facetTones.length] }, // Top (lit)
        { pts: [p10, p11, pm], tone: facetTones[(facetIdx + 4) % facetTones.length] }, // Right (shadowed)
        { pts: [p11, p01, pm], tone: facetTones[(facetIdx + 6) % facetTones.length] }, // Bottom (mid-dark)
        { pts: [p01, p00, pm], tone: facetTones[(facetIdx + 1) % facetTones.length] }  // Left (warm lit)
      ];

      brush.noStroke();
      for (let t of tris) {
        brush.wash(t.tone, 240);
        brush.beginShape(0.03);
        brush.vertex(t.pts[0][0], t.pts[0][1]);
        brush.vertex(t.pts[1][0], t.pts[1][1]);
        brush.vertex(t.pts[2][0], t.pts[2][1]);
        brush.endShape(CLOSE);
      }
      brush.noWash();

      // Subtle directional paper shading hatches & crinkle lines inside each sub-triangle
      for (let i = 0; i < 4; i++) {
        let t = tris[i];
        let cx = (t.pts[0][0] + t.pts[1][0] + t.pts[2][0]) / 3;
        let cy = (t.pts[0][1] + t.pts[1][1] + t.pts[2][1]) / 3;

        // Crease ridge & valley shading along triangle edges
        let isRidge = (i === 0 || i === 3);
        brush.set("2H", isRidge ? "#f6f1e4" : "#9c9280", isRidge ? 0.85 : 0.7);
        brush.line(t.pts[0][0], t.pts[0][1], pm[0], pm[1]);

        // Secondary micro-crinkles radiating from vertices
        brush.set("2H", "#b0a694", 0.4);
        for (let k = 0; k < 3; k++) {
          let u = random(0.15, 0.85);
          let vx = lerp(t.pts[0][0], t.pts[1][0], u);
          let vy = lerp(t.pts[0][1], t.pts[1][1], u);
          brush.line(pm[0], pm[1], lerp(pm[0], vx, 0.45), lerp(pm[1], vy, 0.45));
        }

        // Soft tonal modeling near fold valleys
        if (i === 1 || i === 2) {
          brush.set("charcoal", "#a39987", 0.45);
          brush.line(
            lerp(t.pts[0][0], cx, 0.3), lerp(t.pts[0][1], cy, 0.3),
            lerp(t.pts[1][0], cx, 0.3), lerp(t.pts[1][1], cy, 0.3)
          );
        }
      }

      facetIdx += 3;
    }
  }

  // --- 3C. Major Newspaper Fold Creases (Quarter-fold cross + diagonal crumples) ---
  for (let r = 0; r < 5; r++) {
    for (let c = 0; c < 4; c++) {
      drawPaperCrease(gx[r][c], gy[r][c], gx[r][c + 1], gy[r][c + 1], r === 2);
    }
  }
  for (let c = 0; c < 5; c++) {
    for (let r = 0; r < 4; r++) {
      drawPaperCrease(gx[r][c], gy[r][c], gx[r + 1][c], gy[r + 1][c], c === 2);
    }
  }

  // --- 3D. Printed Newsprint Columns, Headlines & Halftones (warped across the folds) ---
  drawNewsprintTypography(gx, gy);

  // --- 3E. Warm Translucent Grease & Smoke-Oil Stains from the Mackerel & Bread ---
  drawGreaseStains();

  // --- 3F. Crisp Illuminated & Shadowed Outer Edge of the Newsprint Sheet ---
  for (let i = 0; i < outerLoop.length; i++) {
    let p1 = outerLoop[i];
    let p2 = outerLoop[(i + 1) % outerLoop.length];
    let isLitEdge = (i < 4 || i >= 12);
    brush.set("HB", isLitEdge ? "#fbf7ec" : "#7a7162", isLitEdge ? 1.15 : 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawPaperCrease(x1, y1, x2, y2, isMainFold) {
  let nx = -(y2 - y1);
  let ny = (x2 - x1);
  let len = sqrt(nx * nx + ny * ny) || 1;
  nx /= len; ny /= len;

  // Shadow side of fold
  brush.set("2B", isMainFold ? "#857b6a" : "#a39988", isMainFold ? 0.9 : 0.55);
  brush.line(x1 + nx * 2, y1 + ny * 2, x2 + nx * 2, y2 + ny * 2);

  // Sharp highlight side of fold ridge
  brush.set("2H", "#faf5e8", isMainFold ? 1.1 : 0.7);
  brush.line(x1 - nx * 1.5, y1 - ny * 1.5, x2 - nx * 1.5, y2 - ny * 1.5);
}

function drawNewsprintTypography(gx, gy) {
  const inkFaint = "#6e685e";
  const inkMid = "#524d45";
  const inkDark = "#3d3932";

  // Helper to bilinearly interpolate within the 4x4 crumpled grid
  const mapGrid = (u, v) => {
    let cu = constrain(u * 4, 0, 3.999);
    let cv = constrain(v * 4, 0, 3.999);
    let c0 = floor(cu), r0 = floor(cv);
    let fu = cu - c0, fv = cv - r0;
    let xTop = lerp(gx[r0][c0], gx[r0][c0 + 1], fu);
    let xBot = lerp(gx[r0 + 1][c0], gx[r0 + 1][c0 + 1], fu);
    let yTop = lerp(gy[r0][c0], gy[r0][c0 + 1], fu);
    let yBot = lerp(gy[r0 + 1][c0], gy[r0 + 1][c0 + 1], fu);
    return [lerp(xTop, xBot, fv), lerp(yTop, yBot, fv)];
  };

  // Top Newspaper Masthead Rule & Serif Header
  let mL = mapGrid(0.05, 0.05);
  let mR = mapGrid(0.95, 0.05);
  brush.set("rotring", inkDark, 0.9);
  brush.line(mL[0], mL[1], mR[0], mR[1]);
  brush.set("rotring", inkMid, 0.45);
  brush.line(mL[0], mL[1] + 5, mR[0], mR[1] + 5);
  brush.line(mL[0], mL[1] + 28, mR[0], mR[1] + 28);

  // Simulated masthead title glyphs
  brush.set("rotring", inkDark, 1.1);
  for (let u = 0.14; u < 0.86; u += 0.028) {
    if (abs(u - 0.42) < 0.03 || abs(u - 0.65) < 0.03) continue;
    let p = mapGrid(u, 0.05);
    brush.line(p[0], p[1] + 9, p[0] + random(-2, 2), p[1] + 23);
    brush.line(p[0] - 4, p[1] + 10, p[0] + 5, p[1] + 10);
  }

  // 6 Vertical Newspaper Columns across the sheet
  const numCols = 6;
  for (let col = 0; col < numCols; col++) {
    let u0 = 0.05 + col * 0.152;
    let u1 = u0 + 0.132;

    // Column dividing rule
    if (col > 0) {
      let uRule = u0 - 0.01;
      for (let s = 0; s < 8; s++) {
        let pa = mapGrid(uRule, 0.09 + s * 0.108);
        let pb = mapGrid(uRule, 0.09 + (s + 1) * 0.108);
        brush.set("2H", inkFaint, 0.4);
        brush.line(pa[0], pa[1], pb[0], pb[1]);
      }
    }

    // Lines of tiny body text, headlines, and halftone blocks inside each column
    let v = 0.10;
    while (v < 0.94) {
      // Occasional bold sub-headline
      if (random() < 0.09 && v < 0.86) {
        let pL = mapGrid(u0, v);
        let pR = mapGrid(u0 + random(0.08, 0.125), v);
        brush.set("rotring", inkDark, 0.95);
        brush.line(pL[0], pL[1], pR[0], pR[1]);
        v += 0.015;
        let pL2 = mapGrid(u0, v);
        let pR2 = mapGrid(u0 + random(0.05, 0.10), v);
        brush.line(pL2[0], pL2[1], pR2[0], pR2[1]);
        v += 0.016;
        continue;
      }

      // Halftone photograph block in col 1 and col 4
      if ((col === 1 && v > 0.18 && v < 0.34) || (col === 4 && v > 0.62 && v < 0.78)) {
        let hEnd = (col === 1) ? 0.34 : 0.78;
        for (let hv = v; hv < hEnd; hv += 0.007) {
          let hpL = mapGrid(u0, hv);
          let hpR = mapGrid(u1, hv);
          brush.set("2B", inkMid, 0.65);
          brush.line(hpL[0], hpL[1], hpR[0], hpR[1]);
        }
        v = hEnd + 0.014;
        continue;
      }

      // Regular micro-text line broken into tiny word segments
      let lineEndU = (random() < 0.16) ? lerp(u0, u1, random(0.45, 0.85)) : u1;
      let curU = u0;
      brush.set("2H", random() < 0.5 ? inkFaint : inkMid, 0.38);
      while (curU < lineEndU - 0.012) {
        let wordLen = random(0.014, 0.036);
        let nextU = min(curU + wordLen, lineEndU);
        let pa = mapGrid(curU, v);
        let pb = mapGrid(nextU, v);
        brush.line(pa[0], pa[1], pb[0], pb[1]);
        curU = nextU + random(0.005, 0.010);
      }
      v += 0.0095;
    }
  }
}

function drawGreaseStains() {
  // Translucent warm amber/ochre oil stains where the smoked fish & rye bread sit on the newsprint
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.55, 0.5);

  const stains = [
    { x: 510, y: 505, rx: 240, ry: 95, ang: 28, c: "#b5863e", a: 52 },
    { x: 545, y: 715, rx: 270, ry: 105, ang: 25, c: "#ab7a32", a: 58 },
    { x: 350, y: 425, rx: 120, ry: 75, ang: 20, c: "#9e6b24", a: 45 },
    { x: 380, y: 645, rx: 135, ry: 82, ang: 22, c: "#9e6b24", a: 50 },
    { x: 690, y: 605, rx: 130, ry: 70, ang: 30, c: "#bd8f46", a: 42 },
    { x: 785, y: 395, rx: 115, ry: 85, ang: -15, c: "#b89052", a: 36 }
  ];

  for (let s of stains) {
    brush.fill(s.c, s.a);
    brush.beginShape(0.45);
    for (let a = 0; a < 360; a += 30) {
      let r1 = s.rx * (0.85 + 0.25 * noise(s.x * 0.01 + cos(a), sin(a)));
      let r2 = s.ry * (0.85 + 0.25 * noise(s.y * 0.01 + sin(a), cos(a)));
      let lx = cos(a) * r1;
      let ly = sin(a) * r2;
      let wx = s.x + lx * cos(s.ang) - ly * sin(s.ang);
      let wy = s.y + lx * sin(s.ang) + ly * cos(s.ang);
      brush.vertex(wx, wy);
    }
    brush.endShape(CLOSE);
  }
  brush.noFill();
}

// ============================================================================
// 4. HYPERREAL HEEL OF RYE BREAD & SCATTERED FLAKY CRUMBS
// ============================================================================
function drawRyeBreadAndCrumbs() {
  const bx = 795, by = 365;

  // --- 4A. Cast Shadow of Rye Bread Heel onto Newsprint ---
  const shadowLayers = [
    { dx: 24, dy: 28, rx: 148, ry: 112, c: "#786954", a: 60 },
    { dx: 14, dy: 17, rx: 138, ry: 104, c: "#4f4232", a: 85 },
    { dx: 6, dy: 8, rx: 130, ry: 96, c: "#261d14", a: 135 }
  ];
  brush.noStroke();
  for (let sl of shadowLayers) {
    brush.wash(sl.c, sl.a);
    brush.beginShape(0.4);
    for (let a = 0; a < 360; a += 24) {
      let radX = sl.rx * (0.92 + 0.1 * sin(a * 3));
      let radY = sl.ry * (0.92 + 0.1 * cos(a * 2));
      brush.vertex(bx + sl.dx + cos(a) * radX, by + sl.dy + sin(a) * radY);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // --- 4B. Domed Dark Mahogany Crust Back of the Rye Loaf Heel ---
  // Outer crust silhouette (extends to the upper-right of the cut face)
  const crustCenter = { x: bx + 34, y: by - 14 };
  const crustTones = [
    { scale: 1.0, dx: 0, dy: 0, c: "#2e190f", a: 245 },
    { scale: 0.92, dx: -4, dy: -4, c: "#472818", a: 210 },
    { scale: 0.78, dx: -10, dy: -10, c: "#633b22", a: 185 },
    { scale: 0.58, dx: -18, dy: -16, c: "#7d4d2d", a: 150 }
  ];

  brush.noStroke();
  for (let ct of crustTones) {
    brush.wash(ct.c, ct.a);
    brush.beginShape(0.38);
    for (let a = 0; a < 360; a += 20) {
      let rx = 128 * ct.scale * (0.94 + 0.08 * sin(a * 3 + 20));
      let ry = 98 * ct.scale * (0.94 + 0.08 * cos(a * 2 - 15));
      let lx = cos(a) * rx;
      let ly = sin(a) * ry;
      let rot = -22;
      let wx = crustCenter.x + ct.dx + lx * cos(rot) - ly * sin(rot);
      let wy = crustCenter.y + ct.dy + lx * sin(rot) + ly * cos(rot);
      brush.vertex(wx, wy);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // Crust texture: roasted blisters, deep artisanal scoring cracks & flour dusting
  for (let i = 0; i < 240; i++) {
    let ang = random(-110, 85);
    let d = random(25, 115);
    let px = crustCenter.x + cos(ang - 22) * d * 1.15;
    let py = crustCenter.y + sin(ang - 22) * d * 0.9;
    let cCol = random(["#1f1009", "#3b2012", "#59331d", "#754729", "#8c5936"]);
    brush.set("cpencil", cCol, random(0.6, 1.3));
    let l = random(5, 16);
    let sa = ang + 70 + random(-20, 20);
    brush.line(px, py, px + cos(sa) * l, py + sin(sa) * l);
  }

  // Deep baker's score crack across the top-right crust with pale flour caught inside
  const scorePts = [
    [bx - 8, by - 92, 0.5],
    [bx + 42, by - 78, 1.3],
    [bx + 92, by - 42, 1.4],
    [bx + 128, by + 8, 0.6]
  ];
  brush.set("charcoal", "#1a0d07", 2.2);
  brush.spline(scorePts, 0.45);
  brush.set("cpencil", "#9e6b43", 1.2);
  brush.spline([
    [bx - 6, by - 88, 0.5],
    [bx + 44, by - 74, 1.2],
    [bx + 94, by - 38, 1.1],
    [bx + 126, by + 12, 0.5]
  ], 0.45);

  // Artisanal flour dusting on the crust ridges
  for (let i = 0; i < 190; i++) {
    let ang = random(-95, 65);
    let d = random(42, 112);
    let fx = crustCenter.x + cos(ang - 22) * d * 1.12 + random(-6, 6);
    let fy = crustCenter.y + sin(ang - 22) * d * 0.88 + random(-6, 6);
    brush.set("cpencil", random(["#dfd7c6", "#cfc5b2", "#eee8da"]), random(0.45, 0.95));
    brush.line(fx, fy, fx + random(-5, 5), fy + random(-4, 4));
  }

  // --- 4C. Sliced Face of the Rye Bread Heel (Hyperreal Cellular Crumb) ---
  const faceCenter = { x: bx - 18, y: by + 12 };
  const faceRx = 108, faceRy = 82, faceRot = -22;

  const facePt = (rScale, angDeg) => {
    let rx = faceRx * rScale * (0.95 + 0.06 * sin(angDeg * 3 + 40));
    let ry = faceRy * rScale * (0.95 + 0.06 * cos(angDeg * 2 - 25));
    // Flatten bottom edge slightly where bread rested in the oven
    if (sin(angDeg) > 0.35) {
      ry *= map(sin(angDeg), 0.35, 1.0, 1.0, 0.78);
    }
    let lx = cos(angDeg) * rx;
    let ly = sin(angDeg) * ry;
    return [
      faceCenter.x + lx * cos(faceRot) - ly * sin(faceRot),
      faceCenter.y + lx * sin(faceRot) + ly * cos(faceRot)
    ];
  };

  // Outer dark baked crust rim of the cut face
  brush.noStroke();
  brush.wash("#2b170e", 245);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 18) {
    let p = facePt(1.03, a);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);

  // Warm dense rye interior crumb base
  const crumbPasses = [
    { s: 0.96, c: "#69492f", a: 245 },
    { s: 0.88, c: "#825e40", a: 225 },
    { s: 0.72, c: "#946f4e", a: 195 },
    { s: 0.50, c: "#a37e5c", a: 155 }
  ];
  for (let cp of crumbPasses) {
    brush.wash(cp.c, cp.a);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 18) {
      let p = facePt(cp.s, a);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // Subtle knife-slice striations across the crumb face
  brush.set("2H", "#735236", 0.35);
  for (let i = -9; i <= 9; i++) {
    let a1 = 155 - i * 7;
    let a2 = 25 + i * 7;
    let p1 = facePt(0.88, a1);
    let p2 = facePt(0.88, a2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 420+ Hyperreal Crumb Alveoli (Pores), Rye Grain Flecks & Caraway Seeds
  for (let i = 0; i < 440; i++) {
    let r = sqrt(random(0.01, 0.86));
    let a = random(360);
    let p = facePt(r, a);
    let px = p[0], py = p[1];
    let poreSize = random(1.8, 5.8) * (1 - r * 0.25);

    // Dark shadowed top-left inside of the bread pore
    let holeCol = random(["#2e1b0f", "#3d2516", "#4f321e", "#5c3b24"]);
    brush.set("rotring", holeCol, random(0.65, 1.25));
    brush.line(px - poreSize * 0.5, py - poreSize * 0.3, px + poreSize * 0.4, py - poreSize * 0.1);
    if (poreSize > 3.2) {
      brush.line(px - poreSize * 0.3, py + poreSize * 0.2, px + poreSize * 0.3, py + poreSize * 0.25);
    }

    // Illuminated warm tan/golden rim on bottom-right edge of the pore
    let rimCol = random(["#b58f69", "#c9a680", "#d9ba96", "#a8825d"]);
    brush.set("glint", rimCol, random(0.6, 1.05));
    brush.line(
      px - poreSize * 0.2, py + poreSize * 0.45,
      px + poreSize * 0.65, py + poreSize * 0.2
    );
  }

  // Embedded cracked rye kernels & curved dark caraway seeds in the slice
  for (let i = 0; i < 65; i++) {
    let r = sqrt(random(0.02, 0.90));
    let a = random(360);
    let p = facePt(r, a);
    let sa = random(360);
    brush.set("rotring", "#24130a", 0.85);
    brush.line(p[0], p[1], p[0] + cos(sa) * 4.5, p[1] + sin(sa) * 4.5);
    brush.set("glint", "#cfa97e", 0.55);
    brush.line(p[0] + 0.8, p[1] + 0.8, p[0] + cos(sa) * 3.5 + 0.8, p[1] + sin(sa) * 3.5 + 0.8);
  }

  // Crisp flaky crust border around the cut slice
  for (let a = 0; a < 360; a += 6) {
    let pIn = facePt(0.94, a);
    let pOut = facePt(1.03, a + 3);
    let isTopLeft = (cos(a - 45) < 0);
    brush.set("cpencil", isTopLeft ? "#a6754b" : "#1c0e07", 0.95);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }

  // --- 4D. Scattered Flaky Crumbs, Crust Shards & Caraway Seeds on Newsprint ---
  drawScatteredCrumbs(bx, by);
}

function drawScatteredCrumbs(bx, by) {
  // Crumb scatter zones around the base of the rye bread heel
  for (let i = 0; i < 115; i++) {
    // Cluster nearer the cut face and cascading down-left & down-right
    let t = pow(random(), 1.35);
    let ang = random(95, 255) + random(-25, 25);
    let dist = lerp(75, 275, t);
    let cx = bx - 15 + cos(ang) * dist + random(-18, 18);
    let cy = by + 25 + sin(ang) * dist * 0.85 + random(-15, 15);

    let sz = random(1.8, 7.5) * (1 - t * 0.45);
    let isCrustShard = random() < 0.35;

    // Tiny crisp cast shadow to bottom-right
    brush.set("rotring", "#2b2118", sz * 0.26);
    brush.line(cx + 1.5, cy + 2.2, cx + sz * 0.85 + 1.5, cy + sz * 0.35 + 2.2);

    // Crumb body
    let bodyCol = isCrustShard
      ? random(["#3b2012", "#54301b", "#6e4226"])
      : random(["#8c6747", "#a37c58", "#b8926c", "#785538"]);
    brush.set("cpencil", bodyCol, sz * 0.35);
    brush.line(cx, cy, cx + sz * 0.75, cy + random(-sz * 0.3, sz * 0.3));

    // Bright top-left crumb catchlight
    let hiCol = isCrustShard ? "#b58359" : "#ebdac3";
    brush.set("glint", hiCol, sz * 0.22);
    brush.line(cx - 0.5, cy - 0.8, cx + sz * 0.45, cy - 0.6);
  }

  // Scattered caraway seeds on the newsprint
  for (let i = 0; i < 28; i++) {
    let cx = bx + random(-185, 105);
    let cy = by + random(55, 195);
    let a = random(360);
    // Shadow
    brush.set("2H", "#4a3d2f", 0.55);
    brush.line(cx + 1.2, cy + 1.5, cx + cos(a) * 6 + 1.2, cy + sin(a) * 6 + 1.5);
    // Curved caraway seed
    brush.set("rotring", "#2e1a0e", 0.75);
    brush.line(cx, cy, cx + cos(a) * 5.5, cy + sin(a) * 5.5);
    brush.set("glint", "#b88b5e", 0.45);
    brush.line(cx + 0.5, cy - 0.4, cx + cos(a) * 4, cy + sin(a) * 4 - 0.4);
  }
}

// ============================================================================
// 5. HYPERREAL SMOKED MACKEREL (GOLD-BRONZE SHEEN, EVERY SCALE, FLAKY FLESH)
// ============================================================================
function drawSmokedMackerel(cfg) {
  // Cubic Bezier spine helper for the mackerel
  const spinePt = (t) => {
    let u = 1 - t;
    let x = u * u * u * cfg.x0 + 3 * u * u * t * cfg.x1 + 3 * u * t * t * cfg.x2 + t * t * t * cfg.x3;
    let y = u * u * u * cfg.y0 + 3 * u * u * t * cfg.y1 + 3 * u * t * t * cfg.y2 + t * t * t * cfg.y3;
    return [x, y];
  };

  const spineTan = (t) => {
    let eps = 0.005;
    let pA = spinePt(max(0, t - eps));
    let pB = spinePt(min(1, t + eps));
    let dx = pB[0] - pA[0];
    let dy = pB[1] - pA[1];
    let l = sqrt(dx * dx + dy * dy) || 1;
    return [dx / l, dy / l];
  };

  // Anatomical fusiform mackerel profile (t = 0 snout, t = 0.21 gill edge, t = 0.40 max girth, t = 0.90 tail peduncle)
  const halfWidth = (t, isDorsal) => {
    let w;
    if (t < 0.16) {
      w = pow(t / 0.16, 0.74) * 0.68;
    } else if (t < 0.42) {
      let u = (t - 0.16) / 0.26;
      w = lerp(0.68, 1.0, sin(u * 90));
    } else if (t < 0.88) {
      let u = (t - 0.42) / 0.46;
      w = lerp(1.0, 0.155, pow(u, 1.18));
    } else {
      let u = (t - 0.88) / 0.12;
      w = lerp(0.155, 0.19, u);
    }
    let asym = isDorsal ? (0.93 - cfg.roll * 0.15) : (1.07 + cfg.roll * 0.15);
    return w * cfg.maxRadius * asym;
  };

  // Maps body coordinates (t in [0, 0.92], v in [-1 dorsal .. +1 ventral]) to canvas [x, y]
  const bodyPt = (t, v) => {
    let sp = spinePt(t);
    let tan = spineTan(t);
    // Normal pointing toward dorsal (-v) and ventral (+v)
    let nx = -tan[1];
    let ny = tan[0];
    let r = (v < 0) ? halfWidth(t, true) * (-v) : halfWidth(t, false) * v;
    return [sp[0] + nx * r, sp[1] + ny * r];
  };

  // --- 5A. Deep Multi-Pass Cast Shadow & Warm Golden Reflection on Newsprint ---
  const fishShadows = [
    { dx: 18, dy: 26, s: 1.08, c: "#7d6442", a: 55 }, // Warm amber reflected glow
    { dx: 12, dy: 18, s: 1.02, c: "#4d3c28", a: 85 },
    { dx: 6, dy: 9, s: 0.96, c: "#21180f", a: 145 }   // Crisp contact shadow
  ];
  brush.noStroke();
  for (let fs of fishShadows) {
    brush.wash(fs.c, fs.a);
    brush.beginShape(0.3);
    for (let t = 0; t <= 0.92; t += 0.06) {
      let p = bodyPt(t, -0.82 * fs.s);
      brush.vertex(p[0] + fs.dx, p[1] + fs.dy);
    }
    for (let t = 0.92; t >= 0; t -= 0.06) {
      let p = bodyPt(t, 1.02 * fs.s);
      brush.vertex(p[0] + fs.dx, p[1] + fs.dy);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // --- 5B. Dorsal Spiny Fin, Second Dorsal, Anal Fin, Finlets & Forked Tail Fin (Behind Body) ---
  drawMackerelFinsAndTail(bodyPt, spinePt, spineTan, cfg);

  // --- 5C. Base 3D Cylindrical Metallic Body Wash ---
  brush.noStroke();
  // Full silhouette base in rich smoked bronze
  brush.wash("#7a4b1e", 242);
  brush.beginShape(0.25);
  for (let t = 0; t <= 0.92; t += 0.04) {
    let p = bodyPt(t, -1.0);
    brush.vertex(p[0], p[1]);
  }
  for (let t = 0.92; t >= 0; t -= 0.04) {
    let p = bodyPt(t, 1.0);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);

  // Longitudinal cylindrical tone bands (Dorsal char -> Gold-Bronze flank -> Smoked Cream belly -> Reflected shadow)
  const bands = [
    { v0: -1.00, v1: -0.58, c: "#29180d", a: 230 }, // Deep charred dorsal ridge
    { v0: -0.65, v1: -0.28, c: "#693b14", a: 210 }, // Smoked mahogany upper flank
    { v0: -0.35, v1: 0.12,  c: "#c98527", a: 215 }, // Burnished golden-bronze lateral band
    { v0: -0.22, v1: 0.02,  c: "#edb44e", a: 195 }, // Intense metallic gold sheen core
    { v0: 0.08,  v1: 0.52,  c: "#d8ae72", a: 205 }, // Warm copper-champagne lower flank
    { v0: 0.42,  v1: 0.80,  c: "#ebd6b0", a: 210 }, // Silvery smoked cream belly
    { v0: 0.74,  v1: 1.00,  c: "#6e4d2c", a: 215 }  // Turned belly edge in shadow
  ];

  for (let b of bands) {
    brush.wash(b.c, b.a);
    brush.beginShape(0.25);
    for (let t = 0.02; t <= 0.91; t += 0.05) {
      let p = bodyPt(t, b.v0);
      brush.vertex(p[0], p[1]);
    }
    for (let t = 0.91; t >= 0.02; t -= 0.05) {
      let p = bodyPt(t, b.v1);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(CLOSE);
  }
  brush.noWash();

  // --- 5D. Fine Longitudinal Shading & Cylindrical Form Modeling ---
  const vSteps = 44;
  for (let iv = 0; iv <= vSteps; iv++) {
    let v = map(iv, 0, vSteps, -0.97, 0.97);
    let col;
    if (v < -0.62) col = "#1f1209";
    else if (v < -0.36) col = "#4f2c10";
    else if (v < -0.15) col = "#b5721e";
    else if (v < 0.06) col = "#f2c25e";
    else if (v < 0.32) col = "#cf9848";
    else if (v < 0.68) col = "#f0dec0";
    else if (v < 0.85) col = "#a68256";
    else col = "#47301b";

    brush.set("cpencil", col, 0.85);
    let pts = [];
    for (let t = 0.04; t <= 0.90; t += 0.04) {
      let p = bodyPt(t, v);
      pts.push([p[0], p[1], 0.9]);
    }
    brush.spline(pts, 0.4);
  }

  // --- 5E. Signature Mackerel Dorsal Tiger-Stripes (Wavy Vermiculations) ---
  const numStripes = 33;
  for (let i = 0; i < numStripes; i++) {
    let tBase = map(i, 0, numStripes - 1, 0.21, 0.86);
    let stripePts = [];
    let steps = 7;
    let phase = i * 47;
    for (let s = 0; s <= steps; s++) {
      let sv = map(s, 0, steps, -0.96, 0.04 + 0.08 * sin(i * 55));
      // Stripes angle slightly backward and undulate organically
      let st = tBase + (s / steps) * 0.018 + sin(s * 65 + phase) * 0.008;
      let p = bodyPt(st, sv);
      let press = map(s, 0, steps, 0.9, 0.25);
      if (s === 3) press = 1.25;
      stripePts.push([p[0], p[1], press]);
    }
    brush.set("charcoal", "#170e07", 1.05);
    brush.spline(stripePts, 0.5);

    // Warm bronze border along each dark stripe
    brush.set("cpencil", "#4a280d", 0.75);
    let offsetPts = stripePts.map(pt => [pt[0] + 1.5, pt[1] + 1.0, pt[2] * 0.8]);
    brush.spline(offsetPts, 0.5);

    // Occasional bifurcating fork in the mackerel stripe
    if (i % 3 === 1 && i < numStripes - 3) {
      let pFork0 = bodyPt(tBase + 0.009, -0.52);
      let pFork1 = bodyPt(tBase + 0.022, -0.24);
      let pFork2 = bodyPt(tBase + 0.026, -0.02);
      brush.set("charcoal", "#1f1209", 0.85);
      brush.spline([[pFork0[0], pFork0[1], 0.9], [pFork1[0], pFork1[1], 1.0], [pFork2[0], pFork2[1], 0.3]], 0.5);
    }
  }

  // --- 5F. Every Scale, Diamond Micro-Mesh & Smoked Skin Crinkles ---
  // Imbricated scale rows from gill cover (t=0.21) to tail peduncle (t=0.88)
  const scaleCols = 52;
  const scaleRows = 18;
  for (let ic = 0; ic < scaleCols; ic++) {
    let t = map(ic, 0, scaleCols - 1, 0.21, 0.88);
    let scaleW = map(t, 0.21, 0.88, 6.2, 2.8);

    for (let ir = 0; ir < scaleRows; ir++) {
      let v = map(ir, 0, scaleRows - 1, -0.88, 0.86) + ((ic % 2) * 0.025);
      if (abs(v) > 0.92) continue;

      // Skip scale skin inside the flaky flesh split on Fish 2
      if (cfg.hasSkinSplit && t > 0.42 && t < 0.60 && v > -0.18 && v < 0.36) continue;

      let p = bodyPt(t, v);
      let pNext = bodyPt(t + 0.011, v + 0.045);
      let pPrev = bodyPt(t + 0.011, v - 0.045);

      // Choose scale edge tone based on cylindrical illumination
      let sCol, sBrush, sWt;
      if (v > -0.34 && v < 0.08) {
        // Dazzling gold-bronze highlight zone
        sCol = ( (ic + ir) % 3 === 0 ) ? "#fff1be" : ((ic % 2 === 0) ? "#f5c663" : "#d48b28");
        sBrush = "glint";
        sWt = 0.85;
      } else if (v >= 0.08 && v < 0.68) {
        // Warm silver-gold belly scales
        sCol = ( (ic + ir) % 2 === 0 ) ? "#faecd2" : "#bfa071";
        sBrush = "glint";
        sWt = 0.72;
      } else if (v <= -0.34) {
        // Smoked bronze & copper dorsal scales
        sCol = ( (ic + ir) % 4 === 0 ) ? "#b87425" : "#38200d";
        sBrush = "2H";
        sWt = 0.65;
      } else {
        // Shadowed ventral turn
        sCol = "#4f361e";
        sBrush = "2H";
        sWt = 0.6;
      }

      brush.set(sBrush, sCol, sWt);
      brush.line(p[0], p[1], pNext[0], pNext[1]);
      if ((ic + ir) % 2 === 0) {
        brush.line(p[0], p[1], pPrev[0], pPrev[1]);
      }
    }
  }

  // Characteristic hot-smoked mackerel transverse skin crinkles & heat blisters
  for (let i = 0; i < 38; i++) {
    let t = random(0.23, 0.82);
    let vStart = random(-0.48, 0.15);
    let vEnd = vStart + random(0.28, 0.58);
    if (cfg.hasSkinSplit && t > 0.41 && t < 0.61 && vEnd > -0.2 && vStart < 0.38) continue;

    let crinkleDark = [];
    let crinkleLit = [];
    for (let s = 0; s <= 5; s++) {
      let sv = lerp(vStart, vEnd, s / 5);
      let st = t + sin(s * 72 + i * 30) * 0.007;
      let p = bodyPt(st, sv);
      crinkleDark.push([p[0], p[1], 0.8]);
      crinkleLit.push([p[0] - 1.3, p[1] - 1.1, 0.95]);
    }
    brush.set("2B", "#4a280e", 0.65);
    brush.spline(crinkleDark, 0.45);
    brush.set("glint", "#ffebb3", 0.75);
    brush.spline(crinkleLit, 0.45);
  }

  // Lateral sensory line running from upper gill to tail
  let latPts = [];
  for (let t = 0.21; t <= 0.89; t += 0.03) {
    let lv = lerp(-0.18, 0.0, (t - 0.21) / 0.68);
    let p = bodyPt(t, lv);
    latPts.push([p[0], p[1], 0.85]);
  }
  brush.set("2B", "#3d220c", 0.7);
  brush.spline(latPts, 0.4);
  brush.set("glint", "#f7d37e", 0.65);
  brush.spline(latPts.map(pt => [pt[0], pt[1] + 1.4, pt[2]]), 0.4);

  // --- 5G. Flaky Split in the Smoked Skin (on Foreground Mackerel) ---
  if (cfg.hasSkinSplit) {
    drawFlakySkinSplit(bodyPt);
  }

  // --- 5H. Detailed Anatomical Head, Metallic Gill Cover (Operculum) & Glassy Eye ---
  drawMackerelHeadAndEye(bodyPt, cfg);

  // --- 5I. Near Pectoral Fin Overlapping the Golden Flank ---
  drawPectoralFin(bodyPt);

  // --- 5J. Final Burnished Gold-Bronze Specular Sheen & Blister Highlights ---
  for (let i = 0; i < 95; i++) {
    let t = random(0.21, 0.84);
    let v = random(-0.32, 0.04);
    if (cfg.hasSkinSplit && t > 0.41 && t < 0.61 && v > -0.2 && v < 0.38) continue;

    let p1 = bodyPt(t, v);
    let p2 = bodyPt(t + random(0.012, 0.035), v + random(-0.03, 0.03));
    let hiCol = random() < 0.45 ? "#fffdf2" : "#ffea9c";
    brush.set("glint", hiCol, random(0.75, 1.35) * cfg.lightBoost);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Crisp dorsal & ventral contour accents
  let dorsalContour = [];
  let ventralContour = [];
  for (let t = 0.01; t <= 0.91; t += 0.03) {
    let pd = bodyPt(t, -1.0);
    let pv = bodyPt(t, 1.0);
    dorsalContour.push([pd[0], pd[1], 0.95]);
    ventralContour.push([pv[0], pv[1], 0.95]);
  }
  brush.set("charcoal", "#140b05", 1.05);
  brush.spline(dorsalContour, 0.4);
  brush.set("2B", "#2b1b0e", 0.9);
  brush.spline(ventralContour, 0.4);
}

function drawMackerelFinsAndTail(bodyPt, spinePt, spineTan, cfg) {
  // 1. Spiny First Dorsal Fin (t = 0.28 .. 0.45, slightly folded along back)
  brush.noStroke();
  brush.wash("#5c3a1d", 175);
  brush.beginShape(0.2);
  for (let t = 0.28; t <= 0.46; t += 0.03) {
    let p = bodyPt(t, -0.96);
    brush.vertex(p[0], p[1]);
  }
  for (let t = 0.45; t >= 0.29; t -= 0.04) {
    let h = sin(((t - 0.28) / 0.18) * 180) * 0.42;
    let p = bodyPt(t + 0.02, -1.0 - h);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Spiny dorsal rays
  for (let i = 0; i < 11; i++) {
    let t = map(i, 0, 10, 0.285, 0.445);
    let h = sin((i / 10) * 170 + 10) * 0.42;
    let pBase = bodyPt(t, -0.95);
    let pTip = bodyPt(t + 0.028, -1.0 - h);
    brush.set("rotring", "#241409", 0.75);
    brush.line(pBase[0], pBase[1], pTip[0], pTip[1]);
    brush.set("glint", "#d9a252", 0.55);
    brush.line(pBase[0] - 0.8, pBase[1] - 0.8, pTip[0] - 0.8, pTip[1] - 0.8);
  }

  // 2. Second Dorsal Fin (t = 0.58 .. 0.69) & Anal Fin (t = 0.60 .. 0.71)
  const drawSmallFin = (t0, t1, sign, maxH) => {
    for (let i = 0; i <= 9; i++) {
      let u = i / 9;
      let t = lerp(t0, t1, u);
      let h = sin(u * 165 + 15) * maxH;
      let pBase = bodyPt(t, sign * 0.94);
      let pTip = bodyPt(t + 0.025, sign * (1.0 + h));
      brush.set("2B", "#3d2411", 0.75);
      brush.line(pBase[0], pBase[1], pTip[0], pTip[1]);
      if (i % 2 === 0) {
        brush.set("glint", "#e0b065", 0.5);
        brush.line(pBase[0], pBase[1], lerp(pBase[0], pTip[0], 0.75), lerp(pBase[1], pTip[1], 0.75));
      }
    }
  };
  drawSmallFin(0.58, 0.69, -1, 0.34);
  drawSmallFin(0.60, 0.71, 1, 0.30);

  // 3. Signature Mackerel Dorsal & Ventral Finlets (5 tiny tufts from t = 0.73 to 0.87)
  for (let i = 0; i < 5; i++) {
    let t = map(i, 0, 4, 0.73, 0.865);
    for (let sign of [-1, 1]) {
      let p0 = bodyPt(t, sign * 0.92);
      let p1 = bodyPt(t + 0.018, sign * 1.24);
      let p2 = bodyPt(t + 0.024, sign * 1.12);
      brush.set("rotring", "#241408", 0.65);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
      brush.line(p0[0], p0[1], p2[0], p2[1]);
      brush.set("glint", "#d9a252", 0.45);
      brush.line(p0[0], p0[1], lerp(p0[0], p1[0], 0.7), lerp(p0[1], p1[1], 0.7));
    }
  }

  // 4. Deeply Forked Caudal (Tail) Fin (t = 0.89 .. 1.0)
  let pPed = spinePt(0.90);
  let tan = spineTan(0.92);
  let nx = -tan[1], ny = tan[0];
  let tailLen = cfg.maxRadius * 1.38;
  let lobeSpread = cfg.maxRadius * 0.92;

  let pUpperTip = [
    pPed[0] + tan[0] * tailLen + nx * (-lobeSpread),
    pPed[1] + tan[1] * tailLen + ny * (-lobeSpread)
  ];
  let pLowerTip = [
    pPed[0] + tan[0] * (tailLen * 0.95) + nx * (lobeSpread * 0.96),
    pPed[1] + tan[1] * (tailLen * 0.95) + ny * (lobeSpread * 0.96)
  ];
  let pForkNotch = [
    pPed[0] + tan[0] * (tailLen * 0.36),
    pPed[1] + tan[1] * (tailLen * 0.36)
  ];

  let pBaseTop = bodyPt(0.90, -0.95);
  let pBaseBot = bodyPt(0.90, 0.95);

  // Tail shadow
  brush.noStroke();
  brush.wash("#332518", 95);
  brush.beginShape(0.15);
  brush.vertex(pBaseTop[0] + 10, pBaseTop[1] + 14);
  brush.vertex(pUpperTip[0] + 10, pUpperTip[1] + 14);
  brush.vertex(pForkNotch[0] + 10, pForkNotch[1] + 14);
  brush.vertex(pLowerTip[0] + 10, pLowerTip[1] + 14);
  brush.vertex(pBaseBot[0] + 10, pBaseBot[1] + 14);
  brush.endShape(CLOSE);

  // Tail smoky bronze base wash
  brush.wash("#593518", 215);
  brush.beginShape(0.12);
  brush.vertex(pBaseTop[0], pBaseTop[1]);
  brush.vertex(pUpperTip[0], pUpperTip[1]);
  brush.vertex(pForkNotch[0], pForkNotch[1]);
  brush.vertex(pLowerTip[0], pLowerTip[1]);
  brush.vertex(pBaseBot[0], pBaseBot[1]);
  brush.endShape(CLOSE);
  brush.noWash();

  // Radiating caudal fin rays (Upper & Lower Lobes)
  const drawLobeRays = (pTip, baseSign) => {
    for (let i = 0; i <= 14; i++) {
      let u = i / 14;
      let bx = lerp(pPed[0], baseSign < 0 ? pBaseTop[0] : pBaseBot[0], 1 - u * 0.7);
      let by = lerp(pPed[1], baseSign < 0 ? pBaseTop[1] : pBaseBot[1], 1 - u * 0.7);
      let tx = lerp(pTip[0], pForkNotch[0], pow(u, 1.15));
      let ty = lerp(pTip[1], pForkNotch[1], pow(u, 1.15));

      // Dark charred ray
      brush.set("rotring", i < 4 ? "#140b05" : "#361e0c", i < 3 ? 1.05 : 0.7);
      brush.line(bx, by, tx, ty);

      // Warm golden-bronze ray highlight
      if (i % 2 === 0) {
        brush.set("glint", "#d99841", 0.65);
        brush.line(bx, by, lerp(bx, tx, 0.72), lerp(by, ty, 0.72));
      }
    }
  };
  drawLobeRays(pUpperTip, -1);
  drawLobeRays(pLowerTip, 1);
}

function drawFlakySkinSplit(bodyPt) {
  // A realistic tear/split in the taut golden smoked skin revealing tender, flaky pinkish-ivory flesh
  const t0 = 0.42, t1 = 0.60;
  const vMid = 0.08, vHalf = 0.24;

  // Exposed smoked flesh base
  brush.noStroke();
  brush.wash("#b87b56", 235);
  brush.beginShape(0.35);
  for (let i = 0; i <= 8; i++) {
    let u = i / 8;
    let t = lerp(t0, t1, u);
    let v = vMid - sin(u * 180) * vHalf;
    let p = bodyPt(t, v);
    brush.vertex(p[0], p[1]);
  }
  for (let i = 8; i >= 0; i--) {
    let u = i / 8;
    let t = lerp(t0, t1, u);
    let v = vMid + sin(u * 180) * vHalf;
    let p = bodyPt(t, v);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);
  brush.noWash();

  // Flaky W-shaped myomere muscle segments inside the exposed flesh
  for (let i = 1; i < 11; i++) {
    let u = i / 11;
    let t = lerp(t0 + 0.015, t1 - 0.015, u);
    let span = sin(u * 180) * (vHalf * 0.88);
    let pTop = bodyPt(t + 0.01, vMid - span);
    let pCenter = bodyPt(t - 0.012, vMid);
    let pBot = bodyPt(t + 0.01, vMid + span);

    // Deep flake crevice
    brush.set("2B", "#6e3d20", 0.85);
    brush.line(pTop[0], pTop[1], pCenter[0], pCenter[1]);
    brush.line(pCenter[0], pCenter[1], pBot[0], pBot[1]);

    // Moist, tender salmon-ivory flake highlight
    brush.set("cpencil", "#f2d2b6", 1.05);
    brush.line(pTop[0] + 2.2, pTop[1] + 1.2, pCenter[0] + 2.2, pCenter[1] + 1.2);
    brush.line(pCenter[0] + 2.2, pCenter[1] + 1.2, pBot[0] + 2.2, pBot[1] + 1.2);

    brush.set("glint", "#fff2e3", 0.75);
    brush.line(
      lerp(pTop[0], pCenter[0], 0.3) + 1.5,
      lerp(pTop[1], pCenter[1], 0.3) + 1.0,
      lerp(pTop[0], pCenter[0], 0.8) + 1.5,
      lerp(pTop[1], pCenter[1], 0.8) + 1.0
    );
  }

  // Curled, crispy golden-brown skin edges around the split
  let topLip = [], botLip = [], topHi = [];
  for (let i = 0; i <= 10; i++) {
    let u = i / 10;
    let t = lerp(t0, t1, u);
    let span = sin(u * 180) * vHalf;
    let pt = bodyPt(t, vMid - span);
    let pb = bodyPt(t, vMid + span);
    topLip.push([pt[0], pt[1], 1.0]);
    botLip.push([pb[0], pb[1], 1.0]);
    topHi.push([pt[0] - 1.5, pt[1] - 1.5, 1.1]);
  }
  brush.set("charcoal", "#2e1608", 1.1);
  brush.spline(topLip, 0.45);
  brush.spline(botLip, 0.45);
  brush.set("glint", "#ffdf85", 1.05);
  brush.spline(topHi, 0.45);
}

function drawMackerelHeadAndEye(bodyPt, cfg) {
  // 1. Metallic Golden-Copper Gill Cover (Operculum & Preoperculum)
  // Posterior opercular margin at t ≈ 0.205, preopercle at t ≈ 0.145
  let opRim = [];
  let opShadow = [];
  let preOpRim = [];
  for (let s = 0; s <= 8; s++) {
    let v = map(s, 0, 8, -0.78, 0.88);
    let curveT = 0.195 + sin((s / 8) * 180) * 0.025;
    let p = bodyPt(curveT, v);
    opRim.push([p[0], p[1], 1.0]);
    opShadow.push([p[0] + 2.2, p[1] + 1.6, 1.1]);

    let preT = 0.135 + sin((s / 8) * 180) * 0.018;
    let pp = bodyPt(preT, v * 0.85);
    preOpRim.push([pp[0], pp[1], 0.9]);
  }

  // Metallic copper-gold plate sheen on the gill cover
  for (let i = 0; i < 28; i++) {
    let tA = random(0.11, 0.18);
    let tB = tA + random(0.02, 0.04);
    let v = random(-0.45, 0.55);
    let pA = bodyPt(tA, v);
    let pB = bodyPt(tB, v + random(-0.06, 0.06));
    let plateCol = (v < 0.15)
      ? random(["#f7cb68", "#fff0b8", "#d9922b"])
      : random(["#e8c48e", "#f7e3be", "#bf8f4e"]);
    brush.set("glint", plateCol, random(0.85, 1.35));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Dark gill slit shadow & bright golden opercular rim
  brush.set("charcoal", "#170b04", 1.35);
  brush.spline(opShadow, 0.45);
  brush.set("glint", "#ffea9e", 1.15);
  brush.spline(opRim, 0.45);

  brush.set("2B", "#3d220d", 0.85);
  brush.spline(preOpRim, 0.45);
  brush.set("glint", "#f5c867", 0.8);
  brush.spline(preOpRim.map(pt => [pt[0] - 1.2, pt[1] - 1.0, pt[2]]), 0.45);

  // 2. Jaws, Snout & Mouth Line (t = 0.0 .. 0.095)
  let pSnout = bodyPt(0.0, 0.05);
  let pMouthMid = bodyPt(0.048, 0.24);
  let pJawCorner = bodyPt(0.092, 0.36);
  let pMaxilla = bodyPt(0.088, 0.18);

  brush.set("charcoal", "#140a04", 1.25);
  brush.spline([[pSnout[0], pSnout[1], 1.1], [pMouthMid[0], pMouthMid[1], 1.2], [pJawCorner[0], pJawCorner[1], 0.8]], 0.4);
  brush.set("2B", "#381e0b", 0.9);
  brush.line(pMouthMid[0], pMouthMid[1], pMaxilla[0], pMaxilla[1]);
  brush.set("glint", "#f7ce72", 0.95);
  brush.line(pSnout[0], pSnout[1] - 1.5, pMaxilla[0], pMaxilla[1] - 1.5);

  // 3. The Sunken Glassy Smoked Eye (at t = 0.082, v = -0.18)
  let pEye = bodyPt(0.082, -0.18);
  let eyeR = cfg.maxRadius * 0.205;

  // Dark smoked orbital socket
  brush.noStroke();
  brush.wash("#1f1108", 240);
  brush.circle(pEye[0], pEye[1], eyeR * 1.18, 0.12);

  // Golden-amber smoked iris
  brush.wash("#b8751e", 235);
  brush.circle(pEye[0], pEye[1], eyeR * 0.88, 0.08);
  brush.wash("#ebae44", 190);
  brush.circle(pEye[0] - 1.2, pEye[1] + 1.0, eyeR * 0.72, 0.08);

  // Deep glossy obsidian pupil
  brush.wash("#0d0907", 250);
  brush.circle(pEye[0], pEye[1], eyeR * 0.50, 0.06);
  brush.noWash();

  // Iris detail & charred orbital ring
  brush.set("charcoal", "#120904", 1.2);
  brush.circle(pEye[0], pEye[1], eyeR * 1.05, 0.1);
  brush.set("glint", "#ffd970", 0.85);
  brush.arc(pEye[0], pEye[1], eyeR * 0.82, 20, 175);

  // Razor-sharp wet specular catchlights on the cornea
  brush.set("glint", "#fffef7", 1.55);
  brush.line(pEye[0] - eyeR * 0.36, pEye[1] - eyeR * 0.28, pEye[0] - eyeR * 0.05, pEye[1] - eyeR * 0.36);
  brush.set("glint", "#fff6d1", 1.0);
  brush.line(pEye[0] + eyeR * 0.18, pEye[1] + eyeR * 0.26, pEye[0] + eyeR * 0.34, pEye[1] + eyeR * 0.14);
}

function drawPectoralFin(bodyPt) {
  // Translucent smoked amber pectoral fin rooted just behind the gill cover (t = 0.215, v = 0.18)
  let pRootTop = bodyPt(0.212, 0.08);
  let pRootBot = bodyPt(0.225, 0.34);
  let pTip = bodyPt(0.355, 0.26);
  let pTrail = bodyPt(0.315, 0.48);

  // Cast shadow of the pectoral fin onto the golden fish flank
  brush.noStroke();
  brush.wash("#381e0a", 130);
  brush.beginShape(0.2);
  brush.vertex(pRootBot[0] + 3, pRootBot[1] + 5);
  brush.vertex(pTip[0] + 5, pTip[1] + 7);
  brush.vertex(pTrail[0] + 4, pTrail[1] + 6);
  brush.endShape(CLOSE);

  // Translucent smoked bronze fin membrane
  brush.wash("#6e4119", 170);
  brush.beginShape(0.2);
  brush.vertex(pRootTop[0], pRootTop[1]);
  brush.vertex(pTip[0], pTip[1]);
  brush.vertex(pTrail[0], pTrail[1]);
  brush.vertex(pRootBot[0], pRootBot[1]);
  brush.endShape(CLOSE);
  brush.noWash();

  // Individual pectoral fin rays
  for (let i = 0; i <= 9; i++) {
    let u = i / 9;
    let rx = lerp(pRootTop[0], pRootBot[0], u);
    let ry = lerp(pRootTop[1], pRootBot[1], u);
    let tx = lerp(pTip[0], pTrail[0], pow(u, 0.9));
    let ty = lerp(pTip[1], pTrail[1], pow(u, 0.9));

    brush.set("rotring", i === 0 ? "#1f1006" : "#3d220d", i === 0 ? 1.0 : 0.65);
    brush.line(rx, ry, tx, ty);
    if (i < 6) {
      brush.set("glint", "#f2be5c", 0.65);
      brush.line(rx, ry, lerp(rx, tx, 0.75), lerp(ry, ty, 0.75));
    }
  }
}

