// ============================================================================
// 3D VECTOR & CAMERA UTILITIES
// ============================================================================

function v3(x, y, z) { return [x, y, z]; }
function vAdd(a, b) { return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]; }
function vSub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function vScale(a, s) { return [a[0] * s, a[1] * s, a[2] * s]; }
function vLerp(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function vDot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function vCross(a, b) {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
}
function vLen(a) { return Math.hypot(a[0], a[1], a[2]); }
function vDist(a, b) { return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]); }
function vNorm(a) {
  let l = vLen(a);
  return l > 1e-8 ? [a[0] / l, a[1] / l, a[2] / l] : [0, 1, 0];
}

function setupCameraAndLights() {
  // Off-centre gallery vantage point looking slightly down at the floor
  camPos = [-68, 310, 865];
  camTarget = [12, 126, -25];
  focalLength = 1330;
  screenCX = 588;
  screenCY = 542;

  camForward = vNorm(vSub(camTarget, camPos));
  let worldUp = vNorm([-0.016, 1.0, 0.0]); // subtle natural gallery perspective tilt
  camRight = vNorm(vCross(camForward, worldUp));
  camUp = vNorm(vCross(camRight, camForward));

  // Primary gallery key spotlight (upper-right-front) & secondary fill track light
  light1 = vNorm([0.74, 0.80, 0.44]);
  light2 = vNorm([0.44, 0.88, 0.18]);
}

function project3D(p) {
  let rel = vSub(p, camPos);
  let x = vDot(rel, camRight);
  let y = vDot(rel, camUp);
  let z = vDot(rel, camForward);
  if (z < 10) z = 10;
  let scale = focalLength / z;
  return [screenCX + x * scale, screenCY - y * scale, z];
}

function projectShadowOnFloor(p, lightVec) {
  if (p[1] <= 0) return [p[0], 0, p[2]];
  let t = p[1] / lightVec[1];
  return [p[0] - lightVec[0] * t, 0, p[2] - lightVec[2] * t];
}

// Strict coplanar point helper: P(s, t) = A + s*(B - A) + t*(C - A)
function coplanarPt(A, B, C, s, t) {
  return [
    A[0] + s * (B[0] - A[0]) + t * (C[0] - A[0]),
    A[1] + s * (B[1] - A[1]) + t * (C[1] - A[1]),
    A[2] + s * (B[2] - A[2]) + t * (C[2] - A[2])
  ];
}

// Compute t so that P(s, t) lies strictly on the floor Y = 0
function floorT(A, B, C, s) {
  let yAB = A[1] + s * (B[1] - A[1]);
  let dyAC = C[1] - A[1];
  if (Math.abs(dyAC) < 1e-6) return 1.0;
  return -yAB / dyAC;
}

