function buildSculptureGeometry() {
  plates = [];
  hinges = [];

  // Primary Spine Anchors
  let S_front = [68, 214, 30];
  let S_rear  = [284, 198, -42];
  let B_midRef = [166, 118, 42];

  // Plate 1: Central Dorsal Spine (Bare Brushed Aluminium, with circular relief port)
  let B_front = coplanarPt(S_front, S_rear, B_midRef, -0.06, 0.96);
  let B_mid   = coplanarPt(S_front, S_rear, B_midRef, 0.46, 0.96);
  let B_rear  = coplanarPt(S_front, S_rear, B_midRef, 0.94, 0.92);

  let p1 = createPlate({
    id: "P1_spine",
    A: S_front, B: S_rear, C: B_midRef,
    stPoly: [
      [0.0, 0.0],
      [0.96, 0.0],
      [1.01, 0.09],
      [0.94, 0.92],
      [0.46, 0.96],
      [-0.06, 0.96],
      [-0.09, 0.14]
    ],
    mat: "bare_alu",
    thickness: 8.0,
    grainAngle: 4,
    holes: [{ u: 142, v: 46, r: 22.5 }] // Milled circular aperture
  });

  // Plate 2: Thoracic Belly Fold (Flat Cadmium Orange)
  let K_frontRef = [74, 64, 146];
  let K_front = coplanarPt(B_front, B_mid, K_frontRef, 0.0, 1.0);
  let K_mid   = coplanarPt(B_front, B_mid, K_frontRef, 0.92, 0.96);

  let p2 = createPlate({
    id: "P2_thorax",
    A: B_front, B: B_mid, C: K_frontRef,
    stPoly: [
      [0.0, 0.0],
      [1.0, 0.0],
      [1.03, 0.16],
      [0.92, 0.96],
      [0.0, 1.0],
      [-0.06, 0.22]
    ],
    mat: "cadmium_orange",
    thickness: 7.5,
    grainAngle: 12,
    holes: []
  });

  // Plate 3: Front Stride Leg (Bare Brushed Aluminium, resting flat on floor Y = 0)
  let G_frontRef = [62, 0, 184];
  let tG0 = floorT(K_front, K_mid, G_frontRef, 0.02);
  let tG1 = floorT(K_front, K_mid, G_frontRef, 0.88);
  let G_frontA = coplanarPt(K_front, K_mid, G_frontRef, 0.02, tG0);
  let G_frontB = coplanarPt(K_front, K_mid, G_frontRef, 0.88, tG1);

  let p3 = createPlate({
    id: "P3_front_leg",
    A: K_front, B: K_mid, C: G_frontRef,
    stPoly: [
      [0.0, 0.0],
      [1.0, 0.0],
      [1.04, 0.34],
      [0.91, 0.42], // precision side relief notch
      [0.94, 0.78],
      [0.88, tG1],  // resting flat on Y = 0
      [0.02, tG0]   // resting flat on Y = 0
    ],
    mat: "bare_alu",
    thickness: 8.0,
    grainAngle: -6,
    holes: [{ u: 54, v: 42, r: 12.5 }]
  });

  // Plate 4: Fore-Foot Stabilizer Pad (Egg-Yolk Yellow, resting on floor Y = 0)
  let G_clawRef = [-6, 0, 214];
  let tClaw0 = floorT(K_front, G_frontA, G_clawRef, 1.0);
  let tClaw1 = floorT(K_front, G_frontA, G_clawRef, 0.72);

  let p4 = createPlate({
    id: "P4_fore_foot",
    A: K_front, B: G_frontA, C: G_clawRef,
    stPoly: [
      [0.14, 0.0],
      [1.0, 0.0],               // G_frontA (Y = 0)
      [0.72, tClaw1],           // G_claw (Y = 0)
      [0.46, tClaw1 * 0.82],
      [0.08, 0.26]
    ],
    mat: "egg_yolk",
    thickness: 7.0,
    grainAngle: 18,
    holes: []
  });

  // Plate 5: Upper Dorsal Crest Wing (Egg-Yolk Yellow)
  let W_crestRef = [106, 318, -32];
  let W_outerA = coplanarPt(S_front, S_rear, W_crestRef, 0.04, 0.95);
  let W_outerB = coplanarPt(S_front, S_rear, W_crestRef, 0.74, 0.98);

  let p5 = createPlate({
    id: "P5_crest_wing",
    A: S_front, B: S_rear, C: W_crestRef,
    stPoly: [
      [0.05, 0.0],
      [0.85, 0.0],
      [0.88, 0.18],
      [0.74, 0.98],
      [0.04, 0.95],
      [-0.02, 0.25]
    ],
    mat: "egg_yolk",
    thickness: 7.5,
    grainAngle: -8,
    holes: []
  });

  // Plate 6: Outer Wing Counter-Flap (Bare Brushed Aluminium)
  let W_tipRef = [138, 258, -142];
  let p6 = createPlate({
    id: "P6_wing_flap",
    A: W_outerA, B: W_outerB, C: W_tipRef,
    stPoly: [
      [0.04, 0.0],
      [0.96, 0.0],
      [0.88, 0.92],
      [0.72, 1.0],
      [0.08, 0.94],
      [-0.02, 0.22]
    ],
    mat: "bare_alu",
    thickness: 7.0,
    grainAngle: 5,
    holes: []
  });

  // Plate 7: Anterior Neck / Cranial Beak Plane (Bare Brushed Aluminium)
  let H_neckRef = [-42, 190, 88];
  let H_lowA = coplanarPt(S_front, B_front, H_neckRef, 0.96, 0.12);
  let H_lowB = coplanarPt(S_front, B_front, H_neckRef, 0.68, 0.92);

  let p7 = createPlate({
    id: "P7_neck_beak",
    A: S_front, B: B_front, C: H_neckRef,
    stPoly: [
      [0.0, 0.0],
      [0.96, 0.0],
      [0.96, 0.12],
      [0.68, 0.92],
      [0.44, 1.02],
      [0.08, 0.95],
