    ],
    mat: "bare_alu",
    thickness: 7.5,
    grainAngle: -14,
    holes: []
  });

  // Plate 8: Lower Mandible / Chin Fold (Flat Cadmium Orange)
  let H_jawRef = [28, 82, 152];
  let p8 = createPlate({
    id: "P8_mandible",
    A: H_lowA, B: H_lowB, C: H_jawRef,
    stPoly: [
      [0.0, 0.0],
      [0.94, 0.0],
      [0.82, 0.86],
      [0.58, 0.98],
      [0.06, 0.92]
    ],
    mat: "cadmium_orange",
    thickness: 7.0,
    grainAngle: 8,
    holes: []
  });

