function createPlate(cfg) {
  let A = cfg.A, B = cfg.B, C = cfg.C;
  let uVec = vSub(B, A);
  let uHat = vNorm(uVec);
  let wVec = vSub(C, A);
  let uC = vDot(wVec, uHat);
  let vVec = vSub(wVec, vScale(uHat, uC));
  let vHat = vNorm(vVec);
  let nHat = vNorm(vCross(uHat, vHat));

  // Ensure normal faces generally toward camera for consistent front/back lighting
  let centroidApprox = coplanarPt(A, B, C, 0.45, 0.45);
  let toCam = vSub(camPos, centroidApprox);
  if (vDot(nHat, toCam) < 0) {
    nHat = vScale(nHat, -1);
  }

  let verts3D = cfg.stPoly.map(([s, t]) => coplanarPt(A, B, C, s, t));
  let vertsUV = verts3D.map(p => {
    let d = vSub(p, A);
    return [vDot(d, uHat), vDot(d, vHat)];
  });

  // Compute bounding box in UV space
  let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity;
  for (let uv of vertsUV) {
    if (uv[0] < minU) minU = uv[0];
    if (uv[0] > maxU) maxU = uv[0];
    if (uv[1] < minV) minV = uv[1];
    if (uv[1] > maxV) maxV = uv[1];
  }

  // Rotated grain axes in the plate's plane
  let ang = (cfg.grainAngle || 0) * Math.PI / 180;
  let gU = vAdd(vScale(uHat, Math.cos(ang)), vScale(vHat, Math.sin(ang)));
  let gV = vAdd(vScale(uHat, -Math.sin(ang)), vScale(vHat, Math.cos(ang)));

  return {
    id: cfg.id,
    A, B, C,
    uHat, vHat, nHat,
    gU, gV,
    verts3D,
    vertsUV,
    minU, maxU, minV, maxV,
    mat: cfg.mat,
    thickness: cfg.thickness || 7.5,
    holes: cfg.holes || [],
    planeD: vDot(nHat, A)
  };
}

function createHinge(pA, pB, plateA, plateB, knuckles, tStart, tEnd, drawAfterIdx) {
  return {
    A: vLerp(pA, pB, tStart),
    B: vLerp(pA, pB, tEnd),
    rawA: pA,
    rawB: pB,
    plateA,
    plateB,
    knuckles: knuckles || 5,
    drawAfterIdx
  };
}

// ============================================================================
// 2D & 3D GEOMETRY INTERSECTION HELPERS
// ============================================================================

function pointInPoly2D(pt, poly) {
  let x = pt[0], y = pt[1];
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function pointOnPlateUV(u, v, plate) {
  if (u < plate.minU || u > plate.maxU || v < plate.minV || v > plate.maxV) return false;
  if (!pointInPoly2D([u, v], plate.vertsUV)) return false;
  for (let h of plate.holes) {
    if (Math.hypot(u - h.u, v - h.v) < h.r) return false;
  }
  return true;
}

function distToPolyEdge2D(pt, poly) {
  let minD = Infinity;
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    let dx = b[0] - a[0], dy = b[1] - a[1];
    let l2 = dx * dx + dy * dy;
    let t = l2 > 1e-6 ? ((pt[0] - a[0]) * dx + (pt[1] - a[1]) * dy) / l2 : 0;
    t = Math.max(0, Math.min(1, t));
    let d = Math.hypot(pt[0] - (a[0] + t * dx), pt[1] - (a[1] + t * dy));
    if (d < minD) minD = d;
  }
  return minD;
}

// Test if a 3D ray from orig in dir hits any plate (excluding ignorePlate)
function isRayShadowed(orig, dir, ignorePlate) {
  for (let pl of plates) {
    if (pl === ignorePlate) continue;
    let denom = vDot(pl.nHat, dir);
    if (Math.abs(denom) < 1e-5) continue;
    let t = (pl.planeD - vDot(pl.nHat, orig)) / denom;
    if (t <= 2.5) continue;
    let hit = vAdd(orig, vScale(dir, t));
    let rel = vSub(hit, pl.A);
    let u = vDot(rel, pl.uHat);
    let v = vDot(rel, pl.vHat);
    if (pointOnPlateUV(u, v, pl)) return true;
  }
  return false;
}

function drawBrushPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (Math.hypot(pts[i][0] - clean[clean.length - 1][0], pts[i][1] - clean[clean.length - 1][1]) > 0.6) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3 && Math.hypot(clean[0][0] - clean[clean.length - 1][0], clean[0][1] - clean[clean.length - 1][1]) < 0.6) {
    clean.pop();
  }
  if (clean.length < 3) return;

  brush.beginShape(curvature);
  for (let p of clean) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

