  // Crisp shadow-gap line and lower concrete curb lip
  brush.set("2B", "#3E3A34", 0.55);
  brush.line(gapTopL[0], gapTopL[1], gapTopR[0], gapTopR[1]);

  brush.set("HB", "#7A7368", 0.42);
  brush.line(wallLeft[0], wallLeft[1], wallRight[0], wallRight[1]);

  brush.set("2H", "#F2EEE6", 0.38);
  brush.line(wallLeft[0], wallLeft[1] + 1.5, wallRight[0], wallRight[1] + 1.5);
}

