// ============================================================================
// 3. OVERLAPPING RAY-CAST CHARCOAL & GRAPHITE SHADOWS ON CONCRETE FLOOR
// ============================================================================

function renderFloorCastShadows() {
  brush.noStroke();

  // Secondary softer gallery light cast shadows (penumbra layer)
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.52, 0.28);
  for (let pl of plates) {
    let shPts2 = pl.verts3D.map(v => project3D(projectShadowOnFloor(v, light2)));
    brush.fill("#857D70", 52);
    drawBrushPoly(shPts2, 0.04);
  }

  // Primary directional spotlight cast shadows (umbra layer)
  brush.fillBleed(0.09, "out");
  brush.fillTexture(0.58, 0.35);
  for (let pl of plates) {
    let shPts1 = pl.verts3D.map(v => project3D(projectShadowOnFloor(v, light1)));
    brush.fill("#4E4941", 82);
    drawBrushPoly(shPts1, 0.02);
  }

  // Warm pigment color-bounce glazes on the concrete floor near painted plates
  let warmZones = [
    { center: [95, 0, 135], rx: 75, rz: 45, col: "#B85E32", alpha: 38 },  // under orange thorax
    { center: [285, 0, 38], rx: 65, rz: 42, col: "#B85E32", alpha: 36 },  // near orange rear leg
    { center: [22, 0, 196], rx: 52, rz: 36, col: "#C8962E", alpha: 42 }   // near yellow fore-foot
  ];
  brush.fillBleed(0.22, "out");
  for (let wz of warmZones) {
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let p3 = [wz.center[0] + Math.cos(a * Math.PI / 180) * wz.rx, 0, wz.center[2] + Math.sin(a * Math.PI / 180) * wz.rz];
      pts.push(project3D(p3));
    }
    brush.fill(wz.col, wz.alpha);
    drawBrushPoly(pts, 0.25);
  }

  // Bright oval light patches inside the shadow cast through the milled circular holes!
  for (let pl of plates) {
    for (let h of pl.holes) {
      let holePts1 = [];
      for (let a = 0; a < 360; a += 20) {
        let rad = a * Math.PI / 180;
        let u = h.u + Math.cos(rad) * h.r;
        let v = h.v + Math.sin(rad) * h.r;
        let p3 = vAdd(pl.A, vAdd(vScale(pl.uHat, u), vScale(pl.vHat, v)));
        holePts1.push(project3D(projectShadowOnFloor(p3, light1)));
      }
      brush.fillBleed(0.06, "out");
      brush.fill("#C8C0B2", 145);
      drawBrushPoly(holePts1, 0.2);
    }
  }
  brush.noFill();

  // Dense charcoal and graphite hatching across the floor shadow field
  // Ray-test exact points on the floor Y = 0 against light1 and light2!
  for (let z3 = -210; z3 <= 245; z3 += 3.2) {
    let inRun = false;
    let runStart = null;
    let runLevel = 0;

    for (let x3 = -260; x3 <= 385; x3 += 4.5) {
      let pt = [x3, 0.1, z3];
      let s1 = isRayShadowed(pt, light1, null) ? 1 : 0;
      let s2 = isRayShadowed(pt, light2, null) ? 1 : 0;
      let lvl = s1 * 2 + s2; // 0 = lit, 1 = L2 penumbra, 2 = L1 umbra, 3 = double-shadow core

      if (lvl > 0 && !inRun) {
        inRun = true;
        runStart = pt;
        runLevel = lvl;
      } else if (inRun && (lvl !== runLevel || x3 >= 380)) {
        let runEnd = pt;
        drawShadowFloorSpan(runStart, runEnd, runLevel, z3);
        if (lvl > 0) {
          runStart = pt;
          runLevel = lvl;
        } else {
          inRun = false;
        }
      }
    }
  }
}

function drawShadowFloorSpan(pStart3, pEnd3, level, z3) {
  let sA = project3D(pStart3);
  let sB = project3D(pEnd3);
  let len = Math.hypot(sB[0] - sA[0], sB[1] - sA[1]);
  if (len < 3) return;

  let wScale = map(z3, -210, 245, 0.75, 1.25);

  if (level === 1) {
    // Soft secondary shadow penumbra
    brush.set("2B", "#787064", 0.38 * wScale);
    brush.line(sA[0], sA[1], sB[0], sB[1]);
  } else if (level === 2) {
    // Primary spotlight umbra
    brush.set("charcoal_soft", "#3E3A34", 0.62 * wScale);
    brush.line(sA[0], sA[1], sB[0], sB[1]);
    if (random() < 0.55) {
      brush.set("2B", "#2F2B26", 0.36 * wScale);
      brush.line(sA[0] + random(-2, 2), sA[1] + random(-1, 1), sB[0] + random(-2, 2), sB[1] + random(-1, 1));
    }
  } else if (level >= 3) {
    // Deep overlapping shadow core (umbra + penumbra intersection)
    brush.set("charcoal_soft", "#26231F", 0.78 * wScale);
    brush.line(sA[0], sA[1], sB[0], sB[1]);
    brush.set("2B", "#1A1815", 0.44 * wScale);
    brush.line(sA[0], sA[1] + 0.8, sB[0], sB[1] - 0.8);
  }
}

// ============================================================================
// 4. PITTED CONCRETE AGGREGATE PORES & CONTACT OCCLUSION
// ============================================================================

function renderContactOcclusionAndFloorPits() {
  // Pitted concrete texture: aggregate pores, micro-cracks, and grit across Y = 0
  for (let i = 0; i < 950; i++) {
    let z3 = random(-310, 460);
    let x3 = random(-500, 580);
    let sPt = project3D([x3, 0, z3]);
    if (sPt[1] < 458 || sPt[1] > 1192 || sPt[0] < 8 || sPt[0] > 1192) continue;

    let persp = map(z3, -310, 460, 0.35, 1.45);
    let shadowed = isRayShadowed([x3, 0.2, z3], light1, null);

    if (random() < 0.68) {
      // Tiny concrete pore (dark top lip + pale bottom rim when in light)
      let pitW = random(1.2, 4.2) * persp;
      let darkCol = shadowed ? "#1D1A17" : (random() < 0.5 ? "#524C43" : "#6B6359");
      brush.set("2B", darkCol, 0.36 * persp);
      brush.line(sPt[0], sPt[1], sPt[0] + pitW, sPt[1] + random(-0.5, 0.5));

      if (!shadowed && random() < 0.65) {
        brush.set("2H", "#E5DFD2", 0.28 * persp);
        brush.line(sPt[0] + 0.3, sPt[1] + 1.1 * persp, sPt[0] + pitW, sPt[1] + 1.1 * persp);
      }
    } else {
      // Fine charcoal spray / aggregate cluster
      brush.set("concrete_pit", shadowed ? "#2A2622" : "#7E7568", 0.48 * persp);
      brush.line(sPt[0], sPt[1], sPt[0] + 3.5 * persp, sPt[1] + 0.8 * persp);
    }
  }

  // Razor-sharp contact occlusion where the 4 resting plate edges meet Y = 0
  for (let pl of plates) {
    let n = pl.verts3D.length;
    for (let i = 0; i < n; i++) {
      let a = pl.verts3D[i];
      let b = pl.verts3D[(i + 1) % n];
      if (Math.abs(a[1]) < 1.5 && Math.abs(b[1]) < 1.5) {
        let pA = project3D(a);
        let pB = project3D(b);

        // Soft charcoal contact halo on the floor
        brush.set("charcoal_soft", "#221F1B", 1.05);
        brush.line(pA[0], pA[1] + 1.5, pB[0], pB[1] + 1.5);

        // Crisp dark graphite contact crease right under the metal edge
        brush.set("2B", "#141210", 0.65);
        brush.line(pA[0], pA[1] + 0.6, pB[0], pB[1] + 0.6);
      }
    }
  }
}

// ============================================================================
// 5. RENDERING THE 15 INTERLOCKING PLATES & 14 MECHANICAL HINGES
// ============================================================================

function renderSculpture() {
  for (let idx = 0; idx < plates.length; idx++) {
    let pl = plates[idx];
    renderSinglePlate(pl);

    // Draw any hinges scheduled right after this plate layer
    for (let h of hinges) {
      if (h.drawAfterIdx === idx + 1) {
        renderMechanicalHinge(h);
      }
    }
  }
}

function renderSinglePlate(pl) {
  let screenPoly = pl.verts3D.map(v => {
    let p = project3D(v);
    return [p[0], p[1]];
  });

  // Step A: Opaque Base Wash & Broad Tonal Fill
  let baseColor = getPlateBaseColor(pl);
  brush.noStroke();
  brush.wash(baseColor, 245);
  drawBrushPoly(screenPoly, 0);
  brush.noWash();

  // Repaint hole interior if a hole looks through to floor or background plate
  for (let h of pl.holes) {
    renderPlateHoleInterior(pl, h);
  }

  // Step B: High-Resolution Anisotropic Brushed Metal or Matte Pigment Scanlines
  renderPlateSurfaceGrain(pl);

  // Step C: 3D Extruded Plate Thickness Rim & Hole Cylinder Thickness
  renderPlateThicknessAndHoleRim(pl);

  // Step D: Crisp Sheared Edge Burrs & Specular Catch-Lights
  renderPlateEdgeBurrs(pl);
}

function getPlateBaseColor(pl) {
  let ndl = Math.max(0, vDot(pl.nHat, light1));
  if (pl.mat === "cadmium_orange") {
    return ndl > 0.35 ? "#C45026" : "#963918";
  } else if (pl.mat === "egg_yolk") {
    return ndl > 0.35 ? "#D49826" : "#A87419";
  } else {
    return ndl > 0.45 ? "#B4B6B0" : (ndl > 0.2 ? "#949690" : "#767771");
  }
}

function renderPlateHoleInterior(pl, hole) {
  let holePts = [];
  let backPts = [];
  let tVec = vScale(pl.nHat, -pl.thickness);

  for (let a = 0; a < 360; a += 18) {
    let rad = a * Math.PI / 180;
    let u = hole.u + Math.cos(rad) * hole.r;
    let v = hole.v + Math.sin(rad) * hole.r;
    let pFront = vAdd(pl.A, vAdd(vScale(pl.uHat, u), vScale(pl.vHat, v)));
    let pBack = vAdd(pFront, tVec);
    let sF = project3D(pFront);
    let sB = project3D(pBack);
    holePts.push([sF[0], sF[1]]);
    backPts.push([sB[0], sB[1]]);
  }

  // Dark shadowed interior visible through the aperture
  brush.noStroke();
  brush.wash("#58534A", 235);
  drawBrushPoly(holePts, 0.15);
  brush.noWash();

  // Subtle hatching inside aperture
  brush.hatchStyle("2B", "#3A3630", 0.38);
  brush.hatch(3.5, 35, { rand: 0.04 });
  drawBrushPoly(holePts, 0.1);
  brush.noHatch();
}

function renderPlateSurfaceGrain(pl) {
  // Project bounding span in UV to determine optimal scanline spacing
  let diag3D = Math.hypot(pl.maxU - pl.minU, pl.maxV - pl.minV);
  let stepV = pl.mat === "bare_alu" ? 2.1 : 2.5;
  let stepU = 7.5;

  let plateSeed = pl.id.charCodeAt(1) * 37 + pl.id.charCodeAt(2) * 13;

  for (let v = pl.minV + 1.0; v <= pl.maxV - 1.0; v += stepV) {
    // 1D brushed-metal streak variation across v
    let streakNoise = noise(plateSeed + v * 0.28) * 0.65 + noise(plateSeed * 2 + v * 1.15) * 0.35;

    let segPts = [];
    let segColor = null;
    let segBrush = "metal_grain";
    let segWeight = 0.38;

    for (let u = pl.minU + 1.0; u <= pl.maxU - 1.0; u += stepU) {
      if (!pointOnPlateUV(u, v, pl)) {
        flushSurfaceSegment(segPts, segBrush, segColor, segWeight);
        segPts = [];
        continue;
      }

      let p3 = vAdd(pl.A, vAdd(vScale(pl.uHat, u), vScale(pl.vHat, v)));
      let sPt = project3D(p3);

      // Compute local hyperreal shading (anisotropic Ward specular + ray-cast shadows + radiosity)
      let shade = evaluatePlateSurfacePoint(pl, p3, u, v, streakNoise);

      if (segPts.length === 0) {
        segColor = shade.color;
        segBrush = shade.brush;
        segWeight = shade.weight;
        segPts.push([sPt[0], sPt[1]]);
      } else if (shade.color === segColor && segPts.length < 5) {
        segPts.push([sPt[0], sPt[1]]);
      } else {
        segPts.push([sPt[0], sPt[1]]);
        flushSurfaceSegment(segPts, segBrush, segColor, segWeight);
        segPts = [[sPt[0], sPt[1]]];
        segColor = shade.color;
        segBrush = shade.brush;
        segWeight = shade.weight;
      }
    }
    flushSurfaceSegment(segPts, segBrush, segColor, segWeight);
  }

  // Secondary cross-grain or specular sheen accents
  if (pl.mat === "bare_alu") {
    renderAluminiumSpecularSweeps(pl, plateSeed);
  } else {
    renderPaintedPlateWeathering(pl, plateSeed);
  }
}

function flushSurfaceSegment(pts, bName, col, w) {
  if (!pts || pts.length < 2 || !col) return;
  brush.set(bName, col, w);
  let a = pts[0];
  let b = pts[pts.length - 1];
  brush.line(a[0], a[1], b[0], b[1]);
}

function evaluatePlateSurfacePoint(pl, p3, u, v, streakNoise) {
  let N = pl.nHat;
  let T = pl.gU;
  let B = pl.gV;
  let V = vNorm(vSub(camPos, p3));

  // Ray-cast self-shadowing from other plates
  let orig = vAdd(p3, vScale(N, 1.8));
  let shad1 = isRayShadowed(orig, light1, pl);
  let shad2 = isRayShadowed(orig, light2, pl);

  let ndl1 = Math.max(0, vDot(N, light1));
  let ndl2 = Math.max(0, vDot(N, light2));

  // Anisotropic Ward reflection along brushed grain T
  let H1 = vNorm(vAdd(light1, V));
  let tDotH = vDot(T, H1);
  let bDotH = vDot(B, H1);
  let nDotH = Math.max(0.001, vDot(N, H1));
  let anisoSpec = Math.exp(-((tDotH * tDotH) / 0.22 + (bDotH * bDotH) / 0.032) / (nDotH * nDotH));
  if (shad1) anisoSpec *= 0.08;

  // Color bounce from nearby orange/yellow plates
  let orangeBounce = 0;
  if (pl.mat === "bare_alu") {
    let dOrange1 = vDist(p3, [120, 95, 105]);
    let dOrange2 = vDist(p3, [275, 55, 50]);
    if (dOrange1 < 95 || dOrange2 < 85) orangeBounce = 1;
  }

  if (pl.mat === "bare_alu") {
    // Compute brushed aluminium luminance (0..1)
    let lum = 0.24 + (shad1 ? 0.04 : ndl1 * 0.42) + (shad2 ? 0.02 : ndl2 * 0.16);
    lum += anisoSpec * 0.48;
    lum += (streakNoise - 0.5) * 0.24;

    // Horizon / floor reflection modulation on vertical-ish metal plates
    let reflY = vSub( vScale(N, 2 * vDot(N, V)), V )[1];
    if (reflY < -0.12) lum -= 0.10; // reflecting dark concrete floor
    if (reflY > 0.20) lum += 0.08;  // reflecting bright gallery wall/ceiling

    if (orangeBounce && lum > 0.35 && lum < 0.68 && random() < 0.28) {
      return { color: "#B88462", brush: "metal_grain", weight: 0.38 };
    }

    if (lum > 0.88) return { color: "#F5F4EE", brush: "metal_grain", weight: 0.42 };
    if (lum > 0.76) return { color: "#E2E3DD", brush: "metal_grain", weight: 0.38 };
    if (lum > 0.64) return { color: "#CACBC5", brush: "metal_grain", weight: 0.38 };
    if (lum > 0.52) return { color: "#B0B2AC", brush: "metal_grain", weight: 0.38 };
    if (lum > 0.40) return { color: "#92948E", brush: "metal_grain", weight: 0.40 };
    if (lum > 0.29) return { color: "#757670", brush: "metal_grain", weight: 0.42 };
    return { color: "#585751", brush: "metal_grain", weight: 0.44 };
  }

  if (pl.mat === "cadmium_orange") {
    // Edge wear revealing raw aluminium near sheared perimeter
    let edgeDist = distToPolyEdge2D([u, v], pl.vertsUV);
    if (edgeDist < 2.2 && random() < 0.42) {
      return { color: "#D4D5CF", brush: "2H", weight: 0.32 };
    }

    let lum = 0.22 + (shad1 ? 0.0 : ndl1 * 0.52) + (shad2 ? 0.04 : ndl2 * 0.18) + (streakNoise - 0.5) * 0.12;
    if (lum > 0.72) return { color: "#DE6435", brush: "cpencil", weight: 0.45 };
    if (lum > 0.56) return { color: "#CA5226", brush: "cpencil", weight: 0.45 };
    if (lum > 0.42) return { color: "#B0421B", brush: "cpencil", weight: 0.46 };
    if (lum > 0.30) return { color: "#8E3314", brush: "cpencil", weight: 0.48 };
    return { color: "#6E250E", brush: "cpencil", weight: 0.50 };
  }

  // Egg-Yolk Yellow
  let edgeDist = distToPolyEdge2D([u, v], pl.vertsUV);
  if (edgeDist < 2.2 && random() < 0.42) {
    return { color: "#D8D9D3", brush: "2H", weight: 0.32 };
  }

  let lum = 0.24 + (shad1 ? 0.0 : ndl1 * 0.52) + (shad2 ? 0.04 : ndl2 * 0.18) + (streakNoise - 0.5) * 0.12;
  if (lum > 0.74) return { color: "#E8B23C", brush: "cpencil", weight: 0.45 };
  if (lum > 0.58) return { color: "#D69C28", brush: "cpencil", weight: 0.45 };
  if (lum > 0.44) return { color: "#BC831C", brush: "cpencil", weight: 0.46 };
  if (lum > 0.32) return { color: "#9A6814", brush: "cpencil", weight: 0.48 };
  return { color: "#784F0E", brush: "cpencil", weight: 0.50 };
}

function renderAluminiumSpecularSweeps(pl, seed) {
  // Fine micro-scratches and soft anisotropic highlight bands
  for (let i = 0; i < 38; i++) {
    let v = random(pl.minV + 4, pl.maxV - 4);
    let u1 = random(pl.minU + 4, pl.maxU - 28);
    let u2 = u1 + random(18, 65);
    if (!pointOnPlateUV(u1, v, pl) || !pointOnPlateUV(u2, v, pl)) continue;

    let pA = vAdd(pl.A, vAdd(vScale(pl.uHat, u1), vScale(pl.vHat, v)));
    let pB = vAdd(pl.A, vAdd(vScale(pl.uHat, u2), vScale(pl.vHat, v)));
    let shad = isRayShadowed(vAdd(pA, vScale(pl.nHat, 1.8)), light1, pl);

    let sA = project3D(pA);
    let sB = project3D(pB);

    if (!shad && random() < 0.65) {
      brush.set("burr_pen", "#F7F6F0", 0.24);
      brush.line(sA[0], sA[1], sB[0], sB[1]);
    } else {
      brush.set("2H", "#5E5E58", 0.26);
      brush.line(sA[0], sA[1], sB[0], sB[1]);
    }
  }
}

function renderPaintedPlateWeathering(pl, seed) {
  // Subtle matte surface cross-grain and faint handling marks on painted faces
  for (let i = 0; i < 24; i++) {
    let u = random(pl.minU + 6, pl.maxU - 6);
    let v = random(pl.minV + 6, pl.maxV - 6);
    let u2 = u + random(-18, 18);
    let v2 = v + random(-14, 14);
    if (!pointOnPlateUV(u, v, pl) || !pointOnPlateUV(u2, v2, pl)) continue;

    let pA = project3D(vAdd(pl.A, vAdd(vScale(pl.uHat, u), vScale(pl.vHat, v))));
    let pB = project3D(vAdd(pl.A, vAdd(vScale(pl.uHat, u2), vScale(pl.vHat, v2))));

    let col = pl.mat === "cadmium_orange"
      ? (random() < 0.5 ? "#E47346" : "#8A2E11")
      : (random() < 0.5 ? "#EDC052" : "#966412");
    brush.set("2H", col, 0.25);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }
}

function renderPlateThicknessAndHoleRim(pl) {
  let tVec = vScale(pl.nHat, -pl.thickness);
  let n = pl.verts3D.length;

  // Outer perimeter thickness walls (machined bare aluminium edges)
  for (let i = 0; i < n; i++) {
    let v1 = pl.verts3D[i];
    let v2 = pl.verts3D[(i + 1) % n];
    let v1b = vAdd(v1, tVec);
    let v2b = vAdd(v2, tVec);

    let edgeVec = vSub(v2, v1);
    let edgeNormal = vNorm(vCross(edgeVec, pl.nHat));
    let mid = vLerp(v1, v2, 0.5);
    let toCam = vNorm(vSub(camPos, mid));

    // Draw side wall if visible or if projected thickness is noticeable
    let s1 = project3D(v1);
    let s2 = project3D(v2);
    let s1b = project3D(v1b);
    let s2b = project3D(v2b);

    let distScreen = Math.hypot(s1[0] - s1b[0], s1[1] - s1b[1]);
    if (vDot(edgeNormal, toCam) > -0.15 && distScreen > 1.2) {
      let ndl = vDot(edgeNormal, light1);
      let rimCol = ndl > 0.35 ? "#E4E5DF" : (ndl > -0.1 ? "#A6A8A2" : "#62625C");

      brush.noStroke();
      brush.wash(rimCol, 240);
      drawBrushPoly([[s1[0], s1[1]], [s2[0], s2[1]], [s2b[0], s2b[1]], [s1b[0], s1b[1]]], 0);
      brush.noWash();

      // Back edge contour line
      brush.set("2B", "#3A3834", 0.34);
      brush.line(s1b[0], s1b[1], s2b[0], s2b[1]);
    }
  }

  // Inner cylindrical wall of milled circular apertures
  for (let h of pl.holes) {
    let steps = 24;
    for (let i = 0; i < steps; i++) {
      let a1 = (i / steps) * Math.PI * 2;
      let a2 = ((i + 1) / steps) * Math.PI * 2;
      let p1 = vAdd(pl.A, vAdd(vScale(pl.uHat, h.u + Math.cos(a1) * h.r), vScale(pl.vHat, h.v + Math.sin(a1) * h.r)));
      let p2 = vAdd(pl.A, vAdd(vScale(pl.uHat, h.u + Math.cos(a2) * h.r), vScale(pl.vHat, h.v + Math.sin(a2) * h.r)));
      let p1b = vAdd(p1, tVec);
      let p2b = vAdd(p2, tVec);

      // Inward normal of the hole cylinder
      let inNorm = vNorm(vAdd(vScale(pl.uHat, -Math.cos(a1)), vScale(pl.vHat, -Math.sin(a1))));
      let toCam = vNorm(vSub(camPos, p1));
      if (vDot(inNorm, toCam) > -0.1) {
        let s1 = project3D(p1), s2 = project3D(p2);
        let s1b = project3D(p1b), s2b = project3D(p2b);
        let ndl = vDot(inNorm, light1);
        let col = ndl > 0.4 ? "#EFEFE9" : (ndl > 0.0 ? "#AEAFAA" : "#64645E");

        brush.noStroke();
        brush.wash(col, 240);
        drawBrushPoly([[s1[0], s1[1]], [s2[0], s2[1]], [s2b[0], s2b[1]], [s1b[0], s1b[1]]], 0);
        brush.noWash();

        brush.set("burr_pen", "#2E2C28", 0.32);
        brush.line(s1b[0], s1b[1], s2b[0], s2b[1]);
      }

      // Front aperture rim burr highlight
      let sF1 = project3D(p1), sF2 = project3D(p2);
      let rimLight = vDot(inNorm, light1) > 0.15;
      brush.set("burr_pen", rimLight ? "#FAF9F4" : "#34322E", rimLight ? 0.42 : 0.36);
      brush.line(sF1[0], sF1[1], sF2[0], sF2[1]);
    }
  }
}

function renderPlateEdgeBurrs(pl) {
  let n = pl.verts3D.length;
  for (let i = 0; i < n; i++) {
    let v1 = pl.verts3D[i];
    let v2 = pl.verts3D[(i + 1) % n];
    let s1 = project3D(v1);
    let s2 = project3D(v2);

    let edgeVec = vSub(v2, v1);
    let outNorm = vNorm(vCross(edgeVec, pl.nHat));
    let bevelLight = vDot(vNorm(vAdd(outNorm, pl.nHat)), light1);

    // 1. Crisp structural dark hairline at the sheared edge
    brush.set("burr_pen", "#2A2724", 0.42);
    brush.line(s1[0], s1[1], s2[0], s2[1]);

    // 2. Intermittent bright metallic wire-burr & micro-irregularities along the cut edge
    let edgeLen = Math.hypot(s2[0] - s1[0], s2[1] - s1[1]);
    let dx = (s2[0] - s1[0]) / (edgeLen || 1);
    let dy = (s2[1] - s1[1]) / (edgeLen || 1);
    let nx = -dy, ny = dx;

    let steps = Math.max(3, Math.floor(edgeLen / 14));
    for (let k = 0; k < steps; k++) {
      let t0 = k / steps;
      let t1 = Math.min(1, (k + random(0.45, 0.92)) / steps);
      let xA = lerp(s1[0], s2[0], t0) + nx * 0.7;
      let yA = lerp(s1[1], s2[1], t0) + ny * 0.7;
      let xB = lerp(s1[0], s2[0], t1) + nx * 0.7;
      let yB = lerp(s1[1], s2[1], t1) + ny * 0.7;

      if (bevelLight > 0.05 || random() < 0.45) {
        let burrCol = bevelLight > 0.35 ? "#FCFBF6" : "#DFE0DA";
        let burrW = bevelLight > 0.35 ? random(0.35, 0.58) : random(0.24, 0.38);
        brush.set("burr_pen", burrCol, burrW);
        brush.line(xA, yA, xB, yB);

        // Occasional tiny raised shear-burr nick catching a bright glint
        if (random() < 0.28) {
          let bx = lerp(xA, xB, 0.5);
          let by = lerp(yA, yB, 0.5);
          brush.set("burr_pen", "#FFFFFF", 0.48);
          brush.line(bx, by, bx + nx * random(1.4, 2.8) + dx * 1.5, by + ny * random(1.4, 2.8) + dy * 1.5);
        }
      }
    }
  }
}

// ============================================================================
// MECHANICAL HINGES, KNUCKLES, HINGE PINS, AND RIVETS
// ============================================================================

function renderMechanicalHinge(h) {
  let A = h.A;
  let B = h.B;
  let axis = vSub(B, A);
  let axisHat = vNorm(axis);
  let numK = h.knuckles;

  // Determine leaf vectors perpendicular to the hinge on plateA and plateB
  let leafWidth = 15.5;
  let leafVecA = getHingeLeafVector(A, B, h.plateA, leafWidth);
  let leafVecB = getHingeLeafVector(A, B, h.plateB, leafWidth);

  // 1. Render rectangular hinge leaves & rivets on both adjoining plates
  renderHingeLeafAndRivets(A, B, leafVecA, h.plateA.nHat, numK, 0);
  renderHingeLeafAndRivets(A, B, leafVecB, h.plateB.nHat, numK, 1);

  // 2. Render protruding steel hinge pin ends at A and B
  let pinExt = 5.5;
  let pinStart = vAdd(A, vScale(axisHat, -pinExt));
  let pinEnd = vAdd(B, vScale(axisHat, pinExt));
  drawHingePinEnd(pinStart, A);
  drawHingePinEnd(B, pinEnd);

  // 3. Render alternating cylindrical hinge knuckles along A -> B
  let rad3D = 4.6;
  let toCam = vNorm(vSub(camPos, vLerp(A, B, 0.5)));
  let sideHat = vNorm(vCross(axisHat, toCam));

  for (let i = 0; i < numK; i++) {
    let t0 = (i + 0.04) / numK;
    let t1 = (i + 0.96) / numK;
    let kA = vLerp(A, B, t0);
    let kB = vLerp(A, B, t1);

    let topA = project3D(vAdd(kA, vScale(sideHat, rad3D)));
    let topB = project3D(vAdd(kB, vScale(sideHat, rad3D)));
    let botA = project3D(vAdd(kA, vScale(sideHat, -rad3D)));
    let botB = project3D(vAdd(kB, vScale(sideHat, -rad3D)));
    let midA = project3D(vAdd(kA, vScale(sideHat, rad3D * 0.28)));
    let midB = project3D(vAdd(kB, vScale(sideHat, rad3D * 0.28)));

    // Base cylinder body wash
    let bodyCol = (i % 2 === 0) ? "#989A94" : "#868882";
    brush.noStroke();
    brush.wash(bodyCol, 245);
    drawBrushPoly([[topA[0], topA[1]], [topB[0], topB[1]], [botB[0], botB[1]], [botA[0], botA[1]]], 0);
    brush.noWash();

    // Shadow side of knuckle cylinder
    brush.set("2B", "#3A3834", 0.52);
    brush.line(botA[0], botA[1], botB[0], botB[1]);

    // Upper contour of knuckle cylinder
    brush.set("burr_pen", "#4A4844", 0.36);
    brush.line(topA[0], topA[1], topB[0], topB[1]);

    // Specular ridge along the barrel of the knuckle
    brush.set("burr_pen", "#FAF9F4", 0.52);
    brush.line(midA[0], midA[1], midB[0], midB[1]);

    // Dark mechanical seam gap at the end of each knuckle
    brush.set("burr_pen", "#181614", 0.55);
    brush.line(topA[0], topA[1], botA[0], botA[1]);
    brush.line(topB[0], topB[1], botB[0], botB[1]);
  }
}

function getHingeLeafVector(A, B, pl, width) {
  let midHinge = vLerp(A, B, 0.5);
  // Vector from hinge midpoint toward plate interior
  let plateCenter = coplanarPt(pl.A, pl.B, pl.C, 0.45, 0.45);
  let toCenter = vSub(plateCenter, midHinge);
  let axisHat = vNorm(vSub(B, A));
  let perp = vSub(toCenter, vScale(axisHat, vDot(toCenter, axisHat)));
  return vScale(vNorm(perp), width);
}

function renderHingeLeafAndRivets(A, B, leafVec, plateNormal, numK, parity) {
  let lA = vAdd(A, leafVec);
  let lB = vAdd(B, leafVec);

  let sA = project3D(A), sB = project3D(B);
  let sLA = project3D(lA), sLB = project3D(lB);

  let ndl = Math.max(0, vDot(plateNormal, light1));
  let leafCol = ndl > 0.38 ? "#C0C2BC" : "#92948E";

  // Draw leaf strap segments corresponding to alternating knuckles
  for (let i = 0; i < numK; i++) {
    if (i % 2 !== parity) continue;
    let t0 = (i + 0.05) / numK;
    let t1 = (i + 0.95) / numK;

    let p0 = project3D(vLerp(A, B, t0));
    let p1 = project3D(vLerp(A, B, t1));
    let p2 = project3D(vLerp(lA, lB, t1));
    let p3 = project3D(vLerp(lA, lB, t0));

    brush.noStroke();
    brush.wash(leafCol, 235);
    drawBrushPoly([[p0[0], p0[1]], [p1[0], p1[1]], [p2[0], p2[1]], [p3[0], p3[1]]], 0);
    brush.noWash();

    // Crisp leaf border & specular bevel
    brush.set("burr_pen", "#383632", 0.34);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(p2[0], p2[1], p3[0], p3[1]);
    brush.line(p3[0], p3[1], p0[0], p0[1]);

    brush.set("burr_pen", "#F2F1EB", 0.28);
    brush.line(p3[0] + 0.6, p3[1] - 0.6, p2[0] + 0.6, p2[1] - 0.6);

    // Crisp dome-head pop rivet in the center of the leaf tab
    let tMid = (t0 + t1) * 0.5;
    let rPos3 = vAdd(vLerp(A, B, tMid), vScale(leafVec, 0.58));
    drawCrispRivet(rPos3, plateNormal);
  }

  // Also add structural rivets along the plate margin just outside the hinge leaf
  for (let r = 0; r < 3; r++) {
    let tR = 0.18 + r * 0.32;
    let rPos3 = vAdd(vLerp(A, B, tR), vScale(leafVec, 1.38));
    drawCrispRivet(rPos3, plateNormal);
  }
}

function drawCrispRivet(pos3D, normal) {
  let s = project3D(pos3D);
  let rx = s[0], ry = s[1];
  let rad = map(s[2], 650, 1050, 2.9, 1.9);

  // 1. Dark circular shadow rim beneath rivet head
  brush.set("burr_pen", "#262420", 0.38);
  brush.circle(rx + 0.5, ry + 0.6, rad, 0.04);

  // 2. Metallic dome body
  brush.set("burr_pen", "#C6C8C2", 0.45);
  brush.circle(rx, ry, rad * 0.72, 0.02);

  // 3. Dark central blind-rivet mandrel hole
  brush.set("burr_pen", "#1A1816", 0.48);
  brush.line(rx - 0.5, ry, rx + 0.5, ry);

  // 4. Crisp pinpoint specular glint on upper-right dome rim
  brush.set("burr_pen", "#FFFFFF", 0.46);
  brush.line(rx + rad * 0.25, ry - rad * 0.35, rx + rad * 0.65, ry - rad * 0.15);
}

function drawHingePinEnd(pStart, pEnd) {
  let sA = project3D(pStart);
  let sB = project3D(pEnd);

  // Dark steel pin core
  brush.set("2B", "#2C2A26", 0.68);
  brush.line(sA[0], sA[1], sB[0], sB[1]);

  // Bright machined steel pin highlight
  brush.set("burr_pen", "#F5F4EE", 0.38);
  brush.line(sA[0], sA[1] - 0.8, sB[0], sB[1] - 0.8);
}

