// ============================================================================
// 1. TILE WALL BASE & PILLOWED GLAZE TOPOGRAPHY
// ============================================================================
function drawTileWallBase() {
  brush.noField();
  brush.noStroke();

  // Cool upper-left kitchen daylight gradation across the wall
  for (let r = 0; r < ROW_EDGES.length - 1; r++) {
    for (let c = 0; c < COL_EDGES.length - 1; c++) {
      let x0 = COL_EDGES[c] + GROUT_W / 2;
      let x1 = COL_EDGES[c + 1] - GROUT_W / 2;
      let y0 = ROW_EDGES[r] + GROUT_W / 2;
      let y1 = ROW_EDGES[r + 1] - GROUT_W / 2;
      let w = x1 - x0;
      let h = y1 - y0;

      // Subtle tile-to-tile tin glaze temperature variation
      let tileShift = ( ((c * 7 + r * 13) % 5) - 2 );
      let baseCol = lerpColor(color("#e5ebf0"), color("#d3dce4"), (c * 0.16 + r * 0.22));
      let rC = constrain(red(baseCol) + tileShift, 0, 255);
      let gC = constrain(green(baseCol) + tileShift, 0, 255);
      let bC = constrain(blue(baseCol) + tileShift * 1.2, 0, 255);

      brush.wash(color(rC, gC, bC), 235);
      brush.rect(x0, y0, w, h, "corner");
      brush.noWash();

      // Pillowed handmade ceramic glaze shading (bright upper-left, shaded lower-right)
      let steps = 11;
      for (let i = 0; i < steps; i++) {
        let t = i / (steps - 1);
        let yy = lerp(y0 + 10, y1 - 10, t);
        let lightCol = lerpColor(color("#f4f8fb"), color("#ccd6df"), t * 0.85 + c * 0.04);
        brush.set("glaze_soft", lightCol, 1.35);
        brush.line(x0 + 8, yy, x1 - 8, yy + random(-1.5, 1.5));
      }

      // Soft bevel shadow along bottom and right tile perimeter (curving into grout)
      brush.set("glaze_soft", "#b5c1cd", 0.65);
      brush.line(x0 + 4, y1 - 5, x1 - 3, y1 - 5);
      brush.line(x1 - 5, y0 + 4, x1 - 5, y1 - 3);

      brush.set("glaze_soft", "#c4cfd9", 0.9);
      brush.line(x0 + 6, y1 - 11, x1 - 6, y1 - 11);
      brush.line(x1 - 11, y0 + 6, x1 - 11, y1 - 6);

      // Crisp glassy bevel highlight along top and left tile edges catching cool window light
      brush.set("wet_sheen", "#f7fbff", 0.55);
      brush.line(x0 + 4, y0 + 3.5, x1 - 8, y0 + 3.5);
      brush.line(x0 + 3.5, y0 + 4, x0 + 3.5, y1 - 8);
    }
  }
}

// ============================================================================
