  drawPostMillTile(133, 183, 393, 443, COB_DEEP, COB_MID, COB_PALE, COB_WASH, MAN_MID, MAN_PALE);

  // --- ROW 1, COL 2 (x: 399..659, y: 183..443): Tiny Dutch Sailing Ship in Medallion ---
  drawTinyShipTile(399, 183, 659, 443, COB_DEEP, COB_MID, COB_PALE, COB_WASH, MAN_DEEP, MAN_PALE);

  // --- ROW 1, COL 3 (x: 665..925, y: 183..443): Manganese & Cobalt Smock Windmill & Bridge ---
  drawSmockMillTile(665, 183, 925, 443, MAN_DEEP, MAN_MID, MAN_PALE, MAN_WASH, COB_MID, COB_PALE);

  // --- ROW 1, COL 4 (x: 931..1191, y: 183..443): Distant Polder Mill & Mooring Posts ---
  drawDistantPolderTile(931, 183, 1191, 443, COB_DEEP, COB_MID, COB_PALE, MAN_PALE);

  // --- ROW 2, COL 1 (x: 133..393, y: 449..709): Drainage Wipmolen & Canal Cottage ---
  drawWipmolenTile(133, 449, 393, 709, MAN_DEEP, MAN_MID, MAN_PALE, COB_MID, COB_PALE);

  // --- ROW 2, COL 2 (x: 399..659, y: 449..709): Partially behind glove - Upper Windmill Sails ---
  drawPartialMillTile(399, 449, 659, 709, COB_DEEP, COB_MID, COB_PALE, MAN_PALE);

  // --- ROW 2, COL 3 (x: 665..925, y: 449..709): Partially behind cuff - Tiny Sloop on Right ---
  drawPartialShipTile(665, 449, 925, 709, MAN_DEEP, MAN_MID, COB_MID, COB_PALE);

  // --- ROW 2, COL 4 (x: 931..1191, y: 449..709): Jetty & Mooring Dolphins on Right ---
  drawJettyTile(931, 449, 1191, 709, COB_DEEP, COB_MID, COB_PALE, MAN_MID);

  // --- ROW 0 Partial Top Tiles (y: -67..177): Watery Reed Beds & Distant Sails ---
  drawTopRowFragments(COB_MID, COB_PALE, MAN_MID, MAN_PALE);
}

function drawWatercolorPool(pts, col, alphaVal, bleedVal, texVal) {
  brush.noStroke();
  brush.fill(col, alphaVal);
  brush.fillBleed(bleedVal, "out");
  brush.fillTexture(texVal, 0.68);
  brush.beginShape(0.45);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawTileCornerMotifs(x0, y0, x1, y1, mainCol, paleCol) {
  let corners = [
    [x0 + 22, y0 + 22, 1, 1],
    [x1 - 22, y0 + 22, -1, 1],
    [x0 + 22, y1 - 22, 1, -1],
    [x1 - 22, y1 - 22, -1, -1]
  ];
  for (let c of corners) {
    let cx = c[0], cy = c[1], sx = c[2], sy = c[3];
    if (cy < -10 || cy > SINK_Y || cx < -10 || cx > 1210) continue;

    // Loose pooled dot at corner center
    brush.set("wc_drag", paleCol, 0.55);
    brush.line(cx - sx * 6, cy, cx + sx * 8, cy + sy * 2);
    brush.line(cx, cy - sy * 6, cx + sx * 2, cy + sy * 8);

    // Ox-head / spider scrolls in fine cobalt/manganese brush
    brush.set("rotring", mainCol, 0.35);
    brush.spline([
      [cx - sx * 12, cy + sy * 4, 0.4],
      [cx - sx * 3, cy - sy * 3, 0.9],
      [cx + sx * 4, cy - sy * 12, 0.4]
    ], 0.6);
    brush.spline([
      [cx - sx * 8, cy + sy * 11, 0.3],
      [cx + sx * 2, cy + sy * 2, 0.8],
      [cx + sx * 11, cy - sy * 8, 0.3]
    ], 0.5);
    // Tiny antennae ticks
    brush.line(cx + sx * 3, cy + sy * 3, cx + sx * 13, cy + sy * 13);
    brush.line(cx - sx * 12, cy - sy * 6, cx - sx * 5, cy - sy * 6);
    brush.line(cx - sx * 6, cy - sy * 12, cx - sx * 6, cy - sy * 5);
  }
}

function drawPostMillTile(x0, y0, x1, y1, cobDeep, cobMid, cobPale, cobWash, manMid, manPale) {
  let cx = (x0 + x1) * 0.5 - 4;
  let cy = (y0 + y1) * 0.5 + 8;

  // 1. Pooled watercolor cloud washes
  drawWatercolorPool([
    [x0 + 42, y0 + 82], [x0 + 105, y0 + 58], [x0 + 178, y0 + 68],
    [x0 + 215, y0 + 98], [x0 + 150, y0 + 114], [x0 + 68, y0 + 106]
  ], cobWash, 58, 0.35, 0.78);

  drawWatercolorPool([
    [x0 + 95, y0 + 110], [x0 + 175, y0 + 95], [x0 + 225, y0 + 125],
    [x0 + 195, y0 + 152], [x0 + 110, y0 + 145]
  ], manPale, 45, 0.3, 0.72);

  // 2. Pooled dike & foreground bank
  drawWatercolorPool([
    [x0 + 34, cy + 52], [cx - 25, cy + 36], [cx + 35, cy + 38],
    [x1 - 38, cy + 58], [x1 - 45, cy + 76], [x0 + 42, cy + 72]
  ], cobPale, 75, 0.28, 0.8);

  drawWatercolorPool([
    [cx - 42, cy + 44], [cx + 22, cy + 40], [cx + 52, cy + 58], [cx - 30, cy + 62]
  ], manMid, 62, 0.25, 0.75);

  // 3. Windmill wooden body (pooled cobalt + manganese shadow side)
  drawWatercolorPool([
    [cx - 17, cy - 38], [cx + 2, cy - 48], [cx + 18, cy - 36],
    [cx + 16, cy + 16], [cx - 16, cy + 16]
  ], cobMid, 95, 0.18, 0.82);

  drawWatercolorPool([
    [cx + 1, cy - 46], [cx + 18, cy - 36], [cx + 16, cy + 16], [cx + 2, cy + 16]
  ], manMid, 82, 0.15, 0.75);

  // Dragging watercolor strokes for horizon, water ripples, and clouds
  brush.set("wc_drag", cobPale, 0.85);
  brush.spline([[x0 + 36, cy + 56, 0.9], [cx, cy + 53, 0.5], [x1 - 36, cy + 58, 0.2]], 0.3);
  brush.set("wc_drag", cobWash, 0.65);
  for (let wy = cy + 66; wy <= cy + 96; wy += 9) {
    let span = map(wy, cy + 66, cy + 96, 85, 42);
    brush.line(cx - span + random(-8, 8), wy, cx + span + random(-8, 8), wy + random(-1.5, 1.5));
  }

  // Trestle legs & tail-pole of the post-mill
  brush.set("wc_drag", cobDeep, 0.45);
  brush.line(cx - 12, cy + 15, cx - 22, cy + 44);
  brush.line(cx + 12, cy + 15, cx + 21, cy + 44);
  brush.line(cx, cy + 14, cx, cy + 44);
  brush.line(cx - 24, cy + 43, cx + 25, cy + 43);
  // Diagonal tail pole & ladder to the right
  brush.set("rotring", manMid, 0.48);
  brush.line(cx + 14, cy + 4, cx + 56, cy + 44);
  brush.line(cx + 10, cy + 12, cx + 44, cy + 45);

  // Architectural outlines of the mill box
  brush.set("rotring", cobDeep, 0.45);
  brush.line(cx - 17, cy - 38, cx - 16, cy + 16);
  brush.line(cx + 17, cy - 36, cx + 16, cy + 16);
  brush.line(cx - 17, cy - 38, cx + 1, cy - 49);
  brush.line(cx + 1, cy - 49, cx + 17, cy - 36);
  brush.line(cx - 16, cy + 16, cx + 16, cy + 16);
  // Horizontal clapboard lines
  for (let yy = cy - 30; yy < cy + 14; yy += 6.5) {
    brush.set("crazing_pen", cobDeep, 0.55);
    brush.line(cx - 15, yy, cx + 15, yy + 1);
  }

  // 4. Sweeping Windmill Sails (hub at cx - 6, cy - 26)
  let hx = cx - 6, hy = cy - 26;
  let sailAngles = [32, 122, 212, 302];
  let sailLen = 74;
  for (let ang of sailAngles) {
    let ex = hx + cos(ang) * sailLen;
    let ey = hy + sin(ang) * sailLen;
    // Main stock
    brush.set("wc_drag", cobDeep, 0.42);
    brush.line(hx, hy, ex, ey);
    brush.set("rotring", cobDeep, 0.52);
    brush.line(hx, hy, ex, ey);

    // Lattice grid & dragging canvas wash along one side of stock
    let nx = cos(ang + 90) * 11;
    let ny = sin(ang + 90) * 11;
    brush.set("wc_drag", (ang === 32 || ang === 212) ? cobPale : manPale, 0.48);
    brush.line(hx + cos(ang) * 16 + nx * 0.5, hy + sin(ang) * 16 + ny * 0.5, ex + nx * 0.5, ey + ny * 0.5);

    brush.set("crazing_pen", cobDeep, 0.5);
    brush.line(hx + cos(ang) * 14 + nx, hy + sin(ang) * 14 + ny, ex + nx, ey + ny);
    for (let d = 16; d <= sailLen - 2; d += 7.5) {
      let px = hx + cos(ang) * d;
      let py = hy + sin(ang) * d;
      brush.line(px, py, px + nx, py + ny);
    }
  }

  // Foreground reeds on left & birds in sky
  brush.set("wc_drag", cobDeep, 0.35);
  for (let rx = x0 + 48; rx < x0 + 96; rx += 6) {
    let rh = random(18, 34);
    brush.spline([[rx, cy + 68, 0.9], [rx + random(-4, 6), cy + 68 - rh * 0.5, 0.5], [rx + random(-2, 9), cy + 68 - rh, 0.1]], 0.4);
  }
  drawDelftBirds(x0 + 82, y0 + 75, 4, cobMid);
}

function drawTinyShipTile(x0, y0, x1, y1, cobDeep, cobMid, cobPale, cobWash, manDeep, manPale) {
  let cx = (x0 + x1) * 0.5;
  let cy = (y0 + y1) * 0.5 + 4;

  // Delicate hand-brushed double circular medallion (tondo) typical of Delft marine tiles
  brush.set("rotring", cobPale, 0.38);
  brush.circle(cx, cy, 98, 0.18);
