// ============================================================================
// 3. GLAZE CRAZING IN PEN HAIRLINES
// ============================================================================
function drawAllTileCrazing() {
  for (let r = 0; r < ROW_EDGES.length - 1; r++) {
    for (let c = 0; c < COL_EDGES.length - 1; c++) {
      let x0 = COL_EDGES[c] + GROUT_W / 2 + 2;
      let x1 = COL_EDGES[c + 1] - GROUT_W / 2 - 2;
      let y0 = max(2, ROW_EDGES[r] + GROUT_W / 2 + 2);
      let y1 = ROW_EDGES[r + 1] - GROUT_W / 2 - 2;
      if (x1 <= 0 || x0 >= 1200 || y1 <= 0) continue;
      drawTileCrazingNetwork(x0, y0, x1, y1, c * 31 + r * 97 + 11);
    }
  }
}

function drawTileCrazingNetwork(x0, y0, x1, y1, seedVal) {
  randomSeed(seedVal);
  let cols = max(3, floor((x1 - x0) / 34));
  let rows = max(3, floor((y1 - y0) / 34));
  let cellW = (x1 - x0) / cols;
  let cellH = (y1 - y0) / rows;

  // Generate perturbed cellular nodes for authentic ceramic stress crackle
  let nodes = [];
  for (let j = 0; j <= rows; j++) {
    let rowArr = [];
    for (let i = 0; i <= cols; i++) {
      let px = x0 + i * cellW + (i > 0 && i < cols ? random(-cellW * 0.36, cellW * 0.36) : 0);
      let py = y0 + j * cellH + (j > 0 && j < rows ? random(-cellH * 0.36, cellH * 0.36) : 0);
      rowArr.push([px, py]);
    }
    nodes.push(rowArr);
  }

  // Primary & secondary hairline crackle network
  for (let j = 0; j <= rows; j++) {
    for (let i = 0; i <= cols; i++) {
      let p = nodes[j][i];

      // Horizontal-ish crack segment
      if (i < cols && random() < 0.88) {
        let q = nodes[j][i + 1];
        drawCrazingSegment(p[0], p[1], q[0], q[1], true);

        // Occasional finer interior T-junction sub-crack
        if (j < rows && random() < 0.52) {
          let rNode = nodes[j + 1][i];
          let mx1 = lerp(p[0], q[0], random(0.3, 0.7));
          let my1 = lerp(p[1], q[1], random(0.3, 0.7));
          let mx2 = lerp(p[0], rNode[0], random(0.3, 0.7));
          let my2 = lerp(p[1], rNode[1], random(0.3, 0.7));
          drawCrazingSegment(mx1, my1, mx2, my2, false);
        }
      }

      // Vertical-ish crack segment
      if (j < rows && random() < 0.88) {
        let q = nodes[j + 1][i];
        drawCrazingSegment(p[0], p[1], q[0], q[1], true);
      }
    }
  }
}

function drawCrazingSegment(xA, yA, xB, yB, isPrimary) {
  let mx = (xA + xB) * 0.5 + random(-3.5, 3.5);
  let my = (yA + yB) * 0.5 + random(-3.5, 3.5);

  // Subtle staining near tile edges or old moisture
  let stainCols = ["#939ea8", "#a2adb7", "#85919c", "#adb7c0"];
  let colChoice = stainCols[floor(random(stainCols.length))];
  let w = isPrimary ? random(0.32, 0.52) : random(0.22, 0.34);

  brush.set("crazing_pen", colChoice, w);
  brush.spline([
    [xA, yA, 0.45],
    [mx, my, 0.85],
    [xB, yB, 0.45]
  ], 0.35);
}

// ============================================================================
// 4. GROUT LINES WITH EXACT SOFT SHADOWS
// ============================================================================
function drawGroutNetwork() {
  // Horizontal grout channels
  for (let r = 1; r < ROW_EDGES.length; r++) {
    let gy = ROW_EDGES[r];
    // Recessed mortar base
    brush.noStroke();
    brush.wash("#aeb9c4", 220);
    brush.rect(0, gy - 3, 1200, 6, "corner");
    brush.noWash();

    // Soft cast shadow from upper tile's lower lip (cool light from top-left)
    brush.set("glaze_soft", "#687684", 0.38);
    brush.line(0, gy - 1.5, 1200, gy - 1.5);
    brush.set("rubber_detail", "#4f5d6b", 0.55);
    brush.line(0, gy - 2.5, 1200, gy - 2.5);

    // Fine mortar texture & lower tile top-edge highlight
    brush.set("2H", "#7c8a98", 0.55);
    brush.line(0, gy + 0.5, 1200, gy + 0.5);
    brush.set("wet_sheen", "#f5f9fc", 0.42);
    brush.line(0, gy + 3.8, 1200, gy + 3.8);
  }

  // Vertical grout channels
  for (let c = 1; c < COL_EDGES.length - 1; c++) {
    let gx = COL_EDGES[c];
    brush.noStroke();
    brush.wash("#aeb9c4", 220);
    brush.rect(gx - 3, 0, 6, SINK_Y, "corner");
    brush.noWash();

    // Soft cast shadow from left tile's right lip
    brush.set("glaze_soft", "#687684", 0.38);
    brush.line(gx - 1.5, 0, gx - 1.5, SINK_Y);
    brush.set("rubber_detail", "#4f5d6b", 0.55);
    brush.line(gx - 2.5, 0, gx - 2.5, SINK_Y);

    // Fine mortar tooth & right tile left-edge highlight
    brush.set("2H", "#7c8a98", 0.55);
    brush.line(gx + 0.5, 0, gx + 0.5, SINK_Y);
    brush.set("wet_sheen", "#f5f9fc", 0.42);
    brush.line(gx + 3.8, 0, gx + 3.8, SINK_Y);
  }

  // Subtle age darkening at grout cross-intersections
  for (let r = 1; r < ROW_EDGES.length; r++) {
    for (let c = 1; c < COL_EDGES.length - 1; c++) {
      let gx = COL_EDGES[c], gy = ROW_EDGES[r];
      brush.set("rubber_detail", "#42505e", 0.65);
      brush.line(gx - 6, gy - 1, gx + 6, gy - 1);
      brush.line(gx - 1, gy - 6, gx - 1, gy + 6);
    }
  }
}

// ============================================================================
// 5. CERAMIC SINK EDGE, BULLNOSE RIM & BASIN
// ============================================================================
function drawSinkArchitecture() {
  // Base porcelain washes for rear deck (718..795), bullnose (795..855), and deep basin (855..1200)
  brush.noStroke();
  brush.wash("#d8e1e8", 250);
  brush.rect(0, SINK_Y, 1200, 82, "corner");
  brush.wash("#b5c2ce", 250);
  brush.rect(0, 800, 1200, 60, "corner");
  brush.wash("#6c7a88", 255);
  brush.rect(0, 860, 1200, 340, "corner");
  brush.noWash();

  // 1. Rear Silicone / Mortar Cove Joint at y = 712..724
  brush.set("glaze_soft", "#63717f", 0.55);
  brush.line(0, SINK_Y - 2, 1200, SINK_Y - 2);
  brush.set("rubber_detail", "#455361", 0.7);
  brush.line(0, SINK_Y - 3.5, 1200, SINK_Y - 3.5);
  brush.set("wet_sheen", "#f2f7fb", 0.5);
  brush.line(0, SINK_Y + 3, 1200, SINK_Y + 3);

  // 2. Smooth Horizontal Porcelain Deck (y = 722..796)
  for (let y = 724; y <= 796; y += 4.5) {
    let t = map(y, 724, 796, 0, 1);
    let col = lerpColor(color("#ced8e1"), color("#eaf0f5"), t);
    brush.set("glaze_soft", col, 1.3);
    brush.line(0, y, 1200, y);
  }

  // Faint glossy vertical reflections of the tile grout joints on the horizontal sink deck
  for (let c = 1; c < COL_EDGES.length - 1; c++) {
    let gx = COL_EDGES[c];
    brush.set("glaze_soft", "#9aa7b4", 0.45);
    brush.line(gx, 722, gx, 805);
  }

  // Warm yellow bounce reflection on the wet porcelain right beneath the draped glove
  for (let y = 724; y <= 845; y += 5) {
    let alphaW = map(y, 724, 845, 0.85, 0.45);
    brush.set("glaze_soft", "#cfb75a", alphaW);
    brush.line(355, y, 760, y);
  }

  // 3. Rounded Porcelain Bullnose Lip (y = 794..858)
  // Brilliant cool window highlight band across the upper curve of the bullnose
  for (let y = 795; y <= 818; y += 2.2) {
    let amt = 1 - abs(y - 806) / 12;
    let col = lerpColor(color("#e4edf3"), color("#ffffff"), constrain(amt, 0, 1));
    brush.set("wet_sheen", col, 0.95);
    brush.line(0, y, 1200, y);
  }

  // Shaded lower roll of the bullnose turning into the vertical basin wall
  for (let y = 820; y <= 862; y += 3) {
    let t = map(y, 820, 862, 0, 1);
    let col;
    if (t < 0.65) {
      col = lerpColor(color("#c4d0db"), color("#697785"), t / 0.65);
    } else {
      col = lerpColor(color("#697785"), color("#8795a3"), (t - 0.65) / 0.35);
    }
    brush.set("glaze_soft", col, 1.15);
    brush.line(0, y, 1200, y);
  }

  // 4. Deep Vertical Sink Basin Wall (y = 862..1200)
  for (let y = 864; y <= 1200; y += 6.5) {
    let t = map(y, 864, 1200, 0, 1);
    let col = lerpColor(color("#7a8896"), color("#495663"), pow(t, 0.85));
    brush.set("glaze_soft", col, 1.5);
    brush.line(0, y, 1200, y);
  }

  // Subtle vertical water streaks inside the dark porcelain basin
  for (let sx of [165, 240, 710, 865, 1020]) {
    brush.set("glaze_soft", "#8695a4", 0.35);
    brush.line(sx, 855, sx + random(-4, 4), 1190);
    brush.set("wet_sheen", "#b8c7d6", 0.22);
    brush.line(sx - 2, 855, sx - 2, 1120);
