// 6. SINGLE WATER DRIP RUNNING DOWN A TILE IN COOL KITCHEN LIGHT
// ============================================================================
function drawSingleTileDrip(baseX, startY, endY) {
  // Build organic meandering path for the rivulet down the tile (jogging at grout y = 446)
  let pts = [];
  let steps = 42;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(startY, endY - 12, t);
    let wobble = sin(t * 540) * 1.6 + cos(t * 260) * 1.1;
    // Slight step-jog where the drip crosses the horizontal grout line at y = 446
    let groutJog = (y > 443 && y < 454) ? 2.2 : (y >= 454 ? 1.5 : 0);
    pts.push([baseX + wobble + groutJog, y, t]);
  }

  // 1. Soft cast shadow of the water rivulet to the right (away from upper-left light)
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let w = map(p0[2], 0, 1, 0.3, 0.68);
    brush.set("rubber_detail", "#7d8d9c", w);
    brush.line(p0[0] + 3.4, p0[1] + 1, p1[0] + 3.4, p1[1] + 1);
  }

  // 2. Luminous internal caustic line inside the right edge of the rivulet
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let w = map(p0[2], 0, 1, 0.25, 0.55);
    brush.set("wet_sheen", "#f0f7fc", w);
    brush.line(p0[0] + 1.6, p0[1], p1[0] + 1.6, p1[1]);
  }

  // 3. Crisp dark refractive left border (facing light)
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let w = map(p0[2], 0, 1, 0.22, 0.45);
    brush.set("crazing_pen", "#526373", w * 1.2);
    brush.line(p0[0] - 2.0, p0[1], p1[0] - 2.0, p1[1]);
  }

  // 4. Razor-sharp cool-white specular highlight along the left ridge of the water trail
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    // Swells and pinches due to surface tension
    let swell = 0.5 + 0.45 * sin(i * 28);
    let w = map(p0[2], 0, 1, 0.28, 0.72) * swell;
    brush.set("wet_sheen", "#ffffff", w);
    brush.line(p0[0] - 0.8, p0[1], p1[0] - 0.8, p1[1]);
  }

  // 5. Plump Pendant Teardrop Bead at the bottom of the drip (endY)
  let dx = pts[pts.length - 1][0];
  let dy = endY;

  // Cast shadow below-right of the droplet head
  brush.set("rubber_shader", "#5d6f80", 0.55);
  brush.line(dx + 3, dy - 5, dx + 5, dy + 8);
  brush.set("rubber_detail", "#485969", 0.65);
  brush.spline([
    [dx - 2, dy + 9, 0.4],
    [dx + 5, dy + 10, 0.9],
    [dx + 8, dy + 1, 0.5]
  ], 0.5);

  // Focusing caustic glow inside the droplet's shadow
  brush.set("wet_sheen", "#f5fbff", 0.55);
  brush.spline([
    [dx + 1, dy + 7, 0.5],
    [dx + 4.5, dy + 6, 0.9],
    [dx + 5.5, dy + 1, 0.4]
  ], 0.5);

  // Dark upper-left refraction crescent inside the bead
  brush.set("rubber_detail", "#4d6070", 0.6);
  brush.spline([
    [dx - 5.5, dy + 3, 0.4],
    [dx - 6.2, dy - 4, 0.9],
    [dx - 2, dy - 11, 0.4]
  ], 0.5);

  // Cool sky-white internal belly reflection on lower-right
  brush.set("wet_sheen", "#e3f0fa", 0.65);
  brush.spline([
    [dx - 3, dy + 7, 0.5],
    [dx + 2.5, dy + 6.5, 0.95],
    [dx + 4.5, dy - 1, 0.5]
  ], 0.5);

  // Blinding pure-white primary specular highlight on upper-left crown of bead
  brush.set("wet_sheen", "#ffffff", 0.95);
  brush.spline([
    [dx - 3.8, dy - 7, 0.6],
    [dx - 4.2, dy - 1, 1.0],
    [dx - 3.0, dy + 4, 0.4]
  ], 0.5);
  brush.set("wet_sheen", "#ffffff", 0.6);
  brush.line(dx - 1.5, dy - 10, dx - 1.5, dy - 7);

  // Two tiny satellite micro-beads along the trail
  drawClearWaterBead(baseX + 0.5, startY + 95, 2.8);
  drawClearWaterBead(baseX + 2.0, startY + 275, 3.4);
}

function drawClearWaterBead(cx, cy, r) {
  brush.set("rubber_detail", "#566878", 0.35 * (r / 3));
  brush.line(cx + r * 0.6, cy - r * 0.3, cx + r * 0.8, cy + r * 0.9);
  brush.set("crazing_pen", "#4a5c6b", 0.5);
  brush.arc(cx, cy, r, 135, 305);
  brush.set("wet_sheen", "#ffffff", 0.55 * (r / 3));
  brush.line(cx - r * 0.45, cy - r * 0.45, cx - r * 0.35, cy + r * 0.25);
}

