// Helper: Evaluates a cubic-like piecewise path & normal at parameter t in [0, 1]
function evalSpine(pts, radii, t) {
  let n = pts.length - 1;
  let segF = constrain(t * n, 0, n - 0.0001);
  let idx = floor(segF);
  let u = segF - idx;

  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];

  // Catmull-Rom interpolation for smooth organic curvature
  let u2 = u * u, u3 = u2 * u;
  let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * u + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
  let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * u + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);

  // Tangent derivative
  let dx = 0.5 * ((-p0[0] + p2[0]) + (4 * p0[0] - 10 * p1[0] + 8 * p2[0] - 2 * p3[0]) * u + (-3 * p0[0] + 9 * p1[0] - 9 * p2[0] + 3 * p3[0]) * u2);
  let dy = 0.5 * ((-p0[1] + p2[1]) + (4 * p0[1] - 10 * p1[1] + 8 * p2[1] - 2 * p3[1]) * u + (-3 * p0[1] + 9 * p1[1] - 9 * p2[1] + 3 * p3[1]) * u2);
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len, ty = dy / len;
  let nx = -ty, ny = tx; // Normal pointing left/right of spine

  let r1 = radii[idx];
  let r2 = radii[min(n, idx + 1)];
  let rad = lerp(r1, r2, u);

  return { x, y, tx, ty, nx, ny, rad };
}

// Physically-based yellow rubber color shader from 3D surface normal (Nx, Ny, Nz) and crease AO
function shadeYellowRubber(Nx, Ny, Nz, ao, bounceAmt) {
  // Primary cool upper-left kitchen light
  let Lx = -0.52, Ly = -0.60, Lz = 0.61;
  let ndotl = constrain(Nx * Lx + Ny * Ly + Nz * Lz, -1, 1);
  let diff = constrain((ndotl + 0.25) / 1.25, 0, 1) * ao;

  // Color ramp from deep olive-umber shadow -> warm golden ochre -> vibrant cadmium-lemon yellow
  let cShadow = color("#4d3b06");
  let cDarkMid = color("#8f6f0e");
  let cWarmBounce = color("#d68400"); // Warm subsurface internal rubber bounce
  let cLitYellow = color("#f0c11f");
  let cBrightYellow = color("#ffe047");
  let cCoolRim = color("#c4b868");

  let baseCol;
  if (diff < 0.35) {
    baseCol = lerpColor(cShadow, cDarkMid, diff / 0.35);
  } else if (diff < 0.72) {
    baseCol = lerpColor(cDarkMid, cLitYellow, (diff - 0.35) / 0.37);
  } else {
    baseCol = lerpColor(cLitYellow, cBrightYellow, (diff - 0.72) / 0.28);
  }

  // Mix in warm golden-orange subsurface glow inside rubber creases
  if (bounceAmt > 0.01) {
    baseCol = lerpColor(baseCol, cWarmBounce, constrain(bounceAmt * 0.65, 0, 0.7));
  }

  // Subtle cool porcelain reflected rim light when normal faces down/right
  let rimDot = constrain(Nx * 0.65 + Ny * 0.55 - Nz * 0.2, 0, 1);
  if (diff < 0.42 && rimDot > 0.25) {
    baseCol = lerpColor(baseCol, cCoolRim, (rimDot - 0.25) * 0.45);
  }

  // Halfway vector for wet specular sheen: H = normalize(L + V), V = (0,0,1)
  let Hx = -0.32, Hy = -0.37, Hz = 0.87;
  let ndoth = constrain(Nx * Hx + Ny * Hy + Nz * Hz, 0, 1);
  let spec = pow(ndoth, 26) * ao;

  return { col: baseCol, spec: spec, diff: diff };
}

function drawCuffInteriorOpening() {
