}

function drawGauntletCuffLobes() {
  // Three sculptural folded lobes of the rubber gauntlet cuff leaning against the Delft tiles
  let lobes = [
    // Lower lobe resting on tile base & sink deck
    {
      pts: [[515, 728], [595, 705], [685, 662], [768, 612]],
      radii: [48, 44, 38, 28],
      ridgeBias: -0.15,
      aoBase: 0.88
    },
    // Middle collapsed trough lobe
    {
      pts: [[498, 668], [585, 622], [682, 568], [785, 518]],
      radii: [46, 44, 40, 32],
      ridgeBias: -0.05,
      aoBase: 0.94
    },
    // Upper arched ridge lobe catching strong cool kitchen window light
    {
      pts: [[478, 622], [562, 545], [658, 475], [758, 428]],
      radii: [42, 40, 36, 26],
      ridgeBias: -0.25,
      aoBase: 1.0
    }
  ];

  // Solid base wash under cuff so zero tile shows through
  for (let lb of lobes) {
    let poly = [];
    for (let t = 0; t <= 1.001; t += 0.1) {
      let sp = evalSpine(lb.pts, lb.radii, t);
      poly.push([sp.x + sp.nx * sp.rad, sp.y + sp.ny * sp.rad]);
    }
    for (let t = 1; t >= -0.001; t -= 0.1) {
      let sp = evalSpine(lb.pts, lb.radii, t);
      poly.push([sp.x - sp.nx * sp.rad, sp.y - sp.ny * sp.rad]);
    }
    drawWatercolorPool(poly, "#c49412", 240, 0.04, 0.4);
  }

  // Contoured 3D normal-shaded strokes along each cuff lobe
  for (let lIdx = 0; lIdx < lobes.length; lIdx++) {
    let lb = lobes[lIdx];
    let sSteps = 24;
    for (let si = 0; si <= sSteps; si++) {
      let s = map(si, 0, sSteps, -1, 1); // -1 is top-left edge, +1 is bottom-right edge
      let segs = 22;
      for (let ti = 0; ti < segs; ti++) {
        let t0 = ti / segs;
        let t1 = (ti + 1) / segs;
        let tMid = (t0 + t1) * 0.5;

        let sp0 = evalSpine(lb.pts, lb.radii, t0);
        let sp1 = evalSpine(lb.pts, lb.radii, t1);

        // Transverse buckle waves along the cuff length
        let wave = sin(tMid * 520 + lIdx * 70) * 0.18 + cos(tMid * 880) * 0.1;
        let sEff = constrain(s + lb.ridgeBias, -0.98, 0.98);

        // 3D normal on the curved rubber lobe
        let Nx = sp0.nx * sEff + sp0.tx * wave;
        let Ny = sp0.ny * sEff + sp0.ty * wave;
        let Nz = sqrt(max(0.05, 1 - sEff * sEff));
        let nLen = sqrt(Nx * Nx + Ny * Ny + Nz * Nz);
        Nx /= nLen; Ny /= nLen; Nz /= nLen;

        let isTrough = (abs(s) > 0.72);
        let ao = lb.aoBase * (isTrough ? 0.72 : 1.0) * (1 - 0.12 * wave);
        let bounce = isTrough ? 0.65 : max(0, -wave * 0.5);

        let sh = shadeYellowRubber(Nx, Ny, Nz, ao, bounce);
        let xA = sp0.x + sp0.nx * (s * sp0.rad);
        let yA = sp0.y + sp0.ny * (s * sp0.rad);
        let xB = sp1.x + sp1.nx * (s * sp1.rad);
        let yB = sp1.y + sp1.ny * (s * sp1.rad);

        brush.set("rubber_shader", sh.col, 0.88);
        brush.line(xA, yA, xB, yB);

        if (sh.spec > 0.22) {
          let specCol = lerpColor(color("#fff49c"), color("#ffffff"), constrain((sh.spec - 0.22) / 0.55, 0, 1));
          brush.set("wet_sheen", specCol, map(sh.spec, 0.22, 1, 0.28, 0.85));
          brush.line(xA, yA, xB, yB);
        }
      }
    }
  }

  // Rolled rubber bead along the right cuff rim opening
  let rimPts = [
    [756, 418], [728, 462], [716, 515], [735, 565], [768, 616]
  ];
  for (let s = -1; s <= 1; s += 0.25) {
    let col = (s < -0.2) ? "#fff078" : (s < 0.4 ? "#f0c224" : "#8c6b0c");
    brush.set("rubber_detail", col, 0.85);
    let curve = [];
    for (let p of rimPts) {
      curve.push([p[0] + s * 6.5, p[1] + s * 2.5, 0.8]);
    }
    brush.spline(curve, 0.5);
  }
  brush.set("wet_sheen", "#ffffff", 0.72);
  brush.spline([[753, 420, 0.5], [724, 462, 1.0], [712, 515, 0.9], [731, 565, 0.6]], 0.5);
}

function drawPalmAndWristArch() {
  // Bridges from the wrist (x: 465..565, y: 585..715) across the sink edge to the finger bases (x: 395..605, y: 740..780)
  let palmSpine = [
    [525, 618], [498, 668], [486, 718], [495, 765]
  ];
  let palmRadii = [68, 78, 88, 96];

  let poly = [];
  for (let t = 0; t <= 1.001; t += 0.1) {
    let sp = evalSpine(palmSpine, palmRadii, t);
    poly.push([sp.x + sp.nx * sp.rad, sp.y + sp.ny * sp.rad]);
  }
  for (let t = 1; t >= -0.001; t -= 0.1) {
    let sp = evalSpine(palmSpine, palmRadii, t);
    poly.push([sp.x - sp.nx * sp.rad, sp.y - sp.ny * sp.rad]);
  }
  drawWatercolorPool(poly, "#cfa015", 245, 0.03, 0.4);

  // Render across the palm width with diagonal compression folds where the glove bends over the sink edge
  let sSteps = 36;
  for (let si = 0; si <= sSteps; si++) {
    let s = map(si, 0, sSteps, -1, 1);
    let tSteps = 20;
    for (let ti = 0; ti < tSteps; ti++) {
      let t0 = ti / tSteps;
      let t1 = (ti + 1) / tSteps;
      let tMid = (t0 + t1) * 0.5;

      let sp0 = evalSpine(palmSpine, palmRadii, t0);
      let sp1 = evalSpine(palmSpine, palmRadii, t1);

      // Strong compression wrinkles across the wrist & sink bullnose bend
      let foldPhase = tMid * 720 + s * 220;
      let foldWave = sin(foldPhase) * 0.26 * (1 - abs(s) * 0.4);
      // Metacarpal knuckle swells near t = 0.85..1.0
      let knuckleSwell = (tMid > 0.7) ? cos(s * 540) * 0.16 * ((tMid - 0.7) / 0.3) : 0;

      let Nx = sp0.nx * (s * 0.85 + knuckleSwell) + sp0.tx * foldWave;
      let Ny = sp0.ny * (s * 0.85) + sp0.ty * foldWave - 0.18 * (1 - tMid);
      let Nz = sqrt(max(0.08, 1 - s * s * 0.75));
      let nLen = sqrt(Nx * Nx + Ny * Ny + Nz * Nz);
      Nx /= nLen; Ny /= nLen; Nz /= nLen;

      let ao = 1.0 - max(0, -foldWave * 0.75);
      let bounce = max(0, -foldWave * 1.4);
      let sh = shadeYellowRubber(Nx, Ny, Nz, ao, bounce);

      let xA = sp0.x + sp0.nx * (s * sp0.rad);
      let yA = sp0.y + sp0.ny * (s * sp0.rad);
      let xB = sp1.x + sp1.nx * (s * sp1.rad);
      let yB = sp1.y + sp1.ny * (s * sp1.rad);

      brush.set("rubber_shader", sh.col, 0.9);
      brush.line(xA, yA, xB, yB);

      if (sh.spec > 0.20) {
        let specCol = lerpColor(color("#fff28a"), color("#ffffff"), constrain((sh.spec - 0.2) / 0.55, 0, 1));
        brush.set("wet_sheen", specCol, map(sh.spec, 0.2, 1, 0.3, 0.92));
        brush.line(xA, yA, xB, yB);
      }
    }
  }
}

function drawDrapedFinger(cfg) {
  let pts = cfg.pts;
  let radii = cfg.radii;

  // 1. Opaque base wash for the finger silhouette
  let poly = [];
  for (let t = 0; t <= 1.001; t += 0.08) {
    let sp = evalSpine(pts, radii, t);
    let tipScale = (t > 0.88) ? sqrt(max(0, 1 - pow((t - 0.88) / 0.12, 2))) : 1;
    poly.push([sp.x + sp.nx * sp.rad * tipScale, sp.y + sp.ny * sp.rad * tipScale]);
  }
  for (let t = 1; t >= -0.001; t -= 0.08) {
    let sp = evalSpine(pts, radii, t);
    let tipScale = (t > 0.88) ? sqrt(max(0, 1 - pow((t - 0.88) / 0.12, 2))) : 1;
    poly.push([sp.x - sp.nx * sp.rad * tipScale, sp.y - sp.ny * sp.rad * tipScale]);
  }
  drawWatercolorPool(poly, "#c99812", 248, 0.02, 0.35);

  // 2. Longitudinal 3D normal-shaded strips with empty-glove lumen dimple & knuckle ring wrinkles
  let sSteps = 18;
  let tSteps = 34;

  for (let si = 0; si <= sSteps; si++) {
    let s = map(si, 0, sSteps, -1, 1); // -1 = left edge (lit), +1 = right edge (shaded)

    for (let ti = 0; ti < tSteps; ti++) {
      let t0 = ti / tSteps;
      let t1 = (ti + 1) / tSteps;
      let tMid = (t0 + t1) * 0.5;

      let sp0 = evalSpine(pts, radii, t0);
      let sp1 = evalSpine(pts, radii, t1);

      let tipScale0 = (t0 > 0.86) ? sqrt(max(0.04, 1 - pow((t0 - 0.86) / 0.14, 2))) : 1;
      let tipScale1 = (t1 > 0.86) ? sqrt(max(0.04, 1 - pow((t1 - 0.86) / 0.14, 2))) : 1;

      // Empty rubber finger cross-section: raised outer ridges at |s| ≈ 0.65, slight concave dimple at s ≈ 0
      let dimpleEnv = sin(constrain(map(tMid, 0.12, 0.88, 0, 180), 0, 180));
      let dDimple_ds = cfg.dimpleDepth * dimpleEnv * (4 * s * (1 - s * s));

      // Transverse knuckle joint ring wrinkles at each bend in cfg.knuckleT
      let wrinkleSlopeT = 0;
      let wrinklePinch = 0;
      for (let kt of cfg.knuckleT) {
        let dt = (tMid - kt) / 0.065;
        if (abs(dt) < 2.2) {
          // Paired double-ridge knuckle wrinkle
          let env = exp(-dt * dt * 1.2);
          wrinkleSlopeT += env * cos(dt * 240) * 0.42;
          wrinklePinch += env * sin(dt * 240) * 0.14;
        }
      }

      // Compute 3D normal of the wrinkled rubber finger
      let sNorm = constrain(s - dDimple_ds * 0.55 + cfg.twist, -0.98, 0.98);
      let Nx = sp0.nx * sNorm + sp0.tx * wrinkleSlopeT;
      let Ny = sp0.ny * sNorm + sp0.ty * wrinkleSlopeT + (tMid > 0.86 ? (tMid - 0.86) * 3.5 : 0);
      let Nz = sqrt(max(0.06, 1 - sNorm * sNorm));
      let nLen = sqrt(Nx * Nx + Ny * Ny + Nz * Nz);
      Nx /= nLen; Ny /= nLen; Nz /= nLen;

      let ao = 1.0 - max(0, -wrinklePinch * 1.8) - (abs(s) < 0.35 ? dimpleEnv * 0.12 : 0);
      let bounce = max(0, -wrinklePinch * 2.5) + (abs(s) > 0.78 ? 0.35 : 0);

      let sh = shadeYellowRubber(Nx, Ny, Nz, ao, bounce);

      let r0 = sp0.rad * tipScale0 * (1 + wrinklePinch * 0.45);
      let r1 = sp1.rad * tipScale1 * (1 + wrinklePinch * 0.45);

      let xA = sp0.x + sp0.nx * (s * r0);
      let yA = sp0.y + sp0.ny * (s * r0);
      let xB = sp1.x + sp1.nx * (s * r1);
      let yB = sp1.y + sp1.ny * (s * r1);

      brush.set("rubber_shader", sh.col, 0.62);
      brush.line(xA, yA, xB, yB);

      // Wet liquid sheen along the lit left ridge, central dimple rim, and knuckle crests
      if (sh.spec > 0.18) {
        let specCol = lerpColor(color("#fff394"), color("#ffffff"), constrain((sh.spec - 0.18) / 0.55, 0, 1));
        brush.set("wet_sheen", specCol, map(sh.spec, 0.18, 1, 0.25, 0.88));
        brush.line(xA, yA, xB, yB);
      }
    }
  }

  // 3. Crisp transverse knuckle ring creases & wet ridge highlights wrapped across each finger joint
  for (let kt of cfg.knuckleT) {
    let sp = evalSpine(pts, radii, kt);
    let r = sp.rad * 0.92;

    // Dark warm-amber crease trough
    brush.set("rubber_detail", "#5e4606", 0.58);
    brush.spline([
      [sp.x - sp.nx * r * 0.85, sp.y - sp.ny * r * 0.85 + 2, 0.3],
      [sp.x - sp.tx * 3.5, sp.y - sp.ty * 3.5, 0.95],
      [sp.x + sp.nx * r * 0.85, sp.y + sp.ny * r * 0.85 + 2, 0.3]
    ], 0.5);

    // Golden-orange subsurface bounce line right beside the crease
    brush.set("rubber_detail", "#d98200", 0.48);
    brush.spline([
      [sp.x - sp.nx * r * 0.8, sp.y - sp.ny * r * 0.8 + 4, 0.3],
      [sp.x - sp.tx * 1.2, sp.y - sp.ty * 1.2, 0.85],
      [sp.x + sp.nx * r * 0.75, sp.y + sp.ny * r * 0.75 + 4, 0.3]
    ], 0.5);

    // Bright wet specular ridge on the upper lip of the knuckle fold
    brush.set("wet_sheen", "#ffffff", 0.68);
    brush.spline([
      [sp.x - sp.nx * r * 0.75, sp.y - sp.ny * r * 0.75 - 1, 0.4],
      [sp.x - sp.nx * r * 0.15 - sp.tx * 5.5, sp.y - sp.ny * r * 0.15 - sp.ty * 5.5, 1.0],
      [sp.x + sp.nx * r * 0.35, sp.y + sp.ny * r * 0.35 - 2, 0.2]
    ], 0.5);
  }

  // 4. Subtle embossed diamond grip texture on the lower half of each finger (t = 0.45..0.92)
  for (let t = 0.46; t <= 0.88; t += 0.042) {
    let spA = evalSpine(pts, radii, t);
    let spB = evalSpine(pts, radii, t + 0.038);
    let rA = spA.rad * 0.72, rB = spB.rad * 0.72;

    brush.set("crazing_pen", "#9e770c", 0.32);
    brush.line(spA.x - spA.nx * rA, spA.y - spA.ny * rA, spB.x + spB.nx * rB, spB.y + spB.ny * rB);
    brush.line(spA.x + spA.nx * rA, spA.y + spA.ny * rA, spB.x - spB.nx * rB, spB.y - spB.ny * rB);

    // Tiny wet diamond specular glints on the lit side of the grip pattern
    brush.set("wet_sheen", "#fff8b8", 0.26);
    brush.line(spA.x - spA.nx * rA * 0.65, spA.y - spA.ny * rA * 0.65, spB.x - spB.nx * rB * 0.25, spB.y - spB.ny * rB * 0.25);
  }
}

