function drawRubberWaterDroplet(cx, cy, rx, ry, isPendant) {
  // 1. Cast shadow below-right (in dark olive-brown on rubber, or dark slate in basin for pendant drops)
  let shadCol = isPendant ? "#28333e" : "#4a3704";
  brush.set("rubber_detail", shadCol, 0.55 * (rx / 4.2));
  brush.spline([
    [cx - rx * 0.3, cy + ry * 0.75, 0.4],
    [cx + rx * 0.75, cy + ry * 0.95, 0.95],
    [cx + rx * 1.05, cy + ry * 0.1, 0.4]
  ], 0.5);

  // 2. Warm golden-amber caustic focused inside the droplet's shadow
  let causticCol = isPendant ? "#ffe266" : "#ffae00";
  brush.set("wet_sheen", causticCol, 0.48 * (rx / 4.2));
  brush.spline([
    [cx - rx * 0.1, cy + ry * 0.65, 0.5],
    [cx + rx * 0.55, cy + ry * 0.65, 0.9],
    [cx + rx * 0.75, cy + ry * 0.05, 0.4]
  ], 0.5);

  // 3. Dark upper-left refraction crescent
  brush.set("rubber_detail", "#5c4405", 0.52 * (rx / 4.2));
  brush.spline([
    [cx - rx * 0.85, cy + ry * 0.25, 0.4],
    [cx - rx * 0.92, cy - ry * 0.45, 0.95],
    [cx - rx * 0.15, cy - ry * 0.92, 0.4]
  ], 0.5);

  // 4. Luminous lemon-white lower-right internal reflection
  brush.set("wet_sheen", "#fff59e", 0.58 * (rx / 4.2));
  brush.spline([
    [cx - rx * 0.35, cy + ry * 0.55, 0.4],
    [cx + rx * 0.45, cy + ry * 0.48, 0.9],
    [cx + rx * 0.65, cy - ry * 0.15, 0.4]
  ], 0.5);

  // 5. Crisp pure-white primary specular highlight on the upper-left crown
  brush.set("wet_sheen", "#ffffff", 0.88 * (rx / 4.2));
  brush.line(cx - rx * 0.48, cy - ry * 0.52, cx - rx * 0.38, cy - ry * 0.08);
}
